#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define PI_SPI_OK 0

static int pi_spi_handle = -1;

void shutdown_handler(int signum) {
    if (pi_spi_handle != -1) {
        spiClose(pi_spi_handle);
    }
    piStop();
    exit(0);
}

int main() {
    if (piGpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio.\n");
        return EXIT_FAILURE;
    }

    pi_spi_handle = spiOpen("/dev/spidev0.0", 1000000, 0);
    if (pi_spi_handle < 0) {
        fprintf(stderr, "Error opening SPI device: %d\n", pi_spi_handle);
        return EXIT_FAILURE;
    }

    signal(SIGINT, shutdown_handler);
    signal(SIGTERM, shutdown_handler);

    while (1) {
        unsigned char tx_buf[2] = { (1 << 7) | (ADC_CHANNEL << 4), 0 };
        unsigned char rx_buf[2] = { 0, 0 };

        if (spiXfer(pi_spi_handle, tx_buf, rx_buf, 16) != PI_SPI_OK) {
            fprintf(stderr, "Error performing SPI transfer: %d\n", spiError());
            shutdown_handler(0);
        }

        int adc_value = (rx_buf[0] & 0x03) << 8 | rx_buf[1];

        time_t now = time(NULL);
        struct tm *local_time = localtime(&now);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", local_time);

        printf("%s: ADC value: %d\n", time_str, adc_value);

        sleep(1);
    }

    shutdown_handler(0);
    return EXIT_SUCCESS;
}

