#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define ADS1115_ADDRESS 0x48
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONVERSION_REG 0x00

#define ADS1115_PGA_4096 0x00
#define ADS1115_MUX_AIN0 0x04
#define ADS1115_DR_128SPS 0x08

#define ADS1115_CONFIG_DEFAULT (ADS1115_PGA_4096 | ADS1115_MUX_AIN0 | ADS1115_DR_128SPS)

#define MLX91219_SENSITIVITY 0.040f
#define MLX91219_OFFSET 2.5f

static int i2c_handle = -1;

void exit_handler(int signum) {
    if (i2c_handle != -1) {
        piI2C_close(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = piI2C_open(1, ADS1115_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        exit_handler(0);
        return EXIT_FAILURE;
    }

    uint16_t config_reg = ADS1115_CONFIG_DEFAULT;
    if (piI2C_writeI2CBlockData(i2c_handle, ADS1115_CONFIG_REG, 2, (uint8_t*)&config_reg) < 0) {
        fprintf(stderr, "Failed to write to ADS1115 configuration register.\n");
        exit_handler(0);
        return EXIT_FAILURE;
    }

    signal(SIGINT, exit_handler);

    while (1) {
        uint16_t conversion_reg;
        if (piI2C_readI2CBlockData(i2c_handle, ADS1115_CONVERSION_REG, 2, (uint8_t*)&conversion_reg) < 0) {
            fprintf(stderr, "Failed to read from ADS1115 conversion register.\n");
            exit_handler(0);
            return EXIT_FAILURE;
        }

        float voltage = ((float)conversion_reg / 32767.0f) * 4.096f;
        float current = (voltage - MLX91219_OFFSET) / MLX91219_SENSITIVITY;

        printf("Current: %.3f A\n", current);

        sleep(500);
    }

    exit_handler(0);
    return EXIT_SUCCESS;
}

