#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_FLAME_SENSOR 4
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define FILE_NAME "flame_data.csv"

FILE *file;
int spi_handle;

void log_data(void) {
    int flame_detected = gpioRead(GPIO_FLAME_SENSOR);
    unsigned char tx_buffer[3] = {0x01, 0x80, 0x00};
    unsigned char rx_buffer[3];

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 3) {
        printf("SPI transfer failed\n");
        return;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];
    double temperature = 10.0 + (adc_value / 1023.0) * 30.0;

    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(file, "%s,%d,%.2f\n", timestamp, flame_detected, temperature);
    fflush(file);
}

void handle_sigint(int signum) {
    spiClose(spi_handle);
    fclose(file);
    exit(0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(GPIO_FLAME_SENSOR, PI_INPUT);
    spi_handle = spiOpen("/dev/spidev0.0", SPI_SPEED, 0);
    if (spi_handle < 0) {
        printf("Failed to open SPI device\n");
        return 1;
    }

    file = fopen(FILE_NAME, "w");
    if (file == NULL) {
        printf("Failed to open file\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        log_data();
        sleep(1);
    }

    return 0;
}

