#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include "pigpio.h"
#include "piI2C.h"

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 27
#define ADC_I2C_BUS 1
#define ADC_I2C_ADDR 0x48
#define ADC_CHANNEL 0
#define ADC_SPS 128
#define ADC_GAIN 4096
#define ADC_TEMP_OFFSET 20
#define ADC_TEMP_SLOPE 60.0 / (80 - 20)
#define DEBOUNCE_TIME 50
#define BUZZER_DURATION 2000

FILE *log_file;
volatile int running = 1;

void handle_sigint(int signo) {
    running = 0;
    gpioWrite(BUZZER_PIN, 0);
    gpioCallback(FLAME_SENSOR_PIN, PI_EITHER_EDGE, NULL, NULL);
    piI2CClose(ADC_I2C_BUS);
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

void handle_flame(int gpio, int level, uint32_t tick) {
    static unsigned long last_event = 0;
    if (level == PI_LOW && ((unsigned long)tick - last_event) > DEBOUNCE_TIME * 1000) {
        last_event = tick;
        fprintf(log_file, "%ld: Flame detected!\n", tick / 1000);
        fflush(log_file);
    }
}

int main() {
    int rc;
    unsigned long start_buzzer;
    double temp;
    int adc_handle;
    struct sigaction sa;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_sigint;
    sigaction(SIGINT, &sa, NULL);

    if ((rc = gpioInitialise()) < 0) {
        fprintf(stderr, "gpioInitialise() failed: %d\n", rc);
        return 1;
    }

    gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_UP);
    gpioSetAlert(FLAME_SENSOR_PIN, 1);
    if ((rc = gpioCallback(FLAME_SENSOR_PIN, PI_EITHER_EDGE, handle_flame, NULL)) < 0) {
        fprintf(stderr, "gpioCallback() failed: %d\n", rc);
        return 1;
    }

    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    if ((adc_handle = piI2COpen("/dev/i2c-%d", ADC_I2C_BUS)) < 0 ||
        piI2CWriteByteData(adc_handle, 0x80 | (0x10 | ADC_CHANNEL), ADC_I2C_ADDR) < 0 ||
        piI2CWriteByteData(adc_handle, 0x40 | (ADC_SPS << 6), ADC_I2C_ADDR) < 0 ||
        piI2CWriteByteData(adc_handle, ADC_GAIN, ADC_I2C_ADDR) < 0) {
        fprintf(stderr, "ADC configuration failed\n");
        return 1;
    }

    if ((log_file = fopen("fire_log.txt", "w")) == NULL) {
        fprintf(stderr, "fopen() failed\n");
        return 1;
    }

    while (running) {
        if ((rc = piI2CReadWordData(adc_handle, ADC_I2C_ADDR)) < 0) {
            fprintf(stderr, "piI2CReadWordData() failed: %d\n", rc);
            continue;
        }

        temp = ((double)rc / 65535 * 3.3 - 0.1) * ADC_TEMP_SLOPE + ADC_TEMP_OFFSET;
        if (temp > 60) {
            fprintf(log_file, "%ld: Temperature %.1fC\n", millis() / 1000, temp);
            fflush(log_file);
            if (gpioRead(FLAME_SENSOR_PIN) == PI_LOW) {
                fprintf(log_file, "%ld: Fire detected!\n", millis() / 1000);
                fflush(log_file);
                start_buzzer = millis();
                gpioWrite(BUZZER_PIN, 1);
                while (running && (millis() - start_buzzer) < BUZZER_DURATION)
                    sleep(100000);
                gpioWrite(BUZZER_PIN, 0);
            }
        }

        sleep(100000);
    }

    return 0;
}

