#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/spi/spidev.h>
#include <sys/ioctl.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip4"
#define GPIO_FAN 18
#define GPIO_CURRENT_SENSOR 8
#define SPI_SPEED 1000000
#define SENSOR_SENSITIVITY 100.0
#define CURRENT_THRESHOLD 5.0

static struct gpiod_chip *chip;
static struct gpiod_line *fan_line;
static struct gpiod_line *sensor_line;
static int spi_fd;

static void cleanup_and_exit(int sig)
{
    gpiod_line_set_value(fan_line, 0);
    gpiod_line_release(fan_line);
    gpiod_line_release(sensor_line);
    gpiod_chip_close(chip);
    close(spi_fd);
    exit(sig);
}

int main(int argc, char **argv)
{
    const struct spi_ioc_transfer xfer = {
        .tx_buf = (unsigned long) "\x01\x80\x00",
        .rx_buf = (unsigned long) "\x00\x00\x00",
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };
    uint16_t adc_value;
    double current;
    char *end;
    int ret;

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open spi device");
        return 1;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    sensor_line = gpiod_chip_get_line(chip, GPIO_CURRENT_SENSOR);
    if (!sensor_line) {
        fprintf(stderr, "Failed to get current sensor line\n");
        return 1;
    }

    fan_line = gpiod_chip_get_line(chip, GPIO_FAN);
    if (!fan_line) {
        fprintf(stderr, "Failed to get fan line\n");
        return 1;
    }

    while (1) {
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer);
        if (ret < 0) {
            perror("spi message");
            return 1;
        }

        adc_value = (((uint8_t *) xfer.rx_buf)[1] & 0x03) << 8 | ((uint8_t *) xfer.rx_buf)[2];

        if (adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "Sensor absent\n");
            return 1;
        }

        current = (double) adc_value / 1023.0 * 3.3 / SENSOR_SENSITIVITY;

        if (current > CURRENT_THRESHOLD) {
            gpiod_line_set_value(fan_line, 1);
        } else {
            gpiod_line_set_value(fan_line, 0);
        }

        printf("%s Current: %.2f A\n", asctime(localtime(&time(NULL))), current);

        sleep(1);
    }

    return 0;
}

