#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 4
#define MCP3008_CH0_GPIO 0
#define SPI_CHANNEL 0
#define SPI_CLOCK 1000000
#define ADC_MAX_VALUE 1023
#define TEMP_MIN 10.0
#define TEMP_MAX 40.0
#define CSV_FILE "flame_data.csv"

volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

int main() {
    int pi = pigpio_start(NULL, NULL);
    if (pi < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %d\n", pi);
        return EXIT_FAILURE;
    }

    int spi_handle = spi_open(SPI_CHANNEL, SPI_CLOCK, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel: %d\n", spi_handle);
        pigpio_stop(pi);
        return EXIT_FAILURE;
    }

    FILE* csv = fopen(CSV_FILE, "w");
    if (csv == NULL) {
        fprintf(stderr, "Failed to open CSV file for writing\n");
        spi_close(spi_handle);
        pigpio_stop(pi);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (!stop) {
        int flame_presence = gpio_read(FLAME_SENSOR_GPIO);
        if (flame_presence < 0) {
            fprintf(stderr, "Failed to read flame sensor\n");
            continue;
        }

        unsigned char spi_tx_buf[3] = {1 << 7, 0, 0};
        unsigned char spi_rx_buf[3];
        int spi_result = spi_xfer(spi_handle, spi_tx_buf, spi_rx_buf, sizeof(spi_tx_buf) * 8);
        if (spi_result < 0) {
            fprintf(stderr, "SPI transfer failed: %d\n", spi_result);
            continue;
        }

        int adc_value = ((spi_rx_buf[1] & 0x03) << 8) | spi_rx_buf[2];
        double temp = TEMP_MIN + (TEMP_MAX - TEMP_MIN) * adc_value / ADC_MAX_VALUE;

        time_t now = time(NULL);
        struct tm* now_local = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_local);

        fprintf(csv, "%s,%d,%.2f\n", timestamp, flame_presence, temp);
        fflush(csv);

        sleep(1);
    }

    fclose(csv);
    spi_close(spi_handle);
    pigpio_stop(pi);

    return EXIT_SUCCESS;
}

