    if (!co_log_file) {
        fprintf(stderr, "Failed to open co_log.txt.\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    alert_log_file = fopen("alert_log.txt", "w");
    if (!alert_log_file) {
        fprintf(stderr, "Failed to open alert_log.txt.\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    while (1) {
        int ox_val = piI2C_readWord(I2C_BUS, SENSOR_ADDR, OX_REG);
        int red_val = piI2C_readWord(I2C_BUS, SENSOR_ADDR, RED_REG);

        if (ox_val < 0 || red_val < 0) {
