        time_t t = time(NULL);
        struct tm *curr_time = localtime(&t);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", curr_time);

        fprintf(co_log_file, "%s: %d PPM\n", time_str, co_level);
        fflush(co_log_file);

        if (co_level > ALERT_THRESHOLD) {
            fprintf(alert_log_file, "%s: CO level alert! %d PPM\n", time_str, co_level);
            fflush(alert_log_file);
