#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MIC1_ADDR 0x48
#define MIC2_ADDR 0x49
#define MIC_REG 0x00
#define MIC_SENSITIVITY -38.0
#define REF_PRESSURE 20e-6
#define SAMPLE_INTERVAL 100
#define LOG_FILE "audio_log.txt"

FILE *log_file;
volatile sig_atomic_t stop = 0;

void handle_signal(int signum) {
    stop = 1;
}

double convert_to_db(int16_t raw_data) {
    double pressure = (double)raw_data * REF_PRESSURE;
    return MIC_SENSITIVITY + 20.0 * log10(pressure);
}

void log_data(double db_value) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d %.1f dB\n",
            timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
            timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec, db_value);
}

int main() {
    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    int handle1 = gpioI2CSetBus(I2C_BUS);
    int handle2 = gpioI2CSetBus(I2C_BUS);
    if (handle1 < 0 || handle2 < 0) {
        fprintf(stderr, "Failed to set I2C bus\n");
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop) {
        int16_t data1 = gpioI2CReadWord(handle1, MIC1_ADDR, MIC_REG);
        int16_t data2 = gpioI2CReadWord(handle2, MIC2_ADDR, MIC_REG);

        if (data1 < 0 || data2 < 0) {
            log_data(-999.0);
            fprintf(stderr, "Failed to read from microphone\n");
        } else {
            double db1 = convert_to_db(data1);
            double db2 = convert_to_db(data2);
            log_data((db1 + db2) / 2.0);
        }

        delay(SAMPLE_INTERVAL);
    }

    gpioI2CClose(handle1);
    gpioI2CClose(handle2);
    gpioTerminate();
    fclose(log_file);

    return EXIT_SUCCESS;
}

