#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define ADDR 0x48
#define A0 0
#define MLX_CHANNEL 0x00
#define MLX_CONFIG 0x01
#define MLX_DATA 0x02
#define MLX_AVG 0x03
#define MLX_ID 0x04

#define MLX_CONTINUOUS 0x00
#define MLX_SINGLE 0x01
#define MLX_ID_VALUE 0x11

#define LED_PIN 17
#define SAMPLE_RATE 10
#define BUF_SIZE 100
#define THRESHOLD 50.0

volatile int stop = 0;

void shutdown(int signum) {
    stop = 1;
}

int main() {
    int pi = pigpio_start(NULL, NULL);
    if (pi < 0) {
        printf("pigpio_start failed\n");
        return -1;
    }

    if (gpioCfgIntDefault(pi) < 0) {
        printf("gpioCfgIntDefault failed\n");
        return -1;
    }

    if (gpioSetMode(pi, LED_PIN, PI_OUTPUT) < 0) {
        printf("gpioSetMode failed\n");
        return -1;
    }

    if (gpioI2CSetBus(pi, 1, ADDR) < 0) {
        printf("gpioI2CSetBus failed\n");
        return -1;
    }

    if (gpioI2CWriteByte(pi, MLX_CONFIG, MLX_CONTINUOUS) < 0) {
        printf("gpioI2CWriteByte failed\n");
        return -1;
    }

    if (gpioI2CWriteByte(pi, MLX_CHANNEL, A0) < 0) {
        printf("gpioI2CWriteByte failed\n");
        return -1;
    }

    double buf[BUF_SIZE];
    int buf_idx = 0;
    double sum = 0.0;

    signal(SIGINT, shutdown);

    while (!stop) {
        int data = gpioI2CReadWord(pi, MLX_DATA);
        if (data < 0) {
            printf("gpioI2CReadWord failed\n");
            return -1;
        }

        double current = (double)data * 100.0 / 32767.0;
        buf[buf_idx] = current;
        buf_idx = (buf_idx + 1) % BUF_SIZE;
        sum += current;

        if (buf_idx == 0) {
            double avg = sum / BUF_SIZE;
            sum = 0.0;

            if (avg > THRESHOLD) {
                gpioWrite(pi, LED_PIN, 1);
            } else {
                gpioWrite(pi, LED_PIN, 0);
            }
        }

        sleep(1.0 / SAMPLE_RATE);
    }

    gpioWrite(pi, LED_PIN, 0);
    pigpio_stop(pi);

    return 0;
}

