#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_ADDR 0x29
#define I2C_BUS 1
#define ATIME 0x01
#define CONTROL 0x0F
#define ENABLE 0x00
#define ID_REG 0x12
#define ID_VAL 0x44

static int i2c_handle = -1;
static FILE *csv_file = NULL;

static void sig_handler(int signo) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    int i2c_handle;
    int ret;
    int id_val;
    int clear, red, green, blue;
    int read_failures = 0;
    struct tm *ts;
    time_t timer;
    char buffer[20];

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "gpioInitialise failed: %d\n", ret);
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        return 1;
    }

    ret = i2cReadByteData(i2c_handle, ID_REG, &id_val);
    if (ret < 0) {
        fprintf(stderr, "i2cReadByteData failed: %d\n", ret);
        return 1;
    }
    if ((id_val & 0x0F) != ID_VAL) {
        fprintf(stderr, "Invalid sensor ID: 0x%02X\n", id_val);
        return 1;
    }

    ret = i2cWriteByteData(i2c_handle, ATIME, 0xFF);
    if (ret < 0) {
        fprintf(stderr, "i2cWriteByteData failed: %d\n", ret);
        return 1;
    }

    ret = i2cWriteByteData(i2c_handle, CONTROL, 0x01);
    if (ret < 0) {
        fprintf(stderr, "i2cWriteByteData failed: %d\n", ret);
        return 1;
    }

    ret = i2cWriteByteData(i2c_handle, ENABLE, 0x01 | 0x02);
    if (ret < 0) {
        fprintf(stderr, "i2cWriteByteData failed: %d\n", ret);
        return 1;
    }

    csv_file = fopen("color_log.csv", "w");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open color_log.csv for writing\n");
        return 1;
    }
    fprintf(csv_file, "date,clear,red,green,blue\n");

    while (1) {
        ret = i2cReadWordData(i2c_handle, 0x14, &clear);
        if (ret < 0) {
            fprintf(stderr, "i2cReadWordData failed: %d\n", ret);
            read_failures++;
            if (read_failures >= 3) {
                return 1;
            }
            sleep(1);
            continue;
        }
        read_failures = 0;

        ret = i2cReadWordData(i2c_handle, 0x16, &red);
        if (ret < 0) {
            fprintf(stderr, "i2cReadWordData failed: %d\n", ret);
            read_failures++;
            if (read_failures >= 3) {
                return 1;
            }
            sleep(1);
            continue;
        }

        ret = i2cReadWordData(i2c_handle, 0x18, &green);
        if (ret < 0) {
            fprintf(stderr, "i2cReadWordData failed: %d\n", ret);
            read_failures++;
            if (read_failures >= 3) {
                return 1;
            }
            sleep(1);
            continue;
        }

        ret = i2cReadWordData(i2c_handle, 0x1A, &blue);
        if (ret < 0) {
            fprintf(stderr, "i2cReadWordData failed: %d\n", ret);
            read_failures++;
            if (read_failures >= 3) {
                return 1;
            }
            sleep(1);
            continue;
        }

        timer = time(NULL);
        ts = localtime(&timer);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", ts);
        fprintf(csv_file, "%s,%d,%d,%d,%d\n", buffer, clear, red, green, blue);
        fflush(csv_file);

        sleep(1);
    }

    return 0;
}

