    req.default_val = 1;
    ret = gpiod_line_request(cs_line, &req, "CS line");
    if (ret) {
        perror("gpiod_line_request");
        return 1;
    }

    spi_fd = open(SPI_BUS, O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    fputs(HEADER, log_file);

    while (1) {
        for (int ch = 0; ch < 2; ch++) {
            gpiod_line_set_value(cs_line, 0);

            spi_buf[0] = 0x01;
            spi_buf[1] = (ch << 4) | 0x80;
            spi_buf[2] = 0;
            spi_buf[3] = 0;

            ret = write(spi_fd, spi_buf, 4);
            if (ret < 0) {
                perror("write");
                exit_handler(0);
            }

            gpiod_line_set_value(cs_line, 1);

            ret = read(spi_fd, spi_buf, 3);
            if (ret < 0) {
                perror("read");
                exit_handler(0);
            }

            clock_gettime(CLOCK_REALTIME, &ts);
            sprintf(log_buf, "%ld.%09ld,%d,", ts.tv_sec, ts.tv_nsec, ((spi_buf[1] & 0x03) << 8) | spi_buf[2]);
            fputs(log_buf, log_file);
        }

        fflush(log_file);
        sleep(DELAY);
    }

    return 0;
}
