#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_SHUTDOWN_PIN 17
#define GPIO_MCP3008_CH0 8
#define GPIO_MCP3008_SCLK 11
#define GPIO_MCP3008_MOSI 10
#define GPIO_MCP3008_MISO 9
#define MAX_TRIES 3
#define SENSITIVITY 0.1
#define OFFSET 0.05
#define LOG_FILE "current_log.csv"
#define MLX91211_MAX_CURRENT 10.0

struct gpiod_line *gpio_shutdown;
struct gpiod_chip *gpiod_chip;
int spi_fd;

void exit_handler(int signum) {
    gpiod_line_set_value(gpio_shutdown, 1);
    gpiod_line_release(gpio_shutdown);
    gpiod_chip_close(gpiod_chip);
    close(spi_fd);
    exit(0);
}

int main() {
    struct sigaction action;
    action.sa_handler = exit_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open spi device");
        exit(1);
    }

    int retry = 0;
    while (retry < MAX_TRIES) {
        gpiod_chip = gpiod_chip_open_by_name("/dev/gpiochip0");
        if (!gpiod_chip) {
            perror("open gpio chip");
            if (++retry > MAX_TRIES)
                exit(1);
            continue;
        }

        gpio_shutdown = gpiod_chip_get_line(gpiod_chip, GPIO_SHUTDOWN_PIN);
        if (!gpio_shutdown) {
            perror("get gpio line");
            gpiod_chip_close(gpiod_chip);
            if (++retry > MAX_TRIES)
                exit(1);
            continue;
        }

        if (gpiod_line_request_output(gpio_shutdown, "shutdown", 1)) {
            perror("request gpio line");
            gpiod_line_release(gpio_shutdown);
            gpiod_chip_close(gpiod_chip);
            if (++retry > MAX_TRIES)
                exit(1);
            continue;
        }
        break;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("open log file");
        exit_handler(0);
    }

    if (fseek(log_file, 0, SEEK_END) != 0 || ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,current\n");
    }

    while (1) {
        int16_t adc_value = 0;
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &adc_value) < 0) {
            perror("spi transfer");
            exit_handler(0);
        }

        double voltage = (adc_value * 3.3) / 1023.0;
        double current = (voltage - OFFSET) / SENSITIVITY;
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s,%.2f\n", timestamp, current);
        fflush(log_file);

        if (current > MLX91211_MAX_CURRENT) {
            gpiod_line_set_value(gpio_shutdown, 0);
            sleep(1);
            gpiod_line_set_value(gpio_shutdown, 1);
        }

        sleep(1);
    }

    return 0;
}

