#define MLX90817_I2C_BUS 1
#define MLX90817_I2C_ADDR 0x40
#define MLX90817_REG_PRESSURE 0x00

static int i2c_handle = -1;
static FILE *log_file = NULL;

void sig_handler(int signo) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(signo);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(MLX90817_I2C_BUS, MLX90817_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return EXIT_FAILURE;
    }

    log_file = fopen("pressure_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        return EXIT_FAILURE;
    }

    if (fprintf(log_file, "timestamp,pressure_kPa\n") < 0) {
        fprintf(stderr, "Failed to write to log file.\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        uint16_t raw_value;
        int res = i2cReadWord(i2c_handle, MLX90817_REG_PRESSURE, &raw_value);
        if (res < 0) {
            fprintf(stderr, "Failed to read from sensor: %d\n", res);
            sleep(1);
            continue;
        }

        double pressure_kPa = (raw_value / 65535.0) * 500.0;

        time_t now = time(NULL);
        struct tm *utc_time = gmtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%FT%TZ", utc_time);

        if (fprintf(log_file, "%s,%.2f\n", timestamp, pressure_kPa) < 0) {
            fprintf(stderr, "Failed to write to log file.\n");
            return EXIT_FAILURE;
        }

        fflush(log_file);

        sleep(1);
    }

    return EXIT_SUCCESS;
}

