#include <stdio.h>
#include <signal.h>
#include <pigpio.h>

#define ADDR 0x48
#define GAIN 0x03
#define MUX 0x04
#define OSR 0x08
#define PGAIN 0x00
#define TGAIN 0x01

#define LED 17
#define PRESSURE_THRESHOLD 105.0

static int pi;

void cleanup(int sig) {
    // Release resources
    piGpioInitialise();
    piI2IClose(pi, ADDR);
    exit(0);
}

int main() {
    int ret;
    uint16_t data;
    float pressure, temperature;

    // Register cleanup handler
    signal(SIGINT, cleanup);

    // Initialise pigpio
    pi = piGpioInitialise();
    if (pi < 0) {
        printf("Failed to initialise pigpio: %d\n", pi);
        return -1;
    }

    // Open I2C device
    ret = piI2COpen(pi, ADDR);
    if (ret < 0) {
        printf("Failed to open I2C device: %d\n", ret);
        return -1;
    }

    // Configure ADS1115
    ret = piI2CWrite(pi, ADDR, GAIN, 0x00);
    if (ret < 0) {
        printf("Failed to write to I2C device: %d\n", ret);
        return -1;
    }

    ret = piI2CWrite(pi, ADDR, MUX, 0x04);
    if (ret < 0) {
        printf("Failed to write to I2C device: %d\n", ret);
        return -1;
    }

    ret = piI2CWrite(pi, ADDR, OSR, 0x08);
    if (ret < 0) {
        printf("Failed to write to I2C device: %d\n", ret);
        return -1;
    }

    // Set LED as output
    ret = piGpioSetMode(pi, LED, PI_OUTPUT);
    if (ret < 0) {
        printf("Failed to set GPIO mode: %d\n", ret);
        return -1;
    }

    while (1) {
        // Read pressure
        for (int i = 0; i < 3; i++) {
            ret = piI2CRead(pi, ADDR, PGAIN, &data);
            if (ret >= 0) break;
            printf("Failed to read from I2C device: %d\n", ret);
        }
        if (ret < 0) return -1;

        pressure = (float)data * 6.144 / 2048;
        pressure = pressure * 400 / 3.3;

        // Read temperature
        for (int i = 0; i < 3; i++) {
            ret = piI2CRead(pi, ADDR, TGAIN, &data);
            if (ret >= 0) break;
            printf("Failed to read from I2C device: %d\n", ret);
        }
        if (ret < 0) return -1;

        temperature = (float)data * 6.144 / 2048;
        temperature = (temperature - 1) * 100 / 1.5;

        printf("Pressure: %.1f kPa, Temperature: %.1f C\n", pressure, temperature);

        // Set LED state
        if (pressure > PRESSURE_THRESHOLD) {
            ret = piGpioWrite(pi, LED, PI_HIGH);
        } else {
            ret = piGpioWrite(pi, LED, PI_LOW);
        }
        if (ret < 0) {
            printf("Failed to write GPIO: %d\n", ret);
            return -1;
        }

        // Sleep for 1 second
        sleep(1);
    }

    return 0;
}

