    sigaction(SIGINT, &sigIntHandler, NULL);
    sigaction(SIGTERM, &sigIntHandler, NULL);

    if (gpioInitialise() < 0) {
        printf("gpioInitialise() failed\n");
        return -1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        printf("spiOpen() failed\n");
        return -1;
    }

    gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT);

    log_file = fopen("current_log.txt", "a");
    if (log_file == NULL) {
        printf("fopen() failed\n");
        return -1;
    }

    while (1) {
        unsigned char tx_buf[3] = {0x01, (ADC_CHANNEL << 4), 0x00};
        unsigned char rx_buf[3];
        if (spiWriteRead(spi_handle, tx_buf, rx_buf, 3) < 0) {
            printf("spiWriteRead() failed\n");
            return -1;
        }

        int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
        if (adc_value < 0 || adc_value > ADC_MAX) {
            printf("Invalid ADC value: %d\n", adc_value);
            return -1;
        }

        double voltage = (double)adc_value / ADC_MAX * VOLT_MAX;
        double current = (voltage - VOLT_MAX / 2) / CURRENT_SENSITIVITY;
        if (current < 0) current = 0;

        time_t t = time(NULL);
        struct tm *lt = localtime(&t);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", lt);

        if (current > CURRENT_MAX) {
            gpioWrite(GPIO_SHUTDOWN, 1);
            fprintf(log_file, "%s OVERCURRENT\n", timestamp);
            sig_handler(0);
        }

        fprintf(log_file, "%s %.3f\n", timestamp, current);
        fflush(log_file);

        sleep(0.1);
    }

    return 0;
