#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_CS 8

#define ADC_CMD 0x018000

FILE *log_file;
int spi_handle;

void shutdown_handler(int signum) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    struct tm timestamp;
    time_t now;
    char log_line[128];
    int adc_value;
    int methane_ppm;
    int res;
    unsigned char tx[3];
    unsigned char rx[3];

    signal(SIGINT, shutdown_handler);
    signal(SIGTERM, shutdown_handler);

    spi_handle = -1;
    log_file = NULL;

    res = gpioInitialise();
    if (res < 0) {
        fprintf(stderr, "gpioInitialise() failed: %d\n", res);
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen() failed: %d\n", spi_handle);
        return 1;
    }

    log_file = fopen("methane_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "fopen() failed\n");
        return 1;
    }

    while (1) {
        tx[0] = ADC_CMD >> 16;
        tx[1] = ADC_CMD >> 8;
        tx[2] = ADC_CMD;

        res = spiXfer(spi_handle, SPI_CS, tx, rx, 3);
        if (res < 0) {
            fprintf(stderr, "spiXfer() failed: %d\n", res);
            continue;
        }

        adc_value = ((rx[1] & 0x03) << 8) | rx[2];
        methane_ppm = adc_value * 5000 / 1023;

        now = time(NULL);
        localtime_r(&now, &timestamp);
        strftime(log_line, sizeof(log_line), "%Y-%m-%dT%H:%M:%S", &timestamp);
        sprintf(log_line + strlen(log_line), " %d\n", methane_ppm);

        fputs(log_line, log_file);
        fflush(log_file);

        if (methane_ppm > 1000) {
            fprintf(stderr, "LEAK ALARM: Methane concentration exceeds 1000 PPM!\n");
        }
    }

    shutdown_handler(0);

    return 0;
}

