#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define ADDR 0x48
#define MLX_ADDR 0x15
#define MLX_PRESSURE 0x00
#define ADC_CHANNEL 0
#define SAMPLE_RATE 1000
#define VREF 3.3
#define GAIN 1
#define OFFSET 0.5
#define SENSITIVITY 0.1
#define LOWER_PRESSURE_LIMIT 0
#define UPPER_PRESSURE_LIMIT 100

static int i2c_fd = -1;
static int mlx_fd = -1;
static FILE *log_file = NULL;

void cleanup_and_exit(int sig) {
    if (i2c_fd != -1) {
        piI2CClose(i2c_fd);
    }
    if (mlx_fd != -1) {
        piI2CClose(mlx_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(sig);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    i2c_fd = piI2C(1, ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device.\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    mlx_fd = piI2C(1, MLX_ADDR);
    if (mlx_fd < 0) {
        fprintf(stderr, "Failed to open MLX device.\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    log_file = fopen("pressure_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    signal(SIGINT, cleanup_and_exit);

    while (1) {
        int data = 0;
        if (piI2CReadByteData(mlx_fd, MLX_PRESSURE, &data) < 0) {
            fprintf(stderr, "Failed to read MLX data.\n");
            cleanup_and_exit(EXIT_FAILURE);
        }

        int raw_adc = data;
        double voltage = (double)raw_adc / (1 << 16) * VREF * GAIN;
        double pressure = (voltage - OFFSET) / SENSITIVITY;

        if (pressure < LOWER_PRESSURE_LIMIT || pressure > UPPER_PRESSURE_LIMIT) {
            continue;
        }

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

        fprintf(log_file, "%s, %.2f\n", timestamp, pressure);
        fflush(log_file);

        sleep(SAMPLE_RATE / 1000);
    }

    cleanup_and_exit(EXIT_SUCCESS);
}

