#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_FLAGS (SPI_MODE_0 | SPI_CS_HIGH | SPI_3WIRE | SPI_LSB_FIRST | SPI_CLOCK_DIV2)
#define SPI_SPEED 1000000
#define SPI_BUF_SIZE 4
#define ADC_VREF 5000
#define THERMISTOR_BETA 3950
#define THERMISTOR_R0 10000
#define THERMISTOR_T0 25
#define HUMIDITY_ALERT 80
#define LOG_FILE "humidity_log.txt"

FILE *log_file;
int spi_handle;

void cleanup(int signum) {
    if (log_file) fclose(log_file);
    if (spi_handle >= 0) gpioSpidevClose(spi_handle);
    exit(0);
}

int main() {
    int ret;
    unsigned char spi_tx_buf[SPI_BUF_SIZE] = {0};
    unsigned char spi_rx_buf[SPI_BUF_SIZE] = {0};
    float humidity, temperature;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    spi_handle = gpioSpidevOpen(SPI_DEVICE, SPI_FLAGS, SPI_SPEED);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(-spi_handle));
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup(0);
        return 1;
    }

    while (1) {
        ret = gpioSpidevTransfer(spi_handle, spi_tx_buf, spi_rx_buf, SPI_BUF_SIZE);
        if (ret < 0) {
            fprintf(stderr, "SPI transfer failed: %s\n", strerror(-ret));
            cleanup(0);
            return 1;
        }

        // Convert 12-bit ADC result to voltage
        int adc_result = (spi_rx_buf[1] & 0x0F) << 8 | spi_rx_buf[2];
        float adc_voltage = (float)adc_result / 0xFFF * ADC_VREF;

        // Calculate humidity and temperature
        humidity = (adc_voltage - 0.824) / 0.0315;
        float r_thermistor = (ADC_VREF - adc_voltage) / adc_voltage * THERMISTOR_R0;
        temperature = 1 / (1 / THERMISTOR_R0 + log(r_thermistor / THERMISTOR_R0) / THERMISTOR_BETA) - 273.15;

        // Log readings
        time_t t = time(NULL);
        struct tm *tm = localtime(&t);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
        fprintf(log_file, "%s, %.2f, %.2f\n", timestamp, humidity, temperature);
        fflush(log_file);

        // Send alert if humidity is too high
        if (humidity > HUMIDITY_ALERT) {
            // TODO: implement email alert
        }
    }

    return 0;
}

