#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 1000000
#define LOG_FILE "temperature_log.csv"

struct gpiod_chip *chip = NULL;
struct gpiod_line *cs_line = NULL;
int spi_fd = -1;
FILE *log_file = NULL;

void cleanup_and_exit(int exit_code) {
    if (cs_line)
        gpiod_line_release(cs_line);
    if (chip)
        gpiod_chip_close(chip);
    if (spi_fd >= 0)
        close(spi_fd);
    if (log_file)
        fclose(log_file);
    exit(exit_code);
}

void handle_signal(int signum) {
    printf("Signal %d received, cleaning up and exiting...\n", signum);
    cleanup_and_exit(0);
}

int main() {
    struct spi_ioc_transfer xfer;
    uint8_t tx_buf[3] = {0x01, 0x80, 0x00};
    uint8_t rx_buf[3] = {0, 0, 0};
    float voltage, temp;
    time_t now;
    struct tm *time_info;
    char time_string[20];

    chip = gpiod_chip_open_by_number(4);
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        cleanup_and_exit(1);
    }

    cs_line = gpiod_chip_get_line(chip, CS_LINE);
    if (!cs_line) {
        perror("gpiod_chip_get_line");
        cleanup_and_exit(1);
    }

    if (gpiod_line_request_output(cs_line, "cs_line", 1)) {
        perror("gpiod_line_request_output");
        cleanup_and_exit(1);
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        cleanup_and_exit(1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_MAX_SPEED_HZ)) {
        perror("ioctl");
        cleanup_and_exit(1);
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        cleanup_and_exit(1);
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,temperature_celsius\n");
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        xfer.tx_buf = (unsigned long)tx_buf;
        xfer.rx_buf = (unsigned long)rx_buf;
        xfer.len = 3;
        xfer.speed_hz = SPI_MAX_SPEED_HZ;
        xfer.bits_per_word = SPI_BITS_PER_WORD;
        xfer.delay_usecs = 0;
        xfer.cs_change = 0;

        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer)) {
            perror("ioctl");
            cleanup_and_exit(1);
        }

        gpiod_line_set_value(cs_line, 1);

        voltage = ((float)((rx_buf[1] << 8) | rx_buf[2])) / 4095.0 * 3.3;
        temp = (voltage - 0.5) / 0.01;

        if (temp < -40.0 || temp > 125.0) {
            printf("Invalid temperature reading: %.2fC\n", temp);
            sleep(1);
            continue;
        }

        now = time(NULL);
        time_info = localtime(&now);
        strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", time_info);

        fprintf(log_file, "%s,%.2f\n", time_string, temp);
        fflush(log_file);

        sleep(1);
    }

    return 0;
}

