#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define ADC_CHANNELS 3
#define SAMPLE_RATE 100
#define IMPACT_THRESHOLD 2.0
#define VREF 3.3
#define ADXL335_0G 1.65
#define ADXL335_SENSITIVITY 0.3

FILE *log_file;
int spi_handle;

void handle_sigint(int signo) {
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main() {
    struct timespec ts;
    int i, j, ret;
    unsigned char tx_buf[2], rx_buf[ADC_CHANNELS * 2];
    float adc_values[ADC_CHANNELS], accel_values[ADC_CHANNELS], magnitude;

    signal(SIGINT, handle_sigint);

    ret = gpioInitialise();
    if (ret < 0) {
        printf("gpioInitialise failed: %d\n", ret);
        return 1;
    }

    spi_handle = spiOpen("/dev/spidev0.0", 1000000, 0);
    if (spi_handle < 0) {
        printf("spiOpen failed: %d\n", spi_handle);
        return 1;
    }

    log_file = fopen("impact_log.txt", "w");
    if (log_file == NULL) {
        printf("fopen failed\n");
        return 1;
    }

    while (1) {
        for (i = 0; i < ADC_CHANNELS; i++) {
            tx_buf[0] = (1 << 7) | (i << 4);
            tx_buf[1] = 0;

            ret = spiXfer(spi_handle, tx_buf, rx_buf + 2 * i, 2);
            if (ret != 0) {
                printf("spiXfer failed: %d\n", ret);
                return 1;
            }

            adc_values[i] = ((rx_buf[2 * i] & 0x03) << 8) | rx_buf[2 * i + 1];
        }

        for (i = 0; i < ADC_CHANNELS; i++) {
            accel_values[i] = (adc_values[i] * VREF / 1023 - ADXL335_0G) / ADXL335_SENSITIVITY;
        }

        magnitude = 0;
        for (i = 0; i < ADC_CHANNELS; i++) {
            magnitude += accel_values[i] * accel_values[i];
        }
        magnitude = sqrt(magnitude);

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld,%.9ld,%.2f,%.2f,%.2f", ts.tv_sec, ts.tv_nsec, accel_values[0], accel_values[1], accel_values[2]);

        if (magnitude > IMPACT_THRESHOLD) {
            fprintf(log_file, ",IMPACT DETECTED\n");
        } else {
            fprintf(log_file, "\n");
        }

        fflush(log_file);

        usleep(1000000 / SAMPLE_RATE);
    }

    return 0;
}

