#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x49
#define I2C_CMD_REG 0xC0
#define I2C_DATA_REG 0xC1
#define I2C_ERR_FLAG_OK 0
#define I2C_ERR_FLAG_READ_ERR 1
#define I2C_ERR_FLAG_SENSOR_ABSENT 2

FILE *log_file;
int i2c_handle;

void handle_sigint(int signum) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    signal(SIGINT, handle_sigint);

    log_file = fopen("biometric_log.csv", "w");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        return 1;
    }
    fprintf(log_file, "timestamp,HR,SpO2,error_flag\n");
    fflush(log_file);

    int pi = gpioInitialise();
    if (pi < 0) {
        printf("Failed to initialize pigpio: %d\n", pi);
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        printf("Failed to open I2C device: %d\n", i2c_handle);
        fprintf(log_file, "%ld,,,%d\n", time(NULL), I2C_ERR_FLAG_SENSOR_ABSENT);
        fflush(log_file);
        return 1;
    }

    while (1) {
        int cmd_ret = i2cWriteByteData(i2c_handle, I2C_CMD_REG, 0x00);
        if (cmd_ret < 0) {
            printf("Failed to write to command register: %d\n", cmd_ret);
            fprintf(log_file, "%ld,,,%d\n", time(NULL), I2C_ERR_FLAG_READ_ERR);
            fflush(log_file);
            continue;
        }

        unsigned char data[2];
        int data_ret = i2cRead(i2c_handle, I2C_DATA_REG, data, 2);
        if (data_ret < 0) {
            printf("Failed to read from data register: %d\n", data_ret);
            fprintf(log_file, "%ld,,,%d\n", time(NULL), I2C_ERR_FLAG_READ_ERR);
            fflush(log_file);
            continue;
        }

        int ir = (data[0] << 8) | data[1];
        int red = (data[2] << 8) | data[3];
        fprintf(log_file, "%ld,%d,%d,%d\n", time(NULL), ir, red, I2C_ERR_FLAG_OK);
        fflush(log_file);

        sleep(1);
    }

    return 0;
}

