#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define ADC_CHANNEL 0
#define MAX_FLOW_RATE 5.0
#define MIN_FLOW_RATE 0.0
#define LOG_FILE "flow_log.csv"

FILE *log_file;
int spi_handle;

void exit_handler(int signum) {
    fclose(log_file);
    spi_close(spi_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    int pi = gpioInitialise();
    if (pi < 0) {
        fprintf(stderr, "Error initializing pigpio: %d\n", pi);
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        spi_close(spi_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, exit_handler);
    signal(SIGTERM, exit_handler);

    while (1) {
        uint32_t adc_value;
        int res = spiRead(spi_handle, ADC_CHANNEL, &adc_value);
        if (res < 0) {
            fprintf(stderr, "Error reading from ADC: %d\n", res);
            continue;
        }

        if (adc_value == 0 || adc_value == 0x3FF) {
            fprintf(stderr, "Sensor not present\n");
            continue;
        }

        double voltage = (double)adc_value / 1023 * 3.3;
        double flow_rate = voltage / 3.3 * MAX_FLOW_RATE;
        if (flow_rate < MIN_FLOW_RATE || flow_rate > MAX_FLOW_RATE) {
            fprintf(stderr, "Invalid flow rate: %f\n", flow_rate);
            continue;
        }

        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        struct tm *timeinfo = localtime(&ts.tv_sec);

        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(log_file, "%s.%06ld,%f\n", timestamp, ts.tv_nsec / 1000, flow_rate);
        fflush(log_file);
    }

    exit_handler(0);
    return 0;
}

