#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEV "/dev/i2c-1"
#define SENSOR_ADDR 0x67
#define MEASUREMENT_CMD 0x6845
#define DATA_LEN 6

int i2c_fd = -1;
FILE *csv_file = NULL;

void cleanup_and_exit(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    exit(signum);
}

int main() {
    int ret;
    unsigned char data[DATA_LEN];

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    csv_file = fopen("environmental_data.csv", "w");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        return EXIT_FAILURE;
    }

    while (1) {
        i2c_fd = open(I2C_DEV, O_RDWR);
        if (i2c_fd == -1) {
            perror("Failed to open I2C device");
            sleep(5);
            continue;
        }

        ret = ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR);
        if (ret == -1) {
            perror("Failed to set sensor address");
            close(i2c_fd);
            sleep(5);
            continue;
        }

        ret = write(i2c_fd, &MEASUREMENT_CMD, sizeof(MEASUREMENT_CMD));
        if (ret == -1) {
            perror("Failed to write measurement command");
            close(i2c_fd);
            sleep(5);
            continue;
        }

        sleep(1);  // Wait for conversion to finish

        ret = read(i2c_fd, data, DATA_LEN);
        if (ret == -1) {
            perror("Failed to read sensor data");
            close(i2c_fd);
            sleep(5);
            continue;
        }

        close(i2c_fd);

        // Convert raw data to temperature and pressure
        int32_t pressure = (data[0] << 16) | (data[1] << 8) | data[2];
        int32_t temperature = (data[3] << 16) | (data[4] << 8) | data[5];

        // TODO: Apply ICP-10125 calibration formulas
        // ...

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        printf("%s, %d Pa, %d C\n", timestamp, pressure, temperature);
        fprintf(csv_file, "%s, %d, %d\n", timestamp, pressure, temperature);

        sleep(5);
    }

    return EXIT_SUCCESS;
}

