#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define GAIN 1
#define SAMPLE_RATE 1000
#define MIC1_SPI_CHANNEL 0
#define MIC2_SPI_CHANNEL 1

volatile sig_atomic_t stop = 0;

void sigint_handler(int signo) {
    stop = 1;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        printf("Usage: %s <gain>\n", argv[0]);
        return 1;
    }

    int gain = atoi(argv[1]);

    if (gain < 1 || gain > 10) {
        printf("Gain must be between 1 and 10\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio\n");
        return 1;
    }

    if (spiOpen(MIC1_SPI_CHANNEL, SAMPLE_RATE, 0) < 0 || spiOpen(MIC2_SPI_CHANNEL, SAMPLE_RATE, 0) < 0) {
        printf("Failed to open SPI channel\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (!stop) {
        int mic1_data = spiRead(MIC1_SPI_CHANNEL, ADC_CHANNEL);
        int mic2_data = spiRead(MIC2_SPI_CHANNEL, ADC_CHANNEL);

        if (mic1_data < 0 || mic2_data < 0) {
            printf("Failed to read from SPI channel\n");
            spiClose(MIC1_SPI_CHANNEL);
            spiClose(MIC2_SPI_CHANNEL);
            gpioTerminate();
            return 1;
        }

        int result = (mic1_data - mic2_data) * gain;

        printf("%d,%d,%d\n", mic1_data, mic2_data, result);
    }

    spiClose(MIC1_SPI_CHANNEL);
    spiClose(MIC2_SPI_CHANNEL);
    gpioTerminate();

    return 0;
}

