#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_DEVICE "/dev/spidev0.0"
#define ADC_CHANNEL 0
#define LOG_FILE "moisture_log.txt"

static int spi_handle = -1;
static FILE *log_file = NULL;

void cleanup_and_exit(int signum) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    piGpioTerminate();
    exit(signum);
}

int main() {
    if (piGpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_DEVICE, 1000000, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", SPI_DEVICE);
        cleanup_and_exit(EXIT_FAILURE);
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        cleanup_and_exit(EXIT_FAILURE);
    }

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    while (1) {
        unsigned char tx_buf[3] = {1, (ADC_CHANNEL << 4), 0};
        unsigned char rx_buf[3] = {0, 0, 0};

        if (spiXfer(spi_handle, tx_buf, rx_buf, 3) < 0) {
            fprintf(stderr, "SPI transfer failed.\n");
            cleanup_and_exit(EXIT_FAILURE);
        }

        int adc_reading = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
        if (adc_reading < 0 || adc_reading > 1023) {
            fprintf(stderr, "Invalid ADC reading: %d\n", adc_reading);
            cleanup_and_exit(EXIT_FAILURE);
        }

        time_t now = time(NULL);
        struct tm *utc_time = gmtime(&now);
        char timestamp[20] = {0};
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_time);

        if (fprintf(log_file, "%s,%d\n", timestamp, adc_reading) < 0) {
            fprintf(stderr, "Failed to write to log file.\n");
            cleanup_and_exit(EXIT_FAILURE);
        }

        fflush(log_file);
        sleep(60);
    }

    cleanup_and_exit(EXIT_SUCCESS);
}

