#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <linux/spi/spidev.h>

#define SPI_DEV "/dev/spidev0.0"
#define GPIO_BUZZER 18
#define ADC_CHANNEL 0
#define ADC_MAX_VALUE 1023
#define FLAME_DETECT_VOLTAGE 1.0
#define DEFAULT_TEMP 25.0

struct gpiod_chip *chip;
struct gpiod_line *line;
int spi_fd;
FILE *log_file;
volatile sig_atomic_t stop;

void handle_sigint(int signum) {
    stop = 1;
}

void write_log(const char *format, ...) {
    va_list args;
    va_start(args, format);
    vfprintf(log_file, format, args);
    va_end(args);
    fflush(log_file);
}

double read_temp() {
    double temp;
    FILE *file = fopen("ambient_temp.txt", "r");
    if (!file || fscanf(file, "%lf", &temp) != 1) {
        temp = DEFAULT_TEMP;
    }
    if (file) fclose(file);
    return temp;
}

int read_adc() {
    uint8_t tx_buf[3] = {0x01, 0x80, 0x00};
    uint8_t rx_buf[3] = {0x00, 0x00, 0x00};
    struct spi_ioc_transfer xfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = 1000000,
        .bits_per_word = 8,
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) == -1) {
        return -1;
    }
    int value = (rx_buf[1] & 0x03) << 8 | rx_buf[2];
    return value > ADC_MAX_VALUE ? -1 : value;
}

int main() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }
    line = gpiod_chip_get_line(chip, GPIO_BUZZER);
    if (!line) {
        perror("gpiod_chip_get_line");
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(line, "buzzer", 0) == -1) {
        perror("gpiod_line_request_output");
        return EXIT_FAILURE;
    }
    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd == -1) {
        perror("open");
        return EXIT_FAILURE;
    }
    log_file = fopen("flame_log.txt", "w");
    if (!log_file) {
        perror("fopen");
        return EXIT_FAILURE;
    }
    signal(SIGINT, handle_sigint);
    while (!stop) {
        int adc_value;
        for (int i = 0; i < 3; i++) {
            adc_value = read_adc();
            if (adc_value != -1) break;
            usleep(500000);
        }
        if (adc_value == -1) {
            write_log("Failed to read ADC value\n");
            gpiod_line_set_value(line, 0);
            continue;
        }
        double voltage = adc_value * 3.3 / ADC_MAX_VALUE;
        double temp = read_temp();
        double comp_voltage = voltage + (temp - DEFAULT_TEMP) * 0.001;
        int flame_detected = comp_voltage > FLAME_DETECT_VOLTAGE;
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
        write_log("%s,%d,%.2f,%.2f,%.2f,%d\n", timestamp, adc_value, voltage, comp_voltage, temp, flame_detected);
        gpiod_line_set_value(line, flame_detected);
        usleep(500000);
    }
    gpiod_line_set_value(line, 0);
    fclose(log_file);
    close(spi_fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

