#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define LED_PIN 17
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define WATER_LEVEL_THRESHOLD 75
#define WATER_LEVEL_HYSTERESIS 10
#define JSON_FILE "water_levels.json"

FILE *json_file;
int spi_handle;
int led_state = 0;
int should_exit = 0;

void write_to_json(int water_level) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char time_str[30];
    strftime(time_str, sizeof(time_str), "%Y-%m-%dT%H:%M:%S", localtime(&ts.tv_sec));
    fprintf(json_file, "{\"timestamp\":\"%s.%03ld\",\"water_level\":%d},\n", time_str, ts.tv_nsec / 1000000, water_level);
    fflush(json_file);
}

void handle_exit(int signum) {
    should_exit = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio: %s\n", pigpio_error());
        return 1;
    }

    spi_handle = spiOpen("/dev/spidev0.0", SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        printf("Failed to open SPI device: %s\n", pigpio_error());
        gpioTerminate();
        return 1;
