    if (sigaction(SIGINT, &action, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }
    if (sigaction(SIGTERM, &action, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }

    if (piGpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio\n");
        exit_handler(0);
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
