            fprintf(stderr, "Error reading from SPI device\n");
            exit_handler(0);
        }

        int raw_value = (rx_buf[1] & 0x03) << 8 | rx_buf[2];
        // The sensor outputs a 10-bit value representing mass flow rate in LPM
        // The conversion factor is 1000 LPM per 1023 ADC counts
        double lpm = raw_value * 1000.0 / 1023.0;

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

        fprintf(file, "%s,%.2f\n", timestamp, lpm);
        fflush(file);

        sleep(0.1);
    }

    exit_handler(0);
    return 0;
}

