#define MAX_BUF 100

struct config {
    int spi_channel;
    int adc_channel;
    int min_raw;
    int max_raw;
    int moisture_threshold;
    int log_frequency;
    char email[MAX_BUF];
    char msmtp_config[MAX_BUF];
};

struct context {
    int spi_handle;
    struct config *config;
};

void log_error(const char *msg) {
    fprintf(stderr, "%s\n", msg);
}

void send_email(struct context *ctx) {
    char cmd[MAX_BUF];
    snprintf(cmd, MAX_BUF, "echo \"Moisture level dropped below %d%%\" | msmtp -C %s %s",
             ctx->config->moisture_threshold, ctx->config->msmtp_config, ctx->config->email);
    if (system(cmd) != 0) {
        log_error("Failed to send email");
    }
}

void log_moisture(struct context *ctx, int moisture) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char buffer[MAX_BUF];
    strftime(buffer, MAX_BUF, "%Y-%m-%d %H:%M:%S", timeinfo);
    FILE *file = fopen("plant_data.txt", "a");
    if (file == NULL) {
        log_error("Failed to open plant_data.txt");
        return;
    }
    fprintf(file, "%s, %d\n", buffer, moisture);
    fclose(file);
    if (moisture < ctx->config->moisture_threshold) {
        send_email(ctx);
    }
}

void read_moisture(struct context *ctx) {
    int value = spiRead(ctx->spi_handle);
    if (value < 0) {
        log_error("Failed to read ADC");
        return;
    }
    int moisture = (value - ctx->config->min_raw) * 100 / (ctx->config->max_raw - ctx->config->min_raw);
    if (moisture < 0) {
        moisture = 0;
    } else if (moisture > 100) {
        moisture = 100;
    }
    log_moisture(ctx, moisture);
}

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        spiClose(spiHandle);
        gpioTerminate();
        exit(0);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 9) {
        fprintf(stderr, "Usage: %s <spi_channel> <adc_channel> <min_raw> <max_raw> <moisture_threshold> <log_frequency> <email> <msmtp_config>\n", argv[0]);
        return 1;
    }

    struct config *config = malloc(sizeof(struct config));
    config->spi_channel = atoi(argv[1]);
    config->adc_channel = atoi(argv[2]);
    config->min_raw = atoi(argv[3]);
    config->max_raw = atoi(argv[4]);
    config->moisture_threshold = atoi(argv[5]);
    config->log_frequency = atoi(argv[6]);
    strncpy(config->email, argv[7], MAX_BUF);
    strncpy(config->msmtp_config, argv[8], MAX_BUF);

    struct context *ctx = malloc(sizeof(struct context));
    ctx->config = config;

    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        return 1;
    }

    ctx->spi_handle = spiOpen(config->spi_channel, 500000, 0);
    if (ctx->spi_handle < 0) {
        log_error("Failed to open SPI");
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        read_moisture(ctx);
        sleep(config->log_frequency);
    }

    spiClose(ctx->spi_handle);
    gpioTerminate();
    free(config);
    free(ctx);

    return 0;
}

