#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <linux/spi/spidev.h>
#include <sys/ioctl.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CHANNEL 0
#define DRY_CALIBRATION 700
#define WET_CALIBRATION 300

static int fd;

void exit_handler(int signum) {
    close(fd);
    exit(0);
}

int main() {
    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return 1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, 0) < 0) {
        perror("Error setting SPI mode");
        return 1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, 8) < 0) {
        perror("Error setting bits per word");
        return 1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, 1000000) < 0) {
        perror("Error setting max speed Hz");
        return 1;
    }

    signal(SIGINT, exit_handler);
    signal(SIGTERM, exit_handler);

    while (1) {
        uint8_t command[3] = {0x01, 0x80 + (CHANNEL << 4), 0x00};
        uint8_t response[2];

        if (write(fd, command, sizeof(command)) != sizeof(command)) {
            perror("Error writing to SPI device");
            return 1;
        }

        if (read(fd, response, sizeof(response)) != sizeof(response)) {
            perror("Error reading from SPI device");
            return 1;
        }

        int raw_adc = ((response[0] & 0x03) << 8) | response[1];
