#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CS 8
#define GPIO_MISO 9
#define GPIO_MOSI 10
#define GPIO_SCLK 11

static int pi_handle = 0;
static int spi_handle = 0;

void exit_handler(int signum) {
    if (spi_handle > 0) {
        spi_close(spi_handle);
    }
    if (pi_handle > 0) {
        gpioTerminate();
    }
    exit(0);
}

int main() {
    signal(SIGINT, exit_handler);
    signal(SIGTERM, exit_handler);

    pi_handle = gpioInitialise();
    if (pi_handle <= 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(-pi_handle));
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_DEVICE, GPIO_SCLK, GPIO_CS, GPIO_MISO, GPIO_MOSI);
    if (spi_handle <= 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(-spi_handle));
        exit_handler(0);
        return EXIT_FAILURE;
    }

    while (1) {
        int16_t adc_value = spiRead(spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read from SPI device: %s\n", strerror(-adc_value));
            exit_handler(0);
            return EXIT_FAILURE;
        }

        if (adc_value < 0 || adc_value > 1023) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            continue;
        }

        double voltage = (double)adc_value / 1023.0 * 3.3;
        if (voltage < 0.5 || voltage > 4.5) {
            fprintf(stderr, "Sensor absent or out of range: %.2fV\n", voltage);
            continue;
        }

        double pressure = 100.0 + (voltage - 2.5) * 100.0;
        if (pressure < 10.0 || pressure > 150.0) {
            fprintf(stderr, "Pressure out of range: %.2fkPa\n", pressure);
            continue;
        }

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

        printf("%s: %.2fkPa\n", timestamp, pressure);

        sleep(1);
    }

    exit_handler(0);
    return EXIT_SUCCESS;
}

