#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <libgpiod.h>
#include <spi/spi.h>

#define SPI_BUS_PATH "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_FREQ 1000000
#define SPI_CS_GPIO 8
#define ADC_CHANNEL 0
#define MIN_ADC_VALUE 300
#define MAX_ADC_VALUE 700
#define READ_INTERVAL 5

struct spi_device *spi;
struct gpiod_chip *gpiod_chip;
struct gpiod_line *cs_line;
int exit_flag = 0;

void exit_handler(int signum) {
    exit_flag = 1;
}

void error_handler(const char *msg) {
    fprintf(stderr, "%s: %s\n", msg, strerror(errno));
    exit(EXIT_FAILURE);
}

void cleanup() {
    if (cs_line)
        gpiod_line_release(cs_line);
    if (gpiod_chip)
        gpiod_chip_close(gpiod_chip);
    if (spi)
        spi_device_close(spi);
}

int main() {
    struct spi_ioc_transfer xfer;
    uint16_t tx_buf = ((ADC_CHANNEL << 12) | 0x8000) >> 8;
    uint16_t rx_buf = 0;
    int moisture_percent;

    signal(SIGINT, exit_handler);
    signal(SIGTERM, exit_handler);

    spi = spi_device_open(SPI_BUS_PATH, SPI_MODE, SPI_FREQ);
    if (!spi)
        error_handler("spi_device_open");

    gpiod_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!gpiod_chip)
        error_handler("gpiod_chip_open");

    cs_line = gpiod_chip_get_line(gpiod_chip, SPI_CS_GPIO);
    if (!cs_line)
        error_handler("gpiod_chip_get_line");

    if (gpiod_line_request_output(cs_line, "cs_line", 1))
        error_handler("gpiod_line_request_output");

    memset(&xfer, 0, sizeof(xfer));
    xfer.tx_buf = (unsigned long)&tx_buf;
    xfer.rx_buf = (unsigned long)&rx_buf;
    xfer.len = 2;
    xfer.speed_hz = SPI_FREQ;
    xfer.cs_change = 1;

    while (!exit_flag) {
        if (gpiod_line_set_value(cs_line, 0))
            error_handler("gpiod_line_set_value");

        if (spi_device_transfer(spi, &xfer))
            error_handler("spi_device_transfer");

        if (gpiod_line_set_value(cs_line, 1))
            error_handler("gpiod_line_set_value");

        moisture_percent = (100 * (rx_buf - MIN_ADC_VALUE)) / (MAX_ADC_VALUE - MIN_ADC_VALUE);

        time_t t = time(NULL);
        struct tm *tm = localtime(&t);
        printf("Moisture: %d%% at %02d:%02d:%02d\n", moisture_percent, tm->tm_hour, tm->tm_min, tm->tm_sec);

        sleep(READ_INTERVAL);
    }

    cleanup();

    return 0;
}

