code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <linux/spi/spidev.h>
#include <sys/ioctl.h>
#include <libgpiod.h>
#include <time.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CS_GPIO 8
#define CHANNELS 4
#define VREF 3300

struct gpiod_line *cs_line;
struct gpiod_chip *chip;
int spi_fd;
FILE *file;

void exit_handler(int signum) {
    fclose(file);
    gpiod_line_release(cs_line);
    close(spi_fd);
    exit(0);
}

int main() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    cs_line = gpiod_chip_get_line(chip, CS_GPIO);
    if (!cs_line) {
        perror("Failed to get GPIO line");
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "cs_line", 1)) {
        perror("Failed to request GPIO line as output");
        return 1;
    }

    struct spi_ioc_transfer xfer[CHANNELS];
    uint16_t tx[CHANNELS], rx[CHANNELS];
    for (int i = 0; i < CHANNELS; i++) {
        tx[i] = (1 << 8) | i;
        xfer[i].tx_buf = (unsigned long) &tx[i];
        xfer[i].rx_buf = (unsigned long) &rx[i];
        xfer[i].len = 2;
        xfer[i].speed_hz = 1000000;
        xfer[i].delay_usecs = 0;
        xfer[i].bits_per_word = 0;
        xfer[i].cs_change = (i != (CHANNELS - 1));
    }

    file = fopen("environmental_data.csv", "w");
    if (!file) {
        perror("Failed to open file");
        return 1;
    }

    signal(SIGINT, exit_handler);
    signal(SIGTERM, exit_handler);

    while (1) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(CHANNELS), xfer) < 0) {
            perror("SPI message failed");
            return 1;
        }

        for (int i = 0; i < CHANNELS; i++) {
            int val = ((rx[i] & 0x3F00) >> 8) | ((rx[i] & 0x00FF) << 8);
            double voltage = (double) val * VREF / 1023.0;
            time_t t = time(NULL);
            struct tm *tmp = localtime(&t);
            char buffer[80];
            strftime(buffer, 80, "%d/%m/%Y %H:%M:%S", tmp);
            fprintf(file, "%s, %.3f\n", buffer, voltage);
        }

        fflush(file);
        sleep(1);
    }

    return 0;
}

