void cleanup_and_exit(int sig) {
    if (i2c_handle >= 0) {
        piI2CClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (sig) {
        printf("Exiting on signal %d\n", sig);
        exit(sig);
    }
}

void error_and_exit(const char *msg) {
    fprintf(stderr, "%s\n", msg);
    cleanup_and_exit(1);
}

int main() {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    i2c_handle = piI2C(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        error_and_exit("Failed to open I2C device");
    }

    unsigned char part_id;
    if (piI2CReadByteDirect(i2c_handle, REG_PART_ID, &part_id) < 0) {
