    }
    if (part_id != EXPECTED_PART_ID) {
        error_and_exit("Unexpected sensor Part ID");
    }

    if (piI2CWriteByteDirect(i2c_handle, REG_MODE_CONFIG, VAL_RESET) < 0 ||
        piI2CWriteByteDirect(i2c_handle, REG_MODE_CONFIG, VAL_SPO2_MODE) < 0 ||
        piI2CWriteByteDirect(i2c_handle, REG_SPO2_CONFIG, VAL_SPO2_CONFIG) < 0 ||
        piI2CWriteByteDirect(i2c_handle, REG_LED1_PA, VAL_LED_PA) < 0 ||
        piI2CWriteByteDirect(i2c_handle, REG_LED2_PA, VAL_LED_PA) < 0) {
        error_and_exit("Failed to configure sensor");
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        error_and_exit("Failed to open log file");
    }

    unsigned char data[6];
    while (1) {
        if (piI2CReadBytes(i2c_handle, REG_FIFO_DATA, sizeof(data), data) < 0) {
            error_and_exit("Failed to read sensor data");
        }

        // Compute SpO2 and heart rate here...

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        char now_str[20];
        strftime(now_str, sizeof(now_str), "%Y-%m-%dT%H:%M:%S", now_tm);

        if (spo2 < 95.0 || hr > 100.0) {
            fprintf(log_file, "%s: SpO2 = %.1f%%, HR = %.0f BPM\n", now_str, spo2, hr);
            fflush(log_file);
        }

        sleep(1);
    }

    return 0;
}

