#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define VREF 3.3
#define MAX_TRIES 3

FILE *csv_file;
int spi_handle;

void write_csv_header() {
    fprintf(csv_file, "Timestamp,Channel,Voltage\n");
}

void write_csv_data(int channel, float voltage) {
    time_t now = time(0);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%FT%TZ", gmtime(&now));
    fprintf(csv_file, "%s,%d,%.2f\n", timestamp, channel, voltage);
}

void handle_sigint(int signum) {
    spiClose(spi_handle);
    gpioTerminate();
    fclose(csv_file);
    exit(0);
}

int main() {
    int ret;
    int tries = 0;
    float voltage;
    unsigned char tx_buf[3] = {0x01, 0x00, 0x00};
    unsigned char rx_buf[3] = {0x00, 0x00, 0x00};

    signal(SIGINT, handle_sigint);

    spi_handle = spiOpen(SPI_DEVICE, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI device: %d\n", spi_handle);
        return 1;
    }

    csv_file = fopen("analog_log.csv", "w");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        return 1;
    }

    write_csv_header();

    for (int channel = 0; channel < 3; channel++) {
        tx_buf[1] = (channel << 4) | 0x08;
        for (tries = 0; tries < MAX_TRIES; tries++) {
            ret = spiXfer(spi_handle, tx_buf, rx_buf, sizeof(tx_buf) * 8);
            if (ret < 0) {
                fprintf(stderr, "SPI transfer failed: %d\n", ret);
                continue;
            }
            voltage = ((rx_buf[1] & 0x03) << 8 | rx_buf[2]) * VREF / 1023.0;
            write_csv_data(channel, voltage);
            break;
        }
        if (tries == MAX_TRIES) {
            fprintf(stderr, "Failed to read channel %d after %d tries\n", channel, MAX_TRIES);
        }
    }

    fclose(csv_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

