#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SLAVE_SELECT 0
#define GPIO_BUZZER 24
#define ADC_CHANNEL 0
#define ADC_THRESHOLD 500

int pi, spi_handle;
volatile sig_atomic_t stop = 0;

void sig_handler(int signo) {
    if (signo == SIGINT) {
        stop = 1;
    }
}

void cleanup() {
    if (spi_handle >= 0) {
        if (spiClose(spi_handle) < 0) {
            fprintf(stderr, "Failed to close SPI handle: %s\n", pigpio_error());
        }
    }
    if (gpioWrite(GPIO_BUZZER, 0) < 0) {
        fprintf(stderr, "Failed to reset GPIO state: %s\n", pigpio_error());
    }
    if (gpioTerminate() < 0) {
        fprintf(stderr, "Failed to terminate GPIO: %s\n", pigpio_error());
    }
    exit(0);
}

int main() {
    signal(SIGINT, sig_handler);

    pi = gpioInitialise();
    if (pi < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SLAVE_SELECT, 1000000);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI: %s\n", pigpio_error());
        cleanup();
        return 1;
    }

    if (gpioSetMode(GPIO_BUZZER, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode: %s\n", pigpio_error());
        cleanup();
        return 1;
    }

    while (!stop) {
        int value = 0;
        char tx_buf[3] = {1, (ADC_CHANNEL << 4), 0};
        char rx_buf[3] = {0, 0, 0};

        if (spiXfer(spi_handle, tx_buf, rx_buf, 3) < 0) {
            fprintf(stderr, "Failed to read from SPI: %s\n", pigpio_error());
            cleanup();
            return 1;
        }

        value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

        if (value < ADC_THRESHOLD) {
            if (gpioWrite(GPIO_BUZZER, 0) < 0) {
                fprintf(stderr, "Failed to write GPIO: %s\n", pigpio_error());
                cleanup();
                return 1;
            }
        } else {
            if (gpioWrite(GPIO_BUZZER, 1) < 0) {
                fprintf(stderr, "Failed to write GPIO: %s\n", pigpio_error());
                cleanup();
                return 1;
            }
        }

        sleep(500);
    }

    cleanup();
    return 0;
}

