        value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

        if (value < ADC_THRESHOLD) {
            if (gpioWrite(GPIO_BUZZER, 0) < 0) {
                fprintf(stderr, "Failed to write GPIO: %s\n", pigpio_error());
                cleanup();
                return 1;
            }
        } else {
            if (gpioWrite(GPIO_BUZZER, 1) < 0) {
                fprintf(stderr, "Failed to write GPIO: %s\n", pigpio_error());
                cleanup();
                return 1;
            }
        }

        sleep(500);
    }

    cleanup();
    return 0;
