#define SAMPLE_RATE 50000
#define POLL_RATE 200000
#define LOCK_RELEASE_TIME 3000000
#define LOG_FILE "/var/log/door_events.log"

struct gpiod_line *gpio_lines[2];
struct gpiod_chip *gpio_chip;
int i2c_file_descriptor;
FILE *log_file;

void log_event(const char *event) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(log_file, "%ld.%09ld: %s\n", ts.tv_sec, ts.tv_nsec, event);
    fflush(log_file);
}

void handle_sigint(int signum) {
    gpiod_line_set_value(gpio_lines[1], 0);
    log_event("Interrupt received, de-energized relay");
    exit(0);
}

int main() {
    struct i2c_msg msgs[2];
    unsigned short data[2];
    unsigned int sample_sum = 0;
    unsigned int sample_count = 0;
    unsigned int trigger_threshold;
    unsigned int lock_release_end;
    int i;

    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    for (i = 0; i < 2; i++) {
        gpio_lines[i] = gpiod_chip_get_line(gpio_chip, i == 0 ? 27 : 17);
        if (!gpio_lines[i]) {
            perror("gpiod_chip_get_line");
            return 1;
        }

        if (gpiod_line_request_input(gpio_lines[i], "door_sensor") < 0) {
            perror("gpiod_line_request_input");
            return 1;
        }
    }

    i2c_file_descriptor = open("/dev/i2c-1", O_RDWR);
    if (i2c_file_descriptor < 0) {
        perror("open");
        return 1;
    }

    if (ioctl(i2c_file_descriptor, I2C_SLAVE, ADDR) < 0) {
        perror("ioctl");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    msgs[0].addr = ADDR;
    msgs[0].flags = 0;
    msgs[0].len = 1;
    msgs[0].buf = (unsigned char*)&data[0];
    msgs[1].addr = ADDR;
    msgs[1].flags = I2C_M_RD;
    msgs[1].len = 2;
    msgs[1].buf = (unsigned char*)&data[1];

    for (i = 0; i < 10; i++) {
        if (i2c_rdwr(i2c_file_descriptor, msgs, 2) < 0) {
            log_event("I2C read failure, continuing");
            continue;
        }

        sample_sum += data[1];
        sample_count++;
        usleep(SAMPLE_RATE);
    }

    if (sample_count > 0) {
        trigger_threshold = sample_sum / sample_count * 0.8;
    } else {
        trigger_threshold = 0;
    }

    while (1) {
        if (i2c_rdwr(i2c_file_descriptor, msgs, 2) < 0) {
            log_event("I2C read failure, continuing");
            continue;
        }

        if (data[1] < trigger_threshold) {
            gpiod_line_set_value(gpio_lines[1], 1);
            lock_release_end = clock_gettime(CLOCK_MONOTONIC, NULL) + LOCK_RELEASE_TIME;
            while (clock_gettime(CLOCK_MONOTONIC, NULL) < lock_release_end) {
                usleep(POLL_RATE);
            }
            gpiod_line_set_value(gpio_lines[1], 0);
            if (gpiod_line_get_value(gpio_lines[0]) == 0) {
                log_event("Door opened");
            } else {
                log_event("Door not opened");
            }
        }

        usleep(POLL_RATE);
    }

    fclose(log_file);
    close(i2c_file_descriptor);
    for (i = 0; i < 2; i++) {
        gpiod_line_release(gpio_lines[i]);
    }
    gpiod_chip_close(gpio_chip);

    return 0;
}

