#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <linux/spi/spidev.h>
#include <sys/ioctl.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CS_PINS 3
#define CS_PINS_GPIO {8, 7, 25}
#define SAMPLE_RATE 5

struct gpiod_line *cs_lines[CS_PINS];
struct gpiod_chip *chip;
int spi_fd;

void sig_handler(int signo) {
    for (int i = 0; i < CS_PINS; i++) {
        gpiod_line_release(cs_lines[i]);
    }
    gpiod_chip_close(chip);
    close(spi_fd);
    exit(signo);
}

int main() {
    struct sigaction sigIntHandler;
    sigIntHandler.sa_handler = sig_handler;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_flags = 0;
    sigaction(SIGINT, &sigIntHandler, NULL);
    sigaction(SIGTERM, &sigIntHandler, NULL);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        exit(EXIT_FAILURE);
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < CS_PINS; i++) {
        cs_lines[i] = gpiod_chip_get_line(chip, CS_PINS_GPIO[i]);
        if (!cs_lines[i]) {
            perror("Error getting GPIO line");
            exit(EXIT_FAILURE);
        }
        if (gpiod_line_request_output(cs_lines[i], "cs", 1)) {
            perror("Error requesting GPIO line");
            exit(EXIT_FAILURE);
        }
    }

    FILE *file = fopen("soil_moisture_log.csv", "a");
    if (!file) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }
    if (fseek(file, 0, SEEK_END) != 0 || ftell(file) == 0) {
        fprintf(file, "timestamp,sensor1,sensor2,sensor3\n");
    }

    while (1) {
        int values[CS_PINS];
        for (int i = 0; i < CS_PINS; i++) {
            gpiod_line_set_value(cs_lines[i], 0);

            uint8_t tx_buf[3] = {0x01, (0x08 | i) << 4, 0x00};
            uint8_t rx_buf[3] = {0x00, 0x00, 0x00};
            struct spi_ioc_transfer xfer = {
                .tx_buf = (uint64_t)tx_buf,
                .rx_buf = (uint64_t)rx_buf,
                .len = sizeof(tx_buf),
                .speed_hz = 1000000,
                .bits_per_word = 8,
            };
            if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
                perror("Error in SPI transfer");
                values[i] = -1;
            } else {
                values[i] = (rx_buf[1] & 0x03) << 8 | rx_buf[2];
            }

            gpiod_line_set_value(cs_lines[i], 1);
        }

        time_t t = time(NULL);
        struct tm *tmp = localtime(&t);
        char buffer[80];
        strftime(buffer, 80, "%d/%m/%Y %H:%M:%S", tmp);

        fprintf(file, "%s,%d,%d,%d\n", buffer, values[0], values[1], values[2]);
        fflush(file);

        sleep(SAMPLE_RATE);
    }

    fclose(file);
    close(spi_fd);
    for (int i = 0; i < CS_PINS; i++) {
        gpiod_line_release(cs_lines[i]);
    }
    gpiod_chip_close(chip);

    return 0;
}

