#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <getopt.h>
#include <pigpio.h>
#include <mcp3008.h>

#define GPIO_PUMP 18
#define GPIO_SPI_CS 8
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CH0 0
#define ADC_MAX 1023
#define MOISTURE_DRY 200
#define MOISTURE_WET 800
#define DEFAULT_THRESHOLD 30
#define DEFAULT_DURATION 10
#define DEFAULT_INTERVAL 60
#define LOG_FILE "irrigation.log"
#define RETRY_COUNT 3

static int moisture_threshold = DEFAULT_THRESHOLD;
static int pump_duration = DEFAULT_DURATION;
static int sleep_interval = DEFAULT_INTERVAL;
static FILE *log_file;

static void log_message(const char *message) {
    time_t now = time(NULL);
    fprintf(log_file, "%s [%s]\n", ctime(&now), message);
    fflush(log_file);
}

static void handle_signal(int signum) {
    gpioWrite(GPIO_PUMP, 0);
    spiClose(SPI_CHANNEL);
    piGpioTerminate();
    exit(signum);
}

int main(int argc, char *argv[]) {
    int opt, ret, moisture, adc_value;
    char buf[256];

    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                moisture_threshold = atoi(optarg);
                break;
            case 'd':
                pump_duration = atoi(optarg);
                break;
            case 's':
                sleep_interval = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s sleep_interval]\n", argv[0]);
                exit(1);
        }
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        exit(1);
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (piGpioInitialise() < 0) {
        log_message("Failed to initialize pigpio");
        exit(1);
    }

    if (gpioCfgIntr(GPIO_PUMP, 0) < 0) {
        log_message("Failed to configure GPIO interrupt");
        exit(1);
    }

    if (spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE) < 0) {
        log_message("Failed to open SPI channel");
        exit(1);
    }

    if (gpioWrite(GPIO_PUMP, 0) < 0) {
        log_message("Failed to deactivate pump");
        exit(1);
    }

    while (1) {
        for (int i = 0; i < RETRY_COUNT; i++) {
            if ((adc_value = mcp3008Read(SPI_CHANNEL, GPIO_SPI_CS, ADC_CH0)) >= 0) {
                moisture = (adc_value * 100) / ADC_MAX;
                sprintf(buf, "Moisture: %d%%", moisture);
                log_message(buf);

                if (moisture < moisture_threshold) {
                    if (gpioWrite(GPIO_PUMP, 1) < 0) {
                        log_message("Failed to activate pump");
                        exit(1);
                    }

                    sprintf(buf, "Pump activated for %d seconds", pump_duration);
                    log_message(buf);
                    sleep(pump_duration);

                    if (gpioWrite(GPIO_PUMP, 0) < 0) {
                        log_message("Failed to deactivate pump");
                        exit(1);
                    }

                    log_message("Pump deactivated");
                }

                break;
            } else {
                sprintf(buf, "Failed to read ADC value, retry %d of %d", i + 1, RETRY_COUNT);
                log_message(buf);
            }
        }

        sleep(sleep_interval);
    }

    return 0;
}

