#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <spi.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SAMPLE_INTERVAL_MS 10
#define EMA_ALPHA 0.6
#define THRESHOLD_MARGIN 0.2
#define LOG_FILE "/var/log/sound_events.log"

FILE *log_file;
spi_t spi;
double ema = 0;
int running = 1;

void handle_signal(int signum) {
    running = 0;
}

void log_peak(int value) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(log_file, "%s %d\n", timestamp, value);
    fflush(log_file);
}

int main() {
    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        fclose(log_file);
        return 1;
    }

    spi = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi < 0) {
        fprintf(stderr, "Failed to open SPI channel %d at %d Hz: %d\n", SPI_CHANNEL, SPI_SPEED, spi);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        unsigned char tx[4] = {0x01, 0x80, 0x00, 0x00};
        unsigned char rx[4];

        if (spiXfer(spi, tx, rx, sizeof(tx)) != sizeof(tx)) {
            fprintf(stderr, "SPI transfer failed: %d\n", spi);
            spiClose(spi);
            gpioTerminate();
            fclose(log_file);
            return 1;
        }

        int value = (rx[1] & 0x0F) << 8 | rx[2];
        double diff = value - ema;

        ema = ema * EMA_ALPHA + value * (1 - EMA_ALPHA);

        if (diff > ema * THRESHOLD_MARGIN) {
            log_peak(value);
        }

        msleep(SAMPLE_INTERVAL_MS);
    }

    spiClose(spi);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

