#include <linux/i2c.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define ADDR 0x48
#define DELAY_MS 100

static int fd;

void sigint_handler(int signum) {
    close(fd);
    exit(0);
}

int main() {
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    if (ioctl(fd, I2C_SLAVE, ADDR) < 0) {
        perror("ioctl");
        exit(1);
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        // Perform a dummy read
        unsigned char dummy;
        if (write(fd, &dummy, 1) != 1) {
            perror("write");
            exit(1);
        }
        if (read(fd, &dummy, 1) != 1) {
            perror("read");
            exit(1);
        }

        // Read the actual value
        unsigned char value;
        if (write(fd, &value, 1) != 1) {
            perror("write");
            exit(1);
        }
        if (read(fd, &value, 1) != 1) {
            perror("read");
            exit(1);
        }

        printf("%d\n", value);

        usleep(DELAY_MS * 1000);
    }

    return 0;
}

