#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <adc1115.h>

#define ADC_I2C_BUS 1
#define ADC_I2C_ADDR 0x48
#define ADC_CHANNEL 0
#define GAUSS_THRESHOLD 500
#define GPIO_SHUTDOWN 27

static int pi_handle;
static int adc_handle;
static double buffer[10];
static int buffer_index = 0;
static int shutdown = 0;

static void handle_shutdown(int signum) {
    shutdown = 1;
}

static void log_error(const char *msg) {
    syslog(LOG_ERR, "%s", msg);
}

static void log_info(const char *msg) {
    syslog(LOG_INFO, "%s", msg);
}

static void log_and_exit(const char *msg) {
    log_error(msg);
    exit(EXIT_FAILURE);
}

static void check_shutdown() {
    if (shutdown) {
        if (pigpio_i2c_close(adc_handle) != 0) {
            log_error("Failed to close I2C handle");
        }
        if (gpio_write(GPIO_SHUTDOWN, 0) != 0) {
            log_error("Failed to write GPIO");
        }
        if (gpio_terminate() != 0) {
            log_error("Failed to terminate pigpio");
        }
        closelog();
        exit(EXIT_SUCCESS);
    }
}

int main() {
    openlog("honeywell_ss49e", LOG_CONS | LOG_PERROR, LOG_USER);

    if (gpio_initialise() != 0) {
        log_and_exit("Failed to initialize pigpio");
    }
    pi_handle = gpio_initialise();

    if (gpio_set_mode(GPIO_SHUTDOWN, PI_OUTPUT) != 0) {
        log_and_exit("Failed to set GPIO mode");
    }

    adc_handle = pigpio_i2c_open(ADC_I2C_BUS, ADC_I2C_ADDR);
    if (adc_handle < 0) {
        log_and_exit("Failed to open I2C handle");
    }

    if (gpio_write(GPIO_SHUTDOWN, 1) != 0) {
        log_and_exit("Failed to write GPIO");
    }

    signal(SIGINT, handle_shutdown);
    signal(SIGTERM, handle_shutdown);

    while (1) {
        check_shutdown();

        int16_t raw_value;
        if (adc1115_read(adc_handle, ADC_CHANNEL, &raw_value) != 0) {
            log_error("Failed to read ADC");
            continue;
        }

        double voltage = adc1115_convert_to_voltage(raw_value);
        if (voltage < 0 || voltage > 3.3) {
            log_error("Invalid voltage reading");
            continue;
        }

        double field_strength = (voltage - 2.5) / 1.4;
        log_info("Field strength: %f Gauss");

        buffer[buffer_index] = field_strength;
        buffer_index = (buffer_index + 1) % sizeof(buffer) / sizeof(buffer[0]);

        double average = 0;
        for (int i = 0; i < sizeof(buffer) / sizeof(buffer[0]); i++) {
            average += buffer[i];
        }
        average /= sizeof(buffer) / sizeof(buffer[0]);

        if (average > GAUSS_THRESHOLD) {
            if (gpio_write(GPIO_SHUTDOWN, 0) != 0) {
                log_error("Failed to write GPIO");
            }
        }
    }

    return 0;
}

