#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define PUMP_GPIO 18
#define WATERING_THRESHOLD 300
#define WATERING_DURATION 10000
#define SAMPLE_INTERVAL 60000
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_DEVICE "/dev/spidev0.0"
#define LOG_FILE "watering_events.txt"

int spi_handle;
int gpio_handle;
volatile sig_atomic_t stop;

void start_pump(void) {
    gpioWrite(gpio_handle, PUMP_GPIO, 1);
}

void stop_pump(void) {
    gpioWrite(gpio_handle, PUMP_GPIO, 0);
}

void log_event(int moisture) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char buffer[80];
    strftime(buffer, sizeof(buffer), "%d-%m-%Y %H:%M:%S", timeinfo);
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        printf("Error opening log file\n");
        return;
    }
    fprintf(file, "%s, %d\n", buffer, moisture);
    fclose(file);
}

void handle_error(const char *message) {
    printf("%s\n", message);
    stop_pump();
    gpioClose(gpio_handle);
    exit(EXIT_FAILURE);
}

void signal_handler(int signum) {
    stop = 1;
}

int main(void) {
    gpio_handle = gpioOpen(0);
    if (gpio_handle < 0) {
        handle_error("Error initializing GPIO");
    }

    spi_handle = spiOpen(SPI_DEVICE, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        handle_error("Error initializing SPI");
    }

    gpioSetMode(gpio_handle, PUMP_GPIO, PI_OUTPUT);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop) {
        start_pump();
        msleep(WATERING_DURATION);
        stop_pump();

        int adc_value = adcRead(spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            handle_error("Error reading ADC");
        }

        log_event(adc_value);

        if (adc_value < WATERING_THRESHOLD) {
            printf("Soil moisture level low, starting pump\n");
        } else {
            printf("Soil moisture level normal\n");
        }

        msleep(SAMPLE_INTERVAL);
    }

    stop_pump();
    gpioClose(gpio_handle);
    spiClose(spi_handle);

    return 0;
}

