#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_FULL_SCALE 1023
#define RAIN_FULL_SCALE 10
#define RETRY_DELAY 1000

static int pi_handle = 0;
static int spi_handle = -1;

void sigint_handler(int signo) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (pi_handle > 0) {
        gpioTerminate();
    }
    exit(0);
}

int main() {
    pi_handle = gpioInitialise();
    if (pi_handle <= 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(-pi_handle));
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(-spi_handle));
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        int data[3] = {0x01, 0x80, 0x00};
        int result = spiXfer(spi_handle, data, data, 3);
        if (result < 0) {
            fprintf(stderr, "SPI transfer failed: %s\n", strerror(-result));
            sleep(RETRY_DELAY / 1000);
            continue;
        }

        int raw_adc = (data[1] & 0x03) << 8 | data[2];
        int rain_intensity = (raw_adc * RAIN_FULL_SCALE + ADC_FULL_SCALE / 2) / ADC_FULL_SCALE;

        time_t now = time(NULL);
        struct tm *local_time = localtime(&now);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", local_time);

        printf("%s: Raw ADC: %d, Rain intensity: %d\n", time_str, raw_adc, rain_intensity);

        sleep(1);
    }

    return 0;
}

