        int raw_adc = (data[1] & 0x03) << 8 | data[2];
        int rain_intensity = (raw_adc * RAIN_FULL_SCALE + ADC_FULL_SCALE / 2) / ADC_FULL_SCALE;

        time_t now = time(NULL);
        struct tm *local_time = localtime(&now);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", local_time);

        printf("%s: Raw ADC: %d, Rain intensity: %d\n", time_str, raw_adc, rain_intensity);

        sleep(1);
    }

    return 0;
}
