#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <ads1115.h>

#define ADDR 0x48
#define GAIN 4.096
#define AIN0 0
#define I2C_BUS 1
#define LED_PIN 17
#define DEFAULT_THRESHOLD 100.0

volatile int stop = 0;
double threshold = DEFAULT_THRESHOLD;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        stop = 1;
        gpioWrite(LED_PIN, 0);
        piGpioTerminate();
        printf("Exiting...\n");
    }
}

void blink(int times) {
    for (int i = 0; i < times; i++) {
        gpioWrite(LED_PIN, 1);
        sleep(50);
        gpioWrite(LED_PIN, 0);
        sleep(50);
    }
}

int main(int argc, char *argv[]) {
    if (argc > 1) {
        threshold = atof(argv[1]);
    }

    if (piGpioInitialise() < 0) {
        printf("Failed to initialize pigpio.\n");
        return -1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);

    int fd = ads1115Open(I2C_BUS, ADDR, AIN0, GAIN);
    if (fd < 0) {
        printf("Failed to open ADS1115.\n");
        piGpioTerminate();
        return -1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (!stop) {
        double val = ads1115Read(fd);
        if (val < 0) {
            printf("Failed to read ADS1115.\n");
            blink(3);
            continue;
        }

        double field = val * 1000.0;
        printf("Magnetic field: %.2f Gauss\n", field);

        if (field > threshold) {
            blink(10);
        }

        sleep(100);
    }

    return 0;
}

