#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <spi.h>
#include <paho_mqtt/MQTTClient.h>

#define GPIO_PUMP_CONTROL 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define HL69_ADC_CHANNEL 0
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define MQTT_TOPIC_PUMP_CONTROL "pump_control"
#define MQTT_TOPIC_SOIL_MOISTURE "soil_moisture"
#define MQTT_BROKER "tcp://mqtt.eclipse.org:1883"
#define MQTT_CLIENT_ID "soil_moisture_sensor"

static int spi_handle;
static MQTTClient mqtt_client;
static volatile sig_atomic_t stop = 0;

static void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        stop = 1;
    }
}

static void mqtt_command_callback(char* topic, MQTTClient_message* message) {
    if (strcmp(topic, MQTT_TOPIC_PUMP_CONTROL) == 0) {
        if (strcmp(message->payload, "pump_on") == 0) {
            if (gpioWrite(GPIO_PUMP_CONTROL, 1) != 0) {
                syslog(LOG_ERR, "Failed to write GPIO %d", GPIO_PUMP_CONTROL);
            }
        } else if (strcmp(message->payload, "pump_off") == 0) {
            if (gpioWrite(GPIO_PUMP_CONTROL, 0) != 0) {
                syslog(LOG_ERR, "Failed to write GPIO %d", GPIO_PUMP_CONTROL);
            }
        }
    }
}

int main() {
    openlog("soil_moisture_sensor", LOG_PERROR, LOG_USER);
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        syslog(LOG_ERR, "Failed to open SPI channel %d", SPI_CHANNEL);
        return 1;
    }

    if (gpioWrite(GPIO_PUMP_CONTROL, 0) != 0) {
        syslog(LOG_ERR, "Failed to write GPIO %d", GPIO_PUMP_CONTROL);
        return 1;
    }

    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    MQTTClient_message pub_msg = MQTTClient_message_initializer;
    MQTTClient_subscribeOptions sub_opts = MQTTClient_subscribeOptions_initializer;

    MQTTClient_create(&mqtt_client, MQTT_BROKER, MQTT_CLIENT_ID,
                      MQTTCLIENT_PERSISTENCE_NONE, 0);
    conn_opts.username = NULL;
    conn_opts.password = NULL;
    conn_opts.keepAliveInterval = 60;
    conn_opts.cleansession = 1;

    if (MQTTClient_connect(mqtt_client, &conn_opts) != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker");
        return 1;
    }

    sub_opts.qos = 1;
    sub_opts.nl = 0;
    sub_opts.rap = 0;
    sub_opts.rhq = 0;

    if (MQTTClient_subscribe(mqtt_client, MQTT_TOPIC_PUMP_CONTROL, &sub_opts) != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "Failed to subscribe to MQTT topic %s", MQTT_TOPIC_PUMP_CONTROL);
        return 1;
    }

    while (!stop) {
        char payload[10];
        int adc_value = spiRead(spi_handle, HL69_ADC_CHANNEL);
        if (adc_value < 0) {
            syslog(LOG_ERR, "Failed to read ADC");
            continue;
        }

        int moisture = adc_value * 100 / 1023;
        sprintf(payload, "%d", moisture);
        pub_msg.payload = payload;
        pub_msg.payloadlen = strlen(payload);
        pub_msg.qos = 1;
        pub_msg.retained = 0;

        if (MQTTClient_publish(mqtt_client, MQTT_TOPIC_SOIL_MOISTURE, &pub_msg) != MQTTCLIENT_SUCCESS) {
            syslog(LOG_ERR, "Failed to publish to MQTT topic %s", MQTT_TOPIC_SOIL_MOISTURE);
        }

        if (moisture < MOISTURE_THRESHOLD_LOW) {
            if (gpioWrite(GPIO_PUMP_CONTROL, 1) != 0) {
                syslog(LOG_ERR, "Failed to write GPIO %d", GPIO_PUMP_CONTROL);
            }
        } else if (moisture > MOISTURE_THRESHOLD_HIGH) {
            if (gpioWrite(GPIO_PUMP_CONTROL, 0) != 0) {
                syslog(LOG_ERR, "Failed to write GPIO %d", GPIO_PUMP_CONTROL);
            }
        }
    }

    MQTTClient_disconnect(mqtt_client, 10000);
    MQTTClient_destroy(&mqtt_client);
    spiClose(spi_handle);
    gpioTerminate();

    closelog();
    return 0;
}

