#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define MCP3008_CH0_CMD 0x01

static int spi_fd = -1;

static void sigint_handler(int signum) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    exit(0);
}

int main(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open spi device");
        return EXIT_FAILURE;
    }

    struct spi_ioc_transfer xfer[2];
    memset(xfer, 0, sizeof(xfer));

    xfer[0].tx_buf = (unsigned long) &MCP3008_CH0_CMD;
    xfer[0].len = 1;
    xfer[0].cs_change = 1;

    xfer[1].rx_buf = (unsigned long) malloc(2);
    xfer[1].len = 2;

    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(2), xfer);
    if (ret < 0) {
        perror("spi message");
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(2), xfer);
        if (ret < 0) {
            perror("spi message");
            return EXIT_FAILURE;
        }

        unsigned short raw = ((*(unsigned short*)xfer[1].rx_buf) >> 6) & 0x3FF;
        printf("Raw value: %hu, Voltage: %.3f V\n", raw, raw * 3.3 / 1024.0);

        usleep(500000);
    }

    close(spi_fd);
    free((void*)xfer[1].rx_buf);

    return EXIT_SUCCESS;
}

