#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_MAX_SPEED_HZ 1000000
#define SPI_BITS_PER_WORD 8
#define ADC_CHANNEL 0
#define PWM_FREQ 100
#define PWM_DUTY_CYCLE_MAX 100
#define NOISE_THRESHOLD 500
#define LOG_FILE "vibration_log.txt"

volatile sig_atomic_t stop = 0;
int spi_fd = -1;

void shutdown_handler(int signum) {
    stop = 1;
}

void log_event(const char* event, int value) {
    FILE* f = fopen(LOG_FILE, "a");
    if (f == NULL) {
        perror("fopen");
        return;
    }

    time_t t = time(NULL);
    struct tm* tm = localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(f, "%s: %s - Value: %d\n", timestamp, event, value);
    fclose(f);
}

int main() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        return 1;
    }

    int ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("ioctl");
        return 1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_MAX_SPEED_HZ);
    if (ret < 0) {
        perror("ioctl");
        return 1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        perror("ioctl");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return 1;
    }

    gpioSetPWMfrequency(17, PWM_FREQ);
    gpioSetPWMfrequency(27, PWM_FREQ);

    signal(SIGINT, shutdown_handler);
    signal(SIGTERM, shutdown_handler);

    while (!stop) {
        uint8_t tx_buf[2] = { (1 << 6) | ADC_CHANNEL, 0 };
        uint8_t rx_buf[2] = { 0, 0 };

        ret = write(spi_fd, tx_buf, sizeof(tx_buf));
        if (ret < 0) {
            perror("write");
            continue;
        }

        ret = read(spi_fd, rx_buf, sizeof(rx_buf));
        if (ret < 0) {
            perror("read");
            continue;
        }

        int adc_value = ((rx_buf[0] & 0x0F) << 8) | rx_buf[1];

        if (adc_value > NOISE_THRESHOLD) {
            int pwm_duty_cycle = (adc_value - NOISE_THRESHOLD) * PWM_DUTY_CYCLE_MAX / (1023 - NOISE_THRESHOLD);
            gpioSetPWMdutycycle(17, pwm_duty_cycle);
            gpioSetPWMdutycycle(27, pwm_duty_cycle);
            log_event("Vibration started", pwm_duty_cycle);
        } else {
            gpioSetPWMdutycycle(17, 0);
            gpioSetPWMdutycycle(27, 0);
            log_event("Vibration stopped", 0);
        }

        usleep(10000);
    }

    gpioSetPWMdutycycle(17, 0);
    gpioSetPWMdutycycle(27, 0);

    close(spi_fd);
    gpioTerminate();

    return 0;
}

