#define SPI_DEV "/dev/spidev0.0"
#define ADC_CHANNEL 0
#define LOG_FILE "tamper_log.csv"

int i2c_fd, spi_fd, log_fd;

void cleanup_and_exit(int signum) {
    close(i2c_fd);
    close(spi_fd);
    fdatasync(log_fd);
    close(log_fd);
    exit(0);
}

int main() {
    int ret;
    struct sigaction act;
    act.sa_handler = cleanup_and_exit;
    sigemptyset(&act.sa_mask);
    act.sa_flags = 0;
    sigaction(SIGINT, &act, NULL);
    sigaction(SIGTERM, &act, NULL);

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("open i2c device");
        exit(1);
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("set i2c slave addr");
        exit(1);
    }

    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("open spi device");
        exit(1);
    }

    log_fd = open(LOG_FILE, O_CREAT | O_WRONLY | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("open log file");
        exit(1);
    }

    fprintf(log_fd, "timestamp,sound_level_db,light_level_lux,error_code\n");

    while (1) {
        int sound_level_db = 0, light_level_lux = 0, error_code = 0;
        char buf[2];

        // read sound level
        // ...

        // read light level
        ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
        if (ret < 0) {
            error_code = errno;
        } else {
            ret = write(i2c_fd, "\x11", 1);
            if (ret < 0) {
                error_code = errno;
            } else {
                usleep(180000);
                ret = read(i2c_fd, buf, 2);
                if (ret < 0) {
                    error_code = errno;
                } else {
                    light_level_lux = (buf[0] << 8) | buf[1];
                }
            }
        }

        // log data
        time_t t = time(NULL);
        struct tm *tm = localtime(&t);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
        fprintf(log_fd, "%s,%d,%d,%d\n", timestamp, sound_level_db, light_level_lux, error_code);
        fflush(log_fd);

        sleep(5);
    }

    return 0;
}

