#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define MOISTURE_THRESHOLD 30
#define GPIO_PUMP 17

int pi, spi_handle;
volatile int stop = 0;

void shutdown_handler(int signum) {
    stop = 1;
    gpioWrite(GPIO_PUMP, 0);
    spiClose(spi_handle);
    gpioTerminate();
    printf("Shutdown complete.\n");
    exit(0);
}

int main() {
    struct sigaction action;
    action.sa_handler = shutdown_handler;
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    pi = gpioInitialise();
    if (pi < 0) {
        printf("Error initializing pigpio: %d\n", pi);
        return 1;
    }

    gpioSetMode(GPIO_PUMP, PI_OUTPUT);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        printf("Error opening SPI device: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    while (!stop) {
        int tries = 0;
        int value;
        while (tries < 3 && (value = spiRead(spi_handle, ADC_CHANNEL)) < 0) {
            tries++;
            printf("SPI read failed, retrying...\n");
        }

        if (value < 0) {
            printf("Too many failed SPI reads, shutting down.\n");
            shutdown_handler(0);
        }

        int moisture = value * 100 / 1023;
        printf("Moisture: %d%%\n", moisture);

        if (moisture < MOISTURE_THRESHOLD) {
            gpioWrite(GPIO_PUMP, 1);
        } else {
            gpioWrite(GPIO_PUMP, 0);
        }

        sleep(60);
    }

    shutdown_handler(0);
    return 0;
