#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <spi.h>

#define ADC_CHANNEL 0
#define CO2_SLOPE 0.5
#define CO2_INTERCEPT -50
#define CO2_ALARM 700
#define FAN_GPIO 18

FILE *log_file;
int spi_handle;

void log_data(int co2_ppm, int fan_state) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%d,%d\n", timestamp, co2_ppm, fan_state);
    fflush(log_file);
}

void handle_signal(int signum) {
    // Turn off fan and clean up
    gpioWrite(FAN_GPIO, 0);
    spiClose(spi_handle);
    piGpioTerminate();
    fclose(log_file);
    exit(0);
}

int main() {
    if (piGpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    spi_handle = spiOpen("/dev/spidev0.0", 1000000, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI: %d\n", spi_handle);
        return 1;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    log_file = fopen("air_quality.log", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        char tx_buf[2] = {0x00, 0x00};
        tx_buf[0] = (0x1 << 7) | (ADC_CHANNEL << 4);
        char rx_buf[2];
        if (spiXfer(spi_handle, tx_buf, rx_buf, 16) < 0) {
            fprintf(stderr, "SPI transfer error\n");
            continue;
        }

        int adc_value = ((rx_buf[0] & 0x03) << 8) | rx_buf[1];
        if (adc_value < 0 || adc_value > 1023) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            continue;
        }

