#include <gpiod.h>
#include <spi0.h>

#define ADC_CHANNEL 0
#define SPI_CLOCK 1000000
#define PROXIMITY_THRESHOLD 20
#define POLL_INTERVAL 100000
#define DEBOUNCE_DELAY 1000000
#define LOG_FILE "door_events.log"

struct gpiod_line *gpio_line;
struct gpiod_chip *gpio_chip;
struct spi0_device *spi_device;
FILE *log_file;

void cleanup_and_exit(int signum) {
    if (gpio_line)
        gpiod_line_release(gpio_line);
    if (gpio_chip)
        gpiod_chip_close(gpio_chip);
    if (spi_device)
        spi0_close(spi_device);
    if (log_file)
        fclose(log_file);
    exit(signum);
}

int main() {
    int ret;
    unsigned int adc_value;
    time_t last_trigger = 0;

    signal(SIGINT, cleanup_and_exit);

    gpio_chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!gpio_chip) {
        perror("gpiod_chip_open_by_name");
        cleanup_and_exit(-1);
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, 17);
    if (!gpio_line) {
        perror("gpiod_chip_get_line");
        cleanup_and_exit(-1);
    }

    ret = gpiod_line_request_output(gpio_line, "door_sensor", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        cleanup_and_exit(-1);
    }

    spi_device = spi0_open(0, ADC_CHANNEL, SPI_CLOCK);
    if (!spi_device) {
        perror("spi0_open");
        cleanup_and_exit(-1);
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        cleanup_and_exit(-1);
    }

    while (1) {
        adc_value = spi0_read(spi_device);
        if (adc_value == SPI0_ERROR) {
            fprintf(log_file, "%s: SPI error\n", ctime(&last_trigger));
            continue;
        }

        if (adc_value < PROXIMITY_THRESHOLD && difftime(time(NULL), last_trigger) > DEBOUNCE_DELAY) {
            ret = gpiod_line_set_value(gpio_line, 1);
            if (ret < 0) {
                perror("gpiod_line_set_value");
                cleanup_and_exit(-1);
            }

            last_trigger = time(NULL);
            fprintf(log_file, "%s: Proximity detected, relay energized\n", ctime(&last_trigger));
        }

        usleep(POLL_INTERVAL);
    }

    cleanup_and_exit(0);
}

