#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define ADC_CHANNELS 3
#define ADC_COMMAND 0x01
#define ADC_CLOCK 1000000
#define ADC_MODE 0
#define PWM_FREQ 100
#define PWM_RANGE 100
#define GPIO_VALVE 17
#define GPIO_ADC 8
#define LOG_FILE "irrigation.log"

FILE *log_file;
int spi_handle;

void shutdown_handler(int signum) {
    printf("Shutting down...\n");
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main() {
    int init_status = gpioInitialise();
    if (init_status < 0) {
        printf("Error initializing pigpio: %d\n", init_status);
        return 1;
    }

    spi_handle = spiOpen(GPIO_ADC, ADC_CLOCK, ADC_MODE);
    if (spi_handle < 0) {
        printf("Error opening SPI: %d\n", spi_handle);
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        printf("Error opening log file\n");
        return 1;
    }

    signal(SIGINT, shutdown_handler);
    signal(SIGTERM, shutdown_handler);

    gpioSetPWMfrequency(GPIO_VALVE, PWM_FREQ);
    gpioSetPWMrange(GPIO_VALVE, PWM_RANGE);

    while (1) {
        int adc_values[ADC_CHANNELS];
        int valid_channels = 0;
        int total_adc = 0;
        for (int i = 0; i < ADC_CHANNELS; i++) {
            int command = ADC_COMMAND << 2 | i;
            int result = spiXfer(spi_handle, &command, sizeof(command), &adc_values[i], sizeof(adc_values[i]));
            if (result >= 0) {
                total_adc += adc_values[i];
                valid_channels++;
            } else {
                printf("Error reading ADC: %d\n", result);
            }
        }

        if (valid_channels > 0) {
            int average_adc = total_adc / valid_channels;
            int pwm_duty = PWM_RANGE - (average_adc * PWM_RANGE / 1023);
            gpioSetPWMdutycycle(GPIO_VALVE, pwm_duty);

            time_t now = time(NULL);
            struct tm *timeinfo = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            fprintf(log_file, "%s, %d, %d, %d, %d, %d\n", timestamp, adc_values[0], adc_values[1], adc_values[2], average_adc, pwm_duty);
            fflush(log_file);
        }

        sleep(5);
    }

    return 0;
}

