#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_RETRIES 5

volatile sig_atomic_t stop = 0;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        stop = 1;
    }
}

int main() {
    int pi = pigpio_start();
    if (pi < 0) {
        printf("Failed to connect to pigpio daemon.\n");
        return 1;
    }

    int spi_handle = spi_open(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        printf("Failed to open SPI channel.\n");
        pigpio_stop(pi);
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    FILE *file = fopen("soil_data.txt", "a");
    if (file == NULL) {
        printf("Failed to open soil_data.txt for writing.\n");
        spi_close(spi_handle);
        pigpio_stop(pi);
        return 1;
    }

    while (!stop) {
        unsigned char cmd[3] = {0x01, 0x80, 0x00};
        unsigned char res[2] = {0x00, 0x00};

        int retries = 0;
        int success = 0;

        while (retries < SPI_RETRIES && !success) {
            int err = spi_xfer(spi_handle, cmd, res, sizeof(cmd));
            if (err < 0) {
                printf("SPI transfer failed. Retrying...\n");
                sleep(1 << retries);
                retries++;
            } else {
                success = 1;
            }
        }

        if (!success) {
            fprintf(file, "%s ERROR: SPI communication failed after %d retries.\n",
                    ctime(time(NULL)), SPI_RETRIES);
            continue;
        }

        int adc_value = (res[0] << 8) | res[1];
        if (adc_value < 0 || adc_value > 1023) {
            fprintf(file, "%s ERROR: Invalid ADC value %d.\n", ctime(time(NULL)), adc_value);
            continue;
        }

        // Convert ADC value to soil moisture percentage.
        // This depends on the specific sensor and its datasheet.
        // For YL-69, the ADC value is inversely proportional to soil moisture.
        // Assuming the ADC value 0 corresponds to 100% moisture and 1023 to 0%,
        // the formula is simply:
        //   moisture = 100 - (adc_value / 10.23)
        double moisture = 100 - (adc_value / 10.23);

        fprintf(file, "%s Moisture: %.2f%%\n", ctime(time(NULL)), moisture);
        sleep(5);
    }

    fclose(file);
    spi_close(spi_handle);
    pigpio_stop(pi);

    return 0;
}

