#define SPI_DEVICE "/dev/spidev0.0"
#define CHANNEL 0
#define MAX_TRIES 3

struct gpiod_chip *chip;
struct gpiod_line *line;
FILE *file;
int spi_fd;

void cleanup_and_exit(int signum) {
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(file);
    close(spi_fd);
    exit(0);
}

int main() {
    struct spi_ioc_transfer xfer[2];
    uint8_t tx[3], rx[3];
    uint16_t adc_value, ppm;
    int tries, res;

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, 8);
    if (!line) {
        perror("Failed to get GPIO line");
        return 1;
    }

    res = gpiod_line_request_output(line, "main", 0);
    if (res < 0) {
        perror("Failed to request GPIO line");
        return 1;
    }

    file = fopen("alcohol_log.txt", "w");
    if (!file) {
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        tx[0] = 0x01;
        tx[1] = (CHANNEL << 4) | 0x80;
        tx[2] = 0x00;

        memset(xfer, 0, sizeof(xfer));
        xfer[0].tx_buf = (unsigned long)tx;
        xfer[0].len = 3;
        xfer[0].speed_hz = 1000000;
        xfer[0].bits_per_word = 8;
        xfer[0].cs_change = 1;
        xfer[1].rx_buf = (unsigned long)rx;
        xfer[1].len = 2;
        xfer[1].speed_hz = 1000000;
        xfer[1].bits_per_word = 8;
        xfer[1].cs_change = 1;

        tries = 0;
        while (tries < MAX_TRIES) {
            res = ioctl(spi_fd, SPI_IOC_MESSAGE(2), xfer);
            if (res < 0) {
                perror("Failed to read from SPI device");
                tries++;
                usleep(100000);
                continue;
            }
            break;
        }

        if (tries == MAX_TRIES) {
            fprintf(file, "%s ADC read error: Could not read from SPI device\n",
                    asctime(gmtime(&time(NULL))));
            continue;
        }

        adc_value = ((rx[1] & 0x03) << 8) | rx[2];
        if (adc_value == 0 || adc_value == 1023) {
            fprintf(file, "%s ADC read error: Sensor not present\n",
                    asctime(gmtime(&time(NULL))));
            continue;
        }

        ppm = (adc_value * 0.5) - 10.0;
        fprintf(file, "%s PPM: %d\n", asctime(gmtime(&time(NULL))), ppm);

        if (ppm > 50)
            fprintf(file, "%s Alcohol detected! Limit exceeded.\n",
                    asctime(gmtime(&time(NULL))));
        else if (ppm < 20)
            fprintf(file, "%s Sobriety confirmed.\n",
                    asctime(gmtime(&time(NULL))));
        else
            fprintf(file, "%s Alcohol level within acceptable range.\n",
                    asctime(gmtime(&time(NULL))));

        sleep(1);
    }

    return 0;
}

