#include <stdlib.h>
#include <math.h>
#include <signal.h>
#include <pigpio.h>

#define MIN_SPEED 50
#define MAX_SPEED 255
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_CE 0
#define ADC_CHANNELS 2
#define MOTOR1_EN 18
#define MOTOR1_DIR 23
#define MOTOR2_EN 24
#define MOTOR2_DIR 25

static int pi;
static int spi;
static int adc_values[ADC_CHANNELS];
static volatile sig_atomic_t stop = 0;

void handle_signal(int signum) {
    stop = 1;
}

void cleanup() {
    if (spi >= 0) {
        spiClose(spi);
    }
    if (pi > 0) {
        gpioTerminate();
    }
}

int main() {
    struct sigaction action;
    action.sa_handler = handle_signal;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    pi = gpioInitialise();
    if (pi <= 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    spi = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi < 0) {
        fprintf(stderr, "spiOpen failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(MOTOR1_EN, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIR, PI_OUTPUT);
    gpioSetMode(MOTOR2_EN, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIR, PI_OUTPUT);

    gpioWrite(MOTOR1_EN, 1);
    gpioWrite(MOTOR2_EN, 1);

    while (!stop) {
        for (int i = 0; i < ADC_CHANNELS; i++) {
            adc_values[i] = spiRead(spi, i << 6);
            if (adc_values[i] < 0) {
                fprintf(stderr, "spiRead failed\n");
                cleanup();
                return EXIT_FAILURE;
            }
