#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define ADC_CS 8
#define LED_PIN 17
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define SAMPLE_RATE 100
#define CALIBRATION_TIME 5
#define NOISE_THRESHOLD 1.10

int spi_handle;
volatile int running = 1;

void handle_sigint(int signum) {
    running = 0;
    gpioWrite(LED_PIN, 0);
    spiClose(spi_handle);
    piGpioInitialise();
    exit(0);
}

int main() {
    if (piGpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel: %d\n", spi_handle);
        return 1;
    }

    if (gpioCfgOut(LED_PIN) < 0) {
        fprintf(stderr, "Failed to configure GPIO %d as output\n", LED_PIN);
        return 1;
    }

    if (gpioCfgOut(ADC_CS) < 0) {
        fprintf(stderr, "Failed to configure GPIO %d as output\n", ADC_CS);
        return 1;
    }

    signal(SIGINT, handle_sigint);

    int sample_count = SAMPLE_RATE * CALIBRATION_TIME;
    int total = 0;

    for (int i = 0; i < sample_count; i++) {
        gpioWrite(ADC_CS, 0);
        unsigned char tx_buf[3] = {0x01, 0x80, 0x00};
        unsigned char rx_buf[3];
        spiXfer(spi_handle, tx_buf, rx_buf, 3);
        gpioWrite(ADC_CS, 1);

        int sample = (rx_buf[1] & 0x03) << 8 | rx_buf[2];
        total += sample;

        usleep(10000);
    }

    int average_ambient = total / sample_count;
    int noise_threshold = average_ambient * NOISE_THRESHOLD;

    int debounce_count = SAMPLE_RATE * 10 / 100;
    int led_on_count = 0;

    while (running) {
        gpioWrite(ADC_CS, 0);
        unsigned char tx_buf[3] = {0x01, 0x80, 0x00};
        unsigned char rx_buf[3];
        spiXfer(spi_handle, tx_buf, rx_buf, 3);
        gpioWrite(ADC_CS, 1);

        int sample = (rx_buf[1] & 0x03) << 8 | rx_buf[2];

        if (sample > noise_threshold) {
            led_on_count++;
            if (led_on_count > debounce_count) {
                gpioWrite(LED_PIN, 1);
            }
        } else {
            led_on_count = 0;
            gpioWrite(LED_PIN, 0);
        }

        usleep(10000);
    }

    return 0;
}

