#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SLAVE 0
#define SPI_SPEED 1000000

FILE *log_file;
int spi_handle;

void handle_sigint(int signo) {
    fclose(log_file);
    spi_close(spi_handle);
    pi_stop();
    exit(0);
}

int main() {
    struct sigaction action;
    action.sa_handler = handle_sigint;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);

    if (pi_init() < 0) {
        fprintf(stderr, "ERROR: Failed to initialize pigpio\n");
        return 1;
    }

    spi_handle = spi_open(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "ERROR: Failed to open SPI channel\n");
        pi_stop();
        return 1;
    }

    log_file = fopen("airflow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "ERROR: Failed to open log file\n");
        spi_close(spi_handle);
        pi_stop();
        return 1;
    }

    unsigned char tx_buf[3] = {0x01, 0x80, 0x00};
    unsigned char rx_buf[3];
    int i;

    pi_timer_ms(100, 0, [](int timer_id, void *user_data) {
        if (spi_xfer(spi_handle, tx_buf, rx_buf, 3) < 0) {
            time_t now = time(NULL);
            struct tm *timeinfo = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(log_file, "%s ERROR: ADC read failed\n", timestamp);
            fflush(log_file);
        } else {
            int raw_value = (rx_buf[1] & 0x03) << 8 | rx_buf[2];
            double voltage = raw_value * 3.3 / 1023.0;
            double airflow = (voltage - 0.5) / (4.5 - 0.5) * 200;
            time_t now = time(NULL);
            struct tm *timeinfo = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(log_file, "%s %f SLPM\n", timestamp, airflow);
            fflush(log_file);
        }
    });

    while (1) {
        sleep(1);
    }

    return 0;
}

