#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <poll.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 8
#define LOG_FILE "audio_log.txt"

static struct gpiod_line *gpio_line;
static int spi_fd;
static FILE *log_file;

static void cleanup_and_exit(int sig)
{
    if (gpio_line)
        gpiod_line_release(gpio_line);
    if (spi_fd >= 0)
        close(spi_fd);
    if (log_file)
        fclose(log_file);
    exit(sig);
}

int main(void)
{
    struct gpiod_chip *gpio_chip;
    struct spi_ioc_transfer xfer;
    uint8_t tx_buf[3] = {0x01, 0x80, 0x00};
    uint8_t rx_buf[2] = {0};
    struct timespec ts = {.tv_sec = 0, .tv_nsec = 1000000};
    int ret;

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI device");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, 0);
    if (ret < 0) {
        perror("SPI_IOC_WR_MODE");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, 8);
    if (ret < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, 1000000);
    if (ret < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        exit(EXIT_FAILURE);
    }

    gpio_chip = gpiod_chip_open(GPIO_CHIP);
    if (!gpio_chip) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_LINE);
    if (!gpio_line) {
        perror("gpiod_chip_get_line");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(gpio_line, "adc_cs", 1);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        exit(EXIT_FAILURE);
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    while (1) {
        struct timespec rem;
        clock_gettime(CLOCK_MONOTONIC_RAW, &ts);

        gpiod_line_set_value(gpio_line, 0);

        xfer.tx_buf = (unsigned long)tx_buf;
        xfer.rx_buf = (unsigned long)rx_buf;
        xfer.len = sizeof(tx_buf);
        xfer.speed_hz = 1000000;
        xfer.bits_per_word = 8;
        xfer.delay_usecs = 0;
        xfer.cs_change = 0;

        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer);
        if (ret < 0) {
            perror("SPI_IOC_MESSAGE");
            exit(EXIT_FAILURE);
        }

        gpiod_line_set_value(gpio_line, 1);

        uint32_t adc_value = (rx_buf[0] << 8) | rx_buf[1];
        fprintf(log_file, "%lu|%u\n", ts.tv_nsec, adc_value);
        fflush(log_file);

        nanosleep(&ts, &rem);
    }

    return 0;
}

