#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define VREF 3.3
#define PPM_SCALE 1000.0

static int spi_handle;
static FILE *log_file;

void exit_handler(int signum) {
    fclose(log_file);
    spiClose(spi_handle);
    piGpioInitialise();
    printf("\nExiting...\n");
    exit(0);
}

int main() {
    int ret;
    struct sigaction action;
    uint8_t tx_buf[3] = {0x01, 0x80, 0x00};
    uint8_t rx_buf[3];
    float voltage, ppm;
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    action.sa_handler = exit_handler;
    action.sa_flags = 0;
    sigemptyset(&action.sa_mask);
    sigaction(SIGINT, &action, NULL);

    spi_handle = spiOpen(SPI_DEVICE, SPI_SPEED, 0);
    if (spi_handle < 0) {
        printf("Failed to open SPI device: %d\n", spi_handle);
        return -1;
    }

    log_file = fopen("gas_log.txt", "a");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        return -1;
    }

    while (1) {
        ret = spiXfer(spi_handle, tx_buf, rx_buf, 24);
        if (ret != 24) {
            printf("SPI transfer failed: %d\n", ret);
            nanosleep(&ts, NULL);
            continue;
        }

        voltage = ((rx_buf[1] & 0x03) << 8 | rx_buf[2]) * VREF / 1023.0;
        ppm = voltage * PPM_SCALE;

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld, %.3f, %.3f\n", ts.tv_sec, ts.tv_nsec, voltage, ppm);
        printf("Voltage: %.3f V, PPM: %.3f\n", voltage, ppm);

        ts.tv_nsec += 1000000000; // 1 second
        while (ts.tv_nsec >= 1000000000) {
            ts.tv_nsec -= 1000000000;
            ts.tv_sec++;
        }

        nanosleep(&ts, NULL);
    }

    return 0;
}

