#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <pigpioSPI.h>

#define ADC_CHANNELS 8
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define CS_GPIO 8
#define MOSI_GPIO 10
#define MISO_GPIO 9
#define SCLK_GPIO 11

#define X_CHANNEL 0
#define Y_CHANNEL 1
#define Z_CHANNEL 2

#define SENSITIVITY 300.0f
#define ZERO_BIAS 1.5f

#define FILTER_ALPHA 0.8f

static float kalman_filter(float alpha, float value, float previous_filtered_value);
static void exit_handler(int signum);

static float x_filter = 0.0f, y_filter = 0.0f, z_filter = 0.0f;

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel: %d\n", spi_handle);
        return EXIT_FAILURE;
    }

    if (gpioCfgOut(CS_GPIO) < 0 || gpioCfgOut(MOSI_GPIO) < 0 || gpioCfgIn(MISO_GPIO) < 0 || gpioCfgOut(SCLK_GPIO) < 0) {
        fprintf(stderr, "Failed to configure GPIO\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, exit_handler);
    signal(SIGTERM, exit_handler);

    while (1) {
        for (int channel = 0; channel < ADC_CHANNELS; ++channel) {
            gpioWrite(CS_GPIO, 0);
            spiWrite(spi_handle, &channel, 1);
            gpioWrite(CS_GPIO, 1);

            int value = spiRead(spi_handle);
            if (value < 0) {
                fprintf(stderr, "Failed to read SPI: %d\n", value);
                exit_handler(0);
            }

            float voltage = (float)value / 1023.0f * 3.3f;
            float acceleration = (voltage - ZERO_BIAS) / SENSITIVITY;

            switch (channel) {
                case X_CHANNEL:
                    x_filter = kalman_filter(FILTER_ALPHA, acceleration, x_filter);
                    break;
                case Y_CHANNEL:
                    y_filter = kalman_filter(FILTER_ALPHA, acceleration, y_filter);
                    break;
                case Z_CHANNEL:
                    z_filter = kalman_filter(FILTER_ALPHA, acceleration, z_filter);
                    break;
                default:
                    break;
            }
        }

        printf("X: %.2f g, Y: %.2f g, Z: %.2f g\n", x_filter, y_filter, z_filter);
        sleep(0.1);
    }

    return EXIT_SUCCESS;
}

static float kalman_filter(float alpha, float value, float previous_filtered_value) {
    float filtered_value = alpha * value + (1.0f - alpha) * previous_filtered_value;
    return filtered_value;
}

static void exit_handler(int signum) {
    spiClose(SPI_CHANNEL);
    gpioTerminate();

    exit(signum);
}

