#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <time.h>

#define GPIO4 4
#define GPIO17 17
#define GPIO27 27

#define V_QUIESCENT 1.65
#define SENSITIVITY 0.025
#define VCC 3.3
#define SAMPLE_INTERVAL 100000
#define LOG_FILE "magnetic_log.txt"

struct gpiod_line *lines[3];
struct gpiod_chip *chip;
FILE *log_file;

void sigint_handler(int signum) {
    for (int i = 0; i < 3; i++)
        gpiod_line_release(lines[i]);
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(0);
}

int main() {
    chip = gpiod_chip_open_by_name("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen");
        gpiod_chip_close(chip);
        return 1;
    }

    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, (i * 13) + 4);
        if (!lines[i]) {
            perror("gpiod_chip_get_line");
            sigint_handler(0);
            return 1;
        }

        if (gpiod_line_request_input(lines[i], "DRV5055VA", -1)) {
            perror("gpiod_line_request_input");
            sigint_handler(0);
            return 1;
        }
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        int values[3];
        for (int i = 0; i < 3; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                perror("gpiod_line_get_value");
                continue;
            }
            values[i] = (value * VCC - V_QUIESCENT) / SENSITIVITY;
            if (values[i] < -100 || values[i] > 100)
                fprintf(stderr, "Warning: Sensor %d magnetic field strength out of range: %d mT\n", i + 1, values[i]);
        }

        fprintf(log_file, "%d,%d,%d\n", values[0], values[1], values[2]);
        fflush(log_file);

        usleep(SAMPLE_INTERVAL);
    }

    return 0;
}

