#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <spidev.h>

#define ADC_CHANNEL 0
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30
#define POLL_INTERVAL 60

int spi_fd;
int pump_state = 0;

void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(stderr, "%s - %s\n", timestamp, event);
    fflush(stderr);
}

void handle_exit(int signum) {
    if (pump_state == 1) {
        piGpioWrite(PUMP_GPIO, 0);
        log_event("Pump turned off on exit");
    }
    close(spi_fd);
    exit(0);
}

int main() {
    signal(SIGINT, handle_exit);
    signal(SIGTERM, handle_exit);

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        log_event("Failed to open SPI device");
        return 1;
    }

    if (piGpioInitialise() < 0) {
        log_event("Failed to initialize pigpio");
        return 1;
    }

    if (piGpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        log_event("Failed to set GPIO mode");
        return 1;
    }

    log_event("Program started");

    while (1) {
        uint16_t adc_value;
        uint8_t tx_buf[3] = {1, (ADC_CHANNEL << 4), 0};
        uint8_t rx_buf[2];

        if (write(spi_fd, tx_buf, 3) != 3) {
            log_event("Failed to write to SPI device");
            continue;
        }

        if (read(spi_fd, rx_buf, 2) != 2) {
            log_event("Failed to read from SPI device");
            continue;
        }

        adc_value = (rx_buf[0] & 0x03) << 8 | rx_buf[1];

        if (adc_value < (1023 * MOISTURE_THRESHOLD / 100)) {
            if (pump_state == 0) {
                piGpioWrite(PUMP_GPIO, 1);
                pump_state = 1;
                log_event("Pump turned on");
            }
        } else {
            if (pump_state == 1) {
                piGpioWrite(PUMP_GPIO, 0);
                pump_state = 0;
                log_event("Pump turned off");
            }
        }

        sleep(POLL_INTERVAL);
    }

    return 0;
}

