#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <linux/spi/spidev.h>
#include <sys/ioctl.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CSV_FILE "sensor_data.csv"

int spi_fd = -1;
FILE* csv_file = NULL;

void cleanup_and_exit(int signum) {
    if (csv_file != NULL)
        fclose(csv_file);
    if (spi_fd != -1)
        close(spi_fd);
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    const struct spi_ioc_transfer xfer[3] = {
        {.tx_buf = (unsigned long) "\x01\x80\x00", .len = 3},
        {.rx_buf = (unsigned long) "\x00\x00\x00", .len = 3},
        {.tx_buf = (unsigned long) "\x01\x84\x00", .len = 3},
    };

    signal(SIGINT, cleanup_and_exit);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open spi device");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, SPI_MODE_0) < 0) {
        perror("set spi mode");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, 8) < 0) {
        perror("set spi bits per word");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, 1000000) < 0) {
        perror("set spi speed");
        return 1;
    }

    csv_file = fopen(CSV_FILE, "w");
    if (csv_file == NULL) {
        perror("open csv file");
        return 1;
    }

    for (;;) {
        for (int i = 0; i < 3; ++i) {
            xfer[i].tx_buf += i;
            xfer[i].rx_buf += i;
            if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer[i]) < 0) {
                perror("spi transfer");
                return 1;
            }
            xfer[i].tx_buf -= i;
            xfer[i].rx_buf -= i;
            int value = ((xfer[i].rx_buf[1] & 0x03) << 8) | xfer[i].rx_buf[2];
            fprintf(csv_file, "%d,%d\n", i, value);
        }
        sleep(1);
    }

    return 0;
}

