#include <signal.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <cJSON.h>

#define LED_GPIO 17
#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_TOPIC "home/led_control"

struct timespec start;
int reconnect_delay = 1000;
mosquitto *mosq = NULL;

void log_error(const char *format, ...) {
    va_list args;
    va_start(args, format);
    clock_gettime(CLOCK_REALTIME, &start);
    fprintf(stderr, "[%ld.%09ld] ", start.tv_sec, start.tv_nsec);
    vfprintf(stderr, format, args);
    fprintf(stderr, "\n");
    va_end(args);
}

void on_connect(struct mosquitto *mosq, void *obj, int rc) {
    if (rc) {
        log_error("MQTT connect failed: %s", mosquitto_connack_string(rc));
        return;
    }
    mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0, NULL);
}

void on_message(struct mosquitto *mosq, void *obj, const struct mosquitto_message *msg) {
    cJSON *root = cJSON_Parse(msg->payload);
    if (!root) {
        log_error("Failed to parse JSON: %s", msg->payload);
        return;
    }
    cJSON *led_state = cJSON_GetObjectItem(root, "led_state");
    if (!led_state || !cJSON_IsBool(led_state)) {
        log_error("Invalid JSON, expected {led_state: bool}");
        cJSON_Delete(root);
        return;
    }
    gpioWrite(LED_GPIO, led_state->valueint);
    cJSON_Delete(root);
}

void on_disconnect(struct mosquitto *mosq, void *obj, int rc) {
    log_error("MQTT disconnected: %s", mosquitto_disconnect_string(rc));
}

void on_signal(int signum) {
    gpioWrite(LED_GPIO, 0);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        return 1;
    }
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction action;
    action.sa_handler = on_signal;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_error("Failed to create MQTT client");
        return 1;
    }
    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);

    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc) {
        log_error("Failed to connect to MQTT broker: %s", mosquitto_connack_string(rc));
        return 1;
    }
    mosquitto_loop_start(mosq);

    while (mosquitto_loop_in_use(mosq)) {
        if (mosquitto_loop_iterate(mosq, reconnect_delay) == MOSQ_ERR_SUCCESS) {
            reconnect_delay = 1000;
        } else if (reconnect_delay < 60000) {
            reconnect_delay *= 2;
        }
    }

    on_signal(0);
    return 0;
}

