#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_SOUND_SENSOR 17
#define GPIO_ALARM_LED 18
#define CHIP "gpiochip0"

struct gpiod_chip *chip;
struct gpiod_line *sound_sensor_line, *alarm_led_line;

void exit_handler(int signum)
{
    gpiod_line_release(sound_sensor_line);
    gpiod_line_release(alarm_led_line);
    gpiod_chip_close(chip);
    printf("Exiting...\n");
    exit(0);
}

int main()
{
    int ret;

    chip = gpiod_chip_open(CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }

    sound_sensor_line = gpiod_chip_get_line(chip, GPIO_SOUND_SENSOR);
    if (!sound_sensor_line) {
        perror("gpiod_chip_get_line");
        exit(EXIT_FAILURE);
    }

    alarm_led_line = gpiod_chip_get_line(chip, GPIO_ALARM_LED);
    if (!alarm_led_line) {
        perror("gpiod_chip_get_line");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_input(sound_sensor_line, "sound sensor");
    if (ret < 0) {
        perror("gpiod_line_request_input");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(alarm_led_line, "alarm led", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, exit_handler);
    signal(SIGTERM, exit_handler);

    while (1) {
        ret = gpiod_line_get_value(sound_sensor_line);
        if (ret < 0) {
            perror("gpiod_line_get_value");
            exit_handler(0);
        }

        printf("Sound level: %d\n", ret);

        if (!ret) {
            gpiod_line_set_value(alarm_led_line, 1);
            sleep(1);
            gpiod_line_set_value(alarm_led_line, 0);
        }

        usleep(100000);
    }

    exit_handler(0);
}

