#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_LINE 17
#define LOG_FILE "/var/log/vibration_shutdown.log"

volatile sig_atomic_t stop = 0;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM)
        stop = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct timespec ts;
    FILE *log_file;
    char timestamp[20];

    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto err_close_chip;
    }

    if (gpiod_line_request_falling_edge_events(line, "vibration-monitor")) {
        perror("gpiod_line_request_falling_edge_events");
        goto err_release_line;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        goto err_release_line;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (!stop) {
        if (gpiod_line_event_wait(line, NULL)) {
            if (errno == ETIMEDOUT)
                continue;
            perror("gpiod_line_event_wait");
            goto err_close_log;
        }

        if (gpiod_line_event_read(line)) {
            perror("gpiod_line_event_read");
            goto err_close_log;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        if (fprintf(log_file, "%s: Vibration detected\n", timestamp) < 0) {
            perror("fprintf");
            goto err_close_log;
        }

        if (fflush(log_file) != 0) {
            perror("fflush");
            goto err_close_log;
        }

        printf("%s: Vibration detected\n", timestamp);

        system("sudo shutdown -h now");
    }

    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;

err_close_log:
    fclose(log_file);

err_release_line:
    gpiod_line_release(line);

err_close_chip:
    gpiod_chip_close(chip);

    return EXIT_FAILURE;
}

