#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_CHIP_ID 0x58

#define BMP280_REG_CALIB_START 0x88
#define BMP280_REG_CALIB_END 0xA1
#define BMP280_REG_CHIP_ID 0xD0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_PRESS_LSB 0xF8
#define BMP280_REG_PRESS_XLSB 0xF9
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC

static int bmp280_i2c_handle = -1;
static FILE *log_file = NULL;

void cleanup_and_exit(int signum) {
    if (bmp280_i2c_handle >= 0) {
        piI2C_close(bmp280_i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (gpioInitialise() >= 0) {
        gpioTerminate();
    }
    exit(signum);
}

int main() {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    int pi_result = gpioInitialise();
    if (pi_result < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %d\n", pi_result);
        return EXIT_FAILURE;
    }

    bmp280_i2c_handle = piI2C_open(1, BMP280_I2C_ADDR, 0);
    if (bmp280_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle: %d\n", bmp280_i2c_handle);
        cleanup_and_exit(-1);
    }

    int8_t chip_id = piI2C_readReg8(bmp280_i2c_handle, BMP280_REG_CHIP_ID);
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Failed to detect BMP280: %d\n", chip_id);
        cleanup_and_exit(-1);
    }

    uint8_t calib_data[24];
    for (int i = 0; i < sizeof(calib_data); i++) {
        calib_data[i] = piI2C_readReg8(bmp280_i2c_handle, BMP280_REG_CALIB_START + i);
    }

    piI2C_writeReg8(bmp280_i2c_handle, BMP280_REG_CTRL_MEAS, 0x00);

    log_file = fopen("altitude_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup_and_exit(-1);
    }

    while (1) {
        int16_t raw_pressure = (piI2C_readReg8(bmp280_i2c_handle, BMP280_REG_PRESS_MSB) << 12) |
                               (piI2C_readReg8(bmp280_i2c_handle, BMP280_REG_PRESS_LSB) << 4) |
                               (piI2C_readReg8(bmp280_i2c_handle, BMP280_REG_PRESS_XLSB) >> 4);
        int16_t raw_temperature = (piI2C_readReg8(bmp280_i2c_handle, BMP280_REG_TEMP_MSB) << 12) |
                                  (piI2C_readReg8(bmp280_i2c_handle, BMP280_REG_TEMP_LSB) << 4) |
                                  (piI2C_readReg8(bmp280_i2c_handle, BMP280_REG_TEMP_XLSB) >> 4);

        // Compensate raw temperature and pressure here using the calibration data...

        time_t now = time(NULL);
        struct tm *local_time = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", local_time);

        fprintf(log_file, "%s, %.2f, %.2f\n", timestamp, temperature, pressure_pa);
        fflush(log_file);

        sleep(5);
    }

    return EXIT_SUCCESS;
}

