#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/time.h>

#define I2C_DEVICE     "/dev/i2c-1"
#define I2C_SENSOR     0x23
#define SPI_DEVICE     "/dev/spidev0.0"
#define SPI_CHANNEL    0
#define LOG_FILE       "environmental_log.txt"

static int i2c_file = -1;
static int spi_file = -1;
static FILE *log_file = NULL;

static void cleanup_and_exit(int signum) {
    if (i2c_file != -1) close(i2c_file);
    if (spi_file != -1) close(spi_file);
    if (log_file != NULL) fclose(log_file);
    exit(0);
}

static void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
    cleanup_and_exit(0);
}

static void log_sensor_data(float light, int sound) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s, Light: %.2f lux, Sound: %d\n", timestamp, light, sound);
    fflush(log_file);
}

static float read_light_level() {
    uint8_t buf[2];
    if (write(i2c_file, &buf, 1) != 1) log_error("Failed to write to I2C device");
    if (read(i2c_file, &buf, 2) != 2) log_error("Failed to read from I2C device");
    uint16_t raw_data = (buf[0] << 8) | buf[1];
    return raw_data * 1.2 / 65535.0;
}

static int read_sound_level() {
    uint16_t buf;
    if (ioctl(spi_file, SPI_IOC_MESSAGE(1), &spi_conf) != 0) log_error("Failed to configure SPI device");
    if (write(spi_file, &spi_conf, sizeof(spi_conf)) != sizeof(spi_conf)) log_error("Failed to write to SPI device");
    if (read(spi_file, &buf, 2) != 2) log_error("Failed to read from SPI device");
    return buf & 0x3FF;
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = cleanup_and_exit;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    i2c_file = open(I2C_DEVICE, O_RDWR);
    if (i2c_file == -1) log_error("Failed to open I2C device");
    if (ioctl(i2c_file, I2C_SLAVE, I2C_SENSOR) != 0) log_error("Failed to set I2C slave address");

    spi_file = open(SPI_DEVICE, O_RDWR);
    if (spi_file == -1) log_error("Failed to open SPI device");
    if (ioctl(spi_file, SPI_IOC_WR_MODE, &spi_mode) != 0) log_error("Failed to set SPI mode");
    if (ioctl(spi_file, SPI_IOC_WR_BITS_PER_WORD, &spi_bits) != 0) log_error("Failed to set SPI bits per word");
    if (ioctl(spi_file, SPI_IOC_WR_MAX_SPEED_HZ, &spi_speed) != 0) log_error("Failed to set SPI speed");

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) log_error("Failed to open log file");

    while (1) {
        float light = read_light_level();
        int sound = read_sound_level();
        log_sensor_data(light, sound);
        sleep(1);
    }

    return 0;
}

