#include <libgpiod.h>

#define GPIO_LINE 17

struct gpiod_line *line;
struct gpiod_chip *chip;
FILE *log_file;

void write_to_log(int state) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char buffer[80];
    strftime(buffer, sizeof(buffer), "%d-%m-%Y %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %d\n", buffer, GPIO_LINE, state);
    fflush(log_file);
}

void handle_signal(int signum) {
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(signum);
}

int main() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(line, "flame_sensor", GPIOD_LINE_FLAG_BIAS_PULL_DOWN)) {
        fprintf(stderr, "Failed to request GPIO line as input: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    log_file = fopen("flame_events.log", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int last_value = -1;
    while (1) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Failed to get GPIO line value: %s\n", strerror(errno));
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            fclose(log_file);
            return 1;
        }

        if (value != last_value) {
            write_to_log(value);
            if (value)
                printf("Flame detected!\n");
            last_value = value;
        }

        sleep(1);
    }

    return 0;
}

