#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 500000

#define I2C_ADDRESS 0x62
#define I2C_BUS 1

#define LOG_FILE "temperature_log.txt"

FILE *log_file;
int spi_fd;
int i2c_fd;

void exit_handler(int signum) {
    fclose(log_file);
    spiClose(spi_fd);
    i2cClose(i2c_fd);
    exit(0);
}

int main() {
    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        fprintf(stderr, "Error opening log file\n");
        exit(1);
    }

    if ((spi_fd = spiOpen(SPI_DEVICE, SPI_CHANNEL, SPI_SPEED)) < 0) {
        fprintf(stderr, "Error opening SPI device\n");
        exit(1);
    }

    if ((i2c_fd = i2cOpen(I2C_BUS, I2C_ADDRESS, 0)) < 0) {
        fprintf(stderr, "Error opening I2C device\n");
        exit(1);
    }

    signal(SIGINT, exit_handler);

    while (1) {
        unsigned char tx_buf[3] = {0x01, 0x80, 0x00};
        unsigned char rx_buf[3];
        float adc_value, temperature, dac_value;

        if (spiXfer(spi_fd, tx_buf, rx_buf, 3) != 3) {
            fprintf(stderr, "Error reading from SPI device\n");
            continue;
        }

        adc_value = ((rx_buf[1] & 0x03) << 8 | rx_buf[2]) / 1023.0;
        temperature = adc_value * 50.0;
        dac_value = adc_value * 3.3;

        unsigned char dac_buf[3] = {0x40, (unsigned char)(dac_value * 256), (unsigned char)(dac_value * 256)};

        if (i2cWrite(i2c_fd, dac_buf, 3) != 3) {
            fprintf(stderr, "Error writing to I2C device\n");
            continue;
        }

        time_t now = time(NULL);
        char *time_str = ctime(&now);
        time_str[strlen(time_str) - 1] = '\0';

        fprintf(log_file, "%s, %.2f, %.2f, %.2f\n", time_str, adc_value, temperature, dac_value);
        printf("%s, %.2f, %.2f, %.2f\n", time_str, adc_value, temperature, dac_value);

        fflush(log_file);
        fflush(stdout);

        sleep(500);
    }

    return 0;
}

