#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000

#define ADC_CHANNELS 3
#define ADC_MAX_VALUE 1023

FILE *log_file;
int spi_handle;

void exit_handler(int signum) {
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
    printf("Goodbye!\n");
    exit(0);
}

int main() {
    int i, result;
    unsigned char tx_data[4] = {0x01, 0x80, 0x00, 0x00};
    unsigned char rx_data[4];
    struct tm *timeinfo;
    time_t now;
    char timestamp[20];

    log_file = fopen("soil_data.txt", "a");
    if (log_file == NULL) {
        printf("Error opening log file!\n");
        exit(1);
    }

    spi_handle = spiOpen(SPI_DEVICE, SPI_SPEED, 0);
    if (spi_handle < 0) {
        printf("Error opening SPI device: %d\n", spi_handle);
        fclose(log_file);
        exit(1);
    }

    signal(SIGINT, exit_handler);

    while (1) {
        for (i = 0; i < ADC_CHANNELS; i++) {
            tx_data[1] = (0x10 << i) | 0x80;
            result = spiXfer(spi_handle, tx_data, rx_data, sizeof(tx_data));
            if (result != 0) {
                printf("Error in spiXfer: %d\n", result);
                continue;
            }

            int adc_value = ((rx_data[1] & 0x03) << 8) | rx_data[2];
            if (adc_value < 0 || adc_value > ADC_MAX_VALUE) {
                printf("Invalid ADC value: %d\n", adc_value);
