#define SPI_CHANNEL 0
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define THRESHOLD 500
#define LED_PIN 16
#define DEBOUNCE_DELAY 500

int spi_handle;

void exit_handler(int signum) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    gpioWrite(LED_PIN, 0);
    exit(0);
}

int main() {
    struct sigaction action;
    action.sa_handler = exit_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);

    spi_handle = spiOpen(SPI_DEVICE, SPI_SPEED, SPI_CHANNEL);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(-spi_handle));
        exit_handler(0);
    }

    int gpio_init = gpioInitialise();
    if (gpio_init < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(-gpio_init));
        exit_handler(0);
    }

    int gpio_set = gpioSetMode(LED_PIN, PI_OUTPUT);
    if (gpio_set < 0) {
        fprintf(stderr, "Failed to set GPIO mode: %s\n", strerror(-gpio_set));
        exit_handler(0);
    }

    FILE *log_file = fopen("sound_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        exit_handler(0);
    }

    while (1) {
        int adc_value = mcp3008Read(spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC: %s\n", strerror(-adc_value));
            exit_handler(0);
        }

        if (adc_value > THRESHOLD) {
            gpioWrite(LED_PIN, 1);
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
            fprintf(log_file, "%s\n", timestamp);
            delay(DEBOUNCE_DELAY);
            gpioWrite(LED_PIN, 0);
        }
    }

    fclose(log_file);
    exit_handler(0);
}

