#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define PWM_RANGE 255
#define PWM_DUTY 150
#define RAIN_THRESHOLD 5
#define LOG_FILE "rain_log.txt"

#define GPIO_IN1 17
#define GPIO_IN2 18
#define GPIO_ENA 27

volatile sig_atomic_t stop = 0;
int spi_handle = 0;
FILE* log_file = NULL;

void shutdown_handler(int signum) {
    stop = 1;
}

void cleanup() {
    if (spi_handle) {
        spiClose(spi_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
}

void error_exit(const char* message) {
    fprintf(stderr, "%s\n", message);
    cleanup();
    exit(EXIT_FAILURE);
}

int main() {
    int pi = gpioInitialise();
    if (pi < 0) {
        error_exit("Failed to initialize pigpio.");
    }

    spi_handle = spiOpen("/dev/spidev0.0", SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        error_exit("Failed to open SPI device.");
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        error_exit("Failed to open log file.");
    }

    gpioSetMode(GPIO_IN1, PI_OUTPUT);
    gpioSetMode(GPIO_IN2, PI_OUTPUT);
    gpioSetMode(GPIO_ENA, PI_OUTPUT);
    gpioSetPWMrange(GPIO_ENA, PWM_RANGE);

    signal(SIGINT, shutdown_handler);
    signal(SIGTERM, shutdown_handler);

    while (!stop) {
        unsigned char tx[3] = {0x01, (0x08 | ADC_CHANNEL) << 4, 0x00};
        unsigned char rx[3] = {0, 0, 0};

        int result = spiWriteRead(spi_handle, tx, rx, 3);
        if (result < 0) {
            error_exit("SPI transfer failed.");
        }

        int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
        int rain_level = 10 - (adc_value * 10 / 1023);

        time_t t = time(NULL);
        struct tm* time = localtime(&t);
        char timestamp[20];
        strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", time);

        fprintf(log_file, "%s, %d\n", timestamp, rain_level);
        fflush(log_file);

        if (rain_level >= RAIN_THRESHOLD) {
            gpioWrite(GPIO_IN1, 1);
            gpioWrite(GPIO_IN2, 0);
            gpioPWM(GPIO_ENA, PWM_DUTY);
            sleep(3);
        } else {
            gpioWrite(GPIO_IN1, 0);
            gpioWrite(GPIO_IN2, 1);
            gpioPWM(GPIO_ENA, PWM_DUTY);
            sleep(3);
        }
    }

    gpioWrite(GPIO_IN1, 0);
    gpioWrite(GPIO_IN2, 0);
    gpioPWM(GPIO_ENA, 0);

    cleanup();

    return 0;
}

