#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define ADC_CHANNEL 26
#define LED_PIN 16
#define THRESHOLD 700
#define DEBOUNCE_TIME 50
#define LED_ON_TIME 500

volatile int trigger = 0;

void sigint_handler(int signo) {
    trigger = 1;
}

void led_on(int dummy) {
    gpioWrite(LED_PIN, 1);
    msleep(LED_ON_TIME);
    gpioWrite(LED_PIN, 0);
}

int main() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    srand((unsigned int) ts.tv_nsec);

    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ADC_CHANNEL, PI_INPUT) < 0) {
        printf("Failed to set ADC GPIO mode.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        printf("Failed to set LED GPIO mode.\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (!trigger) {
        int adc_value = gpioRead(ADC_CHANNEL);
        if (adc_value < 0) {
            printf("Failed to read ADC value.\n");
            return EXIT_FAILURE;
        }

        if (adc_value > THRESHOLD) {
            clock_gettime(CLOCK_REALTIME, &ts);
            printf("Clap detected at %ld.%09ld\n", ts.tv_sec, ts.tv_nsec);
            led_on(0);
            msleep(DEBOUNCE_TIME);
        }
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

