#include <signal.h>
#include <time.h>

#define GPIO_PATH "/sys/class/gpio/"
#define GPIO_17_PATH GPIO_PATH "gpio17/"
#define GPIO_17_VALUE_PATH GPIO_17_PATH "value"

#define GPIO_UNEXPORT_PATH GPIO_PATH "unexport"

#define GPIO_EXPORT_PATH GPIO_PATH "export"
#define GPIO_17_NUM 17

#define LOG_FILE "distance_log.txt"

#define A 26.0
#define B -6.0

#define PROXIMITY_THRESHOLD 200

int gpio_fd = -1;
int log_file_fd = -1;

void exit_handler(int signum) {
    if (gpio_fd != -1) {
        write(gpio_fd, "17", 2);
        close(gpio_fd);
    }
    if (log_file_fd != -1) {
        close(log_file_fd);
    }
    exit(0);
}

int main() {
    struct sigaction action;
    action.sa_handler = exit_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    gpio_fd = open(GPIO_UNEXPORT_PATH, O_WRONLY);
    if (gpio_fd == -1) {
        perror("Failed to open GPIO unexport");
        return 1;
    }

    if (write(gpio_fd, "17", 2) != 2) {
        perror("Failed to unexport GPIO 17");
        return 1;
    }
    close(gpio_fd);

    gpio_fd = open(GPIO_EXPORT_PATH, O_WRONLY);
    if (gpio_fd == -1) {
        perror("Failed to open GPIO export");
        return 1;
    }

    if (write(gpio_fd, "17", 2) != 2) {
        perror("Failed to export GPIO 17");
        return 1;
    }
    close(gpio_fd);

    log_file_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (log_file_fd == -1) {
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        gpio_fd = open(GPIO_17_VALUE_PATH, O_RDONLY);
        if (gpio_fd == -1) {
            perror("Failed to open GPIO 17 value");
            sleep(1);
            continue;
        }

        char gpio_value;
        if (read(gpio_fd, &gpio_value, 1) != 1) {
            perror("Failed to read GPIO 17 value");
            close(gpio_fd);
            sleep(1);
            continue;
        }
        close(gpio_fd);

        double voltage = (gpio_value == '0') ? 0.0 : 3.3;
        double distance = A / voltage + B;

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        char log_message[100];
        sprintf(log_message, "%s Distance: %.2f mm\n", timestamp, distance);
        write(log_file_fd, log_message, strlen(log_message));

        printf("%s\n", distance < PROXIMITY_THRESHOLD ? "Feeder Activated" : "Feeder Idle");
    }

    return 0;
}

