#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/spi/spidev.h>
#include <sys/ioctl.h>
#include <inttypes.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 8
#define MCP3008_CHANNEL 0
#define LOG_FILE "magnetic_log.txt"

struct gpiod_line *gpio_line;
int spi_fd;
FILE *log_file;

void cleanup_and_exit(int signum) {
    gpiod_line_release(gpio_line);
    close(spi_fd);
    if (log_file) fclose(log_file);
    exit(signum);
}

int main() {
    struct gpiod_chip *gpio_chip;
    struct spi_ioc_transfer xfer;
    uint16_t spi_data;
    struct timespec ts;
    double vout_mV, b_mt;
    int ret;

    gpio_chip = gpiod_chip_open(GPIO_CHIP);
    if (!gpio_chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_LINE);
    if (!gpio_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    ret = gpiod_line_request_output(gpio_line, "spi_cs", 1);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    while (1) {
        /* Prepare SPI transfer */
        spi_data = (0x1 << 12) | (MCP3008_CHANNEL << 8);
        xfer.tx_buf = (__u64)&spi_data;
        xfer.rx_buf = (__u64)&spi_data;
        xfer.len = 2;
        xfer.speed_hz = 1000000;
        xfer.bits_per_word = 8;
        xfer.delay_usecs = 0;
        xfer.cs_change = 1;

        /* Drive CS low */
        gpiod_line_set_value(gpio_line, 0);

        /* Perform SPI transfer */
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer);
        if (ret < 0) {
            perror("ioctl");
            fprintf(stderr, "SPI transfer failed\n");
            continue;
        }

        /* Drive CS high */
        gpiod_line_set_value(gpio_line, 1);

        /* Compute voltage and magnetic field */
        spi_data = (spi_data >> 6) & 0x3FF;
        vout_mV = spi_data * 3300.0 / 1023.0;
        b_mt = (vout_mV - 1650.0) / 100.0;

        /* Get current time */
        clock_gettime(CLOCK_REALTIME, &ts);

        /* Write to log file */
        fprintf(log_file, "%" PRId64 ".%.9ld,%.2f\n", ts.tv_sec, ts.tv_nsec, b_mt);
        fflush(log_file);

        /* Sleep for 500 ms */
        usleep(500000);
    }

    /* This should never be reached */
    return 0;
}

