#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define LED_PIN 21
#define SPI_CHANNEL 0
#define SPI_DEVICE "/dev/spidev0.0"
#define FIELD_THRESHOLD 10.0
#define VCC 3.3
#define SENSITIVITY_MV_PER_MT 1.65
#define DELAY_MS 100

static int spi_handle = -1;
static int pigpio_handle = -1;

void cleanup(int signum) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (pigpio_handle >= 0) {
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
    }
    exit(0);
}

int main() {
    int spi_result;
    FILE* log_file;
    char log_path[] = "magnetic_log.txt";
    struct timespec ts;
    int16_t adc_value;
    double voltage, field_mT;

    signal(SIGINT, cleanup);

    pigpio_handle = gpioInitialise();
    if (pigpio_handle < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %d\n", pigpio_handle);
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);

    spi_handle = spiOpen(SPI_DEVICE, 1000000, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI device: %d\n", spi_handle);
        cleanup(0);
        return 1;
    }

    log_file = fopen(log_path, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup(0);
        return 1;
    }

    while (1) {
        spi_result = spiRead(spi_handle, ADC_CHANNEL, &adc_value);
        if (spi_result < 0) {
            fprintf(stderr, "Failed to read ADC: %d\n", spi_result);
            cleanup(0);
            return 1;
        }

        voltage = (double)adc_value * VCC / 1023;
        field_mT = (voltage - VCC / 2) * 1000 / SENSITIVITY_MV_PER_MT;

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld: %f mT\n", ts.tv_sec, ts.tv_nsec, field_mT);
        fflush(log_file);

        if (field_mT > FIELD_THRESHOLD) {
            gpioWrite(LED_PIN, 1);
        } else {
            gpioWrite(LED_PIN, 0);
        }

        usleep(DELAY_MS * 1000);
    }

    cleanup(0);
    return 0;
}

