#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define ADC_CMD 0x0180
#define LOG_FILE "moisture_log.txt"

volatile sig_atomic_t stop = 0;

void sigint_handler(int signo) {
    stop = 1;
}

void log_message(const char *message, int adc_value) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        printf("Error opening log file\n");
        return;
    }
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s %s %d\n", timestamp, message, adc_value);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        printf("Error initializing pigpio\n");
        return EXIT_FAILURE;
    }

    if (spiOpen(SPI_CHANNEL, SPI_BAUD, 0) < 0) {
        printf("Error opening SPI channel\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (!stop) {
        uint8_t tx_buf[3] = {ADC_CMD >> 8, ADC_CMD & 0xFF, 0};
