#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

volatile sig_atomic_t stop = 0;

void sigint_handler(int signo) {
    stop = 1;
}

int main() {
    int pi;
    int spi_handle;
    int channel = 0;
    FILE *log_file;
    struct tm *ts;
    time_t timer;
    char buffer[20];
    char filename[] = "current_log.txt";
    int raw_code;
    double voltage;
    double current;

    pi = gpioInitialise();
    if (pi < 0) {
        printf("gpioInitialise() failed: %d\n", pi);
        return 1;
    }

    spi_handle = spiOpen(0, 1000000, 0);
    if (spi_handle < 0) {
        gpioTerminate();
        printf("spiOpen() failed: %d\n", spi_handle);
        return 1;
    }

    log_file = fopen(filename, "a");
    if (log_file == NULL) {
        spiClose(spi_handle);
        gpioTerminate();
        printf("fopen() failed\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (!stop) {
        int tx[3] = {0x01, 0x80 | (channel<<4), 0x00};
        int rx[3];

        if (spiXfer(spi_handle, tx, rx, 3) != 3) {
            printf("spiXfer() failed\n");
            continue;
        }

        raw_code = ((rx[1] & 0x03) << 8) | rx[2];
        voltage = raw_code * (5.0 / 1023.0);
        current = (voltage - 2.5) * (50.0 / 2.5);

        if (voltage < 0.0 || voltage > 5.0) {
            printf("Voltage out of range: %f\n", voltage);
            continue;
        }

        timer = time(NULL);
        ts = localtime(&timer);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", ts);

        fprintf(log_file, "%s %.2f A\n", buffer, current);
        fflush(log_file);

        gpioDelay(100000);
    }

    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

