#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

volatile sig_atomic_t terminate = 0;

int spi_handle = -1;

struct spi_config_t {
    int channel;
    int baud;
};

void signal_handler(int signal) {
    terminate = 1;
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    printf("Signal %d received, closing SPI and terminating pigpio\n", signal);
    gpioTerminate();
    exit(0);
}

int spi_setup(struct spi_config_t config) {
    spi_handle = spiOpen(config.channel, config.baud, 0);
    if (spi_handle < 0) {
        printf("Failed to open SPI device: %d\n", spi_handle);
        gpioTerminate();
        exit(-1);
    }
    return spi_handle;
}

int read_mcp3008(int channel) {
    unsigned char tx_buf[3] = {0x01, 0x80 | (channel << 4), 0x00};
    unsigned char rx_buf[3] = {0x00, 0x00, 0x00};
    int ret;

    ret = spiXfer(spi_handle, tx_buf, rx_buf, sizeof(tx_buf));
    if (ret < 0) {
        printf("SPI transfer failed: %d\n", ret);
        sleep(1);
        return -1;
    }

    return ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
}

double calculate_moisture_level(int adc_value) {
    double moisture_level = 100.0 - ((adc_value - MIN_ADC) / (double)(MAX_ADC - MIN_ADC)) * 100.0;
    if (moisture_level < 0.0) {
        moisture_level = 0.0;
    } else if (moisture_level > 100.0) {
        moisture_level = 100.0;
    }
    return moisture_level;
}

void log_data(double moisture_level) {
    time_t now = time(0);
    struct tm *time_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        printf("Failed to open file %s for writing\n", LOG_FILE);
        return;
    }

    fprintf(file, "%s,%.2f\n", timestamp, moisture_level);
    fclose(file);

    printf("%s,%.2f\n", timestamp, moisture_level);
}

int main() {
    struct spi_config_t spi_config = {SPI_CHANNEL, SPI_BAUD};

    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio\n");
        exit(-1);
    }

    spi_setup(spi_config);

    signal(SIGINT, signal_handler);

    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value >= 0) {
            double moisture_level = calculate_moisture_level(adc_value);
            log_data(moisture_level);
        }
        sleep(READ_DELAY);
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }

    gpioTerminate();

    return 0;
}

