#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define LOG_FILE "frame_log.txt"

volatile sig_atomic_t stop = 0;
int fd = -1;
FILE *log_file = NULL;

void cleanup_and_exit(int sig) {
    if (fd != -1) {
        close(fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (sig != 0) {
        printf("Signal %d received, shutting down...\n", sig);
    }
    exit(sig);
}

void handle_error(const char *operation) {
    perror(operation);
    cleanup_and_exit(1);
}

void capture_video() {
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    struct timeval timestamp;
    void *mmap_start;
    int mmap_length;

    // Open the video device
    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        handle_error("open");
    }

    // Set the video format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        handle_error("VIDIOC_S_FMT");
    }

    // Request and mmap buffers
    memset(&req, 0, sizeof(req));
    req.count = 4;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        handle_error("VIDIOC_REQBUFS");
    }

    for (int i = 0; i < req.count; ++i) {
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            handle_error("VIDIOC_QUERYBUF");
        }

        mmap_start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (mmap_start == MAP_FAILED) {
            handle_error("mmap");
        }

        buf.m.userptr = (unsigned long)mmap_start;
        buf.length = buf.length;
        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            handle_error("VIDIOC_QBUF");
        }
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        handle_error("VIDIOC_STREAMON");
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        handle_error("fopen");
    }

    // Main capture loop
    while (!stop) {
        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            handle_error("VIDIOC_DQBUF");
        }

        gettimeofday(&timestamp, NULL);
        fprintf(log_file, "%ld.%06ld\n", timestamp.tv_sec, timestamp.tv_usec);

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            handle_error("VIDIOC_QBUF");
        }
    }

    // Stop streaming
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        handle_error("VIDIOC_STREAMOFF");
    }

    // Unmap buffers
    for (int i = 0; i < req.count; ++i) {
        if (munmap(mmap_start, buf.length) < 0) {
            handle_error("munmap");
        }
    }

    cleanup_and_exit(0);
}

int main() {
    struct sigaction action;

    // Set up signal handling
    memset(&action, 0, sizeof(action));
    action.sa_handler = cleanup_and_exit;
    sigaction(SIGINT, &action, NULL);

    capture_video();
    return 0;
}

