#define DEV_NAME "/dev/video0"
#define IMAGE_NAME "image.jpg"
#define WIDTH 1920
#define HEIGHT 1080
#define NUM_BUFS 4

struct buffer {
    void *start;
    size_t length;
};

struct buffer *bufs;
int dev_fd, img_fd;

void cleanup_and_exit(int signum)
{
    const int save_errno = errno;

    ioctl(dev_fd, VIDIOC_STREAMOFF, NULL);

    for (int i = 0; i < NUM_BUFS; i++)
        munmap(bufs[i].start, bufs[i].length);

    free(bufs);

    close(dev_fd);
    if (img_fd != -1)
        close(img_fd);

    errno = save_errno;
    exit(signum ? 0 : 1);
}

int main()
{
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers reqbufs;
    struct v4l2_buffer buf;
    struct sigaction action;

    action.sa_handler = cleanup_and_exit;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;

    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    dev_fd = open(DEV_NAME, O_RDWR);
    if (dev_fd == -1) {
        perror("open");
        return 1;
    }

    if (ioctl(dev_fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        return 1;
    }

    if ((cap.capabilities & V4L2_CAP_VIDEO_CAPTURE) == 0 ||
        (cap.capabilities & V4L2_CAP_STREAMING) == 0) {
        fprintf(stderr, "Device does not support required capabilities\n");
        return 1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(dev_fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        return 1;
    }

    memset(&reqbufs, 0, sizeof(reqbufs));
    reqbufs.count = NUM_BUFS;
    reqbufs.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    reqbufs.memory = V4L2_MEMORY_MMAP;

    if (ioctl(dev_fd, VIDIOC_REQBUFS, &reqbufs) == -1) {
        perror("VIDIOC_REQBUFS");
        return 1;
    }

    bufs = calloc(reqbufs.count, sizeof(*bufs));
    if (bufs == NULL) {
        perror("calloc");
        return 1;
    }

    for (int i = 0; i < reqbufs.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(dev_fd, VIDIOC_MMAP, &buf) == -1) {
            perror("VIDIOC_MMAP");
            return 1;
        }

        bufs[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, dev_fd, buf.m.offset);
        if (bufs[i].start == MAP_FAILED) {
            perror("mmap");
            return 1;
        }

        bufs[i].length = buf.length;

        if (ioctl(dev_fd, VIDIOC_QBUF, &buf) == -1) {
            perror("VIDIOC_QBUF");
            return 1;
        }
    }

    if (ioctl(dev_fd, VIDIOC_STREAMON, NULL) == -1) {
        perror("VIDIOC_STREAMON");
        return 1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(dev_fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("VIDIOC_DQBUF");
        return 1;
    }

    if (buf.bytesused <= 0) {
        fprintf(stderr, "Invalid frame size: %zu\n", buf.bytesused);
        return 1;
    }

    img_fd = open(IMAGE_NAME, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (img_fd == -1) {
        perror("open");
        return 1;
    }

    if (write(img_fd, bufs[buf.index].start, buf.bytesused) != (ssize_t)buf.bytesused) {
        perror("write");
        return 1;
    }

    cleanup_and_exit(0);

    return 0;
}

