#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_PAN_SERVO 4
#define GPIO_TILT_SERVO 5
#define GPIO_TILT_UP 6
#define GPIO_TILT_DOWN 7
#define GPIO_PAN_LEFT 8
#define GPIO_PAN_RIGHT 9
#define SERVO_MIN 25
#define SERVO_MAX 125
#define SERVO_MID 75
#define SERVO_STEP 5
#define PWM_PERIOD_US 20000
#define PWM_DUTY_MIN 50
#define PWM_DUTY_MAX 100
#define PWM_DUTY_MID 75
#define POLL_INTERVAL_US 50000

struct gpiod_chip *chip;
struct gpiod_line *lines[4];
int servo_duty[2] = { SERVO_MID, SERVO_MID };

void handle_sigint(int signum)
{
    for (int i = 0; i < 2; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
    exit(0);
}

int main(void)
{
    struct gpiod_line_request_config config = {
        .flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW,
        .consumer = "servo_controller",
    };

    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    for (int i = 0; i < 2; i++) {
        lines[i] = gpiod_chip_get_line(chip, i == 0 ? GPIO_TILT_UP : GPIO_PAN_LEFT);
        if (!lines[i]) {
            perror("gpiod_chip_get_line");
            return 1;
        }

        if (gpiod_line_request_pulse_width_input(lines[i], &config, PWM_PERIOD_US, servo_duty[i] * 20)) {
            perror("gpiod_line_request_pulse_width_input");
            return 1;
        }
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        for (int i = 2; i < 4; i++) {
            lines[i] = gpiod_chip_get_line(chip, i == 2 ? GPIO_TILT_DOWN : GPIO_PAN_RIGHT);
            if (!lines[i]) {
                perror("gpiod_chip_get_line");
                return 1;
            }

            if (gpiod_line_request_pulse_width_input(lines[i], &config, PWM_PERIOD_US, servo_duty[i - 2] * 20)) {
                perror("gpiod_line_request_pulse_width_input");
                return 1;
            }
        }

        for (int i = 0; i < 4; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                perror("gpiod_line_get_value");
                return 1;
            }

            if (value) {
                int servo = i < 2 ? 0 : 1;
                servo_duty[servo] += i % 2 == 0 ? -SERVO_STEP : SERVO_STEP;
                if (servo_duty[servo] < SERVO_MIN)
                    servo_duty[servo] = SERVO_MIN;
                else if (servo_duty[servo] > SERVO_MAX)
                    servo_duty[servo] = SERVO_MAX;

                if (gpiod_line_set_pulse_width(lines[servo], servo_duty[servo] * 20)) {
                    perror("gpiod_line_set_pulse_width");
                    return 1;
                }
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    return 0;
}

