#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/videodev2.h>

#define DEV_NAME "/dev/video0"

void print_resolutions(int fd) {
    struct v4l2_frmsizeenum frmsize = {
        .index = 0,
        .pixel_format = V4L2_PIX_FMT_YUYV,
    };

    printf("Supported resolutions:\n");
    while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) == 0) {
        printf("  %ux%u\n", frmsize.discrete.width, frmsize.discrete.height);
        frmsize.index++;
    }
}

void print_framerates(int fd, int width, int height) {
    struct v4l2_frmivalenum frmival = {
        .index = 0,
        .pixel_format = V4L2_PIX_FMT_YUYV,
        .width = width,
        .height = height,
    };

    printf("  Frame rates:\n");
    while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmival) == 0) {
        printf("    %u/%u\n", frmival.discrete.numerator, frmival.discrete.denominator);
        frmival.index++;
    }
}

void print_autofocus(int fd) {
    struct v4l2_queryctrl queryctrl = {
        .id = V4L2_CID_FOCUS_AUTO,
    };

    if (ioctl(fd, VIDIOC_QUERYCTRL, &queryctrl) == 0) {
        printf("Autofocus supported: %s\n", queryctrl.flags & V4L2_CTRL_FLAG_DISABLED ? "no" : "yes");
    } else {
        printf("Autofocus supported: no\n");
    }
}

int main() {
    int fd = open(DEV_NAME, O_RDONLY);
    if (fd < 0) {
        perror("Failed to open device");
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Failed to query device capabilities");
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device is not a video capture device\n");
        return EXIT_FAILURE;
    }

    print_resolutions(fd);
    print_autofocus(fd);

    close(fd);
    return EXIT_SUCCESS;
}

