#include <stdio.h>
#include <signal.h>
#include <pigpio.h>

#define PAN_SERVO 4
#define TILT_SERVO 5
#define UP_BUTTON 6
#define DOWN_BUTTON 7
#define LEFT_BUTTON 8
#define RIGHT_BUTTON 9
#define CENTER_POS 1500
#define MIN_POS 1000
#define MAX_POS 2000
#define STEP 10
#define DELAY 50

volatile int stop = 0;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        stop = 1;
    }
}

int main() {
    int pi = pigpio_start(0, 0);
    if (pi < 0) {
        printf("Failed to initialize pigpio: %d\n", pi);
        return 1;
    }

    gpioSetPullUpDown(UP_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(DOWN_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(LEFT_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_BUTTON, PI_PUD_UP);

    gpioServo(PAN_SERVO, CENTER_POS);
    gpioServo(TILT_SERVO, CENTER_POS);

    printf("Started camera control with servos on GPIO %d and %d, buttons on GPIO %d-%d, center position: %d\n", PAN_SERVO, TILT_SERVO, UP_BUTTON, RIGHT_BUTTON, CENTER_POS);

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    int pan_pos = CENTER_POS;
    int tilt_pos = CENTER_POS;

    while (!stop) {
        if (!gpioRead(UP_BUTTON)) {
            tilt_pos = (tilt_pos > MIN_POS) ? (tilt_pos - STEP) : MIN_POS;
        }
        if (!gpioRead(DOWN_BUTTON)) {
            tilt_pos = (tilt_pos < MAX_POS) ? (tilt_pos + STEP) : MAX_POS;
        }
        if (!gpioRead(LEFT_BUTTON)) {
            pan_pos = (pan_pos > MIN_POS) ? (pan_pos - STEP) : MIN_POS;
        }
        if (!gpioRead(RIGHT_BUTTON)) {
            pan_pos = (pan_pos < MAX_POS) ? (pan_pos + STEP) : MAX_POS;
        }

        gpioServo(PAN_SERVO, pan_pos);
        gpioServo(TILT_SERVO, tilt_pos);

        usleep(DELAY * 1000);
    }

    gpioServo(PAN_SERVO, 0);
    gpioServo(TILT_SERVO, 0);

    pigpio_stop(pi);

    return 0;
}

