#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <curl/curl.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_TIME 2000000
#define SERVER_IP "192.168.1.100"
#define SERVER_PORT "8080"
#define DIRECTORY "motion_captures"
#define JPEG_QUALITY 85

static CURL *curl;
static char *server_url;
static int pi_handle;
static int is_motion_detected = 0;

static void handle_signal(int signum) {
    gpioTerminate();
    curl_global_cleanup();
    exit(signum);
}

static size_t writefunc(void *ptr, size_t size, size_t nmemb, void *stream) {
    (void)ptr;
    (void)stream;
    return size * nmemb;
}

static void send_request(const char *filename) {
    struct tm tm;
    time_t now = time(NULL);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime_r(&now, &tm));
    asprintf(&server_url, "http://%s:%s/upload", SERVER_IP, SERVER_PORT);
    curl_easy_setopt(curl, CURLOPT_URL, server_url);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS,
                     "{\"filename\":\""
                     "%s"
                     "\",\"timestamp\":\""
                     "%s.%06ld"
                     "\",\"motion_status\":\""
                     "%s"
                     "\",\"gpio_pin\":\""
                     "%d"
                     "\"}",
                     filename, timestamp, tm.tm_usec, is_motion_detected ? "detected" : "not detected", GPIO_PIN);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writefunc);
    curl_easy_perform(curl);
    free(server_url);
}

static void capture_image(const char *filename) {
    char command[100];
    asprintf(command, "/usr/bin/libcamera-still -o %s/%s -w 640 -h 480 -q %d", DIRECTORY, filename, JPEG_QUALITY);
    system(command);
    free(command);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (curl_global_init(CURL_GLOBAL_DEFAULT) != CURLE_OK) {
        fprintf(stderr, "Failed to initialize curl\n");
        return EXIT_FAILURE;
    }

    curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Failed to initialize curl\n");
        return EXIT_FAILURE;
    }

    pi_handle = gpioInitialise();
    if (pi_handle < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(-pi_handle));
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0 || gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set GPIO mode or pull-up/down: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    while (1) {
        if (gpioRead(GPIO_PIN) == 1 && !is_motion_detected) {
            is_motion_detected = 1;
            char filename[30];
            strftime(filename, sizeof(filename), "%Y%m%d%H%M%S.jpg", localtime(NULL));
            capture_image(filename);
            send_request(filename);
            usleep(DEBOUNCE_TIME);
        } else if (gpioRead(GPIO_PIN) == 0 && is_motion_detected) {
            is_motion_detected = 0;
            usleep(DEBOUNCE_TIME);
        }
        usleep(100000);
    }

    return EXIT_SUCCESS;
}

