    if (pi_handle < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(-pi_handle));
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0 || gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set GPIO mode or pull-up/down: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    while (1) {
        if (gpioRead(GPIO_PIN) == 1 && !is_motion_detected) {
            is_motion_detected = 1;
            char filename[30];
            strftime(filename, sizeof(filename), "%Y%m%d%H%M%S.jpg", localtime(NULL));
            capture_image(filename);
            send_request(filename);
            usleep(DEBOUNCE_TIME);
        } else if (gpioRead(GPIO_PIN) == 0 && is_motion_detected) {
            is_motion_detected = 0;
            usleep(DEBOUNCE_TIME);
        }
        usleep(100000);
    }

    return EXIT_SUCCESS;
}
