#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define WIDTH 640
#define HEIGHT 480
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define CROP_START_X 100
#define CROP_START_Y 50
#define DEVICE "/dev/video0"
#define OUTPUT_FILE "cropped.yuv"

static int fd = -1;
static void *mem = NULL;
static struct v4l2_buffer buf;

static void cleanup_and_exit(int sig) {
    if (mem != NULL)
        munmap(mem, WIDTH * HEIGHT * 2);
    if (fd != -1)
        close(fd);
    exit(EXIT_SUCCESS);
}

int main() {
    fd = open(DEVICE, O_RDWR);
    if (fd == -1) {
        perror("open");
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        return EXIT_FAILURE;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        return EXIT_FAILURE;
    }

    struct v4l2_requestbuffers reqbufs;
    memset(&reqbufs, 0, sizeof(reqbufs));
    reqbufs.count = 1;
    reqbufs.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    reqbufs.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_REQBUFS, &reqbufs) == -1) {
        perror("VIDIOC_REQBUFS");
        return EXIT_FAILURE;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        perror("VIDIOC_QUERYBUF");
        return EXIT_FAILURE;
    }

    mem = mmap(NULL, WIDTH * HEIGHT * 2, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (mem == MAP_FAILED) {
        perror("mmap");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("VIDIOC_QBUF");
        return EXIT_FAILURE;
    }

    struct timeval timeout = { .tv_sec = 2, .tv_usec = 0 };
    fd_set fds;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    int ret = select(fd + 1, &fds, NULL, NULL, &timeout);
    if (ret == -1) {
        perror("select");
        return EXIT_FAILURE;
    }

    if (ret == 0) {
        fprintf(stderr, "Timeout\n");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("VIDIOC_DQBUF");
        return EXIT_FAILURE;
    }

    FILE *output = fopen(OUTPUT_FILE, "wb");
    if (output == NULL) {
        perror("fopen");
        return EXIT_FAILURE;
    }

    char *start = (char *)mem + CROP_START_Y * WIDTH * 2 + CROP_START_X * 2;
    for (int y = 0; y < CROP_HEIGHT; ++y) {
        if (fwrite(start + y * WIDTH * 2, 1, CROP_WIDTH * 2, output) != CROP_WIDTH * 2) {
            perror("fwrite");
            return EXIT_FAILURE;
        }
    }

    fclose(output);
    cleanup_and_exit(0);
    return EXIT_SUCCESS;
}

