#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PAN 17
#define GPIO_TILT 18
#define NEUTRAL_ANGLE 90
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define PULSE_MIN 500
#define PULSE_MAX 2500
#define PWM_HZ 50
#define DELAY_MS 100

volatile sig_atomic_t stop = 0;

void sigint_handler(int signum) {
    stop = 1;
}

void set_angle(int pan_angle, int tilt_angle) {
    if (pan_angle < MIN_ANGLE || pan_angle > MAX_ANGLE || tilt_angle < MIN_ANGLE || tilt_angle > MAX_ANGLE) {
        printf("Error: Angle out of range.\n");
        return;
    }

    int pan_pulse = PULSE_MIN + (pan_angle * (PULSE_MAX - PULSE_MIN) / MAX_ANGLE);
    int tilt_pulse = PULSE_MIN + (tilt_angle * (PULSE_MAX - PULSE_MIN) / MAX_ANGLE);

    if (piSetServoPulse(GPIO_PAN, pan_pulse) != 0 || piSetServoPulse(GPIO_TILT, tilt_pulse) != 0) {
        printf("Error: Failed to set PWM pulse.\n");
        return;
    }

    usleep(DELAY_MS * 1000);
}

int main() {
    if (piInit() != 0) {
        printf("Error: Failed to initialize pigpio.\n");
        return 1;
    }

    set_angle(NEUTRAL_ANGLE, NEUTRAL_ANGLE);

    signal(SIGINT, sigint_handler);

    char input;
    int pan_angle = NEUTRAL_ANGLE;
    int tilt_angle = NEUTRAL_ANGLE;

    while (!stop) {
        if (scanf("%c", &input) != 1) {
            printf("Error: Failed to read input.\n");
            break;
        }

        switch (input) {
            case 'q':
                stop = 1;
                break;
            case 'w':
                tilt_angle = (tilt_angle > MIN_ANGLE) ? tilt_angle - 5 : MIN_ANGLE;
                break;
            case 's':
                tilt_angle = (tilt_angle < MAX_ANGLE) ? tilt_angle + 5 : MAX_ANGLE;
                break;
            case 'a':
                pan_angle = (pan_angle > MIN_ANGLE) ? pan_angle - 5 : MIN_ANGLE;
                break;
            case 'd':
                pan_angle = (pan_angle < MAX_ANGLE) ? pan_angle + 5 : MAX_ANGLE;
                break;
            default:
                continue;
        }

        set_angle(pan_angle, tilt_angle);
    }

    set_angle(NEUTRAL_ANGLE, NEUTRAL_ANGLE);
    piStop();

    return 0;
}

