#define I2C_BUS 1
#define CPU_TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define CPU_STAT_FILE "/proc/stat"

static int i2c_fd = -1;

static const char font5x7[10][5] = {
    {0x00, 0x00, 0x00, 0x00, 0x00}, // '0'
    {0x00, 0x0F, 0x00, 0x00, 0x00}, // '1'
    //...
};

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        piI2CSend(i2c_fd, OLED_ADDR, NULL, 0);
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);

    i2c_fd = piI2COpen(I2C_BUS, OLED_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(-i2c_fd));
        return 1;
    }

    while (1) {
        char temp_str[8] = {0}, cpu_str[8] = {0};
        int temp_fd = open(CPU_TEMP_FILE, O_RDONLY);
        if (temp_fd < 0) {
            strcpy(temp_str, "Err");
        } else {
            read(temp_fd, temp_str, sizeof(temp_str));
            close(temp_fd);
        }

        int cpu_fd = open(CPU_STAT_FILE, O_RDONLY);
        if (cpu_fd < 0) {
            strcpy(cpu_str, "Err");
        } else {
            char line[128];
            read(cpu_fd, line, sizeof(line));
            close(cpu_fd);

            unsigned long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
            sscanf(line, "%*s %lu %lu %lu %lu %lu %lu %lu %lu %lu %lu",
                &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice);

            unsigned long total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
            unsigned long busy = total - idle;
            sprintf(cpu_str, "%.1f%%", (float)busy / total * 100);
        }

        for (int i = 0; i < strlen(temp_str); i++) {
            if (piI2CSend(i2c_fd, OLED_ADDR, font5x7[temp_str[i] - '0'], 5) < 0) {
                fprintf(stderr, "I2C write error\n");
                cleanup(0);
            }
        }

        for (int i = 0; i < strlen(cpu_str); i++) {
            if (piI2CSend(i2c_fd, OLED_ADDR, font5x7[cpu_str[i] - '0'], 5) < 0) {
                fprintf(stderr, "I2C write error\n");
                cleanup(0);
            }
        }

        sleep(1);
    }

    return 0;
}
```

This code initializes the I2C device on the Raspberry Pi, then enters a loop where it reads the CPU temperature and usage from the specified files, formats the values as strings, and then sends the bitmap data for each digit of the string to the OLED display. If it encounters an error while opening or reading a file, it prints an error string to the display instead of the missing value. If it encounters an error while writing to the I2C device, it prints a message to stderr, cleans up, and exits. It also implements a basic 5x7 bitmap font to render the temperature and usage text on the display. It handles the SIGINT signal to ensure that it cleans up and exits gracefully when the program is interrupted.

