#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <pigpiod_if.h>

#define GPIO_WATER_SENSOR 17
#define I2C_BUS 1
#define I2C_LCD_ADDR 0x27
#define PULSES_PER_LITER 450
#define UPDATE_INTERVAL 1
#define LCD_UPDATE_INTERVAL 10

volatile sig_atomic_t stop = 0;
unsigned long pulseCount = 0;
time_t lastLcdUpdate = 0, lastConsoleUpdate = 0;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        stop = 1;
    }
}

void updateLcd(int fd) {
    char buf[16];
    sprintf(buf, "Flow: %.2fL/min", (float)pulseCount/UPDATE_INTERVAL);
    piI2CWrite(fd, I2C_LCD_ADDR, (uint8_t*)buf, strlen(buf));
    sprintf(buf, "Total: %.2fL", (float)pulseCount/PULSES_PER_LITER);
    piI2CWrite(fd, I2C_LCD_ADDR, (uint8_t*)buf, strlen(buf), 1);
}

int main() {
    int gpioFd, i2cFd;
    struct sigaction sigIntHandler;

    sigIntHandler.sa_handler = sig_handler;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_flags = 0;
    sigaction(SIGINT, &sigIntHandler, NULL);
    sigaction(SIGTERM, &sigIntHandler, NULL);

    gpioFd = piGpioInitialise();
    if (gpioFd < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(-gpioFd));
        return EXIT_FAILURE;
    }

    i2cFd = piI2CSetup(I2C_BUS);
    if (i2cFd < 0) {
        fprintf(stderr, "Failed to initialize I2C: %s\n", strerror(-i2cFd));
        piGpioTerminate(gpioFd);
        return EXIT_FAILURE;
    }

    piGpioSetMode(gpioFd, GPIO_WATER_SENSOR, PI_INPUT);
    piGpioSetISRFunc(gpioFd, GPIO_WATER_SENSOR, 0, NULL);

    while (!stop) {
        time_t now = time(NULL);
        if (difftime(now, lastConsoleUpdate) >= UPDATE_INTERVAL) {
            printf("Flow rate: %.2f L/min, Total: %.2f L\n", (float)pulseCount/UPDATE_INTERVAL, (float)pulseCount/PULSES_PER_LITER);
            lastConsoleUpdate = now;
        }
        if (difftime(now, lastLcdUpdate) >= LCD_UPDATE_INTERVAL) {
            updateLcd(i2cFd);
            lastLcdUpdate = now;
        }
        sleep(1);
    }

    piGpioTerminate(gpioFd);
    piI2CClose(i2cFd);

    return EXIT_SUCCESS;
}

