#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <i2c.h>

#define GPIO_SENSOR 17
#define I2C_ADDR 0x27
#define I2C_BUS 1

volatile sig_atomic_t stop = 0;

void handle_sig(int sig) {
    stop = 1;
}

int main() {
    int pi = pigpio_start(0, 0);
    if (pi < 0) {
        printf("Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioCfgIntEnable(pi, GPIO_SENSOR, 1, 0, 0) < 0) {
        printf("Failed to set up GPIO interrupt\n");
        pigpio_stop(pi);
        return EXIT_FAILURE;
    }

    int fd = i2cOpen(I2C_BUS, I2C_ADDR);
    if (fd < 0) {
        printf("Failed to open I2C bus\n");
        pigpio_stop(pi);
        return EXIT_FAILURE;
    }

    if (i2cWriteByte(fd, 0x00) < 0) {
        printf("Failed to write to I2C bus\n");
        i2cClose(fd);
        pigpio_stop(pi);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sig);
    signal(SIGTERM, handle_sig);

    time_t last_pulse_time = time(NULL);
    int pulse_count = 0;
    double flow_rate = 0.0;

    while (!stop) {
        if (gpioWaitForInt(pi, GPIO_SENSOR, 1000) < 0) {
            printf("Sensor not present\n");
            i2cClose(fd);
            pigpio_stop(pi);
            return EXIT_FAILURE;
        }

        pulse_count++;
        time_t current_time = time(NULL);
        if (difftime(current_time, last_pulse_time) >= 1.0) {
            flow_rate = pulse_count * 7.5 / difftime(current_time, last_pulse_time);
            last_pulse_time = current_time;
            pulse_count = 0;

            char buffer[16];
            sprintf(buffer, "%.2f L/min", flow_rate);
            if (i2cWriteByte(fd, 0x00) < 0 || i2cWriteStr(fd, buffer) < 0) {
                printf("Failed to write to I2C bus\n");
                i2cClose(fd);
                pigpio_stop(pi);
                return EXIT_FAILURE;
            }
        }
    }

    i2cClose(fd);
    pigpio_stop(pi);
    return EXIT_SUCCESS;
}

