#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>

#define MATRIX_ROWS 8
#define MATRIX_COLS 8

struct gpiod_chip *chip;
struct gpiod_line *rows[MATRIX_ROWS];
struct gpiod_line *cols[MATRIX_COLS];

void cleanup_and_exit(int sig)
{
    for (int i = 0; i < MATRIX_ROWS; i++)
        gpiod_line_release(rows[i]);
    for (int i = 0; i < MATRIX_COLS; i++)
        gpiod_line_release(cols[i]);
    gpiod_chip_close(chip);
    exit(0);
}

int main()
{
    signal(SIGINT, cleanup_and_exit);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    for (int i = 0; i < MATRIX_ROWS; i++) {
        rows[i] = gpiod_chip_get_line(chip, 17 + i);
        if (!rows[i]) {
            perror("gpiod_chip_get_line");
            return 1;
        }
        if (gpiod_line_request_output(rows[i], "row", 0)) {
            perror("gpiod_line_request_output");
            return 1;
        }
    }

    for (int i = 0; i < MATRIX_COLS; i++) {
        cols[i] = gpiod_chip_get_line(chip, 5 + i);
        if (!cols[i]) {
            perror("gpiod_chip_get_line");
            return 1;
        }
        if (gpiod_line_request_output(cols[i], "col", 1)) {
            perror("gpiod_line_request_output");
            return 1;
        }
    }

    while (1) {
        for (int r = 0; r < MATRIX_ROWS; r++) {
            gpiod_line_set_value(rows[r], 1);
            for (int c = 0; c < MATRIX_COLS; c++) {
                gpiod_line_set_value(cols[c], r % 2 ? c : MATRIX_COLS - c - 1);
                usleep(800);
                gpiod_line_set_value(cols[c], 1);
            }
            gpiod_line_set_value(rows[r], 0);
        }
    }

    return 0;
}

