#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x4C
#define I2C_REG 0x0D

static int i2c_handle = -1;
static FILE *log_file = NULL;

void sigint_handler(int signum) {
    if (i2c_handle != -1) {
        piI2C_close(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio.\n");
        return 1;
    }

    i2c_handle = piI2C_open(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        printf("Failed to open I2C handle: %d\n", i2c_handle);
        return 1;
    }

    log_file = fopen("depth_log.csv", "a");
    if (log_file == NULL) {
        printf("Failed to open log file.\n");
        return 1;
    }

    struct tm *ts;
    time_t timer;
    char buffer[256];
    if (ftell(log_file) == 0) {
        ts = localtime(&timer);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", ts);
        fprintf(log_file, "timestamp,distance\n");
        fflush(log_file);
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        int result = piI2C_writeByte(i2c_handle, I2C_REG);
        if (result < 0) {
            printf("Failed to write to I2C: %d\n", result);
            fprintf(log_file, "%s,-1\n", buffer);
            fflush(log_file);
            continue;
        }

        unsigned char data[2];
        result = piI2C_readBytes(i2c_handle, data, 2);
        if (result < 0) {
            printf("Failed to read from I2C: %d\n", result);
            fprintf(log_file, "%s,-1\n", buffer);
            fflush(log_file);
            continue;
        }

        int distance = (data[0] << 8) | data[1];
        timer = time(NULL);
        ts = localtime(&timer);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", ts);
        fprintf(log_file, "%s,%d\n", buffer, distance);
        fflush(log_file);

        sleep(0.1);
    }

    return 0;
}

