#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <pigpiod_if.h>

#define SENSOR_ADDR 0x60
#define PART_ID_REG 0x00
#define COMMAND_REG 0x18
#define EXPECTED_PART_ID 0x45

FILE *log_file;
int i2c_handle;

void sigint_handler(int signum) {
    piI2CSimpleClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    i2c_handle = piI2CSetSlaveAddress(1, SENSOR_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(-i2c_handle));
        return 1;
    }

    int part_id = piI2CReadWord(i2c_handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Failed to read PART ID: %s\n", strerror(-part_id));
        return 1;
    }

    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected PART ID: 0x%02x\n", part_id);
        return 1;
    }

    if (piI2CWriteWord(i2c_handle, COMMAND_REG, 0x0000) < 0) {
        fprintf(stderr, "Failed to write to command register\n");
        return 1;
    }

    log_file = fopen("biometric_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        int light_data = piI2CReadWord(i2c_handle, 0x20);
        if (light_data < 0) {
            fprintf(stderr, "Failed to read light data: %s\n", strerror(-light_data));
            continue;
        }

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

        fprintf(log_file, "%s, %d\n", timestamp, light_data);
        fflush(log_file);

        usleep(500000);
    }

    return 0;
}

