#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP_NAME1 "gpiochip4"
#define GPIO_CHIP_NAME2 "gpiochip0"
#define GPIO_LINE_NUMBER_SENSOR 4
#define GPIO_LINE_NUMBER_LED 17
#define POLL_INTERVAL_MS 100

struct gpiod_chip *chip = NULL;
struct gpiod_line *sensor_line = NULL, *led_line = NULL;
FILE *log_file = NULL;

void cleanup_and_exit(int signum) {
    if (sensor_line)
        gpiod_line_release(sensor_line);
    if (led_line)
        gpiod_line_release(led_line);
    if (chip)
        gpiod_chip_close(chip);
    if (log_file)
        fclose(log_file);
    printf("Exiting...\n");
    exit(signum);
}

int main() {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME1);
    if (!chip) {
        chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME2);
        if (!chip) {
            fprintf(stderr, "Failed to open GPIO chip\n");
            return EXIT_FAILURE;
        }
    }

    sensor_line = gpiod_chip_get_line(chip, GPIO_LINE_NUMBER_SENSOR);
    if (!sensor_line) {
        fprintf(stderr, "Failed to get sensor line\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(sensor_line, "sensor")) {
        fprintf(stderr, "Failed to request sensor line\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    led_line = gpiod_chip_get_line(chip, GPIO_LINE_NUMBER_LED);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(led_line, "led", 0)) {
        fprintf(stderr, "Failed to request LED line\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    log_file = fopen("proximity.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    int sensor_value = gpiod_line_get_value(sensor_line);
    while (1) {
        usleep(POLL_INTERVAL_MS * 1000);

        int new_sensor_value = gpiod_line_get_value(sensor_line);
        if (new_sensor_value < 0) {
            fprintf(stderr, "Failed to read sensor value\n");
            cleanup_and_exit(EXIT_FAILURE);
        }

        if (new_sensor_value == 0 && sensor_value == 1) {
            char timestamp[30];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%FT%TZ", gmtime(&now));
            fprintf(log_file, "%s Object detected\n", timestamp);
            fflush(log_file);

            gpiod_line_set_value(led_line, 1);
            usleep(100 * 1000);
            gpiod_line_set_value(led_line, 0);
        }

        sensor_value = new_sensor_value;
    }

    cleanup_and_exit(EXIT_SUCCESS);
}

