#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60

#define REG_PART_ID 0x00
#define EXPECTED_PART_ID 0x45

#define REG_HW_KEY 0x07
#define HW_KEY_VALUE 0x17

#define REG_CH_LIST 0x4F
#define CH_LIST_VALUE 0x03

#define REG_MEAS_RATE 0x4E
#define MEAS_RATE_VALUE 0x01

#define REG_COMMAND 0x30
#define CMD_ALS_FORCE 0x06
#define CMD_PS_FORCE 0x07

#define REG_PS1_DATA 0x18
#define REG_ALS_VIS_DATA 0x22

FILE *log_file;
int i2c_handle;

void sigint_handler(int signo) {
    fclose(log_file);
    gpioI2CBusDisable(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio.\n");
        return 1;
    }

    i2c_handle = gpioI2CSetSlaveAddress(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        printf("Failed to set I2C slave address.\n");
        return 1;
    }

    log_file = fopen("biometric_data.log", "w");
    if (log_file == NULL) {
        printf("Failed to open log file.\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    if (gpioI2CWriteByteData(i2c_handle, REG_HW_KEY, HW_KEY_VALUE) < 0) {
        printf("Failed to write to HW_KEY register.\n");
        return 1;
    }

    if (gpioI2CWriteByteData(i2c_handle, REG_CH_LIST, CH_LIST_VALUE) < 0) {
        printf("Failed to write to CH_LIST register.\n");
        return 1;
    }

    if (gpioI2CWriteByteData(i2c_handle, REG_MEAS_RATE, MEAS_RATE_VALUE) < 0) {
        printf("Failed to write to MEAS_RATE register.\n");
        return 1;
    }

    while (1) {
        int part_id = gpioI2CReadByteData(i2c_handle, REG_PART_ID);
        if (part_id < 0) {
            printf("Failed to read PART_ID register.\n");
            return 1;
        }

        if (part_id != EXPECTED_PART_ID) {
            printf("Unexpected sensor type.\n");
            return 1;
        }

        if (gpioI2CWriteByteData(i2c_handle, REG_COMMAND, CMD_ALS_FORCE) < 0) {
            printf("Failed to write to COMMAND register (ALS_FORCE).\n");
            return 1;
        }

        if (gpioI2CWriteByteData(i2c_handle, REG_COMMAND, CMD_PS_FORCE) < 0) {
            printf("Failed to write to COMMAND register (PS_FORCE).\n");
            return 1;
        }

        int ps1_data = gpioI2CReadWordData(i2c_handle, REG_PS1_DATA);
        if (ps1_data < 0) {
            printf("Failed to read PS1 data.\n");
            return 1;
        }

        int als_vis_data = gpioI2CReadWordData(i2c_handle, REG_ALS_VIS_DATA);
        if (als_vis_data < 0) {
            printf("Failed to read ALS_VIS data.\n");
            return 1;
        }

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

        fprintf(log_file, "%s,%d,%d\n", timestamp, ps1_data, als_vis_data);
        fflush(log_file);

        sleep(1);
    }

    return 0;
}

