#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_GPIO 17
#define ECHO_GPIO 27
#define TIMEOUT_US 30000
#define MIN_DISTANCE_CM 2
#define MAX_DISTANCE_CM 400
#define REMINDER_DISTANCE_CM 15
#define LOG_FILE "distance_log.txt"
#define POLL_INTERVAL_SEC 60

struct gpiod_line *trigger_line;
struct gpiod_line *echo_line;
FILE *log_file;

void log_entry(const char *message, int distance) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
    fprintf(log_file, "%s: %s (%d cm)\n", timestamp, message, distance);
    fflush(log_file);
}

void sig_handler(int signum) {
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    fclose(log_file);
    exit(signum);
}

int main() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line_request_config req_config = {
        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_DISABLE,
        .consumer = "Ultrasonic Sensor",
        .type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
        .default_val = 0,
    };

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_GPIO);
    if (!trigger_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    ret = gpiod_line_request(trigger_line, &req_config);
    if (ret) {
        perror("gpiod_line_request");
        return 1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_GPIO);
    if (!echo_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    req_config.type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    ret = gpiod_line_request(echo_line, &req_config);
    if (ret) {
        perror("gpiod_line_request");
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        struct timespec start, end;
        long long duration_ns;
        int distance = -1;

        gpiod_line_set_value(trigger_line, 1);
        usleep(10);
        gpiod_line_set_value(trigger_line, 0);

        clock_gettime(CLOCK_MONOTONIC, &start);
        ret = gpiod_line_wait_for_rising_edge(echo_line, TIMEOUT_US);
        if (ret < 0) {
            log_entry("Echo never rises", distance);
            continue;
        }

        clock_gettime(CLOCK_MONOTONIC, &end);
        duration_ns = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);
        if (duration_ns > TIMEOUT_US * 1000) {
            log_entry("Echo stuck high", distance);
            continue;
        }

        distance = (int)((double)duration_ns / 1000 / 1000 * 34300 / 2);
        if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
            log_entry("Invalid distance", distance);
            continue;
        }

        log_entry("Measured distance", distance);
        if (distance < REMINDER_DISTANCE_CM) {
            log_entry("Time to water the plant!", distance);
        }

        sleep(POLL_INTERVAL_SEC);
    }

    return 0;
}

