#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x39
#define I2C_HANDLE -1
#define I2C_TIMEOUT 1000
#define SLEEP_MS 100
#define PROXIMITY_THRESHOLD 200

volatile sig_atomic_t stop = 0;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        stop = 1;
    }
}

int main() {
    FILE *csv_file = fopen("color_proximity_log.csv", "w");
    if (csv_file == NULL) {
        printf("Failed to open CSV file for writing.\n");
        return 1;
    }

    int i2c_handle = I2C_HANDLE;
    while (!stop) {
        if (i2c_handle == I2C_HANDLE) {
            i2c_handle = piI2C(I2C_BUS, I2C_ADDR, I2C_TIMEOUT);
            if (i2c_handle == I2C_HANDLE) {
                printf("Failed to open I2C bus.\n");
                continue;
            }

            int id = piI2CReadByteData(i2c_handle, 0x92);
            if (id != 0xAB) {
                printf("Invalid sensor ID.\n");
                piI2CSetHandle(I2C_HANDLE);
                i2c_handle = I2C_HANDLE;
                continue;
            }

            if (piI2CWriteByteData(i2c_handle, 0x80, 0x03) != 0 ||
                piI2CWriteByteData(i2c_handle, 0x81, 0xDB) != 0 ||
                piI2CWriteByteData(i2c_handle, 0x83, 0xF6) != 0 ||
                piI2CWriteByteData(i2c_handle, 0x8E, 0x87) != 0 ||
                piI2CWriteByteData(i2c_handle, 0xF1, 0x03) != 0 ||
                piI2CWriteByteData(i2c_handle, 0x90, 0x01) != 0) {
                printf("Failed to write to sensor.\n");
                piI2CSetHandle(I2C_HANDLE);
                i2c_handle = I2C_HANDLE;
                continue;
            }
        }

        int proximity = piI2CReadByteData(i2c_handle, 0x9C);
        if (proximity > PROXIMITY_THRESHOLD) {
            int r = piI2CReadWordData(i2c_handle, 0x96);
            int g = piI2CReadWordData(i2c_handle, 0x98);
            int b = piI2CReadWordData(i2c_handle, 0x9A);

            time_t now = time(NULL);
            struct tm *timeinfo = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            fprintf(csv_file, "%s,%d,%d,%d,%d\n", timestamp, proximity, r, g, b);
        }

        if (stop) break;
        sleep(SLEEP_MS / 1000.0);
    }

    fclose(csv_file);
    piI2CSetHandle(I2C_HANDLE);
    piGpioInitialise();

    return 0;
}

int main_init() {
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    if (piGpioInitialise() < 0) {
        printf("Failed to initialize pigpio.\n");
        return 1;
    }

    return 0;
}

int main_cleanup() {
    piGpioTerminate();
    return 0;
}

int main(int argc, char *argv[]) {
    if (main_init() != 0) {
        return 1;
    }

    int result = main_loop();

    main_cleanup();

    return result;
}

