#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/i2c.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_SLAVE_ADDRESS 0x5A
#define SI1182_PART_ID 0x1182
#define MEAS_RATE0_REG 0x08
#define COMMAND_REG 0x47
#define PS_DATA0_REG 0x24
#define PS_DATA1_REG 0x25
#define SAMPLE_RATE 100

volatile sig_atomic_t running = true;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        running = false;
    }
}

int main() {
    int fd, ret;
    struct i2c_msg msgs[2];
    char buffer[2];
    FILE *csv_file;
    struct tm *ts;
    time_t t;
    char timestamp[20];

    fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    ret = ioctl(fd, I2C_SLAVE, I2C_SLAVE_ADDRESS);
    if (ret < 0) {
        perror("ioctl");
        return 1;
    }

    buffer[0] = 0x00;
    msgs[0].addr = I2C_SLAVE_ADDRESS;
    msgs[0].flags = 0;
    msgs[0].len = 1;
    msgs[0].buf = buffer;

    ret = i2c_smbus_read_word_data(fd, 0x00);
    if (ret < 0) {
        perror("i2c_smbus_read_word_data");
        return 1;
    } else if (ret != SI1182_PART_ID) {
        fprintf(stderr, "Unexpected part ID: %04x\n", ret);
        return 1;
    }

    buffer[0] = 0x08;
    buffer[1] = 0x01;
    msgs[1].addr = I2C_SLAVE_ADDRESS;
    msgs[1].flags = 0;
    msgs[1].len = 2;
    msgs[1].buf = buffer;

    buffer[0] = 0x47;
    buffer[1] = 0x00;
    msgs[2].addr = I2C_SLAVE_ADDRESS;
    msgs[2].flags = 0;
    msgs[2].len = 2;
    msgs[2].buf = buffer;

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    csv_file = fopen("heartrate.csv", "w");
    if (csv_file == NULL) {
        perror("fopen");
        return 1;
    }

    while (running) {
