#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define GPIO 17

static int i2c_handle = -1;
static FILE *log_file = NULL;

static void cleanup_and_exit(int sig) {
    if (i2c_handle != -1) {
        piI2CClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (sig == SIGINT) {
        printf("\nShutdown on SIGINT\n");
    }
    gpioTerminate();
    exit(sig);
}

static void check_i2c_transaction(int result) {
    if (result < 0) {
        printf("I2C transaction failed: %d\n", result);
        cleanup_and_exit(-1);
    }
}

static void check_sensor_presence() {
    int present = piI2CReadByteData(i2c_handle, 0x00);
    if (present < 0) {
        printf("Sensor not present\n");
        cleanup_and_exit(-1);
    }
}

static void trigger_single_measurement() {
    int result = piI2CWriteByteData(i2c_handle, 0x00, 0x01);
    check_i2c_transaction(result);
}

static int wait_for_interrupt(int timeout_ms) {
    int start_ms = millis();
    while (1) {
        int interrupt_status = piI2CReadByteData(i2c_handle, 0x13);
        if (interrupt_status < 0) {
            check_i2c_transaction(interrupt_status);
        } else if (interrupt_status & 0x01) {
            return 0;
        } else if (millis() - start_ms > timeout_ms) {
            return -1;
        }
        usleep(1000);
    }
}

static void clear_interrupt() {
    int result = piI2CWriteByteData(i2c_handle, 0x0B, 0x01);
    check_i2c_transaction(result);
}

static int read_distance() {
    unsigned char buf[14];
    int result = piI2CReadI2CBlockData(i2c_handle, 0x14, 14, buf);
    check_i2c_transaction(result);
    return (buf[10] << 8) | buf[11];
}

static void log_distance(int distance) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%d\n", timestamp, distance);
    fflush(log_file);
}

int main() {
    signal(SIGINT, cleanup_and_exit);

    int pi_result = gpioInitialise();
    if (pi_result < 0) {
        printf("gpioInitialise failed: %d\n", pi_result);
        return -1;
    }

    int gpio_result = gpioSetPullUpDown(GPIO, PI_PUD_UP);
    if (gpio_result < 0) {
        printf("gpioSetPullUpDown failed: %d\n", gpio_result);
        cleanup_and_exit(-1);
    }

    i2c_handle = piI2CSetup(I2C_BUS);
    if (i2c_handle < 0) {
        printf("piI2CSetup failed: %d\n", i2c_handle);
        cleanup_and_exit(-1);
    }

    int result = piI2CSetSlaveAddress(i2c_handle, I2C_ADDR);
    if (result < 0) {
        printf("piI2CSetSlaveAddress failed: %d\n", result);
        cleanup_and_exit(-1);
    }

    check_sensor_presence();

    log_file = fopen("distance_log.txt", "w");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        cleanup_and_exit(-1);
    }

    while (1) {
        trigger_single_measurement();
        int interrupt_result = wait_for_interrupt(100);
        if (interrupt_result < 0) {
            printf("Timeout waiting for interrupt\n");
            continue;
        }
        clear_interrupt();
        int distance = read_distance();
        log_distance(distance);
    }

    return 0;
}

