int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize GPIO");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_SENSOR1, PI_INPUT) < 0) {
        log_error("Failed to set sensor 1 GPIO mode");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_SENSOR2, PI_INPUT) < 0) {
