#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define LED_PIN 17
#define I2C_BUS 1
#define I2C_ADDR 0x6A

FILE *log_file;
int i2c_handle;

void cleanup_and_exit(int sig) {
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) gpioI2Cunexport(i2c_handle);
    gpioTerminate();
    exit(sig);
}

int main() {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("distance_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    i2c_handle = gpioI2Csetup(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to setup I2C.\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    if (gpioCfgOut(LED_PIN) < 0) {
        fprintf(stderr, "Failed to setup GPIO output.\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    while (1) {
        int distance;
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);

        if (gpioI2Cread(i2c_handle, &distance, sizeof(distance)) < 0) {
            fprintf(stderr, "Failed to read from sensor.\n");
            cleanup_and_exit(EXIT_FAILURE);
        }

        fprintf(log_file, "%ld.%09ld: %d cm\n", ts.tv_sec, ts.tv_nsec, distance);
        fflush(log_file);

        if (distance < 20) {
            gpioWrite(LED_PIN, 1);
        } else {
            gpioWrite(LED_PIN, 0);
        }

        sleep(100);
    }

    cleanup_and_exit(EXIT_SUCCESS);
}

