    if (argc > 1) {
        threshold = atoi(argv[1]);
    }

    signal(SIGINT, cleanup);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    i2c_handle = piI2C_open(1, ICU_20201_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return EXIT_FAILURE;
    }

    int who_am_i = piI2C_readByteData(i2c_handle, ICU_20201_WHO_AM_I);
    if (who_am_i < 0 || who_am_i != ICU_20201_WHO_AM_I_VALUE) {
        fprintf(stderr, "ICU-20201 not found at address 0x%02X: %d\n", ICU_20201_ADDR, who_am_i);
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_PIN);
        return EXIT_FAILURE;
    }

    log_file = fopen("tof_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    while (1) {
        int distance = piI2C_readWordData(i2c_handle, 0x10);
        if (distance < 0) {
            fprintf(stderr, "Failed to read distance: %d\n", distance);
            continue;
        }

        time_t now = time(NULL);
        struct tm *local_time = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", local_time);

        fprintf(log_file, "%s: %d\n", timestamp, distance);
        fflush(log_file);

        if (distance < threshold) {
            gpioWrite(LED_PIN, PI_HIGH);
        } else {
            gpioWrite(LED_PIN, PI_LOW);
        }

        sleep(50);
    }

    return EXIT_SUCCESS;
}

