#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SENSOR_ADDRESS 0x50
#define SAMPLE_COUNT 10
#define COMMAND_FRAME_SIZE 4
#define RESPONSE_FRAME_SIZE 15
#define DISTANCE_OFFSET 11

int i2c_file_descriptor = -1;
FILE *log_file = NULL;

void handle_sigint(int signum) {
    if (i2c_file_descriptor != -1) {
        close(i2c_file_descriptor);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    signal(SIGINT, handle_sigint);

    int i2c_bus = 1;
    i2c_file_descriptor = open("/dev/i2c-1", O_RDWR);
    if (i2c_file_descriptor < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_file_descriptor, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        return EXIT_FAILURE;
    }

    unsigned char command_frame[COMMAND_FRAME_SIZE] = {0x50, 0x0A, 0x00, 0x01};
    unsigned char response_frame[RESPONSE_FRAME_SIZE];

    while (1) {
        if (write(i2c_file_descriptor, command_frame, COMMAND_FRAME_SIZE) != COMMAND_FRAME_SIZE) {
            perror("Failed to write to I2C device");
            return EXIT_FAILURE;
        }

        usleep(10000);  // Wait 10 ms

        if (read(i2c_file_descriptor, response_frame, RESPONSE_FRAME_SIZE) != RESPONSE_FRAME_SIZE) {
            perror("Failed to read from I2C device");
            return EXIT_FAILURE;
        }

        if (response_frame[0] != 0x50) {
            fprintf(stderr, "Invalid response frame header\n");
            continue;
        }

        int distance = (response_frame[DISTANCE_OFFSET] << 8) | response_frame[DISTANCE_OFFSET + 1];

        if (distance < 1000) {
            if (log_file == NULL) {
                log_file = fopen("intrusion_log.txt", "a");
                if (log_file == NULL) {
                    perror("Failed to open log file");
                    return EXIT_FAILURE;
                }
            }

            time_t now = time(NULL);
            struct tm *local_time = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", local_time);

            fprintf(log_file, "%s: Intrusion detected at distance %d mm\n", timestamp, distance);
        }

        usleep(100000);  // Wait 100 ms
    }

    return EXIT_SUCCESS;
}

