#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29

#define REG_MODEL_ID 0xC0
#define EXPECTED_MODEL_ID 0xEE

#define REG_SYSRANGE_START 0x00
#define SYSRANGE_START_VALUE 0x01

#define REG_RESULT_INTERRUPT_STATUS 0x13
#define REG_RESULT_RANGE_STATUS 0x14

#define REG_SYSTEM_INTERRUPT_CLEAR 0x0B
#define SYSTEM_INTERRUPT_CLEAR_VALUE 0x01

static int i2c_handle = -1;

void sig_handler(int signo) {
    if (i2c_handle != -1) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(signo);
}

int main() {
    int pi, r, model_id;
    unsigned char buf[2];
    struct timespec ts;

    pi = gpioInitialise();
    if (pi < 0) {
        printf("gpioInitialise() failed: %s\n", strerror(errno));
        return pi;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        printf("i2cOpen() failed: %s\n", strerror(errno));
        return i2c_handle;
    }

    r = i2cReadByteData(i2c_handle, REG_MODEL_ID);
    if (r < 0) {
        printf("i2cReadByteData() failed: %s\n", strerror(errno));
        return r;
    }
    model_id = r;
    if (model_id != EXPECTED_MODEL_ID) {
        printf("Unexpected model ID: 0x%02X\n", model_id);
        return -1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        buf[0] = SYSRANGE_START_VALUE;
        r = i2cWrite(i2c_handle, REG_SYSRANGE_START, buf, 1);
        if (r < 0) {
            fprintf(stderr, "i2cWrite() failed: %s\n", strerror(errno));
            continue;
        }

        ts.tv_sec = 0;
        ts.tv_nsec = 100000000;  // 100 ms
        do {
            r = i2cReadByteData(i2c_handle, REG_RESULT_INTERRUPT_STATUS);
            if (r < 0) {
                fprintf(stderr, "i2cReadByteData() failed: %s\n", strerror(errno));
                break;
            }
            nanosleep(&ts, NULL);
        } while ((r & 1) == 0);

        if ((r & 1) == 0) {
            fprintf(stderr, "Range measurement timed out\n");
            continue;
        }

        r = i2cRead(i2c_handle, REG_RESULT_RANGE_STATUS, buf, 2);
        if (r < 0) {
            fprintf(stderr, "i2cRead() failed: %s\n", strerror(errno));
            continue;
        }

        buf[0] = SYSTEM_INTERRUPT_CLEAR_VALUE;
        r = i2cWrite(i2c_handle, REG_SYSTEM_INTERRUPT_CLEAR, buf, 1);
        if (r < 0) {
            fprintf(stderr, "i2cWrite() failed: %s\n", strerror(errno));
        }

        time_t now = time(NULL);
        struct tm *tm_now = localtime(&now);
        printf("%04d-%02d-%02d %02d:%02d:%02d Distance: %d mm\n",
               tm_now->tm_year + 1900, tm_now->tm_mon + 1, tm_now->tm_mday,
               tm_now->tm_hour, tm_now->tm_min, tm_now->tm_sec,
               buf[0] | (buf[1] << 8));

        ts.tv_sec = 0;
        ts.tv_nsec = 500000000;  // 500 ms
        nanosleep(&ts, NULL);
    }

    return 0;
}

