#define MLX75030_ADDR 0x4C
#define MLX75030_REG_DISTANCE 0x00
#define MLX75030_COUNT_TO_MM 0.125

static int fd = -1;

void cleanup(int signum) {
    if (fd != -1) {
        close(fd);
    }
    printf("Exiting...\n");
    exit(0);
}

int main(void) {
    struct sigaction action;
    struct timespec ts;
    uint16_t distance;

    memset(&action, 0, sizeof(action));
    action.sa_handler = cleanup;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        fprintf(stderr, "Failed to set slave address: %s\n", strerror(errno));
        cleanup(0);
        return 1;
    }

    while (1) {
        if (read(fd, &distance, sizeof(distance)) != sizeof(distance)) {
            fprintf(stderr, "Failed to read distance: %s\n", strerror(errno));
        } else {
            printf("Distance: %.2f mm\n", (double)distance * MLX75030_COUNT_TO_MM);
        }

        ts.tv_sec = 0;
        ts.tv_nsec = 500000000;
        nanosleep(&ts, NULL);
    }

    return 0;
}

