        return EXIT_FAILURE;
    }

    i2c_handle = piI2C_open(1, OPT3101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", piI2C_error_text(i2c_handle));
        return EXIT_FAILURE;
    }

    while (!stop) {
        int distance, ambient, status;

        if (piI2C_read_device(i2c_handle, OPT3101_REG_DISTANCE, &distance, 2) != 2) {
            fprintf(stderr, "Failed to read distance: %s\n", piI2C_error_text(i2c_handle));
            return EXIT_FAILURE;
