        if (piI2C_read_device(i2c_handle, OPT3101_REG_AMBIENT, &ambient, 2) != 2) {
            fprintf(stderr, "Failed to read ambient: %s\n", piI2C_error_text(i2c_handle));
            return EXIT_FAILURE;
