#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TIMEOUT 200000 // 200 ms

volatile sig_atomic_t shutdown = 0;

void handle_signal(int signum) {
    shutdown = 1;
}

int main() {
    if (gpioInitialise() == PI_INIT_FAILED) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!shutdown) {
        gpioWrite(TRIGGER_PIN, 1);
        delay(10); // 10 microsecond trigger pulse
        gpioWrite(TRIGGER_PIN, 0);

        int tick = gpioTick();
        int level = gpioRead(ECHO_PIN);

        if (level != 1) {
            fprintf(stderr, "Echo line did not rise.\n");
            continue;
        }

        int rising_edge = gpioWaitForLevel(ECHO_PIN, 1, TIMEOUT);
        if (rising_edge == 0) {
            fprintf(stderr, "Echo rising edge timeout.\n");
            continue;
        }

        int falling_edge = gpioWaitForLevel(ECHO_PIN, 0, TIMEOUT);
        if (falling_edge == 0) {
            fprintf(stderr, "Echo falling edge timeout.\n");
            continue;
        }

        int pulse_us = gpioTick() - tick;
        if (pulse_us <= 0 || pulse_us > 38000) {
            fprintf(stderr, "Invalid pulse duration: %d us.\n", pulse_us);
            continue;
        }

        double distance_cm = (pulse_us * 0.0343) / 2;
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        printf("Distance: %.2f cm at %ld.%09lds\n", distance_cm, ts.tv_sec, ts.tv_nsec);

        sleep(1); // Once per second
    }

    gpioTerminate();

    return EXIT_SUCCESS;
}

