#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <termios.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define LED_PIN 17
#define DISTANCE_THRESHOLD 1.0
#define LOG_FILE "intrusion_log.csv"

int uart_fd = -1;
FILE *log_file = NULL;

void cleanup_and_exit(int signum) {
    if (uart_fd != -1) close(uart_fd);
    if (log_file != NULL) fclose(log_file);
    gpioTerm();
    printf("Exiting...\n");
    exit(signum);
}

void handle_error(const char *msg) {
    perror(msg);
    cleanup_and_exit(-1);
}

void init_uart() {
    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd < 0) handle_error("open UART");

    struct termios options;
    if (tcgetattr(uart_fd, &options) < 0) handle_error("tcgetattr");

    options.c_cflag |= (CS8 | CREAD | CLOCAL);
    options.c_ispeed = BAUD_RATE;
    options.c_ospeed = BAUD_RATE;

    if (tcsetattr(uart_fd, TCSANOW, &options) < 0) handle_error("tcsetattr");
}

void init_gpio() {
    if (gpioInitialise() < 0) handle_error("gpioInitialise");
    gpioSetMode(LED_PIN, PI_OUTPUT);
}

void init_log_file() {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) handle_error("fopen");
}

void intrusion_alert(float distance) {
    gpioWrite(LED_PIN, PI_ON);
    sleep(2);
    gpioWrite(LED_PIN, PI_OFF);

    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", local_time);

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file);
}

void check_sensor_data(unsigned short *data) {
    for (int i = 0; i < 64; i++) {
        float distance = i * 0.0486;
        if (data[i] != 0 && distance <= DISTANCE_THRESHOLD) {
            intrusion_alert(distance);
            break;
        }
    }
}

int main() {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    init_uart();
    init_gpio();
    init_log_file();

    unsigned char buffer[136];
    unsigned short data[64];

    while (1) {
        ssize_t bytes_read = read(uart_fd, buffer, sizeof(buffer));
        if (bytes_read < 0) handle_error("read");
        if (bytes_read != sizeof(buffer)) continue;

        if (memcmp(buffer, "\x02\x01\x04\x03\x06\x05\x08\x07", 8) != 0) continue;

        for (int i = 0; i < 64; i++) {
            data[i] = buffer[8 + 2 * i] | (buffer[9 + 2 * i] << 8);
        }

        check_sensor_data(data);
    }

    return 0;
}

