#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <pigpiod_if.h>

#define I2C_BUS 1
#define I2C_ADDR 0x69
#define GPIO_ALERT 17
#define MIN_DISTANCE 10.0
#define SAMPLE_INTERVAL 100

static int pi_h;
static int i2c_h;
static FILE *log_file;

static void cleanup_and_exit(int sig) {
    if (i2c_h >= 0) {
        piI2C_close(pi_h, i2c_h);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(sig);
}

int main() {
    struct sigaction action;
    action.sa_handler = cleanup_and_exit;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    pi_h = gpioInitialise();
    if (pi_h <= 0) {
        fprintf(stderr, "gpioInitialise() failed\n");
        cleanup_and_exit(-1);
    }

    i2c_h = piI2C_open(pi_h, I2C_BUS, I2C_ADDR);
    if (i2c_h < 0) {
        fprintf(stderr, "piI2C_open() failed\n");
        cleanup_and_exit(-1);
    }

    log_file = fopen("distance_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "fopen() failed\n");
        cleanup_and_exit(-1);
    }

    gpioSetAlert(GPIO_ALERT, 0, 0);

    while (1) {
        int status;
        uint16_t high, low;
        uint32_t distance;
        struct tm *timeinfo;
        char timestamp[20];

        time_t now = time(NULL);
        timeinfo = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

        status = piI2C_read(pi_h, i2c_h, 0x31, &high, 1);
        if (status < 0) {
            fprintf(stderr, "piI2C_read() failed\n");
            cleanup_and_exit(-1);
        }

        status = piI2C_read(pi_h, i2c_h, 0x32, &low, 1);
        if (status < 0) {
            fprintf(stderr, "piI2C_read() failed\n");
            cleanup_and_exit(-1);
        }

        distance = (high << 8) | low;

        fprintf(log_file, "%s %u\n", timestamp, distance);
        fflush(log_file);

        if (distance < MIN_DISTANCE) {
            gpioSetAlert(GPIO_ALERT, 1, 0);
        }

        usleep(SAMPLE_INTERVAL * 1000);
    }

    return 0;
}

