#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define I2C_TIMEOUT 100
#define SLEEP_TIME 100000
#define DISTANCE_THRESHOLD_STOP 300
#define DISTANCE_THRESHOLD_APPROACH 600
#define DISTANCE_THRESHOLD_SLOW 1200

static int i2c_h;
static FILE *log_file;

static void cleanup_and_exit(int sig) {
    if (i2c_h >= 0) {
        if (i2cClose(i2c_h) < 0) {
            fprintf(stderr, "Failed to close I2C device: %s\n", strerror(errno));
        }
    }
    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Failed to close log file: %s\n", strerror(errno));
        }
    }
    if (piGpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", strerror(errno));
    }
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    if (piGpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    i2c_h = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_h < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        cleanup_and_exit(0);
    }

    log_file = fopen("distance_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup_and_exit(0);
    }
    fprintf(log_file, "timestamp,distance_mm\n");

    uint8_t model_id[2];
    if (i2cReadWord(i2c_h, 0x010F, model_id, sizeof(model_id), I2C_TIMEOUT) < 0) {
        fprintf(stderr, "Failed to read model ID: %s\n", strerror(errno));
        cleanup_and_exit(0);
    }
    if (model_id[0] != 0xEA) {
        fprintf(stderr, "Unexpected model ID: 0x%02X\n", model_id[0]);
        cleanup_and_exit(0);
    }

    uint8_t reset[2] = {0x00, 0x00};
    if (i2cWriteWord(i2c_h, 0x0000, reset, sizeof(reset), I2C_TIMEOUT) < 0) {
        fprintf(stderr, "Failed to write reset: %s\n", strerror(errno));
        cleanup_and_exit(0);
    }
    usleep(SLEEP_TIME);

    uint8_t mode[2] = {0x01, 0x00};
    if (i2cWriteWord(i2c_h, 0x0007, mode, sizeof(mode), I2C_TIMEOUT) < 0) {
        fprintf(stderr, "Failed to write mode: %s\n", strerror(errno));
        cleanup_and_exit(0);
    }

    while (1) {
        uint8_t status[2];
        if (i2cReadWord(i2c_h, 0x013, status, sizeof(status), I2C_TIMEOUT) < 0) {
            fprintf(stderr, "Failed to read status: %s\n", strerror(errno));
            cleanup_and_exit(0);
        }
        if ((status[1] & 0x01) == 0x01) {
            uint8_t distance[2];
            if (i2cReadWord(i2c_h, 0x078, distance, sizeof(distance), I2C_TIMEOUT) < 0) {
                fprintf(stderr, "Failed to read distance: %s\n", strerror(errno));
                cleanup_and_exit(0);
            }
            uint16_t distance_mm = (distance[0] << 8) | distance[1];
            fprintf(log_file, "%ld,%u\n", time(NULL), distance_mm);
            fflush(log_file);

            if (distance_mm < DISTANCE_THRESHOLD_STOP) {
                printf("STOP\n");
            } else if (distance_mm < DISTANCE_THRESHOLD_APPROACH) {
                printf("APPROACH\n");
            } else if (distance_mm < DISTANCE_THRESHOLD_SLOW) {
                printf("SLOW\n");
            } else {
                printf("CLEAR\n");
            }

            uint8_t clear[2] = {0x01, 0x00};
            if (i2cWriteWord(i2c_h, 0x014, clear, sizeof(clear), I2C_TIMEOUT) < 0) {
                fprintf(stderr, "Failed to clear interrupt: %s\n", strerror(errno));
                cleanup_and_exit(0);
            }
        }
        usleep(SLEEP_TIME);
    }

    cleanup_and_exit(0);
}

