#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x45
#define GPIO_LED 18
#define GPIO_SDA 2
#define GPIO_SCL 3
#define I2C_RETRIES 3
#define I2C_DELAY 10000
#define MIN_DISTANCE 50
#define MAX_DISTANCE 500
#define MIN_FREQUENCY 10
#define MAX_FREQUENCY 1

static int i2c_handle = -1;
static int led_state = 0;

void shutdown_handler(int signum) {
    if (i2c_handle >= 0) {
        piI2CClose(i2c_handle);
    }
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (gpioCfgIntern(GPIO_LED, PI_CFG_OUTPUT) < 0) {
        fprintf(stderr, "Failed to configure LED GPIO\n");
        return 1;
    }

    if (gpioCfgIntern(GPIO_SDA, PI_CFG_INPUT) < 0 || gpioCfgIntern(GPIO_SCL, PI_CFG_INPUT) < 0) {
        fprintf(stderr, "Failed to configure I2C GPIO\n");
        return 1;
    }

    i2c_handle = piI2COpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    signal(SIGINT, shutdown_handler);
    signal(SIGTERM, shutdown_handler);

    while (1) {
        int distance = 0;
        int retries = 0;
        while (retries < I2C_RETRIES) {
            if (piI2CReadByteData(i2c_handle, 0x00, &distance) == 0) {
                break;
            }
            usleep(I2C_DELAY);
            retries++;
        }

        if (retries == I2C_RETRIES) {
            fprintf(stderr, "Failed to read distance\n");
            shutdown_handler(0);
            return 1;
        }

        int frequency = MIN_FREQUENCY + (MAX_FREQUENCY - MIN_FREQUENCY) * (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE);
        if (frequency < MIN_FREQUENCY) {
            frequency = MIN_FREQUENCY;
        } else if (frequency > MAX_FREQUENCY) {
            frequency = MAX_FREQUENCY;
        }

        printf("Distance: %d, Blink frequency: %d\n", distance, frequency);

        led_state = !led_state;
        gpioWrite(GPIO_LED, led_state);

        usleep(1000000 / frequency);
    }

    return 0;
}

