#define MLX75030_TRIGGER_CMD 0x00
#define I2C_BUS 1
#define READ_RETRIES 5
#define SAMPLE_INTERVAL_MS 100

volatile sig_atomic_t stop = 0;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        stop = 1;
    }
}

int main() {
    int handle, err;
    FILE *log_file;
    unsigned char cmd = MLX75030_TRIGGER_CMD;
    unsigned short distance;
    struct timespec ts;

    // Open I2C device
    handle = piI2CInit(I2C_BUS, MLX75030_ADDR);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        piI2CClose(handle);
        return EXIT_FAILURE;
    }

    // Register signal handlers
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (!stop) {
        // Write trigger command
        err = piI2CWriteByteData(handle, cmd);
        if (err < 0) {
            fprintf(stderr, "Failed to write command: %d\n", err);
            continue;
        }

        // Delay for measurement
        nanosleep((const struct timespec[]){{0, SAMPLE_INTERVAL_MS * 900000}}, &ts);

        // Read distance
        for (int i = 0; i <= READ_RETRIES; i++) {
            err = piI2CReadWordData(handle, &distance);
            if (err >= 0) break;
            fprintf(stderr, "Failed to read distance: %d\n", err);
            if (i < READ_RETRIES) {
                fprintf(stderr, "Retrying...\n");
                nanosleep((const struct timespec[]){{0, 500000000}}, &ts);  // 0.5 sec
            }
        }

        // Get current timestamp
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);

        // Write to log file
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%d\n",
                timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
                timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec, distance);
        fflush(log_file);
    }

    // Close log file and I2C device
    fclose(log_file);
    piI2CClose(handle);

    return EXIT_SUCCESS;
}

