#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR1 17
#define SENSOR2 27
#define DEBOUNCE_TIME 50
#define POLL_TIME 10

FILE *log_file;
volatile sig_atomic_t stop;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        stop = 1;
    }
}

void log_event(int sensor_id, const char *event_type) {
    time_t now = time(NULL);
    struct tm *utc_time = gmtime(&now);
    fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02dZ Sensor %d %s\n",
            utc_time->tm_year + 1900, utc_time->tm_mon + 1, utc_time->tm_mday,
            utc_time->tm_hour, utc_time->tm_min, utc_time->tm_sec,
            sensor_id, event_type);
    if (ferror(log_file)) {
        fprintf(stderr, "Error writing to log file\n");
        exit(EXIT_FAILURE);
    }
}

int main() {
    int pi = gpioInitialise();
    if (pi < 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", pigpio_error(pi));
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(SENSOR1, PI_INPUT) < 0 || gpioSetMode(SENSOR2, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting GPIO mode: %s\n", pigpio_error(pi));
        exit(EXIT_FAILURE);
    }

    log_file = fopen("proximity_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    int prev_state1 = gpioRead(SENSOR1);
    int prev_state2 = gpioRead(SENSOR2);
    if (prev_state1 < 0 || prev_state2 < 0) {
        fprintf(stderr, "Error reading sensor state: %s\n", pigpio_error(pi));
        exit(EXIT_FAILURE);
    }

    while (!stop) {
        sleep_ms(POLL_TIME);

        int state1 = gpioRead(SENSOR1);
        int state2 = gpioRead(SENSOR2);
        if (state1 < 0 || state2 < 0) {
            fprintf(stderr, "Error reading sensor state: %s\n", pigpio_error(pi));
            exit(EXIT_FAILURE);
        }

        if (state1 != prev_state1) {
            if (state1 == 0) {
                log_event(1, "DETECTED");
            } else {
                log_event(1, "CLEARED");
            }
            prev_state1 = state1;
            sleep_ms(DEBOUNCE_TIME);
        }

        if (state2 != prev_state2) {
            if (state2 == 0) {
                log_event(2, "DETECTED");
            } else {
                log_event(2, "CLEARED");
            }
            prev_state2 = state2;
            sleep_ms(DEBOUNCE_TIME);
        }
    }

    fclose(log_file);
    gpioTerminate();

    return 0;
}

