#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>

#define I2C_DEV_PATH "/dev/i2c-1"
#define TDK_CH101_ADDR 0x49
#define MEAS_TRIGGER_REG 0x04
#define MEAS_STATUS_REG 0x06
#define DIST_HIGH_REG 0x08
#define DIST_LOW_REG 0x09
#define DATA_READY_BIT 0
#define I2C_TIMEOUT_MS 50
#define LOG_FILE_PATH "distance_log.csv"

static int i2c_fd = -1;
static FILE* log_file = NULL;

static void write_log(unsigned int distance_mm) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm* tm = localtime(&ts.tv_sec);
    fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02d.%03ld,%u\n",
            tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
            tm->tm_hour, tm->tm_min, tm->tm_sec, ts.tv_nsec / 1e6,
            distance_mm);
    fflush(log_file);
}

static int i2c_write_read(unsigned char reg, unsigned char* data, size_t len) {
    unsigned char buf[256];
    buf[0] = reg;
    memcpy(buf + 1, data, len);
    if (write(i2c_fd, buf, len + 1) != len + 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    if (read(i2c_fd, buf, len) != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    memcpy(data, buf, len);
    return 0;
}

static void sig_handler(int signum) {
    if (i2c_fd != -1) close(i2c_fd);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    exit(0);
}

int main() {
    i2c_fd = open(I2C_DEV_PATH, O_RDWR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Open %s failed: %s\n", I2C_DEV_PATH, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, TDK_CH101_ADDR) == -1) {
        fprintf(stderr, "I2C slave addr 0x%02x failed: %s\n", TDK_CH101_ADDR, strerror(errno));
        return 1;
    }
    log_file = fopen(LOG_FILE_PATH, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Open %s failed: %s\n", LOG_FILE_PATH, strerror(errno));
        return 1;
    }
    fprintf(log_file, "timestamp,distance_mm\n");
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);
    while (1) {
        unsigned char trigger = 0x01;
        if (i2c_write_read(MEAS_TRIGGER_REG, &trigger, 1) == -1) continue;
        unsigned char status = 0;
        for (int i = 0; i < I2C_TIMEOUT_MS; ++i) {
            usleep(1000);
            if (i2c_write_read(MEAS_STATUS_REG, &status, 1) == -1) continue;
            if (status & (1 << DATA_READY_BIT)) break;
        }
        if (!(status & (1 << DATA_READY_BIT))) {
            fprintf(stderr, "Data not ready\n");
            continue;
        }
        unsigned char high, low;
        if (i2c_write_read(DIST_HIGH_REG, &high, 1) == -1 ||
            i2c_write_read(DIST_LOW_REG, &low, 1) == -1) {
            continue;
        }
        unsigned int distance_mm = (high << 8) | low;
        write_log(distance_mm);
        usleep(500000);
    }
    return 0;
}

