#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define VL53L5CX_I2C_ADDR 0x29
#define VL53L5CX_I2C_BUS "/dev/i2c-1"
#define VL53L5CX_ZONE_COUNT 64

volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

int i2c_read(int file, int address, unsigned char *data) {
    struct i2c_msg msgs[2] = {
        { address, 0, 1, &address },
        { address, I2C_M_RD, 1, data },
    };

    if(i2c_rdwr(file, msgs, 2) != 2) {
        perror("i2c_rdwr");
        return -1;
    }

    return 0;
}

int i2c_write(int file, int address, unsigned char data) {
    struct i2c_msg msgs[1] = {
        { address, 0, 1, &data },
    };

    if(i2c_rdwr(file, msgs, 1) != 1) {
        perror("i2c_rdwr");
        return -1;
    }

    return 0;
}

int main() {
    int file;
    unsigned char data;

    file = open(VL53L5CX_I2C_BUS, O_RDWR);
    if(file < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    if(ioctl(file, I2C_SLAVE, VL53L5CX_I2C_ADDR) < 0) {
        perror("ioctl");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while(!stop) {
        for(int i = 0; i < VL53L5CX_ZONE_COUNT; i++) {
            if(i2c_write(file, i, 0) < 0) {
                return EXIT_FAILURE;
            }

            if(i2c_read(file, i, &data) < 0) {
                return EXIT_FAILURE;
            }

            printf("Zone %d: %d\n", i, data);
        }

        sleep(500);
    }

    close(file);

    return EXIT_SUCCESS;
}

