#include <pigpio.h>

#define MLX75030_I2C_ADDR 0x4C
#define MLX75030_READ_CMD 0x80
#define MAX_TRIES 3

volatile sig_atomic_t stop = 0;

void sigint_handler(int signum) {
    stop = 1;
}

int main() {
    int i2c_handle;
    int pi;
    int status;
    int tries;
    unsigned char cmd = MLX75030_READ_CMD;
    unsigned char data[2];
    struct timespec ts;

    // Connect to pigpio daemon
    pi = pigpio_start();
    if (pi < 0) {
        printf("Failed to connect to pigpio daemon\n");
        return EXIT_FAILURE;
    }

    // Open I2C handle
    i2c_handle = i2c_open(1, MLX75030_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        printf("Failed to open I2C handle: %d\n", i2c_handle);
        pigpio_stop(pi);
        return EXIT_FAILURE;
    }

    // Register signal handler
    signal(SIGINT, sigint_handler);

    while (!stop) {
        tries = 0;
        while (tries < MAX_TRIES) {
            // Write command and read data
            status = i2c_i2c(i2c_handle, &cmd, 1, data, 2);
            if (status == 0) {
                // Success
                break;
            } else if (status < 0 && status != -EBUSY) {
                // Sensor-absent or bus-error
                printf("I2C read failed: %d\n", status);
                pigpio_stop(pi);
                i2c_close(i2c_handle);
                return EXIT_FAILURE;
            }
            // Retry
            delay(10000);  // 10 ms
            tries++;
        }
        if (tries == MAX_TRIES) {
            printf("I2C read failed after %d retries\n", MAX_TRIES);
            pigpio_stop(pi);
            i2c_close(i2c_handle);
            return EXIT_FAILURE;
        }

        // Extract distance and log it
        clock_gettime(CLOCK_REALTIME, &ts);
        printf("%ld.%09ld: Distance = %d.%02d mm\n", ts.tv_sec, ts.tv_nsec, data[0], data[1]*100/256);

        // Wait 100 ms
        delay(100000);
    }

    // Clean up
    i2c_close(i2c_handle);
    pigpio_stop(pi);

    return EXIT_SUCCESS;
}

