#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29

#define REG_SOFT_RESET 0x7FFF
#define REG_RANGING_START 0x0009
#define REG_INTERRUPT_STATUS 0x0046
#define REG_RANGE_RESULT_HI 0x0096
#define REG_RANGE_RESULT_LO 0x0097

static int i2c_handle = -1;

static void cleanup_and_exit(int sig) {
    if (i2c_handle >= 0) {
        piI2CClose(i2c_handle);
    }
    gpioTerminate();
    exit(sig);
}

int main() {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = piI2C(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d address 0x%02X.\n", I2C_BUS, I2C_ADDR);
        cleanup_and_exit(EXIT_FAILURE);
    }

    if (piI2CWriteByteData(i2c_handle, REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Failed to write to register 0x%04X.\n", REG_SOFT_RESET);
        cleanup_and_exit(EXIT_FAILURE);
    }

    usleep(10000);

    if (piI2CWriteByteData(i2c_handle, REG_RANGING_START, 0x00) < 0) {
        fprintf(stderr, "Failed to write to register 0x%04X.\n", REG_RANGING_START);
        cleanup_and_exit(EXIT_FAILURE);
    }

    while (1) {
        int status = piI2CReadByteData(i2c_handle, REG_INTERRUPT_STATUS);
        if (status < 0) {
            fprintf(stderr, "Failed to read from register 0x%04X.\n", REG_INTERRUPT_STATUS);
            continue;
        }

        if (status & 0x01) {
            int hi = piI2CReadByteData(i2c_handle, REG_RANGE_RESULT_HI);
            int lo = piI2CReadByteData(i2c_handle, REG_RANGE_RESULT_LO);
            if (hi < 0 || lo < 0) {
                fprintf(stderr, "Failed to read from registers 0x%04X or 0x%04X.\n", REG_RANGE_RESULT_HI, REG_RANGE_RESULT_LO);
                continue;
            }

            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            printf("Timestamp: %ld-%02ld-%02ld %02ld:%02ld:%02ld.%06ld, Distance: %d mm\n",
                ts.tv_sec / 31536000 + 1970, (ts.tv_sec / 2592000) % 12 + 1, (ts.tv_sec / 86400) % 30 + 1,
                (ts.tv_sec / 3600) % 24, (ts.tv_sec / 60) % 60, ts.tv_sec % 60, ts.tv_nsec / 1000,
                (hi << 8) | lo);
        }

        usleep(500000);
    }

    return EXIT_SUCCESS;
}

