#define REG_I2C_SLAVE__DEVICE_ADDRESS 0x0001
#define REG_SYSTEM__MODE_START 0x0007
#define REG_RESULT__FINAL_CROSSTALK_CORRECTED_DISTANCE_MM 0x0096

static int buzzer_on = 0;

static void sigint_handler(int signo) {
    if (buzzer_on) {
        gpioWrite(GPIO_BUZZER, 0);
    }
    piI2CClose(I2C_BUS);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        printf("Failed to initialize GPIO\n");
        return 1;
    }

    if (gpioSetMode(GPIO_BUZZER, PI_OUTPUT) < 0) {
        printf("Failed to set GPIO mode\n");
        return 1;
    }

    if (piI2CSetBus(I2C_BUS) < 0) {
        printf("Failed to set I2C bus\n");
        return 1;
    }

    if (piI2CSetSlaveAddr(I2C_ADDR) < 0) {
        printf("Failed to set I2C slave address\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        if (piI2CWriteByte(REG_SOFT_RESET) < 0 ||
            piI2CWriteByte(REG_I2C_SLAVE__DEVICE_ADDRESS) < 0 ||
            piI2CWriteByte(REG_SYSTEM__MODE_START) < 0) {
            printf("Failed to configure sensor\n");
            continue;
        }

        int distance;
        if (piI2CReadByte(REG_RESULT__FINAL_CROSSTALK_CORRECTED_DISTANCE_MM, &distance, I2C_TIMEOUT) < 0) {
            printf("Failed to read distance\n");
            continue;
        }

        if (distance < 100) {
            if (!buzzer_on) {
                gpioWrite(GPIO_BUZZER, 1);
                buzzer_on = 1;
            }
        } else if (buzzer_on) {
            gpioWrite(GPIO_BUZZER, 0);
            buzzer_on = 0;
        }

        sleep(500);
    }

    return 0;
}

