#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_GPIO 23
#define ECHO_GPIO 24
#define SERVO_GPIO 17
#define SOUND_SPEED 343.0
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define MIN_ANGLE -90.0
#define MAX_ANGLE 90.0
#define LOG_FILE "sensor_data.log"

volatile sig_atomic_t stop = 0;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        stop = 1;
    }
}

void log_distance(double distance) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open %s for writing\n", LOG_FILE);
        return;
    }

    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(file, "%s, %.2f\n", timestamp, distance);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(TRIGGER_GPIO, PI_OUTPUT);
    gpioSetMode(ECHO_GPIO, PI_INPUT);

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (!stop) {
        gpioDigitalWrite(TRIGGER_GPIO, 1);
        usleep(10);
        gpioDigitalWrite(TRIGGER_GPIO, 0);

        int echo_pulse_width = gpioPulseIn(ECHO_GPIO, 1, 50000);
        if (echo_pulse_width == 0 || echo_pulse_width == GPIO_TIMEOUT) {
            fprintf(stderr, "Echo stuck low or high\n");
            continue;
        }

        double distance = (double) echo_pulse_width * SOUND_SPEED / 2e8;
        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(stderr, "Invalid distance: %.2f\n", distance);
            continue;
        }

        log_distance(distance);

        double angle = MIN_ANGLE + (MAX_ANGLE - MIN_ANGLE) * (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE);
        gpioServo(SERVO_GPIO, (int) (1500 + 10 * angle));

        usleep(200000);
    }

    gpioServo(SERVO_GPIO, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

