#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/msg.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define I2C_HANDLE -1
#define GPIO_BUZZER 23
#define SENSOR_MODEL_ID 0xEA
#define SENSOR_RESET_REG 0x0000
#define SENSOR_RESET_VAL1 0x00
#define SENSOR_RESET_VAL2 0x01
#define SENSOR_TIMING_BUDGET_REG 0x0014
#define SENSOR_TIMING_BUDGET_VAL 0x3C00
#define SENSOR_RANGE_START_REG 0x0080
#define SENSOR_RANGE_START_VAL 0x01
#define SENSOR_DATA_READY_REG 0x0089
#define SENSOR_DATA_READY_BIT 0
#define SENSOR_DISTANCE_REG_L 0x0096
#define SENSOR_DISTANCE_REG_H 0x0097
#define MIN_DISTANCE 100

static int i2c_handle = I2C_HANDLE;
static int msg_queue_id = -1;
static int buzzer_gpio = GPIO_BUZZER;

static void cleanup(int signum) {
    if (i2c_handle != I2C_HANDLE) {
        piI2CClose(i2c_handle);
    }
    if (msg_queue_id != -1) {
        msgctl(msg_queue_id, IPC_RMID, NULL);
    }
    if (gpioInitialise() >= 0) {
        gpioWrite(buzzer_gpio, 0);
        gpioTerminate();
    }
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    signal(SIGINT, cleanup);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    if (gpioSetMode(buzzer_gpio, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        return 1;
    }

    i2c_handle = piI2C(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return 1;
    }

    if (piI2CWriteByteData(i2c_handle, 0x010F) != SENSOR_MODEL_ID) {
        fprintf(stderr, "Failed to verify sensor model ID\n");
        return 1;
    }

    if (piI2CWriteByteData(i2c_handle, SENSOR_RESET_REG, SENSOR_RESET_VAL1) < 0 ||
        piI2CWriteByteData(i2c_handle, SENSOR_RESET_REG, SENSOR_RESET_VAL2) < 0) {
