        fprintf(stderr, "Failed to set timing budget\n");
        return 1;
    }

    if (piI2CWriteByteData(i2c_handle, SENSOR_RANGE_START_REG, SENSOR_RANGE_START_VAL) < 0) {
        fprintf(stderr, "Failed to start ranging\n");
        return 1;
    }

    msg_queue_id = msgget(IPC_PRIVATE, 0666 | IPC_CREAT);
    if (msg_queue_id < 0) {
        fprintf(stderr, "Failed to create message queue\n");
        return 1;
    }

    while (1) {
        if ((piI2CReadByteData(i2c_handle, SENSOR_DATA_READY_REG) >> SENSOR_DATA_READY_BIT) & 1) {
