#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <paho-mqtt/MQTTClient.h>

#define VL53L1X_ADDR 0x29
#define VL53L1X_RESET_REG 0x0
#define VL53L1X_START_REG 0x100
#define VL53L1X_RESULT_REG 0x146
#define VL53L1X_I2C_RETRIES 5

#define SERVO_PIN 18
#define SERVO_OPEN 1500
#define SERVO_CLOSE 900
#define SERVO_DURATION 500

#define MQTT_BROKER "tcp://localhost:1883"
#define MQTT_CLIENTID "gate_controller"
#define MQTT_USER "user"
#define MQTT_PASS "pass"

static int servo_state = SERVO_CLOSE;
static MQTTClient mqtt_client;
static FILE *log_file;

void log_event(const char *event) {
    time_t now = time(NULL);
    char buffer[26];
    strftime(buffer, 26, "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(log_file, "%s - %s\n", buffer, event);
    fflush(log_file);
}

int i2c_write_reg(int fd, int addr, int reg, int val) {
    char buf[3];
    buf[0] = reg >> 8;
    buf[1] = reg & 0xFF;
    buf[2] = val;
    return write(fd, buf, 3);
}

int i2c_read_reg(int fd, int addr, int reg, int *val) {
    char buf[2];
    buf[0] = reg >> 8;
    buf[1] = reg & 0xFF;
    if (write(fd, buf, 2) != 2) return -1;
    if (read(fd, buf, 1) != 1) return -1;
    *val = buf[0];
    return 0;
}

void handle_command(char *topic, byte *message, int len) {
    if (strcmp(topic, "force_open") == 0) {
        servo_state = SERVO_OPEN;
        log_event("Gate manually opened");
    } else if (strcmp(topic, "force_close") == 0) {
        servo_state = SERVO_CLOSE;
        log_event("Gate manually closed");
    } else if (strcmp(topic, "status_request") == 0) {
        // TODO: send status message
    }
}

void handle_signal(int signum) {
    MQTTClient_disconnect(mqtt_client, 1000);
    MQTTClient_destroy(&mqtt_client);
    fclose(log_file);
    exit(0);
}

int main() {
    int fd, val, retries;
    log_file = fopen("gate_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    fd = i2cOpen(1, VL53L1X_ADDR, 0);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return 1;
    }
    i2c_write_reg(fd, VL53L1X_ADDR, VL53L1X_RESET_REG, 0);
    sleep(1);
    i2c_write_reg(fd, VL53L1X_ADDR, VL53L1X_START_REG, 1);
    signal(SIGINT, handle_signal);
    MQTTClient_create(&mqtt_client, MQTT_BROKER, MQTT_CLIENTID,
                      MQTTCLIENT_PERSISTENCE_NONE, NULL);
    MQTTClient_setCallbacks(mqtt_client, NULL, NULL, handle_command);
    MQTTClient_connect(mqtt_client, NULL);
    while (1) {
        for (retries = 0; retries < VL53L1X_I2C_RETRIES; retries++) {
            if (i2c_read_reg(fd, VL53L1X_ADDR, VL53L1X_RESULT_REG, &val) == 0)
                break;
            sleep(1);
        }
        if (retries == VL53L1X_I2C_RETRIES) {
            log_event("I2C communication error");
            continue;
        }
        if (val < 20) {
            if (servo_state != SERVO_OPEN) {
                servo_state = SERVO_OPEN;
                gpioServo(SERVO_PIN, servo_state);
                log_event("Gate automatically opened");
                sleep(SERVO_DURATION / 1000);
            }
        } else {
            if (servo_state != SERVO_CLOSE) {
                servo_state = SERVO_CLOSE;
                gpioServo(SERVO_PIN, servo_state);
                log_event("Gate automatically closed");
                sleep(SERVO_DURATION / 1000);
            }
        }
    }
    return 0;
}

