#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define TRIGGER_PULSE_US 10
#define MAX_ECHO_US 30000
#define MIN_ECHO_US 100
#define MEASUREMENT_PERIOD_MS 200
#define TIMEOUT_US 60000

FILE *log_file;
volatile int stop = 0;

void sig_handler(int signo) {
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();
    stop = 1;
}

void echo_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_rising_tick = 0;
    if (level == 0) {
        uint32_t pulse_width = tick - last_rising_tick;
        if (pulse_width < MIN_ECHO_US || pulse_width > MAX_ECHO_US) {
            fprintf(stderr, "Warning: Invalid pulse width %u\n", pulse_width);
        } else {
            time_t now = time(NULL);
            struct tm *timeinfo = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
            double distance = pulse_width * 0.0343;
            fprintf(stdout, "%s: Distance: %.2f cm\n", timestamp, distance);
            fprintf(log_file, "%s: Distance: %.2f cm\n", timestamp, distance);
            fflush(log_file);
        }
    } else if (level == 1) {
        last_rising_tick = tick;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioCfgInt(ECHO_PIN, echo_callback);

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (!stop) {
        gpioWrite(TRIG_PIN, 1);
        delayMicroseconds(TRIGGER_PULSE_US);
        gpioWrite(TRIG_PIN, 0);
        delay(MEASUREMENT_PERIOD_MS);
    }

    return EXIT_SUCCESS;
}

