#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define I2C_HANDLE -1

#define GPIO_OPEN 18
#define GPIO_CLOSE 19

#define VL53L1X_SOFT_RESET_CMD 0x0000
#define VL53L1X_TIMING_BUDGET_CMD 0x0006
#define VL53L1X_START_RANGING_CMD 0x0000
#define VL53L1X_RESULT_DATA_CMD 0x10B

FILE *log_file;

void cleanup_and_exit(int signum) {
    if (I2C_HANDLE >= 0) {
        i2cClose(I2C_HANDLE);
    }
    gpioTerminate();
    fclose(log_file);
    exit(signum);
}

int main() {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_OPEN, PI_OUTPUT);
    gpioSetMode(GPIO_CLOSE, PI_OUTPUT);

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        cleanup_and_exit(EXIT_FAILURE);
    }

    log_file = fopen("gate_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    // Soft reset and configure VL53L1X
    if (i2cWriteWordData(i2c_handle, VL53L1X_SOFT_RESET_CMD, 0xABCD) < 0) {
        fprintf(stderr, "Failed to reset sensor\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    if (i2cWriteWordData(i2c_handle, VL53L1X_TIMING_BUDGET_CMD, 20000) < 0) {
        fprintf(stderr, "Failed to set timing budget\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    if (i2cWriteWordData(i2c_handle, VL53L1X_START_RANGING_CMD, 1) < 0) {
        fprintf(stderr, "Failed to start ranging\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    while (1) {
        sleep(500);

        uint16_t distance;
        if (i2cReadI2CBlockData(i2c_handle, VL53L1X_RESULT_DATA_CMD, 2, &distance) < 0) {
            fprintf(stderr, "Failed to read distance\n");
            cleanup_and_exit(EXIT_FAILURE);
        }

        time_t now = time(NULL);
        struct tm *utc_time = gmtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_time);

        if (distance < 200) {
            gpioWrite(GPIO_OPEN, PI_HIGH);
            gpioWrite(GPIO_CLOSE, PI_LOW);
            fprintf(log_file, "%s Gate opened, distance: %d mm\n", timestamp, distance);
        } else {
            gpioWrite(GPIO_OPEN, PI_LOW);
            gpioWrite(GPIO_CLOSE, PI_HIGH);
            fprintf(log_file, "%s Gate closed, distance: %d mm\n", timestamp, distance);
        }

        fflush(log_file);
    }

    cleanup_and_exit(EXIT_SUCCESS);
}

