#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <pigpiod_if.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define I2C_RETRIES 5
#define I2C_DELAY 100

#define GPIO_TRIGGER 24
#define GPIO_FORWARD 17
#define GPIO_BACKWARD 18

volatile int running = 1;

int i2c_h;

void stop_motor(void) {
    gpioWrite(GPIO_FORWARD, 0);
    gpioWrite(GPIO_BACKWARD, 0);
}

void sig_handler(int signo) {
    running = 0;
}

void isr(int gpio, int level, uint32_t tick) {
    int i, ret;
    uint8_t data[2];

    if (level != 1) return;

    for (i = 0; i < I2C_RETRIES; i++) {
        ret = i2cWriteByte(i2c_h, 0x0000);
        if (ret < 0) {
            printf("i2cWriteByte(0x0000) failed: %d\n", ret);
            usleep(I2C_DELAY * 1000);
            continue;
        }

        ret = i2cReadByte(i2c_h, &data[0]);
        if (ret < 0) {
            printf("i2cReadByte failed: %d\n", ret);
            usleep(I2C_DELAY * 1000);
            continue;
        }

        if ((data[0] & 1) == 0) break;

        usleep(1000);
    }

    if (i == I2C_RETRIES) {
        printf("Data not ready after %d retries\n", I2C_RETRIES);
        stop_motor();
        return;
    }

    for (i = 0; i < I2C_RETRIES; i++) {
        ret = i2cWriteByte(i2c_h, 0x0096);
        if (ret < 0) {
            printf("i2cWriteByte(0x0096) failed: %d\n", ret);
            usleep(I2C_DELAY * 1000);
            continue;
        }

        ret = i2cReadByte(i2c_h, &data[0]);
        if (ret < 0) {
            printf("i2cReadByte failed: %d\n", ret);
            usleep(I2C_DELAY * 1000);
            continue;
        }

        ret = i2cReadByte(i2c_h, &data[1]);
        if (ret < 0) {
            printf("i2cReadByte failed: %d\n", ret);
            usleep(I2C_DELAY * 1000);
            continue;
        }

        break;
    }

    if (i == I2C_RETRIES) {
        printf("Failed to read distance after %d retries\n", I2C_RETRIES);
        stop_motor();
        return;
    }

    int distance = (data[0] << 8) | data[1];
    printf("Distance: %d mm\n", distance);

    if (distance < 100) {
        gpioWrite(GPIO_FORWARD, 1);
        gpioWrite(GPIO_BACKWARD, 0);
        printf("Motor: forward\n");
    } else if (distance > 300) {
        gpioWrite(GPIO_FORWARD, 0);
        gpioWrite(GPIO_BACKWARD, 1);
        printf("Motor: backward\n");
    } else {
        stop_motor();
        printf("Motor: stop\n");
    }
}

int main(void) {
    int ret;

    ret = gpioInitialise();
    if (ret < 0) {
        printf("gpioInitialise failed: %d\n", ret);
        return 1;
    }

    ret = gpioSetMode(GPIO_TRIGGER, PI_INPUT);
    if (ret < 0) {
        printf("gpioSetMode(%d, PI_INPUT) failed: %d\n", GPIO_TRIGGER, ret);
        return 1;
    }

    ret = gpioSetMode(GPIO_FORWARD, PI_OUTPUT);
    if (ret < 0) {
        printf("gpioSetMode(%d, PI_OUTPUT) failed: %d\n", GPIO_FORWARD, ret);
        return 1;
    }

    ret = gpioSetMode(GPIO_BACKWARD, PI_OUTPUT);
    if (ret < 0) {
        printf("gpioSetMode(%d, PI_OUTPUT) failed: %d\n", GPIO_BACKWARD, ret);
        return 1;
    }

    ret = gpioSetISRFunc(GPIO_TRIGGER, PI_RisingEdge, 0, isr);
    if (ret < 0) {
        printf("gpioSetISRFunc failed: %d\n", ret);
        return 1;
    }

    i2c_h = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_h < 0) {
        printf("i2cOpen failed: %d\n", i2c_h);
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (running) {
        sleep(1);
    }

    ret = i2cClose(i2c_h);
    if (ret < 0) {
        printf("i2cClose failed: %d\n", ret);
    }

    stop_motor();

    ret = gpioTerminate();
    if (ret < 0) {
        printf("gpioTerminate failed: %d\n", ret);
    }

    return 0;
}

