#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <libgpiod.h>

#define I2C_ADDR 0x5A
#define I2C_FD 1
#define GPIO_FD 2
#define LOG_FD 3

static int i2c_fd;
static struct gpiod_chip *gpio_chip;
static struct gpiod_line *gpio_lines[4];
static FILE *log_file;

static void cleanup_and_exit(int signum) {
    for (int i = 0; i < 4; i++)
        gpiod_line_release(gpio_lines[i]);
    gpiod_chip_close(gpio_chip);
    fclose(log_file);
    close(i2c_fd);
    exit(signum);
}

int main() {
    struct sigaction action;
    action.sa_handler = cleanup_and_exit;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    for (int i = 0; i < 4; i++) {
        gpio_lines[i] = gpiod_chip_get_line(gpio_chip, 17 + i);
        if (!gpio_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", 17 + i);
            return 1;
        }
        if (gpiod_line_request_output(gpio_lines[i], "proximity", 0)) {
            fprintf(stderr, "Failed to request GPIO line %d\n", 17 + i);
            return 1;
        }
    }

