#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <mpr121.h>

#define LED_PIN 27
#define MPR121_ADDR 0x5A
#define MPR121_ELE_0 0
#define MPR121_TOUCH_THRESHOLD 0x0A
#define MPR121_RELEASE_THRESHOLD 0x05

volatile sig_atomic_t stop = 0;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        stop = 1;
    }
}

int main() {
    int pi = pigpio_start();
    if (pi < 0) {
        fprintf(stderr, "Could not connect to pigpio daemon\n");
        return EXIT_FAILURE;
    }

    struct tm *ts;
    time_t t;
    FILE *log_file = fopen("proximity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Could not open proximity.log for writing\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    mpr121_t *mpr121 = mpr121_new(pi, 1, MPR121_ADDR);
    if (mpr121 == NULL) {
        fprintf(stderr, "Could not initialize MPR121\n");
        return EXIT_FAILURE;
    }

    if (mpr121_read_device_id(mpr121) != MPR121_DEVICE_ID) {
        fprintf(stderr, "MPR121 not found at address 0x%X\n", MPR121_ADDR);
        return EXIT_FAILURE;
    }

    if (mpr121_write_register(mpr121, MPR121_REG_BASE_CONFIG_0 + MPR121_ELE_0, MPR121_TOUCH_THRESHOLD) < 0 ||
        mpr121_write_register(mpr121, MPR121_REG_BASE_CONFIG_1 + MPR121_ELE_0, MPR121_RELEASE_THRESHOLD) < 0 ||
        mpr121_write_register(mpr121, MPR121_REG_FILTER_CONFIG, 0x00) < 0 ||
        mpr121_write_register(mpr121, MPR121_REG_SENSOR_CONFIG, 0x00) < 0 ||
        mpr121_write_register(mpr121, MPR121_REG_GPIO_CONFIG, 0x00) < 0 ||
        mpr121_write_register(mpr121, MPR121_REG_GPIO_DATA_OUTPUT, 0x00) < 0) {
        fprintf(stderr, "Could not configure MPR121\n");
        return EXIT_FAILURE;
    }

    gpio_mode(pi, LED_PIN, PI_OUTPUT);

    while (!stop) {
        if (mpr121_read_electrode_state(mpr121, MPR121_ELE_0) & MPR121_TOUCH_STATUS_BIT) {
            gpio_write(pi, LED_PIN, 1);
            t = time(NULL);
            ts = localtime(&t);
            fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d: Proximity detected on electrode 0\n",
                    ts->tm_year + 1900, ts->tm_mon + 1, ts->tm_mday, ts->tm_hour, ts->tm_min, ts->tm_sec);
            fflush(log_file);
            sleep(1);
            gpio_write(pi, LED_PIN, 0);
        }
    }

    fclose(log_file);
    mpr121_delete(mpr121);
    pigpio_stop(pi);

    return EXIT_SUCCESS;
}

