#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define TRIGGER_GPIO 17
#define ECHO_GPIO 18
#define MIN_DISTANCE 2
#define MAX_DISTANCE 400
#define TIMEOUT_US 30000

struct gpiod_line *trigger_line, *echo_line;
struct gpiod_chip *chip;
FILE *log_file;
volatile sig_atomic_t stop = 0;

void sigint_handler(int signum) {
    stop = 1;
}

void log_distance(int distance) {
    time_t now = time(NULL);
    struct tm *utc_time = gmtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_time);
    fprintf(log_file, "%s: %d\n", timestamp, distance);
    fflush(log_file);
}

int main() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_GPIO);
    if (!trigger_line) {
        perror("gpiod_chip_get_line");
        goto err_chip;
    }

    if (gpiod_line_request_output(trigger_line, "trigger", 0)) {
        perror("gpiod_line_request_output");
        goto err_trigger;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_GPIO);
    if (!echo_line) {
        perror("gpiod_chip_get_line");
        goto err_trigger;
    }

    if (gpiod_line_request_input(echo_line, "echo")) {
        perror("gpiod_line_request_input");
        goto err_echo;
    }

    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        perror("fopen");
        goto err_echo;
    }

    signal(SIGINT, sigint_handler);

    while (!stop) {
        gpiod_line_set_value(trigger_line, 0);
        usleep(5);
        gpiod_line_set_value(trigger_line, 1);
        usleep(10);
        gpiod_line_set_value(trigger_line, 0);

        struct timespec timeout;
        clock_gettime(CLOCK_REALTIME, &timeout);
        timeout.tv_nsec += TIMEOUT_US * 1000;
        if (timeout.tv_nsec >= 1000000000) {
            timeout.tv_nsec -= 1000000000;
            timeout.tv_sec++;
        }

        int res = gpiod_line_wait_for_rising_edge(echo_line, &timeout);
        if (res < 0) {
            if (errno == ETIMEDOUT) {
                fprintf(stderr, "Timeout waiting for echo rising edge\n");
            } else {
                perror("gpiod_line_wait_for_rising_edge");
            }
            continue;
        }

        res = gpiod_line_wait_for_falling_edge(echo_line, &timeout);
        if (res < 0) {
            if (errno == ETIMEDOUT) {
                fprintf(stderr, "Timeout waiting for echo falling edge\n");
            } else {
                perror("gpiod_line_wait_for_falling_edge");
            }
            continue;
        }

        unsigned int pulse_us = gpiod_line_get_rising_edge_event_count(echo_line);
        int distance = (pulse_us * 0.0343) / 2.0;
        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(stderr, "Invalid distance: %d\n", distance);
            continue;
        }

        log_distance(distance);
    }

    fclose(log_file);
err_echo:
    gpiod_line_release(echo_line);
err_trigger:
    gpiod_line_release(trigger_line);
err_chip:
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

