#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIG_PIN 17
#define ECHO_PIN 18

FILE *log_file;
volatile int stop = 0;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        gpioSetISRFuncEx(ECHO_PIN, RISING_EDGE, 0, NULL);
        fclose(log_file);
        gpioTerminate();
        stop = 1;
    }
}

void trigger_pulse(int gpio, int level, int tick, void *data) {
    gpioWrite(TRIG_PIN, 1);
    sleep(1000);
    gpioWrite(TRIG_PIN, 0);
}

void echo_pulse_width(int gpio, int level, int tick, void *data) {
    static unsigned long long last_tick = 0;
    unsigned long long pulse_us;
    struct timespec ts;
    char time_str[20];

    if (level == 0) {
        last_tick = tick;
    } else if (level == 1) {
        pulse_us = tick - last_tick;
        if (pulse_us > 0 && pulse_us < 25000) {
            clock_gettime(CLOCK_REALTIME, &ts);
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
            fprintf(log_file, "%s, %.2f\n", time_str, pulse_us * 343.0 / 2e6);
        }
    }
}

int main() {
    int pi = pigpio_start(0, 0);
    if (pi < 0) {
        printf("Failed to initialize pigpio\n");
        return -1;
    }

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        return -1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_pulse_width);
    gpioTriggerFuncEx(TRIG_PIN, 10, 0, trigger_pulse, NULL);

    while (!stop) {
        sleep(100000);
    }

    return 0;
}

