            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
            fprintf(log_file, "%s, %.2f\n", time_str, pulse_us * 343.0 / 2e6);
        }
    }
}

int main() {
    int pi = pigpio_start(0, 0);
    if (pi < 0) {
        printf("Failed to initialize pigpio\n");
        return -1;
    }

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        return -1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_pulse_width);
    gpioTriggerFuncEx(TRIG_PIN, 10, 0, trigger_pulse, NULL);

    while (!stop) {
        sleep(100000);
    }

    return 0;
}
```

This code initializes pigpio, sets up the GPIO pins, and opens the log file. It then sets up signal handlers for SIGINT and SIGTERM to cleanly shut down the program. The trigger_pulse function fires a 10 microsecond trigger pulse once per second, and the echo_pulse_width function measures the echo pulse width on EITHER_EDGE transitions. The main loop runs until the stop flag is set, which happens when the program receives a SIGINT or SIGTERM.

