    openlog("vl53l1x", LOG_PID, LOG_USER);

    if (piGpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialise pigpio: %s", strerror(errno));
        exit(1);
    }

    if (gpioSetMode(GPIO_XSHUT, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO mode: %s", strerror(errno));
        exit(1);
    }

    if (gpioWrite(GPIO_XSHUT, PI_HIGH) < 0) {
        syslog(LOG_ERR, "Failed to write GPIO: %s", strerror(errno));
        exit(1);
