#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <pigpiod_if.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define GPIO_GATE 24

FILE *log_file;
int i2c_handle;

void log_msg(const char *msg) {
    time_t now = time(NULL);
    fprintf(log_file, "%s: %s\n", ctime(&now), msg);
    fflush(log_file);
}

void sig_handler(int signo) {
    if (i2c_handle >= 0) {
        piI2C_close(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(signo);
}

int main() {
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("gate_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    i2c_handle = piI2C_open(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        log_msg("Failed to open I2C handle");
        return EXIT_FAILURE;
    }

    uint8_t model_id;
    if (piI2C_read_byte_data(i2c_handle, 0x010F, &model_id) < 0) {
        log_msg("Failed to read model ID");
        return EXIT_FAILURE;
    }
    if (model_id != 0xEA) {
        log_msg("Unexpected model ID");
        return EXIT_FAILURE;
    }

    if (piI2C_write_byte_data(i2c_handle, 0x0021, 0x00) < 0) {
        log_msg("Failed to set ranging mode");
        return EXIT_FAILURE;
    }

    if (piI2C_write_byte_data(i2c_handle, 0x0015, 0x01) < 0) {
        log_msg("Failed to start ranging");
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_GATE, PI_OUTPUT);
    gpioWrite(GPIO_GATE, 0);

    while (1) {
        uint16_t distance;
        if (piI2C_read_word_data(i2c_handle, 0x0089, &distance) < 0) {
            log_msg("Failed to read distance");
            return EXIT_FAILURE;
        }
        distance /= 10;  // convert from mm to cm

        int gate_state = gpioRead(GPIO_GATE);
        if (distance < 20 && gate_state == 0) {
            gpioWrite(GPIO_GATE, 1);
            log_msg("Gate opened");
        } else if (distance >= 20 && gate_state == 1) {
            gpioWrite(GPIO_GATE, 0);
            log_msg("Gate closed");
        }

        char buffer[64];
        sprintf(buffer, "Distance: %d cm", distance);
        log_msg(buffer);

        sleep(100);
    }

    return EXIT_SUCCESS;
}

