#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18
#define SAMPLE_SIZE 5
#define TIMEOUT 30000

volatile sig_atomic_t stop = 0;

double moving_average[SAMPLE_SIZE] = {0};
int avg_index = 0;

FILE *csv_file;

void sigint_handler(int signum) {
    stop = 1;
}

void servo_command(int pulse_width) {
    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Failed to command servo\n");
        exit(EXIT_FAILURE);
    }
}

void echo_alert(int gpio, int level, uint32_t tick) {
    static uint32_t echo_start = 0;
    static int pulse_width = 0;

    if (level == 0) {
        echo_start = tick;
    } else {
        pulse_width = tick - echo_start;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetAlertFunc(ECHO_PIN, echo_alert) < 0) {
        fprintf(stderr, "Failed to register alert callback\n");
        exit(EXIT_FAILURE);
    }

    gpioSetPullUpDown(TRIGGER_PIN, PI_PUD_OFF);
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    gpioHardwarePWM(SERVO_PIN, 50, 1500000);

    signal(SIGINT, sigint_handler);

    csv_file = fopen("distance_log.csv", "w");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        exit(EXIT_FAILURE);
    }
    fprintf(csv_file, "timestamp,distance,servo_angle\n");

    while (!stop) {
        gpioTrigger(TRIGGER_PIN, 10, 1);

        uint32_t start = millis();
        while (!stop && pulse_width == 0 && millis() - start < TIMEOUT) {
            sleep(1);
        }

        if (pulse_width == 0) {
            fprintf(csv_file, "%ld,-1.0,90.0\n", millis());
            servo_command(1500);
        } else {
            double distance = pulse_width * 34300.0 / 2 / 10000.0;
            if (distance < 2 || distance > 400) {
                fprintf(csv_file, "%ld,-1.0,90.0\n", millis());
                servo_command(1500);
            } else {
                moving_average[avg_index] = distance;
                avg_index = (avg_index + 1) % SAMPLE_SIZE;
                double avg = 0;
                for (int i = 0; i < SAMPLE_SIZE; i++) {
                    avg += moving_average[i];
                }
                avg /= SAMPLE_SIZE;

                double servo_angle = 90 + log(avg / 100) * 90;
                if (servo_angle < 0) servo_angle = 0;
                if (servo_angle > 180) servo_angle = 180;

                fprintf(csv_file, "%ld,%.2f,%.2f\n", millis(), avg, servo_angle);
                servo_command(500 + servo_angle * 10);
            }
        }

        pulse_width = 0;
        fflush(csv_file);
        sleep(100);
    }

    servo_command(1500);
    fclose(csv_file);
    gpioTerminate();

    return 0;
}

