code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <vl53l1x.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define GPIO_LED 17
#define SAMPLES 10
#define SAMPLE_PERIOD 50

struct timespec ts;
int i2c_handle;
VL53L1X_Dev_t sensor;
int readings[SAMPLES];
int read_index = 0;
int led_on = 0;

void sigint_handler(int signo) {
    if (led_on) {
        gpioWrite(GPIO_LED, 0);
        led_on = 0;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (sensor.comms_speed_khz > 0) {
        VL53L1X_Stop(sensor);
        VL53L1X_Close(sensor);
        sensor.comms_speed_khz = 0;
    }
    if (pi_initialised) {
        gpioTerminate();
    }
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);

    if (gpioInitialise() < 0) {
        printf("Failed to initialise GPIO\n");
        return 1;
    }
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        printf("Failed to open I2C bus\n");
        sigint_handler(0);
        return 1;
    }

    sensor.comms_speed_khz = 400;
    sensor.comms_handle = i2c_handle;
    if (VL53L1X_Open(&sensor) < 0) {
        printf("Failed to open sensor\n");
        sigint_handler(0);
        return 1;
    }
    if (VL53L1X_SetDefaultConfiguration(&sensor) < 0) {
        printf("Failed to set default configuration\n");
        sigint_handler(0);
        return 1;
    }
    if (VL53L1X_EnableSignalRateCheck(&sensor) < 0) {
        printf("Failed to enable signal rate check\n");
        sigint_handler(0);
        return 1;
    }
    if (VL53L1X_SetXTalkCompensationEnable(&sensor, 1) < 0) {
        printf("Failed to enable cross-talk compensation\n");
        sigint_handler(0);
        return 1;
    }
    if (VL53L1X_Start(&sensor) < 0) {
        printf("Failed to start ranging\n");
        sigint_handler(0);
        return 1;
    }

    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);
        ts.tv_nsec += SAMPLE_PERIOD * 1000000;
        if (ts.tv_nsec >= 1000000000) {
            ts.tv_nsec -= 1000000000;
            ts.tv_sec++;
        }
        VL53L1X_PerformSingleRangingMeasurement(&sensor);
        if (sensor.RangeMilliMeter < 200) {
            if (!led_on) {
                gpioWrite(GPIO_LED, 1);
                led_on = 1;
            }
        } else {
            if (led_on) {
                gpioWrite(GPIO_LED, 0);
                led_on = 0;
            }
        }
        readings[read_index] = sensor.RangeMilliMeter;
        read_index = (read_index + 1) % SAMPLES;
        nanosleep(&ts, NULL);
    }

    return 0;
}

