    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cUnwrite(i2c_handle);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFunc(GPIO, interrupt_handler) < 0) {
        fprintf(stderr, "Failed to set GPIO alert function\n");
        log_file = NULL;
        sigint_handler(0);
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        if (interrupt_flag) {
            interrupt_flag = 0;
            int proximity = i2cReadWord(i2c_handle, PROXIMITY_REG);
            if (proximity < 0) {
                fprintf(stderr, "Failed to read proximity\n");
                continue;
            }
            log_proximity(proximity);
        }
    }

