#include <math.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SPEAKER_PIN 18
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 200.0
#define MIN_FREQUENCY 200.0
#define MAX_FREQUENCY 2000.0
#define PULSE_US 10
#define TIMEOUT_MS 200

double last_frequency = MIN_FREQUENCY;

void exit_handler(int signum) {
    piHiPri(0);
    pwmWrite(SPEAKER_PIN, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        printf("Failed to initialize GPIO\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SPEAKER_PIN, PI_OUTPUT);

    if (gpioHardwarePWM(SPEAKER_PIN, MIN_FREQUENCY, 50 * 1024)) {
        printf("Failed to set up PWM\n");
        return 1;
    }

    signal(SIGINT, exit_handler);
    signal(SIGTERM, exit_handler);

    while (1) {
        gpioTrigger(TRIGGER_PIN, PULSE_US, 0);

        while (gpioRead(ECHO_PIN) == 0) {
            if (gpioWaveTxBusy()) {
                double distance = (double) gpioRead(ECHO_PIN) / 10000.0;
                if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                    double frequency = MIN_FREQUENCY + (MAX_FREQUENCY - MIN_FREQUENCY) * exp(distance / 50.0);
                    last_frequency = frequency;
                }
                pwmWrite(SPEAKER_PIN, last_frequency * 1024);
                break;
            }
        }
    }

    return 0;
}

