#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18
#define MIN_DIST 5
#define MAX_DIST 50
#define MIN_FREQ 200
#define MAX_FREQ 2000

static int pi_handle = 0;
static unsigned int last_distance = 0;

void sigint_handler(int signo) {
    gpioHardwarePWM(BUZZER_PIN, 0, 0);
    if (pi_handle > 0) {
        gpioTerminate();
    }
    exit(0);
}

int main() {
    struct sigaction action;
    action.sa_handler = sigint_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);

    pi_handle = gpioInitialise();
    if (pi_handle <= 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", strerror(-pi_handle));
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0 || gpioSetMode(ECHO_PIN, PI_INPUT) != 0 || gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        return 1;
    }

    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    while (1) {
        gpioWrite(TRIGGER_PIN, 0);
        gpioDelay(10000);
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(10);
        gpioWrite(TRIGGER_PIN, 0);

        unsigned int echo_pulse_width = gpioReadPulse(ECHO_PIN, PI_TIMEOUT, 100000);
        if (echo_pulse_width == 0) {
            fprintf(stderr, "Echo pulse timeout\n");
            if (last_distance == 0) {
                return 1;
            }
        } else {
            last_distance = echo_pulse_width / 58;
        }

        unsigned int freq = MIN_FREQ + (MAX_FREQ - MIN_FREQ) * (MAX_DIST - last_distance) / (MAX_DIST - MIN_DIST);
        if (freq < MIN_FREQ) {
            freq = MIN_FREQ;
        } else if (freq > MAX_FREQ) {
            freq = MAX_FREQ;
        }

        gpioHardwarePWM(BUZZER_PIN, freq, 500000);

        printf("Distance: %u cm, Frequency: %u Hz\n", last_distance, freq);

        gpioDelay(10000);
    }

    return 0;
}

