    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(signum);
}

int main() {
    signal(SIGINT, exit_handler);
    signal(SIGTERM, exit_handler);

    spi_handle = spiOpen("/dev/spidev0.0", SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(-spi_handle));
        exit_handler(EXIT_FAILURE);
    }

    gpioCfg(SPI_CS_PIN, PI_OUTPUT);
    gpioWrite(SPI_CS_PIN, 1);

    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        exit_handler(EXIT_FAILURE);
    }

    for (int i = 0; i < SENSOR_INIT_RETRIES; i++) {
        unsigned char init_data[] = {REG_CONTINUOUS_MODE, 0x01, REG_RANGE, 0x00, REG_TRIGGER, TRIGGER_VALUE};
        if (spiXfer(spi_handle, init_data, NULL, sizeof(init_data)) < 0) {
            fprintf(stderr, "Failed to initialise sensor: %s\n", strerror(errno));
            if (i == SENSOR_INIT_RETRIES - 1) {
                exit_handler(EXIT_FAILURE);
            }
            continue;
        }
        break;
    }

    while (1) {
        unsigned char trigger_data[] = {REG_TRIGGER, TRIGGER_VALUE};
        if (spiXfer(spi_handle, trigger_data, NULL, sizeof(trigger_data)) < 0) {
            fprintf(stderr, "Failed to trigger measurement: %s\n", strerror(errno));
            continue;
        }

        unsigned char read_data[] = {REG_DISTANCE_L, 0x00, REG_DISTANCE_H, 0x00};
        unsigned char response[sizeof(read_data)];
        if (spiXfer(spi_handle, read_data, response, sizeof(response)) < 0) {
            fprintf(stderr, "Failed to read distance: %s\n", strerror(errno));
            continue;
        }

        int distance = (response[1] << 8) | response[0];
        time_t now = time(NULL);
        struct tm *local_time = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", local_time);
        fprintf(log_file, "%s,%d\n", timestamp, distance);
        fflush(log_file);

        sleep(100);
    }

    return 0;
}
```

This code initialises the sensor, reads the distance, and logs it to a CSV file. It handles SPI communication errors, sensor initialisation failures, and sensor-absent conditions gracefully, logging errors to stderr and continuing to run indefinitely. It installs SIGINT and SIGTERM handlers that close the SPI handle, release resources, and flush the log file.

