#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60
#define I2C_RETRIES 3
#define I2C_DELAY 10
#define REG_RESET 0x30
#define REG_ID 0x00
#define REG_ALS 0x22
#define REG_PS1 0x18
#define PART_ID 0x41

static volatile sig_atomic_t stop = 0;

static void handle_sigint(int signum) {
    stop = 1;
}

int main() {
    int i2c_handle;
    FILE *log_file;
    struct tm *ts;
    time_t now;
    char time_string[20];
    unsigned char id;
    unsigned char als_data[2];
    unsigned char ps1_data[2];
    int als;
    int ps1;

    signal(SIGINT, handle_sigint);

    i2c_handle = piI2C(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return EXIT_FAILURE;
    }

    if (piI2CWriteByteData(i2c_handle, REG_RESET, 0x01) < 0) {
        fprintf(stderr, "Failed to reset sensor\n");
        goto cleanup_i2c;
    }

    if (piI2CReadByteData(i2c_handle, REG_ID, &id, I2C_RETRIES, I2C_DELAY) < 0) {
        fprintf(stderr, "Failed to read part ID\n");
        goto cleanup_i2c;
    }

    if (id != PART_ID) {
        fprintf(stderr, "Unexpected part ID: 0x%02x\n", id);
        goto cleanup_i2c;
    }

    log_file = fopen("si1120_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        goto cleanup_i2c;
    }

    while (!stop) {
        if (piI2CReadI2CBlockData(i2c_handle, REG_ALS, 2, als_data, I2C_RETRIES, I2C_DELAY) < 0) {
            fprintf(stderr, "Failed to read ALS data\n");
            continue;
        }

        if (piI2CReadI2CBlockData(i2c_handle, REG_PS1, 2, ps1_data, I2C_RETRIES, I2C_DELAY) < 0) {
            fprintf(stderr, "Failed to read PS1 data\n");
            continue;
        }

        als = als_data[0] | (als_data[1] << 8);
        ps1 = ps1_data[0] | (ps1_data[1] << 8);

        now = time(NULL);
        ts = localtime(&now);
        strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", ts);

        fprintf(log_file, "%s, ALS: %d, PS1: %d\n", time_string, als, ps1);
        fflush(log_file);

        usleep(500000);
    }

    fclose(log_file);

cleanup_i2c:
    piI2CSetBus(I2C_BUS);
    piI2CClose(i2c_handle);

    return EXIT_SUCCESS;
}

