static FILE *log_file;

void exit_handler(int signum) {
    fclose(log_file);
    close(i2c_file_descriptor);
    exit(signum);
}

int main() {
    int ret;
    char part_id[2];
    char config[2];
    char ambient_light[2];
    char proximity[2];
    struct timespec ts;
    struct tm tm;
    char timestamp[20];

    i2c_file_descriptor = open("/dev/i2c-1", O_RDWR);
    if (i2c_file_descriptor < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(i2c_file_descriptor, I2C_SLAVE, SENSOR_ADDRESS);
    if (ret < 0) {
        perror("Failed to set sensor address");
        exit(EXIT_FAILURE);
    }

    part_id[0] = PART_ID_REG;
    ret = write(i2c_file_descriptor, part_id, 1);
    if (ret < 0) {
        perror("Failed to write to sensor");
        exit(EXIT_FAILURE);
    }

    ret = read(i2c_file_descriptor, part_id, 1);
    if (ret < 0) {
        perror("Failed to read part ID from sensor");
        exit(EXIT_FAILURE);
    }

    if (part_id[0] != 0x11) {
        fprintf(stderr, "Invalid part ID: 0x%02x\n", part_id[0]);
        exit(EXIT_FAILURE);
    }

    config[0] = CONFIG_REG;
    config[1] = 0x07;
    ret = write(i2c_file_descriptor, config, 2);
    if (ret < 0) {
        perror("Failed to write to sensor");
        exit(EXIT_FAILURE);
    }

    log_file = fopen("biometric_log.txt", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, exit_handler);
    signal(SIGTERM, exit_handler);

    while (1) {
        ambient_light[0] = AMBIENT_LIGHT_REG;
        ret = write(i2c_file_descriptor, ambient_light, 1);
        if (ret < 0) {
            perror("Failed to write to sensor");
            exit(EXIT_FAILURE);
        }

        ret = read(i2c_file_descriptor, ambient_light, 2);
        if (ret < 0) {
            perror("Failed to read ambient light from sensor");
            exit(EXIT_FAILURE);
        }

        proximity[0] = PROXIMITY_REG;
        ret = write(i2c_file_descriptor, proximity, 1);
        if (ret < 0) {
            perror("Failed to write to sensor");
            exit(EXIT_FAILURE);
        }

        ret = read(i2c_file_descriptor, proximity, 2);
        if (ret < 0) {
            perror("Failed to read proximity from sensor");
            exit(EXIT_FAILURE);
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        localtime_r(&ts.tv_sec, &tm);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
        sprintf(timestamp + strlen(timestamp), ".%03ld", ts.tv_nsec / 1e6);

        int ambient_light_val = ambient_light[0] | (ambient_light[1] << 8);
        float lux = ambient_light_val * 0.1;
        int proximity_val = proximity[0] | (proximity[1] << 8);

        fprintf(log_file, "%s,%.2f,%d\n", timestamp, lux, proximity_val);
        printf("%s,%.2f,%d\n", timestamp, lux, proximity_val);

        nanosleep(&ts, NULL);
    }

    return 0;
}

