FILE *log_file;
int i2c_handle;

void sig_handler(int signo) {
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    exit(signo);
}

void write_to_log(const char *message) {
    time_t now = time(0);
    struct tm *time_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", time_info);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio.\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("proximity_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen("/dev/i2c-1", SILABS_I2C_ADDR);
    if (i2c_handle < 0) {
        write_to_log("Failed to open I2C handle.");
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    const int write_sequence[][2] = {
        {0x07, 0x03},
        {0x06, 0x02},
        {0x1A, 0x00},
        {0x21, 0x0B},
        {0x24, 0x00},
        {0x22, 0x49},
