#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27
#define MIN_DISTANCE 20

volatile int echo_rising_edge_time = 0;
volatile int echo_falling_edge_time = 0;
volatile int should_exit = 0;

void echo_alert(int gpio, int level, int tick, void *data) {
    if (level == 0) {
        echo_falling_edge_time = tick;
    } else if (level == 1) {
        echo_rising_edge_time = tick;
    }
}

void handle_sigint(int signum) {
    should_exit = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output.\n", TRIGGER_PIN);
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input.\n", ECHO_PIN);
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output.\n", BUZZER_PIN);
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_alert, NULL) < 0) {
        fprintf(stderr, "Failed to set alert function for GPIO%d.\n", ECHO_PIN);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (!should_exit) {
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(10);
        gpioWrite(TRIGGER_PIN, 0);

        while (echo_rising_edge_time == 0 || echo_falling_edge_time == 0) {
            if (should_exit) {
                break;
            }
            gpioDelay(1);
        }

        if (should_exit) {
            break;
        }

        int distance = (echo_falling_edge_time - echo_rising_edge_time) * 0.0343 / 2;
        printf("Distance: %d cm\n", distance);

        if (distance < MIN_DISTANCE) {
            if (gpioWrite(BUZZER_PIN, 1) < 0) {
                fprintf(stderr, "Failed to set GPIO%d high.\n", BUZZER_PIN);
                return EXIT_FAILURE;
            }
        } else {
            if (gpioWrite(BUZZER_PIN, 0) < 0) {
                fprintf(stderr, "Failed to set GPIO%d low.\n", BUZZER_PIN);
                return EXIT_FAILURE;
            }
        }

        echo_rising_edge_time = 0;
        echo_falling_edge_time = 0;

        gpioDelay(1000);
    }

    gpioTerminate();

    return EXIT_SUCCESS;
}

