#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

#define MIN_DISTANCE 20
#define MAX_DISTANCE 200
#define MIN_PULSE 500
#define MAX_PULSE 2500

volatile int running = 1;

void sigint_handler(int signum) {
    running = 0;
}

double get_distance() {
    static int echo_gpio = -1;
    static int trigger_gpio = -1;
    int i, pulse_ticks;
    double distance;

    if (echo_gpio < 0) {
        echo_gpio = gpioCfg(ECHO_PIN, PI_INPUT);
        if (echo_gpio < 0) {
            printf("Failed to configure echo GPIO: %d\n", echo_gpio);
            return -1.0;
        }
    }

    if (trigger_gpio < 0) {
        trigger_gpio = gpioCfg(TRIGGER_PIN, PI_OUTPUT);
        if (trigger_gpio < 0) {
            printf("Failed to configure trigger GPIO: %d\n", trigger_gpio);
            return -1.0;
        }
    }

    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(20);
    gpioWrite(TRIGGER_PIN, 0);

    for (i = 0; i < 10000; i++) {
        if (gpioRead(ECHO_PIN)) {
            break;
        }
        gpioDelay(1);
    }

    if (i == 10000) {
        printf("Echo timeout\n");
        return -1.0;
    }

    pulse_ticks = i;

    for (; i < 10000; i++) {
        if (!gpioRead(ECHO_PIN)) {
            break;
        }
        gpioDelay(1);
    }

    if (i == 10000) {
        printf("Echo timeout\n");
        return -1.0;
    }

    pulse_ticks = i - pulse_ticks;

    distance = pulse_ticks * 1.0 / 58.0;

    return distance;
}

void set_servo_angle(int pulse) {
    static int servo_gpio = -1;

    if (servo_gpio < 0) {
        servo_gpio = gpioCfg(SERVO_PIN, PI_OUTPUT);
        if (servo_gpio < 0) {
            printf("Failed to configure servo GPIO: %d\n", servo_gpio);
            return;
        }
    }

    gpioPWM(SERVO_PIN, pulse);
}

int main() {
    int pi;

    pi = piGpioInitialise();
    if (pi < 0) {
        printf("Failed to initialise pigpio: %d\n", pi);
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        double distance;
        int pulse;

        distance = get_distance();
        if (distance < 0.0) {
            continue;
        }

        if (distance < MIN_DISTANCE) {
            pulse = MAX_PULSE;
        } else if (distance > MAX_DISTANCE) {
            pulse = MIN_PULSE;
        } else {
            pulse = MIN_PULSE + (MAX_PULSE - MIN_PULSE) * (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE);
        }

        printf("Distance: %.2f cm, Servo pulse: %d us\n", distance, pulse);

        set_servo_angle(pulse);

        gpioDelay(100);
    }

    set_servo_angle(0);

    piGpioTerminate();

    return EXIT_SUCCESS;
}

