#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define GPIO_SERVO 18

#define REG_MODEL_ID 0x010F
#define EXPECTED_MODEL_ID 0xEA
#define REG_TIMING_BUDGET 0x001D
#define START_RANGING_REG 0x0018
#define DISTANCE_REG 0x0082

FILE *log_file;
int i2c_handle;

void cleanup_and_exit(int sig) {
    fclose(log_file);
    piI2CSimpleClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        printf("Error initializing pigpio.\n");
        return 1;
    }

    log_file = fopen("gate_log.txt", "w");
    if (log_file == NULL) {
        printf("Error opening log file.\n");
        gpioTerminate();
        return 1;
    }

    i2c_handle = piI2CSetSlaveAddress(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        printf("Error setting up I2C.\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, cleanup_and_exit);

    if (piI2CWriteByteData(i2c_handle, REG_MODEL_ID, EXPECTED_MODEL_ID) < 0) {
        printf("Error reading model ID.\n");
        cleanup_and_exit(0);
    }

    if (piI2CWriteByteData(i2c_handle, REG_TIMING_BUDGET, 200) < 0) {
        printf("Error setting timing budget.\n");
        cleanup_and_exit(0);
    }

    if (piI2CWriteByteData(i2c_handle, START_RANGING_REG, 1) < 0) {
        printf("Error starting ranging.\n");
        cleanup_and_exit(0);
    }

    gpioSetPWMrange(GPIO_SERVO, 2000);
    gpioSetPWMdutycycle(GPIO_SERVO, 1000);

    int servo_open = 0;
    while (1) {
        int distance;
        if (piI2CReadWordData(i2c_handle, DISTANCE_REG, &distance) < 0) {
            printf("Error reading distance.\n");
            cleanup_and_exit(0);
        }

        if (distance < 200 && !servo_open) {
            gpioSetPWMdutycycle(GPIO_SERVO, 2000);
            servo_open = 1;
            time_t t = time(NULL);
            char* timestamp = ctime(&t);
            timestamp[strlen(timestamp)-1] = '\0';
            fprintf(log_file, "%s: Gate opened\n", timestamp);
        } else if (distance >= 250 && servo_open) {
            gpioSetPWMdutycycle(GPIO_SERVO, 1000);
            servo_open = 0;
            time_t t = time(NULL);
            char* timestamp = ctime(&t);
            timestamp[strlen(timestamp)-1] = '\0';
            fprintf(log_file, "%s: Gate closed\n", timestamp);
        }
    }

    cleanup_and_exit(0);
}

