#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18
#define TIMEOUT 50000

volatile int stop = 0;

void sigint_handler(int signo) {
    gpioServo(SERVO_PIN, 0);
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    signal(SIGINT, sigint_handler);

    while (!stop) {
        gpioWrite(TRIGGER_PIN, 1);
        delay(10);
        gpioWrite(TRIGGER_PIN, 0);

        int edge = gpioCfgTimeout(ECHO_PIN, TIMEOUT, PI_TIMEOUT_RISING_EDGE);
        if (edge < 0) {
            fprintf(stderr, "Failed to configure timeout for rising edge\n");
            break;
