#define I2C_BUS 1
#define I2C_ADDR 0x40
#define I2C_CONFIG_REG 0x03
#define I2C_TEMP_REG 0x01
#define I2C_HUMIDITY_REG 0x02

static int i2c_handle;
static volatile sig_atomic_t stop = 0;

void sigint_handler(int signum) {
    stop = 1;
}

int main() {
    struct sigaction action;
    action.sa_handler = sigint_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);

    if (piGpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    i2c_handle = piI2C(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return EXIT_FAILURE;
    }

    while (!stop) {
        if (piI2CWriteByte(i2c_handle, I2C_CONFIG_REG) < 0 ||
            piDelay(10) < 0 ||
            piI2CWriteByte(i2c_handle, 0x00) < 0 ||
            piDelay(10) < 0 ||
            piI2CReadWord(i2c_handle, I2C_TEMP_REG) < 0 ||
            piI2CReadWord(i2c_handle, I2C_HUMIDITY_REG) < 0) {
            fprintf(stderr, "I2C operation failed, reopening I2C bus\n");
            piI2CClose(i2c_handle);
            sleep(1);
            i2c_handle = piI2C(I2C_BUS, I2C_ADDR);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to reopen I2C bus: %d\n", i2c_handle);
                return EXIT_FAILURE;
            }
            continue;
        }

        int16_t temp_raw = piI2CResult();
        int16_t humidity_raw = piI2CResult();

        double temp = (175.72 * temp_raw) / 65536.0 - 46.85;
        double humidity = (125.0 * humidity_raw) / 65536.0 - 6.0;

        printf("Temperature: %.2f C, Humidity: %.2f%%\n", temp, humidity);

        sleep(2);
    }

    piI2CClose(i2c_handle);
    piGpioTerminate();

    return EXIT_SUCCESS;
}

