#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define MPU_ADDR 0x68
#define MPU_WHOAMI_REG 0x00
#define MPU_WHOAMI_VAL 0x68
#define MPU_PWR_MGMT_1 0x6B
#define MPU_SAMPLE_RATE_REG 0x19
#define MPU_ACCEL_CONFIG_REG 0x1C
#define MPU_GYRO_CONFIG_REG 0x1B
#define MPU_READ_REG 0x3B

static int i2c_handle;

void cleanup_and_exit(int sig) {
    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        if (i2cClose(i2c_handle) < 0) {
            printf("Error closing I2C handle: %s\n", strerror(errno));
        }
    }
    if (gpioTerminate() < 0) {
        printf("Error terminating GPIO: %s\n", strerror(errno));
    }
    exit(0);
}

int main() {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    printf("Starting up...\n");

    if (gpioInitialise() < 0) {
        printf("Error initializing GPIO: %s\n", strerror(errno));
        return 1;
    }

    i2c_handle = i2cOpen("/dev/i2c-1", MPU_ADDR);
    if (i2c_handle < 0) {
        printf("Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, MPU_PWR_MGMT_1, 0x00) < 0) {
        printf("Error writing to MPU_PWR_MGMT_1: %s\n", strerror(errno));
        return 1;
    }

    usleep(1000);

    if (i2cWriteByteData(i2c_handle, MPU_PWR_MGMT_1, 0x01) < 0) {
        printf("Error writing to MPU_PWR_MGMT_1: %s\n", strerror(errno));
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, MPU_SAMPLE_RATE_REG, 0x07) < 0) {
        printf("Error writing to MPU_SAMPLE_RATE_REG: %s\n", strerror(errno));
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, MPU_ACCEL_CONFIG_REG, 0x00) < 0) {
        printf("Error writing to MPU_ACCEL_CONFIG_REG: %s\n", strerror(errno));
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, MPU_GYRO_CONFIG_REG, 0x00) < 0) {
        printf("Error writing to MPU_GYRO_CONFIG_REG: %s\n", strerror(errno));
        return 1;
    }

    uint8_t whoami;
    if (i2cReadByteData(i2c_handle, MPU_WHOAMI_REG, &whoami) < 0) {
        printf("Error reading from MPU_WHOAMI_REG: %s\n", strerror(errno));
        return 1;
    }

    if (whoami != MPU_WHOAMI_VAL) {
        printf("Unexpected device ID: 0x%02x\n", whoami);
        return 1;
    }

    uint8_t data[14];
    while (1) {
        if (i2cReadI2CBlockData(i2c_handle, MPU_READ_REG, 14, data) < 0) {
            printf("Error reading from MPU_READ_REG: %s\n", strerror(errno));
            return 1;
        }

        int16_t accel_x = (data[0] << 8) | data[1];
        int16_t accel_y = (data[2] << 8) | data[3];
        int16_t accel_z = (data[4] << 8) | data[5];
        int16_t temp = (data[6] << 8) | data[7];
        int16_t gyro_x = (data[8] << 8) | data[9];
        int16_t gyro_y = (data[10] << 8) | data[11];
        int16_t gyro_z = (data[12] << 8) | data[13];

        printf("Accel: %5d %5d %5d, Temp: %5d, Gyro: %5d %5d %5d\n",
               accel_x, accel_y, accel_z, temp, gyro_x, gyro_y, gyro_z);

        usleep(100000);
    }

    return 0;
}

