#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <string.h>

#define SHT40_ADDR 0x44
#define SHT40_CMD 0xFD

volatile sig_atomic_t stop = 0;

void handle_signal(int signum) {
    stop = 1;
}

int validate_crc(const char *data, int len) {
    int crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc == 0;
}

int main() {
    struct sigaction action;
    action.sa_handler = handle_signal;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    int pi = pigpio_start();
    if (pi < 0) {
        fprintf(stderr, "Could not start pigpio\n");
        return EXIT_FAILURE;
    }

    int handle = i2c_open(1, SHT40_ADDR);
    if (handle < 0) {
        fprintf(stderr, "Could not open I2C bus\n");
        pigpio_stop(pi);
        return EXIT_FAILURE;
    }

    while (!stop) {
        int err = i2c_write_byte(handle, SHT40_CMD);
        if (err < 0) {
            fprintf(stderr, "Could not write to I2C bus\n");
            i2c_close(handle);
            usleep(10000);
            handle = i2c_open(1, SHT40_ADDR);
            if (handle < 0) {
                fprintf(stderr, "Could not re-open I2C bus\n");
                pigpio_stop(pi);
                return EXIT_FAILURE;
            }
            continue;
        }

        usleep(10000);

        char buf[6];
        err = i2c_read(handle, buf, sizeof(buf));
        if (err < 0) {
            fprintf(stderr, "Could not read from I2C bus\n");
            i2c_close(handle);
            usleep(10000);
            handle = i2c_open(1, SHT40_ADDR);
            if (handle < 0) {
                fprintf(stderr, "Could not re-open I2C bus\n");
                pigpio_stop(pi);
                return EXIT_FAILURE;
            }
            continue;
        }

        if (!validate_crc(buf, 2) || !validate_crc(buf + 2, 2)) {
            fprintf(stderr, "CRC validation failed\n");
            continue;
        }

        int t_raw = (buf[0] << 8) | buf[1];
        int rh_raw = (buf[3] << 8) | buf[4];
        float t = -45.0 + 175.0 * t_raw / 65535.0;
        float rh = -6.0 + 125.0 * rh_raw / 65535.0;

        printf("Temperature: %.2f C, Humidity: %.2f%%\n", t, rh);

        sleep(5);
    }

    i2c_close(handle);
    pigpio_stop(pi);

    return EXIT_SUCCESS;
}

