#define MLX90614_OBJECT_TEMP_REG 0x07
#define LOG_FILE "temperature_log.csv"

static int i2c_file_descriptor = -1;
static FILE* log_file = NULL;

static void cleanup_and_exit(int signum) {
    if (i2c_file_descriptor != -1) {
        close(i2c_file_descriptor);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(signum);
}

int main() {
    int ret;
    unsigned char buffer[2];

    i2c_file_descriptor = open("/dev/i2c-1", O_RDWR);
    if (i2c_file_descriptor == -1) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    ret = ioctl(i2c_file_descriptor, I2C_SLAVE, MLX90614_I2C_ADDR);
    if (ret == -1) {
        perror("Failed to set I2C slave address");
        cleanup_and_exit(EXIT_FAILURE);
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup_and_exit(EXIT_FAILURE);
    }

