FILE *log_file, *error_log;
int i2c_handle;

void cleanup_and_exit(int sig) {
    if (log_file) fclose(log_file);
    if (error_log) fclose(error_log);
    if (i2c_handle >= 0) piI2CClose(i2c_handle);
    exit(sig);
}

int main() {
    signal(SIGINT, cleanup_and_exit);

    log_file = fopen("enclosure_temp_log.txt", "w");
    if (!log_file) {
        printf("Failed to open log file\n");
        return 1;
    }

    error_log = fopen("error_log.txt", "w");
    if (!error_log) {
        printf("Failed to open error log file\n");
        cleanup_and_exit(1);
    }

    i2c_handle = piI2C(I2C_BUS, SENSOR_ADDR);
    if (i2c_handle < 0) {
        fprintf(error_log, "Failed to open I2C handle: %s\n", piErrorMessage(i2c_handle));
        cleanup_and_exit(1);
    }

    while (1) {
        int status, temp;
        unsigned char buffer[2];

        status = piI2CRead(i2c_handle, buffer, 2);
        if (status < 0) {
            fprintf(error_log, "I2C read error: %s\n", piErrorMessage(status));
            cleanup_and_exit(1);
        }

        temp = (buffer[0] << 8) | buffer[1];
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);

        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);

        fprintf(log_file, "%s, %d\n", timestamp, temp);
        fflush(log_file);

        sleep(5);
