#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>

#define SHT40_ADDR 0x44
#define SHT40_MEASURE_HIGH_REP 0xFD
#define SHT40_CRC_POLYNOMIAL 0x31
#define SHT40_CRC_INITIAL 0xFF

int i2c_fd = -1;
FILE *log_file = NULL;

void cleanup_and_exit(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int sht40_crc8(const unsigned char *data, int length) {
    unsigned char crc = SHT40_CRC_INITIAL;
    for (int i = 0; i < length; ++i) {
        crc ^= data[i];
        for (int j = 0; j < 8; ++j) {
            if (crc & 0x80) {
                crc <<= 1;
                crc ^= SHT40_CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    struct tm *timeinfo;
    char timestamp[20];
    unsigned char read_buf[6];
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    log_file = fopen("sht40_log.txt", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_ADDR) == -1) {
        perror("Failed to set I2C slave address");
        return 1;
    }

    while (1) {
        if (write(i2c_fd, &SHT40_MEASURE_HIGH_REP, 1) != 1) {
            fprintf(log_file, "Failed to write to sensor\n");
            fflush(log_file);
            sleep(1);
            continue;
        }
        usleep(10000);
        if (read(i2c_fd, read_buf, sizeof(read_buf)) != sizeof(read_buf)) {
            fprintf(log_file, "Failed to read from sensor\n");
            fflush(log_file);
            sleep(1);
            continue;
        }
        if (sht40_crc8(read_buf, 2) != read_buf[2] || sht40_crc8(read_buf + 3, 2) != read_buf[5]) {
            fprintf(log_file, "CRC check failed\n");
            fflush(log_file);
            sleep(1);
            continue;
        }
        int temperature = (read_buf[0] << 8 | read_buf[1]) * 175.0f / 65535.0f - 45.0f;
        int humidity = (read_buf[3] << 8 | read_buf[4]) * 100.0f / 65535.0f;
        time_t now = time(NULL);
        timeinfo = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(log_file, "%s: Temperature = %d C, Humidity = %d%%\n", timestamp, temperature, humidity);
        fflush(log_file);
        sleep(5);
    }

    return 0;
}

