#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define SDP31_ADDRESS 0x28
#define SDP31_TRIGGER_CMD {0x21, 0x96}
#define SDP31_DATA_LEN 6

volatile sig_atomic_t stop = 0;
FILE *log_file;
int i2c_handle;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        stop = 1;
    }
}

int retry_i2c_write(int handle, const char *data, int len, int retries) {
    int i;
    for (i = 0; i <= retries; i++) {
        if (i2cWriteDevice(handle, data, len) == 0) {
            return 0;
        }
        if (i < retries) {
            usleep(1000 * (1 << i));
        }
    }
    return -1;
}

int retry_i2c_read(int handle, char *data, int len, int retries) {
    int i;
    for (i = 0; i <= retries; i++) {
        if (i2cReadDevice(handle, data, len) == len) {
            return 0;
        }
        if (i < retries) {
            usleep(1000 * (1 << i));
        }
    }
    return -1;
}

int main() {
    struct sigaction sigIntHandler;
    sigIntHandler.sa_handler = sig_handler;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_flags = 0;
    sigaction(SIGINT, &sigIntHandler, NULL);
    sigaction(SIGTERM, &sigIntHandler, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("airflow.log", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, SDP31_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (!stop) {
        if (retry_i2c_write(i2c_handle, SDP31_TRIGGER_CMD, sizeof(SDP31_TRIGGER_CMD), 3) < 0) {
            fprintf(stderr, "Failed to write to I2C device\n");
            break;
        }

        usleep(1000);

        char data[SDP31_DATA_LEN];
        if (retry_i2c_read(i2c_handle, data, SDP31_DATA_LEN, 3) < 0) {
            fprintf(stderr, "Failed to read from I2C device\n");
            break;
        }

        int pressure = (data[0] << 8) | data[1];
        int temperature = (data[3] << 8) | data[4];
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld,%.2f,%.2f\n", ts.tv_sec, ts.tv_nsec, pressure / 60.0, temperature / 200.0);
        fflush(log_file);

        usleep(100000);
    }

    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}

