int i2c_fd, log_fd;

void cleanup_and_exit(int signum) {
    close(i2c_fd);
    close(log_fd);
    exit(signum);
}

unsigned char crc8(unsigned char *data, int len) {
    unsigned char crc = 0;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            else
                crc <<= 1;
        }
    }
    return crc;
}

int main() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    log_fd = open("airflow_data.txt", O_CREAT | O_TRUNC | O_WRONLY, 0644);
    if (log_fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

