        if (write(i2c_fd, &SDP800_TRIGGER_CMD, 2) != 2) {
            perror("write");
            exit(EXIT_FAILURE);
        }

        usleep(45000);

        if (read(i2c_fd, buf, SDP800_DATA_LEN) != SDP800_DATA_LEN) {
            perror("read");
            exit(EXIT_FAILURE);
        }

        if (crc8(buf, 2) != 0 || crc8(buf + 3, 2) != 0 || crc8(buf + 6, 2) != 0) {
            fprintf(stderr, "CRC error\n");
