        int temperature_raw = (buf[3] << 8) | buf[4];
        int scale_factor = (buf[6] << 8) | buf[7];

        double pressure_pa = (double)pressure_raw / scale_factor;
        double temperature_c = (double)temperature_raw / 200 - 45;

        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        dprintf(log_fd, "%ld.%09ld,%.2f,%.2f\n", ts.tv_sec, ts.tv_nsec, pressure_pa, temperature_c);

        usleep(100000);
    }

    return 0;
}

