#define I2C_BUS 1
#define I2C_ADDR 0x4A
#define I2C_HANDLE -1

#define SINGLE_SHOT_CMD 0x2C06
#define SLEEP_TIME 5000000
#define READ_LEN 3

volatile sig_atomic_t stop;

int i2c_handle = I2C_HANDLE;
FILE *log_file = NULL, *error_file = NULL;

void sigint_handler(int signum) {
    stop = 1;
}

int crc8(const unsigned char *data, int length) {
    int crc = 0xFF;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc & 0xFF;
}

void log_error(const char *msg) {
    if (error_file) {
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
        fprintf(error_file, "%s: %s\n", timestamp, msg);
        fflush(error_file);
    }
}

int main() {
    signal(SIGINT, sigint_handler);

    if ((i2c_handle = piI2C(I2C_BUS, I2C_ADDR)) < 0) {
        log_error("Failed to initialise I2C");
        return EXIT_FAILURE;
    }

    if (!(log_file = fopen("enclosure_temp_log.txt", "a"))) {
        log_error("Failed to open log file");
        return EXIT_FAILURE;
    }

    if (!(error_file = fopen("error_log.txt", "a"))) {
        log_error("Failed to open error log file");
        return EXIT_FAILURE;
    }

    while (!stop) {
        unsigned char cmd[2] = {SINGLE_SHOT_CMD >> 8, SINGLE_SHOT_CMD & 0xFF};
        if (piI2CWrite(i2c_handle, cmd, sizeof(cmd)) < 0) {
            log_error("Failed to write to I2C");
            continue;
        }

        usleep(SLEEP_TIME);

        unsigned char data[READ_LEN];
        if (piI2CRead(i2c_handle, data, READ_LEN) < 0) {
            log_error("Failed to read from I2C");
            continue;
        }

        if (crc8(data, READ_LEN) != 0) {
            log_error("CRC mismatch");
            continue;
        }

        int raw = (data[0] << 8) | data[1];
        float temp = -45.0 + 175.0 * raw / 65535.0;

        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

        fprintf(log_file, "%s: %.2f\n", timestamp, temp);
        fflush(log_file);
    }

    fclose(log_file);
    fclose(error_file);
    piI2CClose(i2c_handle);

    return EXIT_SUCCESS;
}

