#define SHT40_ADDR 0x44
#define SHT40_MEASURE_HIGH_REP 0xFD
#define I2C_FILE "/dev/i2c-1"
#define LOG_FILE "sht40_log.txt"

volatile sig_atomic_t stop = 0;

int i2c_file = -1;
