int sht40_crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

void sigint_handler(int signum) {
    stop = 1;
    if (i2c_file != -1)
        close(i2c_file);
    if (log_file != NULL)
        fclose(log_file);
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);

    i2c_file = open(I2C_FILE, O_RDWR);
    if (i2c_file == -1) {
        perror("Failed to open I2C device");
        return 1;
    }
    if (ioctl(i2c_file, I2C_SLAVE, SHT40_ADDR) == -1) {
        perror("Failed to set I2C slave address");
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    unsigned char data[6];
    while (!stop) {
        if (write(i2c_file, &SHT40_MEASURE_HIGH_REP, 1) != 1) {
            perror("Failed to write to I2C device");
            continue;
        }
        usleep(8500);
        if (read(i2c_file, &data, 6) != 6) {
            perror("Failed to read from I2C device");
            continue;
        }
        if (sht40_crc8(data, 2) != data[2] || sht40_crc8(data + 3, 2) != data[5]) {
