        int humidity = ((data[3] << 8) | data[4]) * 100.0f / 65535.0f;
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestr[20];
        strftime(timestr, sizeof(timestr), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(log_file, "%s: Temperature = %d C, Humidity = %d%%\n", timestr, temperature, humidity);
        fflush(log_file);
        sleep(5);
    }

