#define SDP800_MEASURE_CMD 0x362F
#define SDP800_RESPONSE_LEN 6
#define SDP800_PRESSURE_SCALE 240
#define SDP800_TEMP_SCALE 200
#define SDP800_TEMP_OFFSET -45

#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

int i2c_fd = -1;
FILE *log_file = NULL;

void cleanup_and_exit(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(sig);
}

