    unsigned char crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    signal(SIGINT, cleanup_and_exit);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        cleanup_and_exit(-1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP800_ADDR) == -1) {
        perror("Failed to set I2C slave address");
        cleanup_and_exit(-1);
    }

    unsigned char cmd[2] = {SDP800_MEASURE_CMD >> 8, SDP800_MEASURE_CMD & 0xFF};
    if (write(i2c_fd, cmd, sizeof(cmd)) != sizeof(cmd)) {
        perror("Failed to write to I2C device");
        cleanup_and_exit(-1);
    }

    usleep(1000);  // wait at least 1 ms

    unsigned char response[SDP800_RESPONSE_LEN];
    if (read(i2c_fd, response, sizeof(response)) != sizeof(response)) {
        perror("Failed to read from I2C device");
        cleanup_and_exit(-1);
    }

    unsigned short pressure = (response[0] << 8) | response[1];
    unsigned char pressure_crc = crc8(&response[0], 2);
    if (pressure_crc != response[2]) {
        fprintf(stderr, "Pressure CRC mismatch: 0x%02X != 0x%02X\n", pressure_crc, response[2]);
        cleanup_and_exit(-1);
    }

    unsigned short temp = (response[3] << 8) | response[4];
    unsigned char temp_crc = crc8(&response[3], 2);
    if (temp_crc != response[5]) {
        fprintf(stderr, "Temperature CRC mismatch: 0x%02X != 0x%02X\n", temp_crc, response[5]);
        cleanup_and_exit(-1);
    }

    log_file = fopen("airflow_data.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup_and_exit(-1);
    }

    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f, %.2f\n", timestamp, pressure / (float)SDP800_PRESSURE_SCALE,
            (temp / (float)SDP800_TEMP_SCALE) + SDP800_TEMP_OFFSET);

    cleanup_and_exit(0);
}

