#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_ADDR 0x40
#define SENSOR_BUS 1
#define FAN_GPIO 18
#define MAX_RETRIES 3
#define TEMP_THRESHOLD 28.0
#define TEMP_HYSTERESIS 1.0
#define READING_INTERVAL 2000
#define BUF_SIZE 60

struct reading {
    time_t timestamp;
    float temp;
    float humidity;
};

struct context {
    int i2c_handle;
    int fan_gpio;
    int current_state;
    struct reading buf[BUF_SIZE];
    int buf_head;
    int buf_tail;
};

void handle_sigint(int signum) {
    struct context *ctx = (struct context *)signal_context;
    ctx->current_state = 0;
    piGpioWrite(ctx->fan_gpio, 0);
    piI2CSpectate(ctx->i2c_handle);
    gpioTerminate();
    exit(0);
}

int read_sensor(struct context *ctx, int cmd, float *value) {
    unsigned char buf[3];
    int retries = 0;

    while (retries <= MAX_RETRIES) {
        if (piI2CWriteByte(ctx->i2c_handle, cmd) == 0) {
            usleep(10000);
            if (piI2CReadBytes(ctx->i2c_handle, buf, 2) == 2) {
                int raw = (buf[0] << 8) | buf[1];
                *value = ((cmd == 0xE3) ? (175.72 * raw / 65536.0 - 46.85) : (125.0 * raw / 65536.0 - 6.0));
                return 1;
            }
        }
        retries++;
    }

    return 0;
}

void update_fan_state(struct context *ctx, float temp) {
    int new_state = (temp > TEMP_THRESHOLD) ? 1 : ((temp < TEMP_THRESHOLD - TEMP_HYSTERESIS) ? 0 : ctx->current_state);
    if (new_state != ctx->current_state) {
        ctx->current_state = new_state;
        piGpioWrite(ctx->fan_gpio, new_state);
    }
}

void log_reading(struct context *ctx, struct reading r) {
    ctx->buf[ctx->buf_head] = r;
    ctx->buf_head = (ctx->buf_head + 1) % BUF_SIZE;
    if (ctx->buf_head == ctx->buf_tail)
        ctx->buf_tail = (ctx->buf_tail + 1) % BUF_SIZE;

    for (int i = ctx->buf_tail; i != ctx->buf_head; i = (i + 1) % BUF_SIZE) {
        struct reading *r = &ctx->buf[i];
        printf("%ld: temp = %.1f, humidity = %.1f\n", r->timestamp, r->temp, r->humidity);
    }
}

int main() {
    struct context ctx;
    memset(&ctx, 0, sizeof(ctx));

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    ctx.i2c_handle = piI2CSetup(SENSOR_BUS);
    if (ctx.i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    if (piI2CSetSlaveAddr(ctx.i2c_handle, SENSOR_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        piI2CSpectate(ctx.i2c_handle);
        gpioTerminate();
        return 1;
    }

    ctx.fan_gpio = FAN_GPIO;
    if (piGpioSetMode(ctx.fan_gpio, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        piI2CSpectate(ctx.i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        float temp, humidity;
        if (read_sensor(&ctx, 0xE3, &temp) && read_sensor(&ctx, 0xE5, &humidity)) {
            struct reading r = { time(NULL), temp, humidity };
            log_reading(&ctx, r);
            update_fan_state(&ctx, temp);
        }

        usleep(READING_INTERVAL * 1000);
    }

    return 0;
}

