#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SCD40_I2C_BUS 1
#define SCD40_I2C_ADDR 0x62

#define SCD40_CMD_START_MEASUREMENT 0x21B1
#define SCD40_CMD_STOP_MEASUREMENT 0x3F86
#define SCD40_CMD_READ_DATA_READY 0xE4B8
#define SCD40_CMD_READ_DATA 0xEC05

#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL 0xFF

static int i2c_handle = -1;
static FILE *log_file = NULL;

static void cleanup_and_exit(int sig) {
    if (i2c_handle >= 0) {
        if (i2cCommand(i2c_handle, SCD40_CMD_STOP_MEASUREMENT) != 0) {
            fprintf(stderr, "Failed to send Stop Measurement command\n");
        }
        if (i2cClose(i2c_handle) != 0) {
            fprintf(stderr, "Failed to close I2C handle\n");
        }
    }
    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Failed to close log file\n");
        }
    }
    if (piStop() != 0) {
        fprintf(stderr, "Failed to stop pigpio\n");
    }
    exit(0);
}

static int crc8(const unsigned char *data, int len, int crc) {
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (piInit() != 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }
    i2c_handle = i2cOpen(SCD40_I2C_BUS, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }
    if (i2cCommand(i2c_handle, SCD40_CMD_START_MEASUREMENT) != 0) {
        fprintf(stderr, "Failed to send Start Measurement command\n");
        return 1;
    }
    sleep(1);
    log_file = fopen("air_quality.log", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }
    signal(SIGINT, cleanup_and_exit);
    unsigned char buffer[9];
    while (1) {
        if (i2cCommand(i2c_handle, SCD40_CMD_READ_DATA_READY) != 0) {
            fprintf(stderr, "Failed to read Data Ready flag\n");
            return 1;
        }
        if (buffer[0] != 0x01) {
            usleep(100000);
            continue;
        }
        if (i2cCommand(i2c_handle, SCD40_CMD_READ_DATA) != 0) {
            fprintf(stderr, "Failed to read data\n");
            return 1;
        }
        if (crc8(buffer, 9, CRC8_INITIAL) != 0) {
            fprintf(stderr, "CRC check failed\n");
            return 1;
        }
        int co2 = buffer[1] << 8 | buffer[2];
        int temperature = -45 + 175 * ((buffer[3] << 8 | buffer[4]) / 65535.0);
        int humidity = 100 * ((buffer[5] << 8 | buffer[6]) / 65535.0);
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(log_file, "%s,%d,%d,%d\n", timestamp, co2, temperature, humidity);
        fflush(log_file);
        sleep(5);
    }
    return 0;
}

