            fprintf(stderr, "Failed to read Data Ready flag\n");
            return 1;
        }
        if (buffer[0] != 0x01) {
            usleep(100000);
            continue;
        }
        if (i2cCommand(i2c_handle, SCD40_CMD_READ_DATA) != 0) {
            fprintf(stderr, "Failed to read data\n");
            return 1;
        }
        if (crc8(buffer, 9, CRC8_INITIAL) != 0) {
            fprintf(stderr, "CRC check failed\n");
            return 1;
        }
        int co2 = buffer[1] << 8 | buffer[2];
        int temperature = -45 + 175 * ((buffer[3] << 8 | buffer[4]) / 65535.0);
        int humidity = 100 * ((buffer[5] << 8 | buffer[6]) / 65535.0);
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(log_file, "%s,%d,%d,%d\n", timestamp, co2, temperature, humidity);
        fflush(log_file);
        sleep(5);
    }
    return 0;
}
