#define CIRCULAR_BUFFER_SIZE 20

struct measurement {
    uint16_t co2;
    int16_t temperature;
    uint16_t humidity;
};

struct measurement circular_buffer[CIRCULAR_BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;
int buffer_count = 0;

int pi, i2c;

void cleanup(int signum) {
    // stop periodic measurement
    uint8_t cmd[] = {0x21, 0xB1, 0x00};
    if (i2cWrite(i2c, cmd, sizeof(cmd)) < 0) {
        printf("i2cWrite failed\n");
    }

    // close i2c handle
    if (i2cClose(i2c) < 0) {
        printf("i2cClose failed\n");
    }

    // release gpio
    gpioTerminate();

    // terminate pigpio
    piStop();

    exit(0);
}

int main() {
    // initialize pigpio
    pi = piGpioInitialise();
    if (pi < 0) {
        printf("piGpioInitialise failed\n");
        return -1;
    }

    // initialize gpio 17 as output
    if (gpioInitialise() < 0) {
        printf("gpioInitialise failed\n");
        return -1;
    }
    if (gpioSetMode(17, PI_OUTPUT) < 0) {
        printf("gpioSetMode failed\n");
        return -1;
    }

    // initialize i2c
    i2c = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c < 0) {
        printf("i2cOpen failed\n");
        return -1;
    }

    // set up signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // start periodic measurement
    uint8_t cmd[] = {0x21, 0xB1, 0x05};
    if (i2cWrite(i2c, cmd, sizeof(cmd)) < 0) {
        printf("i2cWrite failed\n");
        return -1;
    }

    while (1) {
        // poll get_data_ready_status
        uint8_t status[2];
        if (i2cRead(i2c, status, sizeof(status)) < 0) {
            printf("i2cRead failed\n");
            return -1;
        }
        if ((status[0] & 0x01) == 0) {
            // data not ready, sleep for measurement interval
            sleep(MEASUREMENT_INTERVAL);
            continue;
        }

        // read_measurement
        uint8_t data[9];
        if (i2cRead(i2c, data, sizeof(data)) < 0) {
            printf("i2cRead failed\n");
            return -1;
        }

        // validate CRC-8 checksum
        uint8_t crc = 0;
        for (int i = 0; i < 8; i++) {
            crc = crc8(crc, data[i]);
        }
        if (crc != data[8]) {
            printf("CRC-8 checksum failed\n");
            continue;
        }

        // store measurement in circular buffer
        struct measurement m;
        m.co2 = (data[0] << 8) | data[1];
        m.temperature = (data[2] << 8) | data[3];
        m.humidity = (data[4] << 8) | data[5];
        circular_buffer[buffer_head] = m;
        buffer_head = (buffer_head + 1) % CIRCULAR_BUFFER_SIZE;
        if (buffer_count < CIRCULAR_BUFFER_SIZE) {
            buffer_count++;
        } else {
            buffer_tail = (buffer_tail + 1) % CIRCULAR_BUFFER_SIZE;
        }

        // print measurement
        printf("CO2: %u, Temperature: %d, Humidity: %u\n", m.co2, m.temperature, m.humidity);

        // set LED state
        if (gpioWrite(17, m.co2 > CO2_THRESHOLD ? PI_HIGH : PI_LOW) < 0) {
            printf("gpioWrite failed\n");
            return -1;
        }
    }

    return 0;
}

