        int edge = gpioWaitForEdge(GPIO, PI_EITHER_EDGE, TIMEOUT);
        if (edge < 0) {
            log_temperature(NAN);
            failure_count++;
            if (failure_count >= 3) {
                log_temperature(-9999);
                break;
            }
            continue;
        }

        int tick = gpioTick();
        int high = gpioRead(GPIO);
        int low = !high;

        int th = 0;
        int tl = 0;
        while (!stop && gpioRead(GPIO) == high) {
            int now = gpioTick();
            if (now < tick || now - tick > TIMEOUT) {
                log_temperature(NAN);
                failure_count++;
                if (failure_count >= 3) {
                    log_temperature(-9999);
                    break;
                }
                break;
            }
            th += now - tick;
            tick = now;
        }

        if (stop || failure_count >= 3) {
            break;
        }

        while (!stop && gpioRead(GPIO) == low) {
            int now = gpioTick();
            if (now < tick || now - tick > TIMEOUT) {
                log_temperature(NAN);
                failure_count++;
                if (failure_count >= 3) {
                    log_temperature(-9999);
                    break;
                }
                break;
            }
            tl += now - tick;
            tick = now;
        }

        if (stop || failure_count >= 3 || tl < TL_MIN || tl > TL_MAX) {
            break;
        }

        double temperature = 4215 - (2143.0 * th / tl);
        log_temperature(temperature);
        failure_count = 0;

        usleep(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}

