#include <pigpio.h>

#define SHT35_ADDR 0x44
#define SHT35_MEASURE_COMMAND 0x2400
#define SHT35_CRC_POLYNOMIAL 0x31
#define MAX_RETRIES 3
#define LOG_FILE "environmental_data.txt"

FILE *log_file;
int i2c_handle;

void log_data(float temp, float humidity) {
    time_t now = time(NULL);
    struct tm *utc_time = gmtime(&now);
    fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02dZ %.2f %.2f\n",
            utc_time->tm_year + 1900, utc_time->tm_mon + 1, utc_time->tm_mday,
            utc_time->tm_hour, utc_time->tm_min, utc_time->tm_sec, temp, humidity);
    fflush(log_file);
}

void handle_signal(int signum) {
    piI2CSimpleClose(i2c_handle);
    fclose(log_file);
    piGpioInitialise();
    exit(0);
}

int main() {
    if (piGpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    i2c_handle = piI2CSetup(1);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        int retries = 0;
        float temp = 0, humidity = 0;
        while (retries < MAX_RETRIES) {
            if (piI2CSimpleWrite16(i2c_handle, SHT35_ADDR, SHT35_MEASURE_COMMAND) < 0) {
                fprintf(stderr, "Failed to write to I2C bus\n");
                sleep(1);
                retries++;
                continue;
            }

            usleep(15000);

            unsigned char data[6];
            if (piI2CSimpleRead(i2c_handle, SHT35_ADDR, data, sizeof(data)) < 0) {
                fprintf(stderr, "Failed to read from I2C bus\n");
                sleep(1);
                retries++;
                continue;
            }

            int temp_word = (data[0] << 8) | data[1];
            int humidity_word = (data[3] << 8) | data[4];

            int crc = 0;
            for (int i = 0; i < 6; i++) {
                crc ^= data[i];
                for (int j = 0; j < 8; j++) {
                    if (crc & 0x80) {
                        crc ^= SHT35_CRC_POLYNOMIAL;
                    }
                    crc <<= 1;
                }
            }

            if (crc != data[5]) {
                fprintf(stderr, "CRC failed\n");
                sleep(1);
                retries++;
                continue;
            }

            temp = (float)((175.72 * temp_word / 65535.0) - 46.85);
            humidity = (float)((100.0 * humidity_word / 65535.0) - 2.5);
            retries = 0;
            break;
        }

        if (retries == MAX_RETRIES) {
            log_data(NAN, NAN);
        } else {
            time_t now = time(NULL);
            double t = difftime(now, time(NULL));
            temp += 4 * sin(t / 3600.0 * 2 * M_PI);
            humidity += 5 * sin(t / 3600.0 * 2 * M_PI);
            log_data(temp, humidity);
        }

        sleep(5);
    }

    return 0;
}

