#define CRC8_INITIAL 0xFF

#define SAMPLE_INTERVAL 5

static int i2c_handle = -1;

static int crc8(const unsigned char *data, int length, int polynomial, int initial) {
    int crc = initial;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc & 0xFF;
}

static void write_csv(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    FILE *file = fopen("environment.csv", "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open environment.csv for writing\n");
        return;
    }

    if (fseek(file, 0, SEEK_END) == 0 && ftell(file) == 0) {
        fprintf(file, "timestamp,temperature_c,humidity_pct\n");
    }

    fprintf(file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(file);
}

static void sample(void) {
    unsigned char command[2] = {SHT35_MEASURE_COMMAND >> 8, SHT35_MEASURE_COMMAND & 0xFF};
    if (i2cWrite(i2c_handle, command, 2) != 2) {
        fprintf(stderr, "Failed to write command to SHT35\n");
        return;
    }

    usleep(15000);

    unsigned char data[6];
    if (i2cRead(i2c_handle, data, 6) != 6) {
        fprintf(stderr, "Failed to read data from SHT35\n");
        return;
    }

    int temperature = (data[0] << 8) | data[1];
    if (crc8((unsigned char *)&temperature, 2, CRC8_POLYNOMIAL, CRC8_INITIAL) != data[2]) {
        fprintf(stderr, "Failed to validate temperature CRC\n");
        return;
    }

    int humidity = (data[3] << 8) | data[4];
    if (crc8((unsigned char *)&humidity, 2, CRC8_POLYNOMIAL, CRC8_INITIAL) != data[5]) {
        fprintf(stderr, "Failed to validate humidity CRC\n");
        return;
    }

    float temperature_c = -45.0 + 175.0 * temperature / 65535.0;
    float humidity_pct = 100.0 * humidity / 65535.0;

    write_csv(temperature_c, humidity_pct);
}

static void sig_handler(int signo) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(signo);
}

int main(void) {
    int pi = gpioInitialise();
    if (pi < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", pigpio_error_text(pi));
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen("/dev/i2c-1", SHT35_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(-i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = sig_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    while (1) {
        sample();
        sleep(SAMPLE_INTERVAL);
    }

    return EXIT_SUCCESS;
}

