        log_error("Failed to write humidity command to sensor");
        return;
    }
    if (read(i2c_fd, read_buf, sizeof(read_buf)) != sizeof(read_buf)) {
        log_error("Failed to read humidity from sensor");
        return;
    }
    if (crc8(read_buf, sizeof(read_buf) - 1) != read_buf[2]) {
        log_error("Humidity CRC error");
        return;
