#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define I2C_CMD 0x362F
#define I2C_CMD_LEN 2
#define I2C_READ_LEN 9
#define I2C_SCALE_FACTOR_LEN 3
#define I2C_CRC_LEN 1
#define I2C_CONV_TIME 500000

FILE *file;
int i2c_handle;

void cleanup(int signum) {
    if (i2c_handle > 0) {
        piI2C_close(i2c_handle);
    }
    if (file != NULL) {
        fclose(file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    int ret;
    unsigned char cmd[I2C_CMD_LEN] = {I2C_CMD >> 8, I2C_CMD & 0xFF};
    unsigned char read_buf[I2C_READ_LEN];
    float pressure, temperature;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    ret = gpioInitialise();
    if (ret < 0) {
        printf("gpioInitialise failed: %d\n", ret);
        return -1;
    }

    i2c_handle = piI2C_open(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        printf("piI2C_open failed: %d\n", i2c_handle);
        return -1;
    }

    file = fopen("airflow.dat", "wb");
    if (file == NULL) {
        printf("fopen failed\n");
        return -1;
    }

    while (1) {
        ret = piI2C_write(i2c_handle, cmd, I2C_CMD_LEN);
        if (ret < 0) {
            printf("piI2C_write failed: %d\n", ret);
            return -1;
        }

        usleep(I2C_CONV_TIME);

        ret = piI2C_read(i2c_handle, read_buf, I2C_READ_LEN);
        if (ret < 0) {
            printf("piI2C_read failed: %d\n", ret);
            return -1;
        }

        // Validate CRC-8 for pressure and temperature
        // Implementation depends on the library used and the CRC algorithm

        // Convert pressure and temperature
        pressure = ((read_buf[0] << 8) | read_buf[1]) / (float)((read_buf[6] << 16) | (read_buf[7] << 8) | read_buf[8]) - 1000;
        temperature = ((read_buf[3] << 8) | read_buf[4]) / 200.0 - 45.0;

        // Write pressure and temperature to file
        fwrite(&pressure, sizeof(float), 1, file);
        fwrite(&temperature, sizeof(float), 1, file);
    }

    return 0;
}
