#define I2C_BUS 1
#define I2C_ADDR 0x25
#define I2C_HANDLE -1
#define I2C_WRITE_CMD 0x3603
#define I2C_READ_LEN 9
#define I2C_TIMEOUT 1000
#define LOG_FILE "pressure_log.txt"
#define LOG_INTERVAL 5
#define CRC8_POLYNOMIAL 0x31

static int i2c_handle = I2C_HANDLE;
static FILE *log_file = NULL;

static void exit_handler(int signum) {
    if (i2c_handle != I2C_HANDLE) {
        piI2C_close(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

static unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0;
    int i, j;
    for (i = 0; i < len; i++) {
        crc ^= data[i];
        for (j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc <<= 1;
                crc ^= CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    unsigned char cmd[2] = {I2C_WRITE_CMD >> 8, I2C_WRITE_CMD & 0xFF};
    unsigned char data[I2C_READ_LEN];
    int ret;

    signal(SIGINT, exit_handler);
    signal(SIGTERM, exit_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = piI2C_open(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle: %d\n", i2c_handle);
        exit_handler(0);
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        exit_handler(0);
    }

    while (1) {
        ret = piI2C_write(i2c_handle, cmd, sizeof(cmd));
        if (ret < 0) {
            fprintf(stderr, "I2C write error: %d\n", ret);
            exit_handler(0);
        }

        usleep(45000);

        ret = piI2C_read(i2c_handle, data, I2C_READ_LEN, I2C_TIMEOUT);
        if (ret < 0) {
            fprintf(stderr, "I2C read error: %d\n", ret);
            exit_handler(0);
        }

        if (crc8(data, 3) != 0 || crc8(data + 3, 3) != 0) {
            fprintf(stderr, "CRC failure.\n");
            continue;
        }

        float pressure = (data[0] << 16 | data[1] << 8 | data[2]) * 60.0;
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);
        fprintf(log_file, "%s, %.2f Pa\n", timestamp, pressure);
        fflush(log_file);

        sleep(LOG_INTERVAL);
    }

    exit_handler(0);
    return EXIT_SUCCESS;
}

