#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <i2c.h>

#define SENSOR_ADDRESS 0x28
#define I2C_BUS 1
#define PWM_FREQ 25000
#define PWM_GPIO 18
#define LOG_FILE "flow_log.txt"

FILE *log_file;
int i2c_handle;
volatile sig_atomic_t stop;

void shutdown_handler(int signum) {
    stop = 1;
}

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

void log_reading(unsigned long timestamp, unsigned short pressure) {
    fprintf(log_file, "%lu,%hu\n", timestamp, pressure);
    fflush(log_file);
}

int main() {
    if (piGpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDRESS, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (pigpio_PWM(PWM_GPIO, 0, 0) < 0) {
        log_error("Failed to set initial PWM value");
        return EXIT_FAILURE;
    }

    if (pigpio_i2c_PWM(PWM_GPIO, PWM_FREQ) < 0) {
        log_error("Failed to set PWM frequency");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        log_error("Failed to open log file");
        return EXIT_FAILURE;
    }

    signal(SIGINT, shutdown_handler);
    signal(SIGTERM, shutdown_handler);

    while (!stop) {
        unsigned char buffer[2];
        if (i2cRead(i2c_handle, buffer, 2) < 0) {
            log_error("Failed to read from I2C device");
            continue;
        }

        unsigned short raw_reading = (buffer[0] << 8) | buffer[1];
        raw_reading &= 0x3FFF;  // Mask off status bits and shift right by 2
        float flow_rate = (float)raw_reading / 1638.0f * 10.0f;

        int pwm_duty_cycle = (int)(flow_rate / 10.0f * 1024.0f);
        if (pwm_duty_cycle < 0) pwm_duty_cycle = 0;
        if (pwm_duty_cycle > 1024) pwm_duty_cycle = 1024;

        if (pigpio_PWM(PWM_GPIO, 0, pwm_duty_cycle) < 0) {
            log_error("Failed to set PWM value");
            continue;
        }

        log_reading(time(NULL), raw_reading);
        sleep(0.1);
    }

    pigpio_PWM(PWM_GPIO, 0, 0);  // Turn off fan
    i2cClose(i2c_handle);
    fclose(log_file);
    piGpioTerminate();

    return EXIT_SUCCESS;
}

