#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5D

#define REG_WHO_AM_I 0x0F
#define EXPECTED_WHO_AM_I 0xB1

#define REG_CTRL_REG1 0x10
#define CTRL_REG1_VALUE 0xB0

#define REG_PRESS_OUT_XL 0x28
#define REG_PRESS_OUT_L 0x29
#define REG_PRESS_OUT_H 0x2A

#define REG_TEMP_OUT_L 0x2B
#define REG_TEMP_OUT_H 0x2C

#define PRESSURE_CONVERSION 4096.0
#define TEMPERATURE_CONVERSION 480.0
#define TEMPERATURE_OFFSET 42.5

FILE *log_file;
volatile sig_atomic_t stop_signal = 0;

void handle_sigint(int signum) {
    stop_signal = 1;
}

void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *local = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", local);
    fprintf(stderr, "%s: %s\n", timestamp, message);
    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file);
    }
}

int main() {
    int i2c_handle = gpioI2CSetup(I2C_BUS);
    if (i2c_handle < 0) {
        log_error("Failed to setup I2C");
        return EXIT_FAILURE;
    }

    struct sigaction action;
    action.sa_handler = handle_sigint;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);

    log_file = fopen("environmental_data.txt", "w");
    if (log_file == NULL) {
        log_error("Failed to open log file");
    }

    int8_t who_am_i;
    if (gpioI2CReadByteData(i2c_handle, I2C_ADDR, REG_WHO_AM_I, &who_am_i) != 0) {
        log_error("Failed to read WHO_AM_I register");
        return EXIT_FAILURE;
    }
    if (who_am_i != EXPECTED_WHO_AM_I) {
        fprintf(stderr, "Unexpected WHO_AM_I value: 0x%02X\n", who_am_i);
        return EXIT_FAILURE;
    }

    if (gpioI2CWriteByteData(i2c_handle, I2C_ADDR, REG_CTRL_REG1, CTRL_REG1_VALUE) != 0) {
        log_error("Failed to write to CTRL_REG1");
        return EXIT_FAILURE;
    }

    while (!stop_signal) {
        int32_t pressure;
        if (gpioI2CReadWordSwapEndian(i2c_handle, I2C_ADDR, REG_PRESS_OUT_XL, &pressure) != 0) {
            log_error("Failed to read pressure");
            continue;
        }
        pressure /= PRESSURE_CONVERSION;

        int16_t temperature;
        if (gpioI2CReadWordSwapEndian(i2c_handle, I2C_ADDR, REG_TEMP_OUT_L, &temperature) != 0) {
            log_error("Failed to read temperature");
            continue;
        }
        temperature = (temperature / TEMPERATURE_CONVERSION) + TEMPERATURE_OFFSET;

        time_t now = time(NULL);
        struct tm *local = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", local);

        fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, (double)pressure, (double)temperature);
        fflush(log_file);

        gpioDelay(1000);
    }

    fclose(log_file);
    gpioI2CDelete(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

