#define SCD30_CMD_DATA_READY 0x0202
#define SCD30_CMD_READ_MEASUREMENT 0x0300
#define SCD30_CMD_ARG_PRESSURE_COMP 0x0000
#define SCD30_CMD_ARG_INTERVAL 0x0002
#define SCD30_CMD_ARG_START_CONT 0x0001
#define SCD30_CMD_ARG_STOP_CONT 0x0000
#define SCD30_DATA_LEN 18
#define SCD30_CRC_POLY 0x31
#define SCD30_CRC_INIT 0xFF

FILE *log_file;
int i2c_handle;

void handle_sig(int sig) {
    i2cWriteDevice(i2c_handle, SCD30_CMD_START_CONTINUOUS, SCD30_CMD_ARG_STOP_CONT);
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main() {
    struct sigaction action;
    action.sa_handler = handle_sig;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    i2c_handle = i2cOpen(SCD30_I2C_BUS, SCD30_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen("air_quality.log", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    i2cWriteDevice(i2c_handle, SCD30_CMD_INTERVAL, SCD30_CMD_ARG_INTERVAL);
    i2cWriteDevice(i2c_handle, SCD30_CMD_START_CONTINUOUS, SCD30_CMD_ARG_START_CONT);
    i2cWriteDevice(i2c_handle, 0x2100, SCD30_CMD_ARG_PRESSURE_COMP);

    while (1) {
        unsigned char data[SCD30_DATA_LEN];
        if (i2cWriteDevice(i2c_handle, SCD30_CMD_DATA_READY, 0) < 0) {
            fprintf(stderr, "Failed to write command\n");
            continue;
        }
        if (i2cReadDevice(i2c_handle, data, 1) < 0) {
            fprintf(stderr, "Failed to read data-ready flag\n");
            continue;
        }
        if (data[0] != 1) {
            continue;
        }
        if (i2cWriteDevice(i2c_handle, SCD30_CMD_READ_MEASUREMENT, 0) < 0) {
            fprintf(stderr, "Failed to write command\n");
            continue;
        }
        if (i2cReadDevice(i2c_handle, data, SCD30_DATA_LEN) < 0) {
            fprintf(stderr, "Failed to read measurement\n");
            continue;
        }
        for (int i = 0; i < SCD30_DATA_LEN; i += 6) {
            if (data[i+5] != (data[i] ^ data[i+1] ^ data[i+2] ^ data[i+3])) {
                fprintf(stderr, "CRC mismatch\n");
                continue;
            }
            time_t now = time(NULL);
            struct tm *utc = gmtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc);
            float co2 = (data[i] << 8) | data[i+1];
            float temp = ((data[i+2] << 8) | data[i+3]) / 100.0;
            float humidity = ((data[i+4] << 8) | data[i+5]) / 100.0;
            fprintf(log_file, "%s,%.0f,%.2f,%.2f\n", timestamp, co2, temp, humidity);
            fflush(log_file);
            char *ventilation = co2 < 800 ? "OFF" : (co2 < 1200 ? "LOW" : "HIGH");
            printf("Ventilation set to %s\n", ventilation);
        }
    }

    return 0;
}

