    signal(SIGTERM, handle_signal);

    unsigned char cmd[2] = {SDP32_CONT_MEAS_CMD >> 8, SDP32_CONT_MEAS_CMD & 0xFF};
    if (piI2C_write(i2c_fd, cmd, 2) != 2) {
        fprintf(stderr, "piI2C_write() failed.\n");
        handle_signal(0);
    }

    unsigned char data[SDP32_READ_LEN];
    while (1) {
        if (piI2C_read(i2c_fd, data, SDP32_READ_LEN) != SDP32_READ_LEN) {
