        int scale_factor = (data[6] << 8) | data[7];
        float pressure_pa = (float)raw_pressure / scale_factor;

        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        printf("%ld.%09ld: %f Pa\n", ts.tv_sec, ts.tv_nsec, pressure_pa);

        delay(sampling_interval_ms);
    }

    return 0;
}

