#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <string.h>

#define SDP810_ADDR 0x25
#define I2C_BUS 1

static int i2c_handle = -1;

static void cleanup_and_exit(int sig) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(sig);
}

static void handle_crc_error() {
    printf("CRC error\n");
    cleanup_and_exit(-1);
}

static void handle_error(const char *msg) {
    printf("%s\n", msg);
    cleanup_and_exit(-1);
}

static void validate_crc(const char *data, int len) {
    int crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    if (crc != 0) {
        handle_crc_error();
    }
}

int main() {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    int pi = gpioInitialise();
    if (pi < 0) {
        handle_error("gpioInitialise failed");
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        handle_error("i2cOpen failed");
    }

    char cmd[] = {0x36, 0x15};
    if (i2cWrite(i2c_handle, cmd, sizeof(cmd)) < 0) {
        handle_error("i2cWrite command failed");
    }

    while (1) {
        usleep(45000);  // wait for conversion

        char data[9];
        if (i2cRead(i2c_handle, data, sizeof(data)) < 0) {
            handle_error("i2cRead data failed");
        }

        validate_crc(data, 9);

        float pressure = (data[0] << 8 | data[1]) / (float)(data[2] << 8 | 1);
        float temperature = (data[3] << 8 | data[4]) / 200.0;

        printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);

        sleep(1);
    }

    return 0;
}

