#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x40

static int i2c_file_descriptor = -1;

void signal_handler(int signum) {
    if (i2c_file_descriptor != -1) {
        close(i2c_file_descriptor);
    }
    exit(signum);
}

int main() {
    struct sigaction action;
    action.sa_handler = signal_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;

    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    i2c_file_descriptor = open(I2C_DEVICE, O_RDWR);
    if (i2c_file_descriptor < 0) {
        fprintf(stderr, "Failed to open I2C device file: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(i2c_file_descriptor, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_file_descriptor);
        return 1;
    }

    unsigned char config_register[] = {0x02, 0x00};
    if (write(i2c_file_descriptor, config_register, sizeof(config_register)) != sizeof(config_register)) {
        fprintf(stderr, "Failed to write to config register: %s\n", strerror(errno));
        close(i2c_file_descriptor);
        return 1;
    }

    unsigned char temperature_register[] = {0x00};
    unsigned char data[4];

    while (1) {
        if (write(i2c_file_descriptor, temperature_register, sizeof(temperature_register)) != sizeof(temperature_register)) {
            fprintf(stderr, "Failed to write to temperature register: %s\n", strerror(errno));
            continue;
        }

        usleep(20000);

        if (read(i2c_file_descriptor, data, sizeof(data)) != sizeof(data)) {
            fprintf(stderr, "Failed to read from sensor: %s\n", strerror(errno));
            continue;
        }

        int temperature = (data[0] << 8) | data[1];
        int humidity = (data[2] << 8) | data[3];

        printf("Temperature: %.2f C, Humidity: %.2f %%\n", (temperature / 65536.0) * 165.0 - 40.0, (humidity / 65536.0) * 100.0);

        sleep(5);
    }

    return 0;
}

