#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define MLX90833_I2C_BUS 1
#define MLX90833_I2C_ADDR 0x60

static int pi_handle = 0;
static int i2c_handle = 0;

void exit_handler(int signum) {
    if (i2c_handle > 0) {
        i2cUnwrite(i2c_handle);
    }
    if (pi_handle > 0) {
        piStop();
    }
    printf("Exiting...\n");
    exit(0);
}

int main() {
    struct timespec ts;
    int status;
    float pressure;

    signal(SIGINT, exit_handler);
    signal(SIGTERM, exit_handler);

    pi_handle = piGpioInitialise();
    if (pi_handle <= 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(-pi_handle));
        return 1;
    }

    i2c_handle = i2cOpen(MLX90833_I2C_BUS, MLX90833_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(-i2c_handle));
        exit_handler(0);
        return 1;
    }

    while (1) {
        status = i2cReadWord(i2c_handle, 0, &pressure);
        if (status < 0) {
            fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(-status));
            exit_handler(0);
            return 1;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        printf("[%ld.%09ld] Pressure: %.2f kPa\n", ts.tv_sec, ts.tv_nsec, pressure);

        // Sleep for 500 ms
        usleep(500000);
    }

    // Should never reach here
    exit_handler(0);
    return 0;
}

