#include <fcntl.h>
#include <sys/ioctl.h>

#define MLX90819_ADDR 0x60
#define MLX90819_PRESSURE_MSB 0xAA
#define MLX90819_PRESSURE_LSB 0xAB

static int i2c_fd = -1;

void sig_handler(int signo) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    struct sigaction action;
    action.sa_handler = sig_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;

    if (sigaction(SIGINT, &action, NULL) == -1 || sigaction(SIGTERM, &action, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("open");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX90819_ADDR) == -1) {
        perror("ioctl");
        return 1;
    }

    uint8_t reg = MLX90819_PRESSURE_MSB;
    uint8_t buf[2];

    while (1) {
        if (write(i2c_fd, &reg, sizeof(reg)) != sizeof(reg)) {
            fprintf(stderr, "Failed to trigger measurement\n");
            continue;
        }

        if (read(i2c_fd, buf, sizeof(buf)) != sizeof(buf)) {
            fprintf(stderr, "Failed to read data\n");
            continue;
        }

        uint16_t raw_pressure = (buf[0] << 8) | buf[1];
        float pressure_kpa = raw_pressure * 0.1f;

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        printf("[%s] Pressure: %.2f kPa\n", timestamp, pressure_kpa);

        sleep(1);
    }

    close(i2c_fd);
    return 0;
}

