#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <errno.h>

#define SENSOR_ADDRESS 0x25
#define I2C_BUS 1
#define PRESSURE_CMD 0x362F
#define LOG_FILE "pressure_log.txt"

static int i2c_file = -1;
static FILE *log_file = NULL;

static void cleanup_and_exit(int signum) {
    if (i2c_file != -1) {
        close(i2c_file);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(signum);
}

static void handle_error(const char *msg) {
    perror(msg);
    cleanup_and_exit(EXIT_FAILURE);
}

static void write_word(int value) {
    if (write(i2c_file, &value, 2) != 2) {
        handle_error("write");
    }
}

static void read_bytes(uint8_t *buffer, size_t count) {
    if (read(i2c_file, buffer, count) != count) {
        handle_error("read");
    }
}

static int crc8(const uint8_t *data, size_t count) {
    int crc = 0xFF;
    for (size_t i = 0; i < count; ++i) {
        crc ^= data[i];
        for (int j = 0; j < 8; ++j) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static void log_data(time_t timestamp, float pressure, float temperature) {
    if (fprintf(log_file, "%ld,%.2f,%.2f\n", timestamp, pressure, temperature) < 0) {
        handle_error("fprintf");
    }
    fflush(log_file);
}

int main() {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file == -1) {
        handle_error("open");
    }

    if (ioctl(i2c_file, I2C_SLAVE, SENSOR_ADDRESS) == -1) {
        handle_error("ioctl");
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        handle_error("fopen");
    }

    while (1) {
        write_word(PRESSURE_CMD);
        usleep(45000);

        uint8_t buffer[9];
        read_bytes(buffer, sizeof(buffer));

        uint16_t pressure = (buffer[0] << 8) | buffer[1];
        uint16_t pressure_crc = buffer[2];
        uint16_t temperature = (buffer[3] << 8) | buffer[4];
        uint16_t temperature_crc = buffer[5];

        if (crc8((uint8_t*)&pressure, 2) != pressure_crc ||
            crc8((uint8_t*)&temperature, 2) != temperature_crc) {
            fprintf(stderr, "CRC error\n");
            continue;
        }

        float pressure_pa = pressure / 60.0f;
        float temperature_c = temperature / 200.0f;

        time_t timestamp = time(NULL);
        log_data(timestamp, pressure_pa, temperature_c);
    }

    return 0;
}

