    if (ioctl(i2c_file, I2C_SLAVE, SENSOR_ADDRESS) == -1) {
        handle_error("ioctl");
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        handle_error("fopen");
    }

    while (1) {
        write_word(PRESSURE_CMD);
        usleep(45000);

        uint8_t buffer[9];
        read_bytes(buffer, sizeof(buffer));

        uint16_t pressure = (buffer[0] << 8) | buffer[1];
        uint16_t pressure_crc = buffer[2];
        uint16_t temperature = (buffer[3] << 8) | buffer[4];
        uint16_t temperature_crc = buffer[5];

        if (crc8((uint8_t*)&pressure, 2) != pressure_crc ||
            crc8((uint8_t*)&temperature, 2) != temperature_crc) {
            fprintf(stderr, "CRC error\n");
            continue;
        }

        float pressure_pa = pressure / 60.0f;
        float temperature_c = temperature / 200.0f;

        time_t timestamp = time(NULL);
        log_data(timestamp, pressure_pa, temperature_c);
    }

    return 0;
}
