#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define MLX90821_I2C_BUS 1
#define MLX90821_I2C_ADDR 0x40
#define MLX90821_PRESSURE_REG 0x00
#define MLX90821_PRESSURE_SCALE 0.01
#define MLX90821_MIN_SAFE_PRESSURE 200
#define MLX90821_MAX_SAFE_PRESSURE 250

static int i2c_handle = -1;
static FILE *log_file = NULL;

void sig_handler(int signo) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(signo);
}

int main() {
    struct stat st = {0};
    char timestamp[20];
    unsigned short pressure_raw;
    float pressure_kPa;
    int retries = 0;

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return EXIT_FAILURE;
    }

    while (1) {
        if (i2c_handle < 0) {
            i2c_handle = i2cOpen("/dev/i2c-%d", MLX90821_I2C_BUS);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to open I2C bus %d.\n", MLX90821_I2C_BUS);
                return EXIT_FAILURE;
            }
        }

        if (i2cWriteByte(i2c_handle, MLX90821_I2C_ADDR, MLX90821_PRESSURE_REG) < 0) {
            fprintf(stderr, "I2C write failed, retrying...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            continue;
        }

        if (i2cReadI2CBlockData(i2c_handle, MLX90821_I2C_ADDR, 2, (uint8_t *)&pressure_raw) < 0) {
            fprintf(stderr, "I2C read failed, retrying...\n");
            if (retries++ > 0) {
                i2cClose(i2c_handle);
                i2c_handle = -1;
            }
            continue;
        }

        retries = 0;

        pressure_kPa = pressure_raw * MLX90821_PRESSURE_SCALE;

        if (pressure_kPa < MLX90821_MIN_SAFE_PRESSURE || pressure_kPa > MLX90821_MAX_SAFE_PRESSURE) {
            fprintf(stderr, "Warning: pressure out of safe range!\n");
        }

        if (stat("pressure_log.csv", &st) == -1) {
            fprintf(stderr, "Failed to get file status.\n");
            return EXIT_FAILURE;
        }

        if (st.st_size == 0) {
            log_file = fopen("pressure_log.csv", "a");
            if (log_file == NULL) {
                fprintf(stderr, "Failed to open log file.\n");
                return EXIT_FAILURE;
            }
            fprintf(log_file, "timestamp,pressure_kPa\n");
        }

        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", gmtime(&now));

        if (log_file == NULL) {
            log_file = fopen("pressure_log.csv", "a");
            if (log_file == NULL) {
                fprintf(stderr, "Failed to open log file.\n");
                return EXIT_FAILURE;
            }
        }

        fprintf(log_file, "%s,%.2f\n", timestamp, pressure_kPa);
        fflush(log_file);

        sleep(1);
    }

    return EXIT_SUCCESS;
}

