    if (ftell(log_file) > 1024 * 1024) {
        fclose(log_file);
        remove(LOG_FILE);
        log_file = fopen(LOG_FILE, "w");
    }
}

void handle_sigint(int signum) {
    fclose(log_file);
    exit(0);
}

int main() {
    int i2c_handle;
    unsigned char data[4];
    int status;

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio\n");
        return 1;
    }

    i2c_handle = gpioI2CSetSlave(I2C_BUS, SENSOR_ADDR);
    if (i2c_handle < 0) {
        printf("Failed to set I2C slave\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        // Trigger measurement
        status = gpioI2CWriteByte(i2c_handle, 0x00);
        if (status < 0) {
            printf("Failed to write to sensor\n");
            continue;
        }

        usleep(40000);  // Wait 40 ms

        // Read measurement
        status = gpioI2CRead(i2c_handle, data, 4);
        if (status < 0) {
            printf("Failed to read from sensor\n");
            continue;
        }

        // Validate sensor status
        if ((data[0] & 0x80) != 0 || (data[2] & 0x80) != 0) {
            printf("Sensor error\n");
            continue;
        }

        // Convert raw values
        int raw_temperature = (data[0] << 8) | data[1];
        int raw_humidity = (data[2] << 8) | data[3];
        int temperature = raw_temperature * 165.0 / 16383.0 - 40.0;
        int humidity = raw_humidity * 100.0 / 16383.0;

        log_data(temperature, humidity);

        sleep(5);  // Sample every 5 seconds
    }

    fclose(log_file);
    gpioI2CClose(i2c_handle);
    gpioTerminate();

    return 0;
}

