#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO 4
#define SENT_SYNC 56
#define SENT_TICK 3
#define SENT_MIN_PULSE 12
#define SENT_MAX_PULSE 271
#define SENT_SCALE 0.006896551724137931
#define SENT_OFFSET 300

volatile sig_atomic_t stop = 0;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        stop = 1;
    }
}

int main() {
    int pi = pigpio_start(NULL, NULL);
    if (pi < 0) {
        fprintf(stderr, "pigpio_start failed\n");
        return EXIT_FAILURE;
    }

    if (gpioCfgIntr(GPIO, PI_ fallingEdge) < 0) {
        fprintf(stderr, "gpioCfgIntr failed\n");
        return EXIT_FAILURE;
    }

    FILE *log = fopen("pressure_log.txt", "w");
    if (log == NULL) {
        fprintf(stderr, "fopen failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (!stop) {
        int pulse = gpioRead(GPIO);
        if (pulse < 0) {
            fprintf(stderr, "gpioRead failed\n");
            break;
        }

        if (pulse < SENT_SYNC || pulse > SENT_SYNC * 2) {
            fprintf(stderr, "Invalid sync pulse width: %d\n", pulse);
            continue;
        }

        int nibbles[4];
        for (int i = 0; i < 4; i++) {
            int pulse = gpioRead(GPIO);
            if (pulse < 0) {
                fprintf(stderr, "gpioRead failed\n");
                goto cleanup;
            }

            if (pulse < SENT_MIN_PULSE || pulse > SENT_MAX_PULSE) {
                fprintf(stderr, "Invalid nibble pulse width: %d\n", pulse);
                goto cleanup;
            }

            nibbles[i] = pulse / SENT_TICK;
        }

        int checksum = (nibbles[0] + nibbles[1] + nibbles[2] + nibbles[3]) % 16;
        if (checksum != 0) {
            fprintf(stderr, "Invalid checksum: %d\n", checksum);
            continue;
        }

        int raw = (nibbles[1] << 8) | (nibbles[2] << 4) | nibbles[3];
        double pressure = raw * SENT_SCALE + SENT_OFFSET;

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char buffer[80];
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log, "%s, Pressure: %.2f Pa\n", buffer, pressure);
    }

cleanup:
    fclose(log);
    pigpio_stop(pi);
    return EXIT_SUCCESS;
}

