            fprintf(stderr, "Invalid checksum: %d\n", checksum);
            continue;
        }

        int raw = (nibbles[1] << 8) | (nibbles[2] << 4) | nibbles[3];
        double pressure = raw * SENT_SCALE + SENT_OFFSET;

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char buffer[80];
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log, "%s, Pressure: %.2f Pa\n", buffer, pressure);
    }

cleanup:
    fclose(log);
    pigpio_stop(pi);
    return EXIT_SUCCESS;
}
```

This code initializes the pigpio library, sets up a GPIO interrupt for falling edges, and opens a log file for writing. It then enters a main loop where it reads the GPIO pin, checks the pulse width for a valid sync pulse, and reads and checks the pulse widths for the status and data nibbles. If all checks pass, it calculates the checksum, converts the raw value to pressure, and writes a log entry. On a signal to stop (SIGINT or SIGTERM), it closes the log file and stops the pigpio library.

