#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SHT40_ADDR 0x44
#define SHT40_MEASURE_HIGH_PRECISION 0xFD
#define SHT40_CRC_POLYNOMIAL 0x31
#define SHT40_CRC_INITIAL_VALUE 0xFF

static int pi_handle;
static int i2c_handle;
static FILE *log_file;

static void handle_sigint(int signum) {
    if (i2c_handle >= 0) {
        piI2C_close(i2c_handle);
    }
    if (pi_handle >= 0) {
        gpioTerminate();
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

static int crc8(const char *data, int len, int polynomial, int initial_value) {
    int crc = initial_value;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc & 0xFF;
}

int main() {
    pi_handle = gpioInitialise();
    if (pi_handle < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %d\n", pi_handle);
        return 1;
    }

    i2c_handle = piI2C_open(1, SHT40_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        piI2C_close(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    char data[6];
    while (1) {
        int result = piI2C_writeByte(i2c_handle, SHT40_MEASURE_HIGH_PRECISION);
        if (result < 0) {
            fprintf(stderr, "Failed to write to I2C bus: %d\n", result);
            handle_sigint(0);
            return 1;
        }

        usleep(10000);  // 8.5 ms

        result = piI2C_readBytes(i2c_handle, data, sizeof(data));
        if (result < 0) {
            fprintf(stderr, "Failed to read from I2C bus: %d\n", result);
            handle_sigint(0);
            return 1;
        }

        int temp = (data[0] << 8) | data[1];
        int hum = (data[3] << 8) | data[4];

        if (crc8(data, 2, SHT40_CRC_POLYNOMIAL, SHT40_CRC_INITIAL_VALUE) != data[2] ||
            crc8(data + 3, 2, SHT40_CRC_POLYNOMIAL, SHT40_CRC_INITIAL_VALUE) != data[5]) {
            fprintf(stderr, "CRC validation failed\n");
            continue;
        }

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);

        fprintf(log_file, "%s, %.2f °C, %.2f %%RH\n", timestamp,
                -45.0 + 175.0 * (temp / 65535.0),
                -6.0 + 125.0 * (hum / 65535.0));
        fflush(log_file);

        sleep(5);
    }

    return 0;
}

