#define I2C_BUS 1
#define I2C_ADDR 0x48
#define TEMP_REG 0x00
#define LOG_SIZE 1024
#define LOG_FILE "temperature_log.dat"

volatile sig_atomic_t stop = 0;
float log_buffer[LOG_SIZE];
int log_index = 0;

void handle_signal(int signum) {
    stop = 1;
}

void flush_log() {
    FILE *file = fopen(LOG_FILE, "wb");
    if (file == NULL) {
        printf("Failed to open %s for writing\n", LOG_FILE);
        return;
    }
    fwrite(log_buffer, sizeof(float), log_index, file);
    fclose(file);
}

int main() {
    int pi = pigpio_start();
    if (pi < 0) {
        printf("Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int handle = i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        printf("Failed to open I2C handle\n");
        pigpio_stop(pi);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop) {
        int result = i2c_rd_word_reg(handle, TEMP_REG);
        if (result >= 0) {
            float temp = (float)result * 0.0078125;
            log_buffer[log_index++] = temp;
            if (log_index == LOG_SIZE) {
                flush_log();
                log_index = 0;
            }
        } else {
            printf("Failed to read temperature\n");
        }

        sleep(5);
    }

    flush_log();
    i2c_close(handle);
    pigpio_stop(pi);

    return EXIT_SUCCESS;
}

