#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <pigpioI2C.h>

#define SHTC3_ADDR 0x70
#define SHTC3_CMD_NORMAL_MEASUREMENT 0x7866

#define TEMP_MIN -40.0
#define TEMP_MAX 125.0
#define HUMIDITY_MIN 0.0
#define HUMIDITY_MAX 100.0

#define LOG_FILE "shtc3_environment.log"

static int i2c_handle = -1;
static FILE *log_file = NULL;

static void cleanup_and_exit(int sig) {
    if (i2c_handle != -1) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    exit(sig);
}

static int crc8(const unsigned char *data, int len, int poly, int init) {
    int crc = init;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ poly;
            else
                crc <<= 1;
        }
    }
    return crc & 0xFF;
}

static void read_shtc3(void) {
    unsigned char cmd[2] = {SHTC3_CMD_NORMAL_MEASUREMENT >> 8, SHTC3_CMD_NORMAL_MEASUREMENT & 0xFF};
    unsigned char data[6];
    if (i2cWrite(i2c_handle, cmd, 2) != 2) {
        fprintf(stderr, "I2C write error\n");
        return;
    }
    sleep(1);  // wait at least 12.4 ms
    if (i2cRead(i2c_handle, data, 6) != 6) {
        fprintf(stderr, "I2C read error\n");
        return;
    }
    if (crc8(data, 2, 0x31, 0xFF) != data[2]) {
        fprintf(stderr, "Temperature CRC failure\n");
        return;
    }
    if (crc8(data + 3, 2, 0x31, 0xFF) != data[5]) {
        fprintf(stderr, "Humidity CRC failure\n");
        return;
    }
    float temp = 175.0 * ((data[0] << 8 | data[1]) >> 4) / 65535.0 - 45.0;
    float humidity = 100.0 * ((data[3] << 8 | data[4]) >> 4) / 65535.0;
    if (temp < TEMP_MIN || temp > TEMP_MAX || humidity < HUMIDITY_MIN || humidity > HUMIDITY_MAX) {
        fprintf(stderr, "Value out of range\n");
        return;
    }
    time_t now = time(NULL);
    struct tm *now_tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);
    if (log_file == NULL && (log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Could not open log file\n");
        return;
    }
    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temp, humidity);
    fflush(log_file);
    printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temp, humidity);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Could not initialize pigpio\n");
        return EXIT_FAILURE;
    }
    i2c_handle = i2cOpen("/dev/i2c-1", SHTC3_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Could not open I2C device\n");
        return EXIT_FAILURE;
    }
    signal(SIGINT, cleanup_and_exit);
    while (1) {
        read_shtc3();
        sleep(5);
    }
    return EXIT_SUCCESS;
}

