#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define MAX_RETRIES 3

static int i2c_handle = -1;
static int retry_count = 0;

void sigint_handler(int signum) {
    if (i2c_handle >= 0) {
        piI2C_close(i2c_handle);
    }
    piStop();
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);

    FILE *log_file = fopen("temperature_log.txt", "w");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        return 1;
    }

    while (1) {
        if (i2c_handle < 0) {
            if (retry_count > MAX_RETRIES) {
                printf("Too many consecutive failures, exiting\n");
                fclose(log_file);
                return 1;
            }

            i2c_handle = piI2C_open(I2C_BUS, I2C_ADDR);
            if (i2c_handle < 0) {
                printf("Failed to open I2C device, retrying\n");
                retry_count++;
                sleep(1);
                continue;
            }

            retry_count = 0;
        }

        int16_t temp_raw;
        int result = piI2C_read_device_word(i2c_handle, 0x00, &temp_raw);
        if (result < 0) {
            printf("Failed to read temperature, error %d\n", result);
            piI2C_close(i2c_handle);
            i2c_handle = -1;
            sleep(1);
            continue;
        }

        double temp_c = temp_raw * 0.0078125;

        time_t now = time(NULL);
        struct tm *local_time = localtime(&now);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", local_time);

        fprintf(log_file, "%s, Temperature: %.2f C\n", time_str, temp_c);
        fflush(log_file);

        sleep(1);
    }

    fclose(log_file);
    return 0;
}

