#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x49

static int i2c_handle = -1;
static FILE *log_file = NULL;

void cleanup_and_exit(int sig) {
    if (i2c_handle != -1) {
        piI2C_close(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (sig == SIGINT) {
        printf("\nExiting on SIGINT.\n");
    } else if (sig == SIGTERM) {
        printf("Exiting on SIGTERM.\n");
    }
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }
    i2c_handle = piI2C_open(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle: %d\n", i2c_handle);
        return EXIT_FAILURE;
    }
    log_file = fopen("flow_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    // Discard first two reads due to possible stale data
    for (int i = 0; i < 2; i++) {
        unsigned char data[4];
        int res = piI2C_readDevice(i2c_handle, data, 4);
        if (res < 0) {
            fprintf(log_file, "%ld: Read error: %d\n", time(NULL), res);
            continue;
        }
    }

    while (1) {
        unsigned char data[4];
        int res = piI2C_readDevice(i2c_handle, data, 4);
        if (res < 0) {
            fprintf(log_file, "%ld: Read error: %d\n", time(NULL), res);
            // Attempt to re-initialize I2C handle
            piI2C_close(i2c_handle);
            i2c_handle = piI2C_open(I2C_BUS, I2C_ADDR);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-open I2C handle: %d\n", i2c_handle);
                return EXIT_FAILURE;
            }
            continue;
        }

        // Convert raw values
        unsigned int raw_flow = (data[0] << 8) | data[1];
        unsigned int raw_temp = (data[2] << 8) | data[3];
        double flow_slpm = ((double)raw_flow / 16384.0 - 0.1) / 0.8 * 25.0;
        double temp_c = ((double)raw_temp / 4096.0 - 0.1) / 0.8 * 80.0 - 40.0;

        // Log timestamped flow rate and temperature
        fprintf(log_file, "%ld: Flow = %.2f SLPM, Temp = %.2f C\n", time(NULL), flow_slpm, temp_c);

        // Sleep for 1 second
        sleep(1);
    }

    return EXIT_SUCCESS;
}

