#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define LOG_FILE "dht11_readings.txt"

FILE *log_file;

void cleanup_and_exit(int signum) {
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);
    delay(18000);
    gpioSetMode(GPIO_PIN, PI_INPUT);

    while (1) {
        int start_time = gpioTick();
        while (gpioRead(GPIO_PIN) == 0) {
            if (gpioTick() - start_time > 100000) {
                fprintf(log_file, "%s: Sensor absent (line stuck low)\n",
                        asctime(localtime(time(NULL))));
                fflush(log_file);
                delay(2000);
                gpioSetMode(GPIO_PIN, PI_OUTPUT);
                gpioWrite(GPIO_PIN, 0);
                delay(18000);
                gpioSetMode(GPIO_PIN, PI_INPUT);
                continue 2;
            }
        }

        start_time = gpioTick();
        while (gpioRead(GPIO_PIN) == 1) {
            if (gpioTick() - start_time > 100000) {
                fprintf(log_file, "%s: Sensor absent (line stuck high)\n",
                        asctime(localtime(time(NULL))));
                fflush(log_file);
                delay(2000);
                gpioSetMode(GPIO_PIN, PI_OUTPUT);
                gpioWrite(GPIO_PIN, 0);
                delay(18000);
                gpioSetMode(GPIO_PIN, PI_INPUT);
                continue 2;
            }
        }

        int byte = 0, bit_count = 0, checksum = 0;
        for (int i = 0; i < 40; i++) {
            start_time = gpioTick();
            while (gpioRead(GPIO_PIN) == 0) {
                if (gpioTick() - start_time > 100000) {
                    fprintf(log_file, "%s: Data bit timeout\n",
                            asctime(localtime(time(NULL))));
                    fflush(log_file);
                    delay(2000);
                    gpioSetMode(GPIO_PIN, PI_OUTPUT);
                    gpioWrite(GPIO_PIN, 0);
                    delay(18000);
                    gpioSetMode(GPIO_PIN, PI_INPUT);
                    continue 3;
                }
            }

            start_time = gpioTick();
            while (gpioRead(GPIO_PIN) == 1) {
                if (gpioTick() - start_time > 100000) {
                    fprintf(log_file, "%s: Data bit timeout\n",
                            asctime(localtime(time(NULL))));
                    fflush(log_file);
                    delay(2000);
                    gpioSetMode(GPIO_PIN, PI_OUTPUT);
                    gpioWrite(GPIO_PIN, 0);
                    delay(18000);
                    gpioSetMode(GPIO_PIN, PI_INPUT);
                    continue 3;
                }
            }

            if (gpioTick() - start_time > 60000)
                byte |= 1 << (7 - (bit_count % 8));

            bit_count++;
            if (bit_count % 8 == 0) {
                checksum += byte;
                if (bit_count / 8 == 5) {
                    if ((checksum & 0xFF) != byte) {
                        fprintf(log_file, "%s: Checksum failure\n",
                                asctime(localtime(time(NULL))));
                        fflush(log_file);
                        delay(2000);
                        gpioSetMode(GPIO_PIN, PI_OUTPUT);
                        gpioWrite(GPIO_PIN, 0);
                        delay(18000);
                        gpioSetMode(GPIO_PIN, PI_INPUT);
                        continue 2;
                    }
                    fprintf(log_file, "%s: Humidity: %d, Temperature: %d\n",
                            asctime(localtime(time(NULL))), byte, byte);
                    fflush(log_file);
                    delay(2000);
                    gpioSetMode(GPIO_PIN, PI_OUTPUT);
                    gpioWrite(GPIO_PIN, 0);
                    delay(18000);
                    gpioSetMode(GPIO_PIN, PI_INPUT);
                    continue 2;
                }
            }
        }
    }

    return 0;
}

