#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SHT31D_ADDR 0x44
#define SHT31D_MEASURE_COMMAND 0x2C06
#define SHT31D_RETRIES 3

static int pi_handle;
static int i2c_handle;
static FILE *log_file;

static void log_error(const char *message) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(stderr, "%s - %s\n", timestamp, message);
    if (log_file != NULL) {
        fprintf(log_file, "%s - %s\n", timestamp, message);
        fflush(log_file);
    }
}

static void handle_signal(int signum) {
    if (i2c_handle >= 0) {
        piI2C_close(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
