#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x64
#define SENSOR2_ADDR 0x65
#define DEVICE_ID_REG 0x00
#define RED_CHANNEL_REG 0x64
#define GREEN_CHANNEL_REG 0x66
#define BLUE_CHANNEL_REG 0x68
#define DEVICE_ID 0x2A

FILE *log_file = NULL;
int i2c_handle1 = -1, i2c_handle2 = -1;

void cleanup_and_exit(int signum) {
    if (log_file) fclose(log_file);
    if (i2c_handle1 >= 0) gpioI2C_close(i2c_handle1);
    if (i2c_handle2 >= 0) gpioI2C_close(i2c_handle2);
    gpioTerminate();
    exit(signum);
}

int main() {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    i2c_handle1 = gpioI2C_open(I2C_BUS, SENSOR1_ADDR, 0);
    i2c_handle2 = gpioI2C_open(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle1 < 0 || i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C handles.\n");
        cleanup_and_exit(-1);
    }

    log_file = fopen("cct_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        cleanup_and_exit(-1);
    }

    fprintf(log_file, "Timestamp,Average_CCT\n");

    while (1) {
        int device_id1 = gpioI2C_readByteData(i2c_handle1, DEVICE_ID_REG);
        int device_id2 = gpioI2C_readByteData(i2c_handle2, DEVICE_ID_REG);
        if (device_id1 < 0 || device_id2 < 0 || device_id1 != DEVICE_ID || device_id2 != DEVICE_ID) {
            fprintf(stderr, "Sensor not present or wrong device ID.\n");
            continue;
        }

        int red1 = gpioI2C_readWordData(i2c_handle1, RED_CHANNEL_REG);
        int green1 = gpioI2C_readWordData(i2c_handle1, GREEN_CHANNEL_REG);
        int blue1 = gpioI2C_readWordData(i2c_handle1, BLUE_CHANNEL_REG);
        int red2 = gpioI2C_readWordData(i2c_handle2, RED_CHANNEL_REG);
        int green2 = gpioI2C_readWordData(i2c_handle2, GREEN_CHANNEL_REG);
        int blue2 = gpioI2C_readWordData(i2c_handle2, BLUE_CHANNEL_REG);
        if (red1 < 0 || green1 < 0 || blue1 < 0 || red2 < 0 || green2 < 0 || blue2 < 0) {
            fprintf(stderr, "Failed to read sensor data.\n");
            continue;
        }

        // McCamy's formula
        double cct1 = 1000.0 / (0.014388 * log(red1 / 50.0) + 0.045709 * log(green1 / 50.0) - 0.001228 * log(blue1 / 50.0) + 0.000214);
        double cct2 = 1000.0 / (0.014388 * log(red2 / 50.0) + 0.045709 * log(green2 / 50.0) - 0.001228 * log(blue2 / 50.0) + 0.000214);

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s,%.2f\n", timestamp, (cct1 + cct2) / 2.0);
        fflush(log_file);

        sleep(1);
    }

    cleanup_and_exit(0);
}

