#define TEMP_REG 0x0A2E
#define OUTPUT_MIN 0
#define OUTPUT_MAX 32768
#define P_MIN 0.0
#define P_MAX 800.0
#define RAW_TO_TEMP(raw) ((raw * 0.01) - 40.0)

FILE *log_file;
int i2c_handle;

void log_error(const char *msg) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
    fprintf(log_file, "%s - %s\n", timestamp, msg);
    fflush(log_file);
}

void cleanup_and_exit(int signum) {
    if (i2c_handle >= 0) {
        if (i2cClose(i2c_handle) < 0) {
            log_error("Failed to close I2C handle");
        }
    }
    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Failed to close log file\n");
        }
    }
    if (gpioTerminate() < 0) {
        fprintf(stderr, "Failed to terminate GPIO\n");
    }
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        cleanup_and_exit(EXIT_FAILURE);
    }
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup_and_exit(EXIT_FAILURE);
    }
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);
    while (1) {
        int16_t raw_pressure = 0, raw_temp = 0;
        if (i2cWriteByte(i2c_handle, PRESSURE_REG >> 8) < 0 ||
            i2cReadWord(i2c_handle, &raw_pressure) < 0) {
            log_error("Failed to read pressure");
        } else {
            float pressure_kPa = (raw_pressure - OUTPUT_MIN) * (P_MAX - P_MIN) / (OUTPUT_MAX - OUTPUT_MIN);
            fprintf(log_file, "Pressure: %.2f kPa\n", pressure_kPa);
        }
        if (i2cWriteByte(i2c_handle, TEMP_REG >> 8) < 0 ||
            i2cReadWord(i2c_handle, &raw_temp) < 0) {
            log_error("Failed to read temperature");
        } else {
            float temp_C = RAW_TO_TEMP(raw_temp);
            fprintf(log_file, "Temperature: %.2f C\n", temp_C);
        }
        fflush(log_file);
        sleep(SLEEP_SECONDS);
    }
    return EXIT_SUCCESS;
}

