#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <i2c.h>

#define LM75B_ADDR 0x48
#define TEMP_REG 0x00
#define FAN_GPIO 18
#define BUF_SIZE 60
#define ON_TEMP 280
#define OFF_TEMP 260

static int i2c_handle;
static int buf_head, buf_tail;
static int buf_count;
static int buf_sum;
static int fan_state;
static short temp_buffer[BUF_SIZE];

static void sig_handler(int signo) {
    if (i2c_close(i2c_handle) < 0) {
        fprintf(stderr, "Failed to close I2C handle\n");
    }
    if (gpioWrite(FAN_GPIO, 0) < 0) {
        fprintf(stderr, "Failed to write GPIO\n");
    }
    if (gpioTerminate() < 0) {
        fprintf(stderr, "Failed to terminate pigpio\n");
    }
    exit(0);
}

int main() {
    struct sigaction action;
    int ret;
    short temp_raw;
    float temp_conv, temp_avg;

    action.sa_handler = sig_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;

    if (sigaction(SIGINT, &action, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &action, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        return 1;
    }

    i2c_handle = i2cOpen("/dev/i2c-1", LM75B_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    while (1) {
        ret = i2cReadWord(i2c_handle, TEMP_REG, &temp_raw);
        if (ret < 0) {
            fprintf(stderr, "Failed to read I2C\n");
            continue;
        }

        temp_conv = (float)((temp_raw >> 1) * 0.5);
        buf_sum -= temp_buffer[buf_tail];
        temp_buffer[buf_head] = temp_raw >> 1;
        buf_sum += temp_buffer[buf_head];
        buf_head = (buf_head + 1) % BUF_SIZE;
        if (buf_head == buf_tail) {
            buf_tail = (buf_tail + 1) % BUF_SIZE;
        } else {
            buf_count++;
        }
        temp_avg = (float)buf_sum / buf_count;

        if (temp_avg > ON_TEMP && fan_state == 0) {
            ret = gpioWrite(FAN_GPIO, 1);
            if (ret < 0) {
                fprintf(stderr, "Failed to write GPIO\n");
                continue;
            }
            fan_state = 1;
        } else if (temp_avg < OFF_TEMP && fan_state == 1) {
            ret = gpioWrite(FAN_GPIO, 0);
            if (ret < 0) {
                fprintf(stderr, "Failed to write GPIO\n");
                continue;
            }
            fan_state = 0;
        }

        sleep(1);
    }

    return 0;
}

