#define SDP810_ADDR 0x25
#define SDP810_MEASURE 0x362F
#define SDP810_PRESSURE_OFFSET 2
#define SDP810_TEMP_OFFSET 6
#define SDP810_STATUS_OFFSET 10
#define SDP810_CRC_POLY 0x31
#define SDP810_CRC_INIT 0xFF
#define SDP810_PRESSURE_SCALE 60
#define SDP810_TEMP_SCALE 200
#define MAX_PRESSURE 5.0

FILE *log_file;
int i2c_handle;

void handle_signal(int signum) {
    if (i2c_handle >= 0) {
        piI2C_close(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int sdp810_crc8(const unsigned char *data, int len) {
    unsigned char crc = SDP810_CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc <<= 1;
                crc ^= SDP810_CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    log_file = fopen("airflow.log", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    i2c_handle = piI2C_open(1, SDP810_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        return 1;
    }

    unsigned char cmd[2] = {SDP810_MEASURE >> 8, SDP810_MEASURE & 0xFF};
    unsigned char data[11];

    while (1) {
        if (piI2C_write(i2c_handle, cmd, 2) < 0) {
            fprintf(stderr, "Failed to write to I2C\n");
            return 1;
        }

        usleep(45000);

        if (piI2C_read(i2c_handle, data, 11) < 0) {
            fprintf(stderr, "Failed to read from I2C\n");
            return 1;
        }

        if (sdp810_crc8(data, 10) != data[10]) {
            fprintf(stderr, "CRC mismatch\n");
            continue;
        }

        int16_t pressure = (data[SDP810_PRESSURE_OFFSET] << 8) | data[SDP810_PRESSURE_OFFSET + 1];
        int16_t temp = (data[SDP810_TEMP_OFFSET] << 8) | data[SDP810_TEMP_OFFSET + 1];

        double pressure_pa = pressure / (double)SDP810_PRESSURE_SCALE;
        double temp_c = temp / (double)SDP810_TEMP_SCALE;

        if (pressure_pa > MAX_PRESSURE) {
            fprintf(stderr, "Warning: Pressure exceeds %.1f Pa\n", MAX_PRESSURE);
        }

        time_t t = time(NULL);
        struct tm *tmp = localtime(&t);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tmp);

        fprintf(log_file, "%s,%.2f,%.2f\n", time_str, pressure_pa, temp_c);
        fflush(log_file);

        sleep(1);
    }

    return 0;
}

