#include <fcntl.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_SLAVE_ADDR 0x4A
#define GPIO_CONSUMER "temperature-sensor"
#define GPIO_LINE_OFFSET 17
#define TEMP_REG 0x00
#define TEMP_SCALE 0.0625
#define TEMP_HYSTERESIS 1
#define TEMP_LIMIT_HIGH 28
#define TEMP_LIMIT_LOW (TEMP_LIMIT_HIGH - TEMP_HYSTERESIS)

static int i2c_fd;
static struct gpiod_line *gpio_line;
static struct gpiod_chip *gpio_chip;

static void cleanup_and_exit(int signum)
{
    close(i2c_fd);
    gpiod_line_set_value(gpio_line, 0);
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    exit(0);
}

int main(void)
{
    int ret;
    uint16_t temp_msb, temp_lsb;
    double temp_c;

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_SLAVE_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        return 1;
    }

    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_LINE_OFFSET);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        return 1;
    }

    ret = gpiod_line_request_output(gpio_line, GPIO_CONSUMER, 0);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        return 1;
    }

    while (1) {
        ret = read(i2c_fd, &temp_msb, 1);
        if (ret < 0) {
            perror("Failed to read temperature MSB");
            return 1;
        }

        ret = lseek(i2c_fd, TEMP_REG + 1, SEEK_SET);
        if (ret < 0) {
            perror("Failed to seek to temperature LSB");
            return 1;
        }

        ret = read(i2c_fd, &temp_lsb, 1);
        if (ret < 0) {
            perror("Failed to read temperature LSB");
            return 1;
        }

        temp_c = ((temp_msb << 8) | temp_lsb) >> 4;
        temp_c *= TEMP_SCALE;

        printf("Temperature: %.2f °C\n", temp_c);

        if (temp_c > TEMP_LIMIT_HIGH) {
            gpiod_line_set_value(gpio_line, 1);
        } else if (temp_c < TEMP_LIMIT_LOW) {
            gpiod_line_set_value(gpio_line, 0);
        }

        sleep(1);
    }

    return 0;
}

