#define I2C_BUS 1
#define I2C_ADDR 0x25
#define I2C_CMD 0x362F
#define I2C_READ_LEN 9

volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

int main() {
    int i2c_fd;
    unsigned char cmd[2] = {I2C_CMD >> 8, I2C_CMD & 0xFF};
    unsigned char read_buf[I2C_READ_LEN];
    int scale_factor;
    double pressure, temperature;
    FILE *file;
    struct sigaction action;

    action.sa_handler = handle_sigint;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return EXIT_FAILURE;
    }

    i2c_fd = gpioI2CSetup(I2C_BUS, I2C_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to setup I2C communication.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    file = fopen("flow_data.txt", "w");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for writing.\n");
        gpioI2CClose(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (!stop) {
        if (gpioI2CWrite(i2c_fd, cmd, sizeof(cmd)) < 0) {
            fprintf(stderr, "Failed to send command to sensor.\n");
            continue;
        }

        usleep(45000);  // wait at least 45 ms

        if (gpioI2CRead(i2c_fd, read_buf, I2C_READ_LEN) < 0) {
            fprintf(stderr, "Failed to read data from sensor.\n");
            continue;
        }

        // validate CRC-8
        if (gpioI2CCRC8(read_buf, 3) != read_buf[2] || gpioI2CCRC8(read_buf + 3, 3) != read_buf[5]) {
            fprintf(stderr, "CRC-8 validation failed.\n");
            continue;
        }

        // convert raw pressure and temperature
        scale_factor = (read_buf[6] << 8) | read_buf[7];
        pressure = ((read_buf[0] << 8) | read_buf[1]) / (double)scale_factor;
        temperature = ((read_buf[3] << 8) | read_buf[4]) / 200.0;

        // log the reading with a timestamp
        fprintf(file, "%ld, %.2f, %.2f\n", time(NULL), pressure, temperature);
        fflush(file);
    }

    fclose(file);
    gpioI2CClose(i2c_fd);
    gpioTerminate();

    return EXIT_SUCCESS;
}

