    fprintf(stderr, "%s: %s\n", timestamp, msg);
    if (log_file) {
        fprintf(log_file, "%s,%s\n", timestamp, msg);
        fflush(log_file);
    }
}

void sig_handler(int signo) {
    if (log_file) fclose(log_file);
    gpioTerminate();
    exit(signo == SIGTERM ? 0 : 1);
}

int main() {
    int i2c_handle = gpioi2cOpen(I2C_BUS, I2C_ADDRESS);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    log_file = fopen("environment.log", "w");
    if (!log_file) {
        log_error("Failed to open log file");
        sig_handler(0);
    }

    while (1) {
        int raw_value;
        for (int i = 0; i < MAX_TRIES; i++) {
            if (gpioi2cWriteByte(i2c_handle, 0xF5) == 0) {
                usleep(20000);
                if (gpioi2cReadWord(i2c_handle, &raw_value) == 0) {
                    break;
                }
            }
            if (i == MAX_TRIES - 1) {
                log_error("Failed to read humidity");
                sig_handler(0);
            }
        }
        float humidity = 125.0 * raw_value / 65536.0 - 6.0;
        if (humidity < 0) humidity = 0;
        if (humidity > 100) humidity = 100;

        for (int i = 0; i < MAX_TRIES; i++) {
            if (gpioi2cWriteByte(i2c_handle, 0xF3) == 0) {
                usleep(20000);
                if (gpioi2cReadWord(i2c_handle, &raw_value) == 0) {
                    break;
                }
            }
            if (i == MAX_TRIES - 1) {
                log_error("Failed to read temperature");
                sig_handler(0);
            }
        }
        float temperature = 175.72 * raw_value / 65536.0 - 46.85;

        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

        printf("%s,%.2f,%.2f\n", timestamp, temperature, humidity);
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
        fflush(log_file);

        sleep(60);
    }

    return 0;
}
