#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SENSOR_ADDRESS 0x44
#define LOG_FILE "temperature_log.txt"

static int i2c_file_descriptor = -1;
static FILE* log_file = NULL;

static void cleanup(void) {
    if (i2c_file_descriptor != -1) {
        close(i2c_file_descriptor);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

static void error_exit(const char* message) {
    fprintf(stderr, "%s\n", message);
    cleanup();
    exit(EXIT_FAILURE);
}

static void write_log(const char* message) {
    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            error_exit("Failed to open log file");
        }
    }
    fprintf(log_file, "%s\n", message);
}

static void handle_signal(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main(void) {
    struct sigaction action;
    action.sa_handler = handle_signal;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    if (sigaction(SIGINT, &action, NULL) < 0 || sigaction(SIGTERM, &action, NULL) < 0) {
        error_exit("Failed to set signal handler");
    }

    i2c_file_descriptor = open(I2C_DEVICE, O_RDWR);
    if (i2c_file_descriptor < 0) {
        error_exit("Failed to open I2C device");
    }

    if (ioctl(i2c_file_descriptor, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        error_exit("Failed to set slave address");
    }

    unsigned char command[] = {0x2C, 0xE0};
    unsigned char buffer[3];
    while (1) {
        if (write(i2c_file_descriptor, command, sizeof(command)) != sizeof(command)) {
            error_exit("Failed to write command to sensor");
        }
        usleep(10000);  // Wait 10 ms for conversion
        if (read(i2c_file_descriptor, buffer, sizeof(buffer)) != sizeof(buffer)) {
            error_exit("Failed to read sensor data");
        }

        // Validate CRC8 using the Sensirion polynomial 0x31
        unsigned char crc = buffer[0];
        crc ^= buffer[1] >> 4;
        crc ^= buffer[1] << 4;
        crc ^= buffer[2] >> 4;
        crc ^= buffer[2] << 4;
        if (crc != 0) {
            error_exit("CRC mismatch");
        }

        // Convert the raw ticks to Celsius
        int raw = (buffer[1] << 8) | buffer[2];
        double celsius = -45 + 175.0 * raw / 65535.0;

        // Log the reading with an ISO-8601 timestamp
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
        char log_message[50];
        snprintf(log_message, sizeof(log_message), "%s %.2f", timestamp, celsius);
        write_log(log_message);

        sleep(5);  // Wait 5 seconds before the next measurement
    }

    return 0;
}

