volatile sig_atomic_t stop;

void handle_sigint(int signum) {
    stop = 1;
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
}

uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        printf("gpioInitialise failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        printf("i2cOpen failed\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        printf("fopen failed\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    uint8_t cmd[] = {0x36, 0x15};
    uint8_t data[9];
    while (!stop) {
        if (i2cWrite(i2c_handle, cmd, sizeof(cmd)) < 0) {
            fprintf(log_file, "%ld,I2C write error\n", time(NULL));
            fflush(log_file);
            continue;
        }
        sleep(50);  // wait at least 50 ms
        if (i2cRead(i2c_handle, data, sizeof(data)) < 0) {
            fprintf(log_file, "%ld,I2C read error\n", time(NULL));
            fflush(log_file);
            continue;
        }
        if (crc8(data, 3) != 0 || crc8(data + 3, 3) != 0 || crc8(data + 6, 3) != 0) {
            fprintf(log_file, "%ld,CRC error\n", time(NULL));
            fflush(log_file);
            continue;
        }
        float pressure = (data[0] << 8 | data[1]) / (float)data[2];
        float temperature = (data[3] << 8 | data[4]) / 200.0;
        fprintf(log_file, "%ld,%.2f,%.2f\n", time(NULL), pressure, temperature);
        fflush(log_file);
    }

    return 0;
}

