#define SCD40_I2C_ADDR 0x62
#define SCD40_START_MEAS 0x21B1
#define SCD40_STOP_MEAS 0x3F86
#define SCD40_READ_MEAS 0xE000
#define SCD40_CRC_POLY 0x31
#define SCD40_CRC_INIT 0xFF
#define SCD40_BUFFER_SIZE 100

typedef struct {
    time_t timestamp;
    unsigned short co2;
    float temperature;
    float humidity;
} SCD40_reading;

SCD40_reading buffer[SCD40_BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;
volatile sig_atomic_t running = 1;

int crc8(const unsigned char *data, int len, int poly, int init) {
    int crc = init;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ poly;
            else
                crc <<= 1;
        }
    }
    return crc & 0xFF;
}

void *log_thread_func(void *arg) {
    // Write the entire buffer to a timestamped CSV file
    time_t now = time(NULL);
    struct tm *now_tm = localtime(&now);
    char filename[64];
    snprintf(filename, sizeof(filename), "/var/log/scd40_data/data_%04d%02d%02d_%02d%02d%02d.csv",
             now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
             now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec);
    FILE *file = fopen(filename, "w");
    if (!file) {
        perror("fopen");
        return NULL;
    }
    fprintf(file, "timestamp,co2,temperature,humidity\n");
    while (buffer_tail != buffer_head) {
        fprintf(file, "%ld,%hu,%.2f,%.2f\n",
                buffer[buffer_tail].timestamp, buffer[buffer_tail].co2,
                buffer[buffer_tail].temperature, buffer[buffer_tail].humidity);
        buffer_tail = (buffer_tail + 1) % SCD40_BUFFER_SIZE;
    }
    fclose(file);
    return NULL;
}

