#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x63
#define I2C_HANDLE -1

volatile sig_atomic_t exit_flag = 0;

void exit_handler(int signum) {
    exit_flag = 1;
}

int main() {
    int i2c_handle = I2C_HANDLE;
    int fd = -1;
    struct sigaction action;
    action.sa_handler = exit_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = gpioI2CSetup(I2C_BUS);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to setup I2C bus.\n");
        goto cleanup;
    }

    fd = open("environmental_data.txt", O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (fd < 0) {
        fprintf(stderr, "Failed to open file.\n");
        goto cleanup;
    }

    while (!exit_flag) {
        int who_am_i;
        if (gpioI2CReadByteReg(i2c_handle, I2C_ADDR, 0x08, &who_am_i) < 0) {
            fprintf(stderr, "Failed to read WHO_AM_I register.\n");
            continue;
        }
        if (who_am_i != 0x08) {
            fprintf(stderr, "Unexpected sensor identity.\n");
            continue;
        }

        int coeff[4];
        for (int i = 0; i < 4; i++) {
            if (gpioI2CReadByteReg(i2c_handle, I2C_ADDR, 0x05 + i, &coeff[i]) < 0) {
                fprintf(stderr, "Failed to read calibration coefficient.\n");
                continue;
            }
        }

        if (gpioI2CWriteByteReg(i2c_handle, I2C_ADDR, 0x00, 0x00) < 0) {
            fprintf(stderr, "Failed to trigger measurement.\n");
            continue;
        }
        usleep(10000);

        char data[6];
        if (gpioI2CReadI2CBlockData(i2c_handle, I2C_ADDR, 0x00, sizeof(data), data) < 0) {
            fprintf(stderr, "Failed to read measurement data.\n");
            continue;
        }

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

        char output[100];
        sprintf(output, "%s pressure: %.2f hPa, temperature: %.2f C\n", timestamp, 0.01 * ((data[0] << 8) | data[1]), 0.01 * ((data[2] << 8) | data[3]));

        if (write(fd, output, strlen(output)) < 0) {
            fprintf(stderr, "Failed to write to file.\n");
            continue;
        }
        fflush(stdout);

        sleep(5);
    }

cleanup:
    if (fd >= 0) close(fd);
    if (i2c_handle != I2C_HANDLE) gpioI2CClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

