#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <signal.h>
#include <linux/types.h>
#include <gpiod.h>
#include <math.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x63
#define GPIO_LINE 17

struct gpiod_chip *chip;
struct gpiod_line *line;
int i2c_file_descriptor;

uint16_t crc_table[256];

void build_crc_table(void) {
    int i, j;
    uint16_t crc;

    for (i = 0; i < 256; i++) {
        crc = i;
        for (j = 0; j < 8; j++)
            if (crc & 0x0001)
                crc = (crc >> 1) ^ 0x8408;
            else
                crc >>= 1;
        crc_table[i] = crc;
    }
}

uint16_t compute_crc(const uint8_t *data, int length) {
    int i;
    uint16_t crc = 0xffff;

    for (i = 0; i < length; i++)
        crc = (crc >> 8) ^ crc_table[(crc ^ data[i]) & 0xff];

    return crc;
}

void sigint_handler(int signum) {
    gpiod_line_release(line);
    close(i2c_file_descriptor);
    exit(0);
}

int main(void) {
    struct i2c_msg msgs[2];
    uint8_t buf[6];
    uint16_t crc, computed_crc;
    uint32_t pressure, temperature;
    double p, t;
    int rc, i;

    build_crc_table();

    signal(SIGINT, sigint_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    rc = gpiod_line_request_output(line, "icp10125", 0);
    if (rc < 0) {
        perror("gpiod_line_request_output");
        return 1;
    }

    i2c_file_descriptor = open("/dev/i2c-1", O_RDWR);
    if (i2c_file_descriptor < 0) {
        perror("open");
        return 1;
    }

    rc = ioctl(i2c_file_descriptor, I2C_SLAVE, I2C_ADDRESS);
    if (rc < 0) {
        perror("ioctl");
        return 1;
    }

    while (1) {
        msgs[0].addr = I2C_ADDRESS;
        msgs[0].flags = 0;
        msgs[0].len = 2;
        msgs[0].buf = (uint8_t[]){0x40, 0x11};

        msgs[1].addr = I2C_ADDRESS;
        msgs[1].flags = I2C_M_RD;
        msgs[1].len = sizeof(buf);
        msgs[1].buf = buf;

        rc = i2c_rdwr(i2c_file_descriptor, msgs, 2);
        if (rc < 0) {
            perror("i2c_rdwr");
            return 1;
        }

        pressure = (buf[0] << 8) | buf[1];
        temperature = (buf[2] << 8) | buf[3];
        crc = (buf[4] << 8) | buf[5];

        computed_crc = compute_crc(buf, 4);
        if (crc != computed_crc) {
            fprintf(stderr, "CRC mismatch\n");
            return 1;
        }

        p = (double)(pressure - 100000) * 1000.0 / 1023.0 + 100000.0;
        t = (double)(temperature - 2000) * 100.0 / 1023.0 + 20.0;

