uint16_t crc_table[256];

void build_crc_table(void) {
    int i, j;
    uint16_t crc;

    for (i = 0; i < 256; i++) {
        crc = i;
        for (j = 0; j < 8; j++)
            if (crc & 0x0001)
                crc = (crc >> 1) ^ 0x8408;
            else
                crc >>= 1;
        crc_table[i] = crc;
    }
}

uint16_t compute_crc(const uint8_t *data, int length) {
    int i;
    uint16_t crc = 0xffff;

    for (i = 0; i < length; i++)
        crc = (crc >> 8) ^ crc_table[(crc ^ data[i]) & 0xff];

    return crc;
}

void sigint_handler(int signum) {
    gpiod_line_release(line);
    close(i2c_file_descriptor);
    exit(0);
}

int main(void) {
    struct i2c_msg msgs[2];
    uint8_t buf[6];
    uint16_t crc, computed_crc;
    uint32_t pressure, temperature;
    double p, t;
    int rc, i;

    build_crc_table();

    signal(SIGINT, sigint_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

