    if (rc < 0) {
        perror("gpiod_line_request_output");
        return 1;
    }

    i2c_file_descriptor = open("/dev/i2c-1", O_RDWR);
    if (i2c_file_descriptor < 0) {
        perror("open");
        return 1;
    }

    rc = ioctl(i2c_file_descriptor, I2C_SLAVE, I2C_ADDRESS);
    if (rc < 0) {
        perror("ioctl");
        return 1;
    }

    while (1) {
        msgs[0].addr = I2C_ADDRESS;
        msgs[0].flags = 0;
        msgs[0].len = 2;
        msgs[0].buf = (uint8_t[]){0x40, 0x11};

        msgs[1].addr = I2C_ADDRESS;
        msgs[1].flags = I2C_M_RD;
