    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    i2c_handle = piI2COpen(MLX90614_I2C_BUS, MLX90614_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    FILE *log_file = fopen("temperature_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    while (1) {
        int16_t raw_temp;
        for (int i = 0; i < MAX_READ_RETRIES; i++) {
            if (piI2CReadWord(i2c_handle, MLX90614_OBJECT_TEMP_REG, &raw_temp) == 0) {
                break;
            }
            usleep(10000);
        }
        double temp = raw_temp * MLX90614_CONVERSION_FACTOR + MLX90614_CONVERSION_OFFSET;
        if (temp >= MLX90614_CONVERSION_OFFSET) {
            time_t now = time(NULL);
            struct tm *local_time = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", local_time);
            fprintf(log_file, "%s: Object temperature: %.2f °C\n", timestamp, temp);
            fflush(log_file);

            if (temp > TURN_ON_TEMP && !fan_state) {
                gpioWrite(FAN_GPIO, 1);
                fan_state = 1;
            } else if (temp < TURN_OFF_TEMP && fan_state) {
                gpioWrite(FAN_GPIO, 0);
                fan_state = 0;
            }
        }
        sleep(2);
    }

    fclose(log_file);
    piI2CClose(i2c_handle);
    gpioTerminate();
    return 0;
}

