#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define SHT40_ADDR 0x44
#define SHT40_MEASURE_HIGH_REP 0xFD
#define SHT40_RETRIES 3
#define WEBSERVER_PORT 8080

static int i2c_fd = -1;
static int http_fd = -1;

static void cleanup(void) {
    if (i2c_fd != -1) {
        piI2CSimpleClose(i2c_fd);
    }
    if (http_fd != -1) {
        close(http_fd);
    }
    piStop();
}

static void handle_signal(int signum) {
    cleanup();
    exit(signum);
}

int main(void) {
    struct sigaction action;
    action.sa_handler = handle_signal;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    if (piI2CSetup() < 0) {
        fprintf(stderr, "Failed to setup I2C\n");
        return EXIT_FAILURE;
    }

    i2c_fd = piI2CReadOpen("/dev/i2c-1", SHT40_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        cleanup();
        return EXIT_FAILURE;
    }

    http_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (http_fd < 0) {
        fprintf(stderr, "Failed to create socket\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(WEBSERVER_PORT);
    addr.sin_addr.s_addr = htonl(INADDR_ANY);
    if (bind(http_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "Failed to bind socket\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (listen(http_fd, 5) < 0) {
        fprintf(stderr, "Failed to listen on socket\n");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        int client_fd = accept(http_fd, NULL, NULL);
        if (client_fd < 0) {
            fprintf(stderr, "Failed to accept client\n");
            continue;
        }

        int retries = SHT40_RETRIES;
        while (retries--) {
            if (piI2CWriteByte(i2c_fd, SHT40_MEASURE_HIGH_REP) < 0) {
                fprintf(stderr, "Failed to write to I2C device\n");
                continue;
            }

            usleep(10000);  // 10 ms

            uint8_t data[6];
            if (piI2CReadBytes(i2c_fd, data, sizeof(data)) < 0) {
                fprintf(stderr, "Failed to read from I2C device\n");
                continue;
            }

            int raw_t = (data[0] << 8) | data[1];
            int raw_rh = (data[3] << 8) | data[4];
            float t = -45.0 + 175.0 * raw_t / 65535.0;
            float rh = -6.0 + 125.0 * raw_rh / 65535.0;
            if (rh < 0.0) rh = 0.0;
            if (rh > 100.0) rh = 100.0;

            char response[128];
            snprintf(response, sizeof(response),
                     "HTTP/1.1 200 OK\r\n"
                     "Content-Type: text/html\r\n"
                     "\r\n"
                     "<html><body><p>Temperature: %.2f&deg;C</p><p>Humidity: %.2f%%</p></body></html>",
                     t, rh);
            if (send(client_fd, response, strlen(response), 0) < 0) {
                fprintf(stderr, "Failed to send response\n");
            }

            break;
        }

        close(client_fd);
    }

    return EXIT_SUCCESS;
}

