#define I2C_BUS 1
#define I2C_ADDR 0x48
#define REG_TEMP 0x00

volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

int main() {
    int pi;
    int i2c_handle;
    uint16_t temp_raw;
    double temp_c;
    FILE *file;
    struct tm *timeinfo;
    char timestamp[20];
    char filename[] = "/home/pi/temperature_log.csv";

    signal(SIGINT, handle_sigint);

    pi = pigpio_start();

    if (pi < 0) {
        fprintf(stderr, "Could not start pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    i2c_handle = piI2C(I2C_BUS, I2C_ADDR);

    if (i2c_handle < 0) {
        fprintf(stderr, "Could not open I2C device: %s\n", strerror(errno));
        pigpio_stop(pi);
        return EXIT_FAILURE;
    }

    file = fopen(filename, "w");

    if (file == NULL) {
        fprintf(stderr, "Could not open file %s: %s\n", filename, strerror(errno));
        piI2C_close(i2c_handle);
        pigpio_stop(pi);
        return EXIT_FAILURE;
    }

    while (!stop) {
        temp_raw = piI2C_readWord(i2c_handle, REG_TEMP);

        if (temp_raw < 0) {
            fprintf(stderr, "Could not read temperature: %s\n", strerror(errno));
        } else {
            temp_raw >>= 4;
            temp_c = (double)temp_raw * 0.0625;

            timeinfo = localtime(time(NULL));
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            fprintf(file, "%s,%.2f\n", timestamp, temp_c);
            fflush(file);
        }

        sleep(5);
    }

    fclose(file);
    piI2C_close(i2c_handle);
    pigpio_stop(pi);

    return EXIT_SUCCESS;
}

