#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define CONFIG_REG 0x0F
#define CONFIG_VAL 0x00
#define MEASUREMENT_CONFIG 0x0E
#define MEASUREMENT_VAL 0x01
#define MAX_RETRIES 5

volatile sig_atomic_t stop = 0;

void sig_handler(int signo) {
    if (signo == SIGINT) {
        stop = 1;
    }
}

int main() {
    int i2c_handle;
    int retries = 0;
    int status;
    unsigned char buf[2];
    float temperature, humidity;

    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio.\n");
        return 1;
    }

    signal(SIGINT, sig_handler);

    while (1) {
        if (stop) {
            break;
        }

        i2c_handle = gpioI2CSetSlave(I2C_BUS, I2C_ADDR);
        if (i2c_handle < 0) {
            printf("Failed to set I2C slave.\n");
            return 1;
        }

        status = gpioI2CWriteByte(i2c_handle, CONFIG_REG);
        if (status < 0) {
            printf("Failed to write to CONFIG_REG.\n");
