#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SDP800_I2C_BUS 1
#define SDP800_I2C_ADDR 0x25
#define SDP800_MEASURE_CMD 0x362F
#define SDP800_DATA_LEN 6

static int i2c_handle = -1;

static void cleanup_and_exit(int sig) {
    if (i2c_handle != -1) {
        piI2CClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

static int calc_crc8(const unsigned char *data, int len, int poly, int init) {
    int crc = init;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ poly;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc & 0xFF;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup_and_exit);

    i2c_handle = piI2COpen(SDP800_I2C_BUS, SDP800_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d for address 0x%02X.\n", SDP800_I2C_BUS, SDP800_I2C_ADDR);
        cleanup_and_exit(0);
    }

    unsigned char cmd_buf[2] = {SDP800_MEASURE_CMD >> 8, SDP800_MEASURE_CMD & 0xFF};
    if (piI2CWrite(i2c_handle, cmd_buf, 2) < 0) {
        fprintf(stderr, "Failed to write command to SDP800 sensor.\n");
        cleanup_and_exit(0);
    }

    while (1) {
        usleep(45000);  // Wait for measurement to complete.

        unsigned char data[SDP800_DATA_LEN];
        if (piI2CRead(i2c_handle, data, SDP800_DATA_LEN) < 0) {
            fprintf(stderr, "Failed to read data from SDP800 sensor.\n");
            cleanup_and_exit(0);
        }

        int pressure = (data[0] << 8) | data[1];
        int pressure_crc = calc_crc8(data, 2, 0x31, 0xFF);
        if (pressure_crc != data[2]) {
            fprintf(stderr, "Pressure CRC check failed.\n");
            continue;
        }

        int temperature = (data[3] << 8) | data[4];
        int temperature_crc = calc_crc8(data + 3, 2, 0x31, 0xFF);
        if (temperature_crc != data[5]) {
            fprintf(stderr, "Temperature CRC check failed.\n");
            continue;
        }

        printf("Pressure: %d, Temperature: %d\n", pressure, temperature);

        usleep(500000);  // Wait before next measurement.
    }

    return EXIT_SUCCESS;
}

