#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <time.h>
#include <libgpiod.h>

#define DS18B20_PATH "/sys/bus/w1/devices/28-0000052101b9/w1_slave"
#define GPIO_RELAY 17
#define GPIO_PWM 18
#define PWM_PERIOD 1000000
#define LOG_FILE "greenhouse.log"

struct gpiod_line *line_relay, *line_pwm;
struct gpiod_chip *chip;
FILE *log_file;

void cleanup_and_exit(int signum) {
    gpiod_line_set_value(line_relay, 0);
    gpiod_line_release(line_relay);
    gpiod_line_release(line_pwm);
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(signum);
}

int main(int argc, char *argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        return 1;
    }

    double setpoint = atof(argv[1]);
    double Kp = atof(argv[2]), Ki = atof(argv[3]), Kd = atof(argv[4]);
    double temp_sum = 0, error_sum = 0, last_error = 0, pwm_duty = 0;

    chip = gpiod_chip_open_by_name("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line_relay = gpiod_chip_get_line(chip, GPIO_RELAY);
    if (!line_relay) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    if (gpiod_line_request_output(line_relay, "relay", 0)) {
        perror("gpiod_line_request_output");
        return 1;
    }

    line_pwm = gpiod_chip_get_line(chip, GPIO_PWM);
    if (!line_pwm) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    if (gpiod_line_request_pwm(line_pwm, "pwm", PWM_PERIOD, 0)) {
        perror("gpiod_line_request_pwm");
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    while (1) {
        int fd = open(DS18B20_PATH, O_RDONLY);
        if (fd < 0) {
            perror("open");
            continue;
        }

        char buf[100];
        ssize_t bytes_read = read(fd, buf, sizeof(buf) - 1);
        if (bytes_read < 0) {
            perror("read");
            close(fd);
            continue;
        }

        buf[bytes_read] = '\0';
        if (strncmp(buf + bytes_read - 2, "BE", 2)) {
            fprintf(stderr, "CRC error\n");
            close(fd);
            continue;
        }

        double temp = atof(buf + 9);
        temp_sum += temp;

        double error = setpoint - temp;
        error_sum += error;
        double derivative = error - last_error;
        last_error = error;

        pwm_duty = Kp * error + Ki * error_sum + Kd * derivative;
        if (pwm_duty < 0) pwm_duty = 0;
        else if (pwm_duty > 1) pwm_duty = 1;

        gpiod_line_set_pwm_duty_cycle(line_pwm, pwm_duty * PWM_PERIOD);
        if (pwm_duty > 0.01) gpiod_line_set_value(line_relay, 1);
        else gpiod_line_set_value(line_relay, 0);

        time_t t = time(NULL);
        struct tm *tm = localtime(&t);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        fprintf(log_file, "%s, %.2f, %.2f, %.2f, %.2f\n", timestamp, temp, setpoint, error, pwm_duty);
        fflush(log_file);

        close(fd);
        sleep(5);
    }

    return 0;
}

