#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <syslog.h>
#include <signal.h>
#include <netdb.h>
#include <netinet/in.h>
#include <sys/socket.h>
#include <arpa/inet.h>

#define HTU21D_ADDR 0x40
#define I2C_DEV "/dev/i2c-1"
#define API_ENDPOINT "http://api.example.com/humidity"
#define POST_DATA_FMT "{\"humidity\":%.2f}"

static int i2c_fd = -1;
static int sock_fd = -1;

static void cleanup(void) {
    if (i2c_fd != -1)
        close(i2c_fd);
    if (sock_fd != -1)
        close(sock_fd);
}

static void handle_sig(int sig) {
    syslog(LOG_INFO, "Got signal %d, shutting down", sig);
    cleanup();
    closelog();
    exit(0);
}

static int i2c_write_read(const char *data, size_t write_len, char *buf, size_t read_len) {
    struct i2c_msg msgs[] = {
        { .addr = HTU21D_ADDR, .flags = 0, .len = write_len, .buf = (char *)data },
        { .addr = HTU21D_ADDR, .flags = I2C_M_RD, .len = read_len, .buf = buf },
    };
    struct i2c_rdwr_ioctl_data msg_data = { .msgs = msgs, .nmsgs = 2 };
    if (ioctl(i2c_fd, I2C_RDWR, &msg_data) < 0) {
        syslog(LOG_ERR, "I2C communication failed: %m");
        return -1;
    }
    return 0;
}

static int send_http_request(const char *data, size_t len) {
    struct sockaddr_in addr;
    struct hostent *host = gethostbyname("api.example.com");
    if (!host) {
        syslog(LOG_ERR, "Could not resolve host: %m");
        return -1;
    }
    sock_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (sock_fd < 0) {
        syslog(LOG_ERR, "Could not create socket: %m");
        return -1;
    }
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(80);
    memcpy(&addr.sin_addr, host->h_addr_list[0], host->h_length);
    if (connect(sock_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        syslog(LOG_ERR, "Could not connect to host: %m");
        return -1;
    }
    if (write(sock_fd, data, len) < 0) {
        syslog(LOG_ERR, "Could not write to socket: %m");
        return -1;
    }
    return 0;
}

int main(void) {
    openlog("htu21d_reader", LOG_PERROR, LOG_USER);
    signal(SIGINT, handle_sig);
    signal(SIGTERM, handle_sig);
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Could not open I2C device: %m");
        closelog();
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Could not set I2C slave address: %m");
        cleanup();
        closelog();
        return 1;
    }
    while (1) {
        char buf[3];
        if (i2c_write_read("\xE5", 1, buf, 3) < 0) {
            cleanup();
            closelog();
            return 1;
        }
        float humidity = ((buf[0] << 8 | buf[1]) & 0xFFF) * 100.0 / 0xFFF;
        char post_data[64];
        snprintf(post_data, sizeof(post_data), POST_DATA_FMT, humidity);
        if (send_http_request(post_data, strlen(post_data)) < 0) {
            cleanup();
            closelog();
            return 1;
        }
        sleep(60);
    }
    return 0;
}

