#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define BMP280_I2C_BUS 1
#define BMP280_I2C_ADDR 0x76
#define BMP280_CHIP_ID_REG 0xD0
#define BMP280_CHIP_ID 0x58
#define BMP280_CALIB_REG 0x88
#define BMP280_CALIB_LEN 24
#define BMP280_CTRL_MEAS_REG 0xF4
#define BMP280_CTRL_MEAS_VAL 0x27
#define BMP280_RESET_REG 0xE0
#define BMP280_RESET_VAL 0xB6
#define BMP280_DATA_REG 0xF7
#define BMP280_SAMPLE_INTERVAL 2
#define BMP280_PRESSURE_THRESHOLD_LOW 980
#define BMP280_PRESSURE_THRESHOLD_HIGH 1020

static int i2c_handle = -1;
static volatile int stop = 0;

void cleanup(void) {
    if (i2c_handle >= 0) {
        piI2C_close(i2c_handle);
    }
    gpioTerminate();
}

void handle_signal(int signum) {
    stop = 1;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = piI2C_open(BMP280_I2C_BUS, BMP280_I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        cleanup();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int retries = 0;
    while (retries < 3) {
        int chip_id = piI2C_readByteData(i2c_handle, BMP280_CHIP_ID_REG);
        if (chip_id == BMP280_CHIP_ID) {
            break;
        }
        fprintf(stderr, "Invalid chip ID: %d\n", chip_id);
        if (piI2C_close(i2c_handle) < 0) {
            fprintf(stderr, "Failed to close I2C bus.\n");
            cleanup();
            return EXIT_FAILURE;
        }
        i2c_handle = piI2C_open(BMP280_I2C_BUS, BMP280_I2C_ADDR);
        if (i2c_handle < 0) {
            fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
            cleanup();
            return EXIT_FAILURE;
        }
        retries++;
    }
    if (retries == 3) {
        fprintf(stderr, "Failed to verify chip ID after 3 retries.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    int calib[BMP280_CALIB_LEN];
    for (int i = 0; i < BMP280_CALIB_LEN; i++) {
        calib[i] = piI2C_readByteData(i2c_handle, BMP280_CALIB_REG + i);
        if (calib[i] < 0) {
            fprintf(stderr, "Failed to read calibration data: %d\n", calib[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    if (piI2C_writeByteData(i2c_handle, BMP280_RESET_REG, BMP280_RESET_VAL) < 0) {
        fprintf(stderr, "Failed to reset sensor.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (piI2C_writeByteData(i2c_handle, BMP280_CTRL_MEAS_REG, BMP280_CTRL_MEAS_VAL) < 0) {
        fprintf(stderr, "Failed to configure sensor.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("pressure_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    while (!stop) {
        if (piI2C_writeByteData(i2c_handle, BMP280_CTRL_MEAS_REG, 0x01) < 0) {
            fprintf(stderr, "Failed to trigger measurement.\n");
            cleanup();
            return EXIT_FAILURE;
        }
        usleep(10000);

        int raw_data[6];
        for (int i = 0; i < 6; i++) {
            raw_data[i] = piI2C_readByteData(i2c_handle, BMP280_DATA_REG + i);
            if (raw_data[i] < 0) {
                fprintf(stderr, "Failed to read raw data: %d\n", raw_data[i]);
                cleanup();
                return EXIT_FAILURE;
            }
        }

        int adc_P = (raw_data[0] << 12) | (raw_data[1] << 4) | (raw_data[2] >> 4);
        int pressure = 1048576 - adc_P;

        // Apply Bosch compensation formulas here...

        if (pressure < BMP280_PRESSURE_THRESHOLD_LOW || pressure > BMP280_PRESSURE_THRESHOLD_HIGH) {
            time_t now = time(NULL);
            struct tm *local_time = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", local_time);
            fprintf(log_file, "%s: Pressure threshold breach: %d hPa\n", timestamp, pressure);
        }

        sleep(BMP280_SAMPLE_INTERVAL);
    }

    fclose(log_file);
    cleanup();
    return EXIT_SUCCESS;
}

