#define GPIO_RAIN_SENSOR 17
#define GPIO_MOTOR_ENABLE 22
#define GPIO_MOTOR_DIR1 23
#define GPIO_MOTOR_DIR2 24

struct gpiod_line *line_rain, *line_enable, *line_dir1, *line_dir2;
struct gpiod_chip *chip;
int rain_value, motor_enabled = 0;

void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char buffer[80];
    strftime(buffer, sizeof(buffer), "%d-%m-%Y %H:%M:%S", timeinfo);
    printf("[%s] %s\n", buffer, event);
}

void stop_motor(void) {
    if (motor_enabled) {
        gpiod_line_set_value(line_enable, 0);
        motor_enabled = 0;
        log_event("Motor stopped");
    }
}

void open_window(void) {
    if (!motor_enabled) {
        gpiod_line_set_value(line_dir1, 1);
        gpiod_line_set_value(line_dir2, 0);
        gpiod_line_set_value(line_enable, 1);
        motor_enabled = 1;
        log_event("Motor started");
        sleep(5);
        stop_motor();
    }
}

void handle_signal(int signum) {
    stop_motor();
    gpiod_line_release(line_rain);
    gpiod_line_release(line_enable);
    gpiod_line_release(line_dir1);
    gpiod_line_release(line_dir2);
    gpiod_chip_close(chip);
    log_event("Program terminated");
    exit(0);
}

int main(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    line_rain = gpiod_chip_get_line(chip, GPIO_RAIN_SENSOR);
    if (!line_rain || gpiod_line_request_input(line_rain, "Rain sensor")) {
        fprintf(stderr, "Failed to request rain sensor line\n");
        return 1;
    }

    line_enable = gpiod_chip_get_line(chip, GPIO_MOTOR_ENABLE);
    if (!line_enable || gpiod_line_request_output(line_enable, "Motor enable", 0)) {
        fprintf(stderr, "Failed to request motor enable line\n");
        return 1;
    }

    line_dir1 = gpiod_chip_get_line(chip, GPIO_MOTOR_DIR1);
    if (!line_dir1 || gpiod_line_request_output(line_dir1, "Motor direction 1", 0)) {
        fprintf(stderr, "Failed to request motor direction 1 line\n");
        return 1;
    }

    line_dir2 = gpiod_chip_get_line(chip, GPIO_MOTOR_DIR2);
    if (!line_dir2 || gpiod_line_request_output(line_dir2, "Motor direction 2", 0)) {
        fprintf(stderr, "Failed to request motor direction 2 line\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    log_event("Program started");

    while (1) {
        rain_value = gpiod_line_get_value(line_rain);
        if (rain_value == 0) {
            open_window();
        }
        sleep(2);
    }

    return 0;
}

