#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <string.h>
#include <pigpio.h>

#define GPIO_RED     17
#define GPIO_GREEN   22
#define GPIO_BLUE    27
#define PWM_RANGE    255

volatile sig_atomic_t stop = 0;

void sig_handler(int signo) {
    gpioWrite(GPIO_RED, PWM_RANGE);
    gpioWrite(GPIO_GREEN, PWM_RANGE);
    gpioWrite(GPIO_BLUE, PWM_RANGE);
    gpioTerminate();
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    gpioSetPWMrange(GPIO_RED, PWM_RANGE + 1);
    gpioSetPWMrange(GPIO_GREEN, PWM_RANGE + 1);
    gpioSetPWMrange(GPIO_BLUE, PWM_RANGE + 1);

    struct sigaction sigIntHandler;
    sigIntHandler.sa_handler = sig_handler;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_flags = 0;
    sigaction(SIGINT, &sigIntHandler, NULL);
    sigaction(SIGTERM, &sigIntHandler, NULL);

    int fd = open("/proc/stat", O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /proc/stat.\n");
        gpioTerminate();
        return 1;
    }

    char line[100];
    unsigned long user, nice, system, idle, cpu_stat[5];
    while (!stop) {
        lseek(fd, 0, SEEK_SET);
        read(fd, line, sizeof(line));
        sscanf(line, "cpu %lu %lu %lu %lu", &user, &nice, &system, &idle);
        cpu_stat[0] = user + nice + system + idle;
        cpu_stat[1] = user + nice;
        cpu_stat[2] = system;
        cpu_stat[3] = user;
        cpu_stat[4] = idle;

        usleep(500000);

        lseek(fd, 0, SEEK_SET);
        read(fd, line, sizeof(line));
        sscanf(line, "cpu %lu %lu %lu %lu", &user, &nice, &system, &idle);
        cpu_stat[0] += user + nice + system + idle;
        cpu_stat[1] += user + nice;
        cpu_stat[2] += system;
        cpu_stat[3] += user;
        cpu_stat[4] += idle;

        unsigned long cpu_delta = cpu_stat[0] - (cpu_stat[1] + cpu_stat[2] + cpu_stat[3] + cpu_stat[4]);
        unsigned long idle_delta = cpu_stat[4] - idle;
        double cpu_load = 100.0 * (double)cpu_delta / (double)(cpu_delta + idle_delta);

        unsigned char red, green, blue;
        if (cpu_load < 50.0) {
            green = 255;
            red = (unsigned char)(255.0 * cpu_load / 50.0);
            blue = 0;
        } else {
            red = 255;
            green = (unsigned char)(255.0 * (100.0 - cpu_load) / 50.0);
            blue = 0;
        }

        gpioWrite(GPIO_RED, PWM_RANGE - red);
        gpioWrite(GPIO_GREEN, PWM_RANGE - green);
        gpioWrite(GPIO_BLUE, PWM_RANGE - blue);
    }

    close(fd);
    return 0;
}

