#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <spi.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define GPIO_FAN 18
#define GPIO_THERMOCOUPLE 8
#define MAX31855_FAULT_BIT 16
#define MAX31855_TEMP_BITS 14
#define MAX31855_TEMP_OFFSET 0x800
#define LOG_SIZE 20

struct log_entry {
    struct timespec ts;
    int temp;
    int duty;
};

struct log_entry log_buffer[LOG_SIZE];
int log_index = 0;
int spi_handle;
volatile int stop = 0;

void handle_sigint(int signum) {
    gpioPWM(GPIO_FAN, 0);
    spiClose(spi_handle);
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel: %d\n", spi_handle);
        return 1;
    }

    gpioSetMode(GPIO_FAN, PI_OUTPUT);
    gpioSetMode(GPIO_THERMOCOUPLE, PI_INPUT);

    signal(SIGINT, handle_sigint);

    while (!stop) {
        uint32_t data = spiXfer(spi_handle, 0x00000000, 32);
        if (data < 0) {
            fprintf(stderr, "Failed to read thermocouple: %d\n", data);
            continue;
        }

        int fault = (data >> MAX31855_FAULT_BIT) & 1;
        if (fault) {
            fprintf(stderr, "MAX31855 fault detected\n");
            continue;
        }

        int temp = (data >> (MAX31855_TEMP_BITS - 1)) & 0x1FFF;
        if (temp >= MAX31855_TEMP_OFFSET)
            temp -= 1 << MAX31855_TEMP_BITS;

        int duty;
        if (temp < 25000)
            duty = 0;
        else if (temp < 40000)
            duty = (temp - 25000) / 1000;
        else if (temp < 60000)
            duty = 50 + (temp - 40000) / 1000 * 150 / 20000;
        else
            duty = 200;

        gpioPWM(GPIO_FAN, duty);

        clock_gettime(CLOCK_REALTIME, &log_buffer[log_index].ts);
        log_buffer[log_index].temp = temp / 1000;
        log_buffer[log_index].duty = duty;
        log_index = (log_index + 1) % LOG_SIZE;

        sleep(1);
    }

    if (!stop)
        return 1;

    for (int i = 0; i < LOG_SIZE; i++) {
        struct timespec ts = log_buffer[i].ts;
        printf("%ld.%09ld %d %d\n", ts.tv_sec, ts.tv_nsec, log_buffer[i].temp, log_buffer[i].duty);
    }

    gpioTerminate();

    return 0;
}

