#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <bmp180.h>

#define I2C_BUS 1
#define I2C_ADDR 0x77
#define LOG_FILE "altitude_log.txt"

volatile sig_atomic_t stop = 0;
FILE *log_file;
int i2c_handle;

void sigint_handler(int signo) {
    stop = 1;
}

void log_pressure_temperature(void) {
    int16_t pressure, temperature;
    time_t now;
    struct tm *ts;
    char timestr[20];

    if (bmp180_read_pressure_temperature(i2c_handle, &pressure, &temperature) != 0) {
        fprintf(stderr, "Failed to read pressure and temperature\n");
        return;
    }

    time(&now);
    ts = localtime(&now);
    strftime(timestr, sizeof(timestr), "%Y-%m-%d %H:%M:%S", ts);

    fprintf(log_file, "%s,%d,%d\n", timestr, temperature, pressure);
    fflush(log_file);
}

int main(void) {
    struct sigaction sigint_action;
    struct bmp180_calib_data calib_data;

    if (bmp180_init_calib_data(i2c_handle, &calib_data) != 0) {
        fprintf(stderr, "Failed to initialize calibration data\n");
        return EXIT_FAILURE;
    }

    i2c_handle = bmp180_start(I2C_BUS, I2C_ADDR, &calib_data, 3);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to start I2C handle\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        bmp180_stop(i2c_handle);
        return EXIT_FAILURE;
    }

    sigint_action.sa_handler = sigint_handler;
    sigemptyset(&sigint_action.sa_mask);
    sigint_action.sa_flags = 0;
    sigaction(SIGINT, &sigint_action, NULL);

    while (!stop) {
        log_pressure_temperature();
        sleep(1);
    }

    bmp180_stop(i2c_handle);
    fclose(log_file);

    return EXIT_SUCCESS;
}

