#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <unistd.h>
#include <libgpiod.h>

#define SPI_DEV "/dev/spidev0.0"
#define CS_GPIO 8
#define LOG_FILE "rtd_log.csv"

struct gpiod_chip *chip;
struct gpiod_line *cs_line;
int spi_fd;
FILE *log_file;
volatile sig_atomic_t stop;

void sig_handler(int signum) {
    stop = 1;
}

void error_and_exit(const char *msg) {
    fprintf(stderr, "%s\n", msg);
    exit(EXIT_FAILURE);
}

void cleanup_and_exit(void) {
    if (log_file)
        fclose(log_file);
    if (spi_fd >= 0)
        close(spi_fd);
    if (cs_line)
        gpiod_line_release(cs_line);
    if (chip)
        gpiod_chip_close(chip);
    exit(EXIT_FAILURE);
}

int main(void) {
    struct sigaction sigint_action = { .sa_handler = sig_handler };
    struct spi_ioc_transfer xfer[2];
    uint16_t tx_buf[2] = { 0x0000, 0x0000 };
    uint16_t rx_buf[2];
    double temp;
    time_t now;
    struct tm *timeinfo;
    char timestr[20];

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    chip = gpiod_chip_open_by_number(0);
    if (!chip)
        error_and_exit("gpiod_chip_open_by_number");

    cs_line = gpiod_chip_get_line(chip, CS_GPIO);
    if (!cs_line)
        cleanup_and_exit();

    if (gpiod_line_request_output(cs_line, "rtd_logger", 1))
        cleanup_and_exit();

    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0)
        cleanup_and_exit();

    log_file = fopen(LOG_FILE, "w");
    if (!log_file)
        cleanup_and_exit();

    while (!stop) {
        // Set CS low
        gpiod_line_set_value(cs_line, 0);

        // Read RTD registers
        memset(xfer, 0, sizeof(xfer));
        xfer[0].tx_buf = &tx_buf;
        xfer[0].len = sizeof(tx_buf);
        xfer[1].rx_buf = &rx_buf;
        xfer[1].len = sizeof(rx_buf);
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(2), xfer) < 0) {
            fprintf(stderr, "SPI read error\n");
            continue;
        }

        // Check fault status
        if (rx_buf[1] & 0x0001) {
            fprintf(stderr, "RTD fault\n");
            continue;
        }

        // Calculate temperature
        temp = ((double)rx_buf[0] - 500.0) / 10.0;

        // Set CS high
        gpiod_line_set_value(cs_line, 1);

        // Get current time
        now = time(NULL);
        timeinfo = localtime(&now);
        strftime(timestr, sizeof(timestr), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Write to log file
        fprintf(log_file, "%s, %.2f\n", timestr, temp);
        fflush(log_file);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    fclose(log_file);
    close(spi_fd);
    gpiod_line_release(cs_line);
    gpiod_chip_close(chip);

    return 0;
}

