#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x77
#define CALIB_REG 0xAA
#define CTRL_REG 0xF4
#define OSS 0
#define ALERT_GPIO 24
#define BUF_SIZE 600
#define ALERT_THRESHOLD 5

static int i2c_handle;
static int *buf;
static int buf_head, buf_tail;
static int alert_triggered;

void handle_sigint(int signo) {
    if (i2c_handle >= 0) {
        if (i2cClose(i2c_handle) < 0) {
            fprintf(stderr, "Failed to close I2C handle: %s\n", strerror(errno));
        }
    }
    if (gpioSetMode(ALERT_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to reset GPIO: %s\n", strerror(errno));
    }
    if (piGpioInitialise() < 0) {
        fprintf(stderr, "Failed to terminate pigpio: %s\n", strerror(errno));
    }
    exit(0);
}

void sample_func(int gpio, int level, uint32_t tick) {
    int i, sum, avg, ret;
    struct timespec ts;

    if (i2cWriteByteData(i2c_handle, CTRL_REG, 0x34 + OSS) < 0) {
        fprintf(stderr, "Failed to write to sensor: %s\n", strerror(errno));
        return;
    }
    usleep(5000);
    if (i2cReadByteData(i2c_handle, CTRL_REG) < 0) {
        fprintf(stderr, "Failed to read from sensor: %s\n", strerror(errno));
        return;
    }
    buf[buf_head] = ret;
    buf_head = (buf_head + 1) % BUF_SIZE;
    if (buf_head == buf_tail) {
        buf_tail = (buf_tail + 1) % BUF_SIZE;
    }

    sum = 0;
    for (i = 0; i < BUF_SIZE; i++) {
        sum += buf[(buf_tail + i) % BUF_SIZE];
    }
    avg = sum / BUF_SIZE;

    clock_gettime(CLOCK_REALTIME, &ts);
    printf("%ld.%09ld: %d hPa\n", ts.tv_sec, ts.tv_nsec, ret);

    if (alert_triggered && abs(ret - avg) <= ALERT_THRESHOLD) {
        alert_triggered = 0;
        if (gpioSetMode(ALERT_GPIO, PI_INPUT) < 0) {
            fprintf(stderr, "Failed to reset GPIO: %s\n", strerror(errno));
        }
    } else if (!alert_triggered && abs(ret - avg) > ALERT_THRESHOLD) {
        alert_triggered = 1;
        if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO: %s\n", strerror(errno));
        }
    }
}

int main() {
    int i, ret;

    if (piGpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }

    buf = malloc(BUF_SIZE * sizeof(int));
    if (!buf) {
        fprintf(stderr, "Failed to allocate buffer: %s\n", strerror(errno));
        return 1;
    }

    for (i = 0; i < 22; i++) {
        if (i2cReadByteData(i2c_handle, CALIB_REG + i) < 0) {
            fprintf(stderr, "Failed to read calibration data: %s\n", strerror(errno));
            return 1;
        }
    }

    signal(SIGINT, handle_sigint);

    gpioSetTimerFuncEx(0, 50000, sample_func);

    while (1) {
        sleep(1);
    }

    return 0;
}

