#include <pigpio.h>

#define BMP180_I2C_BUS 1
#define BMP180_I2C_ADDR 0x77
#define BMP180_CAL_REG 0xAA
#define BMP180_CAL_LEN 22
#define BMP180_CTRL_REG 0xF4
#define BMP180_DATA_REG 0xF6
#define BMP180_OS_0 0

static int i2c_handle = -1;
static FILE *log_file = NULL;

void exit_handler(int signum) {
    if (i2c_handle != -1) {
        piI2C_close(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Exiting...\n");
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio.\n");
        return 1;
    }

    i2c_handle = piI2C_open(BMP180_I2C_BUS, BMP180_I2C_ADDR);
    if (i2c_handle < 0) {
        printf("Failed to open I2C handle: %d\n", i2c_handle);
        return 1;
    }

    log_file = fopen("bmp180_log.txt", "w");
    if (log_file == NULL) {
        printf("Failed to open log file.\n");
        return 1;
    }

    signal(SIGINT, exit_handler);
    signal(SIGTERM, exit_handler);

    char cal_data[BMP180_CAL_LEN];
    if (piI2C_read(i2c_handle, BMP180_CAL_REG, cal_data, BMP180_CAL_LEN) != BMP180_CAL_LEN) {
        printf("Failed to read calibration data.\n");
        return 1;
    }

    if (piI2C_writeByteData(i2c_handle, BMP180_CTRL_REG, BMP180_OS_0) < 0) {
        printf("Failed to set oversampling rate.\n");
        return 1;
    }

    while (1) {
        int16_t temp, press;
        if (piI2C_readWordData(i2c_handle, BMP180_DATA_REG, &temp) < 0 ||
            piI2C_readWordData(i2c_handle, BMP180_DATA_REG + 2, &press) < 0) {
            printf("Failed to read sensor data.\n");
            return 1;
        }

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s, %d, %d\n", timestamp, temp, press);
        fflush(log_file);

        sleep(500);
    }

    return 0;
}

