#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define GPIO 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"
#define MIN_TEMP 40000
#define MAX_TEMP 70000
#define PWM_FREQ 25000
#define PWM_DUTY_RANGE 255

FILE *log_file;
int pi;

void cleanup(int signum) {
    if (pigpio_write_pwm_duty(pi, GPIO, 0) != 0) {
        fprintf(stderr, "Failed to stop fan: %s\n", pigpio_error());
    }
    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Failed to close log file\n");
        }
    }
    if (pigpio_stop() != 0) {
        fprintf(stderr, "Failed to stop pigpio: %s\n", pigpio_error());
    }
    exit(0);
}

int main() {
    int temp, duty;
    struct timespec ts;
    char time_str[20];

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    pi = pigpio_start();
    if (pi < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        return 1;
    }

    if (pigpio_set_mode(pi, GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO mode: %s\n", pigpio_error());
        return 1;
    }

    if (pigpio_set_pwm_frequency(pi, GPIO, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency: %s\n", pigpio_error());
        return 1;
    }

    if (pigpio_set_pwm_range(pi, GPIO, PWM_DUTY_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range: %s\n", pigpio_error());
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    while (1) {
        FILE *temp_file = fopen(TEMP_FILE, "r");
        if (temp_file == NULL) {
            fprintf(stderr, "Failed to read temperature\n");
            return 1;
        }
        fscanf(temp_file, "%d", &temp);
        fclose(temp_file);

        duty = (temp - MIN_TEMP) * PWM_DUTY_RANGE / (MAX_TEMP - MIN_TEMP);
        if (duty < 0) {
            duty = 0;
        } else if (duty > PWM_DUTY_RANGE) {
            duty = PWM_DUTY_RANGE;
        }

        if (pigpio_write_pwm_duty(pi, GPIO, duty) != 0) {
            fprintf(stderr, "Failed to set PWM duty: %s\n", pigpio_error());
            return 1;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        if (fprintf(log_file, "%s, %d, %d\n", time_str, temp, duty) < 0) {
            fprintf(stderr, "Failed to write to log file\n");
            return 1;
        }

        fflush(log_file);

        sleep(5);
    }

    return 0;
}

