#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define I2C_FD_INVALID -1
#define GPIO_LINE_COUNT 1
#define GPIO_LINE_OFFSET 18
#define TEMP_REG 0x00
#define TEMP_THRESHOLD 28.0
#define BUF_SIZE 60

struct circular_buffer {
    double buf[BUF_SIZE];
    int head;
    int tail;
    int count;
};

struct context {
    int i2c_fd;
    struct gpiod_chip *gpio_chip;
    struct gpiod_line *gpio_line;
    struct circular_buffer cb;
    pthread_mutex_t mutex;
};

void cleanup(struct context *ctx) {
    if (ctx->i2c_fd != I2C_FD_INVALID) {
        close(ctx->i2c_fd);
    }
    if (ctx->gpio_line) {
        gpiod_line_release(ctx->gpio_line);
    }
    if (ctx->gpio_chip) {
        gpiod_chip_close(ctx->gpio_chip);
    }
    pthread_mutex_destroy(&ctx->mutex);
}

void handle_error(struct context *ctx, const char *msg) {
    fprintf(stderr, "%s: %s\n", msg, strerror(errno));
    cleanup(ctx);
    exit(EXIT_FAILURE);
}

void *acquire_data(void *arg) {
    struct context *ctx = arg;
    uint8_t buf[2];
    double avg = 0.0;

    while (1) {
        if (ioctl(ctx->i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
            handle_error(ctx, "Failed to set I2C slave address");
        }
        if (read(ctx->i2c_fd, buf, sizeof(buf)) != sizeof(buf)) {
            handle_error(ctx, "Failed to read temperature");
        }
        int16_t temp = (buf[0] << 8) | buf[1];
        temp >>= 5;
        double temp_c = (double)temp / 256.0;

        pthread_mutex_lock(&ctx->mutex);
        ctx->cb.buf[ctx->cb.head] = temp_c;
        ctx->cb.head = (ctx->cb.head + 1) % BUF_SIZE;
        if (ctx->cb.count < BUF_SIZE) {
            ctx->cb.count++;
        } else {
            ctx->cb.tail = (ctx->cb.tail + 1) % BUF_SIZE;
        }
        avg = 0.0;
        for (int i = 0; i < ctx->cb.count; i++) {
            avg += ctx->cb.buf[(ctx->cb.tail + i) % BUF_SIZE];
        }
        avg /= ctx->cb.count;

        gpiod_line_set_value(ctx->gpio_line, avg > TEMP_THRESHOLD);
        pthread_mutex_unlock(&ctx->mutex);

        sleep(1);
    }

    return NULL;
}

int main() {
    struct context ctx;
    memset(&ctx, 0, sizeof(ctx));
    ctx.i2c_fd = I2C_FD_INVALID;

    pthread_t thread;
    if (pthread_mutex_init(&ctx.mutex, NULL) != 0) {
        fprintf(stderr, "Failed to initialize mutex\n");
        exit(EXIT_FAILURE);
    }

    ctx.i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (ctx.i2c_fd == I2C_FD_INVALID) {
        handle_error(&ctx, "Failed to open I2C device");
    }

    ctx.gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!ctx.gpio_chip) {
        handle_error(&ctx, "Failed to open GPIO chip");
    }
    ctx.gpio_line = gpiod_chip_get_line(ctx.gpio_chip, GPIO_LINE_OFFSET);
    if (!ctx.gpio_line) {
        handle_error(&ctx, "Failed to get GPIO line");
    }
    if (gpiod_line_request_output(ctx.gpio_line, "temperature", 0) < 0) {
        handle_error(&ctx, "Failed to request GPIO line");
    }

    if (pthread_create(&thread, NULL, acquire_data, &ctx) != 0) {
        handle_error(&ctx, "Failed to create thread");
    }

    pthread_join(thread, NULL);

    cleanup(&ctx);

    return 0;
}

