#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <json.h>
#include <spi.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_MODE 1
#define SPI_DEVICE "/dev/spidev0.0"
#define MAX31865_CONFIG 0x80
#define MAX31865_REF_RESISTANCE 430
#define PT100_REF_RESISTANCE 100
#define FAILSAFE_TEMP 80
#define PWM_FREQ 1000
#define PWM_RANGE 1000
#define PWM_GPIO 18

static int spi_handle;
static int pigpio_handle;
static int pwm_duty;
static int target_temp;
static float Kp, Ki, Kd;

static void init_spi(void) {
    spi_handle = spiOpen(SPI_DEVICE, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(-spi_handle));
        exit(EXIT_FAILURE);
    }

    uint8_t config = 0xC1;
    uint8_t tx_buf[2] = {MAX31865_CONFIG, config};
    if (spiWrite(spi_handle, tx_buf, sizeof(tx_buf)) < 0) {
        fprintf(stderr, "Failed to write to SPI device: %s\n", strerror(-spi_handle));
        exit(EXIT_FAILURE);
    }
}

static void init_pigpio(void) {
    pigpio_handle = pigpio_start();
    if (pigpio_handle < 0) {
        fprintf(stderr, "Failed to start pigpio: %s\n", strerror(-pigpio_handle));
        exit(EXIT_FAILURE);
    }

    if (gpioSetPWMfrequency(PWM_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency: %s\n", strerror(-gpioHadError()));
        exit(EXIT_FAILURE);
    }

    if (gpioSetPWMrange(PWM_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range: %s\n", strerror(-gpioHadError()));
        exit(EXIT_FAILURE);
    }
}

static void read_config(void) {
    FILE *file = fopen("config.json", "r");
    if (!file) {
        fprintf(stderr, "Failed to open config file, using defaults\n");
        target_temp = 25;
        Kp = 1.0;
        Ki = 0.1;
        Kd = 0.01;
        return;
    }

    struct json_object *json = json_object_from_file("config.json");
    if (!json) {
        fprintf(stderr, "Failed to parse config file, using defaults\n");
        target_temp = 25;
        Kp = 1.0;
        Ki = 0.1;
        Kd = 0.01;
        return;
    }

    json_object_object_foreach(json, key, val) {
        if (!strcmp(key, "target_temp"))
            target_temp = json_object_get_int(val);
        else if (!strcmp(key, "Kp"))
            Kp = json_object_get_double(val);
        else if (!strcmp(key, "Ki"))
            Ki = json_object_get_double(val);
        else if (!strcmp(key, "Kd"))
            Kd = json_object_get_double(val);
    }

    json_object_put(json);
    fclose(file);
}

static void control_loop(void) {
    while (1) {
        uint8_t rx_buf[3] = {0};
        if (spiRead(spi_handle, rx_buf, sizeof(rx_buf)) < 0) {
            fprintf(stderr, "Failed to read from SPI device: %s\n", strerror(-spi_handle));
            exit(EXIT_FAILURE);
        }

        if (rx_buf[0] & 0x01) {
            fprintf(stderr, "RTD open-circuit fault\n");
            exit(EXIT_FAILURE);
        }

        int rtd_code = (rx_buf[0] << 8) | rx_buf[1];
        int rtd_resistance = (rtd_code / 32768.0) * MAX31865_REF_RESISTANCE;
        int temp = (rtd_resistance - PT100_REF_RESISTANCE) / 0.00385;

        if (temp > FAILSAFE_TEMP) {
            fprintf(stderr, "Temperature exceeds failsafe threshold\n");
            exit(EXIT_FAILURE);
        }

        int error = target_temp - temp;
        pwm_duty += Kp * error + Ki * error / 100 + Kd * (error - prev_error) / 100;
        prev_error = error;

        if (pwm_duty < 0)
            pwm_duty = 0;
        else if (pwm_duty > PWM_RANGE)
            pwm_duty = PWM_RANGE;

        if (gpioPWM(PWM_GPIO, pwm_duty) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle: %s\n", strerror(-gpioHadError()));
            exit(EXIT_FAILURE);
        }

        sleep(0.1);
    }
}

static void sig_handler(int signo) {
    gpioPWM(PWM_GPIO, 0);
    spiClose(spi_handle);
    pigpio_stop(pigpio_handle);
    exit(EXIT_SUCCESS);
}

int main(void) {
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    read_config();
    init_spi();
    init_pigpio();
    control_loop();

    return 0;
}

