        if (gpioPWM(PWM_GPIO, pwm_duty) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle: %s\n", strerror(-gpioHadError()));
            exit(EXIT_FAILURE);
        }

        sleep(0.1);
    }
}

static void sig_handler(int signo) {
    gpioPWM(PWM_GPIO, 0);
    spiClose(spi_handle);
    pigpio_stop(pigpio_handle);
    exit(EXIT_SUCCESS);
}

int main(void) {
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    read_config();
    init_spi();
    init_pigpio();
    control_loop();

    return 0;
}
