#define LOG_FILE_PATH "breach_log.txt"

static int i2c_file_descriptor;
static FILE *log_file;

static void cleanup_and_exit(int signal) {
    close(i2c_file_descriptor);
    fclose(log_file);
    exit(signal);
}

static int write_register(unsigned char reg, unsigned char cmd) {
    unsigned char buffer[2] = {reg, cmd};
    if (write(i2c_file_descriptor, buffer, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_register(unsigned char reg, unsigned char *value) {
    if (write_register(reg, 0) == -1)
        return -1;
    if (read(i2c_file_descriptor, value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_temperature() {
    if (write_register(BMP180_REG_CONTROL, BMP180_CMD_TEMP) == -1)
        return -1;
    usleep(4500);  // Wait for conversion
    unsigned char msb, lsb;
    if (read_register(BMP180_REG_TEMP, &msb) == -1)
        return -1;
    if (read_register(BMP1800_REG_TEMP + 1, &lsb) == -1)
        return -1;
    int32_t raw_temp = (msb << 8) | lsb;
    return (raw_temp * 7.62) / 13107;  // Calibration formula
}

static int read_pressure() {
    if (write_register(BMP180_REG_CONTROL, BMP180_CMD_PRESS) == -1)
        return -1;
    usleep(4500);  // Wait for conversion
    unsigned char msb, lsb, xlsb;
    if (read_register(BMP180_REG_PRESS, &msb) == -1)
        return -1;
    if (read_register(BMP180_REG_PRESS + 1, &lsb) == -1)
        return -1;
    if (read_register(BMP180_REG_PRESS + 2, &xlsb) == -1)
        return -1;
    int32_t raw_press = (msb << 16) | (lsb << 8) | xlsb;
    return (raw_press * 625) / 1048576;  // Calibration formula
}

int main() {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    i2c_file_descriptor = open(I2C_DEV_PATH, O_RDWR);
    if (i2c_file_descriptor == -1) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }
    if (ioctl(i2c_file_descriptor, I2C_SLAVE, BMP180_I2C_ADDR) == -1) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        return 1;
    }

    log_file = fopen(LOG_FILE_PATH, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    while (1) {
        int temperature = read_temperature();
        int pressure = read_pressure();
        if (temperature == -1 || pressure == -1) {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
            continue;
        }

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);

        if (temperature > TEMP_THRESHOLD || pressure < PRESSURE_THRESHOLD) {
            fprintf(log_file, "%s: Temperature = %d.00°C, Pressure = %d.00hPa\n", timestamp, temperature / 100, pressure / 100);
            fflush(log_file);
        }

        sleep(1);
    }

    return 0;
}

