#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <pigpiod_if.h>

#define BMP180_ADDR 0x77
#define BMP180_CALIB_ADDR 0xAA
#define BMP180_TEMP_ADDR 0x2E
#define BMP180_PRESS_ADDR 0x34
#define BMP180_OSS 0
#define FAN_GPIO 18
#define SAMPLE_INTERVAL_MS 500
#define MAX_READINGS 60

struct bmp180_calib {
    unsigned short ac1, ac2, ac3;
    unsigned short ac4, ac5, ac6;
    short b1, b2;
    short mb, mc, md;
};

struct bmp180_reading {
    struct timespec ts;
    int temp;
    unsigned long press;
};

struct bmp180_reading readings[MAX_READINGS];
int reading_idx = 0;
int i2c_handle = -1;
int fan_on = 0;

void handle_signal(int sig) {
    if (fan_on) {
        gpioWrite(FAN_GPIO, 0);
        fan_on = 0;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
    exit(0);
}

void sample_callback(int pi, unsigned gpio, unsigned level, int tick) {
    int16_t raw_temp, raw_press;
    struct bmp180_calib calib;
    int16_t b5;
    unsigned long p;
    int i2c_ret;

    i2c_ret = i2cWriteByteData(i2c_handle, BMP180_TEMP_ADDR);
    if (i2c_ret < 0) {
        printf("i2cWriteByteData(temp) failed: %d\n", i2c_ret);
        return;
    }
    i2c_ret = i2cRead(i2c_handle, &raw_temp, sizeof(raw_temp));
    if (i2c_ret < 0) {
        printf("i2cRead(temp) failed: %d\n", i2c_ret);
        return;
    }

    i2c_ret = i2cWriteByteData(i2c_handle, BMP180_PRESS_ADDR | (BMP180_OSS << 6));
    if (i2c_ret < 0) {
        printf("i2cWriteByteData(press) failed: %d\n", i2c_ret);
        return;
    }
    i2c_ret = i2cRead(i2c_handle, &raw_press, sizeof(raw_press));
    if (i2c_ret < 0) {
        printf("i2cRead(press) failed: %d\n", i2c_ret);
        return;
    }

    b5 = ((raw_temp - ((calib.ac6 << 8) >> 8)) * calib.ac5) >> 15;
    b5 = b5 - ((calib.mc << 11) / (b5 + calib.md));
    int32_t temp = ((b5 * 5 + 128) >> 8);
    p = ((unsigned long)calib.ac4 * ((unsigned long)raw_press - ((unsigned long)calib.ac3 << BMP180_OSS)) >> BMP180_OSS);
    p = p / (1 + ((long)((long)calib.b2 * ((long)b5 - (long)calib.ac6)) >> 12));
    b5 = (b5 + ((long)calib.b1 << 16)) / ((long)calib.ac1 + ((long)calib.ac2 * b5) / (1 << 15));
    p = p * (1 + ((long)b5 * calib.b3) / (1 << 31));

    readings[reading_idx].ts = *clock_gettime(CLOCK_REALTIME);
    readings[reading_idx].temp = temp;
    readings[reading_idx].press = p;
    reading_idx = (reading_idx + 1) % MAX_READINGS;

    printf("%ld.%09ld: Temp = %d.%02d°C, Pressure = %lu Pa\n",
           readings[reading_idx].ts.tv_sec, readings[reading_idx].ts.tv_nsec,
           readings[reading_idx].temp / 100, readings[reading_idx].temp % 100,
           readings[reading_idx].press);

    if (temp > 3000 && !fan_on) {
        gpioWrite(FAN_GPIO, 1);
        fan_on = 1;
    } else if (temp <= 3000 && fan_on) {
        gpioWrite(FAN_GPIO, 0);
        fan_on = 0;
    }
}

int main() {
    int i2c_ret;
    struct bmp180_calib calib;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpioInitialise() < 0) {
        printf("gpioInitialise failed\n");
        return 1;
    }
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    i2c_handle = i2cOpen("/dev/i2c-1", BMP180_ADDR);
    if (i2c_handle < 0) {
        printf("i2cOpen failed: %d\n", i2c_handle);
        return 1;
    }

    i2c_ret = i2cWriteByteData(i2c_handle, BMP180_CALIB_ADDR);
    if (i2c_ret < 0) {
        printf("i2cWriteByteData(calib) failed: %d\n", i2c_ret);
        return 1;
    }
    i2c_ret = i2cRead(i2c_handle, &calib, sizeof(calib));
    if (i2c_ret < 0) {
        printf("i2cRead(calib) failed: %d\n", i2c_ret);
        return 1;
    }

    gpioHardwareTimer(1, SAMPLE_INTERVAL_MS);
    gpioSetISRFunc(1, PI_INT_EDGE_RISING, 0, sample_callback);

    while (1) {
        sleep(1);
    }

    return 0;
}

