#define GPIO_TRIGGER 27
#define DEBOUNCE_TIME 200
#define LOG_INTERVAL 2

static int i2c_file = -1;
static int pi_handle = -1;
static int log_enabled = 0;

static void cleanup_and_exit(int sig) {
    if (i2c_file >= 0) close(i2c_file);
    if (pi_handle >= 0) {
        gpioTerminate();
    }
    exit(sig);
}

static void handle_trigger(int gpio, int level, uint32_t tick) {
    log_enabled = !log_enabled;
}

