    int ret;
    struct sigaction action;
    struct bmp180_calib_data {
        unsigned short AC1, AC2, AC3;
        unsigned short AC4, AC5, AC6;
        short B1, B2;
        short MB, MC, MD;
    } cal_data;
    FILE *log_file;
    unsigned short raw_pressure;
    int pressure;
    time_t last_log_time = 0;

    action.sa_handler = cleanup_and_exit;
    action.sa_flags = 0;
    sigemptyset(&action.sa_mask);
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    pi_handle = gpioInitialise();
    if (pi_handle < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %d\n", pi_handle);
        cleanup_and_exit(-1);
    }

    ret = gpioSetEdgeDetection(GPIO_TRIGGER, PI_EITHER_EDGE);
    if (ret < 0) {
        fprintf(stderr, "Failed to set edge detection: %d\n", ret);
        cleanup_and_exit(-1);
    }

    ret = gpioDebounceTimeout(GPIO_TRIGGER, DEBOUNCE_TIME);
    if (ret < 0) {
        fprintf(stderr, "Failed to set debounce timeout: %d\n", ret);
        cleanup_and_exit(-1);
    }

    ret = gpioCallback(GPIO_TRIGGER, PI_EITHER_EDGE, handle_trigger, NULL);
    if (ret < 0) {
        fprintf(stderr, "Failed to set trigger callback: %d\n", ret);
        cleanup_and_exit(-1);
    }

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file < 0) {
        fprintf(stderr, "Failed to open I2C device file\n");
        cleanup_and_exit(-1);
    }

    ret = ioctl(i2c_file, I2C_SLAVE, BMP180_I2C_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %d\n", ret);
        cleanup_and_exit(-1);
    }

    log_file = fopen("pressure_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup_and_exit(-1);
    }

    while (1) {
        if (log_enabled && time(NULL) - last_log_time >= LOG_INTERVAL) {
            ret = read(i2c_file, &cal_data, sizeof(cal_data));
            if (ret != sizeof(cal_data)) {
                fprintf(stderr, "Failed to read calibration data: %d\n", ret);
                cleanup_and_exit(-1);
            }

            ret = write(i2c_file, &BMP180_CAL_START, 1);
            if (ret != 1) {
                fprintf(stderr, "Failed to write command: %d\n", ret);
                cleanup_and_exit(-1);
            }

            ret = read(i2c_file, &raw_pressure, 2);
            if (ret != 2) {
                fprintf(stderr, "Failed to read pressure data: %d\n", ret);
                cleanup_and_exit(-1);
            }

            pressure = ...;  // Compute pressure using Bosch formulas with cal_data

            fprintf(log_file, "%ld,%d\n", time(NULL), pressure);
            fflush(log_file);
            last_log_time = time(NULL);
        }
    }

    return 0;
}
