#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <spi.h>

#define GPIO_RELAY 17
#define GPIO_CS 8
#define GPIO_MISO 9
#define GPIO_MOSI 10
#define GPIO_SCLK 11
#define MAX_DUTY_CYCLE 800000
#define TARGET_TEMP 25.0
#define LOG_FILE "heater_log.csv"

FILE *log_file;
double target_temp = TARGET_TEMP;
int duty_cycle = 0;
int pi;

void shutdown_handler(int signum) {
    spiClose(pi);
    fclose(log_file);
    gpioWrite(GPIO_RELAY, 0);
    gpioTerminate();
    exit(0);
}

void log_temp(double temp, int duty_cycle) {
    time_t now = time(0);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp)-1] = 0;  // remove trailing newline
    fprintf(log_file, "%s,%.2f,%d\n", timestamp, temp, duty_cycle);
}

void control_loop() {
    int spi_handle;
    uint8_t tx_buf[5] = {0x00, 0x00, 0x00, 0x00, 0x00};
    uint8_t rx_buf[5];
    double temp;
    int error, p, i, u;

    signal(SIGINT, shutdown_handler);
    signal(SIGTERM, shutdown_handler);

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        exit(1);
    }

    spi_handle = spiOpen(GPIO_CS, GPIO_MISO, GPIO_MOSI, GPIO_SCLK, 2000000, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI: %d\n", spi_handle);
        exit(1);
    }

    while (1) {
        spiXfer(spi_handle, tx_buf, rx_buf, 5);
        if (rx_buf[0] & 0x80) {
            fprintf(stderr, "MAX31855 error\n");
            log_temp(0, 0);
            duty_cycle = 0;
        } else {
            temp = ((rx_buf[1] << 12) | (rx_buf[2] << 4) | (rx_buf[3] >> 4)) * 0.0625;
            error = target_temp - temp;
            p = error;
            i = error;
            u = p + i;
            if (u > MAX_DUTY_CYCLE) u = MAX_DUTY_CYCLE;
            if (u < 0) u = 0;
            duty_cycle = u;
            log_temp(temp, duty_cycle);
        }
        gpioWrite(GPIO_RELAY, duty_cycle > 0);
        delay(1000);
    }
}

int main() {
    pi = gpioInitialise();
    if (pi < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %d\n", pi);
        exit(1);
    }

    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioSetMode(GPIO_CS, PI_OUTPUT);
    gpioSetMode(GPIO_MISO, PI_INPUT);
    gpioSetMode(GPIO_MOSI, PI_OUTPUT);
    gpioSetMode(GPIO_SCLK, PI_OUTPUT);

    control_loop();

    gpioTerminate();
    return 0;
}

