#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <pigpio.h>

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    int fd, ret, r, g, b;
    char buf[16];
    unsigned long temp;
    struct sigaction action;

    action.sa_handler = signal_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;

    if (sigaction(SIGINT, &action, NULL) == -1 || sigaction(SIGTERM, &action, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "gpioInitialise failed: %d\n", ret);
        return 1;
    }

    gpioSetPWMrange(17, 255);
    gpioSetPWMrange(18, 255);
    gpioSetPWMrange(27, 255);

    fd = open("/sys/class/thermal/thermal_zone0/temp", O_RDONLY);
    if (fd == -1) {
        perror("open");
        return 1;
    }

    while (!stop) {
        if (read(fd, buf, sizeof(buf)) <= 0) {
            perror("read");
            close(fd);
            gpioTerminate();
            return 1;
        }

        temp = strtoul(buf, NULL, 10);
        printf("Temperature: %lu m°C\n", temp);

        if (temp < 40000) {
            r = 0;
            g = 0;
            b = 255;
        } else if (temp < 60000) {
            r = 0;
            g = 255;
            b = 0;
        } else {
            r = 255;
            g = 0;
            b = 0;
        }

        printf("RGB: %d,%d,%d\n", r, g, b);

        gpioPWM(17, 255 - r);
        gpioPWM(18, 255 - g);
        gpioPWM(27, 255 - b);

        sleep(500);
    }

    gpioPWM(17, 255);
    gpioPWM(18, 255);
    gpioPWM(27, 255);

    close(fd);
    gpioTerminate();

    return 0;
}

