#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <curl/curl.h>
#include <pigpio.h>

#define GPIO_DATA 4
#define MAX_RETRIES 3

struct curl_slist *headers = NULL;
CURL *curl;

void setup_curl() {
    curl = curl_easy_init();
    if(curl) {
        headers = curl_slist_append(headers, "Content-Type: application/json");
    }
}

void post_data(float humidity, float temperature) {
    char postdata[100];
    snprintf(postdata, sizeof(postdata), "{\"humidity\":%.2f,\"temperature\":%.2f}", humidity, temperature);

    curl_easy_setopt(curl, CURLOPT_URL, "http://yourserver.com/api/humidity");
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, postdata);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

    CURLcode res = curl_easy_perform(curl);
    if(res != CURLE_OK)
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
}

void cleanup() {
    if(curl)
        curl_easy_cleanup(curl);
    if(headers)
        curl_slist_free_all(headers);
    gpioTerminate();
    exit(0);
}

void handle_signal(int signum) {
    cleanup();
}

int main() {
    int pi = gpioInitialise();
    if(pi < 0) {
        fprintf(stderr, "gpioInitialise() failed: %s\n", gpioStrerror(pi));
        return 1;
    }

    gpioSetMode(GPIO_DATA, PI_INPUT);
    gpioSetPullUpDown(GPIO_DATA, PI_PUD_UP);

    setup_curl();

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int retry = 0;
    while(1) {
        // Send start signal
        gpioSetMode(GPIO_DATA, PI_OUTPUT);
        gpioWrite(GPIO_DATA, 0);
        usleep(2000);
        gpioSetMode(GPIO_DATA, PI_INPUT);

        // Read response
        int bit, val = 0, count = 0;
        for(int i = 0; i < 40; i++) {
            bit = gpioRead(GPIO_DATA);
            usleep(50);
            bit = gpioRead(GPIO_DATA);
            usleep(50);
            if(bit == 0)
                continue;
            val |= (bit << count);
            count++;
        }

        // Parse data
        int humidity = (val >> 20) & 0xFF;
        int temperature = (val >> 12) & 0xFF;
        int checksum = val & 0xFF;
        if(humidity + temperature != checksum) {
            fprintf(stderr, "Checksum error\n");
            if(retry++ < MAX_RETRIES)
                continue;
            else
                return 1;
        }

        // Post data
        post_data(humidity, temperature);

        retry = 0;
        sleep(60);
    }

    cleanup();
    return 0;
}

