#include <pigpiod_if.h>

#define BMP180_ADDR 0x77
#define BMP180_CAL_START 0xAA
#define BMP180_CAL_END 0xBE
#define BMP180_CONTROL 0xF4
#define BMP180_DATA 0xF6
#define BMP180_OSS 3
#define LOG_FILE "pressure_log.txt"
#define DEBOUNCE_TIME 200000

FILE *log_file;
int logging = 0;
int i2c_handle;

void cleanup(int signum) {
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cUnwrite(i2c_handle);
    piGpioInitialise();
    exit(0);
}

void isr(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    if (tick - last_tick < DEBOUNCE_TIME) return;
    last_tick = tick;
    logging = !logging;
    printf("Logging is now %s\n", logging ? "enabled" : "disabled");
}

int main() {
    signal(SIGINT, cleanup);

    int ret = piGpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "piGpioInitialise failed with error %d\n", ret);
        return 1;
    }

    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed with error %d\n", i2c_handle);
        cleanup(0);
    }

    int16_t cal[22];
    for (int i = BMP180_CAL_START; i <= BMP180_CAL_END; i++) {
        ret = i2cReadWordMode1(i2c_handle, i, &cal[i - BMP180_CAL_START]);
        if (ret < 0) {
            fprintf(stderr, "i2cReadWordMode1 failed with error %d\n", ret);
            cleanup(0);
        }
    }

    ret = gpioSetMode(4, PI_INPUT);
    if (ret < 0) {
        fprintf(stderr, "gpioSetMode failed with error %d\n", ret);
        cleanup(0);
    }

    ret = gpioSetPullUpDown(4, PI_PUD_UP);
    if (ret < 0) {
        fprintf(stderr, "gpioSetPullUpDown failed with error %d\n", ret);
        cleanup(0);
    }

    ret = gpioSetISRFunc(4, PI_FALLING_EDGE, isr);
    if (ret < 0) {
        fprintf(stderr, "gpioSetISRFunc failed with error %d\n", ret);
        cleanup(0);
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen");
        cleanup(0);
    }

    while (1) {
        usleep(2000000);
        if (!logging) {
            printf("Logging is disabled\n");
            continue;
        }

        ret = i2cWriteByte(i2c_handle, BMP180_CONTROL);
        if (ret < 0) {
            fprintf(stderr, "i2cWriteByte failed with error %d\n", ret);
            cleanup(0);
        }

        usleep(26000);

        int16_t pressure;
        ret = i2cReadWordMode1(i2c_handle, BMP180_DATA, &pressure);
        if (ret < 0) {
            fprintf(stderr, "i2cReadWordMode1 failed with error %d\n", ret);
            cleanup(0);
        }

        time_t t = time(NULL);
        struct tm *tm = localtime(&t);
        char buf[80];
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tm);

        fprintf(log_file, "%s: %.2f hPa\n", buf, pressure / 100.0);
        fflush(log_file);
    }

    return 0;
}
