#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <curl/curl.h>
#include <pigpio.h>

#define GPIO 4
#define MAX_RETRIES 3
#define POST_URL "http://your-server.com/api/humidity"

static char *post_url = POST_URL;
static int pi_handle;
static int retry_count = 0;

static void handle_sig(int sig) {
    gpioTerminate();
    curl_global_cleanup();
    exit(0);
}

static size_t writefunc(void *ptr, size_t size, size_t nmemb, void *stream) {
    return size * nmemb;
}

static int read_dht22(void) {
    int i, j, k, l, data[5] = {0, 0, 0, 0, 0};
    int bits[40] = {0};

    gpioWrite(GPIO, 0);
    delay(1000);
    gpioWrite(GPIO, 1);
    delay(20);
    gpioSetPullUpDown(GPIO, PI_PUD_UP);

    for (i = 0; i < 40; i++) {
        j = gpioRead(GPIO);
        while (gpioRead(GPIO) == j) {
            k++;
        }
        if (i == 0 && k > 2000) {
            return -1;
        }
        if (k > 50) {
            bits[i] = 1;
        }
    }

    for (i = 0; i < 40; i++) {
        data[i / 8] = (data[i / 8] << 1) | bits[i];
    }

    if (data[0] != 0 || data[3] != 0 || (data[1] + data[2] + data[3] + data[4]) != data[0]) {
        return -1;
    }

    return data[2];
}

static int post_humidity(int humidity) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;
    char postdata[32];

    snprintf(postdata, sizeof(postdata), "{\"humidity\":%d}", humidity);

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, post_url);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, postdata);
        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writefunc);
        res = curl_easy_perform(curl);
        curl_easy_cleanup(curl);
        if (res != CURLE_OK) {
            syslog(LOG_ERR, "curl error: %s", curl_easy_strerror(res));
            return -1;
        }
    } else {
        syslog(LOG_ERR, "curl init failed");
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    int humidity;

    openlog("dht22", LOG_PERROR, LOG_USER);
    signal(SIGINT, handle_sig);
    signal(SIGTERM, handle_sig);

    if (argc > 1 && strcmp(argv[1], "-s") == 0 && argc > 2) {
        post_url = argv[2];
    }

    pi_handle = gpioInitialise();
    if (pi_handle < 0) {
        syslog(LOG_ERR, "gpioInitialise failed: %s", pigpio_error_text(pi_handle));
        return -1;
    }

    while (1) {
        humidity = read_dht22();
        if (humidity < 0) {
            syslog(LOG_ERR, "read_dht22 failed");
            if (retry_count < MAX_RETRIES) {
                retry_count++;
                sleep(2);
                continue;
            }
            return -1;
        }

        if (post_humidity(humidity) < 0) {
            if (retry_count < MAX_RETRIES) {
                retry_count++;
                sleep(2);
                continue;
            }
            return -1;
        }

        retry_count = 0;
        sleep(10);
    }

    return 0;
}

