#include <time.h>

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define MAX_STATE_FILE "/sys/class/thermal/cooling_device0/max_state"
#define LOG_FILE "/var/log/fan_control.log"

int max_state = 3;
int current_state = -1;
int fd_temp, fd_fan, fd_log;

void sighandler(int signum) {
    if (current_state != 0) {
        dprintf(fd_fan, "0\n");
        current_state = 0;
        time_t t = time(NULL);
        char* time_str = ctime(&t);
        dprintf(fd_log, "%s Fan set to state 0 (off)\n", time_str);
    }
    exit(0);
}

int main() {
    fd_temp = open(TEMP_FILE, O_RDONLY);
    fd_fan = open(FAN_FILE, O_WRONLY);
    fd_log = open(LOG_FILE, O_WRONLY | O_APPEND);
    int fd_max = open(MAX_STATE_FILE, O_RDONLY);
    if (fd_max != -1) {
        char buf[2];
        if (read(fd_max, buf, 1) != -1) {
            max_state = atoi(buf);
        }
        close(fd_max);
    }
    if (fd_temp == -1 || fd_fan == -1 || fd_log == -1) {
        perror("open");
        return 1;
    }
    signal(SIGINT, sighandler);
    signal(SIGTERM, sighandler);
    while (1) {
        char buf[5];
        int n = read(fd_temp, buf, 4);
        if (n == -1) {
            perror("read");
            continue;
        }
        buf[n] = '\0';
        int temp = atoi(buf);
        int state;
        if (temp < 45000) {
            state = 0;
        } else if (temp < 55000) {
            state = 1;
        } else if (temp < 65000) {
            state = 2;
        } else {
            state = 3;
        }
        if (state > max_state) {
            state = max_state;
        }
        if (state != current_state) {
            dprintf(fd_fan, "%d\n", state);
            current_state = state;
            time_t t = time(NULL);
            char* time_str = ctime(&t);
            dprintf(fd_log, "%s Fan set to state %d\n", time_str, state);
        }
        sleep(5);
    }
    return 0;
}

