#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define I2C_RETRIES 3

static int i2c_handle1 = -1;
static int i2c_handle2 = -1;
static FILE *log_file = NULL;

static void cleanup_and_exit(int sig) {
    if (i2c_handle1 != -1) {
        piI2C_close(i2c_handle1);
    }
    if (i2c_handle2 != -1) {
        piI2C_close(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (gpioInitialise() >= 0) {
        gpioTerminate();
    }
    exit(sig);
}

static int validate_crc8(const char *data, int len) {
    static const char crc8_table[16] = {0, 7, 14, 9, 28, 27, 18, 21, 56, 63, 54, 49, 36, 35, 42, 45};
    char crc = 0;
    for (int i = 0; i < len; i++) {
        crc = crc8_table[((crc >> 4) ^ data[i]) & 0xf] ^ (crc << 4);
        crc = crc8_table[((crc >> 4) ^ (data[i] >> 4)) & 0xf] ^ (crc << 4);
    }
    return crc == 0;
}

static void log_flow_rate(int sensor_addr, int raw_value) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    double flow_rate = raw_value * 0.01;
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%.2f\n",
            timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
            timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec,
            sensor_addr == SENSOR1_ADDR ? flow_rate : -1.0);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("flow_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    i2c_handle1 = piI2C_open(I2C_BUS, SENSOR1_ADDR, 0);
    i2c_handle2 = piI2C_open(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle1 < 0 || i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C handle.\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    char cmd[2] = {0x36, 0x08};
    char data[3];
    while (1) {
        for (int retry = 0; retry < I2C_RETRIES; retry++) {
            if (piI2C_writeRead(i2c_handle1, cmd, sizeof(cmd), data, sizeof(data)) == sizeof(data)
                    && validate_crc8(data, sizeof(data))) {
                log_flow_rate(SENSOR1_ADDR, (data[0] << 8) | data[1]);
                break;
            }
            if (retry == I2C_RETRIES - 1) {
                fprintf(stderr, "Failed to read from sensor 1.\n");
            }
            usleep(10000);  // 10 ms
        }

        for (int retry = 0; retry < I2C_RETRIES; retry++) {
            if (piI2C_writeRead(i2c_handle2, cmd, sizeof(cmd), data, sizeof(data)) == sizeof(data)
                    && validate_crc8(data, sizeof(data))) {
                log_flow_rate(SENSOR2_ADDR, (data[0] << 8) | data[1]);
                break;
            }
            if (retry == I2C_RETRIES - 1) {
                fprintf(stderr, "Failed to read from sensor 2.\n");
            }
            usleep(10000);  // 10 ms
        }

        sleep(1);
    }

    return EXIT_SUCCESS;
}

