#include <pigpio.h>

#define GPIO_A 17
#define GPIO_B 18

FILE *log_file;

int state = 0;
int position = 0;

void encoder_handler(int gpio, int level, uint32_t tick) {
    int new_state;

    if (gpio == GPIO_A) {
        new_state = level ? 1 : 0;
    } else if (gpio == GPIO_B) {
        new_state = level ? 2 : 0;
    } else {
        return;
    }

    state = (state & 3) | new_state;

    switch (state) {
        case 0:
        case 3:
        case 5:
        case 6:
            position++;
            break;
        case 1:
        case 2:
        case 4:
            position--;
            break;
    }

    if (position < 0) {
        position += 360;
    } else if (position >= 360) {
        position -= 360;
    }

    if (log_file) {
        fprintf(log_file, "%ld,%d\n", tick, position);
    }
}

void cleanup(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("encoder_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    gpioSetPullUpDown(GPIO_A, PI_PUD_UP);
    gpioSetPullUpDown(GPIO_B, PI_PUD_UP);

    gpioSetISRFunc(GPIO_A, PI_RISING_EDGE, 0, encoder_handler);
    gpioSetISRFunc(GPIO_B, PI_RISING_EDGE, 0, encoder_handler);

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        sleep(1);
    }

    return EXIT_SUCCESS;
}

