#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>
#include <time.h>

#define ADPD144RI_ADDR 0x39
#define ADPD144RI_FIFO_REG 0x60
#define ADPD144RI_IR_THRESHOLD 2000
#define GPIO_LED 17
#define I2C_BUS 1
#define LOG_FILE "adpd144ri_log.txt"

static struct gpiod_line *gpio_led;
static int i2c_fd;
static FILE *log_file;
static volatile sig_atomic_t stop;

static void cleanup_and_exit(int sig) {
    if (gpio_led)
        gpiod_line_release(gpio_led);
    if (i2c_fd > 0)
        close(i2c_fd);
    if (log_file)
        fclose(log_file);
    exit(sig);
}

static void handle_sig(int sig) {
    stop = 1;
}

int main() {
    struct gpiod_chip *gpio_chip;
    struct timespec ts;
    unsigned int ir_data, red_data;
    char log_line[100];

    gpio_chip = gpiod_chip_open_by_name("/dev/gpiochip0");
    if (!gpio_chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    gpio_led = gpiod_chip_get_line(gpio_chip, GPIO_LED);
    if (!gpio_led) {
        perror("gpiod_chip_get_line");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(gpio_led, "led_owner", 0)) {
        perror("gpiod_line_request_output");
        return EXIT_FAILURE;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_ADDR)) {
        perror("ioctl");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sig);
    signal(SIGTERM, handle_sig);

    atexit(cleanup_and_exit);

    while (!stop) {
        if (read(i2c_fd, &ir_data, sizeof(ir_data)) != sizeof(ir_data)) {
            perror("read");
            return EXIT_FAILURE;
        }

        if (ir_data > ADPD144RI_IR_THRESHOLD)
            gpiod_line_set_value(gpio_led, 1);
        else
            gpiod_line_set_value(gpio_led, 0);

        clock_gettime(CLOCK_REALTIME, &ts);
        sprintf(log_line, "%ld,%u,%u\n", ts.tv_sec, red_data, ir_data);
        fputs(log_line, log_file);
        fflush(log_file);

        usleep(100000);
    }

    return EXIT_SUCCESS;
}

