#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

pthread_mutex_t pulse_mutex;
unsigned long long pulse_count = 0;
FILE *log_file;

void isr(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

void signal_handler(int signum) {
    gpioTerminate();
    fclose(log_file);
    pthread_mutex_destroy(&pulse_mutex);
    exit(0);
}

int main() {
    int pi = gpioInitialise();
    if (pi < 0) {
        printf("Error initializing pigpio: %d\n", pi);
        return 1;
    }

    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        printf("Error initializing mutex\n");
        return 1;
    }

    log_file = fopen("rpm_log.txt", "a");
    if (log_file == NULL) {
        printf("Error opening log file\n");
        return 1;
    }

    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = signal_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    gpioSetISRFunc(18, 1, 0, isr);

    while (1) {
        sleep(1);
        pthread_mutex_lock(&pulse_mutex);
        unsigned long long pulses = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double rpm = pulses ? (double)pulses / 60.0 : 0.00;
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s: %.2f RPM\n", timestamp, rpm);
        fflush(log_file);
    }

    return 0;
}

