    if (!gpio_led) {
        perror("Failed to get GPIO line");
        cleanup_and_exit(-1);
    }
    ret = gpiod_line_request_output(gpio_led, "led", 0);
    if (ret) {
        perror("Failed to request GPIO line");
        cleanup_and_exit(-1);
    }

