    while (1) {
        // Read FIFO data
        buf[0] = ADPD144RI_FIFO_DATA_LOW;
        ret = write(i2c_file, buf, 1);
        if (ret != 1) {
            perror("Failed to write to I2C device");
            cleanup_and_exit(-1);
        }
        ret = read(i2c_file, &buf, 4);
        if (ret != 4) {
            perror("Failed to read from I2C device");
            cleanup_and_exit(-1);
        }
        red = (buf[0] << 8) | buf[1];
        ir = (buf[2] << 8) | buf[3];

        // Trigger LED if IR reading exceeds threshold
        if (ir > ADPD144RI_IR_THRESHOLD)
            gpiod_line_set_value(gpio_led, 1);
        else
            gpiod_line_set_value(gpio_led, 0);

        // Log timestamped readings
        fprintf(log_file, "%ld,%hu,%hu\n", time(NULL), red, ir);
        fflush(log_file);

        // Sleep for 100 ms
        usleep(100000);
    }

    return 0;
}

