    signal(SIGTERM, sig_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line_in = gpiod_chip_get_line(chip, 17);
    if (!line_in) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    ret = gpiod_line_request_rising_edge_events(line_in, "audio_detector");
    if (ret) {
        perror("gpiod_line_request_rising_edge_events");
        return 1;
    }

    line_out = gpiod_chip_get_line(chip, 18);
    if (!line_out) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    ret = gpiod_line_request_output(line_out, "gain_control", 0);
    if (ret) {
        perror("gpiod_line_request_output");
        return 1;
    }

    log_file = fopen("audio_log.txt", "w");
