    while (1) {
        ret = gpiod_line_event_wait(line_in, &ts);
        if (ret < 0) {
            perror("gpiod_line_event_wait");
            return 1;
        }

        timeinfo = localtime(&ts.tv_sec);
        strftime(buffer, 26, "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s LEVEL 1\n", buffer);
        fflush(log_file);
    }

    return 0;
}

