#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x36
#define I2C_CMD 0x3608

#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL 0xFF

FILE *log_file;
int i2c_handle;

void sigint_handler(int signum) {
    piI2C_close(i2c_handle);
    fclose(log_file);
    piStop();
    exit(0);
}

unsigned char crc8(const unsigned char *data, int length) {
    unsigned char crc = CRC8_INITIAL;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (piInit() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    i2c_handle = piI2C_open(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }

    unsigned char cmd[2] = {I2C_CMD >> 8, I2C_CMD & 0xFF};
    if (piI2C_write(i2c_handle, cmd, 2) < 0) {
        fprintf(stderr, "Failed to write to I2C device\n");
        return 1;
    }

    log_file = fopen("flow_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    unsigned char data[3];
    while (1) {
        usleep(1000000);

        if (piI2C_read(i2c_handle, data, 3) < 0) {
            fprintf(stderr, "Failed to read from I2C device\n");
            continue;
        }

        if (crc8(data, 2) != data[2]) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        int16_t raw_flow = (data[0] << 8) | data[1];
        double flow_rate = (double)raw_flow / 1000.0;

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        char now_str[20];
        strftime(now_str, sizeof(now_str), "%Y-%m-%d %H:%M:%S", now_tm);

        fprintf(log_file, "%s,%.3f\n", now_str, flow_rate);
        fflush(log_file);
    }

    return 0;
}

