#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x70

static int i2c_handle = -1;
static FILE *log_file = NULL;

void sigint_handler(int signum) {
    if (i2c_handle != -1) {
        piI2C_close(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (gpioInitialise() >= 0) {
        gpioTerminate();
    }
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio.\n");
        return 1;
    }

    i2c_handle = piI2C_open(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("air_quality_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        piI2C_close(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        unsigned char buffer[7];
        int result = piI2C_readDev(i2c_handle, 0x00, sizeof(buffer), buffer);
        if (result < 0) {
            fprintf(stderr, "Failed to read sensor state: %d\n", result);
            continue;
        }

        int tvoc = (buffer[1] << 8) | buffer[2];
        int eco2 = (buffer[5] << 8) | buffer[6];
        float iaq = 100 - (tvoc / 10.0) - ((eco2 - 400) / 50.0);
        if (iaq < 0) iaq = 0;
        if (iaq > 100) iaq = 100;

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);

        fprintf(log_file, "%s,%d,%d,%.2f\n", timestamp, (int)iaq, tvoc, eco2);
        fflush(log_file);

        sleep(5);
    }

    return 0;
}

