#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>

#define GPIOCHIP_NAME "gpiochip0"
#define GPIO_LINE 17
#define CONSUMER_LABEL "ttp223_tamper"
#define POLL_INTERVAL_MS 100
#define INTRUSION_TIMEOUT_SEC 5

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int intrusion_detected = 0;

void cleanup_and_exit(int signum)
{
    printf("Exiting...\n");
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    exit(signum);
}

int main(void)
{
    struct timespec ts_start, ts_now;
    int64_t elapsed_time_sec;

    chip = gpiod_chip_open_by_name(GPIOCHIP_NAME);
    if (!chip) {
        printf("Failed to open %s: %s\n", GPIOCHIP_NAME, strerror(errno));
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        printf("Failed to get line %d: %s\n", GPIO_LINE, strerror(errno));
        cleanup_and_exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(line, CONSUMER_LABEL)) {
        printf("Failed to request line as input: %s\n", strerror(errno));
        cleanup_and_exit(EXIT_FAILURE);
    }

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    clock_gettime(CLOCK_MONOTONIC, &ts_start);

    while (1) {
        int val = gpiod_line_get_value(line);

        if (val < 0) {
            printf("Failed to read line value: %s\n", strerror(errno));
            cleanup_and_exit(EXIT_FAILURE);
        }

        clock_gettime(CLOCK_MONOTONIC, &ts_now);
        elapsed_time_sec = ts_now.tv_sec - ts_start.tv_sec;

        if (val && !intrusion_detected && elapsed_time_sec >= INTRUSION_TIMEOUT_SEC) {
            printf("Intrusion detected!\n");
            intrusion_detected = 1;
        } else if (!val && intrusion_detected) {
            ts_start = ts_now;
            intrusion_detected = 0;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    return 0;
}

