#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/types.h>
#include <linux/i2s.h>
#include <gpiod.h>
#include <alsa/asoundlib.h>

#define PCM_DEVICE "hw:0,0"
#define PCM_CHANNELS 2
#define PCM_RATE 48000
#define PCM_FORMAT SND_PCM_FORMAT_S16_LE
#define PCM_FILE "audio_capture.pcm"
#define GPIO_PATH "/dev/gpiochip0"
#define GPIO_LINE 17

struct gpiod_line *gpio_line;
snd_pcm_t *pcm_handle;
FILE *pcm_file;

void cleanup_and_exit(int sig) {
    if (gpio_line)
        gpiod_line_release(gpio_line);
    if (pcm_handle)
        snd_pcm_close(pcm_handle);
    if (pcm_file)
        fclose(pcm_file);
    exit(sig);
}

int main() {
    int ret;
    struct gpiod_chip *gpio_chip;
    struct snd_i2s_config i2s_config = { .flags = I2S_F_ENABLE };

    // Open GPIO line
    gpio_chip = gpiod_chip_open(GPIO_PATH);
    if (!gpio_chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return -1;
    }
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_LINE);
    if (!gpio_line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        return -1;
    }
    ret = gpiod_line_request_output(gpio_line, "audio_capture", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line\n");
        return -1;
    }

    // Open PCM device
    ret = snd_pcm_open(&pcm_handle, PCM_DEVICE, SND_PCM_STREAM_CAPTURE, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to open PCM device: %s\n", snd_strerror(ret));
        return -1;
    }
    ret = snd_pcm_set_params(pcm_handle, PCM_FORMAT, SND_PCM_ACCESS_RW_INTERLEAVED, PCM_CHANNELS, PCM_RATE, 1, 500000);
    if (ret < 0) {
        fprintf(stderr, "Failed to set PCM parameters: %s\n", snd_strerror(ret));
        return -1;
    }

    // Open PCM file
    pcm_file = fopen(PCM_FILE, "wb");
    if (!pcm_file) {
        fprintf(stderr, "Failed to open PCM file\n");
        return -1;
    }

    // Configure I2S
    ret = ioctl(open("/dev/i2s", O_RDWR), SNDRV_I2S_IOCTL_CONFIG, &i2s_config);
    if (ret < 0) {
        fprintf(stderr, "Failed to configure I2S\n");
        return -1;
    }

    // Handle signals to clean up resources
    signal(SIGINT, cleanup_and_exit);

    // Continuously read from PCM device and write to file
    while (1) {
        short buffer[PCM_CHANNELS * PCM_RATE];
        ret = snd_pcm_readi(pcm_handle, buffer, PCM_CHANNELS * PCM_RATE);
        if (ret < 0) {
            fprintf(stderr, "Failed to read from PCM device: %s\n", snd_strerror(ret));
            cleanup_and_exit(-1);
        }
        for (int i = 0; i < ret; i++) {
            // Right-shift 24-bit data to 16-bit
            buffer[i] >>= 8;
        }
        ret = fwrite(buffer, sizeof(short), PCM_CHANNELS * PCM_RATE, pcm_file);
        if (ret < PCM_CHANNELS * PCM_RATE) {
            fprintf(stderr, "Failed to write to PCM file\n");
            cleanup_and_exit(-1);
        }
    }

    return 0;
}

