#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_PIN 4
#define FAN_PIN 18
#define POLL_INTERVAL_MS 50
#define DEBOUNCE_INTERVAL_MS 50
#define FAN_FREQ 100
#define FAN_MAX_DUTY 8000
#define SENSOR_TIMEOUT_MS 2000

volatile int sensor_state = -1;
volatile int sensor_timeout = 0;
volatile int fan_duty = 0;
volatile int pigpio_initialized = 0;

FILE *log_file;

void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
    fprintf(log_file, "%s %s\n", timestamp, event);
    fflush(log_file);
}

void handle_signal(int signum) {
    if (pigpio_initialized) {
        gpioHardwarePWM(FAN_PIN, 0, 0);
        gpioSetMode(FAN_PIN, PI_INPUT);
        gpioTerminate();
    }
    fclose(log_file);
    exit(signum);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    log_file = fopen("flame_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    int pi = pigpio_start(NULL, NULL);
    if (pi < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }
    pigpio_initialized = 1;

    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PIN, PI_OUTPUT);

    log_event("System start");

    while (1) {
        int sensor_value = gpioRead(SENSOR_PIN);
        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read sensor\n");
            return 1;
        }

        if (sensor_value == 0 && sensor_state != 0) {
            sensor_state = 0;
            sensor_timeout = 0;
            log_event("Flame detected");
        } else if (sensor_value == 1 && sensor_state != 1) {
            sensor_state = 1;
            gpioHardwarePWM(FAN_PIN, FAN_FREQ, 0);
            log_event("Flame ended");
        }

        if (sensor_state == 0) {
            sensor_timeout += POLL_INTERVAL_MS;
            if (sensor_timeout >= SENSOR_TIMEOUT_MS) {
                sensor_state = -1;
                log_event("Sensor absent");
            } else {
                fan_duty = (int)(FAN_MAX_DUTY * (1.0 - exp(-sensor_timeout / 1000.0)));
                gpioHardwarePWM(FAN_PIN, FAN_FREQ, fan_duty);
            }
        }

        sleep_ms(POLL_INTERVAL_MS);
    }

    return 0;
}

