#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define GPIO_TRIGGER 23
#define GPIO_READY 24
#define GPIO_COUNT 256
#define CHIRP_COUNT 64
#define FILE_NAME "heatmap.log"

FILE *file;
int spi_handle;

struct config {
    uint32_t magic;
    uint64_t timestamp;
    uint32_t start_freq;
    uint32_t end_freq;
    uint16_t chirps;
    uint16_t samples;
    uint16_t frame_period;
} config = {
    .magic = 0x52444144,
    .start_freq = 77000,
    .end_freq = 79000,
    .chirps = CHIRP_COUNT,
    .samples = GPIO_COUNT,
    .frame_period = 100,
};

void sig_handler(int signo) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    if (file != NULL) {
        fclose(file);
    }
    exit(signo);
}

int main() {
    if (gpioInitialise() < 0) {
        printf("Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_TRIGGER, PI_OUTPUT);
    gpioSetMode(GPIO_READY, PI_INPUT);
    gpioSetISRFunc(GPIO_READY, PI_RisingEdge, 0, NULL);

    spi_handle = spiOpen("/dev/spidev0.0", SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        printf("Failed to open SPI device\n");
        return EXIT_FAILURE;
    }

    file = fopen(FILE_NAME, "wb");
    if (file == NULL) {
        printf("Failed to open file for writing\n");
        return EXIT_FAILURE;
    }

    fwrite(&config, sizeof(config), 1, file);

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    uint8_t *data = malloc(GPIO_COUNT * sizeof(uint8_t));
    if (data == NULL) {
        printf("Failed to allocate memory\n");
        return EXIT_FAILURE;
    }

    uint64_t frame_number = 0;
    while (1) {
        gpioWrite(GPIO_TRIGGER, 1);
        gpioWaitForLevel(GPIO_READY, 0);
        gpioWrite(GPIO_TRIGGER, 0);

        spiXfer(spi_handle, data, data, GPIO_COUNT);

        fwrite(&frame_number, sizeof(frame_number), 1, file);
        fwrite(data, GPIO_COUNT * sizeof(uint8_t), 1, file);

        frame_number++;
    }

    free(data);
    fclose(file);
    spiClose(spi_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

