#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define OPT3001_ADDR 0x44
#define OPT3001_REG_CONFIG 0x01
#define OPT3001_REG_LOW_LIMIT 0x02
#define OPT3001_REG_HIGH_LIMIT 0x03
#define OPT3001_REG_RESULT 0x00

#define OPT3001_CONTINUOUS_CONV_MODE 0x4000
#define OPT3001_100MS_CONV_TIME 0x0

FILE *file;
int i2c_handle;

void sig_handler(int signo) {
    if (file) fclose(file);
    if (i2c_handle >= 0) piI2C_close(i2c_handle);
    piStop();
    exit(signo);
}

int main() {
    struct sigaction action;
    action.sa_handler = sig_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    if (piGpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio library\n");
        return EXIT_FAILURE;
    }

    i2c_handle = piI2C_open(1, OPT3001_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return EXIT_FAILURE;
    }

    if (piI2C_write16(i2c_handle, OPT3001_REG_CONFIG, OPT3001_CONTINUOUS_CONV_MODE | OPT3001_100MS_CONV_TIME) < 0) {
        fprintf(stderr, "Error writing to sensor\n");
        return EXIT_FAILURE;
    }

    file = fopen("light_data.txt", "w");
    if (!file) {
        fprintf(stderr, "Error opening file\n");
        return EXIT_FAILURE;
    }

    while (1) {
        int result;
        if (piI2C_read16(i2c_handle, OPT3001_REG_RESULT, &result) < 0) {
            fprintf(stderr, "Error reading from sensor\n");
            continue;
        }

        int exponent = (result >> 12) & 0xF;
        int mantissa = result & 0xFFF;
        double lux = 0.01 * (1 << exponent) * mantissa;

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

        fprintf(file, "%s: %.2f lux\n", timestamp, lux);
        fflush(file);
    }

    return EXIT_SUCCESS;
}

