#define GPIO_LINE 17

struct gpiod_line *line;
struct gpiod_chip *chip;
struct gpiod_line_request *req;
struct gpiod_line_settings settings;
struct gpiod_line_config line_config;
struct gpiod_request_config req_config;

sig_atomic_t stop = 0;

void sigint_handler(int signum) {
    stop = 1;
}

int main() {
    struct sigaction action;
    action.sa_handler = sigint_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    if (sigaction(SIGINT, &action, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto err_chip_close;
    }

    memset(&settings, 0, sizeof(settings));
    settings.type = GPIOD_LINE_TYPE_INPUT;
    settings.bias = GPIOD_LINE_BIAS_PULL_UP;
    if (gpiod_line_set_config(line, &settings) < 0) {
        perror("gpiod_line_set_config");
        goto err_line_close;
    }

    memset(&line_config, 0, sizeof(line_config));
    line_config.flags = GPIOD_LINE_FLAG_BIAS_PULL_UP;

    memset(&req_config, 0, sizeof(req_config));
    req_config.consumer = "Flame Detector";

    req = gpiod_line_request_by_offset(chip, GPIO_LINE, &req_config, &line_config);
    if (!req) {
        perror("gpiod_line_request_by_offset");
        goto err_line_close;
    }

    while (!stop) {
        int value = gpiod_line_request_get_value(req);
        if (value < 0) {
            perror("gpiod_line_request_get_value");
            break;
        }

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        printf("[%s] Flame Detected: %s\n", timestamp, value ? "NO" : "YES");
        sleep(1);
    }

    gpiod_line_release(req);
err_line_close:
    gpiod_chip_close(chip);
err_chip_close:
    return EXIT_SUCCESS;
}

