    int left_gpio = 17, center_gpio = 18, right_gpio = 27;
    int left_val, center_val, right_val;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

