        gpioSetMode(center_gpio, PI_INPUT) < 0 ||
        gpioSetMode(right_gpio, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (!stop) {
        left_val = gpioRead(left_gpio);
        center_val = gpioRead(center_gpio);
        right_val = gpioRead(right_gpio);

        if (left_val < 0 || center_val < 0 || right_val < 0) {
            fprintf(stderr, "Failed to read GPIO\n");
            gpioTerminate();
            return EXIT_FAILURE;
        }

        printf("Left: %d, Center: %d, Right: %d\n", left_val, center_val, right_val);

        usleep(50000);
    }

    gpioTerminate();

    return EXIT_SUCCESS;
