#include <assert.h>
#include <errno.h>
#include <gpiod.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

#define CHIP_NAME "gpiochip0"
#define LINE_OFFSETS {2, 3, 4, 5, 6, 7, 8, 9}
#define LINE_COUNT (sizeof(LINE_OFFSETS) / sizeof(LINE_OFFSETS[0]))
#define POLL_TIMEOUT_MS 100

struct gpiod_chip *chip;
struct gpiod_line *lines[LINE_COUNT];
int running;

void cleanup_and_exit(int sig) {
    running = 0;

    for (size_t i = 0; i < LINE_COUNT; i++) {
        gpiod_line_release(lines[i]);
    }

    gpiod_chip_close(chip);

    if (sig == SIGINT) {
        printf("\nShutdown on SIGINT\n");
        exit(EXIT_SUCCESS);
    }
}

int main() {
    signal(SIGINT, cleanup_and_exit);

    chip = gpiod_chip_open(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open chip %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < LINE_COUNT; i++) {
        lines[i] = gpiod_chip_get_line(chip, LINE_OFFSETS[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %zu: %s\n", LINE_OFFSETS[i], strerror(errno));
            return EXIT_FAILURE;
        }

        int ret = gpiod_line_request_input(lines[i], "touch-sensor");
        if (ret < 0) {
            fprintf(stderr, "Failed to request line %zu: %s\n", LINE_OFFSETS[i], strerror(errno));
            return EXIT_FAILURE;
        }
    }

    running = 1;

    while (running) {
        for (size_t i = 0; i < LINE_COUNT; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                fprintf(stderr, "Failed to get value for line %zu: %s\n", LINE_OFFSETS[i], strerror(errno));
                return EXIT_FAILURE;
            }

            printf("Line %zu: %d\n", LINE_OFFSETS[i], value);
        }

        usleep(POLL_TIMEOUT_MS * 1000);
    }

    cleanup_and_exit(0);
}

