#include <stdio.h>
#include <stdlib.h>
#include <libgpiod.h>
#include <time.h>
#include <signal.h>

#define NUM_GPIO_LINES 8
#define GPIO_LINES {2, 3, 4, 17, 27, 22, 10, 9}

struct gpiod_line *gpio_lines[NUM_GPIO_LINES];
struct gpiod_chip *gpio_chip;
int should_exit = 0;

void sigint_handler(int signum) {
    should_exit = 1;
}

int main() {
    struct timespec ts = {.tv_sec = 0, .tv_nsec = 50000000}; // 50 ms
    struct sigaction act;
    int i, ret;

    // Set up signal handler for graceful shutdown
    act.sa_handler = sigint_handler;
    sigemptyset(&act.sa_mask);
    act.sa_flags = 0;
    sigaction(SIGINT, &act, NULL);

    // Open the GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request each GPIO line
    for (i = 0; i < NUM_GPIO_LINES; i++) {
        gpio_lines[i] = gpiod_chip_get_line(gpio_chip, GPIO_LINES[i]);
        if (!gpio_lines[i]) {
            perror("Failed to get GPIO line");
            ret = EXIT_FAILURE;
            goto release_lines;
        }

        ret = gpiod_line_request_input(gpio_lines[i], "touch_sensor", 0);
        if (ret < 0) {
            perror("Failed to request GPIO line");
            goto release_lines;
        }
    }

    // Main loop
    while (!should_exit) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        printf("%d-%02d-%02dT%02d:%02d:%02d,", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec);

        for (i = 0; i < NUM_GPIO_LINES; i++) {
            ret = gpiod_line_get_value(gpio_lines[i]);
            if (ret < 0) {
                perror("Failed to get GPIO line value");
                goto release_lines;
            }
            printf("%d,", ret);
        }
        printf("\n");

        nanosleep(&ts, NULL);
    }

    ret = EXIT_SUCCESS;

release_lines:
    // Release all GPIO lines
    for (i = 0; i < NUM_GPIO_LINES; i++) {
        if (gpio_lines[i])
            gpiod_line_release(gpio_lines[i]);
    }

    // Close the GPIO chip
    if (gpio_chip)
        gpiod_chip_close(gpio_chip);

    return ret;
}

