#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

volatile sig_atomic_t run = 1;

void sigint_handler(int signum) {
    run = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(4, PI_INPUT)) {
        fprintf(stderr, "Failed to set GPIO mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(4, PI_PULL_UP)) {
        fprintf(stderr, "Failed to set pull-up resistor.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    printf("Starting tilt sensor poll loop...\n");

    int prev_state = -1;

    while (run) {
        int state = gpioRead(4);

        if (state < 0) {
            fprintf(stderr, "Failed to read GPIO.\n");
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (state != prev_state) {
            time_t t = time(NULL);
            struct tm* tm = localtime(&t);
            char buf[80];
            strftime(buf, sizeof(buf), "%c", tm);

            printf("[%s] Tilt state changed to: ", buf);

            if (state == 0) {
                printf("Tilted\n");
            } else {
                printf("Not Tilted\n");
            }

            fflush(stdout);

            prev_state = state;
        }

        usleep(100000);
    }

    gpioTerminate();

    printf("Exiting...\n");

    return EXIT_SUCCESS;
}

