#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_ADDR 0x60
#define PART_ID_REG 0x00
#define PART_ID_VAL 0x45
#define HW_KEY_REG 0x10
#define HW_KEY_VAL 0x17
#define CHLIST_REG 0x01
#define CHLIST_VAL 0x01
#define ALS_FORCE_CMD 0x06
#define UV_INDEX_REG 0x72
#define ALS_VISIBLE_REG 0x74

FILE *log_file;

void cleanup_and_exit(int sig) {
    if (log_file) fclose(log_file);
    piI2C_close(1);
    printf("Exiting...\n");
    exit(sig);
}

int main() {
    if (gpioInitialise() < 0) {
        printf("Error initializing GPIO\n");
        return 1;
    }

    if (piI2C_open(1) < 0) {
        printf("Error opening I2C bus\n");
        cleanup_and_exit(1);
    }

    if (piI2C_write(1, SENSOR_ADDR, PART_ID_REG, 1) < 0) {
        printf("Error reading PART ID\n");
        cleanup_and_exit(1);
    }

    int part_id = piI2C_read(1, SENSOR_ADDR, 1);
    if (part_id != PART_ID_VAL) {
        printf("Invalid PART ID: 0x%x\n", part_id);
        cleanup_and_exit(1);
    }

    if (piI2C_write(1, SENSOR_ADDR, HW_KEY_REG, HW_KEY_VAL) < 0) {
        printf("Error writing HW_KEY\n");
        cleanup_and_exit(1);
    }

    if (piI2C_write(1, SENSOR_ADDR, CHLIST_REG, CHLIST_VAL) < 0) {
        printf("Error writing CHLIST\n");
        cleanup_and_exit(1);
    }

    log_file = fopen("uv_als_log.csv", "w");
    if (!log_file) {
        printf("Error opening log file\n");
        cleanup_and_exit(1);
    }
    fprintf(log_file, "timestamp,uv_index,als_visible\n");

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    while (1) {
        if (piI2C_write(1, SENSOR_ADDR, ALS_FORCE_CMD, 1) < 0) {
            printf("Error triggering measurements\n");
            cleanup_and_exit(1);
        }

        sleep(1);

        if (piI2C_write(1, SENSOR_ADDR, UV_INDEX_REG, 1) < 0) {
            printf("Error reading UV index\n");
            cleanup_and_exit(1);
        }
        int uv_index = piI2C_read(1, SENSOR_ADDR, 1);

        if (piI2C_write(1, SENSOR_ADDR, ALS_VISIBLE_REG, 1) < 0) {
            printf("Error reading ALS visible\n");
            cleanup_and_exit(1);
        }
        int als_visible = piI2C_read(1, SENSOR_ADDR, 1);

        time_t t = time(NULL);
        struct tm *tm = localtime(&t);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        printf("UV index: %d, ALS visible: %d\n", uv_index, als_visible);
        fprintf(log_file, "%s,%d,%d\n", timestamp, uv_index, als_visible);
        fflush(log_file);
    }

    cleanup_and_exit(0);
}

