static int i2c_file_descriptor1, i2c_file_descriptor2, gpio_line_fd;
static FILE *log_file;
static volatile sig_atomic_t stop;

static void cleanup(void) {
    fclose(log_file);
    close(i2c_file_descriptor1);
    close(i2c_file_descriptor2);
    gpiod_line_release(gpio_line_fd);
    exit(0);
}

static void signal_handler(int signum) {
    stop = 1;
}

static int crc8(const unsigned char *data, int length) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static void read_sensor(int i2c_file_descriptor, int addr) {
