#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define BUF_SIZE 100

struct reading {
    struct timespec ts;
    int value;
};

struct reading buffer[BUF_SIZE];
int buffer_head = 0;
int buffer_tail = 0;

void handle_interrupt(int signum) {
    int i;
    for (i = 0; i != BUF_SIZE; i++) {
        printf("%ld.%.9ld: %d\n", buffer[i].ts.tv_sec, buffer[i].ts.tv_nsec, buffer[i].value);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    int pi;
    struct timespec ts;
    struct sigaction action;

    pi = gpioInitialise();
    if (pi < 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", gpioStrerror(pi));
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    action.sa_handler = handle_interrupt;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);

    while (1) {
        if (gpioRead(GPIO_PIN) == 0) {
            clock_gettime(CLOCK_REALTIME, &ts);
            buffer[buffer_head].ts = ts;
            buffer[buffer_head].value = 0;
            buffer_head = (buffer_head + 1) % BUF_SIZE;
            if (buffer_head == buffer_tail) {
                buffer_tail = (buffer_tail + 1) % BUF_SIZE;
            }
            printf("Obstacle detected\n");
        }
        sleep_ms(50);
    }

    gpioTerminate();
    return 0;
}

