#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEV "/dev/i2c-1"
#define SENSOR_ADDR 0x55
#define MODE_CONTROL 0x1D
#define STATUS_REG 0x1B
#define ACCEL_X_L 0x2A
#define ACCEL_X_H 0x2B
#define ACCEL_Y_L 0x2C
#define ACCEL_Y_H 0x2D
#define ACCEL_Z_L 0x2E
#define ACCEL_Z_H 0x2F
#define SCALE_FACTOR 0.0009765625
#define CSV_FILE "fan_health.csv"

static int i2c_fd = -1;
static FILE *csv_file = NULL;

static void write_csv(unsigned short x, unsigned short y, unsigned short z) {
    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", local_time);
    fprintf(csv_file, "%s,%u,%u,%u\n", timestamp, x, y, z);
    fflush(csv_file);
}

static void sig_handler(int signum) {
    if (i2c_fd != -1) close(i2c_fd);
    if (csv_file != NULL) fclose(csv_file);
    exit(signum);
}

int main() {
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) == -1) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    if (write(i2c_fd, &MODE_CONTROL, 1) != 1 ||
        write(i2c_fd, "\x10", 1) != 1) {
        perror("write");
        exit(EXIT_FAILURE);
    }

    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    if (ftell(csv_file) == 0) {
        fprintf(csv_file, "timestamp,x,y,z\n");
    }

    unsigned char buf[2];
    while (1) {
        usleep(500000);

        if (write(i2c_fd, &STATUS_REG, 1) != 1 ||
            read(i2c_fd, buf, 1) != 1 ||
            buf[0] & 1 == 0) {
            continue;
        }

        unsigned short x, y, z;
        if (write(i2c_fd, &ACCEL_X_L, 1) != 1 ||
            read(i2c_fd, buf, 2) != 2 ||
            sscanf(buf, "%hu", &x) != 1 ||
            write(i2c_fd, &ACCEL_Y_L, 1) != 1 ||
            read(i2c_fd, buf, 2) != 2 ||
            sscanf(buf, "%hu", &y) != 1 ||
            write(i2c_fd, &ACCEL_Z_L, 1) != 1 ||
            read(i2c_fd, buf, 2) != 2 ||
            sscanf(buf, "%hu", &z) != 1) {
            continue;
        }

        write_csv(x * SCALE_FACTOR, y * SCALE_FACTOR, z * SCALE_FACTOR);
    }

    return 0;
}

