#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x0E
#define DEVICE_ID_REG 0x00
#define EXPECTED_DEVICE_ID 0x8D
#define CSV_FILE "magnetic_log.csv"
#define SLEEP_TIME 100

static int i2c_handle = -1;
static FILE *csv_file = NULL;

static void write_csv_header(void) {
    fprintf(csv_file, "timestamp,x_field,y_field,z_field\n");
    fflush(csv_file);
}

static void write_csv_data(int x, int y, int z) {
    time_t now = time(NULL);
    struct tm *ts = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", ts);
    fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(csv_file);
}

static void handle_sig(int sig) {
    if (i2c_handle >= 0) {
        i2cUnwrite(i2c_handle);
        i2cClose(i2c_handle);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
    exit(0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device.\n");
        return EXIT_FAILURE;
    }

    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file.\n");
        return EXIT_FAILURE;
    }

    if (ftell(csv_file) == 0) {
        write_csv_header();
    }

    signal(SIGINT, handle_sig);
    signal(SIGTERM, handle_sig);

    while (1) {
        int device_id = i2cReadWord(i2c_handle, DEVICE_ID_REG);
        if (device_id < 0) {
            fprintf(stderr, "Failed to read device ID.\n");
            continue;
        }
        if (device_id != EXPECTED_DEVICE_ID) {
            fprintf(stderr, "Unexpected device ID.\n");
            continue;
        }

        int x_field = i2cReadWord(i2c_handle, 0x01);
        int y_field = i2cReadWord(i2c_handle, 0x03);
        int z_field = i2cReadWord(i2c_handle, 0x05);
        if (x_field < 0 || y_field < 0 || z_field < 0) {
            fprintf(stderr, "Failed to read magnetic field data.\n");
            continue;
        }

        // Convert raw 16-bit two's-complement values to mT for 50 mT range.
        x_field = (x_field > 32767) ? x_field - 65536 : x_field;
        y_field = (y_field > 32767) ? y_field - 65536 : y_field;
        z_field = (z_field > 32767) ? z_field - 65536 : z_field;
        x_field *= 50.0 / 32768.0;
        y_field *= 50.0 / 32768.0;
        z_field *= 50.0 / 32768.0;

        write_csv_data(x_field, y_field, z_field);

        usleep(SLEEP_TIME * 1000);
    }

    return EXIT_SUCCESS;
}

