#define INIT_RETRY_INTERVAL_S 60

FILE *log_file = NULL;
int pi_handle = 0;

void write_log(const char *msg) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d %s\n",
            tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
            tm->tm_hour, tm->tm_min, tm->tm_sec, msg);
    fflush(log_file);
}

void sig_handler(int signo) {
    if (pi_handle > 0) {
        gpioTerminate();
    }
    fclose(log_file);
    exit(signo);
}

int main() {
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    log_file = fopen("flood_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    while (1) {
        if (pi_handle <= 0) {
            pi_handle = gpioInitialise();
            if (pi_handle <= 0) {
                write_log("Failed to initialize pigpio");
                sleep(INIT_RETRY_INTERVAL_S);
                continue;
            }
            gpioSetPullUpDown(GPIO_SEN0193, PI_PUD_DOWN);
            gpioSetEdgeDetection(GPIO_SEN0193, PI_EITHER_EDGE);
        }

        int level = gpioRead(GPIO_SEN0193);
        if (level < 0) {
            write_log("Failed to read GPIO");
            gpioTerminate();
            pi_handle = 0;
            sleep(INIT_RETRY_INTERVAL_S);
            continue;
        }

        if (level > 0) {
            write_log("ALERT: Water detected");
        }

        sleep(POLL_INTERVAL_MS / 1000);
    }

    return EXIT_SUCCESS;
}

