#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <signal.h>
#include <stdatomic.h>

#define GPIO_HALL_SENSOR 4
#define LOG_FILE "rpm_log.txt"

volatile sig_atomic_t stop = 0;
atomic_int pulse_count = 0;
FILE *log_file;

void handle_signal(int signum) {
    stop = 1;
}

void count_pulse(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        atomic_fetch_add(&pulse_count, 1);
    }
}

void log_rpm(int timer) {
    if (stop) {
        fclose(log_file);
        gpioTerminate();
        exit(0);
    }

    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    int rpm = atomic_exchange(&pulse_count, 0) * 60;
    printf("%s %d\n", timestamp, rpm);

    if (fprintf(log_file, "%s %d\n", timestamp, rpm) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        exit(1);
    }

    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio\n");
        exit(1);
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        exit(1);
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    gpioSetPullUpDown(GPIO_HALL_SENSOR, PI_PUD_UP);
    gpioSetAlertFunc(GPIO_HALL_SENSOR, NULL, count_pulse);

    gpioSetTimerFunc(0, 1000000, log_rpm);

    while (1) {
        sleep(1);
    }

    return 0;
}

