#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <pthread.h>

#define GPIO_A 17
#define GPIO_B 27

typedef enum {
    STATE_IDLE,
    STATE_RISING_A,
    STATE_FALLING_A,
    STATE_RISING_B,
    STATE_FALLING_B
} state_t;

typedef struct {
    state_t state;
    int direction;
    FILE *log_file;
    pthread_mutex_t lock;
} context_t;

context_t context;

void log_rotation(int direction) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        exit(EXIT_FAILURE);
    }

    struct tm *timeinfo = localtime(&ts.tv_sec);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(context.log_file, "%s.%03ld: %s\n", timestamp, ts.tv_nsec / 1000000, direction ? "CW" : "CCW");
    fflush(context.log_file);
}

void isr_a(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&context.lock);

    if (level == 1) {
        context.state = (context.state == STATE_FALLING_A) ? STATE_RISING_B : STATE_RISING_A;
    } else {
        context.state = (context.state == STATE_RISING_A) ? STATE_FALLING_B : STATE_FALLING_A;
    }

    pthread_mutex_unlock(&context.lock);
}

void isr_b(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&context.lock);

    if (level == 1) {
        context.direction = (context.state == STATE_FALLING_A) ? 1 : 0;
        context.state = STATE_RISING_A;
    } else {
        context.direction = (context.state == STATE_RISING_A) ? 1 : 0;
        context.state = STATE_FALLING_A;
    }

    log_rotation(context.direction);

    pthread_mutex_unlock(&context.lock);
}

void signal_handler(int signum) {
    pthread_mutex_lock(&context.lock);
    fclose(context.log_file);
    gpioTerminate();
    exit(0);
}

int main() {
    if (pigpio_start() == PI_INIT_FAILED) {
        fprintf(stderr, "Failed to start pigpio\n");
        return EXIT_FAILURE;
    }

    context.state = STATE_IDLE;
    context.log_file = fopen("rotation_log.txt", "w");
    if (context.log_file == NULL) {
        perror("fopen");
        return EXIT_FAILURE;
    }

    if (pthread_mutex_init(&context.lock, NULL) != 0) {
        perror("pthread_mutex_init");
        return EXIT_FAILURE;
    }

    gpioSetPullUpDown(GPIO_A, PI_PUD_UP);
    gpioSetPullUpDown(GPIO_B, PI_PUD_UP);

    gpioSetAlertFunc(GPIO_A, isr_a);
    gpioSetAlertFunc(GPIO_B, isr_b);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        sleep(1);
    }

    return 0;
}

