    openlog("touch_sensor", LOG_PID, LOG_USER);

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    chip = gpiod_chip_open(CHIP_NAME);
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        cleanup_and_exit(-1);
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_GPIO);
    if (!sensor_line) {
        syslog(LOG_ERR, "Failed to get sensor line");
        cleanup_and_exit(-1);
