#include <assert.h>
#include <errno.h>
#include <gpiod.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

#define GPIO_CHIP "gpiochip0"
#define TOUCH_SENSOR_LINE 17
#define LED_LINE 18

struct gpiod_line *led_line;
struct gpiod_chip *chip;
struct gpiod_line_request *led_request;
struct gpiod_line_request *touch_request;

void sig_handler(int signum)
{
    gpiod_line_release(led_request);
    gpiod_line_release(touch_request);
    gpiod_chip_close(chip);
    exit(0);
}

int main()
{
    int ret;
    struct gpiod_line *line;
    struct gpiod_line_event event;

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s\n", GPIO_CHIP);
        return errno;
    }

    line = gpiod_chip_get_line(chip, LED_LINE);
    led_line = line;
    led_request = gpiod_line_request_output(line, "led", 0);
    if (!led_request) {
        fprintf(stderr, "Failed to request LED line\n");
        ret = errno;
        goto err_close_chip;
    }

    line = gpiod_chip_get_line(chip, TOUCH_SENSOR_LINE);
    touch_request = gpiod_line_request_input_events(line, "touch sensor");
    if (!touch_request) {
        fprintf(stderr, "Failed to request touch sensor line\n");
        ret = errno;
        goto err_release_led;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        ret = gpiod_line_event_wait(line, NULL);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for event\n");
            goto err_release_touch;
        } else if (ret == 0) {
            continue;
        }

        ret = gpiod_line_event_read(line, &event);
        if (ret < 0) {
            fprintf(stderr, "Failed to read event\n");
            goto err_release_touch;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            int led_value = gpiod_line_get_value(led_line);
            gpiod_line_set_value(led_line, !led_value);
        }
    }

err_release_touch:
    gpiod_line_release(touch_request);
err_release_led:
    gpiod_line_release(led_request);
err_close_chip:
    gpiod_chip_close(chip);

    return ret;
}

