#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR1 4
#define SENSOR2 17
#define LED1 27
#define LED2 22
#define POLL_INTERVAL 50 // in ms
#define BUF_SIZE 100

volatile sig_atomic_t stop = 0;

struct event {
    int sensor;
    time_t timestamp;
    int state;
};

struct event buffer[BUF_SIZE];
int head = 0, tail = 0, overflow = 0;

void log_event(int sensor, int state) {
    if ((tail + 1) % BUF_SIZE == head) {
        overflow++;
        tail = (tail + 1) % BUF_SIZE;
    }
    buffer[tail].sensor = sensor;
    buffer[tail].timestamp = time(NULL);
    buffer[tail].state = state;
    tail = (tail + 1) % BUF_SIZE;
}

void handle_sig(int sig) {
    stop = 1;
}

void cleanup() {
    gpioWrite(LED1, 0);
    gpioWrite(LED2, 0);
    gpioTerminate();
    for (int i = 0; i < BUF_SIZE; i++) {
        printf("Sensor: %d, Timestamp: %ld, State: %d\n", buffer[i].sensor, buffer[i].timestamp, buffer[i].state);
    }
    printf("Overflow count: %d\n", overflow);
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(SENSOR1, PI_INPUT) < 0 || gpioSetMode(SENSOR2, PI_INPUT) < 0 ||
        gpioSetMode(LED1, PI_OUTPUT) < 0 || gpioSetMode(LED2, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        return 1;
    }

    signal(SIGINT, handle_sig);
    signal(SIGTERM, handle_sig);

    int prev_state1 = gpioRead(SENSOR1);
    int prev_state2 = gpioRead(SENSOR2);

    while (!stop) {
        int state1 = gpioRead(SENSOR1);
        int state2 = gpioRead(SENSOR2);

        if (state1 != prev_state1) {
            log_event(SENSOR1, state1);
            gpioWrite(LED1, state1);
            prev_state1 = state1;
        }

        if (state2 != prev_state2) {
            log_event(SENSOR2, state2);
            gpioWrite(LED2, state2);
            prev_state2 = state2;
        }

        sleep(POLL_INTERVAL / 1000.0);
    }

    cleanup();
    return 0;
}

