#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_RAIN_SENSOR 17
#define LOG_FILE "/var/log/rain_events.log"

FILE *log_file;
int pi;
int prev_state = -1;

void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d: %s\n",
            timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
            timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec, event);
    fflush(log_file);
}

void handle_signal(int signum) {
    if (prev_state != -1) {
        pigpio_close(pi);
    }
    fclose(log_file);
    exit(signum);
}

int main() {
    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        exit(EXIT_FAILURE);
    }

    if ((pi = pigpio_start()) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    if (gpio_set_mode(pi, GPIO_RAIN_SENSOR, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        pigpio_close(pi);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    if (gpio_set_pull_up_down(pi, GPIO_RAIN_SENSOR, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor\n");
        pigpio_close(pi);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        int state = gpio_read(pi, GPIO_RAIN_SENSOR);
        if (state < 0) {
            fprintf(stderr, "Failed to read GPIO\n");
            pigpio_close(pi);
            fclose(log_file);
            exit(EXIT_FAILURE);
        }

        if (state != prev_state) {
            prev_state = state;
            log_event(state == 0 ? "Rain Detected" : "No Rain");
        }

        sleep(500);
    }

    return 0;
}

