#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_SENSOR1 17
#define GPIO_SENSOR2 18
#define DEBOUNCE_TIME 5
#define LOG_FILE "shaft_log.txt"

volatile int sensor1_state = -1;
volatile int sensor2_state = -1;
volatile int running = 1;

FILE *log_file;

void handle_sigint(int signum) {
    running = 0;
}

void log_state_change(int state1, int state2) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: log file not open\n");
        return;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(log_file, "%ld.%09ld,%d,%d\n", ts.tv_sec, ts.tv_nsec, state1, state2);
}

void sensor1_callback(int gpio, int level, uint32_t tick) {
    if (level == sensor1_state) return;
    sensor1_state = level;
    log_state_change(sensor1_state, sensor2_state);
}

void sensor2_callback(int gpio, int level, uint32_t tick) {
    if (level == sensor2_state) return;
    sensor2_state = level;
    log_state_change(sensor1_state, sensor2_state);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: unable to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error: unable to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    gpioSetDebounce(GPIO_SENSOR1, DEBOUNCE_TIME);
    gpioSetDebounce(GPIO_SENSOR2, DEBOUNCE_TIME);

    gpioCallback(GPIO_SENSOR1, PI_EITHER_EDGE, sensor1_callback);
    gpioCallback(GPIO_SENSOR2, PI_EITHER_EDGE, sensor2_callback);

    while (running) {
        sleep(1);
    }

    fclose(log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}

