        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    gpioSetDebounce(GPIO_SENSOR1, DEBOUNCE_TIME);
    gpioSetDebounce(GPIO_SENSOR2, DEBOUNCE_TIME);

    gpioCallback(GPIO_SENSOR1, PI_EITHER_EDGE, sensor1_callback);
    gpioCallback(GPIO_SENSOR2, PI_EITHER_EDGE, sensor2_callback);

    while (running) {
        sleep(1);
    }

    fclose(log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}
```

This code initializes the GPIO, sets up the sensor callbacks, and enters a main loop that runs until Ctrl+C is pressed. It logs state changes to a CSV file, and handles potential errors from GPIO initialization and file I/O. It also includes a debounce mechanism to avoid false readings, and ensures clean resource release on all exit paths.

