#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR1 17
#define SENSOR2 18
#define ALARM 27
#define DELAY_MS 100
#define THRESHOLD_MS 2000

FILE *log_file;

void handle_signal(int signo) {
    // Deactivate alarm
    gpioWrite(ALARM, 0);
    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }
    // Call gpioTerminate
    gpioTerminate();
    // Exit
    exit(signo);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Set GPIO directions
    gpioSetMode(SENSOR1, PI_INPUT);
    gpioSetMode(SENSOR2, PI_INPUT);
    gpioSetMode(ALARM, PI_OUTPUT);

    // Enable internal pull-down resistors
    gpioSetPullUpDown(SENSOR1, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR2, PI_PUD_DOWN);

    // Open log file
    log_file = fopen("bridge_integrity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize sensor states and alarm
    int sensor1_state = 0, sensor2_state = 0;
    int alarm_state = 0;

    while (1) {
        // Read sensor states
        int sensor1 = gpioRead(SENSOR1);
        int sensor2 = gpioRead(SENSOR2);

        // Check gpioRead return values
        if (sensor1 < 0 || sensor2 < 0) {
            fprintf(stderr, "Failed to read sensor state\n");
            return EXIT_FAILURE;
        }

        // Check if sensor states have changed
        if (sensor1 != sensor1_state || sensor2 != sensor2_state) {
            time_t now = time(NULL);
            struct tm *timeinfo = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

            if (sensor1 == 1 || sensor2 == 1) {
                // Sensor(s) have been tilted
                fprintf(log_file, "%s: Sensor(s) tilted\n", timestamp);
            } else {
                // Sensor(s) have returned to a neutral state
                fprintf(log_file, "%s: Sensor(s) returned to neutral\n", timestamp);
            }

            sensor1_state = sensor1;
            sensor2_state = sensor2;
        }

        // Check if either sensor has been tilted for more than 2 seconds
        if ((sensor1_state == 1 && clock() - sensor1_state_start >= THRESHOLD_MS) ||
            (sensor2_state == 1 && clock() - sensor2_state_start >= THRESHOLD_MS)) {
            // Activate alarm
            if (alarm_state == 0) {
                gpioWrite(ALARM, 1);
                alarm_state = 1;
                fprintf(log_file, "%s: Alarm activated\n", timestamp);
            }
        } else if (alarm_state == 1) {
            // Deactivate alarm
            gpioWrite(ALARM, 0);
            alarm_state = 0;
            fprintf(log_file, "%s: Alarm deactivated\n", timestamp);
        }

        // Delay
        gpioDelay(DELAY_MS);
    }

    // Unreachable
    return EXIT_SUCCESS;
}

