#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1D
#define LED_GPIO 17
#define THRESHOLD 500
#define RETRIES 3

FILE *log_file;
int i2c_handle;

void cleanup(int signum) {
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cUnwrite(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    int ret, tries, status, led_on = 0;
    float accel[3], magnitude;
    char timestamp[20];
    struct tm *timeinfo;
    time_t now;

    signal(SIGINT, cleanup);

    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "gpioInitialise() failed: %d\n", ret);
        return 1;
    }

    ret = gpioSetMode(LED_GPIO, PI_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "gpioSetMode() failed: %d\n", ret);
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen() failed: %d\n", i2c_handle);
        return 1;
    }

    for (tries = 0; tries < RETRIES; tries++) {
        status = i2cWriteByteData(i2c_handle, 0x1F, 0x00);
        if (status >= 0) break;
        fprintf(stderr, "i2cWriteByteData() failed: %d\n", status);
    }
    if (tries == RETRIES) {
        fprintf(stderr, "Failed to initialize sensor after %d tries\n", RETRIES);
        return 1;
    }

    log_file = fopen("seismic_events.log", "w");
    if (!log_file) {
        perror("fopen()");
        return 1;
    }

    while (1) {
        for (tries = 0; tries < RETRIES; tries++) {
            status = i2cReadBytes(i2c_handle, 0x28, 6, (char *)accel);
            if (status >= 0) break;
            fprintf(stderr, "i2cReadBytes() failed: %d\n", status);
        }
        if (tries == RETRIES) {
            fprintf(stderr, "Failed to read sensor after %d tries\n", RETRIES);
            return 1;
        }

        magnitude = sqrt(accel[0]*accel[0] + accel[1]*accel[1] + accel[2]*accel[2]);
        if (magnitude > THRESHOLD) {
            if (!led_on) {
                now = time(NULL);
                timeinfo = localtime(&now);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
                fprintf(log_file, "%s: Vibration exceeded threshold (%.2f)\n", timestamp, magnitude);
                fflush(log_file);
                led_on = 1;
                gpioWrite(LED_GPIO, 1);
                delay(1000);
                gpioWrite(LED_GPIO, 0);
                led_on = 0;
            }
        }

        delay(100);
    }

    return 0;
}

