#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINES_NUM 4
#define GPIO_LINES_OFFSETS {4, 17, 27, 22}
#define LED_GPIO_LINE 18

struct gpiod_chip *chip;
struct gpiod_line *lines[GPIO_LINES_NUM];
struct gpiod_line *led_line;

void cleanup_and_exit(int signum) {
    printf("Cleaning up and exiting...\n");
    for (int i = 0; i < GPIO_LINES_NUM; i++)
        gpiod_line_release(lines[i]);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    for (int i = 0; i < GPIO_LINES_NUM; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_LINES_OFFSETS[i]);
        if (!lines[i]) {
            perror("Failed to get GPIO line");
            return 1;
        }

        if (gpiod_line_request_input(lines[i], "Obstacle detection")) {
            perror("Failed to request GPIO line as input");
            return 1;
        }
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO_LINE);
    if (!led_line) {
        perror("Failed to get GPIO line");
        return 1;
    }

    if (gpiod_line_request_output(led_line, "LED control", 0)) {
        perror("Failed to request GPIO line as output");
        return 1;
    }

    while (1) {
        int obstacle_detected = 0;
        for (int i = 0; i < GPIO_LINES_NUM; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                perror("Failed to get line value");
                return 1;
            }
            obstacle_detected |= value;
        }

        if (gpiod_line_set_value(led_line, obstacle_detected)) {
            perror("Failed to set line value");
            return 1;
        }

        usleep(50000);  // 50 ms
    }

    return 0;
}

