#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define SENSOR_COUNT 8
#define BCM_PINS "5,6,13,19,26,12,16,20"

struct gpiod_chip *chip;
struct gpiod_line *lines[SENSOR_COUNT];
int states[SENSOR_COUNT];
int bcm_pins[SENSOR_COUNT] = {5, 6, 13, 19, 26, 12, 16, 20};

void print_error_and_exit(const char *msg) {
    fprintf(stderr, "%s: %s\n", msg, strerror(errno));
    exit(EXIT_FAILURE);
}

void release_resources() {
    for (int i = 0; i < SENSOR_COUNT; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);
}

void handle_sigint(int signum) {
    release_resources();
    exit(EXIT_SUCCESS);
}

int main() {
    struct timespec ts = {.tv_sec = 0, .tv_nsec = 50000000};

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip)
        print_error_and_exit("Failed to open GPIO chip");

    for (int i = 0; i < SENSOR_COUNT; i++) {
        lines[i] = gpiod_chip_get_line(chip, bcm_pins[i]);
        if (!lines[i])
            print_error_and_exit("Failed to get GPIO line");

        if (gpiod_line_request_both_edges_events(lines[i], "sensor%d", i))
            print_error_and_exit("Failed to request GPIO line");

        states[i] = gpiod_line_get_value(lines[i]);
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        for (int i = 0; i < SENSOR_COUNT; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value != states[i]) {
                struct tm tm;
                time_t t = time(NULL);
                localtime_r(&t, &tm);
                printf("%04d-%02d-%02dT%02d:%02d:%02d.%03ldZ sensor%d (BCM %d): %s\n",
                       tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                       tm.tm_hour, tm.tm_min, tm.tm_sec, t.tv_nsec / 1000000,
                       i, bcm_pins[i], value ? "released" : "touched");
                states[i] = value;
            }
        }

        nanosleep(&ts, NULL);
    }

    release_resources();
    return 0;
}

