#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <i2c.h>

#define SENSOR_ADDR 0x10
#define CONFIG_REG 0x00
#define ALS_REG 0x04
#define LED_GPIO 18
#define PWM_FREQ 1000
#define PWM_RANGE 100

FILE *log_file;
int i2c_handle;

void sig_handler(int signo) {
    if (i2c_handle >= 0) {
        i2c_close(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(signo);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("grow_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen("/dev/i2c-1", SENSOR_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        return EXIT_FAILURE;
    }

    if (i2cWriteWord(i2c_handle, CONFIG_REG, 0x0000) < 0) {
        fprintf(stderr, "Failed to write to sensor config.\n");
        return EXIT_FAILURE;
    }

    gpioHardwarePWM(LED_GPIO, PWM_FREQ, PWM_RANGE * 1000);

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        int lux, brightness, raw;
        struct timespec ts;
        char time_str[20];

        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        if (i2cReadWord(i2c_handle, ALS_REG, &raw) < 0) {
            fprintf(stderr, "Failed to read lux from sensor.\n");
            return EXIT_FAILURE;
        }

        lux = raw * 0.0576;

        if (lux < 100) {
            brightness = 100;
        } else if (lux < 500) {
            brightness = 75;
        } else if (lux < 1000) {
            brightness = 50;
        } else {
            brightness = 25;
        }

        gpioSetPWMdutycycle(LED_GPIO, PWM_RANGE - (brightness * PWM_RANGE / 100));

        fprintf(log_file, "%s, %d, %d, %d\n", time_str, lux, brightness, raw);
        fflush(log_file);

        sleep(1);
    }

    return EXIT_SUCCESS;
}

