#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define GPIO_LED 17
#define GPIO_START 2
#define GPIO_END 9

volatile sig_atomic_t stop = 0;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        stop = 1;
    }
}

int main() {
    int pi = pigpio_start(0, 0);
    if (pi < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    for (int i = GPIO_START; i <= GPIO_END; i++) {
        if (gpio_set_mode(pi, i, PI_INPUT) < 0 || gpio_set_pull_up_down(pi, i, PI_PUD_DOWN) < 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", i);
            return EXIT_FAILURE;
        }
    }

    if (gpio_set_mode(pi, GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_LED);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    int prev_touches[NUM_CHANNELS] = {0};

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (!stop) {
        for (int i = GPIO_START; i <= GPIO_END; i++) {
            int is_touched = gpio_read(pi, i);
            if (is_touched < 0) {
                fprintf(stderr, "Failed to read GPIO %d\n", i);
                return EXIT_FAILURE;
            }

            if (is_touched && !prev_touches[i - GPIO_START]) {
                time_t now = time(NULL);
                struct tm *time_info = localtime(&now);
                char time_str[20];
                strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", time_info);
                fprintf(log_file, "%s - Channel %d Touched\n", time_str, i - GPIO_START + 1);
                fflush(log_file);
                gpio_write(pi, GPIO_LED, 1);
            }

            prev_touches[i - GPIO_START] = is_touched;
        }

        sleep(50);
    }

    gpio_write(pi, GPIO_LED, 0);
    pigpio_stop(pi);
    fclose(log_file);

    return EXIT_SUCCESS;
}

