#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define CONFIG_VAL 0xC810
#define DATA_REG 0x00

static int i2c_handle;

void sigint_handler(int signo) {
    if (i2c_handle > 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);

