#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_LINE 4
#define LOG_FILE "touch_log.txt"

struct gpiod_line *line;
struct gpiod_chip *chip;
FILE *log_file;

void log_touch_event(int state)
{
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char buffer[80];

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s: Touch %s\n", buffer, state ? "Detected" : "Released");
    fflush(log_file);
}

void handle_signal(int signum)
{
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(0);
}

int main()
{
    int ret;
    int last_state = -1;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        ret = 1;
        goto err_close_chip;
    }

    ret = gpiod_line_request_input_events(line);
    if (ret < 0) {
        fprintf(stderr, "Failed to request input events: %s\n", strerror(errno));
        goto err_release_line;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        ret = 1;
        goto err_release_line;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        ret = gpiod_line_event_wait(line, NULL);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for event: %s\n", strerror(errno));
            break;
        }

        if (ret == 0)
            continue;

        struct gpiod_line_event event;
        ret = gpiod_line_event_read(line, &event);
        if (ret < 0) {
            fprintf(stderr, "Failed to read event: %s\n", strerror(errno));
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE)
            last_state = 1;
        else if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE)
            last_state = 0;

        if (last_state != -1)
            log_touch_event(last_state);
    }

    fclose(log_file);
err_release_line:
    gpiod_line_release(line);
err_close_chip:
    gpiod_chip_close(chip);
    return ret;
}

