#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x08

#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

#define FLOW_MIN 0.0
#define FLOW_MAX 100.0

volatile sig_atomic_t stop = 0;

int i2c_handle;
FILE *log_file;

void handle_sigint(int signum) {
    stop = 1;
}

unsigned char crc8(const unsigned char *data, int len, unsigned char polynomial, unsigned char init) {
    unsigned char crc = init;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

void log_flow_rate(double flow_rate, int raw_flags, const char *status) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%.2f,%d,%s\n", timestamp, flow_rate, raw_flags, status);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = gpioI2CSetSlave(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to set I2C slave address.\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    log_file = fopen("cooling_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        return EXIT_FAILURE;
    }
    fprintf(log_file, "Timestamp,Flow Rate (ml/min),Raw Flags,Status\n");

    while (!stop) {
        unsigned char cmd[] = {0x36, 0x08};
        if (gpioI2CWrite(i2c_handle, cmd, sizeof(cmd)) < 0) {
            log_flow_rate(0.0, 0, "ERROR");
            fprintf(stderr, "Failed to write I2C command.\n");
            usleep(10000);  // 10 ms
            gpioI2CDelete(i2c_handle);
            i2c_handle = gpioI2CSetSlave(I2C_BUS, I2C_ADDR);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-initialize I2C.\n");
                return EXIT_FAILURE;
            }
            continue;
        }

        unsigned char data[3];
        if (gpioI2CRead(i2c_handle, data, sizeof(data)) < 0) {
            log_flow_rate(0.0, 0, "ERROR");
            fprintf(stderr, "Failed to read I2C data.\n");
            usleep(10000);  // 10 ms
            gpioI2CDelete(i2c_handle);
            i2c_handle = gpioI2CSetSlave(I2C_BUS, I2C_ADDR);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-initialize I2C.\n");
                return EXIT_FAILURE;
            }
            continue;
        }

        int raw_value = (data[0] << 8) | data[1];
        if (crc8(data, sizeof(data), CRC8_POLYNOMIAL, CRC8_INIT) != 0) {
            log_flow_rate(raw_value / 90.0, data[2], "ERROR");
            fprintf(stderr, "CRC failure.\n");
            continue;
        }

        double flow_rate = raw_value / 90.0;
        if (flow_rate < FLOW_MIN || flow_rate > FLOW_MAX) {
            log_flow_rate(flow_rate, data[2], "INVALID");
            fprintf(stderr, "Invalid flow rate: %.2f ml/min.\n", flow_rate);
            continue;
        }

        log_flow_rate(flow_rate, data[2], "OK");

        usleep(1000000);  // 1 second
    }

    fclose(log_file);
    gpioI2CDelete(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

