#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <time.h>

struct gpiod_chip *chip;
struct gpiod_line *sensor_line, *led_line;
FILE *log_file;

void sig_handler(int signo) {
    if (chip)
        gpiod_chip_close(chip);
    if (sensor_line)
        gpiod_line_release(sensor_line);
    if (led_line)
        gpiod_line_release(led_line);
    if (log_file)
        fclose(log_file);
    exit(signo);
}

int main() {
    int ret;
    struct timespec ts;
    struct tm tm;

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    sensor_line = gpiod_chip_get_line(chip, 23);
    if (!sensor_line) {
        fprintf(stderr, "Failed to get sensor line\n");
        ret = EXIT_FAILURE;
        goto err_chip;
    }

    ret = gpiod_line_request_rising_edge_events(sensor_line, "sensor");
    if (ret < 0) {
        fprintf(stderr, "Failed to request sensor line events\n");
        goto err_sensor_line;
    }

    led_line = gpiod_chip_get_line(chip, 24);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line\n");
        ret = EXIT_FAILURE;
        goto err_sensor_line;
    }

    ret = gpiod_line_request_output(led_line, "led", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request LED line\n");
        goto err_led_line;
    }

    log_file = fopen("touch_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        ret = EXIT_FAILURE;
        goto err_led_line;
    }

    while (1) {
        ret = gpiod_line_event_wait(sensor_line, &ts);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for sensor line event\n");
            goto err_log_file;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        localtime_r(&ts.tv_sec, &tm);

        fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02d.%09ldZ ",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, ts.tv_nsec);

        ret = gpiod_line_get_value(led_line);
        if (ret < 0) {
            fprintf(stderr, "Failed to get LED line value\n");
            goto err_log_file;
        }

        fprintf(log_file, "LED: %s\n", ret ? "ON" : "OFF");

        ret = gpiod_line_set_value(led_line, !ret);
        if (ret < 0) {
            fprintf(stderr, "Failed to set LED line value\n");
            goto err_log_file;
        }
    }

err_log_file:
    fclose(log_file);
err_led_line:
    gpiod_line_release(led_line);
err_sensor_line:
    gpiod_line_release(sensor_line);
err_chip:
    gpiod_chip_close(chip);

    return ret;
}

