#define BUZZER_DURATION_MS 2000

struct gpiod_line *flame_sensor;
struct gpiod_line *buzzer;
struct gpiod_chip *chip;
FILE *log_file;

void log_event(const char *event) {
    time_t t = time(NULL);
    char *time_str = ctime(&t);
    time_str[strlen(time_str) - 1] = '\0';  // remove trailing newline
    fprintf(log_file, "%s: %s\n", time_str, event);
    fflush(log_file);
}

void handle_shutdown(int signum) {
    gpiod_line_set_value(buzzer, 0);
    gpiod_line_release(flame_sensor);
    gpiod_line_release(buzzer);
    gpiod_chip_close(chip);
    log_event("System stopped");
    exit(0);
}

int main() {
    signal(SIGINT, handle_shutdown);
    signal(SIGTERM, handle_shutdown);

    chip = gpiod_chip_open_by_name(CHIP);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name: %s\n", strerror(errno));
        return 1;
    }

    flame_sensor = gpiod_chip_get_line(chip, FLAME_LINE);
    if (!flame_sensor) {
        fprintf(stderr, "gpiod_chip_get_line: %s\n", strerror(errno));
        return 1;
    }

    buzzer = gpiod_chip_get_line(chip, BUZZER_LINE);
    if (!buzzer) {
        fprintf(stderr, "gpiod_chip_get_line: %s\n", strerror(errno));
        return 1;
    }

    if (gpiod_line_request_input(flame_sensor, "flame_sensor")) {
        fprintf(stderr, "gpiod_line_request_input: %s\n", strerror(errno));
        return 1;
    }

    if (gpiod_line_request_output(buzzer, "buzzer", 0)) {
        fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
        return 1;
    }

    log_file = fopen("alert_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "fopen: %s\n", strerror(errno));
        return 1;
    }

    log_event("System started");

    int last_flame_state = gpiod_line_get_value(flame_sensor);
    while (1) {
        usleep(POLL_INTERVAL_MS * 1000);
        int current_flame_state = gpiod_line_get_value(flame_sensor);
        if (current_flame_state < 0) {
            fprintf(stderr, "gpiod_line_get_value: %s\n", strerror(errno));
            return 1;
        }

        if (current_flame_state < last_flame_state) {
            log_event("Flame detected");
            for (int i = 0; i < BUZZER_DURATION_MS; i += 100) {
                gpiod_line_set_value(buzzer, 1);
                usleep(100 * 1000);
            }
            gpiod_line_set_value(buzzer, 0);
        }

        last_flame_state = current_flame_state;
    }

    return 0;
}

