void toggle_led(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        if (gpioToggle(GPIO_LED) != 0) {
            fprintf(stderr, "Failed to toggle LED: %s\n", strerror(errno));
            exit(EXIT_FAILURE);
        }

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

        if (log_file != NULL) {
            if (fprintf(log_file, "%s\n", timestamp) < 0) {
                fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
            }
        }
    }
}

