    fclose(log_file);
    gpioTerminate();
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    if (gpioSetMode(SENSOR1, PI_INPUT) != 0 || gpioSetMode(SENSOR2, PI_INPUT) != 0 || gpioSetMode(SENSOR3, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO mode.\n");
        return 1;
    }

    if (gpioSetPullUpDown(SENSOR1, PI_PULL_UP) != 0 || gpioSetPullUpDown(SENSOR2, PI_PULL_UP) != 0 || gpioSetPullUpDown(SENSOR3, PI_PULL_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up.\n");
        return 1;
    }

    log_file = fopen("magnet_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int sensor1_state, sensor2_state, sensor3_state;
    int prev_sensor1_state = -1, prev_sensor2_state = -1, prev_sensor3_state = -1;

    while (1) {
        sensor1_state = gpioRead(SENSOR1);
        sensor2_state = gpioRead(SENSOR2);
        sensor3_state = gpioRead(SENSOR3);

        if (sensor1_state < 0 || sensor2_state < 0 || sensor3_state < 0) {
            fprintf(stderr, "Failed to read sensor state.\n");
            continue;
        }

        if (sensor1_state != prev_sensor1_state) {
            log_magnet_state(1, sensor1_state);
            prev_sensor1_state = sensor1_state;
        }

        if (sensor2_state != prev_sensor2_state) {
            log_magnet_state(2, sensor2_state);
            prev_sensor2_state = sensor2_state;
        }

        if (sensor3_state != prev_sensor3_state) {
            log_magnet_state(3, sensor3_state);
            prev_sensor3_state = sensor3_state;
        }

        gpioDelay(100);
    }

    return 0;
}

