#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x4A
#define I2C_HANDLE_INIT -1

#define REG_PART_ID 0x00
#define REG_HW_REV 0x01
#define REG_LED_CURRENT 0x3F
#define REG_AVERAGING 0x04
#define REG_ENABLE 0x01
#define REG_HEART_RATE 0x2A

#define PART_ID_VAL 0x02
#define HW_REV_VAL 0x01
#define LED_CURRENT_VAL 0x00
#define AVERAGING_VAL 0x00
#define ENABLE_VAL 0x01

#define BPM_MIN 30
#define BPM_MAX 220

static int i2c_handle = I2C_HANDLE_INIT;
static FILE *log_file = NULL;

static void cleanup_and_exit(int sig) {
    if (i2c_handle != I2C_HANDLE_INIT) {
        i2cClose(i2c_handle);
        i2c_handle = I2C_HANDLE_INIT;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (sig == SIGINT) {
        printf("\nExiting on SIGINT\n");
    }
    exit(sig);
}

int main() {
    int pi, part_id, hw_rev, write_result, read_result, raw, bpm, bpm_filtered = 0;
    int i2c_result, i;
    char timestamp[20];
    struct tm *timeinfo;
    time_t now;

    signal(SIGINT, cleanup_and_exit);

    pi = piGpioInitialise();
    if (pi < 0) {
        printf("Error initializing pigpio: %d\n", pi);
        cleanup_and_exit(EXIT_FAILURE);
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        printf("Error opening I2C bus: %d\n", i2c_handle);
        cleanup_and_exit(EXIT_FAILURE);
    }

    part_id = i2cReadWordData(i2c_handle, REG_PART_ID);
    if (part_id < 0) {
        printf("Error reading PART_ID: %d\n", part_id);
        cleanup_and_exit(EXIT_FAILURE);
    } else if (part_id != PART_ID_VAL) {
        printf("Wrong PART_ID: 0x%02X\n", part_id);
        cleanup_and_exit(EXIT_FAILURE);
    }

    hw_rev = i2cReadWordData(i2c_handle, REG_HW_REV);
    if (hw_rev < 0) {
        printf("Error reading HW_REV: %d\n", hw_rev);
        cleanup_and_exit(EXIT_FAILURE);
    } else if (hw_rev != HW_REV_VAL) {
        printf("Wrong HW_REV: 0x%02X\n", hw_rev);
        cleanup_and_exit(EXIT_FAILURE);
    }

    write_result = i2cWriteWordData(i2c_handle, REG_LED_CURRENT, LED_CURRENT_VAL);
    if (write_result < 0) {
        printf("Error writing LED_CURRENT: %d\n", write_result);
        cleanup_and_exit(EXIT_FAILURE);
    }

    write_result = i2cWriteWordData(i2c_handle, REG_AVERAGING, AVERAGING_VAL);
    if (write_result < 0) {
        printf("Error writing AVERAGING: %d\n", write_result);
        cleanup_and_exit(EXIT_FAILURE);
    }

    write_result = i2cWriteWordData(i2c_handle, REG_ENABLE, ENABLE_VAL);
    if (write_result < 0) {
        printf("Error writing ENABLE: %d\n", write_result);
        cleanup_and_exit(EXIT_FAILURE);
    }

    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        printf("Error opening log file\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    while (1) {
        raw = i2cReadWordData(i2c_handle, REG_HEART_RATE);
        if (raw < 0) {
            printf("Error reading HEART_RATE: %d\n", raw);
            continue;
        }

        bpm = raw * 0.5;
        bpm_filtered = (bpm + 4 * bpm_filtered) / 5;

        if (bpm_filtered >= BPM_MIN && bpm_filtered <= BPM_MAX) {
            time(&now);
            timeinfo = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(log_file, "%s,%d\n", timestamp, bpm_filtered);
            fflush(log_file);
        }

        sleep(1);
    }

    return 0;
}

