#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define LOG_FILE "flame_log.txt"

struct gpiod_line *line;
struct gpiod_chip *chip;
FILE *log_file;

void sig_handler(int signo) {
    if (line)
        gpiod_line_release(line);
    if (chip)
        gpiod_chip_close(chip);
    if (log_file)
        fclose(log_file);
    exit(signo);
}

int main() {
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(line, "flame_sensor", GPIOD_LINE_FLAG_BIAS_PULL_UP)) {
        fprintf(stderr, "Failed to request GPIO line as input\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        if (gpiod_line_update(line)) {
            fprintf(stderr, "Failed to update GPIO line\n");
            sig_handler(1);
        }

        if (gpiod_line_get_value(line)) {
            time_t t = time(NULL);
            char *time_str = ctime(&t);
            time_str[strlen(time_str) - 1] = '\0';  // remove trailing newline

            printf("FLAME DETECTED\n");
            fprintf(log_file, "%s: FLAME DETECTED\n", time_str);
            fflush(log_file);
        }

        usleep(100000);  // sleep for 100 ms
    }

    return 0;
}

