        if (!display_lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line (display %d): %s\n", i, strerror(errno));
            cleanup_and_exit(0);
        }
        if (gpiod_line_request_output(display_lines[i], "display", 0)) {
            fprintf(stderr, "gpiod_line_request_output (display %d): %s\n", i, strerror(errno));
            cleanup_and_exit(0);
        }
    }

