struct gpiod_line *line1, *line2, *line3, *line4;
struct gpiod_chip *chip;
FILE *csv_file;

void write_to_csv(int value1, int value2, int value3, int value4) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(csv_file, "%d-%02d-%02d %02d:%02d:%02d,%d,%d,%d,%d\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, value1, value2, value3, value4);
    fflush(csv_file);
}

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_line_release(line3);
        gpiod_line_release(line4);
        gpiod_chip_close(chip);
        fclose(csv_file);
        exit(EXIT_SUCCESS);
    }
}

int main() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0\n");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, GPIO17);
    if (!line1) {
        fprintf(stderr, "Failed to get line %d\n", GPIO17);
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, GPIO18);
    if (!line2) {
        fprintf(stderr, "Failed to get line %d\n", GPIO18);
        return EXIT_FAILURE;
    }

    line3 = gpiod_chip_get_line(chip, GPIO27);
    if (!line3) {
        fprintf(stderr, "Failed to get line %d\n", GPIO27);
        return EXIT_FAILURE;
    }

    line4 = gpiod_chip_get_line(chip, GPIO22);
    if (!line4) {
        fprintf(stderr, "Failed to get line %d\n", GPIO22);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line1, "sensor1") ||
        gpiod_line_request_input(line2, "sensor2") ||
        gpiod_line_request_input(line3, "sensor3") ||
        gpiod_line_request_input(line4, "sensor4")) {
        fprintf(stderr, "Failed to request input\n");
        return EXIT_FAILURE;
    }

    csv_file = fopen("tracking_log.csv", "w");
    if (!csv_file) {
        fprintf(stderr, "Failed to open tracking_log.csv\n");
        return EXIT_FAILURE;
    }

    fprintf(csv_file, "timestamp,sensor1,sensor2,sensor3,sensor4\n");

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        int value1, value2, value3, value4;

        value1 = gpiod_line_get_value(line1);
        value2 = gpiod_line_get_value(line2);
        value3 = gpiod_line_get_value(line3);
        value4 = gpiod_line_get_value(line4);

        if (value1 < 0 || value2 < 0 || value3 < 0 || value4 < 0) {
            fprintf(stderr, "Failed to read GPIO value\n");
            continue;
        }

        write_to_csv(value1, value2, value3, value4);

        usleep(100000);
    }

    return EXIT_SUCCESS;
}

