#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO17 17
#define GPIO18 18
#define LOG_FILE "/var/log/tilt_events.log"

struct gpiod_chip *chip;
struct gpiod_line *lines[2];
FILE *log_file;

void log_event(int sensor, const char *event) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, Sensor %d %s\n",
            tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
            tm->tm_hour, tm->tm_min, tm->tm_sec, sensor, event);
    fflush(log_file);
}

void exit_handler(int signum) {
    for (int i = 0; i < 2; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(0);
}

int main() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(1);
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_chip_close(chip);
        exit(1);
    }

    struct sigaction action;
    action.sa_handler = exit_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    for (int i = 0; i < 2; i++) {
        lines[i] = gpiod_chip_get_line(chip, i == 0 ? GPIO17 : GPIO18);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %d\n", i == 0 ? GPIO17 : GPIO18);
            exit_handler(0);
        }

        if (gpiod_line_request_both_edges_events(lines[i], "tilt_sensor", 50000)) {
            fprintf(stderr, "Failed to request line %d\n", i == 0 ? GPIO17 : GPIO18);
            exit_handler(0);
        }
    }

    while (1) {
        for (int i = 0; i < 2; i++) {
            enum gpiod_line_event event;
            if (gpiod_line_event_wait(lines[i], NULL) == 0) {
                if (gpiod_line_event_read(lines[i], &event)) {
                    fprintf(stderr, "Failed to read event from line %d\n", i == 0 ? GPIO17 : GPIO18);
                    exit_handler(0);
                }
                log_event(i + 1, event.event_type == GPIOD_LINE_EVENT_RISING_EDGE ? "tilted" : "returned to normal");
            }
        }
    }

    return 0;
}

