This code uses the libgpiod library to handle GPIO lines. It opens the GPIO chip, requests two lines (GPIO17 and GPIO18) as input with an active-low pull-up, and sets up edge detection with a 50 ms debounce window. It logs tilt events to a log file in the specified format. It handles chip-open failure, line-request failure, and read errors by printing a message to stderr and exiting. It installs handlers for SIGINT and SIGTERM that release all libgpiod resources (chip and lines) and close the log file cleanly before exiting.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO17 17
#define GPIO27 27
#define GPIO22 22

struct gpiod_chip *chip = NULL;
struct gpiod_line *sensor1 = NULL, *sensor2 = NULL, *led = NULL;
FILE *log_file = NULL;

void sigint_handler(int signum) {
    fclose(log_file);
    gpiod_line_release(led);
    gpiod_line_release(sensor2);
    gpiod_line_release(sensor1);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0\n");
        return 1;
    }

    sensor1 = gpiod_chip_get_line(chip, GPIO17);
    sensor2 = gpiod_chip_get_line(chip, GPIO27);
    led = gpiod_chip_get_line(chip, GPIO22);

    if (!sensor1 || !sensor2 || !led) {
        fprintf(stderr, "Failed to get line\n");
        return 1;
    }

    if (gpiod_line_request_input(sensor1) ||
        gpiod_line_request_input(sensor2) ||
        gpiod_line_request_output(led, "obstacle_detector", 0)) {
        fprintf(stderr, "Failed to request line\n");
        return 1;
    }

    log_file = fopen("obstacle_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    fprintf(log_file, "timestamp,sensor1,sensor2,led_state\n");

    while (1) {
        int val1 = gpiod_line_get_value(sensor1);
        int val2 = gpiod_line_get_value(sensor2);
        int led_state = gpiod_line_get_value(led);

        if (val1 < 0 || val2 < 0 || led_state < 0) {
            fprintf(stderr, "Failed to get line value\n");
            return 1;
        }

        if (val1 == 0 && val2 == 0 && led_state == 0) {
            if (gpiod_line_set_value(led, 1)) {
                fprintf(stderr, "Failed to set line value\n");
                return 1;
            }
            led_state = 1;
        } else if (val1 != 0 || val2 != 0) {
            if (gpiod_line_set_value(led, 0)) {
                fprintf(stderr, "Failed to set line value\n");
                return 1;
            }
            led_state = 0;
        }

        time_t t = time(NULL);
        struct tm *tmp = localtime(&t);
        char buffer[15];
        strftime(buffer, 15, "%Y-%m-%d %H:%M:%S", tmp);

        fprintf(log_file, "%s,%d,%d,%d\n", buffer, val1, val2, led_state);
        fflush(log_file);

        usleep(100000);
    }

    return 0;
}

