            return 1;
        }

        if (val1 == 0 && val2 == 0 && led_state == 0) {
            if (gpiod_line_set_value(led, 1)) {
                fprintf(stderr, "Failed to set line value\n");
                return 1;
            }
            led_state = 1;
        } else if (val1 != 0 || val2 != 0) {
            if (gpiod_line_set_value(led, 0)) {
                fprintf(stderr, "Failed to set line value\n");
                return 1;
            }
            led_state = 0;
        }

        time_t t = time(NULL);
        struct tm *tmp = localtime(&t);
        char buffer[15];
        strftime(buffer, 15, "%Y-%m-%d %H:%M:%S", tmp);

        fprintf(log_file, "%s,%d,%d,%d\n", buffer, val1, val2, led_state);
        fflush(log_file);

        usleep(100000);
    }

    return 0;
}
