#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <sys/ioctl.h>
#include <signal.h>

#define SENSOR_ADDRESS 0x49
#define ALS_VISIBLE_DATA_REG 0x24
#define I2C_BUS 1

volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

int main() {
    int fd;
    struct i2c_msg msgs[2];
    uint8_t reg_addr = ALS_VISIBLE_DATA_REG;
    uint8_t data[2];

    signal(SIGINT, handle_sigint);

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to set sensor address");
        close(fd);
        return EXIT_FAILURE;
    }

    msgs[0].addr = SENSOR_ADDRESS;
    msgs[0].flags = 0;
    msgs[0].len = 1;
    msgs[0].buf = &reg_addr;

    msgs[1].addr = SENSOR_ADDRESS;
    msgs[1].flags = I2C_M_RD;
    msgs[1].len = 2;
    msgs[1].buf = data;

    while (!stop) {
        if (i2c_rdwr(fd, msgs, 2) < 0) {
            perror("Failed to read sensor data");
            close(fd);
            return EXIT_FAILURE;
        }

        uint16_t sensor_data = (data[1] << 8) | data[0];
        printf("Sensor data: %u\n", sensor_data);

        usleep(100000);
    }

    close(fd);
    return EXIT_SUCCESS;
}

