#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define GPIOCHIP "gpiochip0"
#define GPIO_LINE_COUNT 8
#define GPIO_LINES {5, 6, 13, 19, 26, 12, 16, 20}

struct gpiod_line *lines[GPIO_LINE_COUNT];
struct gpiod_chip *chip;

volatile sig_atomic_t stop = 0;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        stop = 1;
    }
}

int main() {
    struct sigaction sig_action;
    memset(&sig_action, 0, sizeof(struct sigaction));
    sig_action.sa_handler = sig_handler;
    sigaction(SIGINT, &sig_action, NULL);
    sigaction(SIGTERM, &sig_action, NULL);

    chip = gpiod_chip_open(GPIOCHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < GPIO_LINE_COUNT; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_LINES[i]);
        if (!lines[i]) {
            perror("gpiod_chip_get_line");
            return EXIT_FAILURE;
        }

        if (gpiod_line_request_input(lines[i], "touch_sensor")) {
            perror("gpiod_line_request_input");
            return EXIT_FAILURE;
        }
    }

    while (!stop) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        printf("[%ld.%06lds] ", ts.tv_sec, ts.tv_nsec / 1000);

        for (int i = 0; i < GPIO_LINE_COUNT; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                perror("gpiod_line_get_value");
                return EXIT_FAILURE;
            }
            printf("CH%d=%d ", i + 1, value);
        }
        printf("\n");

        // Poll every 200 ms
        struct timespec sleep_time = {.tv_sec = 0, .tv_nsec = 200000000};
        nanosleep(&sleep_time, NULL);
    }

    for (int i = 0; i < GPIO_LINE_COUNT; i++)
        gpiod_line_release(lines[i]);

    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

