#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x29
#define GPIO_LED 17
#define RED_THRESHOLD 200

static struct gpiod_line *gpio_line;
static int i2c_fd;

static void cleanup_and_exit(int sig) {
    if (gpio_line)
        gpiod_line_release(gpio_line);
    if (i2c_fd >= 0)
        close(i2c_fd);
    ioctl(i2c_fd, I2C_SLAVE, 0x29);
    char data = 0x00;
    write(i2c_fd, &data, 1);
    exit(sig);
}

static int write_register(int fd, uint8_t reg, uint8_t data) {
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl");
        return -1;
    }
    if (write(fd, &reg, 1) != 1) {
        perror("write");
        return -1;
    }
    if (write(fd, &data, 1) != 1) {
        perror("write");
        return -1;
    }
    return 0;
}

static int read_register(int fd, uint8_t reg, uint8_t *data) {
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl");
        return -1;
    }
    if (write(fd, &reg, 1) != 1) {
        perror("write");
        return -1;
    }
    if (read(fd, data, 1) != 1) {
        perror("read");
        return -1;
    }
    return 0;
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = cleanup_and_exit;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    gpio_line = gpiod_line_get_optional("/dev/gpiochip0", GPIO_LED);
    if (!gpio_line) {
        perror("gpiod_line_get_optional");
        return -1;
    }
    if (gpiod_line_request_output(gpio_line, "led", 0) < 0) {
        perror("gpiod_line_request_output");
        return -1;
    }

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return -1;
    }

    while (1) {
        if (write_register(i2c_fd, 0x80, 0x01) < 0) {
            cleanup_and_exit(-1);
        }
        if (write_register(i2c_fd, 0x00, 0x00) < 0) {
            cleanup_and_exit(-1);
        }
        if (write_register(i2c_fd, 0x01, 0x00) < 0) {
            cleanup_and_exit(-1);
        }
        uint8_t id;
        if (read_register(i2c_fd, 0x12, &id) < 0) {
            if (id != 0x44) {
                cleanup_and_exit(-1);
            }
        }
        uint8_t data[8];
        if (read_register(i2c_fd, 0x14, &data[0]) < 0) {
            cleanup_and_exit(-1);
        }
        if (read_register(i2c_fd, 0x16, &data[2]) < 0) {
            cleanup_and_exit(-1);
        }
        if (read_register(i2c_fd, 0x18, &data[4]) < 0) {
            cleanup_and_exit(-1);
        }
        if (read_register(i2c_fd, 0x1A, &data[6]) < 0) {
            cleanup_and_exit(-1);
        }
        uint16_t clear = (data[1] << 8) | data[0];
        uint16_t red = (data[3] << 8) | data[2];
        uint16_t green = (data[5] << 8) | data[4];
        uint16_t blue = (data[7] << 8) | data[6];

        // Apply gain and offset calibration here...

        printf("Clear: %u, Red: %u, Green: %u, Blue: %u\n", clear, red, green, blue);

        if (red > RED_THRESHOLD) {
            gpiod_line_set_value(gpio_line, 1);
        } else {
            gpiod_line_set_value(gpio_line, 0);
        }

        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 200000000;
        nanosleep(&ts, NULL);
    }

    return 0;
}

