#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>
#include <i2c.h>

#define GPIO_PWM 18
#define BH1750_ADDR 0x23
#define BH1750_CMD 0x10
#define BH1750_RETRIES 3
#define LED_STRIP_MAX_BRIGHTNESS 255
#define LED_STRIP_MIN_BRIGHTNESS 0
#define LUX_TO_BRIGHTNESS_FACTOR 1.2

volatile sig_atomic_t stop = 0;

void cleanup(void) {
    piGpioInitialise();
    piGpioSetPWMdutycycle(GPIO_PWM, 0);
    piGpioWaveDelete(0);
    piGpioStop();
    printf("Cleaned up and exited.\n");
}

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    int pi = piGpioInitialise();
    if (pi < 0) {
        printf("Error initializing pigpio: %d\n", pi);
        return EXIT_FAILURE;
    }

    piGpioSetPWMrange(GPIO_PWM, LED_STRIP_MAX_BRIGHTNESS);

    struct sigaction action;
    action.sa_handler = signal_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;

    if (sigaction(SIGINT, &action, NULL) < 0 || sigaction(SIGTERM, &action, NULL) < 0) {
        printf("Error setting up signal handlers.\n");
        return EXIT_FAILURE;
    }

    int fd = i2cOpen(0, BH1750_ADDR, I2C_SLAVE_FORCE);
    if (fd < 0) {
        printf("Error opening I2C device: %d\n", fd);
        return EXIT_FAILURE;
    }

    while (!stop) {
        for (int i = 0; i < BH1750_RETRIES; i++) {
            if (i2cWriteByte(fd, BH1750_CMD) < 0) {
                printf("Error writing to I2C device.\n");
                continue;
            }

            usleep(180000);

            uint8_t buf[2];
            if (i2cReadBytes(fd, buf, 2) < 0) {
                printf("Error reading from I2C device.\n");
                continue;
            }

            int lux = (buf[0] << 8) | buf[1];
            lux /= LUX_TO_BRIGHTNESS_FACTOR;

            if (lux < 0)
                lux = 0;
            else if (lux > 1000)
                lux = 1000;

            int brightness = LED_STRIP_MIN_BRIGHTNESS + (log(lux + 1) / log(1001) * (LED_STRIP_MAX_BRIGHTNESS - LED_STRIP_MIN_BRIGHTNESS));

            piGpioSetPWMdutycycle(GPIO_PWM, brightness);
            break;
        }

        usleep(50000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

