#include <linux/spi/spidev.h>

#define I2C_DEV "/dev/i2c-1"
#define SPI_DEV "/dev/spidev0.0"
#define BH1750_ADDR 0x23
#define APA102_LED_COUNT 32

int i2c_fd, spi_fd;

void handle_sigint(int signum) {
    const uint32_t off_frame = 0x000000FF;
    if (write(spi_fd, &off_frame, sizeof(off_frame)) < 0)
        perror("write off_frame");
    close(spi_fd);
    close(i2c_fd);
    exit(0);
}

int main() {
    signal(SIGINT, handle_sigint);

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C");
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        return 1;
    }

    spi_fd = open(SPI_DEV, O_WRONLY);
    if (spi_fd < 0) {
        perror("open SPI");
        return 1;
    }
    {
        int spi_mode = SPI_MODE_0;
        int spi_bits_per_word = 32;
        int spi_max_speed_hz = 1000000;
        if (ioctl(spi_fd, SPI_IOC_WR_MODE, &spi_mode) < 0 ||
            ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &spi_bits_per_word) < 0 ||
            ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi_max_speed_hz) < 0) {
            perror("ioctl SPI");
            return 1;
        }
    }

    const uint8_t bh1750_command = 0x20;
    if (write(i2c_fd, &bh1750_command, sizeof(bh1750_command)) < 0) {
        perror("write bh1750_command");
        return 1;
    }

    while (1) {
        usleep(120000);

        uint16_t bh1750_raw;
        if (read(i2c_fd, &bh1750_raw, sizeof(bh1750_raw)) < 0) {
            perror("read bh1750_raw");
            return 1;
        }
        float lux = bh1750_raw / 1.2f;
        uint8_t brightness = (lux - 10) / 290 * 31;
        if (brightness > 31) brightness = 31;

        const uint32_t start_frame = 0;
        uint32_t led_frame = 0xE0 | brightness;
        const uint32_t end_frame = 0xFF;
        for (int i = 0; i < APA102_LED_COUNT; i++) {
            if (write(spi_fd, &start_frame, sizeof(start_frame)) < 0 ||
                write(spi_fd, &led_frame, sizeof(led_frame)) < 0 ||
                write(spi_fd, &end_frame, sizeof(end_frame)) < 0) {
                perror("write led_frame");
                return 1;
            }
        }
    }

    return 0;
}

