    if (i2c_handle_high < 0) {
        fprintf(stderr, "Failed to open I2C device at address %x\n", BH1750_ADDR_HIGH);
    } else if (i2cWriteByte(i2c_handle_high, BH1750_INIT_CMD) < 0) {
        fprintf(stderr, "Failed to write to I2C device at address %x\n", BH1750_ADDR_HIGH);
        i2cClose(i2c_handle_high);
        i2c_handle_high = -1;
    }

    int current_brightness = 0;
    int target_brightness = 0;
    while (!stop) {
        int total_lux = 0;
        int sensor_count = 0;
        if (i2c_handle_low >= 0) {
            usleep(180000);
            uint8_t data[2];
            if (i2cRead(i2c_handle_low, data, 2) == 2) {
                total_lux += ((data[0] << 8) | data[1]) >> 4;
                sensor_count++;
            }
        }
        if (i2c_handle_high >= 0) {
            usleep(180000);
            uint8_t data[2];
            if (i2cRead(i2c_handle_high, data, 2) == 2) {
                total_lux += ((data[0] << 8) | data[1]) >> 4;
                sensor_count++;
            }
        }
        if (sensor_count > 0) {
            target_brightness = (total_lux / sensor_count) * APA102_BRIGHTNESS_MAX / 65535;
        }
        if (target_brightness != current_brightness) {
            if (target_brightness > current_brightness) {
                current_brightness = (current_brightness + 1) * APA102_FADE_TIME / 1000;
            } else {
                current_brightness = (current_brightness - 1) * APA102_FADE_TIME / 1000;
            }
            // TODO: write brightness to APA102 strip via SPI
        }
        usleep(SLEEP_TIME);
    }

    cleanup();
    return EXIT_SUCCESS;
