#define GPIO_PIN 18
#define MAX_RETRIES 3
#define RETRY_DELAY 100000
#define INTEGRATION_TIME 100
#define GAIN 8
#define LUX_SCALE (0.0288 * GAIN * INTEGRATION_TIME / 100.0)
#define LUX_MAX 120000
#define BRIGHTNESS_MAX 255

struct gpiod_line *line;
struct gpiod_chip *chip;
int i2c_fd;

void cleanup(int signum) {
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);
    exit(0);
}

int main() {
    chip = gpiod_chip_open_by_name("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    if (gpiod_line_request_output(line, "led_brightness", 0)) {
        perror("gpiod_line_request_output");
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open i2c");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl i2c slave");
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        int retries = 0;
        uint16_t raw;

        while (retries < MAX_RETRIES) {
            if (write(i2c_fd, (uint8_t[]){0x00}, 1) == 1 &&
                read(i2c_fd, &raw, 2) == 2)
                break;

            usleep(RETRY_DELAY);
            retries++;
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read from sensor\n");
            continue;
        }

        double lux = raw * LUX_SCALE;
        uint8_t brightness = BRIGHTNESS_MAX * pow(lux / LUX_MAX, 1.0 / 2.2);

        printf("lux: %.2f, brightness: %d\n", lux, brightness);

        // bit-banging here

        usleep(200000);
    }

    return 0;
}

