#define I2C_ADDR 0x23
#define GPIO_PATH "/sys/class/gpio/"
#define GPIO_NUM 17
#define SAMPLE_RATE 1
#define BUF_SIZE 60

static int i2c_fd, gpio_fd;
static unsigned short i2c_data;
static float buf[BUF_SIZE];
static int buf_idx = 0;

void exit_handler(int signum) {
    close(i2c_fd);
    close(gpio_fd);
    remove(GPIO_PATH "export");
    exit(0);
}

int main() {
    signal(SIGINT, exit_handler);

    // Export GPIO
    gpio_fd = open(GPIO_PATH "export", O_WRONLY);
    if (gpio_fd < 0) {
        perror("open GPIO export");
        exit(1);
    }
    write(gpio_fd, &GPIO_NUM, sizeof(GPIO_NUM));
    close(gpio_fd);

    // Set GPIO direction to output
    char gpio_dir_path[32];
    sprintf(gpio_dir_path, "%sgpio%d/direction", GPIO_PATH, GPIO_NUM);
    gpio_fd = open(gpio_dir_path, O_WRONLY);
    if (gpio_fd < 0) {
        perror("open GPIO direction");
        exit(1);
    }
    write(gpio_fd, "out", 3);
    close(gpio_fd);

    // Open I2C device
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C device");
        exit(1);
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("set I2C address");
        exit(1);
    }

    // Write initialization command
    if (write(i2c_fd, 0x10, 1) < 0) {
        perror("write I2C command");
        exit(1);
    }

    while (1) {
        // Read data
        if (read(i2c_fd, &i2c_data, sizeof(i2c_data)) < 0) {
            perror("read I2C data");
            continue;
        }

        // Convert to lux and store in buffer
        float lux = i2c_data / 1.2;
        buf[buf_idx] = lux;
        buf_idx = (buf_idx + 1) % BUF_SIZE;

        // Compute average over buffer
        float avg_lux = 0;
        for (int i = 0; i < BUF_SIZE; i++) {
            avg_lux += buf[i];
        }
        avg_lux /= BUF_SIZE;

        // Compute blink rate and clamp to [0.5, 5.0]
        float rate = 0.5 + (avg_lux / 1000) * 4.5;
        if (rate < 0.5) rate = 0.5;
        if (rate > 5.0) rate = 5.0;

        // Set GPIO value to blink at computed rate
        gpio_fd = open(gpio_dir_path, O_WRONLY);
        if (gpio_fd < 0) {
            perror("open GPIO value");
            exit(1);
        }
        int val = (int)(rate * 1000);
        write(gpio_fd, &val, sizeof(val));
        close(gpio_fd);

        // Sleep for sample rate
        sleep(SAMPLE_RATE);
    }

    return 0;
}

