#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <libgpiod.h>

#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

#define SEVEN_SEGMENT_5 0b01100111

struct gpiod_chip *chip = NULL;
struct gpiod_line *data_line = NULL, *clock_line = NULL, *latch_line = NULL;

void cleanup(void)
{
    if (data_line)
        gpiod_line_release(data_line);
    if (clock_line)
        gpiod_line_release(clock_line);
    if (latch_line)
        gpiod_line_release(latch_line);
    if (chip)
        gpiod_chip_close(chip);
}

void shift_out(unsigned char val)
{
    int i;
    for (i = 0; i < 8; i++) {
        gpiod_line_set_value(clock_line, 0);
        gpiod_line_set_value(data_line, (val >> (7 - i)) & 1);
        gpiod_line_set_value(clock_line, 1);
    }
    gpiod_line_set_value(latch_line, 1);
    usleep(1000);
    gpiod_line_set_value(latch_line, 0);
}

int main(void)
{
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    data_line = gpiod_chip_get_line(chip, DATA_PIN);
    if (!data_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return EXIT_FAILURE;
    }

    clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    if (!clock_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return EXIT_FAILURE;
    }

    latch_line = gpiod_chip_get_line(chip, LATCH_PIN);
    if (!latch_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(data_line, "data", 0) ||
        gpiod_line_request_output(clock_line, "clock", 0) ||
        gpiod_line_request_output(latch_line, "latch", 0)) {
        perror("gpiod_line_request_output");
        cleanup();
        return EXIT_FAILURE;
    }

    atexit(cleanup);

    while (1) {
        shift_out(SEVEN_SEGMENT_5);
        sleep(500);
        shift_out(0);
        sleep(500);
    }

    return EXIT_SUCCESS;
}

