#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip0"
#define LED_LINE_OFFSET 17
#define BUTTON_LINE_OFFSET 18
#define TIMEOUT_MS 1000

struct gpiod_chip *chip;
struct gpiod_line *led_line, *button_line;

void cleanup_and_exit(int sig)
{
    gpiod_line_release(led_line);
    gpiod_line_release(button_line);
    gpiod_chip_close(chip);
    exit(sig);
}

int main()
{
    int ret;

    signal(SIGINT, cleanup_and_exit);

    chip = gpiod_chip_open(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }

    led_line = gpiod_chip_get_line(chip, LED_LINE_OFFSET);
    if (!led_line) {
        perror("gpiod_chip_get_line");
        cleanup_and_exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(led_line, "led-blink", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        cleanup_and_exit(EXIT_FAILURE);
    }

    button_line = gpiod_chip_get_line(chip, BUTTON_LINE_OFFSET);
    if (!button_line) {
        perror("gpiod_chip_get_line");
        cleanup_and_exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_input_pullup(button_line, "button-pullup");
    if (ret < 0) {
        perror("gpiod_line_request_input_pullup");
        cleanup_and_exit(EXIT_FAILURE);
    }

    ret = gpiod_line_set_debounce(button_line, 50000000);
    if (ret < 0) {
        perror("gpiod_line_set_debounce");
        cleanup_and_exit(EXIT_FAILURE);
    }

    while (1) {
        ret = gpiod_line_set_value(led_line, !gpiod_line_get_value(led_line));
        if (ret < 0) {
            perror("gpiod_line_set_value");
            cleanup_and_exit(EXIT_FAILURE);
        }

        ret = gpiod_line_event_wait(button_line, TIMEOUT_MS);
        if (ret < 0) {
            perror("gpiod_line_event_wait");
            cleanup_and_exit(EXIT_FAILURE);
        }

        if (ret > 0) {
            struct gpiod_line_event event;

            ret = gpiod_line_event_read(button_line, &event);
            if (ret < 0) {
                perror("gpiod_line_event_read");
                cleanup_and_exit(EXIT_FAILURE);
            }

            if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
                ret = gpiod_line_set_value(led_line, 0);
                if (ret < 0) {
                    perror("gpiod_line_set_value");
                    cleanup_and_exit(EXIT_FAILURE);
                }

                printf("Button pressed, LED turned off and program exited.\n");
                cleanup_and_exit(EXIT_SUCCESS);
            }
        }
    }

    return 0;
}

