#include <stdio.h>
#include <signal.h>
#include <stdlib.h>
#include <pigpio.h>

volatile sig_atomic_t stop = 0;

void sigint_handler(int signo) {
    gpioWrite(5, 0);
    gpioTerminate();
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(5, PI_OUTPUT);

    struct sigaction action;
    action.sa_handler = sigint_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);

    while (!stop) {
        gpioWrite(5, 1);
        printf("LED ON\n");
        fflush(stdout);
        gpioDelay(750000);

        gpioWrite(5, 0);
        printf("LED OFF\n");
        fflush(stdout);
        gpioDelay(750000);
    }

    gpioTerminate();
    return 0;
}

