#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>
#include <time.h>

#define RED_GPIO 24
#define GREEN_GPIO 23
#define BLUE_GPIO 18

struct gpiod_line *red_line, *green_line, *blue_line;
struct gpiod_chip *chip;

void sigint_handler(int signum) {
    gpiod_line_release(red_line);
    gpiod_line_release(green_line);
    gpiod_line_release(blue_line);
    gpiod_chip_close(chip);
    printf("Exiting...\n");
    exit(0);
}

int main() {
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        return 1;
    }

    red_line = gpiod_chip_get_line(chip, RED_GPIO);
    if (!red_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    green_line = gpiod_chip_get_line(chip, GREEN_GPIO);
    if (!green_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    blue_line = gpiod_chip_get_line(chip, BLUE_GPIO);
    if (!blue_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    if (gpiod_line_request_output(red_line, "red", 0) ||
        gpiod_line_request_output(green_line, "green", 0) ||
        gpiod_line_request_output(blue_line, "blue", 0)) {
        perror("gpiod_line_request_output");
        return 1;
    }

    signal(SIGINT, sigint_handler);
    srand(time(NULL));

    while (1) {
        int red = rand() % 101;
        int green = rand() % 101;
        int blue = rand() % 101;

        gpiod_line_set_value(red_line, red);
        gpiod_line_set_value(green_line, green);
        gpiod_line_set_value(blue_line, blue);

        struct timespec ts = { .tv_sec = 0, .tv_nsec = 100000000 };
        clock_nanosleep(CLOCK_REALTIME, 0, &ts, NULL);
    }

    return 0;
}

