#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x19
#define G_FORCE_THRESHOLD 2.0

#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define OUT_X_L_A 0x28

#define GPIO_PIN 17
#define PULSE_DURATION 50

int i2c_handle = -1;
int g_force_threshold = G_FORCE_THRESHOLD * 16384;

void cleanup(int signum) {
    if (i2c_handle != -1) {
        piI2CClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if (argc > 1 && strcmp(argv[1], "-t") == 0 && argc > 2) {
        g_force_threshold = atof(argv[2]) * 16384;
    }

    if (gpioInitialise() < 0) {
        printf("Failed to initialize GPIO\n");
        return 1;
    }

    i2c_handle = piI2C(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        printf("Failed to open I2C bus\n");
        cleanup(0);
    }

    if (piI2CWriteByteData(i2c_handle, CTRL_REG1_A, 0x27) < 0) {
        printf("Failed to write to CTRL_REG1_A\n");
        cleanup(0);
    }

    if (piI2CWriteByteData(i2c_handle, CTRL_REG4_A, 0x00) < 0) {
        printf("Failed to write to CTRL_REG4_A\n");
        cleanup(0);
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    FILE *log_file = fopen("impact_log.txt", "w");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        cleanup(0);
    }

    while (1) {
        int16_t data[6];
        if (piI2CReadI2CBlockData(i2c_handle, OUT_X_L_A | 0x80, 6, (uint8_t *)data) < 0) {
            printf("Failed to read from accelerometer\n");
            cleanup(0);
        }

        int total_force = abs(data[0]) + abs(data[1]) + abs(data[2]);
        if (total_force > g_force_threshold) {
            time_t now = time(NULL);
            struct tm *local_time = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", local_time);

            fprintf(log_file, "%s: Impact detected, force: %d LSB\n", timestamp, total_force);
            fflush(log_file);

            gpioWrite(GPIO_PIN, PI_HIGH);
            usleep(PULSE_DURATION * 1000);
            gpioWrite(GPIO_PIN, PI_LOW);
        }

        usleep(100 * 1000);
    }

    fclose(log_file);
    cleanup(0);
    return 0;
}

