#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <i2c.h>

#define I2C_BUS 1
#define I2C_ADDR 0x39
#define I2C_TIMEOUT 100
#define PWM_GPIO 18
#define PWM_RANGE 255

FILE *csv_file;
int i2c_handle;

void shutdown_handler(int signum) {
    piHiLo(PWM_GPIO, 0, 0);
    i2c_close(i2c_handle);
    fclose(csv_file);
    exit(0);
}

int main() {
    if ((i2c_handle = i2c_open(I2C_BUS, I2C_ADDR, I2C_TIMEOUT)) < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return 1;
    }

    if (i2c_write_byte_data(i2c_handle, 0x0D, 0x01) < 0) {
        fprintf(stderr, "Failed to initialize sensor\n");
        return 1;
    }

    if ((csv_file = fopen("color_log.csv", "w")) == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        return 1;
    }

    fprintf(csv_file, "timestamp,als,r,g,b\n");

    signal(SIGINT, shutdown_handler);
    signal(SIGTERM, shutdown_handler);

    while (1) {
        int als, r, g, b;
        struct timespec ts;

        clock_gettime(CLOCK_REALTIME, &ts);

        if ((als = i2c_read_word_data(i2c_handle, 0x64)) < 0 ||
            (r = i2c_read_word_data(i2c_handle, 0x66)) < 0 ||
            (g = i2c_read_word_data(i2c_handle, 0x68)) < 0 ||
            (b = i2c_read_word_data(i2c_handle, 0x6A)) < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            usleep(100000);
            continue;
        }

        fprintf(csv_file, "%ld.%09ld,%d,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec, als, r, g, b);
        fflush(csv_file);

        piHiLo(PWM_GPIO, als * PWM_RANGE / 65535, 0);

        usleep(500000);
    }

    return 0;
}

