#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1F
#define I2C_READ_LEN 6
#define ACCEL_SENSITIVITY 4096.0
#define GRAVITY 9.81
#define THRESHOLD 19.62

volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

int main() {
    if (piGpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        goto cleanup;
    }

    unsigned char who_am_i[1];
    int result = i2cReadByteData(handle, 0x0D, who_am_i);
    if (result < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I: %d\n", result);
        goto cleanup;
    }
    if (who_am_i[0] != 0xC7) {
        fprintf(stderr, "Unexpected WHO_AM_I: 0x%02X\n", who_am_i[0]);
        goto cleanup;
    }

    result = i2cWriteByteData(handle, 0x2A, 0x00);
    if (result < 0) {
        fprintf(stderr, "Failed to put into standby: %d\n", result);
        goto cleanup;
    }

    result = i2cWriteByteData(handle, 0x0E, 0x00);
    if (result < 0) {
        fprintf(stderr, "Failed to configure for ±2g: %d\n", result);
        goto cleanup;
    }

    result = i2cWriteByteData(handle, 0x2A, 0x01);
    if (result < 0) {
        fprintf(stderr, "Failed to activate: %d\n", result);
        goto cleanup;
    }

    signal(SIGINT, handle_sigint);

    FILE *file = fopen("impact_log.txt", "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file.\n");
        goto cleanup;
    }

    while (!stop) {
        unsigned char data[I2C_READ_LEN];
        result = i2cReadI2CBlockData(handle, 0x01, I2C_READ_LEN, data);
        if (result < 0) {
            fprintf(stderr, "Failed to read acceleration: %d\n", result);
            continue;
        }

        int x = ((data[0] << 8) | data[1]) >> 2;
        int y = ((data[2] << 8) | data[3]) >> 2;
        int z = ((data[4] << 8) | data[5]) >> 2;

        x *= (x & 0x400) ? -1 : 1;
        y *= (y & 0x400) ? -1 : 1;
        z *= (z & 0x400) ? -1 : 1;

        x /= ACCEL_SENSITIVITY;
        y /= ACCEL_SENSITIVITY;
        z /= ACCEL_SENSITIVITY;

        x *= GRAVITY;
        y *= GRAVITY;
        z *= GRAVITY;

        double magnitude = sqrt(x * x + y * y + z * z);
        if (magnitude > THRESHOLD) {
            time_t now = time(NULL);
            struct tm *timeinfo = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(file, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, x, y, z, magnitude);
            fflush(file);
        }

        sleep(50);
    }

    fclose(file);

cleanup:
    i2cClose(handle);
    piGpioTerminate();

    return EXIT_SUCCESS;
}

