#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_FILE "/dev/i2c-1"
#define GYRO_ADDR 0x69
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define WHO_AM_I 0x0F
#define OUT_X_L 0x28
#define CAL_SAMPLES 100
#define LOG_FILE "gyro_log.txt"
#define MAX_RATE 50.0

static int i2c_fd = -1;
static FILE *log_file = NULL;

void cleanup_and_exit(int signum) {
    if (i2c_fd != -1) close(i2c_fd);
    if (log_file != NULL) fclose(log_file);
    exit(signum);
}

int main() {
    int ret;
    unsigned char buf[6];
    int16_t cal_x = 0, cal_y = 0, cal_z = 0;
    struct sigaction act;

    act.sa_handler = cleanup_and_exit;
    sigemptyset(&act.sa_mask);
    act.sa_flags = 0;
    sigaction(SIGINT, &act, NULL);
    sigaction(SIGTERM, &act, NULL);

    i2c_fd = open(I2C_FILE, O_RDWR);
    if (i2c_fd == -1) {
        perror("open");
        cleanup_and_exit(-1);
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, GYRO_ADDR);
    if (ret == -1) {
        perror("ioctl");
        cleanup_and_exit(-1);
    }

    buf[0] = CTRL_REG1;
    buf[1] = 0x0F;
    ret = write(i2c_fd, buf, 2);
    if (ret != 2) {
        perror("write");
        cleanup_and_exit(-1);
    }

    buf[0] = CTRL_REG4;
    buf[1] = 0x00;
    ret = write(i2c_fd, buf, 2);
    if (ret != 2) {
        perror("write");
        cleanup_and_exit(-1);
    }

