#include <pigpioI2C.h>

#define ADXL345_ADDR 0x53
#define ADXL345_DEVID 0x00
#define ADXL345_DATAX 0x32
#define ADXL345_CTRL1 0x2A
#define LED_GPIO 17

int i2c_handle;
FILE *log_file;

void cleanup(int signum) {
    if (i2c_handle >= 0) {
        piI2C_close(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    if ((i2c_handle = piI2C_open(1, ADXL345_ADDR)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        cleanup(0);
        return 1;
    }
    if (piI2C_writeByteData(i2c_handle, ADXL345_CTRL1, 0x08) < 0) {
        fprintf(stderr, "Failed to configure ADXL345\n");
        cleanup(0);
        return 1;
    }
    if (piI2C_readByteData(i2c_handle, ADXL345_DEVID) != 0xE5) {
        fprintf(stderr, "Invalid ADXL345 device ID\n");
        cleanup(0);
        return 1;
    }
    if ((log_file = fopen("accel_log.txt", "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup(0);
        return 1;
    }
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    int x, y, z;
    while (1) {
        if (piI2C_readI2CBlockData(i2c_handle, ADXL345_DATAX, 6, &x) < 0) {
            fprintf(stderr, "Failed to read acceleration data\n");
            continue;
        }
        y >>= 8;
        z >>= 16;
        x = (x > 32767) ? x - 65536 : x;
        y = (y > 32767) ? y - 65536 : y;
        z = (z > 32767) ? z - 65536 : z;
        double ax = (double)x / 32768.0;
        double ay = (double)y / 32768.0;
        double az = (double)z / 32768.0;
        fprintf(log_file, "%ld,%.3f,%.3f,%.3f\n", time(NULL), ax, ay, az);
        fflush(log_file);
        gpioWrite(LED_GPIO, (ax*ax + ay*ay + az*az > 4.0));
        sleep(100);
    }
    return 0;
}

