#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29

#define REG_START 0x016
#define REG_STOP 0x000
#define REG_VAL 0x0207

#define SAMPLE_INTERVAL 100
#define DOOR_OPEN_DISTANCE 100
#define LOG_FILE "distance_log.txt"

static int initialized = 0;
static int pi;
static FILE *log_file;

void init_sensor() {
    if (i2cWriteByteData(pi, I2C_BUS, I2C_ADDR, REG_START, REG_VAL) < 0) {
        printf("Failed to write to sensor\n");
        exit(1);
    }

    if (i2cWriteByteData(pi, I2C_BUS, I2C_ADDR, REG_STOP, REG_VAL) < 0) {
        printf("Failed to write to sensor\n");
        exit(1);
    }

    initialized = 1;
}

void log_distance(int distance) {
    time_t now = time(NULL);
    struct tm *local = localtime(&now);
    char buffer[80];

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", local);

    if (distance < DOOR_OPEN_DISTANCE) {
        fprintf(log_file, "%s: DOOR_OPEN\n", buffer);
    } else {
        fprintf(log_file, "%s: DOOR_CLOSED\n", buffer);
    }
}

void handle_sigint(int signum) {
    if (initialized) {
        i2cClose(pi);
    }

    fclose(log_file);
    exit(0);
}

int main() {
    int distance;

    signal(SIGINT, handle_sigint);

    pi = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (pi < 0) {
        printf("Failed to open I2C bus\n");
        exit(1);
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        exit(1);
    }

    init_sensor();

    while (1) {
        if (!initialized) {
            init_sensor();
        }

        distance = i2cReadByteData(pi, I2C_BUS, I2C_ADDR, 0x04d);
        if (distance < 0) {
            printf("Failed to read from sensor\n");
            initialized = 0;
            continue;
        }

        log_distance(distance);
        msleep(SAMPLE_INTERVAL);
    }

    return 0;
}

