void cleanup(void) {
    spiClose(spi_handle);
    fclose(csv_file);
    gpioTerminate();
}

void stop(int signum) {
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    csv_file = fopen("imu_data.csv", "w");
