        fprintf(stderr, "Failed to open CSV file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(csv_file, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");

    signal(SIGINT, stop);
    signal(SIGTERM, stop);
    atexit(cleanup);

    while (running) {
        int16_t data[6];
        for (int i = 0; i < 6; i++) {
            uint16_t reg_addr = 0x80 | (i << 3);
            uint16_t tx_data[2] = {reg_addr, 0};
            int res = spiXfer(spi_handle, (uint8_t *)tx_data, (uint8_t *)data, 4);
            if (res < 0) {
                fprintf(stderr, "SPI transfer failed: %d\n", res);
                continue;
            }
            usleep(40);
            res = spiXfer(spi_handle, (uint8_t *)tx_data, (uint8_t *)data, 4);
            if (res < 0) {
                fprintf(stderr, "SPI transfer failed: %d\n", res);
                continue;
            }
        }

        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(csv_file, "%ld.%09ld,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n", ts.tv_sec, ts.tv_nsec,
                data[0]*GYRO_SENSITIVITY, data[1]*GYRO_SENSITIVITY, data[2]*GYRO_SENSITIVITY,
                data[3]*ACCEL_SENSITIVITY, data[4]*ACCEL_SENSITIVITY, data[5]*ACCEL_SENSITIVITY);
        fflush(csv_file);

        usleep(100000);
    }

    return EXIT_SUCCESS;
}

