#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <linux/spi/spidev.h>
#include <sys/ioctl.h>
#include <gpiod.h>

#define SPI_DEV "/dev/spidev0.0"
#define GPIO_CS 8
#define SPI_MODE 3
#define SPI_FREQ 1000000

struct gpiod_chip *gpiod_chip;
struct gpiod_line *gpiod_line;
int spi_fd;

void exit_handler(int signum) {
    gpiod_line_release(gpiod_line);
    gpiod_chip_close(gpiod_chip);
    close(spi_fd);
    exit(0);
}

int main() {
    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(1);
    }

    struct spi_ioc_transfer xfer[2];
    memset(xfer, 0, sizeof(xfer));

    gpiod_chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!gpiod_chip) {
        perror("Failed to open GPIO chip");
        exit(1);
    }

    gpiod_line = gpiod_chip_get_line(gpiod_chip, GPIO_CS);
    if (!gpiod_line) {
        perror("Failed to get GPIO line");
        exit(1);
    }

    if (gpiod_line_request_output(gpiod_line, "adis16448", 1)) {
        perror("Failed to request GPIO line");
        exit(1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        exit(1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_FREQ) < 0) {
        perror("Failed to set SPI frequency");
        exit(1);
    }

    signal(SIGINT, exit_handler);
    signal(SIGTERM, exit_handler);

    while (1) {
        for (int reg = 0x04; reg <= 0x0E; reg += 2) {
            uint16_t txbuf[2] = { reg | 0x80, 0 };
            uint16_t rxbuf[2] = { 0, 0 };

            xfer[0].tx_buf = (unsigned long)txbuf;
            xfer[0].len = 2;
            xfer[1].rx_buf = (unsigned long)rxbuf;
            xfer[1].len = 2;

            if (ioctl(spi_fd, SPI_IOC_MESSAGE(2), xfer) < 0) {
                perror("Failed to perform SPI transfer");
                exit(1);
            }

            int value = (rxbuf[0] << 8) | rxbuf[1];
            if (reg <= 0x08) {
                printf("Gyroscope %c: %.3f dps\n", "XYZ"[reg/2 - 2], value * 0.02);
            } else {
                printf("Accelerometer %c: %.4f g\n", "XYZ"[reg/2 - 5], value * 0.00025);
            }
        }

        usleep(100000);
    }

    return 0;
}

