#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000

#define ADIS16448_READ 0x8000
#define X_GYRO_OUT 0x04
#define Y_GYRO_OUT 0x06
#define Z_GYRO_OUT 0x08
#define X_ACCL_OUT 0x0A
#define Y_ACCL_OUT 0x0C
#define Z_ACCL_OUT 0x0E

#define GYRO_SCALE 0.05
#define ACCL_SCALE 0.00025

static int spi_handle = -1;

void sig_handler(int signo) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    exit(signo);
}

int main() {
    int pi = pigpio_start(NULL, NULL);
    if (pi < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel: %s\n", pigpio_error());
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);

    unsigned short data[2];
    while (1) {
        // Read gyroscope x
        data[0] = ADIS16448_READ | X_GYRO_OUT;
        data[1] = 0x0000;
        if (spiXfer(spi_handle, data, data, 2*16) < 0) {
            fprintf(stderr, "Failed to read gyroscope x: %s\n", pigpio_error());
            sig_handler(EXIT_FAILURE);
        }
        printf("Gyroscope x: %.2f deg/sec\n", (float)data[1]*GYRO_SCALE);

        // Read gyroscope y
        data[0] = ADIS16448_READ | Y_GYRO_OUT;
        data[1] = 0x0000;
        if (spiXfer(spi_handle, data, data, 2*16) < 0) {
            fprintf(stderr, "Failed to read gyroscope y: %s\n", pigpio_error());
            sig_handler(EXIT_FAILURE);
        }
        printf("Gyroscope y: %.2f deg/sec\n", (float)data[1]*GYRO_SCALE);

        // Read gyroscope z
        data[0] = ADIS16448_READ | Z_GYRO_OUT;
        data[1] = 0x0000;
        if (spiXfer(spi_handle, data, data, 2*16) < 0) {
            fprintf(stderr, "Failed to read gyroscope z: %s\n", pigpio_error());
            sig_handler(EXIT_FAILURE);
        }
        printf("Gyroscope z: %.2f deg/sec\n", (float)data[1]*GYRO_SCALE);

        // Read accelerometer x
        data[0] = ADIS16448_READ | X_ACCL_OUT;
        data[1] = 0x0000;
        if (spiXfer(spi_handle, data, data, 2*16) < 0) {
            fprintf(stderr, "Failed to read accelerometer x: %s\n", pigpio_error());
            sig_handler(EXIT_FAILURE);
        }
        printf("Accelerometer x: %.4f g\n", (float)data[1]*ACCL_SCALE);

        // Read accelerometer y
        data[0] = ADIS16448_READ | Y_ACCL_OUT;
        data[1] = 0x0000;
        if (spiXfer(spi_handle, data, data, 2*16) < 0) {
            fprintf(stderr, "Failed to read accelerometer y: %s\n", pigpio_error());
            sig_handler(EXIT_FAILURE);
        }
        printf("Accelerometer y: %.4f g\n", (float)data[1]*ACCL_SCALE);

        // Read accelerometer z
        data[0] = ADIS16448_READ | Z_ACCL_OUT;
        data[1] = 0x0000;
        if (spiXfer(spi_handle, data, data, 2*16) < 0) {
            fprintf(stderr, "Failed to read accelerometer z: %s\n", pigpio_error());
            sig_handler(EXIT_FAILURE);
        }
        printf("Accelerometer z: %.4f g\n", (float)data[1]*ACCL_SCALE);

        sleep(0.1);
    }

    return EXIT_SUCCESS;
}

