int i2c_read(int reg, uint8_t *buf, int len) {
    struct i2c_msg msgs[2] = {
        {MPU6886_ADDR, 0, 1, &reg},
        {MPU6886_ADDR, I2C_M_RD, len, buf},
    };
    if (ioctl(fd, I2C_RDWR, msgs) < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_write(int reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    struct i2c_msg msgs[1] = {
        {MPU6886_ADDR, 0, 2, buf},
    };
    if (ioctl(fd, I2C_RDWR, msgs) < 0) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Open failed: %s\n", strerror(errno));
        return 1;
    }

    signal(SIGINT, exit_handler);

    uint8_t buf[1];
    int retries = 3;
    while (retries--) {
        if (i2c_read(MPU6886_WHOAMI_REG, buf, 1) < 0) continue;
        if (buf[0] == MPU6886_WHOAMI_VAL) break;
    }
    if (retries < 0) {
        fprintf(stderr, "Sensor absent\n");
        exit_handler(0);
    }

    if (i2c_write(MPU6886_PWR_MGMT_1, 0x00) < 0 ||
        i2c_write(MPU6886_ACCEL_CONFIG, 0x00) < 0 ||
        i2c_write(MPU6886_GYRO_CONFIG, 0x00) < 0) {
        exit_handler(0);
    }

    while (1) {
        uint8_t accel[6], gyro[6];
        if (i2c_read(MPU6886_ACCEL_DATA, accel, 6) < 0 ||
            i2c_read(MPU6886_GYRO_DATA, gyro, 6) < 0) {
            fprintf(stderr, "Read failed, retrying...\n");
            continue;
        }

        int16_t *accel_data = (int16_t *)accel;
        int16_t *gyro_data = (int16_t *)gyro;
        printf("Accel: X=%d, Y=%d, Z=%d, Gyro: X=%d, Y=%d, Z=%d\n",
               accel_data[0], accel_data[1], accel_data[2],
               gyro_data[0], gyro_data[1], gyro_data[2]);

        usleep(50000);
    }

    return 0;
}

