#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define ADXL345_I2C_BUS 1
#define ADXL345_I2C_ADDR 0x53
#define ADXL345_DEV_ID 0xE5
#define ADXL345_REG_DEV_ID 0x00
#define ADXL345_REG_DATA_FORMAT 0x31
#define ADXL345_FULL_RES 0x08
#define ADXL345_RANGE_2G 0x00
#define ADXL345_SCALE 256.0
#define ACC_THRESHOLD 2.5
#define LED_PIN 17
#define LOG_FILE "impact_log.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static int led_on = 0;

void cleanup(int sig) {
    if (i2c_handle >= 0) {
        piI2CClose(i2c_handle);
    }
    if (led_on) {
        gpioWrite(LED_PIN, 0);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    piGpioInitialise();
    exit(0);
}

int main() {
    int ret;
    unsigned char buf[6];
    double x, y, z, acc_mag;
    struct timespec ts;

    if (piGpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    i2c_handle = piI2C(ADXL345_I2C_BUS, ADXL345_I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }

    ret = piI2CReadByteData(i2c_handle, ADXL345_REG_DEV_ID);
    if (ret < 0 || ret != ADXL345_DEV_ID) {
        fprintf(stderr, "ADXL345 not found or wrong device ID: %d\n", ret);
        return 1;
    }

    ret = piI2CWriteByteData(i2c_handle, ADXL345_REG_DATA_FORMAT, ADXL345_FULL_RES | ADXL345_RANGE_2G);
    if (ret < 0) {
        fprintf(stderr, "Failed to set data format: %d\n", ret);
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        ret = piI2CReadI2CBlockData(i2c_handle, 0x32, 6, buf);
        if (ret < 0) {
            fprintf(stderr, "Failed to read acceleration data: %d\n", ret);
            cleanup(0);
        }

        x = ((buf[0] << 8) | buf[1]) / ADXL345_SCALE;
        y = ((buf[2] << 8) | buf[3]) / ADXL345_SCALE;
        z = ((buf[4] << 8) | buf[5]) / ADXL345_SCALE;

        acc_mag = sqrt(x*x + y*y + z*z);

        if (acc_mag > ACC_THRESHOLD) {
            clock_gettime(CLOCK_REALTIME, &ts);
            fprintf(log_file, "%ld.%09ld: %f, %f, %f\n", ts.tv_sec, ts.tv_nsec, acc_mag, x, y, z);
            fflush(log_file);

            gpioWrite(LED_PIN, 1);
            led_on = 1;
            sleep(500);
            gpioWrite(LED_PIN, 0);
            led_on = 0;
        }
    }

    cleanup(0);
    return 0;
}

