#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68
#define I2C_HANDLE -1
#define WHO_AM_I_REG 0x75
#define WHO_AM_I_VAL 0x12
#define PWR_MGMT_1_REG 0x6B
#define ACCEL_CONFIG_REG 0x1C
#define GYRO_CONFIG_REG 0x1B
#define ACCEL_DATA_REG 0x3B
#define GYRO_DATA_REG 0x43
#define CSV_FILE "imu_log.csv"

FILE *csv_file;

void sigint_handler(int signo) {
    if (I2C_HANDLE >= 0) {
        if (i2cClose(I2C_HANDLE) < 0) {
            fprintf(stderr, "Failed to close I2C handle\n");
        }
    }
    if (csv_file != NULL) {
        if (fclose(csv_file) != 0) {
            fprintf(stderr, "Failed to close CSV file\n");
        }
    }
    if (gpioTerminate() < 0) {
        fprintf(stderr, "Failed to terminate pigpio\n");
    }
    exit(0);
}

int main() {
    int handle, ret;
    unsigned char buf[1], val[1];
    unsigned char accel_data[6], gyro_data[6];
    struct sigaction action;

    action.sa_handler = sigint_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return 1;
    }

    buf[0] = PWR_MGMT_1_REG;
    if (i2cWrite(handle, buf, 1) < 0) {
        fprintf(stderr, "Failed to write to PWR_MGMT_1 register\n");
        return 1;
    }

    buf[0] = ACCEL_CONFIG_REG;
    if (i2cWrite(handle, buf, 1) < 0) {
        fprintf(stderr, "Failed to write to ACCEL_CONFIG register\n");
        return 1;
    }

    buf[0] = GYRO_CONFIG_REG;
    if (i2cWrite(handle, buf, 1) < 0) {
        fprintf(stderr, "Failed to write to GYRO_CONFIG register\n");
        return 1;
    }

    buf[0] = WHO_AM_I_REG;
    if (i2cWrite(handle, buf, 1) < 0) {
        fprintf(stderr, "Failed to write to WHO_AM_I register\n");
        return 1;
    }

    if (i2cRead(handle, val, 1) < 0) {
        fprintf(stderr, "Failed to read from WHO_AM_I register\n");
        return 1;
    }

    if (val[0] != WHO_AM_I_VAL) {
        fprintf(stderr, "Unexpected device ID\n");
        return 1;
    }

    csv_file = fopen(CSV_FILE, "w");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file for writing\n");
        return 1;
    }

    while (1) {
        buf[0] = ACCEL_DATA_REG;
        if (i2cWrite(handle, buf, 1) < 0) {
            fprintf(stderr, "Failed to write to ACCEL_DATA register\n");
            return 1;
        }

        if (i2cRead(handle, accel_data, 6) < 0) {
            fprintf(stderr, "Failed to read from ACCEL_DATA register\n");
            return 1;
        }

        buf[0] = GYRO_DATA_REG;
        if (i2cWrite(handle, buf, 1) < 0) {
            fprintf(stderr, "Failed to write to GYRO_DATA register\n");
            return 1;
        }

        if (i2cRead(handle, gyro_data, 6) < 0) {
            fprintf(stderr, "Failed to read from GYRO_DATA register\n");
            return 1;
        }

        fprintf(csv_file, "%ld,%d,%d,%d,%d,%d,%d,%d,%d\n",
                gpioMillis(),
                accel_data[0], accel_data[1], accel_data[2],
                gyro_data[0], gyro_data[1], gyro_data[2]);

        usleep(100000);
    }

    return 0;
}

