        cleanup_and_exit(-1);
    }

    ret = read(i2c_fd, &who_am_i, 1);
    if (ret != 1 || who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "sensor not found\n");
        cleanup_and_exit(-1);
    }

    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (gpio_chip == NULL) {
