        perror("gpiod_chip_get_line");
        cleanup_and_exit(-1);
    }

    ret = gpiod_line_request_output(led_line, "accel_led", 0);
    if (ret != 0) {
        perror("gpiod_line_request_output");
        cleanup_and_exit(-1);
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        cleanup_and_exit(-1);
    }

    while (1) {
        lseek(i2c_fd, ACCEL_REG, SEEK_SET);
