        if (ret != 2) {
            perror("read x");
            cleanup_and_exit(-1);
        }

        lseek(i2c_fd, ACCEL_REG + 2, SEEK_SET);
        ret = read(i2c_fd, &y, 2);
        if (ret != 2) {
            perror("read y");
            cleanup_and_exit(-1);
        }

        lseek(i2c_fd, ACCEL_REG + 4, SEEK_SET);
        ret = read(i2c_fd, &z, 2);
        if (ret != 2) {
            perror("read z");
            cleanup_and_exit(-1);
        }

        magnitude = sqrt(x * x + y * y + z * z);
        if (magnitude > THRESHOLD) {
            clock_gettime(CLOCK_REALTIME, &ts);
            fprintf(log_file, "%ld.%09ld\n", ts.tv_sec, ts.tv_nsec);
            fflush(log_file);

            gpiod_line_set_value(led_line, 1);
            usleep(LED_ON_TIME);
            gpiod_line_set_value(led_line, 0);
        }

        usleep(100000);
    }

    return 0;
}

