static FILE *csv_file = NULL;

void write_csv_header(void)
{
    fprintf(csv_file, "timestamp,x,y,z\n");
}

void close_files(int signum)
{
    if (i2c_file_desc != -1)
        close(i2c_file_desc);
    if (csv_file != NULL)
        fclose(csv_file);
    exit(signum);
}

int main(void)
{
    struct i2c_msg msgs[2];
    uint8_t reg_addr;
    uint16_t data;
    struct timespec ts;
    struct tm *timeinfo;
    char timestamp[20];
    int ret;

    signal(SIGINT, close_files);
    signal(SIGTERM, close_files);

    i2c_file_desc = open("/dev/i2c-1", O_RDWR);
    if (i2c_file_desc < 0) {
        perror("open i2c-1");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(i2c_file_desc, I2C_SLAVE, SENSOR_ADDR);
    if (ret < 0) {
        perror("ioctl set slave addr");
        exit(EXIT_FAILURE);
    }

    csv_file = fopen(FILENAME, "a");
    if (csv_file == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    if (ftell(csv_file) == 0)
        write_csv_header();

    while (1) {
        for (int i = 0; i < 3; i++) {
            reg_addr = i + REG_X;
            msgs[0].addr = SENSOR_ADDR;
            msgs[0].flags = 0;
            msgs[0].len = 1;
            msgs[0].buf = &reg_addr;
            msgs[1].addr = SENSOR_ADDR;
            msgs[1].flags = I2C_M_RD;
            msgs[1].len = 2;
            msgs[1].buf = (uint8_t *)&data;

            ret = i2c_smbus_read_word_data(i2c_file_desc, reg_addr);
            if (ret < 0) {
                fprintf(stderr, "i2c read failed\n");
                continue;
            }
            data = (uint16_t)ret;

            clock_gettime(CLOCK_REALTIME, &ts);
            timeinfo = localtime(&ts.tv_sec);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(csv_file, "%s,%u\n", timestamp, data);
            fflush(csv_file);
        }
        sleep(1);
    }

    return 0;
}

