    if (!gpio_chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, ADXL345_GPIO_LINE);
    if (!gpio_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    ret = gpiod_line_request_falling_edge_events(gpio_line, "adxl345");
    if (ret) {
        perror("gpiod_line_request_falling_edge_events");
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return 1;
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, ADXL345_I2C_ADDR);
    if (ret) {
        perror("ioctl");
        return 1;
    }

    reg = ADXL345_REG_DEVID;
    ret = write(i2c_fd, &reg, 1);
    if (ret != 1) {
        perror("write");
        return 1;
    }

    ret = read(i2c_fd, &reg, 1);
    if (ret != 1) {
        perror("read");
        return 1;
    }

    if (reg != ADXL345_DEVID) {
        fprintf(stderr, "ADXL345 not found\n");
        return 1;
    }

    reg = ADXL345_REG_POWER_CTL;
    ret = write(i2c_fd, &reg, 1);
    if (ret != 1) {
        perror("write");
        return 1;
    }

    reg = ADXL345_POWER_CTL_STANDBY;
    ret = write(i2c_fd, &reg, 1);
    if (ret != 1) {
        perror("write");
        return 1;
    }

    reg = ADXL345_REG_THRESH_FF;
    ret = write(i2c_fd, &reg, 1);
    if (ret != 1) {
        perror("write");
        return 1;
    }

    reg = ADXL345_THRESH_FF;
    ret = write(i2c_fd, &reg, 1);
    if (ret != 1) {
        perror("write");
        return 1;
    }

    reg = ADXL345_REG_TIME_FF;
    ret = write(i2c_fd, &reg, 1);
    if (ret != 1) {
        perror("write");
        return 1;
    }

    reg = ADXL345_TIME_FF;
    ret = write(i2c_fd, &reg, 1);
    if (ret != 1) {
        perror("write");
        return 1;
    }

    reg = ADXL345_REG_INT_ENABLE;
    ret = write(i2c_fd, &reg, 1);
    if (ret != 1) {
        perror("write");
        return 1;
    }

    reg = ADXL345_INT_ENABLE_FF;
    ret = write(i2c_fd, &reg, 1);
    if (ret != 1) {
        perror("write");
        return 1;
    }

    reg = ADXL345_REG_INT_MAP;
    ret = write(i2c_fd, &reg, 1);
    if (ret != 1) {
        perror("write");
        return 1;
    }

    reg = ADXL345_INT_MAP_FF;
    ret = write(i2c_fd, &reg, 1);
    if (ret != 1) {
        perror("write");
        return 1;
    }

    reg = ADXL345_REG_POWER_CTL;
    ret = write(i2c_fd, &reg, 1);
    if (ret != 1) {
        perror("write");
        return 1;
    }

    reg = ADXL345_POWER_CTL_MEASURE;
    ret = write(i2c_fd, &reg, 1);
    if (ret != 1) {
        perror("write");
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    fprintf(log_file, "Timestamp,X,Y,Z\n");

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    while (1) {
        ret = gpiod_line_event_wait(gpio_line, NULL);
        if (ret < 0) {
            perror("gpiod_line_event_wait");
            return 1;
        }

        if (ret == 0)
            continue;

        reg = ADXL345_REG_INT_SOURCE;
        ret = write(i2c_fd, &reg, 1);
        if (ret != 1) {
            perror("write");
            return 1;
        }

        ret = read(i2c_fd, &reg, 1);
        if (ret != 1) {
            perror("read");
            return 1;
        }

        if (!(reg & 0x04))
            continue;

        reg = ADXL345_REG_DATAX0;
        ret = write(i2c_fd, &reg, 1);
        if (ret != 1) {
            perror("write");
            return 1;
        }

        ret = read(i2c_fd, buf, 6);
        if (ret != 6) {
            perror("read");
            return 1;
        }

        ts = localtime(&(time_t){.tv_sec = time(NULL)});
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", ts);

        fprintf(log_file, "%s.%03ld,%d,%d,%d\n", timestamp, ts->tm_usec / 1000,
                buf[0] | (buf[1] << 8), buf[2] | (buf[3] << 8),
                buf[4] | (buf[5] << 8));

        fflush(log_file);
    }

    return 0;
