#define WHO_AM_I_VAL 0x69
#define CTRL_REG1 0x10
#define CTRL_REG1_VAL 0xD7
#define CTRL_REG2 0x11
#define CTRL_REG2_VAL 0x00
#define CTRL_REG3 0x12
#define CTRL_REG3_VAL 0x00
#define CTRL_REG4 0x13
#define CTRL_REG4_VAL 0x00
#define CTRL_REG5 0x14
#define CTRL_REG5_VAL 0x00
#define STATUS_REG 0x17
#define OUT_X_L_ADDR 0x18
#define OUT_Y_L_ADDR 0x1A
#define OUT_Z_L_ADDR 0x1C
#define ACC_THRESHOLD 0.2
#define IMPACT_THRESHOLD 2.5
#define WINDOW_SIZE 104

FILE *log_file;
int i2c_handle;

enum state {IDLE, FREEFALL, IMPACT};
enum state state = IDLE;

void handle_sig(int sig) {
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) piI2CClose(i2c_handle);
    exit(0);
}

