    signal(SIGINT, handle_sig);
    signal(SIGTERM, handle_sig);

    log_file = fopen("motion_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    i2c_handle = piI2C(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        handle_sig(0);
        return 1;
    }

    unsigned char who_am_i;
    if (piI2CRead(i2c_handle, WHO_AM_I_REG, &who_am_i, 1) != 1 || who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "Failed WHO_AM_I check\n");
        handle_sig(0);
        return 1;
    }

    if (piI2CWrite(i2c_handle, CTRL_REG1, &CTRL_REG1_VAL, 1) != 1 ||
        piI2CWrite(i2c_handle, CTRL_REG2, &CTRL_REG2_VAL, 1) != 1 ||
        piI2CWrite(i2c_handle, CTRL_REG3, &CTRL_REG3_VAL, 1) != 1 ||
        piI2CWrite(i2c_handle, CTRL_REG4, &CTRL_REG4_VAL, 1) != 1 ||
        piI2CWrite(i2c_handle, CTRL_REG5, &CTRL_REG5_VAL, 1) != 1) {
        fprintf(stderr, "Failed to configure sensor\n");
        handle_sig(0);
        return 1;
    }

    unsigned char status, data[6];
    double x, y, z, mag;
    time_t t;
    struct tm *lt;
    while (1) {
        if (piI2CRead(i2c_handle, STATUS_REG, &status, 1) != 1 || !(status & 0x08)) {
            fprintf(stderr, "Failed to read sensor data\n");
            handle_sig(0);
            return 1;
        }

        if (piI2CRead(i2c_handle, OUT_X_L_ADDR, data, 6) != 6) {
            fprintf(stderr, "Failed to read sensor data\n");
            handle_sig(0);
            return 1;
        }

        x = ((data[1] << 8) | data[0]) / 16384.0;
        y = ((data[3] << 8) | data[2]) / 16384.0;
        z = ((data[5] << 8) | data[4]) / 16384.0;
        mag = sqrt(x*x + y*y + z*z);

        t = time(NULL);
        lt = localtime(&t);
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%.6f,%.6f,%.6f,%.6f\n",
                lt->tm_year + 1900, lt->tm_mon + 1, lt->tm_mday,
                lt->tm_hour, lt->tm_min, lt->tm_sec, x, y, z, mag);

        switch (state) {
        case IDLE:
            if (mag < ACC_THRESHOLD) state = FREEFALL;
            break;
        case FREEFALL:
            if (mag > IMPACT_THRESHOLD) state = IMPACT;
            else if (mag > ACC_THRESHOLD) state = IDLE;
            break;
        case IMPACT:
            if (mag < ACC_THRESHOLD) state = FREEFALL;
            break;
        }
    }

    return 0;
}

