#define X_GYRO_OUT_REG 0x14
#define DEVICE_ID 0x3F5A
#define LOG_FILE "gyro_log.csv"

FILE *log_file;
int spi_handle;

void handle_sigint(int signo) {
    fclose(log_file);
    spi_end(spi_handle);
    piStop();
    exit(0);
}

int main() {
    int pi = piGpioInitialise();
    if (pi < 0) {
        printf("Failed to initialize pigpio: %d\n", pi);
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        printf("Failed to open SPI: %d\n", spi_handle);
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        return 1;
    }

    fprintf(log_file, "timestamp,angle_rate_x\n");

    signal(SIGINT, handle_sigint);

    unsigned char cmd[2] = {0x00, 0x00};
    unsigned char resp[2] = {0x00, 0x00};

    cmd[0] = WHO_AM_I_REG;
    int ret = spiXfer(spi_handle, cmd, resp, 4);
    if (ret != 0) {
        printf("SPI transfer failed: %d\n", ret);
        return 1;
    }

    if ((resp[0] << 8 | resp[1]) != DEVICE_ID) {
        printf("Unexpected device ID: 0x%04X\n", resp[0] << 8 | resp[1]);
        return 1;
    }

    while (1) {
        cmd[0] = X_GYRO_OUT_REG | 0x80;
        ret = spiXfer(spi_handle, cmd, resp, 4);
        if (ret != 0) {
            printf("SPI transfer failed: %d\n", ret);
            return 1;
        }

        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d,%.3f\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, (resp[0] << 8 | resp[1]) * 0.0305);
        fflush(log_file);

        sleep(10);
    }

    return 0;
}

