This code initializes the pigpio library, opens the SPI channel, and opens the log file. It then sets up a signal handler for SIGINT to close the SPI handle, terminate the pigpio process, and close the log file. The main loop reads the WHO_AM_I register to verify the device ID, then enters an infinite loop where it reads the X_GYRO_OUT register, logs the timestamp and scaled angular rate to the file, and sleeps for 10 ms.

code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x69
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define WHO_AM_I 0x0F
#define OUT_X_L 0x28
#define SENSITIVITY 8.75e-3
#define SAMPLE_INTERVAL 10000
#define RETRY_LIMIT 3
#define LOG_FILE "gyro_log.csv"

static int handle;
static FILE *file;

static void cleanup(int signum) {
    fclose(file);
    piI2CSimpleClose(handle);
    gpioTerminate();
    exit(0);
}

int main() {
    int retries = 0;
    int result;
    unsigned char data[6];
    unsigned char who_am_i;
    struct timespec ts;

    handle = piI2CSimpleOpen(I2C_BUS, I2C_ADDR);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return 1;
    }

    signal(SIGINT, cleanup);

    while (retries < RETRY_LIMIT) {
        result = piI2CWriteByteData(handle, CTRL_REG1, 0x0F);
        if (result < 0) {
            fprintf(stderr, "Failed to write CTRL_REG1: %d\n", result);
            retries++;
            continue;
        }

        result = piI2CWriteByteData(handle, CTRL_REG4, 0x00);
        if (result < 0) {
            fprintf(stderr, "Failed to write CTRL_REG4: %d\n", result);
            retries++;
            continue;
        }

        result = piI2CReadByteData(handle, WHO_AM_I, &who_am_i);
        if (result < 0) {
            fprintf(stderr, "Failed to read WHO_AM_I: %d\n", result);
            retries++;
            continue;
        }

        if (who_am_i != 0xD3) {
            fprintf(stderr, "Unexpected WHO_AM_I value: 0x%02X\n", who_am_i);
            retries++;
            continue;
        }

        break;
    }

    if (retries == RETRY_LIMIT) {
        fprintf(stderr, "Failed to initialize sensor\n");
        cleanup(0);
        return 1;
    }

    file = fopen(LOG_FILE, "w");
    if (!file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup(0);
        return 1;
    }

    fprintf(file, "Timestamp,X,Y,Z\n");

    while (1) {
        result = piI2CReadI2CBlockData(handle, OUT_X_L, sizeof(data), data);
        if (result < 0) {
            fprintf(stderr, "Failed to read sensor data: %d\n", result);
            cleanup(0);
            return 1;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(file, "%ld.%09ld,%.3f,%.3f,%.3f\n", ts.tv_sec, ts.tv_nsec,
                (data[0] | (data[1] << 8)) * SENSITIVITY,
                (data[2] | (data[3] << 8)) * SENSITIVITY,
                (data[4] | (data[5] << 8)) * SENSITIVITY);

        usleep(SAMPLE_INTERVAL);
    }

    return 0;
}

