        result = piI2CReadI2CBlockData(handle, OUT_X_L, sizeof(data), data);
        if (result < 0) {
            fprintf(stderr, "Failed to read sensor data: %d\n", result);
            cleanup(0);
            return 1;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(file, "%ld.%09ld,%.3f,%.3f,%.3f\n", ts.tv_sec, ts.tv_nsec,
                (data[0] | (data[1] << 8)) * SENSITIVITY,
                (data[2] | (data[3] << 8)) * SENSITIVITY,
                (data[4] | (data[5] << 8)) * SENSITIVITY);

        usleep(SAMPLE_INTERVAL);
    }

    return 0;
}
