        return EXIT_FAILURE;
    }

    sensor1 = gpiod_chip_get_line(chip, GPIO17);
    if (!sensor1) {
        perror("gpiod_chip_get_line");
        return EXIT_FAILURE;
    }

    sensor2 = gpiod_chip_get_line(chip, GPIO27);
    if (!sensor2) {
        perror("gpiod_chip_get_line");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(sensor1, "sensor1", GPIOD_LINE_BIAS_PULL_UP) ||
        gpiod_line_request_input(sensor2, "sensor2", GPIOD_LINE_BIAS_PULL_UP)) {
        perror("gpiod_line_request_input");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen");
        return EXIT_FAILURE;
    }

    while (1) {
        value1 = gpiod_line_get_value(sensor1);
        if (value1 < 0) {
            perror("gpiod_line_get_value");
            return EXIT_FAILURE;
        }

        value2 = gpiod_line_get_value(sensor2);
        if (value2 < 0) {
            perror("gpiod_line_get_value");
            return EXIT_FAILURE;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld: Sensor 1: %d, Sensor 2: %d\n", ts.tv_sec, ts.tv_nsec, value1, value2);
        fflush(log_file);

        if (value1 && value2) {
            printf("Both sensors triggered, halting conveyor.\n");
            break;
        }

        usleep(50000);
    }

    sig_handler(0);
    return EXIT_SUCCESS;
}

