#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <math.h>
#include <time.h>

#define I2C_FILE "/dev/i2c-1"
#define SENSOR_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define WHO_AM_I_VAL 0x2A
#define CTRL_REG1_ADDR 0x2A
#define CTRL_REG1_VAL 0x12
#define DATA_REG_START 0x01
#define DATA_REG_END 0x06
#define LOG_FILE "fall_log.txt"
#define TILT_THRESHOLD 45

static int i2c_fd = -1;
static int log_fd = -1;

void cleanup_and_exit(int sig) {
    if (i2c_fd != -1) close(i2c_fd);
    if (log_fd != -1) close(log_fd);
    exit(sig);
}

int main() {
    struct sigaction action;
    action.sa_handler = cleanup_and_exit;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    i2c_fd = open(I2C_FILE, O_RDWR);
    if (i2c_fd == -1) {
        printf("Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) == -1) {
        printf("Failed to set I2C slave address: %s\n", strerror(errno));
        return 1;
    }

    unsigned char who_am_i;
    if (read(i2c_fd, &who_am_i, 1) != 1 || who_am_i != WHO_AM_I_VAL) {
        printf("Failed to verify sensor identity: %s\n", strerror(errno));
        return 1;
    }

    unsigned char ctrl_reg1 = CTRL_REG1_VAL;
    if (write(i2c_fd, &ctrl_reg1, 1) != 1) {
        printf("Failed to initialize sensor: %s\n", strerror(errno));
        return 1;
    }

    log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (log_fd == -1) {
        printf("Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    while (1) {
        unsigned char data_regs[DATA_REG_END - DATA_REG_START + 1];
        for (int i = 0; i < sizeof(data_regs); i++) {
            data_regs[i] = DATA_REG_START + i;
        }

        if (write(i2c_fd, data_regs, sizeof(data_regs)) != sizeof(data_regs)) {
            printf("Failed to read data registers: %s\n", strerror(errno));
            return 1;
        }

        unsigned char data[sizeof(data_regs) * 2];
        if (read(i2c_fd, data, sizeof(data)) != sizeof(data)) {
            printf("Failed to read data: %s\n", strerror(errno));
            return 1;
        }

        int x = (data[0] << 8 | data[1]) >> 4;
        int y = (data[2] << 8 | data[3]) >> 4;
        int z = (data[4] << 8 | data[5]) >> 4;

        double tilt_angle = atan2(x, sqrt(y*y + z*z)) * 180 / M_PI;
        if (fabs(tilt_angle) > TILT_THRESHOLD) {
            time_t t = time(NULL);
            struct tm* ts = localtime(&t);
            char timestamp[30];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", ts);

            char log_entry[100];
            sprintf(log_entry, "%s: X=%d, Y=%d, Z=%d\n", timestamp, x, y, z);

            if (write(log_fd, log_entry, strlen(log_entry)) != strlen(log_entry)) {
                printf("Failed to write to log file: %s\n", strerror(errno));
                return 1;
            }

            fflush(log_fd);
        }

        usleep(10000);
    }

    return 0;
}

