#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x1E
#define MAGNETOMETER_WHO_AM_I 0x3D
#define MAGNETOMETER_CTRL_REG1 0x20
#define MAGNETOMETER_CTRL_REG4 0x23
#define MAGNETOMETER_CTRL_REG3 0x22
#define MAGNETOMETER_X_OUT_L 0x28
#define MAGNETOMETER_READ_LENGTH 6
#define MAGNETOMETER_SENSITIVITY 0.146
#define MAGNETOMETER_CALIBRATION_OFFSET 0
#define MAGNETOMETER_CALIBRATION_SCALE 1
#define MAGNETOMETER_ALERT_THRESHOLD 800

static int i2c_file_descriptor = -1;
static FILE *log_file = NULL;

static void cleanup(int signal) {
    if (i2c_file_descriptor != -1) {
        close(i2c_file_descriptor);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

static int i2c_write_register(int file_descriptor, uint8_t register_address, uint8_t value) {
    uint8_t buffer[2] = {register_address, value};
    if (write(file_descriptor, buffer, 2) != 2) {
        perror("i2c_write_register: write");
        return -1;
    }
    return 0;
}

static int i2c_read_register(int file_descriptor, uint8_t register_address, uint8_t *value) {
    if (write(file_descriptor, &register_address, 1) != 1) {
        perror("i2c_read_register: write");
        return -1;
    }
    if (read(file_descriptor, value, 1) != 1) {
        perror("i2c_read_register: read");
        return -1;
    }
    return 0;
}

int main() {
    int i2c_file_descriptor;
    uint8_t who_am_i;
    uint8_t buffer[MAGNETOMETER_READ_LENGTH];
