#define ADXL354_PARTID_VAL 0x1D
#define ADXL354_XDATA_REG 0x08
#define ADXL354_YDATA_REG 0x0B
#define ADXL354_ZDATA_REG 0x0E
#define ADXL354_RANGE_VAL 0x08
#define ADXL354_READ_CMD 0x80
#define ADXL354_MULTI_BYTE_CMD 0x40
#define ADXL354_SENSITIVITY 0.0000039
#define LOG_INTERVAL 100
#define MAX_RETRIES 3

static int spi_handle;
static FILE *log_file;

void shutdown_handler(int signum) {
    fclose(log_file);
    spi_close(spi_handle);
    pi_stop();
    exit(0);
}

int main() {
    int ret, retries = 0;
    unsigned char cmd[2], resp[3];
    long x_val, y_val, z_val;
    struct timespec ts;

    spi_handle = spi_open(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel: %d\n", spi_handle);
        return 1;
    }

    log_file = fopen("vibration_log.txt", "w");
    if (!log_file) {
