    signal(SIGINT, shutdown_handler);
    signal(SIGTERM, shutdown_handler);

    cmd[0] = ADXL354_RESET_REG | ADXL354_READ_CMD | ADXL354_MULTI_BYTE_CMD;
    cmd[1] = ADXL354_RESET_VAL;
    while ((ret = spi_xfer(spi_handle, cmd, cmd, 2)) < 0 && retries < MAX_RETRIES) {
        fprintf(stderr, "Failed to write to reset register: %d\n", ret);
        retries++;
    }
    if (ret < 0) {
        fprintf(stderr, "Failed to write to reset register after %d retries\n", retries);
        goto error;
    }
    usleep(1000);

    cmd[0] = ADXL354_POWER_CTL | ADXL354_READ_CMD;
    cmd[1] = 0;
    while ((ret = spi_xfer(spi_handle, cmd, cmd, 2)) < 0 && retries < MAX_RETRIES) {
        fprintf(stderr, "Failed to write to power control register: %d\n", ret);
        retries++;
    }
    if (ret < 0) {
        fprintf(stderr, "Failed to write to power control register after %d retries\n", retries);
        goto error;
    }

