    cmd[1] = 0;
    while ((ret = spi_xfer(spi_handle, cmd, cmd, 2)) < 0 && retries < MAX_RETRIES) {
        fprintf(stderr, "Failed to read stable register: %d\n", ret);
        retries++;
    }
    if (ret < 0) {
        fprintf(stderr, "Failed to read stable register after %d retries\n", retries);
        goto error;
    }

