    cmd[1] = ADXL354_PARTID_VAL;
    while ((ret = spi_xfer(spi_handle, cmd, cmd, 2)) < 0 && retries < MAX_RETRIES) {
        fprintf(stderr, "Failed to read part ID: %d\n", ret);
        retries++;
    }
    if (ret < 0) {
        fprintf(stderr, "Failed to read part ID after %d retries\n", retries);
        goto error;
    }

