        }
        z_val = (resp[0] << 16) | (resp[1] << 8) | resp[2];
        if (z_val & 0x800000)
            z_val |= 0xFF000000;
        else
            z_val &= 0x00FFFFFF;

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld: %.6f %.6f %.6f\n", ts.tv_sec, ts.tv_nsec,
                x_val * ADXL354_SENSITIVITY, y_val * ADXL354_SENSITIVITY, z_val * ADXL354_SENSITIVITY);
        usleep(LOG_INTERVAL * 1000);
    }

error:
    fclose(log_file);
    spi_close(spi_handle);
    pi_stop();
    return 1;
}

