#define Y_GYRO 0x06
#define Z_GYRO 0x08
#define X_ACCL 0x0A
#define Y_ACCL 0x0C
#define Z_ACCL 0x0E

#define GYRO_SCALE 0.05
#define ACCL_SCALE 0.0025

FILE *log_file;
int spi_handle;

void sigint_handler(int signum) {
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    struct timespec ts;
    struct spi_msg msg;
    unsigned char data[4];
    double x_gyro, y_gyro, z_gyro, x_accel, y_accel, z_accel;

    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI: %d\n", spi_handle);
        exit(-1);
    }

    log_file = fopen("imu_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        exit(-1);
    }

    fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");

    signal(SIGINT, sigint_handler);

    while (1) {
        for (int reg = X_GYRO; reg <= Z_ACCL; reg += 2) {
            data[0] = reg | 0x80;
            data[1] = 0;
            data[2] = 0;
            data[3] = 0;

            msg.spi_chip_select = 0;
            msg.spi_mode = SPI_MODE;
            msg.spi_baud = SPI_BAUD;
            msg.tx_buf = data;
            msg.rx_buf = data;
            msg.len = 4;

            int ret = spiXfer(spi_handle, &msg, 1);
            if (ret < 0) {
                fprintf(stderr, "spiXfer failed: %d\n", ret);
                continue;
            }

            switch (reg) {
                case X_GYRO:
                    x_gyro = ((data[2] << 8) | data[3]) * GYRO_SCALE;
                    break;
                case Y_GYRO:
                    y_gyro = ((data[2] << 8) | data[3]) * GYRO_SCALE;
