                    x_accel = ((data[2] << 8) | data[3]) * ACCL_SCALE;
                    break;
                case Y_ACCL:
                    y_accel = ((data[2] << 8) | data[3]) * ACCL_SCALE;
                    break;
                case Z_ACCL:
                    z_accel = ((data[2] << 8) | data[3]) * ACCL_SCALE;
                    break;
            }
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n", ts.tv_sec, ts.tv_nsec, x_gyro, y_gyro, z_gyro, x_accel, y_accel, z_accel);

        usleep(10000);
    }

    return 0;
}

