#include <libgpiod.h>
#include <signal.h>
#include <time.h>

#define GPIO_CHIP "gpiochip4"
#define GPIO_LINE 17

struct gpiod_line *line;
struct gpiod_chip *chip;

void sigint_handler(int signum) {
    printf("\nReceived SIGINT, releasing GPIO line and closing chip...\n");
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    exit(0);
}

void check_and_handle_error(int ret, const char *operation) {
    if (ret < 0) {
        printf("%s failed: %s\n", operation, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(1);
    }
}

int main() {
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        printf("Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        exit(1);
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        printf("Failed to get line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        exit(1);
    }

    ret = gpiod_line_request_input(line, "obstacle_detected");
    check_and_handle_error(ret, "gpiod_line_request_input");

    signal(SIGINT, sigint_handler);

    while (1) {
        ret = gpiod_line_get_value(line);
        check_and_handle_error(ret, "gpiod_line_get_value");

        if (!ret) {
            time_t t = time(NULL);
            char* time_str = ctime(&t);
            time_str[strlen(time_str) - 1] = '\0';  // remove trailing newline

            printf("%s: Obstacle detected, starting self-parking sequence...\n", time_str);

            // simulate self-parking sequence
            sleep(2);

            printf("%s: Self-parking sequence completed.\n", time_str);
        }

        sleep(1);
    }

    // should never reach here
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

