#include <signal.h>
#include <gpiod.h>

#define GPIOCHIP "/dev/gpiochip0"
#define GPIO17 17
#define GPIO27 27

struct gpiod_chip *chip = NULL;
struct gpiod_line *line1 = NULL, *line2 = NULL;
struct gpiod_line_request *request = NULL;

void cleanup_and_exit(int sig)
{
    if (request)
        gpiod_line_request_release(request);
    if (line1)
        gpiod_line_close(line1);
    if (line2)
        gpiod_line_close(line2);
    if (chip)
        gpiod_chip_close(chip);
    exit(sig);
}

int main()
{
    int ret;
    unsigned int values[2];

    signal(SIGINT, cleanup_and_exit);

    chip = gpiod_chip_open(GPIOCHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        cleanup_and_exit(-1);
    }

    line1 = gpiod_chip_open_line(chip, GPIO17);
    if (!line1) {
        perror("gpiod_chip_open_line");
        cleanup_and_exit(-1);
    }

    line2 = gpiod_chip_open_line(chip, GPIO27);
    if (!line2) {
        perror("gpiod_chip_open_line");
        cleanup_and_exit(-1);
    }

    request = gpiod_line_request_two_lines(line1, "sensor1", GPIOD_LINE_REQUEST_DIRECTION_INPUT,
                                           line2, "sensor2", GPIOD_LINE_REQUEST_DIRECTION_INPUT);
    if (!request) {
        perror("gpiod_line_request_two_lines");
        cleanup_and_exit(-1);
    }

    while (1) {
        ret = gpiod_line_request_get_values(request, values);
        if (ret < 0) {
            perror("gpiod_line_request_get_values");
            cleanup_and_exit(-1);
        }

        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        printf("[%02d:%02d:%02d] Sensor 1: %s, Sensor 2: %s\n",
               tm.tm_hour, tm.tm_min, tm.tm_sec,
               values[0] ? "clear" : "obstacle",
               values[1] ? "clear" : "obstacle");

        usleep(100000);  // 100 ms
    }

    cleanup_and_exit(0);
}

