#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <libgpiod.h>
#include <linux/spi/spidev.h>

#define SPI_DEV "/dev/spidev0.0"
#define CS_GPIO 8
#define MSC_CTRL_REG 0x24
#define X_RATE_REG 0x04
#define Y_RATE_REG 0x06
#define Z_RATE_REG 0x08
#define SPI_MODE 3
#define SPI_BITS 8
#define SPI_CLK 1000000
#define DELAY_MS 100

struct gpiod_line *cs_line;
struct gpiod_chip *chip;
int spi_fd;

void cleanup_and_exit(int sig) {
    gpiod_line_release(cs_line);
    gpiod_chip_close(chip);
    close(spi_fd);
    exit(sig);
}

int main() {
    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup_and_exit(EXIT_FAILURE);
    }

    cs_line = gpiod_chip_get_line(chip, CS_GPIO);
    if (!cs_line) {
        perror("Failed to get CS line");
        cleanup_and_exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(cs_line, "CS", 1)) {
        perror("Failed to request CS line");
        cleanup_and_exit(EXIT_FAILURE);
    }

    uint8_t tx[4] = {MSC_CTRL_REG, 0x01, 0x00, 0x00};
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), tx)) {
        perror("Failed to write to SPI");
        cleanup_and_exit(EXIT_FAILURE);
    }

    signal(SIGINT, cleanup_and_exit);

    while (1) {
        usleep(DELAY_MS * 1000);

        uint8_t regs[3][3] = {{X_RATE_REG, 0, 0}, {Y_RATE_REG, 0, 0}, {Z_RATE_REG, 0, 0}};
        for (int i = 0; i < 3; i++) {
            if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), regs[i])) {
                perror("Failed to read from SPI");
                cleanup_and_exit(EXIT_FAILURE);
            }

            int16_t rate = (regs[i][1] << 8) | regs[i][2];
            printf("Rate (reg 0x%02X): %.2f deg/sec\n", regs[i][0], rate * 0.02);
        }
    }

    return 0;
}

