#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x6B
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VAL 0x6B
#define CTRL1_XL_REG 0x10
#define CTRL1_XL_VAL 0x42
#define CTRL2_G_REG 0x11
#define CTRL2_G_VAL 0x42
#define OUTX_L_G_REG 0x22
#define GYRO_SENSITIVITY 0.00875
#define ACCEL_SENSITIVITY 0.000061

static int i2c_handle = -1;

void cleanup_and_exit(int sig) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    int ret;

    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "gpioInitialise() failed with error code %d\n", ret);
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen() failed with error code %d\n", i2c_handle);
        return 1;
    }

    unsigned char who_am_i;
    ret = i2cReadByteDirect(i2c_handle, WHO_AM_I_REG, &who_am_i);
    if (ret != 0 || who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: 0x%02X\n", who_am_i);
        return 1;
    }

    ret = i2cWriteByteDirect(i2c_handle, CTRL1_XL_REG, CTRL1_XL_VAL);
    if (ret != 0) {
        fprintf(stderr, "CTRL1_XL write failed with error code %d\n", ret);
        return 1;
    }

    ret = i2cWriteByteDirect(i2c_handle, CTRL2_G_REG, CTRL2_G_VAL);
    if (ret != 0) {
        fprintf(stderr, "CTRL2_G write failed with error code %d\n", ret);
        return 1;
    }

    signal(SIGINT, cleanup_and_exit);

    unsigned char data[12];
    while (1) {
        ret = i2cBurstRead(i2c_handle, OUTX_L_G_REG, data, sizeof(data));
        if (ret != sizeof(data)) {
            fprintf(stderr, "i2cBurstRead() failed with error code %d\n", ret);
            return 1;
        }

        float gyro_x = (data[0] | (data[1] << 8)) * GYRO_SENSITIVITY;
        float gyro_y = (data[2] | (data[3] << 8)) * GYRO_SENSITIVITY;
        float gyro_z = (data[4] | (data[5] << 8)) * GYRO_SENSITIVITY;
        float accel_x = (data[6] | (data[7] << 8)) * ACCEL_SENSITIVITY;
        float accel_y = (data[8] | (data[9] << 8)) * ACCEL_SENSITIVITY;
        float accel_z = (data[10] | (data[11] << 8)) * ACCEL_SENSITIVITY;

        printf("Gyro: %.3f %.3f %.3f, Accel: %.3f %.3f %.3f\n",
               gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);

        sleep(100);
    }

    return 0;
}

