#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1D
#define I2C_WHOAMI_REG 0x0D
#define I2C_WHOAMI_VAL 0xC7

#define I2C_CTRL_REG1 0x2A
#define I2C_CTRL_REG2 0x2B
#define I2C_M_CTRL_REG1 0x5B
#define I2C_M_CTRL_REG2 0x5C
#define I2C_DATA_REG 0x01

static int i2c_handle = -1;

void cleanup(int signum) {
    if (i2c_handle >= 0) {
        if (i2cClose(i2c_handle) < 0) {
            fprintf(stderr, "Failed to close I2C handle: %s\n", strerror(errno));
        }
    }
    if (piGpioInitialise() < 0) {
        fprintf(stderr, "Failed to terminate pigpio: %s\n", strerror(errno));
    }
    exit(signum);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if (piGpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        cleanup(-1);
    }

    int whoami;
    if (i2cReadWord(i2c_handle, I2C_WHOAMI_REG, &whoami) < 0) {
        fprintf(stderr, "Failed to read WHOAMI register: %s\n", strerror(errno));
        cleanup(-1);
    }
