#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/time.h>
#include <math.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define ADXL345_ADDR 0x53
#define DATA_START_REG 0x32
#define TILT_THRESHOLD 30.0
#define LOG_FILE "/var/log/tilt_events.log"

int i2c_file = -1;
FILE *log_file = NULL;

void exit_handler(int signum) {
    if (i2c_file != -1) {
        close(i2c_file);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

void log_tilt_event(double x, double y, double z) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    fprintf(log_file, "%ld.%06ld: Tilt angles: X = %.2f, Y = %.2f, Z = %.2f\n",
            tv.tv_sec, tv.tv_usec, x, y, z);
    fflush(log_file);
}

int main() {
    struct i2c_msg msgs[2];
    uint8_t reg_addr = DATA_START_REG;
    uint8_t data[6];

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file == -1) {
        perror("Failed to open I2C device");
        exit_handler(0);
    }

    if (ioctl(i2c_file, I2C_SLAVE, ADXL345_ADDR) == -1) {
        perror("Failed to set I2C slave address");
        exit_handler(0);
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit_handler(0);
    }

    signal(SIGINT, exit_handler);

    while (1) {
        msgs[0].addr = ADXL345_ADDR;
        msgs[0].flags = 0;
        msgs[0].len = 1;
        msgs[0].buf = &reg_addr;

        msgs[1].addr = ADXL345_ADDR;
        msgs[1].flags = I2C_M_RD;
        msgs[1].len = sizeof(data);
        msgs[1].buf = data;

        if (i2c_file == -1 ||
            write(i2c_file, msgs, 2) == -1) {
            perror("Failed to read from I2C device");
            exit_handler(0);
        }

        double x = (data[0] << 8 | data[1]) / 16384.0;
        double y = (data[2] << 8 | data[3]) / 16384.0;
        double z = (data[4] << 8 | data[5]) / 16384.0;

        double tilt_x = atan2(x, sqrt(y*y + z*z)) * 180.0 / M_PI;
        double tilt_y = atan2(y, sqrt(x*x + z*z)) * 180.0 / M_PI;
        double tilt_z = atan2(z, sqrt(x*x + y*y)) * 180.0 / M_PI;

        if (tilt_x > TILT_THRESHOLD || tilt_y > TILT_THRESHOLD || tilt_z > TILT_THRESHOLD) {
            log_tilt_event(tilt_x, tilt_y, tilt_z);
        }

        usleep(100000);
    }

    exit_handler(0);
}

