#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_SOUND 17
#define INTERVAL_MS 1
#define WINDOW_MS 5000
#define DELAY_MS 1000

volatile sig_atomic_t stop = 0;

void handle_signal(int signum) {
    stop = 1;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    int threshold = atoi(argv[1]);
    if (threshold <= 0) {
        fprintf(stderr, "Threshold must be a positive integer.\n");
        return 1;
    }

    int pi = gpioInitialise();
    if (pi < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", pigpio_error(pi));
        return 1;
    }

    if (gpioSetMode(GPIO_SOUND, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode: %s\n", pigpio_error(gpioSetMode(GPIO_SOUND, PI_INPUT)));
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop) {
        int count = 0;
        struct timespec start, end;
        clock_gettime(CLOCK_REALTIME, &start);

        while (1) {
            if (stop) break;

            if (gpioRead(GPIO_SOUND) > 0) {
                count++;
            }

            clock_gettime(CLOCK_REALTIME, &end);
            int elapsed_ms = (end.tv_sec - start.tv_sec) * 1000 + (end.tv_nsec - start.tv_nsec) / 1000000;

            if (elapsed_ms >= WINDOW_MS) break;

            usleep(INTERVAL_MS * 1000);
        }

        if (count > threshold) {
            printf("ALERT: High-reading count exceeded threshold (%d > %d)\n", count, threshold);
        } else {
            printf("Status: High-reading count %d did not exceed threshold %d\n", count, threshold);
        }

        usleep(DELAY_MS * 1000);
    }

    gpioTerminate();
    return 0;
}

