#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <libgpiod.h>

#define GPIO17 17
#define GPIO27 27
#define LOCK_DURATION 5

struct gpiod_chip *chip;
struct gpiod_line *line17, *line27;
FILE *log_file;
int should_exit;

void exit_handler(int signum) {
    should_exit = 1;
}

void close_resources() {
    gpiod_line_release(line17);
    gpiod_line_release(line27);
    gpiod_chip_close(chip);
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    srand(time(NULL));
    chip = gpiod_chip_open_by_name("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %m\n");
        return 1;
    }

    line17 = gpiod_chip_get_line(chip, GPIO17);
    if (!line17) {
        fprintf(stderr, "Failed to get GPIO line %d: %m\n", GPIO17);
        return 1;
    }

    line27 = gpiod_chip_get_line(chip, GPIO27);
    if (!line27) {
        fprintf(stderr, "Failed to get GPIO line %d: %m\n", GPIO27);
        return 1;
    }

    if (gpiod_line_request_output(line17, "door_access", 0) ||
        gpiod_line_request_output(line27, "door_access", 0)) {
        fprintf(stderr, "Failed to request GPIO line as output: %m\n");
        return 1;
    }

    signal(SIGINT, exit_handler);
    signal(SIGTERM, exit_handler);

    log_file = fopen("access_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open access log file: %m\n");
        return 1;
    }

    while (!should_exit) {
        int code = 100000 + rand() % 900000;
        printf("Enter the code: ");
        int entered_code;
        char buffer[1024];
        if (scanf("%d", &entered_code) != 1) {
            fgets(buffer, 1024, stdin);
            printf("Access denied\n");
            continue;
        }

        if (entered_code == code) {
            time_t now = time(NULL);
            struct tm *timeinfo = localtime(&now);
            char timestamp[20];
            strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(log_file, "%s,%06d\n", timestamp, code);
            fflush(log_file);

            gpiod_line_set_value(line17, 1);
            sleep(LOCK_DURATION);
            gpiod_line_set_value(line17, 0);
        } else {
            printf("Access denied\n");
        }
    }

    gpiod_line_set_value(line17, 0);
    gpiod_line_set_value(line27, 0);
    close_resources();

    return 0;
}

