#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SENSOR_ADDR 0x23
#define SENSOR_CMD 0x21
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "light_log.txt"

void log_entry(int lux_value) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    FILE *f = fopen(LOG_FILE, "a");
    if (f == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    fprintf(f, "Timestamp: %d-%02d-%02d %02d:%02d:%02d, Lux: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, lux_value);
    fclose(f);
}

void handle_sigint(int signum) {
    printf("Interrupted by Ctrl+C\n");
    exit(EXIT_SUCCESS);
}

int main() {
    int i2c_file, ret;
    unsigned char cmd = SENSOR_CMD;
    unsigned char data[2];

    i2c_file = open(I2C_BUS, O_RDWR);
    if (i2c_file < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(i2c_file, I2C_SLAVE, SENSOR_ADDR);
    if (ret < 0) {
        perror("Failed to set sensor address");
        goto cleanup;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        ret = write(i2c_file, &cmd, 1);
        if (ret < 0) {
            perror("Failed to write sensor command");
            goto cleanup;
        }

        usleep(180000);  // 180 ms

        ret = read(i2c_file, data, 2);
        if (ret < 0) {
            perror("Failed to read sensor data");
            goto cleanup;
        }

        int raw_value = (data[0] << 8) | data[1];
        int lux_value = (raw_value * 5) / 6;

        log_entry(lux_value);

        sleep(5);  // 5 seconds
    }

cleanup:
    close(i2c_file);
    exit(EXIT_FAILURE);
}

