#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1E

#define REG_CONF_A 0x00
#define REG_CONF_B 0x01
#define REG_MODE 0x02

#define CONF_A_VAL 0x70
#define CONF_B_VAL 0x20
#define MODE_VAL 0x00

#define SAMPLE_WINDOW 100
#define PRINT_INTERVAL 500

static int pi_h;
static int i2c_h;
static int sample_count = 0;
static long long offset_x = 0, offset_y = 0, offset_z = 0;

static void sig_handler(int signo) {
    if (i2c_h >= 0) {
        piI2C_close(i2c_h);
    }
    if (pi_h > 0) {
        gpioTerminate();
    }
    exit(0);
}

int main() {
    pi_h = gpioInitialise();
    if (pi_h <= 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return 1;
    }

    i2c_h = piI2C_open(I2C_BUS, I2C_ADDR);
    if (i2c_h < 0) {
        fprintf(stderr, "piI2C_open failed\n");
        gpioTerminate();
        return 1;
    }

    if (piI2C_writeByteData(i2c_h, REG_CONF_A, CONF_A_VAL) < 0 ||
        piI2C_writeByteData(i2c_h, REG_CONF_B, CONF_B_VAL) < 0 ||
        piI2C_writeByteData(i2c_h, REG_MODE, MODE_VAL) < 0) {
        fprintf(stderr, "I2C write failed\n");
        piI2C_close(i2c_h);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        int16_t x, y, z;
        if (piI2C_readI2CBlockData(i2c_h, 0x03, 6, (uint8_t*)&x) < 0) {
            fprintf(stderr, "I2C read failed\n");
            continue;
        }
        y = ((int16_t*) &x)[1];
        z = ((int16_t*) &x)[2];

        offset_x += x;
        offset_y += y;
        offset_z += z;
        sample_count++;

        if (sample_count >= SAMPLE_WINDOW) {
            offset_x /= SAMPLE_WINDOW;
            offset_y /= SAMPLE_WINDOW;
            offset_z /= SAMPLE_WINDOW;
            sample_count = 0;
        }

        if (sample_count % (SAMPLE_WINDOW / 2) == 0) {
            x -= offset_x;
            y -= offset_y;
            z -= offset_z;
            printf("X: %d, Y: %d, Z: %d\n", x, y, z);
        }

        sleep(PRINT_INTERVAL / 1000);
    }

    return 0;
}

