#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <libgpiod.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x1D
#define GPIO_LINE 23
#define ACCEL_ODR 0x57
#define ACCEL_FS 0x00
#define INT1_THS 0x7D
#define INT1_DUR 0x00
#define INT1_CFG 0x2A
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define INT1_CFG_REG 0x30
#define WHO_AM_I_REG 0x0F
#define OUT_X_L_A 0x28
#define SAMPLE_SIZE 6
#define BUFFER_SIZE 64

struct gpiod_line *line;
struct gpiod_chip *chip;
int i2c_fd;
long long buffer[BUFFER_SIZE][SAMPLE_SIZE];
int buffer_head = 0;
int buffer_tail = 0;

void handle_sigint(int signum) {
    // Disable the accelerometer
    if (i2c_smbus_write_byte_data(i2c_fd, CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Failed to disable the accelerometer: %s\n", strerror(errno));
    }

    // Close the I2C file descriptor
    if (close(i2c_fd) < 0) {
        fprintf(stderr, "Failed to close I2C file descriptor: %s\n", strerror(errno));
    }

    // Exit cleanly
    exit(0);
}

int main() {
    // Open the I2C device
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        return 1;
    }

    // Verify the WHO_AM_I register
    if (i2c_smbus_read_byte_data(i2c_fd, WHO_AM_I_REG) != 0x49) {
        fprintf(stderr, "Failed to verify WHO_AM_I register\n");
        return 1;
    }

    // Configure the accelerometer
    if (i2c_smbus_write_byte_data(i2c_fd, CTRL_REG1, ACCEL_ODR) < 0 ||
        i2c_smbus_write_byte_data(i2c_fd, CTRL_REG4, ACCEL_FS) < 0 ||
        i2c_smbus_write_byte_data(i2c_fd, INT1_CFG_REG, INT1_CFG) < 0 ||
        i2c_smbus_write_byte_data(i2c_fd, INT1_CFG_REG + 1, INT1_THS) < 0 ||
        i2c_smbus_write_byte_data(i2c_fd, INT1_CFG_REG + 2, INT1_DUR) < 0) {
        fprintf(stderr, "Failed to configure accelerometer: %s\n", strerror(errno));
        return 1;
    }

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Request the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        return 1;
