#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <termios.h>

#define GPIO_LOCK1 17
#define GPIO_LOCK2 27
#define BAUD_RATE 9600
#define EXPECTED_CODE "123456"
#define TIMEOUT_MS 5000
#define UNLOCK_SECONDS 2

int pi_handle;
int serial_handle1;
int serial_handle2;

void exit_handler(int signum) {
    // Set both locks to LOW (locked)
    if (gpioWrite(GPIO_LOCK1, 0) != 0 || gpioWrite(GPIO_LOCK2, 0) != 0) {
        fprintf(stderr, "Failed to set GPIO to LOW: %s\n", strerror(errno));
    }
    // Close serial ports
    piSerialClose(serial_handle1);
    piSerialClose(serial_handle2);
    // Terminate pigpio
    gpioTerminate();
    exit(0);
}

int main() {
    char code1[7] = {0};
    char code2[7] = {0};
    struct termios options;

    // Initialize pigpio
    pi_handle = gpioInitialise();
    if (pi_handle <= 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        exit(1);
    }

    // Set GPIO as outputs, default to LOW (locked)
    if (gpioSetMode(GPIO_LOCK1, PI_OUTPUT) != 0 || gpioSetMode(GPIO_LOCK2, PI_OUTPUT) != 0 ||
        gpioWrite(GPIO_LOCK1, 0) != 0 || gpioWrite(GPIO_LOCK2, 0) != 0) {
        fprintf(stderr, "Failed to set GPIO mode or write: %s\n", strerror(errno));
        exit(1);
    }

    // Open serial ports
    serial_handle1 = piSerialOpen("/dev/ttyAMA0", BAUD_RATE);
    if (serial_handle1 <= 0) {
        fprintf(stderr, "Failed to open serial port 1: %s\n", strerror(errno));
        exit(1);
    }
    serial_handle2 = piSerialOpen("/dev/ttyAMA1", BAUD_RATE);
    if (serial_handle2 <= 0) {
        fprintf(stderr, "Failed to open serial port 2: %s\n", strerror(errno));
        exit(1);
    }

    // Set non-blocking read
    tcgetattr(serial_handle1, &options);
    options.c_cc[VMIN] = 0;
    options.c_cc[VTIME] = TIMEOUT_MS / 10;
    tcsetattr(serial_handle1, TCSANOW, &options);
    tcgetattr(serial_handle2, &options);
    options.c_cc[VMIN] = 0;
    options.c_cc[VTIME] = TIMEOUT_MS / 10;
    tcsetattr(serial_handle2, TCSANOW, &options);

    // Register exit handler for SIGINT/SIGTERM
    signal(SIGINT, exit_handler);
    signal(SIGTERM, exit_handler);

    while (1) {
        // Read from serial ports
        int n1 = piSerialRead(serial_handle1, code1, 6);
        int n2 = piSerialRead(serial_handle2, code2, 6);

        // Check for read errors
        if (n1 < 0 || n2 < 0) {
            fprintf(stderr, "Serial read error: %s\n", strerror(errno));
            exit(1);
        }

        // Check for timeout
        if (n1 == 0 && n2 == 0) {
            continue;
        }

        // Check for non-numeric characters
        for (int i = 0; i < n1; i++) {
            if (code1[i] < '0' || code1[i] > '9') {
                code1[i] = 0;
            }
        }
        for (int i = 0; i < n2; i++) {
            if (code2[i] < '0' || code2[i] > '9') {
                code2[i] = 0;
            }
        }

        // Compare codes
        if (strcmp(code1, EXPECTED_CODE) == 0 && strcmp(code2, EXPECTED_CODE) == 0) {
            // Unlock both locks
            if (gpioWrite(GPIO_LOCK1, 1) != 0 || gpioWrite(GPIO_LOCK2, 1) != 0) {
                fprintf(stderr, "Failed to set GPIO to HIGH: %s\n", strerror(errno));
                exit(1);
            }
            sleep(UNLOCK_SECONDS);
            // Lock both locks
            if (gpioWrite(GPIO_LOCK1, 0) != 0 || gpioWrite(GPIO_LOCK2, 0) != 0) {
                fprintf(stderr, "Failed to set GPIO to LOW: %s\n", strerror(errno));
                exit(1);
            }
        }
    }

    return 0;
}

