    syslog(LOG_INFO, "Shutting down...");
    gpiod_line_set_value(relay_line, 0);
    syslog(LOG_INFO, "Relay de-energized.");
    gpiod_line_release(pir_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
    closelog();
    exit(0);
}

int main() {
    openlog("doorstrike", LOG_PID, LOG_USER);
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open(GPIOCHIP);
    if (!chip) {
        syslog(LOG_ERR, "Failed to open %s: %m", GPIOCHIP);
        exit(1);
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        syslog(LOG_ERR, "Failed to get line %d: %m", PIR_PIN);
        exit(1);
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        syslog(LOG_ERR, "Failed to get line %d: %m", RELAY_PIN);
        exit(1);
    }

    if (gpiod_line_request_input(pir_line, "pir")) {
        syslog(LOG_ERR, "Failed to request input on line %d: %m", PIR_PIN);
        exit(1);
    }

    if (gpiod_line_request_output(relay_line, "relay", 0)) {
        syslog(LOG_ERR, "Failed to request output on line %d: %m", RELAY_PIN);
        exit(1);
    }

    while (1) {
        usleep(50000);
        pir_value = gpiod_line_get_value(pir_line);
        if (pir_value == 1) {
            if (difftime(time(NULL), last_motion_time) > 10) {
                syslog(LOG_WARNING, "Potential malfunction: PIR sensor remained active for more than 10 seconds.");
                gpiod_line_set_value(relay_line, 0);
                syslog(LOG_INFO, "Relay de-energized due to failsafe.");
            } else {
                if (relay_value != 1) {
                    gpiod_line_set_value(relay_line, 1);
                    syslog(LOG_INFO, "Relay energized.");
                    relay_value = 1;
                }
            }
            last_motion_time = time(NULL);
        } else {
            if (relay_value != 0) {
                gpiod_line_set_value(relay_line, 0);
                syslog(LOG_INFO, "Relay de-energized.");
                relay_value = 0;
            }
        }
    }

    return 0;
}
```

This code will open the GPIO chip, request the PIR sensor and relay control lines, and then continuously monitor the PIR sensor. When motion is detected, it will energize the relay for a 1-second strike duration, then de-energize it. If the PIR sensor remains active for more than 10 seconds, it will de-energize the relay and log a warning. It also implements a clean shutdown on SIGINT/SIGTERM, releasing all GPIO lines, closing the chip, closing the log, and exiting.

