            current_action = 2;
        } else {
            current_relais++;
        }
    } else if (current_action == 2) {
        // Pause
        if (current_relais == GPIO_RELAIS4) {
            current_relais = GPIO_RELAIS1;
        } else {
            current_relais++;
        }
    }
