#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define ACCEL_CONFIG 0xA4
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define BUF_LEN 100

struct buf_entry {
    double x, y, z;
};

struct mpu6050_dev {
    int fd;
    struct buf_entry buf[BUF_LEN];
    int buf_head, buf_tail;
};

static struct mpu6050_dev dev;

static int mpu6050_write(int reg, uint8_t val) {
    if (ioctl(dev.fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave: %s\n", strerror(errno));
        return -1;
    }

    uint8_t buf[2] = {reg, val};
    if (write(dev.fd, buf, 2) != 2) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int mpu6050_read(int reg, uint8_t *buf, int len) {
    if (ioctl(dev.fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave: %s\n", strerror(errno));
        return -1;
    }

    if (write(dev.fd, &reg, 1) != 1) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (read(dev.fd, buf, len) != len) {
        fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void mpu6050_sample(union sigval sv) {
    uint8_t raw[6];
    if (mpu6050_read(ACCEL_XOUT_H, raw, 6) < 0)
        exit(EXIT_FAILURE);

    int16_t accel_x = (raw[0] << 8) | raw[1];
    int16_t accel_y = (raw[2] << 8) | raw[3];
    int16_t accel_z = (raw[4] << 8) | raw[5];

    dev.buf[dev.buf_head].x = (double)accel_x / 16384.0;
    dev.buf[dev.buf_head].y = (double)accel_y / 16384.0;
    dev.buf[dev.buf_head].z = (double)accel_z / 16384.0;

    dev.buf_head = (dev.buf_head + 1) % BUF_LEN;
    if (dev.buf_head == dev.buf_tail)
        dev.buf_tail = (dev.buf_tail + 1) % BUF_LEN;
}

static void mpu6050_init(void) {
    if (mpu6050_write(PWR_MGMT_1, 0x00) < 0 ||
        mpu6050_write(ACCEL_CONFIG, 0x00) < 0)
        exit(EXIT_FAILURE);

    struct sigevent ev;
    ev.sigev_notify = SIGEV_THREAD;
    ev.sigev_value.sival_ptr = NULL;
    ev.sigev_notify_function = mpu6050_sample;

    timer_t timer;
    if (timer_create(CLOCK_REALTIME, &ev, &timer) < 0) {
        fprintf(stderr, "Failed to create timer: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    struct itimerspec its;
    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = 10000000;  // 100 Hz
    its.it_interval = its.it_value;

    if (timer_settime(timer, 0, &its, NULL) < 0) {
        fprintf(stderr, "Failed to set timer: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

static void mpu6050_cleanup(int signum) {
    close(dev.fd);
    exit(EXIT_SUCCESS);
}

int main(void) {
    dev.fd = open(I2C_BUS, O_RDWR);
    if (dev.fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    signal(SIGINT, mpu6050_cleanup);
    signal(SIGTERM, mpu6050_cleanup);

    mpu6050_init();

    while (1)
        sleep(1);

    return EXIT_SUCCESS;
}

