    if (signo == SIGINT || signo == SIGTERM) {
        printf("Signal received, turning off relays and exiting...\n");
        gpiod_line_set_value(line_18, 0);
        gpiod_line_set_value(line_23, 0);
        gpiod_line_set_value(line_24, 0);
        gpiod_line_set_value(line_25, 0);
        gpiod_line_release(line_18);
        gpiod_line_release(line_23);
        gpiod_line_release(line_24);
        gpiod_line_release(line_25);
        gpiod_chip_close(chip);
        exit(0);
    }
}

int main() {
    struct timespec ts_start, ts_end;
    double time_taken;

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    line_18 = gpiod_chip_get_line(chip, GPIO_LINE_18);
    if (!line_18) {
        perror("gpiod_chip_get_line");
        return 1;
