#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE_18 18
#define GPIO_LINE_23 23
#define GPIO_LINE_24 24
#define GPIO_LINE_25 25

struct gpiod_line *line_18, *line_23, *line_24, *line_25;
struct gpiod_chip *chip;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        printf("Signal received, turning off relays and exiting...\n");
        gpiod_line_set_value(line_18, 0);
        gpiod_line_set_value(line_23, 0);
        gpiod_line_set_value(line_24, 0);
        gpiod_line_set_value(line_25, 0);
        gpiod_line_release(line_18);
        gpiod_line_release(line_23);
        gpiod_line_release(line_24);
        gpiod_line_release(line_25);
        gpiod_chip_close(chip);
        exit(0);
    }
}

int main() {
    struct timespec ts_start, ts_end;
    double time_taken;

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    line_18 = gpiod_chip_get_line(chip, GPIO_LINE_18);
    if (!line_18) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    line_23 = gpiod_chip_get_line(chip, GPIO_LINE_23);
    if (!line_23) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    line_24 = gpiod_chip_get_line(chip, GPIO_LINE_24);
    if (!line_24) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    line_25 = gpiod_chip_get_line(chip, GPIO_LINE_25);
    if (!line_25) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    if (gpiod_line_request_output(line_18, "line_18", 0) < 0) {
        perror("gpiod_line_request_output");
        return 1;
    }

    if (gpiod_line_request_output(line_23, "line_23", 0) < 0) {
        perror("gpiod_line_request_output");
        return 1;
    }

    if (gpiod_line_request_output(line_24, "line_24", 0) < 0) {
        perror("gpiod_line_request_output");
        return 1;
    }

    if (gpiod_line_request_output(line_25, "line_25", 0) < 0) {
        perror("gpiod_line_request_output");
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts_start);
        gpiod_line_set_value(line_18, 1);
        sleep(2);
        gpiod_line_set_value(line_18, 0);

        clock_gettime(CLOCK_MONOTONIC, &ts_end);
        time_taken = (ts_end.tv_sec - ts_start.tv_sec) * 1e9;
        time_taken = (time_taken + (ts_end.tv_nsec - ts_start.tv_nsec)) * 1e-9;
        printf("2 seconds interval: %f seconds\n", time_taken);

        clock_gettime(CLOCK_MONOTONIC, &ts_start);
        gpiod_line_set_value(line_23, 1);
        sleep(3);
        gpiod_line_set_value(line_23, 0);

        clock_gettime(CLOCK_MONOTONIC, &ts_end);
        time_taken = (ts_end.tv_sec - ts_start.tv_sec) * 1e9;
        time_taken = (time_taken + (ts_end.tv_nsec - ts_start.tv_nsec)) * 1e-9;
        printf("3 seconds interval: %f seconds\n", time_taken);

        clock_gettime(CLOCK_MONOTONIC, &ts_start);
        gpiod_line_set_value(line_24, 1);
        sleep(5);
        gpiod_line_set_value(line_24, 0);

        clock_gettime(CLOCK_MONOTONIC, &ts_end);
        time_taken = (ts_end.tv_sec - ts_start.tv_sec) * 1e9;
        time_taken = (time_taken + (ts_end.tv_nsec - ts_start.tv_nsec)) * 1e-9;
        printf("5 seconds interval: %f seconds\n", time_taken);

        clock_gettime(CLOCK_MONOTONIC, &ts_start);
        gpiod_line_set_value(line_25, 1);
        sleep(7);
        gpiod_line_set_value(line_25, 0);

        clock_gettime(CLOCK_MONOTONIC, &ts_end);
        time_taken = (ts_end.tv_sec - ts_start.tv_sec) * 1e9;
        time_taken = (time_taken + (ts_end.tv_nsec - ts_start.tv_nsec)) * 1e-9;
        printf("7 seconds interval: %f seconds\n", time_taken);
    }

    gpiod_line_release(line_18);
    gpiod_line_release(line_23);
    gpiod_line_release(line_24);
    gpiod_line_release(line_25);
    gpiod_chip_close(chip);

    return 0;
}
```

This code initializes the GPIO lines and sets up a signal handler for SIGINT and SIGTERM. It then enters an infinite loop where it toggles each relay on and off with a sleep interval corresponding to the unique prime number seconds (2, 3, 5, 7 seconds respectively). It measures the actual sleep time taken for each interval and prints it to the console. On receiving a signal, it turns off all relays, releases the GPIO lines, and closes the GPIO chip before exiting.

