#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_PIN 17
#define RELAY_PIN 27
#define POLL_INTERVAL_MS 100
#define ALARM_DURATION_MS 3000

volatile sig_atomic_t stop = 0;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        stop = 1;
    }
}

int main() {
    int pi;
    if ((pi = pigpio_start()) < 0) {
        printf("pigpio_start() failed\n");
        return -1;
    }

    if (gpio_set_mode(pi, SENSOR_PIN, PI_INPUT) < 0) {
        printf("gpio_set_mode(sensor) failed\n");
        return -1;
    }

    if (gpio_set_mode(pi, RELAY_PIN, PI_OUTPUT) < 0) {
        printf("gpio_set_mode(relay) failed\n");
        return -1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    int sensor_value = 0;
    int alarm_start = 0;
    FILE *log_file = fopen("alarm_log.txt", "a");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        return -1;
    }

    while (!stop) {
        int current_sensor_value = gpio_read(pi, SENSOR_PIN);
        if (current_sensor_value < 0) {
            printf("gpio_read() failed\n");
            return -1;
        }

        if (current_sensor_value == 1 && sensor_value == 0) {
            // Debounce
            sensor_value = current_sensor_value;
            alarm_start = millis();
            if (gpio_write(pi, RELAY_PIN, 1) < 0) {
                printf("gpio_write() failed\n");
                return -1;
            }

            time_t now = time(NULL);
            struct tm *local = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", local);
            fprintf(log_file, "%s\n", timestamp);
        } else if (sensor_value == 1 && millis() - alarm_start >= ALARM_DURATION_MS) {
            // Cooldown
            sensor_value = 0;
            if (gpio_write(pi, RELAY_PIN, 0) < 0) {
                printf("gpio_write() failed\n");
                return -1;
            }
        }

        delay(POLL_INTERVAL_MS);
    }

    fclose(log_file);
    pigpio_stop(pi);

    return 0;
}

