#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <signal.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x68
#define I2C_WHOAMI_REG 0x75
#define I2C_WHOAMI_VAL 0x68
#define I2C_PWR_MGMT_1 0x6B
#define I2C_GYRO_XOUT 0x43
#define GYRO_SENSITIVITY 131.0
#define GYRO_THRESHOLD 50.0
#define BUF_SIZE 100

int fd;
int buf_head = 0;
int buf_tail = 0;
float buf[BUF_SIZE];

void callback(void) {
    printf("Angular velocity exceeded threshold!\n");
}

void sigint_handler(int signum) {
    close(fd);
    exit(0);
}

int i2c_write_reg(uint8_t reg, uint8_t data) {
    if (write(fd, &reg, 1) != 1 || write(fd, &data, 1) != 1) {
        fprintf(stderr, "I2C write failed\n");
        return -1;
    }
    return 0;
}

int i2c_read_reg(uint8_t reg, uint8_t *data) {
    if (write(fd, &reg, 1) != 1 || read(fd, data, 1) != 1) {
        fprintf(stderr, "I2C read failed\n");
        return -1;
    }
    return 0;
}

int main(void) {
    fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        return -1;
    }

    if (i2c_write_reg(I2C_PWR_MGMT_1, 0x00) < 0) {
        return -1;
    }

    uint8_t whoami;
    if (i2c_read_reg(I2C_WHOAMI_REG, &whoami) < 0 || whoami != I2C_WHOAMI_VAL) {
        fprintf(stderr, "Failed to verify device\n");
        return -1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        uint8_t data[6];
        if (i2c_read_reg(I2C_GYRO_XOUT, data) < 0) {
            return -1;
        }

        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[2] << 8) | data[3];
        int16_t z = (data[4] << 8) | data[5];

        float mag = sqrt(x*x + y*y + z*z) / GYRO_SENSITIVITY;
        buf[buf_head] = mag;
        buf_head = (buf_head + 1) % BUF_SIZE;
        if (buf_head == buf_tail) {
            buf_tail = (buf_tail + 1) % BUF_SIZE;
        }

        if (mag > GYRO_THRESHOLD) {
            callback();
        }
    }

    return 0;
}

