#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SERIAL_PORT "/dev/serial0"
#define BAUD_RATE 9600
#define READ_TIMEOUT 1000
#define LOG_FILE "co2_log.json"
#define ERROR_LOG "co2_error.log"

volatile sig_atomic_t stop = 0;
FILE *log_file, *error_log;

void sig_handler(int signo) {
    stop = 1;
}

void log_error(const char *msg) {
    time_t t = time(NULL);
    fprintf(error_log, "%s at %s", msg, ctime(&t));
    fflush(error_log);
}

int main() {
    int pi, ser, bytes_read, i, checksum, co2;
    unsigned char response[9], command[9] = {0xFF,0x01,0x86,0x00,0x00,0x00,0x00,0x00,0x79};
    struct timespec ts = {0, 100000000};
    struct sigaction sigIntHandler;

    sigIntHandler.sa_handler = sig_handler;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_flags = 0;
    sigaction(SIGINT, &sigIntHandler, NULL);
    sigaction(SIGTERM, &sigIntHandler, NULL);

    pi = pigpio_start();
    if (pi < 0) {
        log_error("Failed to start pigpio");
        return EXIT_FAILURE;
    }

    ser = serOpen(SERIAL_PORT, BAUD_RATE, 0);
    if (ser < 0) {
        log_error("Failed to open serial port");
        pigpio_stop(pi);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_error("Failed to open log file");
        serClose(ser);
        pigpio_stop(pi);
        return EXIT_FAILURE;
    }

    error_log = fopen(ERROR_LOG, "a");
    if (error_log == NULL) {
        log_error("Failed to open error log file");
        fclose(log_file);
        serClose(ser);
        pigpio_stop(pi);
        return EXIT_FAILURE;
    }

    while (!stop) {
        serWrite(ser, command, 9);
        nanosleep(&ts, NULL);

        bytes_read = 0;
        clock_t start = clock();
        while (bytes_read < 9 && !stop) {
            int available = serDataAvailable(ser);
            if (available > 0) {
                int n = serRead(ser, response + bytes_read, 9 - bytes_read);
                if (n < 0) {
                    log_error("Failed to read from serial port");
                    break;
                }
                bytes_read += n;
            }
            if (clock() - start > READ_TIMEOUT * CLOCKS_PER_SEC / 1000) {
                log_error("Read timeout");
                break;
            }
        }

        if (bytes_read == 9) {
            checksum = 0;
            for (i = 0; i < 8; i++) {
                checksum += response[i];
            }
            checksum = ((~checksum) + 1) & 0xFF;

            if (checksum == response[8]) {
                co2 = (response[2] << 8) | response[3];
                time_t t = time(NULL);
                char timestamp[26];
                strftime(timestamp, 26, "%Y-%m-%dT%H:%M:%S", localtime(&t));
                fprintf(log_file, "{\"timestamp\":\"%s.%06ld\",\"co2\":%d,\"error\":false}\n", timestamp, t, co2);
                fflush(log_file);
                printf("{\"timestamp\":\"%s.%06ld\",\"co2\":%d,\"error\":false}\n", timestamp, t, co2);
            } else {
                log_error("Checksum mismatch");
            }
        }

        sleep(5);
    }

    fclose(log_file);
    fclose(error_log);
    serClose(ser);
    pigpio_stop(pi);

    return EXIT_SUCCESS;
}

