#define DEVIATION_THRESHOLD 10.0
#define SAMPLE_INTERVAL 100
#define BUFFER_SIZE 100

static int i2c_fd = -1;
static int gpio_pin = 17;
static double buffer[BUFFER_SIZE];
static int buffer_head = 0;
static int buffer_count = 0;

static void cleanup(void) {
    if (i2c_fd >= 0) {
        i2cClose(i2c_fd);
    }
    gpioTerminate();
}

static void handle_signal(int signum) {
    cleanup();
    exit(signum);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }
    gpioSetMode(gpio_pin, PI_OUTPUT);

    i2c_fd = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (i2cWriteByteData(i2c_fd, CONFIG_A, 0x70) < 0 ||
        i2cWriteByteData(i2c_fd, CONFIG_B, 0x20) < 0 ||
        i2cWriteByteData(i2c_fd, MODE, 0x00) < 0) {
        fprintf(stderr, "Failed to configure I2C device.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    unsigned char data[READ_LEN];
    while (1) {
        if (i2cReadBytes(i2c_fd, READ_START, data, READ_LEN) < 0) {
            fprintf(stderr, "Failed to read from I2C device.\n");
            continue;
        }

        int x = (data[0] << 8) | data[1];
        int y = (data[2] << 8) | data[3];
        int z = (data[4] << 8) | data[5];

        double heading = atan2(y - Y_OFFSET, x - X_OFFSET) * 180.0 / M_PI;
        if (heading < 0) {
            heading += 360.0;
        }

        buffer[buffer_head] = heading;
        buffer_head = (buffer_head + 1) % BUFFER_SIZE;
        if (buffer_count < BUFFER_SIZE) {
            buffer_count++;
        }

        double deviation = fabs(heading - TARGET_HEADING);
        if (deviation > 180.0) {
            deviation = 360.0 - deviation;
        }

        if (deviation > DEVIATION_THRESHOLD) {
            gpioWrite(gpio_pin, PI_HIGH);
        } else {
            gpioWrite(gpio_pin, PI_LOW);
        }

        usleep(SAMPLE_INTERVAL * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

