#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x23
#define GPIO_RED 17
#define GPIO_GREEN 27
#define GPIO_BLUE 22

struct gpiod_line *lines[3];
int i2c_fd;
FILE *log_file;

void cleanup_and_exit(int sig) {
    for (int i = 0; i < 3; i++) {
        gpiod_line_release(lines[i]);
    }
    close(i2c_fd);
    fclose(log_file);
    exit(sig);
}

int main() {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    struct gpiod_chip *chip = gpiod_chip_open_by_name("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, i == 0 ? GPIO_RED : (i == 1 ? GPIO_GREEN : GPIO_BLUE));
        if (!lines[i]) {
            perror("gpiod_chip_get_line");
            return 1;
        }

        if (gpiod_line_request_output(lines[i], "smart_light", 0)) {
            perror("gpiod_line_request_output");
            return 1;
        }
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR)) {
        perror("ioctl");
        return 1;
    }

    if (write(i2c_fd, (char[]){0x10}, 1) != 1) {
        perror("write");
        return 1;
    }

    log_file = fopen("lighting_log.txt", "w");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    while (1) {
        usleep(1000000);

        char buf[2];
        if (read(i2c_fd, buf, 2) != 2) {
            perror("read");
            return 1;
        }

        int lux = (buf[0] << 8) | buf[1];
        lux /= 12;

        for (int i = 0; i < 3; i++) {
            gpiod_line_set_value(lines[i], lux < 50 ? i == 0 : (lux < 150 ? i == 1 : (lux < 300 ? i == 2 : 1)));
        }

        time_t t = time(NULL);
        struct tm *tm = localtime(&t);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        fprintf(log_file, "%s, %d, %d, %d, %d\n", timestamp, lux, gpiod_line_get_value(lines[0]), gpiod_line_get_value(lines[1]), gpiod_line_get_value(lines[2]));
        fflush(log_file);
    }

    return 0;
}

