#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_INPUT_LOCK   24
#define GPIO_INPUT_UNLOCK 23
#define GPIO_OUTPUT_1     17
#define GPIO_OUTPUT_2     18
#define GPIO_OUTPUT_3     27
#define GPIO_OUTPUT_4     22

volatile int lock_pressed = 0;
volatile int unlock_pressed = 0;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        printf("Received exit signal, de-energizing motor coils...\n");
        gpioWrite(GPIO_OUTPUT_1, 0);
        gpioWrite(GPIO_OUTPUT_2, 0);
        gpioWrite(GPIO_OUTPUT_3, 0);
        gpioWrite(GPIO_OUTPUT_4, 0);
        printf("Releasing all pigpio resources...\n");
        gpioTerminate();
        printf("Exiting...\n");
        exit(0);
    }
}

void lock_pressed_handler(int gpio, int level, uint32_t tick) {
    lock_pressed = 1;
}

void unlock_pressed_handler(int gpio, int level, uint32_t tick) {
    unlock_pressed = 1;
}

int main() {
    int pi = pigpio_start(0, 0);
    if (pi < 0) {
        printf("Failed to initialise pigpio: %d\n", pi);
        return -1;
    }

    if (gpioSetMode(GPIO_OUTPUT_1, PI_OUTPUT) != 0 ||
        gpioSetMode(GPIO_OUTPUT_2, PI_OUTPUT) != 0 ||
        gpioSetMode(GPIO_OUTPUT_3, PI_OUTPUT) != 0 ||
        gpioSetMode(GPIO_OUTPUT_4, PI_OUTPUT) != 0) {
        printf("Failed to set GPIO output mode\n");
        return -1;
    }

    if (gpioSetMode(GPIO_INPUT_LOCK, PI_INPUT) != 0 ||
        gpioSetMode(GPIO_INPUT_UNLOCK, PI_INPUT) != 0) {
        printf("Failed to set GPIO input mode\n");
        return -1;
    }

    if (gpioSetPullUpDown(GPIO_INPUT_LOCK, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(GPIO_INPUT_UNLOCK, PI_PUD_UP) != 0) {
        printf("Failed to set GPIO pull-up\n");
        return -1;
    }

    gpioCallback(GPIO_INPUT_LOCK, PI_EITHER_EDGE, lock_pressed_handler, NULL);
    gpioCallback(GPIO_INPUT_UNLOCK, PI_EITHER_EDGE, unlock_pressed_handler, NULL);

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        if (lock_pressed) {
            lock_pressed = 0;
            printf("Lock button pressed, rotating motor clockwise...\n");
            for (int i = 0; i < 512; i++) {
                gpioWrite(GPIO_OUTPUT_1, 1);
                gpioWrite(GPIO_OUTPUT_2, 0);
                gpioWrite(GPIO_OUTPUT_3, 1);
                gpioWrite(GPIO_OUTPUT_4, 0);
                delay(2000);
                gpioWrite(GPIO_OUTPUT_1, 0);
                gpioWrite(GPIO_OUTPUT_2, 1);
                gpioWrite(GPIO_OUTPUT_3, 0);
                gpioWrite(GPIO_OUTPUT_4, 1);
                delay(2000);
            }
        }

        if (unlock_pressed) {
            unlock_pressed = 0;
            printf("Unlock button pressed, rotating motor counter-clockwise...\n");
            for (int i = 0; i < 512; i++) {
                gpioWrite(GPIO_OUTPUT_1, 0);
                gpioWrite(GPIO_OUTPUT_2, 1);
                gpioWrite(GPIO_OUTPUT_3, 0);
                gpioWrite(GPIO_OUTPUT_4, 1);
                delay(2000);
                gpioWrite(GPIO_OUTPUT_1, 1);
                gpioWrite(GPIO_OUTPUT_2, 0);
                gpioWrite(GPIO_OUTPUT_3, 1);
                gpioWrite(GPIO_OUTPUT_4, 0);
                delay(2000);
            }
        }
    }

    return 0;
}

