        pwm_duty = (data[0] + 1024) / 2;
        write(pwm_duty_fd, &pwm_duty, sizeof(pwm_duty));

        fprintf(log_file, "%ld,%d,%d,%d\n", time(NULL), data[0], data[1], pwm_duty);
        fflush(log_file);

        sleep(1);
    }

    return 0;
}

