#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN_4    4
#define GPIO_PIN_17   17
#define GPIO_PIN_27   27
#define GPIO_PIN_22   22

#define PWM_FREQ      100
#define PWM_DUTY_MAX  100
#define PWM_DUTY_MIN  0

#define SCHEDULE_FILE "lighting_schedule.txt"

static int relays[4] = {GPIO_PIN_4, GPIO_PIN_17, GPIO_PIN_27, GPIO_PIN_22};
static int relay_states[4] = {0, 0, 0, 0};

static void exit_handler(int signum) {
    for (int i = 0; i < 4; i++) {
        gpioWrite(relays[i], 0);
        gpioHardPWM(relays[i], 0);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    struct sigaction action;
    action.sa_handler = exit_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;

    if (sigaction(SIGINT, &action, NULL) < 0 || sigaction(SIGTERM, &action, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise GPIO\n");
        return 1;
    }

    for (int i = 0; i < 4; i++) {
        gpioSetMode(relays[i], PI_OUTPUT);
        gpioHardPWM(relays[i], PWM_FREQ);
    }

    FILE *schedule_file = fopen(SCHEDULE_FILE, "r");
    if (!schedule_file) {
        perror("Failed to open schedule file");
        exit_handler(0);
    }

    while (1) {
        int hour, minute, second, relay, state;
        char line[256];
        if (!fgets(line, sizeof(line), schedule_file)) {
            if (feof(schedule_file)) {
                rewind(schedule_file);
                continue;
            } else {
                perror("Failed to read schedule file");
                exit_handler(0);
            }
        }

        if (sscanf(line, "%d:%d:%d,%d,%d", &hour, &minute, &second, &relay, &state) != 5) {
            fprintf(stderr, "Invalid schedule entry: %s", line);
            continue;
        }

        time_t target_time = time(NULL) + hour*3600 + minute*60 + second;
        while (time(NULL) < target_time) {
            sleep(1);
        }

        if (state == 1) {
            int current_duty = relay_states[relay] ? PWM_DUTY_MAX : PWM_DUTY_MIN;
            for (int duty = current_duty; abs(duty - PWM_DUTY_MAX) < 100; duty += (PWM_DUTY_MAX - current_duty) / 1800) {
                gpioHardPWM(relays[relay], duty);
                sleep(1);
            }
        } else {
            int current_duty = relay_states[relay] ? PWM_DUTY_MAX : PWM_DUTY_MIN;
            for (int duty = current_duty; abs(duty - PWM_DUTY_MIN) < 100; duty += (PWM_DUTY_MIN - current_duty) / 1800) {
                gpioHardPWM(relays[relay], duty);
                sleep(1);
            }
        }

        relay_states[relay] = state;
    }

    fclose(schedule_file);
    exit_handler(0);

    return 0;
}

