#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18
#define MIN_DISTANCE 2000
#define MAX_DISTANCE 30000
#define MIN_FREQUENCY 200
#define MAX_FREQUENCY 2000

volatile int running = 1;

void sigint_handler(int signum) {
    gpioWrite(BUZZER_PIN, 0);
    running = 0;
}

int main() {
    int pi = pigpio_start(0, 0);
    if (pi < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    signal(SIGINT, sigint_handler);

    while (running) {
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(10);
        gpioWrite(TRIGGER_PIN, 0);

        int start = gpioTick();
        while (gpioRead(ECHO_PIN) == 0 && gpioTick() - start < 10000)
            ;

        if (gpioRead(ECHO_PIN) == 0) {
            fprintf(stderr, "HC-SR04 read failed: Sensor not present\n");
            continue;
        }

        int end = gpioTick();
        while (gpioRead(ECHO_PIN) == 1 && gpioTick() - end < 10000)
            ;

        if (gpioRead(ECHO_PIN) == 1) {
            fprintf(stderr, "HC-SR04 read failed: Timeout\n");
            continue;
        }

        int distance = (end - start) * 170;
        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(stderr, "HC-SR04 read failed: Distance out of range\n");
            continue;
        }

        int frequency = MIN_FREQUENCY + (distance - MIN_DISTANCE) *
                                        (MAX_FREQUENCY - MIN_FREQUENCY) /
                                        (MAX_DISTANCE - MIN_DISTANCE);

        gpioHardwarePWM(BUZZER_PIN, frequency, 500000);

        gpioDelay(60);
    }

    pigpio_stop(pi);

    return EXIT_SUCCESS;
}

