#define GPIO_RED     17
#define GPIO_GREEN   22
#define GPIO_BLUE    27

volatile sig_atomic_t stop = 0;

void sig_handler(int signo) {
    if (signo == SIGINT) {
        stop = 1;
    }
}

void cleanup(void) {
    piGpioSetServo(GPIO_RED, 0);
    piGpioSetServo(GPIO_GREEN, 0);
    piGpioSetServo(GPIO_BLUE, 0);
    gpioTerminate();
}

int main() {
    int pi = piGpioInitialise();
    if (pi < 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", piGpioStrError(pi));
        return EXIT_FAILURE;
    }

    if (piGpioSetMode(GPIO_RED, PI_OUTPUT) < 0 ||
        piGpioSetMode(GPIO_GREEN, PI_OUTPUT) < 0 ||
        piGpioSetMode(GPIO_BLUE, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO mode: %s\n", piGpioStrError(pi));
        cleanup();
        return EXIT_FAILURE;
    }

    if (piGpioSetServo(GPIO_RED, 1000) < 0 ||
        piGpioSetServo(GPIO_GREEN, 1000) < 0 ||
        piGpioSetServo(GPIO_BLUE, 1000) < 0) {
        fprintf(stderr, "Error setting GPIO servo: %s\n", piGpioStrError(pi));
        cleanup();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);

    while (!stop) {
        static double proximity = 0.0;
        proximity += 0.01;
        if (proximity > 1.0) proximity -= 1.0;

        int red = proximity * 1000;
        int green = proximity * 1000;
        int blue = proximity * 1000;

        if (piGpioSetServo(GPIO_RED, red) < 0 ||
            piGpioSetServo(GPIO_GREEN, green) < 0 ||
            piGpioSetServo(GPIO_BLUE, blue) < 0) {
            fprintf(stderr, "Error setting GPIO servo: %s\n", piGpioStrError(pi));
            cleanup();
            return EXIT_FAILURE;
        }

        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

