#include <time.h>

#define I2C_FILE "/dev/i2c-1"
#define MPU_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_DATA_H 0x43
#define SENSITIVITY_FACTOR 131.0

