#define GPIO_BUTTON 17
#define GPIO_BUZZER 18
#define PWM_CHANNEL 0
#define PWM_FREQ 1000
#define PWM_DUTY_CYCLE 50
#define DEBOUNCE_TIME 50

volatile int button_pressed = 0;
volatile int melody_playing = 0;

const int melody[] = {523, 587, 659, 587, 523, 493, 523, 587, 659, 587, 523}; // C D E D C G C D E

void handle_signal(int signo) {
    gpioHardwarePWM(GPIO_BUZZER, 0, 0);
    gpioTerminate();
    exit(0);
}

void button_isr(int gpio, int level, uint32_t tick) {
    if (level == 0 && !melody_playing) {
        button_pressed = 1;
    }
}

int main() {
    int ret;

    ret = gpioInitialise();
    if (ret < 0) {
        printf("gpioInitialise failed: %d\n", ret);
        return 1;
    }

    ret = gpioSetMode(GPIO_BUTTON, PI_INPUT);
    if (ret < 0) {
        printf("gpioSetMode failed: %d\n", ret);
        return 1;
    }

    ret = gpioSetPullUpDown(GPIO_BUTTON, PI_PUD_UP);
    if (ret < 0) {
        printf("gpioSetPullUpDown failed: %d\n", ret);
        return 1;
    }

    ret = gpioSetISRFuncEx(GPIO_BUTTON, PI_RISING_EDGE, DEBOUNCE_TIME, button_isr);
    if (ret < 0) {
        printf("gpioSetISRFuncEx failed: %d\n", ret);
        return 1;
    }

    ret = gpioSetMode(GPIO_BUZZER, PI_OUTPUT);
    if (ret < 0) {
        printf("gpioSetMode failed: %d\n", ret);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i = 0;
    while (1) {
        if (button_pressed) {
            button_pressed = 0;
            melody_playing = 1;
            for (int j = 0; j < sizeof(melody) / sizeof(melody[0]); j++) {
                ret = gpioHardwarePWM(GPIO_BUZZER, melody[j], PWM_DUTY_CYCLE * 10000);
                if (ret < 0) {
                    printf("gpioHardwarePWM failed: %d\n", ret);
                    return 1;
                }
                sleep(1);
            }
            gpioHardwarePWM(GPIO_BUZZER, 0, 0);
            melody_playing = 0;
        }
    }

    return 0;
}

