#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <unistd.h>
#include <fcntl.h>

#define LOG_FILE "vibration_events.log"
#define MAX_EVENTS 5

struct gpiod_line *line;
struct gpiod_chip *chip;
FILE *log_file;
int log_file_open_error = 0;
int earthquake_alert_count = 0;
volatile sig_atomic_t stop = 0;

void sig_handler(int signum) {
    stop = 1;
}

void log_event(int value) {
    if (log_file_open_error)
        return;

    if (!log_file) {
        log_file = fopen(LOG_FILE, "a");
        if (!log_file) {
            fprintf(stderr, "Failed to open %s for writing: %m\n", LOG_FILE);
            log_file_open_error = 1;
            return;
        }
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02d %d\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, value);
    fflush(log_file);
    fsync(fileno(log_file));
}

int main(int argc, char **argv) {
    int timeout_ms = argc > 1 ? atoi(argv[1]) : 1000;
    if (timeout_ms <= 0) {
        fprintf(stderr, "Invalid timeout: %s\n", argv[1]);
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %m\n");
        return 1;
    }

    line = gpiod_chip_get_line(chip, 17);
    if (!line) {
        fprintf(stderr, "Failed to get line 17: %m\n");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(line, "vibration_sensor")) {
        fprintf(stderr, "Failed to request line 17 as input: %m\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = sig_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    int event_buffer[MAX_EVENTS];
    int event_count = 0;

    while (!stop) {
        struct gpiod_line_event event;
        if (gpiod_line_event_wait(line, timeout_ms)) {
            if (errno == ETIMEDOUT)
                continue;
            fprintf(stderr, "Failed to wait for event: %m\n");
            break;
        }

        if (gpiod_line_event_read(line, &event)) {
            fprintf(stderr, "Failed to read event: %m\n");
            break;
        }

        log_event(event.event_type == GPIOD_LINE_EVENT_RISING_EDGE ? 1 : 0);

        if (event_count == MAX_EVENTS) {
            memmove(&event_buffer[0], &event_buffer[1], sizeof(int) * (MAX_EVENTS - 1));
            event_count--;
        }

        event_buffer[event_count++] = event.event_type == GPIOD_LINE_EVENT_RISING_EDGE ? 1 : 0;

        if (event_buffer[event_count - 1]) {
            earthquake_alert_count++;
            if (earthquake_alert_count >= 3) {
                printf("EARTHQUAKE ALERT at %04d-%02d-%02dT%02d:%02d:%02d\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec);
                earthquake_alert_count = 0;
            }
        } else {
            earthquake_alert_count = 0;
        }
    }

    if (log_file)
        fclose(log_file);

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

