#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <math.h>
#include <signal.h>

#define I2C_FILE "/dev/i2c-1"
#define MAGNETOMETER_ADDRESS 0x1E
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

static int i2c_file_descriptor;
static FILE *csv_file;

void cleanup(int signal) {
    close(i2c_file_descriptor);
    fclose(csv_file);
    exit(0);
}

int main() {
    struct sigaction action;
    action.sa_handler = cleanup;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    i2c_file_descriptor = open(I2C_FILE, O_RDWR);
    if (i2c_file_descriptor < 0) {
        perror("Failed to open I2C device file");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_file_descriptor, I2C_SLAVE, MAGNETOMETER_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        return EXIT_FAILURE;
    }

    if (write(i2c_file_descriptor, &(uint8_t){0x00}, 1) != 1 ||
        write(i2c_file_descriptor, &(uint8_t){0x02}, 1) != 1 ||
        write(i2c_file_descriptor, &(uint8_t){0x14}, 1) != 1 ||
        write(i2c_file_descriptor, &(uint8_t){0x00}, 1) != 1) {
        perror("Failed to write to magnetometer");
        return EXIT_FAILURE;
    }

    csv_file = fopen("mag_log.csv", "w");
    if (csv_file == NULL) {
        perror("Failed to open CSV file for writing");
        return EXIT_FAILURE;
    }

    fprintf(csv_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading\n");

    while (1) {
        uint8_t data[6];
        if (read(i2c_file_descriptor, data, 6) != 6) {
            fprintf(stderr, "Failed to read from magnetometer\n");
            continue;
        }

        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[2] << 8) | data[3];
        int16_t z = (data[4] << 8) | data[5];

        float cx = (float)(x - X_OFFSET);
        float cy = (float)(y - Y_OFFSET);
        float cz = (float)(z - Z_OFFSET);

        float heading_rad = atan2f(cy, cx);
        float heading_deg = heading_rad * (180.0f / M_PI);
        if (heading_deg < 0) heading_deg += 360.0f;

        char *direction;
        if (heading_deg < 22.5f) direction = "N";
        else if (heading_deg < 67.5f) direction = "NE";
        else if (heading_deg < 112.5f) direction = "E";
        else if (heading_deg < 157.5f) direction = "SE";
        else if (heading_deg < 202.5f) direction = "S";
        else if (heading_deg < 247.5f) direction = "SW";
        else if (heading_deg < 292.5f) direction = "W";
        else direction = "NW";

        printf("%s %.1f\n", direction, heading_deg);

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(csv_file, "%s,%.2f,%.2f,%.2f,%.1f\n", timestamp, cx, cy, cz, heading_deg);

        fflush(csv_file);

        sleep(1);
    }

    return EXIT_SUCCESS;
}

