#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

volatile sig_atomic_t stop = 0;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        gpioServo(17, 0);
        gpioServo(18, 0);
        gpioTerminate();
        stop = 1;
    }
}

int main() {
    int ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "gpioInitialise() failed with error %d\n", ret);
        return EXIT_FAILURE;
    }

    struct sigaction sig_action;
    sig_action.sa_handler = sig_handler;
    sigemptyset(&sig_action.sa_mask);
    sig_action.sa_flags = 0;

    sigaction(SIGINT, &sig_action, NULL);
    sigaction(SIGTERM, &sig_action, NULL);

    int moisture_values[] = {20, 40, 60, 80, 100};
    int num_values = sizeof(moisture_values) / sizeof(moisture_values[0]);
    int i = 0;

    while (!stop) {
        int moisture = moisture_values[i % num_values];
        i++;

        if (moisture < 50) {
            int retry = 0;
            while (gpioServo(17, 900) < 0 && retry < 3) {
                usleep(100000);
                retry++;
            }

            if (retry == 3) {
                printf("Failed to open the valve, aborting the cycle\n");
                continue;
            }

            for (int angle = 0; angle <= 180; angle += 45) {
                retry = 0;
                while (gpioServo(18, 500 + angle * 10) < 0 && retry < 3) {
                    usleep(100000);
                    retry++;
                }

                if (retry == 3) {
                    printf("Failed to set the nozzle to angle %d, continuing to the next\n", angle);
                    continue;
                }

                sleep(2);
            }

            retry = 0;
            while (gpioServo(17, 500) < 0 && retry < 3) {
                usleep(100000);
                retry++;
            }

            if (retry == 3) {
                printf("Failed to close the valve, critical warning\n");
            }
        }

        sleep(5);
    }

    return EXIT_SUCCESS;
}

