#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <signal.h>
#include <time.h>

#define I2C_FILE "/dev/i2c-1"
#define MPU_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_SENSITIVITY 131.0
#define LOG_FILE "gyro_log.txt"
#define SAMPLE_RATE 10

static int i2c_file = -1;
static FILE* log_file = NULL;

void exit_handler(int signum) {
    if (i2c_file != -1) {
        close(i2c_file);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(signum);
}

int main() {
    struct sigaction action;
    action.sa_handler = exit_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    i2c_file = open(I2C_FILE, O_RDWR);
    if (i2c_file == -1) {
        perror("Failed to open I2C device file");
        exit_handler(-1);
    }

    if (ioctl(i2c_file, I2C_SLAVE, MPU_ADDR) == -1) {
        perror("Failed to set I2C slave address");
        exit_handler(-1);
    }

    if (write(i2c_file, &PWR_MGMT_1, 1) != 1 ||
        write(i2c_file, "\0", 1) != 1) {
        perror("Failed to wake sensor");
        exit_handler(-1);
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit_handler(-1);
    }

    unsigned char buffer[6];
    while (1) {
        if (write(i2c_file, &GYRO_XOUT_H, 1) != 1 ||
            read(i2c_file, buffer, 6) != 6) {
            perror("Failed to read gyroscope data");
            exit_handler(-1);
        }

        int32_t x = (buffer[0] << 8) | buffer[1];
        int32_t y = (buffer[2] << 8) | buffer[3];
        int32_t z = (buffer[4] << 8) | buffer[5];

        time_t now = time(NULL);
        struct tm* timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s, %.2f, %.2f, %.2f\n", timestamp,
                x / GYRO_SENSITIVITY, y / GYRO_SENSITIVITY, z / GYRO_SENSITIVITY);

        fflush(log_file);

        sleep(1.0 / SAMPLE_RATE);
    }

    exit_handler(0);
}

