#include <unistd.h>
#include <pigpio.h>

#define STEP_DELAY 3000000 // 3 ms
#define BUTTON_DELAY 10000 // 10 ms
#define COIL_DELAY 100000  // 100 ms
#define LOCK_PIN 24
#define UNLOCK_PIN 23
#define IN1 4
#define IN2 17
#define IN3 27
#define IN4 22

volatile int stop = 0;

void sigint_handler(int signo) {
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
    gpioTerminate();
    stop = 1;
}

void rotate(int steps, int direction) {
    int i, j;
    int coils[4] = {IN1, IN2, IN3, IN4};

    for (i = 0; i < steps; i++) {
        for (j = 0; j < 4; j++) {
            gpioWrite(coils[j], direction);
            usleep(STEP_DELAY);
            gpioWrite(coils[j], 0);
            usleep(COIL_DELAY);
        }
    }
}

int main() {
    int lock, unlock;
    struct sigaction action;

    if (gpioInitialise() < 0) {
        printf("Error initializing GPIO\n");
        return 1;
    }

    gpioSetMode(LOCK_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_PIN, PI_INPUT);
    gpioSetPullUpDown(LOCK_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_PIN, PI_PUD_UP);

    action.sa_handler = sigint_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);

    while (!stop) {
        lock = gpioRead(LOCK_PIN);
        usleep(BUTTON_DELAY);
        if (lock == 0) {
            printf("Locking the door\n");
            rotate(512, 1);
        }

        unlock = gpioRead(UNLOCK_PIN);
        usleep(BUTTON_DELAY);
        if (unlock == 0) {
            printf("Unlocking the door\n");
            rotate(512, 0);
        }
    }

    return 0;
}

