#define ECHO_GPIO 18
#define LOG_FILE "distance_log.txt"
#define TIMEOUT_US 50000
#define GUARD_US 60000

struct gpiod_chip *chip;
struct gpiod_line *trigger, *echo;
FILE *log_file;

void cleanup_and_exit(int signum) {
    gpiod_line_release(trigger);
    gpiod_line_release(echo);
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(0);
}

int main() {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_GPIO);
    if (!trigger) {
        fprintf(stderr, "Failed to get trigger line\n");
        return 1;
    }

    if (gpiod_line_request_output(trigger, "trigger", 0)) {
        fprintf(stderr, "Failed to request trigger line\n");
        return 1;
    }

    echo = gpiod_chip_get_line(chip, ECHO_GPIO);
    if (!echo) {
        fprintf(stderr, "Failed to get echo line\n");
        return 1;
    }

    if (gpiod_line_request_input(echo, "echo")) {
        fprintf(stderr, "Failed to request echo line\n");
        return 1;
    }

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    struct timespec start, end;
    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &start);

        gpiod_line_set_value(trigger, 1);
        usleep(10);
        gpiod_line_set_value(trigger, 0);

        struct gpiod_line_event event;
        if (gpiod_line_wait_rising_edge(echo, TIMEOUT_US) ||
            gpiod_line_event_read(echo, &event)) {
            fprintf(stderr, "Failed to read echo line\n");
            fprintf(log_file, "-1\n");
            fflush(log_file);
            continue;
        }

        clock_gettime(CLOCK_MONOTONIC, &end);
        long duration_us = (end.tv_sec - start.tv_sec) * 1000000 +
                           (end.tv_nsec - start.tv_nsec) / 1000;

        fprintf(log_file, "%ld\n", duration_us * 0.01715);
        fflush(log_file);

        usleep(GUARD_US);
    }

    return 0;
}

