#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define GPIO_RELAY 18

static int i2c_handle = -1;
static int pi_handle = -1;

void cleanup_and_exit(int sig) {
    if (i2c_handle != -1) {
        piI2C_close(i2c_handle);
    }
    if (pi_handle != -1) {
        gpioWrite(GPIO_RELAY, 0);
        gpioTerminate();
    }
    exit(0);
}

int main() {
    int ret;
    uint16_t data;

    signal(SIGINT, cleanup_and_exit);

    pi_handle = gpioInitialise();
    if (pi_handle <= 0) {
        fprintf(stderr, "gpioInitialise() failed\n");
        return 1;
    }

    ret = gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "gpioSetMode() failed\n");
        return 1;
    }

    i2c_handle = piI2C_open(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "piI2C_open() failed\n");
        return 1;
    }

    ret = piI2C_writeByteData(i2c_handle, 0x0000, 0x00);
    if (ret != 0) {
        fprintf(stderr, "piI2C_writeByteData() failed\n");
        return 1;
    }

    ret = piI2C_writeByteData(i2c_handle, 0x0080, 0x01);
    if (ret != 0) {
        fprintf(stderr, "piI2C_writeByteData() failed\n");
        return 1;
    }

    while (1) {
        usleep(100000);

        ret = piI2C_readWordData(i2c_handle, 0x0044);
        if (ret < 0) {
            fprintf(stderr, "piI2C_readWordData() failed\n");
            return 1;
        }

        if (ret & 0x0004) {
            ret = piI2C_readWordData(i2c_handle, 0x0096);
            if (ret < 0) {
                fprintf(stderr, "piI2C_readWordData() failed\n");
                return 1;
            }

            data = (uint16_t)ret;
            printf("Distance: %u\n", data);

            if (data <= 50) {
                gpioWrite(GPIO_RELAY, 1);
            } else {
                gpioWrite(GPIO_RELAY, 0);
            }
        }
    }

    return 0;
}

