#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <linux/i2c.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_SCALE 131.0
#define GYRO_DATA_REG 0x43

volatile sig_atomic_t stop = 0;
int fd;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        close(fd);
        printf("Exiting...\n");
        exit(0);
    }
}

int i2c_write_reg(int file, char reg, char data) {
    char buf[2] = {reg, data};
    if (write(file, buf, 2) != 2) {
        printf("Failed to write to device\n");
        return -1;
    }
    return 0;
}

int i2c_read_reg(int file, char reg, char *data, int len) {
    if (ioctl(file, I2C_SLAVE, MPU6050_ADDR) < 0) {
        printf("Failed to set I2C device address\n");
        return -1;
    }
    if (write(file, &reg, 1) != 1) {
        printf("Failed to write register address\n");
        return -1;
    }
    if (read(file, data, len) != len) {
        printf("Failed to read data\n");
        return -1;
    }
    return 0;
}

int main() {
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        printf("Failed to open I2C device\n");
        return -1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    if (i2c_write_reg(fd, PWR_MGMT_1, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, GYRO_CONFIG, 0x00) < 0) return -1;

    char buf[6];
    while (!stop) {
        if (i2c_read_reg(fd, GYRO_DATA_REG, buf, 6) < 0) return -1;
        short x = (buf[0] << 8) | buf[1];
        short y = (buf[2] << 8) | buf[3];
        short z = (buf[4] << 8) | buf[5];
        printf("Gyroscope: x = %.2f, y = %.2f, z = %.2f dps\n", x * GYRO_SCALE, y * GYRO_SCALE, z * GYRO_SCALE);
        sleep(1);
    }

    close(fd);
    return 0;
}

