#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define GPIOCHIP "/dev/gpiochip0"
#define OFFSET_GPIO17 0
#define OFFSET_GPIO18 1
#define OFFSET_GPIO27 2
#define OFFSET_GPIO22 3
#define LINE_COUNT 4
#define WATERING_INTERVAL 86400
#define POLLING_INTERVAL 60

struct gpiod_chip *chip;
struct gpiod_line *lines[LINE_COUNT];
FILE *log_file;

void sig_handler(int signo) {
    for (int i = 0; i < LINE_COUNT; i++)
        gpiod_line_release(lines[i]);
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(0);
}

int main() {
    struct sigaction sigIntHandler;
    sigIntHandler.sa_handler = sig_handler;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_flags = 0;
    sigaction(SIGINT, &sigIntHandler, NULL);
    sigaction(SIGTERM, &sigIntHandler, NULL);

    chip = gpiod_chip_open(GPIOCHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        exit(1);
    }

    for (int i = 0; i < LINE_COUNT; i++) {
        lines[i] = gpiod_chip_get_line(chip, OFFSET_GPIO17 + i);
        if (!lines[i]) {
            perror("gpiod_chip_get_line");
            exit(1);
        }

        if (gpiod_line_request_output(lines[i], "watering", 1)) {
            perror("gpiod_line_request_output");
            exit(1);
        }
    }

    log_file = fopen("watering_log.txt", "w");
    if (!log_file) {
        perror("fopen");
        exit(1);
    }

    time_t last_watering = time(NULL);
    while (1) {
        for (int i = 0; i < LINE_COUNT; i++) {
            if (gpiod_line_set_value(lines[i], 0)) {
                perror("gpiod_line_set_value");
                exit(1);
            }

            struct tm *timeinfo = localtime(&last_watering);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(log_file, "%s: Watered plant %d\n", timestamp, i + 1);

            sleep(5);

            if (gpiod_line_set_value(lines[i], 1)) {
                perror("gpiod_line_set_value");
                exit(1);
            }
        }

        last_watering = time(NULL) + WATERING_INTERVAL;
        time_t next_watering = last_watering;
        while (time(NULL) < next_watering)
            sleep(POLLING_INTERVAL);
    }

    return 0;
}

