#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO17 17
#define GPIO18 18
#define GPIO27 27
#define GPIO22 22

#define PWM_FREQ 1000
#define MAX_DUTY_CYCLE 255
#define LOG_FILE "smart_lighting.log"

volatile sig_atomic_t stop = 0;

void log_event(const char *event) {
    time_t now = time(NULL);
    FILE *log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        printf("Failed to open log file\n");
        return;
    }
    fprintf(log, "%s: %s\n", ctime(&now), event);
    fclose(log);
}

void handle_signal(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        log_event("Failed to initialise GPIO");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO17, PI_OUTPUT) < 0 ||
        gpioSetMode(GPIO18, PI_OUTPUT) < 0 ||
        gpioSetMode(GPIO27, PI_OUTPUT) < 0 ||
        gpioSetMode(GPIO22, PI_OUTPUT) < 0) {
        log_event("Failed to set GPIO mode");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioHardwarePWM(GPIO17, PWM_FREQ, 0) < 0 ||
        gpioHardwarePWM(GPIO18, PWM_FREQ, 0) < 0 ||
        gpioHardwarePWM(GPIO27, PWM_FREQ, 0) < 0 ||
        gpioHardwarePWM(GPIO22, PWM_FREQ, 0) < 0) {
        log_event("Failed to initialise PWM");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    log_event("Starting sunrise simulation");

    for (int duty_cycle = 0; duty_cycle <= MAX_DUTY_CYCLE && !stop; duty_cycle++) {
        if (gpioWrite(GPIO17, duty_cycle) < 0 ||
            gpioWrite(GPIO18, duty_cycle) < 0 ||
            gpioWrite(GPIO27, duty_cycle) < 0 ||
            gpioWrite(GPIO22, duty_cycle) < 0) {
            log_event("Failed to set PWM duty cycle");
            gpioTerminate();
            return EXIT_FAILURE;
        }
        sleep(1);
    }

    log_event("Sunrise simulation complete");

    gpioTerminate();

    return EXIT_SUCCESS;
}

