    gpioSetMode(LED_GPIO, PI_OUTPUT);

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    piI2C_writeByte(i2c_handle, 0x6B, 0x00);
    piI2C_writeByte(i2c_handle, 0x19, 0x07);
    piI2C_writeByte(i2c_handle, 0x1B, 0x00);

    uint8_t who_am_i = piI2C_readByte(i2c_handle, 0x75);
    if (who_am_i != 0x68) {
        fprintf(stderr, "Failed to find MPU-6050\n");
        exit(1);
    }

    int led_on = 0;
    while (1) {
        int16_t x = piI2C_readWordBigEndian(i2c_handle, 0x43);
        int16_t y = piI2C_readWordBigEndian(i2c_handle, 0x45);
        int16_t z = piI2C_readWordBigEndian(i2c_handle, 0x47);

        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);

        data_buf[buf_head].ts = ts;
        data_buf[buf_head].x = x;
        data_buf[buf_head].y = y;
        data_buf[buf_head].z = z;
        buf_head = (buf_head + 1) % DATA_BUF_LEN;
        if (buf_head == buf_tail) {
            buf_full = 1;
        }

        float abs_x = x * GYRO_SENSITIVITY;
        float abs_y = y * GYRO_SENSITIVITY;
        float abs_z = z * GYRO_SENSITIVITY;

        if (abs_x > MAX_ABS_RATE || abs_y > MAX_ABS_RATE || abs_z > MAX_ABS_RATE) {
            if (!led_on) {
                gpioWrite(LED_GPIO, 1);
                led_on = 1;
            }
        } else if (led_on) {
            gpioWrite(LED_GPIO, 0);
            led_on = 0;
        }

        usleep(50000);
    }

    return 0;
}

