#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 8
#define GYRO_REG 0x43
#define GYRO_SCALE 131.0
#define LOG_FILE "gyro_log.txt"
#define MAX_RETRIES 3

struct context {
    struct gpiod_chip *gpio_chip;
    struct gpiod_line *gpio_line;
    int spi_fd;
    FILE *log_file;
    int retries;
};

static void cleanup(struct context *ctx) {
    if (ctx->gpio_line)
        gpiod_line_release(ctx->gpio_line);
    if (ctx->gpio_chip)
        gpiod_chip_close(ctx->gpio_chip);
    if (ctx->spi_fd >= 0)
        close(ctx->spi_fd);
    if (ctx->log_file)
        fclose(ctx->log_file);
}

static void sig_handler(int signo) {
    struct context *ctx = (struct context *)signal_handler_arg;
    cleanup(ctx);
    exit(0);
}

int main() {
    struct context ctx;
    memset(&ctx, 0, sizeof(ctx));
    ctx.spi_fd = open(SPI_DEVICE, O_RDWR);
    if (ctx.spi_fd < 0) {
        perror("open spi device");
        return 1;
    }
    struct spi_ioc_transfer xfer = {
        .tx_buf = (__u64)NULL,
        .rx_buf = (__u64)NULL,
        .len = 0,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .cs_change = 1,
    };
    if (ioctl(ctx.spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
        perror("spi ioctl");
        return 1;
    }
    ctx.gpio_chip = gpiod_chip_open(GPIO_CHIP);
    if (!ctx.gpio_chip) {
        perror("open gpio chip");
        return 1;
    }
    ctx.gpio_line = gpiod_chip_get_line(ctx.gpio_chip, GPIO_LINE);
    if (!ctx.gpio_line) {
        perror("get gpio line");
        return 1;
    }
    if (gpiod_line_request_output(ctx.gpio_line, "gyro", 1) < 0) {
        perror("request gpio line");
        return 1;
    }
    ctx.log_file = fopen(LOG_FILE, "w");
    if (!ctx.log_file) {
        perror("open log file");
        return 1;
    }
    struct sigaction sigact;
    memset(&sigact, 0, sizeof(sigact));
    sigact.sa_handler = sig_handler;
    sigaction(SIGINT, &sigact, NULL);
    sigaction(SIGTERM, &sigact, NULL);
    signal_handler_arg = &ctx;
    while (1) {
        usleep(10000);
        xfer.tx_buf = (__u64)&GYRO_REG;
        xfer.len = 1;
        if (ioctl(ctx.spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
            if (++ctx.retries > MAX_RETRIES) {
                perror("spi write");
                continue;
            }
        }
        __u8 buf[6];
        xfer.tx_buf = (__u64)NULL;
        xfer.rx_buf = (__u64)buf;
        xfer.len = sizeof(buf);
        if (ioctl(ctx.spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
            if (++ctx.retries > MAX_RETRIES) {
                perror("spi read");
                continue;
            }
        }
        ctx.retries = 0;
        int16_t rates[3];
        for (int i = 0; i < 3; i++)
            rates[i] = (buf[i*2] << 8) | buf[i*2+1];
        char timestamp[30];
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&ts.tv_sec));
        fprintf(ctx.log_file, "%s.%09ld,%hd,%hd,%hd\n", timestamp, ts.tv_nsec, rates[0], rates[1], rates[2]);
        if (ferror(ctx.log_file)) {
            perror("write log file");
            continue;
        }
        fflush(ctx.log_file);
    }
    return 0;
}

