#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/spi/spidev.h>
#include <sys/ioctl.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_CS 8
#define GPIO_LED 17
#define SPI_SPEED 3900000
#define SPI_MODE 0
#define BUF_SIZE 64

struct buffer_entry {
    struct timespec timestamp;
    int16_t x, y, z;
};

struct buffer_entry buffer[BUF_SIZE];
int buffer_head, buffer_tail;

struct gpiod_chip *gpio_chip;
struct gpiod_line *gpio_cs, *gpio_led;
int spi_fd;

void handle_sigint(int signum) {
    int i;
    for (i = 0; i < BUF_SIZE; i++) {
        printf("%ld.%.9ld,%d,%d,%d\n", buffer[i].timestamp.tv_sec, buffer[i].timestamp.tv_nsec, buffer[i].x, buffer[i].y, buffer[i].z);
    }
    gpiod_line_release(gpio_cs);
    gpiod_line_release(gpio_led);
    gpiod_chip_close(gpio_chip);
    close(spi_fd);
    exit(0);
}

int main() {
    struct spi_ioc_transfer xfer[3];
    uint8_t tx_buf[3] = {0x43, 0, 0}, rx_buf[3];
    int i;

    signal(SIGINT, handle_sigint);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open spi device");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED)) {
        perror("spi ioctl");
        return 1;
    }

    gpio_chip = gpiod_chip_open(GPIO_CHIP);
    if (!gpio_chip) {
        perror("open gpio chip");
        return 1;
    }

    gpio_cs = gpiod_chip_get_line(gpio_chip, GPIO_CS);
    gpio_led = gpiod_chip_get_line(gpio_chip, GPIO_LED);
    if (!gpio_cs || !gpio_led) {
        perror("get gpio line");
        return 1;
    }

    if (gpiod_line_request_output(gpio_cs, "cs", 1) ||
        gpiod_line_request_output(gpio_led, "led", 0)) {
        perror("request gpio line");
        return 1;
    }

    for (;;) {
        for (i = 0; i < 3; i++) {
            xfer[i].tx_buf = (unsigned long)&tx_buf[i];
            xfer[i].rx_buf = (unsigned long)&rx_buf[i];
            xfer[i].len = 1;
            xfer[i].delay_usecs = 0;
            xfer[i].speed_hz = 0;
            xfer[i].bits_per_word = 0;
        }

        if (ioctl(spi_fd, SPI_IOC_MESSAGE(3), xfer) < 0) {
            perror("spi transfer");
            return 1;
        }

        buffer[buffer_head].timestamp = clock_gettime(CLOCK_REALTIME);
        buffer[buffer_head].x = (rx_buf[0] << 8) | rx_buf[1];
        buffer[buffer_head].y = (rx_buf[1] << 8) | rx_buf[2];
        buffer[buffer_head].z = (rx_buf[2] << 8) | rx_buf[0];

        if (buffer[buffer_head].x > 200 || buffer[buffer_head].x < -200 ||
            buffer[buffer_head].y > 200 || buffer[buffer_head].y < -200 ||
            buffer[buffer_head].z > 200 || buffer[buffer_head].z < -200) {
            gpiod_line_set_value(gpio_led, 1);
            usleep(500000);
            gpiod_line_set_value(gpio_led, 0);
        }

        buffer_head = (buffer_head + 1) % BUF_SIZE;
        if (buffer_head == buffer_tail)
            buffer_tail = (buffer_tail + 1) % BUF_SIZE;
    }

    return 0;
}

