#include <string.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <pigpio.h>
#include <wiringPiI2C.h>

#define I2C_ADDR 0x68
#define I2C_BUS 1
#define LED_PIN 21

#define ACCEL_CONFIG 0x1C
#define PWR_MGMT_1 0x6B

#define ACCEL_DATA_START 0x3B
#define DATA_LEN 6

FILE *log_file;

void cleanup_and_exit(int sig) {
    piGpioInitialise();
    piGpioSetMode(LED_PIN, PI_OUTPUT);
    piGpioWrite(LED_PIN, 0);
    piGpioTerminate();
    fclose(log_file);
    exit(0);
}

int main() {
    if (wiringPiSetup() == -1) {
        printf("wiringPiSetup failed\n");
        return 1;
    }

    int file_desc = wiringPiI2CSetupInterface(I2C_BUS, I2C_ADDR);
    if (file_desc == -1) {
        printf("Failed to open I2C device file\n");
        return 1;
    }

    if (wiringPiI2CWriteReg8(file_desc, PWR_MGMT_1, 0x00) == -1) {
        printf("Failed to initialise sensor\n");
        return 1;
    }

    if (wiringPiI2CWriteReg8(file_desc, ACCEL_CONFIG, 0x00) == -1) {
        printf("Failed to set accelerometer full-scale range\n");
        return 1;
    }

    log_file = fopen("tilt_log.txt", "w");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        return 1;
    }

    signal(SIGINT, cleanup_and_exit);

    piGpioInitialise();
    piGpioSetMode(LED_PIN, PI_OUTPUT);

    while (1) {
        char data[DATA_LEN];
        if (wiringPiI2CReadRegN(file_desc, ACCEL_DATA_START, data, DATA_LEN) != DATA_LEN) {
            printf("Failed to read sensor data\n");
            continue;
        }

        int16_t accel_x = (data[0] << 8) | data[1];
        int16_t accel_y = (data[2] << 8) | data[3];
        int16_t accel_z = (data[4] << 8) | data[5];

        double roll = atan2((double)accel_y, (double)accel_z) * 180.0 / M_PI;
        double pitch = atan2((double)(-accel_x), sqrt(accel_y * accel_y + accel_z * accel_z)) * 180.0 / M_PI;

        time_t now = time(NULL);
        struct tm *time_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, roll, pitch);
        printf("Roll: %.2f, Pitch: %.2f\n", roll, pitch);

        if (fabs(roll) > 45.0 || fabs(pitch) > 45.0) {
            piGpioWrite(LED_PIN, 1);
        } else {
            piGpioWrite(LED_PIN, 0);
        }

        delay(100);
    }

    cleanup_and_exit(0);
    return 0;
}

