#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <sys/ioctl.h>
#include <libgpiod.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x5A
#define AMBIENT_REG 0x20
#define PROXIMITY_REG 0x22
#define LED_GPIO 17
#define LOG_FILE "biometric_log.txt"

static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;

static void cleanup_and_exit(int signum) {
    if (led_line)
        gpiod_line_set_value(led_line, 0);
    if (i2c_fd != -1)
        close(i2c_fd);
    if (log_file)
        fclose(log_file);
    exit(signum);
}

int main() {
    int retries = 3;
    int proximity;
    struct tm *ts;
    char time_str[20];
    char log_str[64];

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) == -1) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    gpio_chip = gpiod_chip_open_by_name("/dev/gpiochip0");
    if (!gpio_chip) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    led_line = gpiod_chip_get_line(gpio_chip, LED_GPIO);
    if (!led_line) {
        perror("gpiod_chip_get_line");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(led_line, "led", 0) != 0) {
        perror("gpiod_line_request_output");
        exit(EXIT_FAILURE);
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    while (1) {
        for (int i = 0; i < retries; i++) {
            if (write(i2c_fd, &AMBIENT_REG, 1) == 1 &&
                read(i2c_fd, &proximity, 2) == 2) {
                break;
            }
            usleep(10000);
            if (i == retries - 1) {
                fprintf(stderr, "I2C read error\n");
                exit(EXIT_FAILURE);
            }
        }

        time_t now = time(NULL);
        ts = localtime(&now);
        strftime(time_str, sizeof(time_str), "%F %T", ts);
        sprintf(log_str, "%s,AmbientLight:%04x,Proximity:%04x\n", time_str, proximity, proximity);
        fputs(log_str, log_file);
        fflush(log_file);

        if (proximity > 100)
            gpiod_line_set_value(led_line, 1);
        else
            gpiod_line_set_value(led_line, 0);

        usleep(100000);
    }

    return 0;
}

