#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define MAX_RETRIES 3

int spi_handle = -1;
FILE *file = NULL;
volatile sig_atomic_t stop = 0;

void sigint_handler(int signum) {
    stop = 1;
}

int open_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen error: %s\n", strerror(-spi_handle));
        return -1;
    }
    return 0;
}

int read_register(unsigned char reg, short *value) {
    unsigned char tx_buf[3] = {reg | 0x80, 0x00, 0x00};
    unsigned char rx_buf[3] = {0x00, 0x00, 0x00};

    if (spiXfer(spi_handle, tx_buf, rx_buf, sizeof(tx_buf)) < 0) {
        fprintf(stderr, "spiXfer error: %s\n", strerror(-spiXfer(spi_handle, tx_buf, rx_buf, sizeof(tx_buf))));
        return -1;
    }
    *value = (rx_buf[1] << 8) | rx_buf[2];
    return 0;
}

void close_spi() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
}

void close_file() {
    if (file != NULL) {
        fclose(file);
        file = NULL;
    }
}

void cleanup() {
    close_spi();
    close_file();
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise error: %s\n", strerror(-gpioInitialise()));
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    int retries = 0;
    while (spi_handle < 0 && retries < MAX_RETRIES) {
        open_spi();
        retries++;
    }
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI after %d retries\n", MAX_RETRIES);
        cleanup();
        return EXIT_FAILURE;
    }

    file = fopen("gyro_data.csv", "w");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(file, "timestamp,X_rate,Y_rate\n");

    while (!stop) {
        short x_rate, y_rate;
        if (read_register(0x02, &x_rate) < 0 || read_register(0x04, &y_rate) < 0) {
            fprintf(stderr, "Failed to read register\n");
            cleanup();
            return EXIT_FAILURE;
        }

        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(file, "%ld.%09ld,%hd,%hd\n", ts.tv_sec, ts.tv_nsec, x_rate, y_rate);

        usleep(10000);  // 10 ms delay
    }

    cleanup();
    return EXIT_SUCCESS;
}

