        fprintf(log_file, "%s - Seismic event detected!\n", time_str);

        gpioWrite(ALERT_PIN, 1);
        sleep(2);
        gpioWrite(ALERT_PIN, 0);
    }
}

int main() {
    int err;

    log_file = fopen("seismic_events.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    err = gpioInitialise();
    check_error(err, "Failed to initialise pigpio");

    err = gpioSetMode(SENSOR1_PIN, PI_INPUT);
    check_error(err, "Failed to set sensor 1 GPIO mode");

    err = gpioSetMode(SENSOR2_PIN, PI_INPUT);
    check_error(err, "Failed to set sensor 2 GPIO mode");

    err = gpioSetMode(ALERT_PIN, PI_OUTPUT);
    check_error(err, "Failed to set alert GPIO mode");

    err = gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_DOWN);
    check_error(err, "Failed to set sensor 1 pull-down");

    err = gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_DOWN);
    check_error(err, "Failed to set sensor 2 pull-down");

    err = gpioSetEdgeDetection(SENSOR1_PIN, PI_EITHER_EDGE);
    check_error(err, "Failed to set sensor 1 edge detection");

    err = gpioSetEdgeDetection(SENSOR2_PIN, PI_EITHER_EDGE);
    check_error(err, "Failed to set sensor 2 edge detection");

    err = gpioCallback(SENSOR1_PIN, PI_EITHER_EDGE, sensor_callback);
    check_error(err, "Failed to register sensor 1 callback");

    err = gpioCallback(SENSOR2_PIN, PI_EITHER_EDGE, sensor_callback);
    check_error(err, "Failed to register sensor 2 callback");

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        sleep(1);
    }

    return 0;
}
