#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define GPIO_CS 8
#define GPIO_LED 17
#define ADDR_RATE_XL 0x02
#define ADDR_RATE_XH 0x03
#define SENSITIVITY 200.0
#define THRESHOLD 20.0
#define BUF_SIZE 100

struct timespec ts[BUF_SIZE];
int buf[BUF_SIZE];
int buf_head = 0, buf_tail = 0, buf_count = 0;

void push_buf(int val) {
    buf[buf_head] = val;
    buf_head = (buf_head + 1) % BUF_SIZE;
    if (buf_count < BUF_SIZE) buf_count++;
    else buf_tail = (buf_tail + 1) % BUF_SIZE;
}

void sig_handler(int signo) {
    spiClose(SPI_CHANNEL);
    gpioWrite(GPIO_LED, 0);
    piGpioInitialise();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise GPIO\n");
        return EXIT_FAILURE;
    }

    if (gpioCfgInt(GPIO_CS, PI_ACTIVE_HIGH) < 0) {
        fprintf(stderr, "Failed to configure interrupt\n");
        return EXIT_FAILURE;
    }

    if (spiOpen(SPI_CHANNEL, SPI_BAUD, 0) < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        return EXIT_FAILURE;
    }

    if (gpioWrite(GPIO_LED, 0) < 0) {
        fprintf(stderr, "Failed to write to LED GPIO\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        int data[2] = {ADDR_RATE_XL | 0x80, 0};
        if (spiXfer(SPI_CHANNEL, data, 2, NULL, 0) < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            return EXIT_FAILURE;
        }

        int rate = (data[0] << 8) | data[1];
        if (rate > 0x7FFF) rate -= 0x10000;
        rate /= SENSITIVITY;

        clock_gettime(CLOCK_MONOTONIC, &ts[buf_head]);
        push_buf(rate);

        if (abs(rate) > THRESHOLD) {
            if (gpioWrite(GPIO_LED, 1) < 0) {
                fprintf(stderr, "Failed to write to LED GPIO\n");
                return EXIT_FAILURE;
            }
        } else {
            if (gpioWrite(GPIO_LED, 0) < 0) {
                fprintf(stderr, "Failed to write to LED GPIO\n");
                return EXIT_FAILURE;
            }
        }
    }

    return EXIT_SUCCESS;
}

