#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO17 17
#define GPIO18 18
#define GPIO27 27

int pi;
int total_duration;

void cleanup_and_exit(int sig) {
    if (sig) {
        printf("Signal %d received, shutting down...\n", sig);
    }

    // Turn off all lamps
    if (gpioWrite(GPIO17, 0) < 0) {
        printf("Error turning off GPIO17: %s\n", strerror(errno));
    }
    if (gpioWrite(GPIO18, 0) < 0) {
        printf("Error turning off GPIO18: %s\n", strerror(errno));
    }
    if (gpioWrite(GPIO27, 0) < 0) {
        printf("Error turning off GPIO27: %s\n", strerror(errno));
    }

    // Release resources
    if (gpioTerminate() < 0) {
        printf("Error terminating gpio: %s\n", strerror(errno));
    }

    exit(0);
}

int main(int argc, char *argv[]) {
    // Check if the duration argument is supplied and valid
    if (argc != 2 || (total_duration = atoi(argv[1])) <= 0 || total_duration > 3600) {
        printf("Usage: %s <duration>\n", argv[0]);
        printf("Duration must be an integer between 1 and 3600\n");
        return 1;
    }

    // Initialise pigpio
    if ((pi = gpioInitialise()) < 0) {
        printf("Error initialising gpio: %s\n", strerror(errno));
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    // Set up PWM on the three GPIO pins
    if (gpioSetPWMrange(GPIO17, 256) < 0) {
        printf("Error setting PWM range for GPIO17: %s\n", strerror(errno));
        cleanup_and_exit(0);
    }
    if (gpioSetPWMrange(GPIO18, 256) < 0) {
        printf("Error setting PWM range for GPIO18: %s\n", strerror(errno));
        cleanup_and_exit(0);
    }
    if (gpioSetPWMrange(GPIO27, 256) < 0) {
        printf("Error setting PWM range for GPIO27: %s\n", strerror(errno));
        cleanup_and_exit(0);
    }
    if (gpioSetPWMdutycycle(GPIO17, 255) < 0) {
        printf("Error setting PWM duty cycle for GPIO17: %s\n", strerror(errno));
        cleanup_and_exit(0);
    }
    if (gpioSetPWMdutycycle(GPIO18, 255) < 0) {
        printf("Error setting PWM duty cycle for GPIO18: %s\n", strerror(errno));
        cleanup_and_exit(0);
    }
    if (gpioSetPWMdutycycle(GPIO27, 255) < 0) {
        printf("Error setting PWM duty cycle for GPIO27: %s\n", strerror(errno));
        cleanup_and_exit(0);
    }

    // Fade each lamp sequentially
    for (int i = 0; i < 256; i++) {
        printf("Fading GPIO17 to %d%%...\n", (int)((255 - i) * 100.0 / 255 + 0.5));
        if (gpioSetPWMdutycycle(GPIO17, 255 - i) < 0) {
            printf("Error setting PWM duty cycle for GPIO17: %s\n", strerror(errno));
            cleanup_and_exit(0);
        }
        sleep(total_duration / 256);
    }
    for (int i = 0; i < 256; i++) {
        printf("Fading GPIO18 to %d%%...\n", (int)((255 - i) * 100.0 / 255 + 0.5));
        if (gpioSetPWMdutycycle(GPIO18, 255 - i) < 0) {
            printf("Error setting PWM duty cycle for GPIO18: %s\n", strerror(errno));
            cleanup_and_exit(0);
        }
        sleep(total_duration / 256);
    }
    for (int i = 0; i < 256; i++) {
        printf("Fading GPIO27 to %d%%...\n", (int)((255 - i) * 100.0 / 255 + 0.5));
        if (gpioSetPWMdutycycle(GPIO27, 255 - i) < 0) {
            printf("Error setting PWM duty cycle for GPIO27: %s\n", strerror(errno));
            cleanup_and_exit(0);
        }
        sleep(total_duration / 256);
    }

    printf("All lamps have been faded to off.\n");

    cleanup_and_exit(0);

    return 0;
}

