#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define RELAY_GPIO 17
#define MPR121_ADDR 0x5A
#define I2C_BUS 1
#define TOUCH_THRESHOLD 0x0A
#define RELEASE_THRESHOLD 0x08
#define DEBOUNCE_DELAY 0x21
#define CHARGE_TIME 0x0D
#define MPR121_RUN_MODE 0x0D
#define MPR121_RESET 0x63
#define MPR121_STOP_MODE 0x00
#define MPR121_ENABLE_E0 0x01
#define MPR121_REG_TOUCH 0x00
#define MPR121_REG_RELEASE 0x01
#define LOG_FILE "touch_relay.log"

static int i2c_fd = -1;
static int gpio_handle = -1;
static FILE *log_file = NULL;

void log_error(const char *msg) {
    time_t t = time(NULL);
    char *time_str = ctime(&t);
    time_str[strlen(time_str) - 1] = '\0';  // remove trailing newline
    fprintf(log_file, "%s: %s\n", time_str, msg);
    fflush(log_file);
}

void close_resources(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (gpio_handle != -1) {
        gpioTerminate();
        gpio_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    exit(sig);
}

int main() {
    signal(SIGINT, close_resources);
    signal(SIGTERM, close_resources);

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    gpio_handle = gpioInitialise();
    if (gpio_handle < 0) {
        log_error("gpioInitialise failed");
        close_resources(gpio_handle);
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C device");
        close_resources(i2c_fd);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        log_error("Failed to set I2C slave address");
        close_resources(i2c_fd);
    }

    unsigned char buf[2] = {MPR121_REG_TOUCH, 0};
    if (write(i2c_fd, buf, 2) != 2) {
        log_error("Failed to write to I2C device");
        close_resources(i2c_fd);
    }

    buf[0] = MPR121_REG_RELEASE;
    buf[1] = RELEASE_THRESHOLD;
    if (write(i2c_fd, buf, 2) != 2) {
        log_error("Failed to write to I2C device");
        close_resources(i2c_fd);
    }

    buf[0] = DEBOUNCE_DELAY;
    buf[1] = DEBOUNCE_DELAY;
    if (write(i2c_fd, buf, 2) != 2) {
        log_error("Failed to write to I2C device");
        close_resources(i2c_fd);
    }

    buf[0] = CHARGE_TIME;
    buf[1] = CHARGE_TIME;
    if (write(i2c_fd, buf, 2) != 2) {
        log_error("Failed to write to I2C device");
        close_resources(i2c_fd);
    }

    buf[0] = MPR121_RUN_MODE;
    buf[1] = MPR121_RUN_MODE;
    if (write(i2c_fd, buf, 2) != 2) {
        log_error("Failed to write to I2C device");
        close_resources(i2c_fd);
    }

    // Main loop
    while (1) {
        usleep(10000);  // 10 ms delay

        if (read(i2c_fd, buf, 2) != 2) {
