        return 1;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    ret = gpiod_line_request_input(sensor_line, "sensor");
    if (ret < 0) {
        perror("gpiod_line_request_input");
        return 1;
    }

    ret = gpiod_line_request_output(buzzer_line, "buzzer", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        return 1;
    }

    ret = gpiod_line_request_output(led_line, "led", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        return 1;
    }

    log_file = fopen("flame_log.txt", "a");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    while (1) {
        int sensor_val, i;
        for (i = 0; i < 3; ++i) {
            sensor_val = gpiod_line_get_value(sensor_line);
            if (sensor_val < 0) {
                perror("gpiod_line_get_value");
                return 1;
            }
            usleep(50000);
        }

        if (sensor_val == 0) {
            gpiod_line_set_value(buzzer_line, 1);
            gpiod_line_set_value(led_line, 1);
            time_t t = time(NULL);
            struct tm tm = *localtime(&t);
            fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d: Flame Detected\n",
                    tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                    tm.tm_hour, tm.tm_min, tm.tm_sec);
        } else {
            gpiod_line_set_value(buzzer_line, 0);
            gpiod_line_set_value(led_line, 0);
        }
    }

    return 0;
}

