#define DISPENSE_DURATION_US 500000
#define LOG_FILE "dispense_log.txt"

FILE *log_file;

void sigint_handler(int signum) {
    piGpio(GPIO_SOLENOID_1, GPIO_LOW);
    piGpio(GPIO_SOLENOID_2, GPIO_LOW);
    piStop();
    exit(0);
}

int open_log_file() {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int close_log_file() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    return 0;
}

int log_dispense(int gpio, int duration) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d GPIO%d: %d ms\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, gpio, duration);
    return 0;
}

int main() {
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        return -1;
    }

    int pi = piGcd(0);
    if (pi < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioStrError(pi));
        return -1;
    }

    if (piGpio(GPIO_SOLENOID_1, GPIO_OUTPUT) < 0 ||
        piGpio(GPIO_SOLENOID_2, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to configure GPIO as output: %s\n", pigpioStrError(pi));
        return -1;
    }

    if (open_log_file() < 0) {
        return -1;
    }

    while (1) {
        piGpio(GPIO_SOLENOID_1, GPIO_HIGH);
        gpioDelay(DISPENSE_DURATION_US / 2);
        piGpio(GPIO_SOLENOID_2, GPIO_HIGH);
        gpioDelay(DISPENSE_DURATION_US / 2);
        piGpio(GPIO_SOLENOID_1, GPIO_LOW);
        piGpio(GPIO_SOLENOID_2, GPIO_LOW);

        if (log_dispense(GPIO_SOLENOID_1, DISPENSE_DURATION_US / 2) < 0 ||
            log_dispense(GPIO_SOLENOID_2, DISPENSE_DURATION_US / 2) < 0) {
            fprintf(stderr, "Failed to log dispense event: %s\n", strerror(errno));
            return -1;
        }

        gpioDelay(5000000);
    }

    close_log_file();
    piStop();
    return 0;
}

