#define LOG_FILE "balance_log.txt"
#define Kp 1.0
#define Ki 0.01
#define Kd 0.1
#define MAX_SPEED 255
#define ENA 24
#define ENB 25
#define A_FWD 17
#define A_BCK 18
#define B_FWD 22
#define B_BCK 23

FILE *log_file;
double error_sum = 0.0;
double last_error = 0.0;

void log_data(double tilt_error, double distance, int motor_a_speed, int motor_b_speed) {
    time_t now = time(0);
    struct tm *time_info = localtime(&now);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%d,%d\n",
            time_info->tm_year + 1900, time_info->tm_mon + 1, time_info->tm_mday,
            time_info->tm_hour, time_info->tm_min, time_info->tm_sec,
            tilt_error, distance, motor_a_speed, motor_b_speed);
}

void handle_sigint(int signum) {
    gpioWrite(ENA, 0);
    gpioWrite(ENB, 0);
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    gpioSetMode(ENA, PI_OUTPUT);
    gpioSetMode(ENB, PI_OUTPUT);
    gpioSetMode(A_FWD, PI_OUTPUT);
    gpioSetMode(A_BCK, PI_OUTPUT);
    gpioSetMode(B_FWD, PI_OUTPUT);
    gpioSetMode(B_BCK, PI_OUTPUT);

    gpioWrite(ENA, 1);
    gpioWrite(ENB, 1);

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        double tilt_error = ((double) rand() / RAND_MAX * 20.0) - 10.0;
        double distance = ((double) rand() / RAND_MAX * 398.0) + 2.0;

        int motor_a_speed = Kp * tilt_error + MAX_SPEED;
        int motor_b_speed = Kp * tilt_error + MAX_SPEED;

        if (distance < 20.0) {
            motor_a_speed = motor_a_speed / 2;
            motor_b_speed = motor_b_speed / 2;
        }

        if (motor_a_speed < 0) {
            gpioWrite(A_FWD, 0);
            gpioWrite(A_BCK, 1);
            gpioPWM(A_BCK, -motor_a_speed);
        } else {
            gpioWrite(A_FWD, 1);
            gpioWrite(A_BCK, 0);
            gpioPWM(A_FWD, motor_a_speed);
        }

        if (motor_b_speed < 0) {
            gpioWrite(B_FWD, 0);
            gpioWrite(B_BCK, 1);
            gpioPWM(B_BCK, -motor_b_speed);
        } else {
            gpioWrite(B_FWD, 1);
            gpioWrite(B_BCK, 0);
            gpioPWM(B_FWD, motor_b_speed);
        }

        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        gpioDelay(50000);  // 50 ms
    }

    return 0;
}

