#include <pigpio.h>

#define SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_TIME 50

volatile sig_atomic_t stop = 0;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        stop = 1;
    }
}

int main() {
    int pi = pigpio_start(0, 0);

    if (pi < 0) {
        printf("pigpio_start() failed\n");
        return -1;
    }

    if (gpio_set_mode(pi, SENSOR_PIN, PI_INPUT) < 0) {
        printf("gpio_set_mode() failed for sensor pin\n");
        pigpio_stop(pi);
        return -1;
    }

    if (gpio_set_pull_up_down(pi, SENSOR_PIN, PI_PUD_DOWN) < 0) {
        printf("gpio_set_pull_up_down() failed for sensor pin\n");
        pigpio_stop(pi);
        return -1;
    }

    if (gpio_set_mode(pi, RELAY_PIN, PI_OUTPUT) < 0) {
        printf("gpio_set_mode() failed for relay pin\n");
        pigpio_stop(pi);
        return -1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    int sensor_state = 0;
    int relay_state = 0;

    while (!stop) {
        sensor_state = gpio_read(pi, SENSOR_PIN);

        if (sensor_state < 0) {
            printf("gpio_read() failed for sensor pin\n");
            pigpio_stop(pi);
            return -1;
        }

        if (sensor_state == 1) {
            relay_state = !relay_state;
            if (gpio_write(pi, RELAY_PIN, relay_state) < 0) {
                printf("gpio_write() failed for relay pin\n");
                pigpio_stop(pi);
                return -1;
            }
            msleep(DEBOUNCE_TIME);
        }
    }

    pigpio_stop(pi);

    return 0;
}

