#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <signal.h>
#include <alsa/asoundlib.h>
#include <pigpio.h>

#define ALSA_AVAILABLE

#define GPIO_RED   17
#define GPIO_GREEN 18
#define GPIO_BLUE  27

#define SAMPLE_RATE 8000
#define BITS_PER_SAMPLE 16
#define CHANNELS 1
#define PERIOD_FRAMES 1024

#define SINE_FREQUENCY 1000

snd_pcm_t *capture_handle;
snd_pcm_hw_params_t *hw_params;
float sensitivity = 1.0;

void exit_handler(int signum) {
    if (capture_handle) snd_pcm_close(capture_handle);
    gpioTerminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    if (argc > 1) {
        sensitivity = atof(argv[1]);
        if (sensitivity <= 0) {
            fprintf(stderr, "Sensitivity must be positive.\n");
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    gpioSetPWMrange(GPIO_RED, 10000);
    gpioSetPWMrange(GPIO_GREEN, 10000);
    gpioSetPWMrange(GPIO_BLUE, 10000);

    signal(SIGINT, exit_handler);
    signal(SIGTERM, exit_handler);

#ifdef ALSA_AVAILABLE
    int err;
    capture_handle = NULL;
    hw_params = NULL;

    if ((err = snd_pcm_open(&capture_handle, "default", SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Failed to open audio capture device: %s\n", snd_strerror(err));
        goto simulate_audio;
    }

    if ((err = snd_pcm_hw_params_malloc(&hw_params)) < 0) {
        fprintf(stderr, "Failed to allocate hardware parameters: %s\n", snd_strerror(err));
        goto error;
    }

    if ((err = snd_pcm_hw_params_any(capture_handle, hw_params)) < 0) {
        fprintf(stderr, "Failed to initialize hardware parameters: %s\n", snd_strerror(err));
        goto error;
    }

    if ((err = snd_pcm_hw_params_set_access(capture_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Failed to set access type: %s\n", snd_strerror(err));
        goto error;
    }

    if ((err = snd_pcm_hw_params_set_format(capture_handle, hw_params, SND_PCM_FORMAT_S16_LE)) < 0) {
        fprintf(stderr, "Failed to set sample format: %s\n", snd_strerror(err));
        goto error;
    }

    if ((err = snd_pcm_hw_params_set_rate(capture_handle, hw_params, SAMPLE_RATE, 0)) < 0) {
        fprintf(stderr, "Failed to set sample rate: %s\n", snd_strerror(err));
        goto error;
    }

    if ((err = snd_pcm_hw_params_set_channels(capture_handle, hw_params, CHANNELS)) < 0) {
        fprintf(stderr, "Failed to set channel count: %s\n", snd_strerror(err));
        goto error;
    }

    if ((err = snd_pcm_hw_params_set_period_size(capture_handle, hw_params, PERIOD_FRAMES, 0)) < 0) {
        fprintf(stderr, "Failed to set period size: %s\n", snd_strerror(err));
        goto error;
    }

    if ((err = snd_pcm_hw_params(capture_handle, hw_params)) < 0) {
        fprintf(stderr, "Failed to set hardware parameters: %s\n", snd_strerror(err));
        goto error;
    }

    snd_pcm_hw_params_free(hw_params);
    hw_params = NULL;

    short buffer[PERIOD_FRAMES];
    while (1) {
        int frames_read = snd_pcm_readi(capture_handle, buffer, PERIOD_FRAMES);
        if (frames_read == -EPIPE) {
            fprintf(stderr, "Buffer overrun, preparing...\n");
            snd_pcm_prepare(capture_handle);
        } else if (frames_read == -ESTRPIPE) {
            fprintf(stderr, "Device is suspended, resuming...\n");
            snd_pcm_resume(capture_handle);
        } else if (frames_read < 0) {
            fprintf(stderr, "Error reading from audio capture device: %s\n", snd_strerror(frames_read));
            exit_handler(0);
        }

        long long sum = 0;
        for (int i = 0; i < frames_read; i++) {
            sum += buffer[i] * buffer[i];
        }

        float rms = sqrt(sum / (float)frames_read);
        float scaled_rms = rms * sensitivity;

        // Map the RMS to RGB values with a non-linear transition
        int red = scaled_rms * 10000;
        int green = scaled_rms * 10000;
        int blue = scaled_rms * 10000;

        gpioSetPWMdutycycle(GPIO_RED, red);
        gpioSetPWMdutycycle(GPIO_GREEN, green);
        gpioSetPWMdutycycle(GPIO_BLUE, blue);

        usleep(10000);
    }

error:
    if (hw_params) snd_pcm_hw_params_free(hw_params);
    if (capture_handle) snd_pcm_close(capture_handle);
    exit_handler(0);

simulate_audio:
#endif
    // Simulate audio input with a sine wave
    float phase = 0;
    while (1) {
        phase += (2 * M_PI * SINE_FREQUENCY) / SAMPLE_RATE;
        float sample = sin(phase);
        float scaled_sample = sample * sensitivity;

        int red = scaled_sample * 10000;
        int green = scaled_sample * 10000;
        int blue = scaled_sample * 10000;

        gpioSetPWMdutycycle(GPIO_RED, red);
        gpioSetPWMdutycycle(GPIO_GREEN, green);
        gpioSetPWMdutycycle(GPIO_BLUE, blue);

        usleep(10000);
    }

    return 0;
}

