#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define I2C_HANDLE -1

FILE *file = NULL;
int i2c_handle = I2C_HANDLE;

void write_reg(int reg, int value) {
    if (i2cWriteByte(i2c_handle, reg) != 0 || i2cWriteByte(i2c_handle, value) != 0) {
        fprintf(stderr, "I2C write error\n");
    }
}

int read_reg(int reg) {
    if (i2cWriteByte(i2c_handle, reg) != 0) {
        fprintf(stderr, "I2C write error\n");
        return 0;
    }

    int value;
    if (i2cReadByte(i2c_handle, &value) != 0) {
        fprintf(stderr, "I2C read error\n");
        return 0;
    }

    return value;
}

void signal_handler(int signum) {
    if (i2c_handle != I2C_HANDLE) {
        i2cClose(i2c_handle);
    }

    if (file != NULL) {
        fclose(file);
    }

    gpioTerminate();

    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise error\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen error\n");
        return EXIT_FAILURE;
    }

    file = fopen("color_data.csv", "w");
    if (file == NULL) {
        fprintf(stderr, "fopen error\n");
        return EXIT_FAILURE;
    }

    fprintf(file, "timestamp,clear,red,green,blue\n");

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    write_reg(0x80, 0x03);
    write_reg(0x81, 0xD5);

    while (1) {
        int clear = read_reg(0x14) | read_reg(0x15) << 8;
        int red = read_reg(0x16) | read_reg(0x17) << 8;
        int green = read_reg(0x18) | read_reg(0x19) << 8;
        int blue = read_reg(0x1A) | read_reg(0x1B) << 8;

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char buffer[80];
        strftime(buffer, sizeof(buffer), "%d-%m-%Y %H:%M:%S", timeinfo);

        fprintf(file, "%s,%d,%d,%d,%d\n", buffer, clear, red, green, blue);
        fflush(file);

        gpioDelay(500000);
    }

    return EXIT_SUCCESS;
}

