#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define CHIP_NAME "gpiochip0"
#define GPIO_PINS "11,13,15,17"
#define SUNRISE_SECONDS 3600
#define DAYTIME_SECONDS 21600
#define SUNSET_SECONDS 3600
#define NIGHTTIME_SECONDS 52200

struct gpiod_chip *chip;
struct gpiod_line *lines[4];
int line_values[4] = {0, 0, 0, 0};

void sig_handler(int signo) {
    for (int i = 0; i < 4; i++) {
        gpiod_line_set_value(lines[i], 1);
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(1);
    }

    char *pin_str = strtok(GPIO_PINS, ",");
    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, atoi(pin_str));
        if (!lines[i]) {
            perror("gpiod_line_get");
            exit(1);
        }
        if (gpiod_line_request_output(lines[i], "my-program", 1)) {
            perror("gpiod_line_request_output");
            exit(1);
        }
        pin_str = strtok(NULL, ",");
    }

    while (1) {
        for (int i = 0; i < SUNRISE_SECONDS; i++) {
            for (int j = 0; j < 4; j++) {
                line_values[j] = (i * 25) / SUNRISE_SECONDS;
                gpiod_line_set_value(lines[j], line_values[j]);
            }
            sleep(1);
        }

        for (int i = 0; i < DAYTIME_SECONDS; i++) {
            for (int j = 0; j < 4; j++) {
                gpiod_line_set_value(lines[j], 255);
            }
            sleep(1);
        }

        for (int i = SUNRISE_SECONDS; i >= 0; i--) {
            for (int j = 0; j < 4; j++) {
                line_values[j] = (i * 25) / SUNRISE_SECONDS;
                gpiod_line_set_value(lines[j], line_values[j]);
            }
            sleep(1);
        }

        for (int i = 0; i < NIGHTTIME_SECONDS; i++) {
            for (int j = 0; j < 4; j++) {
                gpiod_line_set_value(lines[j], 0);
            }
            sleep(1);
        }
    }

    return 0;
}

