            exit(1);
        }
        if (gpiod_line_request_output(lines[i], "my-program", 1)) {
            perror("gpiod_line_request_output");
            exit(1);
        }
        pin_str = strtok(NULL, ",");
    }

    while (1) {
        for (int i = 0; i < SUNRISE_SECONDS; i++) {
            for (int j = 0; j < 4; j++) {
                line_values[j] = (i * 25) / SUNRISE_SECONDS;
                gpiod_line_set_value(lines[j], line_values[j]);
            }
            sleep(1);
        }

        for (int i = 0; i < DAYTIME_SECONDS; i++) {
            for (int j = 0; j < 4; j++) {
                gpiod_line_set_value(lines[j], 255);
            }
            sleep(1);
        }

        for (int i = SUNRISE_SECONDS; i >= 0; i--) {
            for (int j = 0; j < 4; j++) {
                line_values[j] = (i * 25) / SUNRISE_SECONDS;
                gpiod_line_set_value(lines[j], line_values[j]);
            }
            sleep(1);
        }

        for (int i = 0; i < NIGHTTIME_SECONDS; i++) {
            for (int j = 0; j < 4; j++) {
                gpiod_line_set_value(lines[j], 0);
            }
            sleep(1);
        }
    }

    return 0;
}
