#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68
#define I2C_HANDLE -1

#define REG_PWR_MGMT_1 0x6B
#define REG_SMPLRT_DIV 0x19
#define REG_GYRO_CONFIG 0x1B
#define REG_GYRO_XOUT_H 0x43

#define SLEEP_MS 10
#define INIT_RETRIES 3
#define SENSITIVITY 131.0

FILE *log_file = NULL;
int i2c_handle = I2C_HANDLE;

void sig_handler(int signo) {
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle != I2C_HANDLE) {
        i2cClose(i2c_handle);
    }
    exit(signo);
}

int init_sensor() {
    int retries = INIT_RETRIES;
    while (retries--) {
        if (i2cWriteByteData(i2c_handle, REG_PWR_MGMT_1, 0x00) != 0) {
            printf("Failed to wake sensor, retrying...\n");
            continue;
        }
        if (i2cWriteByteData(i2c_handle, REG_SMPLRT_DIV, 0x07) != 0) {
            printf("Failed to set sample rate, retrying...\n");
            continue;
        }
        if (i2cWriteByteData(i2c_handle, REG_GYRO_CONFIG, 0x00) != 0) {
            printf("Failed to set gyroscope range, retrying...\n");
            continue;
        }
        return 0;
    }
    return -1;
}

int main() {
    struct timespec ts;
    int16_t data[3];

    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio.\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        printf("Failed to open I2C bus.\n");
        return -1;
    }

    if (init_sensor() != 0) {
        printf("Failed to initialize sensor.\n");
        return -1;
    }

    log_file = fopen("gyro_log.csv", "w");
    if (log_file == NULL) {
        printf("Failed to open log file.\n");
        return -1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");

    while (1) {
        if (i2cReadI2CBlockData(i2c_handle, REG_GYRO_XOUT_H, 6, (uint8_t *)data) != 6) {
            printf("Failed to read gyroscope data.\n");
            if (init_sensor() != 0) {
                printf("Failed to re-initialize sensor.\n");
                return -1;
            }
            continue;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%03ld,%.2f,%.2f,%.2f\n", ts.tv_sec, ts.tv_nsec / 1e6,
                data[0] * SENSITIVITY, data[1] * SENSITIVITY, data[2] * SENSITIVITY);

        usleep(SLEEP_MS * 1000);
    }

    return 0;
}

