        if (moisture < 30) {
            if (piGPIO_WRITE(GPIO_RELE4, 0) < 0 ||
                piGPIO_WRITE(GPIO_RELE17, 0) < 0 ||
                piGPIO_WRITE(GPIO_RELE27, 0) < 0 ||
