                printf("Error writing to GPIO\n");
                return 1;
            }
        } else {
            if (piGPIO_WRITE(GPIO_RELE4, 1) < 0 ||
                piGPIO_WRITE(GPIO_RELE17, 1) < 0 ||
                piGPIO_WRITE(GPIO_RELE27, 1) < 0 ||
                piGPIO_WRITE(GPIO_RELE22, 1) < 0) {
                printf("Error writing to GPIO\n");
                return 1;
            }
        }

        fprintf(log_file, "%s: Moisture: %d, Relays: %s\n", timestamp, moisture, (moisture < 30) ? "Active" : "Inactive");
        fflush(log_file);

        sleep(5);
    }

    return 0;
}

