#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define ADXL345_I2C_ADDR 0x53
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define SCALE_FACTOR 256.0
#define FREE_FALL_THRESHOLD 0.2
#define FREE_FALL_DURATION 500
#define GPIO_ALARM 27

int i2c_handle;
FILE *log_file;

void sigint_handler(int signo) {
    if (i2c_handle >= 0) {
        if (i2cUnwrite(i2c_handle) < 0) {
            fprintf(stderr, "i2cUnwrite error: %s\n", pigpio_error());
        }
        if (i2cClose(i2c_handle) < 0) {
            fprintf(stderr, "i2cClose error: %s\n", pigpio_error());
        }
    }
    if (gpioWrite(GPIO_ALARM, 0) < 0) {
        fprintf(stderr, "gpioWrite error: %s\n", pigpio_error());
    }
    if (gpioTerminate() < 0) {
        fprintf(stderr, "gpioTerminate error: %s\n", pigpio_error());
    }
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise error: %s\n", pigpio_error());
        return 1;
    }
    if (gpioSetMode(GPIO_ALARM, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode error: %s\n", pigpio_error());
        return 1;
    }
    i2c_handle = i2cOpen("/dev/i2c-1", ADXL345_I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen error: %s\n", pigpio_error());
        return 1;
    }
    if (i2cWriteByteData(i2c_handle, ADXL345_DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "i2cWriteByteData error: %s\n", pigpio_error());
        return 1;
    }
    if (i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "i2cWriteByteData error: %s\n", pigpio_error());
        return 1;
    }
    signal(SIGINT, sigint_handler);
    log_file = fopen("freefall.log", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Could not open freefall.log for writing\n");
        return 1;
    }
    int free_fall_count = 0;
    while (1) {
        int16_t data[3];
        for (int i = 0; i < 3; i++) {
            if (i2cReadWordData(i2c_handle, ADXL345_DATAX0 + 2 * i, &data[i]) < 0) {
                fprintf(stderr, "i2cReadWordData error: %s\n", pigpio_error());
                continue;
            }
        }
        int is_free_fall = 1;
        for (int i = 0; i < 3; i++) {
            if (data[i] / SCALE_FACTOR > FREE_FALL_THRESHOLD || data[i] / SCALE_FACTOR < -FREE_FALL_THRESHOLD) {
                is_free_fall = 0;
                break;
            }
        }
        if (is_free_fall) {
            free_fall_count++;
            if (free_fall_count * 100 >= FREE_FALL_DURATION) {
                time_t t = time(NULL);
                struct tm tm = *localtime(&t);
                fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, data[0] / SCALE_FACTOR, data[1] / SCALE_FACTOR, data[2] / SCALE_FACTOR);
                if (gpioWrite(GPIO_ALARM, 1) < 0) {
                    fprintf(stderr, "gpioWrite error: %s\n", pigpio_error());
                }
                sleep(5);
                if (gpioWrite(GPIO_ALARM, 0) < 0) {
                    fprintf(stderr, "gpioWrite error: %s\n", pigpio_error());
                }
            }
        } else {
            free_fall_count = 0;
        }
        sleep(1);
    }
    return 0;
}

