        int16_t data[3];
        for (int i = 0; i < 3; i++) {
            if (i2cReadWordData(i2c_handle, ADXL345_DATAX0 + 2 * i, &data[i]) < 0) {
                fprintf(stderr, "i2cReadWordData error: %s\n", pigpio_error());
                continue;
            }
        }
        int is_free_fall = 1;
        for (int i = 0; i < 3; i++) {
            if (data[i] / SCALE_FACTOR > FREE_FALL_THRESHOLD || data[i] / SCALE_FACTOR < -FREE_FALL_THRESHOLD) {
                is_free_fall = 0;
                break;
            }
        }
        if (is_free_fall) {
            free_fall_count++;
            if (free_fall_count * 100 >= FREE_FALL_DURATION) {
                time_t t = time(NULL);
                struct tm tm = *localtime(&t);
                fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, data[0] / SCALE_FACTOR, data[1] / SCALE_FACTOR, data[2] / SCALE_FACTOR);
                if (gpioWrite(GPIO_ALARM, 1) < 0) {
                    fprintf(stderr, "gpioWrite error: %s\n", pigpio_error());
                }
                sleep(5);
                if (gpioWrite(GPIO_ALARM, 0) < 0) {
                    fprintf(stderr, "gpioWrite error: %s\n", pigpio_error());
                }
            }
        } else {
            free_fall_count = 0;
        }
        sleep(1);
    }
    return 0;
}
