void echo_callback(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&mutex);
    if (level == 0) {
        echo_state = 0;
    } else {
        echo_state = 1;
        echo_tick = tick;
    }
    pthread_mutex_unlock(&mutex);
}

int main() {
    struct timeval tv;
    struct timespec ts;
    struct sigaction sigact;
    uint32_t trig_tick;
    int state;
    double distance;

    if (pthread_mutex_init(&mutex, NULL) != 0) {
        printf("Mutex init failed\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        printf("GPIO init failed\n");
        return 1;
    }

    file = fopen(FILE_NAME, "w");
    if (file == NULL) {
        printf("File open failed\n");
        return 1;
    }

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    gpioSetISRFunc(ECHO_PIN, echo_callback);

    sigact.sa_handler = sigint_handler;
    sigemptyset(&sigact.sa_mask);
    sigact.sa_flags = 0;
    sigaction(SIGINT, &sigact, NULL);

    while (1) {
        gpioWrite(TRIG_PIN, 1);
        usleep(TRIGGER_PULSE_US);
        gpioWrite(TRIG_PIN, 0);
        trig_tick = gpioTick();

        state = echo_state;
        while (state == 0) {
            usleep(100);
            if (gpioTick() - trig_tick > 100000) {
                printf("Sensor timeout\n");
                break;
            }
            state = echo_state;
        }

        if (state == 1) {
            pthread_mutex_lock(&mutex);
            if (echo_state == 1) {
                distance = (gpioTick() - echo_tick) * 1.0 / 100;
                if (distance > MAX_RANGE_US) {
                    printf("Invalid pulse width\n");
                } else {
                    gettimeofday(&tv, NULL);
                    ts.tv_sec = tv.tv_sec;
                    ts.tv_nsec = tv.tv_usec * 1000;
                    fprintf(file, "%ld,%.2f\n", ts.tv_sec * 1000000000 + ts.tv_nsec, distance / 2);
                    fflush(file);
                }
            }
            pthread_mutex_unlock(&mutex);
        }

        usleep(200000);
    }

    return 0;
}

