#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x18
#define GPIO_BUZZER 17

#define CTRL_REG1 0x20
#define CTRL_REG4 0x23

#define OUT_X_L 0x28

#define SENSITIVITY 16384.0

#define DEFAULT_FREEFALL_THRESHOLD 0.2
#define DEFAULT_IMPACT_THRESHOLD 1.5

static int i2c_fd = -1;
static int buzzer_gpio = -1;

static void cleanup(void) {
    if (i2c_fd != -1) {
        piI2CClose(i2c_fd);
        i2c_fd = -1;
    }
    if (buzzer_gpio != -1) {
        gpioWrite(buzzer_gpio, 0);
        gpioUnexport(buzzer_gpio);
        buzzer_gpio = -1;
    }
}

static void sigint_handler(int signum) {
    cleanup();
    exit(0);
}

int main(int argc, char *argv[]) {
    double freefall_threshold = DEFAULT_FREEFALL_THRESHOLD;
    double impact_threshold = DEFAULT_IMPACT_THRESHOLD;

    if (argc > 2) {
        fprintf(stderr, "Usage: %s [freefall_threshold [impact_threshold]]\n", argv[0]);
        return 1;
    } else if (argc > 1) {
        freefall_threshold = atof(argv[1]);
        if (argc > 2) {
            impact_threshold = atof(argv[2]);
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    buzzer_gpio = gpioExported(GPIO_BUZZER);
    if (buzzer_gpio < 0) {
        buzzer_gpio = gpioRequest(GPIO_BUZZER, "buzzer");
        if (buzzer_gpio < 0) {
            fprintf(stderr, "Failed to request GPIO %d\n", GPIO_BUZZER);
            gpioTerminate();
            return 1;
        }
        gpioSetMode(buzzer_gpio, PI_OUTPUT);
    }

    i2c_fd = piI2COpen(I2C_BUS, I2C_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d addr %02x\n", I2C_BUS, I2C_ADDR);
        cleanup();
        gpioTerminate();
        return 1;
    }

    if (piI2CWriteByteData(i2c_fd, CTRL_REG1, 0x77) < 0 ||
        piI2CWriteByteData(i2c_fd, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Failed to configure LIS3DH\n");
        cleanup();
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        int16_t x, y, z;
        for (int i = 0; i < 3; i++) {
            if (piI2CReadI2CBlockData(i2c_fd, OUT_X_L, 6, (uint8_t *)&x) < 0) {
                fprintf(stderr, "Failed to read acceleration data\n");
                continue;
            }
            y >>= 8;
            z >>= 8;
            break;
        }

        double magnitude = sqrt(x * x / SENSITIVITY + y * y / SENSITIVITY + z * z / SENSITIVITY);
        if (magnitude < freefall_threshold) {
            printf("Freefall detected\n");
        } else if (magnitude > impact_threshold) {
            printf("Impact detected\n");
            gpioWrite(buzzer_gpio, 1);
            sleep(1);
            gpioWrite(buzzer_gpio, 0);
        }
    }

    return 0;
}

