#define DEFAULT_I2C_ADDR 0x18
#define DEFAULT_THRESHOLD 2.0

int i2c_fd = -1;
float threshold = DEFAULT_THRESHOLD;
unsigned char i2c_addr = DEFAULT_I2C_ADDR;

void usage(char *prog) {
    printf("Usage: %s [-a hex_addr] [-t float_threshold]\n", prog);
    exit(1);
}

void cleanup_and_exit(int sig) {
    if (i2c_fd != -1) {
        i2cClose(i2c_fd);
    }
    piGpioTerminate();
    exit(0);
}

void handle_error(int error, char *msg) {
    if (error < 0) {
        printf("%s: %s\n", msg, strerror(-error));
        cleanup_and_exit(0);
    }
}

void log_high_acceleration(float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    FILE *log = fopen("/var/log/high_acceleration.log", "a");
    if (log == NULL) {
        printf("Failed to open log file: %s\n", strerror(errno));
        return;
    }
    fprintf(log, "%04d-%02d-%02d %02d:%02d:%02d: Acceleration exceeded threshold: X=%.2f, Y=%.2f, Z=%.2f\n",
