#define LEFT_SENSOR 4
#define CENTER_SENSOR 17
#define RIGHT_SENSOR 17
#define ALERT_PIN 22
#define BUF_SIZE 5

struct gpiod_chip *chip;
struct gpiod_line *sensor_lines[3];
struct gpiod_line *alert_line;
int buf[BUF_SIZE];
int buf_idx = 0;
int no_line_count = 0;

void cleanup_and_exit(int signum) {
    gpiod_line_release(sensor_lines[0]);
    gpiod_line_release(sensor_lines[1]);
    gpiod_line_release(sensor_lines[2]);
    gpiod_line_release(alert_line);
    gpiod_chip_close(chip);
    printf("Exiting on signal %d\n", signum);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    sensor_lines[0] = gpiod_chip_get_line(chip, LEFT_SENSOR);
    sensor_lines[1] = gpiod_chip_get_line(chip, CENTER_SENSOR);
    sensor_lines[2] = gpiod_chip_get_line(chip, RIGHT_SENSOR);
    alert_line = gpiod_chip_get_line(chip, ALERT_PIN);

    for (int i = 0; i < 3; i++) {
        if (!sensor_lines[i]) {
            perror("gpiod_chip_get_line");
            cleanup_and_exit(0);
        }
        if (gpiod_line_request_input(sensor_lines[i], "sensor", 0)) {
            perror("gpiod_line_request_input");
            cleanup_and_exit(0);
        }
    }

    if (!alert_line) {
        perror("gpiod_chip_get_line");
        cleanup_and_exit(0);
    }
    if (gpiod_line_request_output(alert_line, "alert", 0)) {
        perror("gpiod_line_request_output");
        cleanup_and_exit(0);
    }

    while (1) {
        int left = gpiod_line_get_value(sensor_lines[0]);
        int center = gpiod_line_get_value(sensor_lines[1]);
        int right = gpiod_line_get_value(sensor_lines[2]);

        printf("Sensor readings: left %d, center %d, right %d\n", left, center, right);

        buf[buf_idx] = center;
        buf_idx = (buf_idx + 1) % BUF_SIZE;

        if (center == 0) {
            no_line_count++;
            if (no_line_count >= 5) {
                gpiod_line_set_value(alert_line, 1);
                sleep(2);
                gpiod_line_set_value(alert_line, 0);
                no_line_count = 0;
            }
        } else {
            no_line_count = 0;
        }

        usleep(10000);  // 10 ms
    }

    return 0;
}

