#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <i2c.h>

#define I2C_BUS 1
#define I2C_ADDR 0x30
#define GPIO_RELAY 17
#define THRESHOLD 500
#define SAMPLE_INTERVAL 100
#define MAX_POLL_ATTEMPTS 50

static int i2c_handle;
static int is_relay_active = 0;

void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
    printf("%s %s\n", timestamp, event);
    fflush(stdout);
}

void sigint_handler(int signum) {
    gpioWrite(GPIO_RELAY, 0);
    gpioTerminate();
    i2cClose(i2c_handle);
    log_event("Shutdown");
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);

    if (gpioInitialise() < 0) {
        log_event("Error initializing pigpio");
        return 1;
    }

    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioWrite(GPIO_RELAY, 0);

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        log_event("Error opening I2C device");
        gpioTerminate();
        return 1;
    }

    while (1) {
        int poll_attempts = 0;
        int read_status = i2cWriteByteData(i2c_handle, 0xC1, 0x01);
        if (read_status < 0) {
            log_event("Error writing to sensor");
            continue;
        }

        while (1) {
            read_status = i2cReadByteData(i2c_handle, 0xC1);
            if (read_status < 0) {
                log_event("Error reading from sensor");
                break;
            }
            if (read_status == 0x00) break;
            if (poll_attempts++ > MAX_POLL_ATTEMPTS) {
                log_event("Sensor poll timeout");
                break;
            }
        }

        if (read_status != 0x00) {
            gpioWrite(GPIO_RELAY, 0);
            is_relay_active = 0;
            log_event("Deactivated relay due to error");
            continue;
        }

        int field_raw = 0;
        read_status = i2cReadByteData(i2c_handle, 0xC0);
        if (read_status < 0) {
            log_event("Error reading field data");
            gpioWrite(GPIO_RELAY, 0);
            is_relay_active = 0;
            continue;
        }
        field_raw |= read_status;

        read_status = i2cReadByteData(i2c_handle, 0xC1);
        if (read_status < 0) {
            log_event("Error reading field data");
            gpioWrite(GPIO_RELAY, 0);
            is_relay_active = 0;
            continue;
        }
        field_raw |= read_status << 8;

        int field_mT_x100 = field_raw * 25 / 1000;
        if (field_mT_x100 > THRESHOLD) {
            if (!is_relay_active) {
                gpioWrite(GPIO_RELAY, 1);
                is_relay_active = 1;
                log_event("Activated relay");
            }
        } else {
            if (is_relay_active) {
                gpioWrite(GPIO_RELAY, 0);
                is_relay_active = 0;
                log_event("Deactivated relay");
            }
        }

        usleep(SAMPLE_INTERVAL * 1000);
    }

    return 0;
}

