#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define PORT 5000
#define GPIO 18
#define MAX_COMMAND_LEN 10

int sockfd, newsockfd;
FILE *log_file;

void handle_signal(int signo) {
    if (sockfd != -1) close(sockfd);
    if (newsockfd != -1) close(newsockfd);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main() {
    struct sockaddr_in serv_addr, cli_addr;
    char client_buffer[MAX_COMMAND_LEN];
    socklen_t cli_len;
    time_t t;
    struct tm *tm;
    char date[20];

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpioInitialise() < 0) {
        printf("Error initializing GPIO\n");
        return 1;
    }

    gpioSetMode(GPIO, PI_OUTPUT);

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        printf("Error creating socket\n");
        return 1;
    }

    bzero((char *) &serv_addr, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_addr.s_addr = INADDR_ANY;
    serv_addr.sin_port = htons(PORT);

    if (bind(sockfd, (struct sockaddr *) &serv_addr, sizeof(serv_addr)) < 0) {
        printf("Error on binding\n");
        return 1;
    }

    listen(sockfd, 5);
    cli_len = sizeof(cli_addr);

    log_file = fopen("relay_log.txt", "a");
    if (log_file == NULL) {
        printf("Error opening log file\n");
        return 1;
    }

    while (1) {
        newsockfd = accept(sockfd, (struct sockaddr *) &cli_addr, &cli_len);
        if (newsockfd < 0) {
            printf("Error on accept\n");
            return 1;
        }

        bzero(client_buffer, MAX_COMMAND_LEN);
        if (read(newsockfd, client_buffer, MAX_COMMAND_LEN) < 0) {
            printf("Error reading from client\n");
            return 1;
        }

        t = time(NULL);
        tm = localtime(&t);
        strftime(date, sizeof(date), "%Y-%m-%d %H:%M:%S", tm);

        if (strcasecmp(client_buffer, "ON\n") == 0) {
            gpioWrite(GPIO, 1);
            fprintf(log_file, "%s: Relay turned ON\n", date);
        } else if (strcasecmp(client_buffer, "OFF\n") == 0) {
            gpioWrite(GPIO, 0);
            fprintf(log_file, "%s: Relay turned OFF\n", date);
        } else {
            fprintf(log_file, "%s: Invalid command received\n", date);
        }

        close(newsockfd);
    }

    return 0;
}

