        if (read(newsockfd, client_buffer, MAX_COMMAND_LEN) < 0) {
            printf("Error reading from client\n");
            return 1;
        }

        t = time(NULL);
        tm = localtime(&t);
        strftime(date, sizeof(date), "%Y-%m-%d %H:%M:%S", tm);

        if (strcasecmp(client_buffer, "ON\n") == 0) {
            gpioWrite(GPIO, 1);
            fprintf(log_file, "%s: Relay turned ON\n", date);
        } else if (strcasecmp(client_buffer, "OFF\n") == 0) {
            gpioWrite(GPIO, 0);
            fprintf(log_file, "%s: Relay turned OFF\n", date);
        } else {
            fprintf(log_file, "%s: Invalid command received\n", date);
        }

        close(newsockfd);
    }

    return 0;
}
```

This code initializes the GPIO and sets up a TCP server on port 5000. It listens for "ON" and "OFF" commands from any client and turns the relay connected to GPIO 18 on or off accordingly. It logs every activation, deactivation, and invalid command with a timestamp. It handles SIGINT and SIGTERM to ensure clean resource release on every exit path.

