#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR1 0x08
#define I2C_ADDR2 0x09
#define GPIO_RELAY 18

#define CRC8_POLY 0x31
#define CRC8_INIT 0xFF

volatile sig_atomic_t shutdown = 0;
int i2c_handle1 = -1, i2c_handle2 = -1;

void handle_signal(int signum) {
    shutdown = 1;
}

uint8_t crc8(const uint8_t *data, size_t len, uint8_t crc) {
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC8_POLY;
            else
                crc <<= 1;
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    i2c_handle1 = gpioI2CSetup(I2C_BUS, I2C_ADDR1, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C handle for sensor 1.\n");
        goto cleanup;
    }

    i2c_handle2 = gpioI2CSetup(I2C_BUS, I2C_ADDR2, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C handle for sensor 2.\n");
        goto cleanup;
    }

    if (gpioWrite(GPIO_RELAY, 0) < 0) {
        fprintf(stderr, "Failed to initialize relay GPIO.\n");
        goto cleanup;
    }

    uint8_t cmd[] = {0x36, 0x08};
    if (gpioI2CWriteDevice(i2c_handle1, cmd, sizeof(cmd)) < 0 ||
        gpioI2CWriteDevice(i2c_handle2, cmd, sizeof(cmd)) < 0) {
        fprintf(stderr, "Failed to send start-measurement command.\n");
        goto cleanup;
    }

    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = handle_signal;
    if (sigaction(SIGINT, &action, NULL) < 0 || sigaction(SIGTERM, &action, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handler.\n");
        goto cleanup;
    }

    FILE *log = fopen("flow_log.txt", "a");
    if (!log) {
        fprintf(stderr, "Failed to open log file.\n");
        goto cleanup;
    }

    while (!shutdown) {
        uint8_t data1[3], data2[3];
        int16_t flow1, flow2;
        uint8_t crc;

        if (gpioI2CReadDevice(i2c_handle1, data1, sizeof(data1)) != sizeof(data1) ||
            gpioI2CReadDevice(i2c_handle2, data2, sizeof(data2)) != sizeof(data2)) {
            fprintf(stderr, "Failed to read sensor data.\n");
            continue;
        }

        crc = crc8(data1, sizeof(data1) - 1, CRC8_INIT);
        if (crc != data1[2] || crc != data2[2]) {
            fprintf(stderr, "CRC mismatch.\n");
            continue;
        }

        flow1 = (data1[0] << 8) | data1[1];
        flow2 = (data2[0] << 8) | data2[1];

        flow1 = 1.0 / 1500.0 * flow1;
        flow2 = 1.0 / 1500.0 * flow2;

        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log, "%ld.%09ld: %.2f, %.2f\n", ts.tv_sec, ts.tv_nsec, (double)flow1, (double)flow2);
        fflush(log);

        if (flow1 < 5.0 || flow2 < 5.0)
            gpioWrite(GPIO_RELAY, 1);
        else
            gpioWrite(GPIO_RELAY, 0);

        usleep(100000);  // 100 ms
    }

    fclose(log);
    gpioWrite(GPIO_RELAY, 0);

cleanup:
    if (i2c_handle1 >= 0)
        gpioI2CClose(i2c_handle1);
    if (i2c_handle2 >= 0)
        gpioI2CClose(i2c_handle2);
    gpioTerminate();

    printf("Shutdown complete.\n");
    return EXIT_SUCCESS;
}

