#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 17
#define WINDOW_MOTOR_ENA 22
#define WINDOW_MOTOR_IN1 23
#define WINDOW_MOTOR_IN2 24
#define POLL_INTERVAL_MS 200
#define MOTOR_RUN_TIME_MS 5000
#define DRY_CONSECUTIVE_POLLS 3

volatile int should_exit = 0;

void handle_signal(int signum) {
    should_exit = 1;
}

int main() {
    openlog("rain_window", LOG_PID, LOG_USER);
    syslog(LOG_INFO, "Starting rain window controller");

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(WINDOW_MOTOR_ENA, PI_OUTPUT);
    gpioSetMode(WINDOW_MOTOR_IN1, PI_OUTPUT);
    gpioSetMode(WINDOW_MOTOR_IN2, PI_OUTPUT);

    gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PULL_UP);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int sensor_value = gpioRead(RAIN_SENSOR_PIN);
    int dry_polls = 0;

    while (!should_exit) {
        int new_sensor_value = gpioRead(RAIN_SENSOR_PIN);

        if (new_sensor_value == 0 && sensor_value == 1) {
            // Transition from wet to dry
            dry_polls = 0;
        } else if (new_sensor_value == 1 && sensor_value == 0) {
            // Transition from dry to wet
            if (++dry_polls >= DRY_CONSECUTIVE_POLLS) {
                syslog(LOG_INFO, "Rain detected, closing window");
                if (gpioWrite(WINDOW_MOTOR_ENA, 1) < 0 ||
                    gpioWrite(WINDOW_MOTOR_IN1, 1) < 0 ||
                    gpioWrite(WINDOW_MOTOR_IN2, 0) < 0) {
                    syslog(LOG_WARNING, "Failed to start motor");
                }
                gpioDelay(MOTOR_RUN_TIME_MS);
                if (gpioWrite(WINDOW_MOTOR_ENA, 0) < 0 ||
                    gpioWrite(WINDOW_MOTOR_IN1, 0) < 0 ||
                    gpioWrite(WINDOW_MOTOR_IN2, 0) < 0) {
                    syslog(LOG_WARNING, "Failed to stop motor");
                }
                syslog(LOG_INFO, "Window closed");
            }
        }

        sensor_value = new_sensor_value;
        gpioDelay(POLL_INTERVAL_MS);
    }

    // Cleanup
    gpioWrite(WINDOW_MOTOR_ENA, 0);
    gpioWrite(WINDOW_MOTOR_IN1, 0);
    gpioWrite(WINDOW_MOTOR_IN2, 0);

    gpioTerminate();

    syslog(LOG_INFO, "Exiting");

    closelog();

    return EXIT_SUCCESS;
}

