#define GPIO_SERVO 18
#define GPIO_LOCK_BUTTON 21
#define GPIO_UNLOCK_BUTTON 22

volatile sig_atomic_t stop = 0;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        stop = 1;
    }
}

int main() {
    int servo_pulse = 0;
    int last_lock_button_state = 0;
    int last_unlock_button_state = 0;

    int pi = gpioInitialise();
    if (pi < 0) {
        fprintf(stderr, "gpioInitialise() failed: %s\n", pigpio_error(pi));
        return EXIT_FAILURE;
    }

    gpioSetPullUpDown(GPIO_LOCK_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(GPIO_UNLOCK_BUTTON, PI_PUD_UP);

    struct sigaction sigIntHandler;
    sigIntHandler.sa_handler = sig_handler;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_flags = 0;
    sigaction(SIGINT, &sigIntHandler, NULL);
    sigaction(SIGTERM, &sigIntHandler, NULL);

    while (!stop) {
        int lock_button_state = gpioRead(GPIO_LOCK_BUTTON);
        int unlock_button_state = gpioRead(GPIO_UNLOCK_BUTTON);

        if (lock_button_state != last_lock_button_state) {
            if (lock_button_state == 0) {
                servo_pulse = 2000;
                printf("Locking the door...\n");
            }
            last_lock_button_state = lock_button_state;
        }

        if (unlock_button_state != last_unlock_button_state) {
            if (unlock_button_state == 0) {
                servo_pulse = 1000;
                printf("Unlocking the door...\n");
            }
            last_unlock_button_state = unlock_button_state;
        }

        int result = gpioServo(GPIO_SERVO, servo_pulse);
        if (result < 0) {
            fprintf(stderr, "gpioServo() failed: %s\n", pigpio_error(result));
            gpioTerminate();
            return EXIT_FAILURE;
        }

        sleep(1);
    }

    printf("Shutting down...\n");
    gpioServo(GPIO_SERVO, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

