#define PIR_SENSOR_PIN 4
#define LED_RELAY_CONTROL_PIN 17
#define LOG_FILE "security_log.txt"

volatile sig_atomic_t stop = 0;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        stop = 1;
    }
}

void log_event(const char* event, int duration) {
    time_t now = time(0);
    struct tm* time_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", time_info);

    FILE* log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        printf("Error opening log file.\n");
        gpioWrite(LED_RELAY_CONTROL_PIN, 0);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    fprintf(log_file, "%s: %s, %d seconds\n", timestamp, event, duration);
    fclose(log_file);
}

int main() {
    int pi = pigpio_start(0, 0);
    if (pi < 0) {
        printf("Error initializing pigpio.\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(PIR_SENSOR_PIN, PI_INPUT) < 0 || gpioSetMode(LED_RELAY_CONTROL_PIN, PI_OUTPUT) < 0) {
        printf("Error setting GPIO modes.\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (!stop) {
        if (gpioRead(PIR_SENSOR_PIN) == 1) {
            if (gpioWrite(LED_RELAY_CONTROL_PIN, 1) < 0) {
                printf("Error activating LED floodlight.\n");
                gpioTerminate();
                exit(EXIT_FAILURE);
            }

            log_event("Floodlight activated", 60);

            for (int i = 0; i < 600 && !stop; i++) {
                sleep(100);
            }

            if (gpioWrite(LED_RELAY_CONTROL_PIN, 0) < 0) {
                printf("Error deactivating LED floodlight.\n");
                gpioTerminate();
                exit(EXIT_FAILURE);
            }

            log_event("Floodlight deactivated", 0);
        }

        sleep(100);
    }

    if (gpioWrite(LED_RELAY_CONTROL_PIN, 0) < 0) {
        printf("Error deactivating LED floodlight.\n");
    }

    gpioTerminate();
    exit(EXIT_SUCCESS);
}

