#include <stdio.h>
#include <stdlib.h>
#include <stdarg.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <syslog.h>
#include <libgpiod.h>
#include <time.h>

#define GPIO_SERVO 17
#define GPIO_PIR 4
#define PORT 5000

struct gpiod_line *line_servo, *line_pir;
FILE *log_file;
int servo_angle;
pthread_t servo_thread;

void log_event(const char *fmt, ...)
{
    va_list args;
    char buffer[256];
    struct tm *timeinfo;
    time_t now = time(0);
    timeinfo = localtime(&now);

    sprintf(buffer, "%d-%02d-%02d %02d:%02d:%02d ", timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday, timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec);

    va_start(args, fmt);
    vsnprintf(buffer + strlen(buffer), sizeof(buffer) - strlen(buffer), fmt, args);
    va_end(args);

    syslog(LOG_USER | LOG_INFO, "%s", buffer);

    if (log_file)
        fprintf(log_file, "%s\n", buffer);
}

void *servo_loop(void *unused)
{
    while (1)
    {
        gpiod_line_set_value(line_servo, (servo_angle * 2000) / 180 + 1000);
        usleep(2000);
        gpiod_line_set_value(line_servo, 0);
        usleep(2000 * (180 - servo_angle) / 180);
    }

    return NULL;
}

void handle_command(const char *cmd)
{
    char command[10];
    int angle;

    sscanf(cmd, "%s %d", command, &angle);

    if (strcmp(command, "SERVO") == 0 && angle >= 0 && angle <= 180)
    {
        servo_angle = angle;
        log_event("Set servo angle to %d", angle);
    }
    else if (strcmp(command, "PIR") == 0)
    {
        int value = gpiod_line_get_value(line_pir);
        log_event("PIR: %d", value);
    }
    else
    {
        log_event("Invalid command: %s", cmd);
    }
}

void sig_handler(int signum)
{
    pthread_cancel(servo_thread);
    gpiod_line_release(line_servo);
    gpiod_line_release(line_pir);
    close(socket);
    fclose(log_file);
    closelog();
    exit(0);
}

int main()
{
    struct sockaddr_in serv_addr;
    int socket, c;
    char buffer[256];

    openlog("rpi_server", LOG_PERROR, LOG_USER);
    log_file = fopen("security.log", "a");

    if (!log_file)
    {
        log_event("Failed to open log file");
        closelog();
        return 1;
    }

    socket = socket(AF_INET, SOCK_STREAM, 0);

    if (socket < 0)
    {
        log_event("Failed to create socket");
        closelog();
        return 1;
    }

    memset(&serv_addr, '0', sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_addr.s_addr = htonl(INADDR_ANY);
    serv_addr.sin_port = htons(PORT);

    if (bind(socket, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0)
    {
        log_event("Bind failed");
        closelog();
        return 1;
    }

    if (listen(socket, 5) < 0)
    {
        log_event("Listen failed");
        closelog();
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("/dev/gpiochip0");

    if (!chip)
    {
        log_event("Failed to open GPIO chip");
        closelog();
        return 1;
    }

    line_servo = gpiod_chip_get_line(chip, GPIO_SERVO);
    line_pir = gpiod_chip_get_line(chip, GPIO_PIR);

    if (!line_servo || !line_pir)
    {
        log_event("Failed to get GPIO lines");
        closelog();
        return 1;
    }

    if (gpiod_line_request_output(line_servo, "servo", 0) < 0)
    {
        log_event("Failed to request output for servo");
        closelog();
        return 1;
    }

    if (gpiod_line_request_input(line_pir, "pir") < 0)
    {
        log_event("Failed to request input for PIR");
        closelog();
        return 1;
    }

    pthread_create(&servo_thread, NULL, servo_loop, NULL);

    while (1)
    {
        c = accept(socket, NULL, NULL);

        if (c < 0)
        {
            log_event("Accept failed");
            closelog();
            return 1;
        }

        if (read(c, buffer, 255) < 0)
        {
            log_event("Read failed");
            closelog();
            return 1;
        }

        handle_command(buffer);
        close(c);
    }

    return 0;
}

