#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <pigpiod_if.h>

#define BH1750_ADDR 0x23
#define BH1750_CMD 0x20
#define LUX_THRESHOLD 150
#define SAMPLE_INTERVAL 2

static int i2c_handle;
static FILE *log_file;

void cleanup_and_exit(int signum) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(23, 0);
    gpioTerminate();
    exit(signum);
}

int main() {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen("/dev/i2c-1", BH1750_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device.\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    log_file = fopen("grow_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    gpioSetMode(23, PI_OUTPUT);
    gpioWrite(23, 1);  // Turn off relay initially

    while (1) {
        if (i2cWriteByte(i2c_handle, BH1750_CMD) != 0) {
            fprintf(stderr, "Failed to write to BH1750.\n");
            continue;
        }
        sleep(120 / 1000);  // Wait for conversion

        unsigned char buf[2];
        if (i2cReadDevice(i2c_handle, buf, sizeof(buf)) != sizeof(buf)) {
            fprintf(stderr, "Failed to read from BH1750.\n");
            continue;
        }

        int raw = (buf[0] << 8) | buf[1];
        double lux = raw / 1.2;

        time_t now = time(NULL);
        struct tm *local_time = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", local_time);

        fprintf(log_file, "%s, %f\n", timestamp, lux);
        fflush(log_file);

        if (lux < LUX_THRESHOLD) {
            gpioWrite(23, 1);  // Turn on relay
        } else {
            gpioWrite(23, 0);  // Turn off relay
        }

        sleep(SAMPLE_INTERVAL);
    }

    cleanup_and_exit(EXIT_SUCCESS);
}

