#define LOCK_GPIO 25
#define THRESHOLD 1000
#define SCALE 1.0
#define DURATION 200
#define MAX_RETRIES 3
#define READ_TIMEOUT_US 1000000

struct gpiod_line *dout_line, *sck_line, *lock_line;
struct gpiod_chip *chip;
int threshold = THRESHOLD, scale = SCALE, duration = DURATION, retries = 0;

void sig_handler(int signo) {
    gpiod_line_set_value(lock_line, 0);
    gpiod_line_release(dout_line);
    gpiod_line_release(sck_line);
    gpiod_line_release(lock_line);
    gpiod_chip_close(chip);
    closelog();
