int main(int argc, char *argv[]) {
    openlog("load_cell_lock", LOG_PERROR, LOG_USER);
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %m");
        exit(EXIT_FAILURE);
    }

    dout_line = gpiod_chip_get_line(chip, DOUT_GPIO);
    if (!dout_line) {
        syslog(LOG_ERR, "Failed to get DOUT line: %m");
        exit(EXIT_FAILURE);
    }

    sck_line = gpiod_chip_get_line(chip, SCK_GPIO);
    if (!sck_line) {
        syslog(LOG_ERR, "Failed to get SCK line: %m");
        exit(EXIT_FAILURE);
    }

    lock_line = gpiod_chip_get_line(chip, LOCK_GPIO);
    if (!lock_line) {
        syslog(LOG_ERR, "Failed to get LOCK line: %m");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(dout_line, "DOUT")) {
        syslog(LOG_ERR, "Failed to request DOUT line: %m");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(sck_line, "SCK", 0)) {
        syslog(LOG_ERR, "Failed to request SCK line: %m");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(lock_line, "LOCK", 0)) {
        syslog(LOG_ERR, "Failed to request LOCK line: %m");
        exit(EXIT_FAILURE);
    }

    for (;;) {
        int i, sum = 0;
        for (i = 0; i < 5; i++) {
            int value;
            if (gpiod_line_wait_for_rising_edge(dout_line, READ_TIMEOUT_US)) {
                if (++retries > MAX_RETRIES) {
                    syslog(LOG_ERR, "Failed to read load cell after %d retries: %m", retries);
                    exit(EXIT_FAILURE);
                }
                continue;
            }
            retries = 0;
            for (value = 0; value < 24; value++) {
                gpiod_line_set_value(sck_line, 1);
                usleep(100);
                value = (value << 1) | gpiod_line_get_value(dout_line);
                gpiod_line_set_value(sck_line, 0);
                usleep(100);
            }
            gpiod_line_set_value(sck_line, 1);
            usleep(100);
            gpiod_line_set_value(sck_line, 0);
            sum += value - (value & 0x800000 ? 0x1000000 : 0);
        }

        int weight = (sum / 5 - 1000) / scale;
        if (weight > threshold) {
            gpiod_line_set_value(lock_line, 1);
            usleep(duration * 1000);
            gpiod_line_set_value(lock_line, 0);
        }
        usleep(500 * 1000);
    }

    return 0;
}

