#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <mosquitto.h>
#include <pigpio.h>

#define GPIO_RELAY 17
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_KEEPALIVE 60

struct mosquitto *mosq = NULL;

void sig_handler(int signo) {
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    gpioWrite(GPIO_RELAY, 0);
    gpioTerminate();
    closelog();
    exit(signo);
}

void connect_callback(struct mosquitto *mosq, void *obj, int rc) {
    if (rc) {
        syslog(LOG_ERR, "Failed to connect: %s", mosquitto_connack_string(rc));
    } else {
        syslog(LOG_INFO, "Connected to MQTT broker");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0, NULL);
    }
}

void subscribe_callback(struct mosquitto *mosq, void *obj, int mid, int qos_level, const char *topic, int payload_len, const void *payload, void *userdata) {
    syslog(LOG_INFO, "Received message on topic %s: %s", topic, (const char *)payload);
    if (strcmp(payload, "ON") == 0) {
        gpioWrite(GPIO_RELAY, 1);
    } else if (strcmp(payload, "OFF") == 0) {
        gpioWrite(GPIO_RELAY, 0);
    } else {
        syslog(LOG_ERR, "Invalid payload: %s", (const char *)payload);
    }
}

void disconnect_callback(struct mosquitto *mosq, void *obj, int rc) {
    syslog(LOG_ERR, "Disconnected: %s", mosquitto_connack_string(rc));
}

void error_callback(struct mosquitto *mosq, void *obj, int rc) {
    syslog(LOG_ERR, "Error: %s", mosquitto_connack_string(rc));
}

int main() {
    openlog("mqtt_relay", LOG_CONS | LOG_NDELAY | LOG_PID, LOG_USER);
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }
    gpioSetMode(GPIO_RELAY, OUTPUT);
    gpioWrite(GPIO_RELAY, 0);

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create MQTT client");
        exit(EXIT_FAILURE);
    }
    mosquitto_connect_callback_set(mosq, connect_callback);
    mosquitto_subscribe_callback_set(mosq, subscribe_callback);
    mosquitto_disconnect_callback_set(mosq, disconnect_callback);
    mosquitto_error_callback_set(mosq, error_callback);

    while (true) {
        if (mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, MQTT_KEEPALIVE) == MOSQ_ERR_SUCCESS) {
            mosquitto_loop_forever(mosq, -1, 1);
        } else {
            syslog(LOG_ERR, "Failed to connect to MQTT broker");
            sleep(5);
        }
    }

    return 0;
}

