#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <pigpiod_if.h>

#define BH1750_ADDR 0x23
#define BH1750_CMD_HR2 0x21
#define BH1750_DATA_LEN 2
#define LUX_DUSK 50
#define LUX_DAWN 200

volatile sig_atomic_t stop = 0;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        stop = 1;
    }
}

void log_message(const char *message, int lux, int relay) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char buffer[80];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *log_file = fopen("chicken_coop_log.txt", "a");
    if (log_file == NULL) {
        printf("Error opening log file\n");
        exit(EXIT_FAILURE);
    }

    fprintf(log_file, "%s: Lux = %d, Relay = %s\n", buffer, lux, relay ? "ON" : "OFF");
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        printf("Error initializing pigpio\n");
        exit(EXIT_FAILURE);
    }

    int relay_gpio = 17;
    gpioSetMode(relay_gpio, PI_OUTPUT);
    gpioWrite(relay_gpio, PI_LOW);

    int i2c_handle = gpioI2CSetSlave(BH1750_ADDR);
    if (i2c_handle < 0) {
        printf("Error setting up I2C slave\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (!stop) {
        gpioI2CWriteByte(i2c_handle, BH1750_CMD_HR2);
        usleep(180000);

        unsigned char data[BH1750_DATA_LEN];
        if (gpioI2CReadBytes(i2c_handle, data, BH1750_DATA_LEN) != BH1750_DATA_LEN) {
            printf("Error reading from sensor\n");
            log_message("Sensor error", 0, gpioRead(relay_gpio));
            gpioWrite(relay_gpio, PI_LOW);
            continue;
        }

        int lux = ((data[0] << 8) | data[1]) / 12;
        log_message("Sensor reading", lux, gpioRead(relay_gpio));

        if (lux < LUX_DUSK && gpioRead(relay_gpio) == PI_HIGH) {
            gpioWrite(relay_gpio, PI_LOW);
        } else if (lux > LUX_DAWN && gpioRead(relay_gpio) == PI_LOW) {
            gpioWrite(relay_gpio, PI_HIGH);
        }

        usleep(5000000);
    }

    gpioWrite(relay_gpio, PI_LOW);
    gpioI2CClose(i2c_handle);
    gpioTerminate();

    return 0;
}

