#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

volatile sig_atomic_t run = 1;

void sigint_handler(int signum) {
    run = 0;
}

int main() {
    int pi;
    int sensor = 4;
    int relay = 17;
    int state = 0;

    pi = gpioInitialise();
    if (pi < 0) {
        fprintf(stderr, "gpioInitialise() failed: %s\n", pigpio_error(pi));
        return EXIT_FAILURE;
    }

    if (gpioSetMode(sensor, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode() failed: %s\n", pigpio_error(pi));
        return EXIT_FAILURE;
    }

    if (gpioSetMode(relay, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode() failed: %s\n", pigpio_error(pi));
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (run) {
        if (gpioRead(sensor) == 1) {
            struct timespec sleep_time = { .tv_sec = 0, .tv_nsec = 50000000 };
            nanosleep(&sleep_time, NULL);

            if (gpioRead(sensor) == 1) {
                state = !state;
                if (gpioWrite(relay, state) < 0) {
                    fprintf(stderr, "gpioWrite() failed: %s\n", pigpio_error(pi));
                    return EXIT_FAILURE;
                }

                time_t now = time(NULL);
                char *time_str = ctime(&now);
                time_str[strlen(time_str) - 1] = '\0'; // remove trailing newline

                printf("[%s] Relay %s\n", time_str, state ? "ON" : "OFF");

                while (gpioRead(sensor) == 1);
            }
        }

        struct timespec sleep_time = { .tv_sec = 0, .tv_nsec = 10000000 };
        nanosleep(&sleep_time, NULL);
    }

    if (gpioWrite(relay, 0) < 0) {
        fprintf(stderr, "gpioWrite() failed: %s\n", pigpio_error(pi));
        return EXIT_FAILURE;
    }

    gpioTerminate();

    printf("Exiting...\n");

    return EXIT_SUCCESS;
}

