#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <pthread.h>
#include <time.h>

#define GPIO_SENSOR 17
#define GPIO_VALVE 27
#define PULSES_PER_LITER 450.0
#define LPM_THRESHOLD 5.0
#define LPM_HYSTERESIS 0.5
#define DEBOUNCE_TIMEOUT 1000

pthread_mutex_t mutex;
FILE *log_file;

void log_message(const char *message) {
    time_t now = time(NULL);
    char buffer[26];
    strftime(buffer, 26, "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(log_file, "%s - %s\n", buffer, message);
    fflush(log_file);
}

void sig_handler(int signo) {
    log_message(signo == SIGINT ? "SIGINT received, reopening solenoid" : "SIGTERM received, reopening solenoid");
    gpioWrite(GPIO_VALVE, 1);
    fclose(log_file);
    pthread_mutex_destroy(&mutex);
    gpioTerminate();
    exit(0);
}

void isr_handler(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&mutex);
    gpioPulseCount(GPIO_SENSOR);
    pthread_mutex_unlock(&mutex);
}

int main() {
    int ret;
    unsigned long pulse_count = 0;
    double lpm;
    char log_path[] = "/home/pi/water_flow.log";

    log_file = fopen(log_path, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", log_path);
        return 1;
    }

    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "gpioInitialise failed with code %d\n", ret);
        return 1;
    }

    ret = gpioSetMode(GPIO_SENSOR, PI_INPUT);
    if (ret < 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d with code %d\n", GPIO_SENSOR, ret);
        return 1;
    }

    ret = gpioSetMode(GPIO_VALVE, PI_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d with code %d\n", GPIO_VALVE, ret);
        return 1;
    }

    ret = gpioSetISRFuncEx(GPIO_SENSOR, PI_EITHER_EDGE, DEBOUNCE_TIMEOUT, isr_handler);
    if (ret < 0) {
        fprintf(stderr, "gpioSetISRFuncEx failed for GPIO %d with code %d\n", GPIO_SENSOR, ret);
        return 1;
    }

    ret = pthread_mutex_init(&mutex, NULL);
    if (ret != 0) {
        fprintf(stderr, "pthread_mutex_init failed with code %d\n", ret);
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        pthread_mutex_lock(&mutex);
        pulse_count = gpioPulseCount(GPIO_SENSOR);
        gpioPulseCount(GPIO_SENSOR);
        pthread_mutex_unlock(&mutex);

        lpm = (pulse_count / PULSES_PER_LITER) * 60.0;
        log_message(lpm);

        if (lpm > LPM_THRESHOLD) {
            gpioWrite(GPIO_VALVE, 0);
            log_message("Valve closed");
        } else if (lpm < (LPM_THRESHOLD - LPM_HYSTERESIS)) {
            gpioWrite(GPIO_VALVE, 1);
            log_message("Valve opened");
        }

        sleep(1);
    }

    return 0;
}

