#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_SENSOR 4
#define GPIO_RELAY 17

volatile int running = 1;
int debounce_time = 50;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        running = 0;
    }
}

void log_relay_state(int state) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestr[20];
    strftime(timestr, sizeof(timestr), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s Relay: %s\n", timestr, state ? "ON" : "OFF");
}

int main(int argc, char *argv[]) {
    if (argc > 2 && strcmp(argv[1], "-d") == 0) {
        debounce_time = atoi(argv[2]);
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_SENSOR, PI_INPUT) < 0 || gpioSetMode(GPIO_RELAY, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    int sensor_state = gpioRead(GPIO_SENSOR);
    int relay_state = 0;
    gpioWrite(GPIO_RELAY, relay_state);

    while (running) {
        int new_sensor_state = gpioRead(GPIO_SENSOR);
        if (new_sensor_state != sensor_state) {
            sensor_state = new_sensor_state;
            if (sensor_state == 1) {
                // Debounce
                sleep_ms(debounce_time);
                int stable_level = gpioRead(GPIO_SENSOR);
                if (stable_level == 1) {
                    relay_state = !relay_state;
                    gpioWrite(GPIO_RELAY, relay_state);
                    log_relay_state(relay_state);
                }
            }
        }
        sleep_ms(10);
    }

    gpioWrite(GPIO_RELAY, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

