#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <termios.h>
#include <pigpio.h>

#define GPIO_SERVO 18
#define PULSE_MIN_US 500
#define PULSE_MAX_US 2500
#define PULSE_HOME_US 1500
#define PULSE_RANGE_US (PULSE_MAX_US - PULSE_MIN_US)
#define ANGLE_MIN 0
#define ANGLE_MAX 180
#define ANGLE_HOME 90
#define ANGLE_INCR 10

static struct termios old_term, new_term;
static int running = 1;

void sigint_handler(int signum) {
    running = 0;
}

void restore_termios() {
    if (tcsetattr(0, TCSANOW, &old_term) == -1) {
        perror("tcsetattr");
        exit(EXIT_FAILURE);
    }
}

void set_raw_termios() {
    if (tcgetattr(0, &old_term) == -1) {
        perror("tcgetattr");
        exit(EXIT_FAILURE);
    }

    new_term = old_term;
    new_term.c_lflag &= ~(ICANON | ECHO);
    new_term.c_cc[VMIN] = 1;
    new_term.c_cc[VTIME] = 0;

    if (tcsetattr(0, TCSANOW, &new_term) == -1) {
        perror("tcsetattr");
        exit(EXIT_FAILURE);
    }
}

int main() {
    int servo_angle = ANGLE_HOME;
    int pulse_width;
    int pi;

    signal(SIGINT, sigint_handler);

    pi = gpioInitialise();
    if (pi < 0) {
        fprintf(stderr, "gpioInitialise failed: %d\n", pi);
        return EXIT_FAILURE;
    }

    set_raw_termios();

    gpioSetPWMfrequency(GPIO_SERVO, 50);
    gpioServo(GPIO_SERVO, PULSE_HOME_US);

    while (running) {
        char c = getchar();

        switch (c) {
        case '+':
            servo_angle = fmin(servo_angle + ANGLE_INCR, ANGLE_MAX);
            break;
        case '-':
            servo_angle = fmax(servo_angle - ANGLE_INCR, ANGLE_MIN);
            break;
        case 'q':
            running = 0;
            break;
        default:
            continue;
        }

        pulse_width = PULSE_MIN_US + (servo_angle * PULSE_RANGE_US / ANGLE_MAX);
        gpioServo(GPIO_SERVO, pulse_width);

        printf("Angle: %d\n", servo_angle);
    }

    gpioServo(GPIO_SERVO, -1);
    gpioTerminate();
    restore_termios();

    return EXIT_SUCCESS;
}

