#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_NUM 17
#define DEBOUNCE_US 2000
#define SAMPLE_INTERVAL_SEC 5

struct gpiod_line *line;
struct gpiod_chip *chip;
FILE *log_file;
int pulse_count;

void sig_handler(int signum) {
    printf("Signal caught, shutting down...\n");
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(0);
}

int main() {
    struct timespec sample_time;
    struct timespec now;
    struct gpiod_line_event event;
    struct sigaction sig_action;
    char log_line[100];
    double rpm;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_NUM);
    if (!line) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_NUM, strerror(errno));
        return 1;
    }

    ret = gpiod_line_request_input_flags(line, "motor_sensor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %d: %s\n", GPIO_NUM, strerror(errno));
        return 1;
    }

    log_file = fopen("motor_rpm.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    sig_action.sa_handler = sig_handler;
    sigemptyset(&sig_action.sa_mask);
    sig_action.sa_flags = 0;
    sigaction(SIGINT, &sig_action, NULL);
    sigaction(SIGTERM, &sig_action, NULL);

    clock_gettime(CLOCK_MONOTONIC, &sample_time);
    sample_time.tv_sec += SAMPLE_INTERVAL_SEC;

    while (1) {
        ret = gpiod_line_event_wait(line, &sample_time);
        if (ret < 0) {
            if (errno == ETIMEDOUT) {
                rpm = (double)pulse_count / SAMPLE_INTERVAL_SEC * 60.0;
                pulse_count = 0;
                clock_gettime(CLOCK_MONOTONIC, &now);
                sprintf(log_line, "%ld.%09ld,%.2f\n", now.tv_sec, now.tv_nsec, rpm);
                fputs(log_line, log_file);
                fflush(log_file);
                printf("Current RPM: %.2f\n", rpm);
                sample_time.tv_sec += SAMPLE_INTERVAL_SEC;
            } else {
                fprintf(stderr, "Failed to wait for event: %s\n", strerror(errno));
                return 1;
            }
        } else {
            ret = gpiod_line_event_read(line, &event);
            if (ret < 0) {
                fprintf(stderr, "Failed to read event: %s\n", strerror(errno));
                return 1;
            }
            pulse_count++;
            gpiod_line_event_set_edge_type(&event, GPIOD_LINE_EVENT_RISING_EDGE);
            gpiod_line_event_set_debounce(&event, DEBOUNCE_US);
            ret = gpiod_line_event_write(line, &event);
            if (ret < 0) {
                fprintf(stderr, "Failed to write event: %s\n", strerror(errno));
                return 1;
            }
        }
    }

    return 0;
}

