#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <spi.h>

#define LOCK_PIN1 17
#define LOCK_PIN2 27
#define BUTTON_PIN 22
#define SPI_CHANNEL 0
#define SPI_SPEED 100000

FILE *log_file;
int spi_handle;

void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
    fprintf(log_file, "%s %s\n", timestamp, message);
    fflush(log_file);
}

void sig_handler(int signo) {
    gpioWrite(LOCK_PIN1, 1);
    gpioWrite(LOCK_PIN2, 1);
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();
    exit(signo);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("/var/log/door_access.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(LOCK_PIN1, PI_OUTPUT);
    gpioSetMode(LOCK_PIN2, PI_OUTPUT);
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);
    gpioSetDebounce(BUTTON_PIN, 50000);

    gpioWrite(LOCK_PIN1, 1);
    gpioWrite(LOCK_PIN2, 1);

    unsigned char tag[10] = {0};
    unsigned char read_tag[10] = {0};

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        memset(read_tag, 0, sizeof(read_tag));
        int bytes = spiXfer(spi_handle, read_tag, tag, sizeof(tag));
        if (bytes != sizeof(tag)) {
            log_message("Failed to read tag");
            continue;
        }

        if (memcmp(read_tag, tag, sizeof(tag)) != 0) {
            log_message("Invalid tag");
            continue;
        }

        if (gpioRead(BUTTON_PIN) == 0) {
            gpioWrite(LOCK_PIN1, 0);
            gpioWrite(LOCK_PIN2, 0);
            gpioDelay(5000000);
            gpioWrite(LOCK_PIN1, 1);
            gpioWrite(LOCK_PIN2, 1);
            log_message("Access granted");
        } else {
            log_message("Button press without a valid tag");
        }
    }

    return EXIT_SUCCESS;
}

