#define PWM_FREQ 100
#define TARGET_RPM 60
#define KP 1.0
#define KI 0.1
#define KD 0.01
#define SAMPLE_TIME 0.1

struct gpio_line {
    struct gpiod_line *line;
    int gpio;
};

struct motor {
    struct gpio_line en, in1, in2;
    int encoder_a, encoder_b;
    double error, integral, derivative, output;
};

struct gpio_chip {
    struct gpiod_chip *chip;
    char *name;
};

struct gpio_chip chips[2];
struct motor motors[2];
pthread_mutex_t mutexes[2];

void *encoder_thread(void *arg) {
    struct motor *motor = arg;
    struct gpiod_line *line = motor->line;
    struct gpiod_edge_event event;
    int dir_gpio = motor->encoder_b;
    int count = 0;

    while (1) {
        if (gpiod_line_event_wait(line, NULL) < 0) {
            // handle error
        }

        if (gpiod_line_event_read(line, &event) < 0) {
            // handle error
        }

        if (gpiod_line_get_value(line) > 0) {
            count += (gpioRead(dir_gpio) > 0) ? 1 : -1;
        }

        pthread_mutex_lock(&mutexes[motor - motors]);
        motor->encoder_count = count;
        pthread_mutex_unlock(&mutexes[motor - motors]);
    }

    return NULL;
}

void control_loop() {
    while (1) {
        for (int i = 0; i < 2; i++) {
            struct motor *motor = &motors[i];

            pthread_mutex_lock(&mutexes[i]);
            int encoder_count = motor->encoder_count;
            pthread_mutex_unlock(&mutexes[i]);

            double current_rpm = encoder_count / SAMPLE_TIME;
            motor->error = TARGET_RPM - current_rpm;
            motor->integral += motor->error * SAMPLE_TIME;
            motor->derivative = (motor->error - motor->last_error) / SAMPLE_TIME;
            motor->output = KP * motor->error + KI * motor->integral + KD * motor->derivative;
            motor->last_error = motor->error;

            int pwm_duty = motor->output / 100.0;
            gpiod_line_set_values(motor->en.line, pwm_duty);

            // log to file
            FILE *file = fopen("motor_log.csv", "a");
            if (file) {
                fprintf(file, "%f,%f,%f,%f\n", current_rpm, motor->error, motor->integral, motor->output);
                fclose(file);
            }
        }

        sleep(SAMPLE_TIME);
    }
}

void init_motor(struct motor *motor, int en, int in1, int in2, int encoder_a, int encoder_b) {
    motor->en.gpio = en;
    motor->in1.gpio = in1;
    motor->in2.gpio = in2;
    motor->encoder_a = encoder_a;
    motor->encoder_b = encoder_b;

    motor->en.line = gpiod_chip_get_line(chips[0].chip, en);
    motor->in1.line = gpiod_chip_get_line(chips[0].chip, in1);
    motor->in2.line = gpiod_chip_get_line(chips[0].chip, in2);
    motor->line = gpiod_chip_get_line(chips[1].chip, encoder_a);

    gpiod_line_request_both_edges_events(motor->line, "encoder");
    gpiod_line_set_value(motor->en.line, 1);
}

