    for (int i = 0; i < 2; i++) {
        gpiod_line_release(motors[i].en.line);
        gpiod_line_release(motors[i].in1.line);
        gpiod_line_release(motors[i].in2.line);
        gpiod_line_release(motors[i].line);
        gpiod_chip_close(chips[i].chip);
    }

    fclose(file);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    init_gpiod();

    init_motor(&motors[0], 23, 24, 25, 5, 6);
    init_motor(&motors[1], 12, 16, 20, 26, 19);

    pthread_t threads[2];
    for (int i = 0; i < 2; i++) {
        pthread_create(&threads[i], NULL, encoder_thread, &motors[i]);
    }

    control_loop();

    return 0;
}

