#define MPR121_REG_MISCFILT 0x46
#define MPR121_REG_TOUCHTHRESH 0x48
#define MPR121_REG_RELEASETHRESH 0x4A
#define MPR121_REG_TOUCHSTATUS 0x00
#define MPR121_REG_RELEASESTATUS 0x01

FILE *log_file;
int i2c_handle;

void cleanup_and_exit(int sig) {
    if (gpioTerm() < 0) {
        fprintf(stderr, "Error in gpioTerm: %s\n", strerror(errno));
    }
    if (i2c_handle >= 0) {
        if (i2cClose(i2c_handle) < 0) {
            fprintf(stderr, "Error in i2cClose: %s\n", strerror(errno));
        }
    }
    if (log_file) {
