        fprintf(stderr, "Error in i2cOpen: %s\n", strerror(errno));
        cleanup_and_exit(1);
    }

    if (gpioSetMode(MPR121_GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error in gpioSetMode: %s\n", strerror(errno));
        cleanup_and_exit(1);
    }

    if (i2cWriteByteData(i2c_handle, MPR121_REG_SOFTRESET, 0xAA) < 0) {
        fprintf(stderr, "Error in i2cWriteByteData: %s\n", strerror(errno));
        cleanup_and_exit(1);
    }

    if (i2cWriteByteData(i2c_handle, MPR121_REG_MISCFILT, 0x04) < 0) {
        fprintf(stderr, "Error in i2cWriteByteData: %s\n", strerror(errno));
        cleanup_and_exit(1);
    }

    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, MPR121_REG_TOUCHTHRESH + 2*i, 0x00) < 0) {
            fprintf(stderr, "Error in i2cWriteByteData: %s\n", strerror(errno));
            cleanup_and_exit(1);
        }
        if (i2cWriteByteData(i2c_handle, MPR121_REG_RELEASETHRESH + 2*i, 0x05) < 0) {
            fprintf(stderr, "Error in i2cWriteByteData: %s\n", strerror(errno));
            cleanup_and_exit(1);
        }
    }

    if (i2cWriteByteData(i2c_handle, MPR121_REG_MISCFILT, 0x04) < 0) {
        fprintf(stderr, "Error in i2cWriteByteData: %s\n", strerror(errno));
        cleanup_and_exit(1);
    }

    if ((log_file = fopen("relay_log.txt", "w")) == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup_and_exit(1);
    }

    signal(SIGINT, cleanup_and_exit);

    int last_touch_status = 0;
    while (1) {
        int touch_status;
        if (i2cReadByteData(i2c_handle, MPR121_REG_TOUCHSTATUS, &touch_status) < 0) {
            fprintf(stderr, "Error in i2cReadByteData: %s\n", strerror(errno));
            cleanup_and_exit(1);
        }

        if (touch_status != last_touch_status) {
            last_touch_status = touch_status;
            if (gpioWrite(MPR121_GPIO_PIN, touch_status ? PI_HIGH : PI_LOW) < 0) {
                fprintf(stderr, "Error in gpioWrite: %s\n", strerror(errno));
                cleanup_and_exit(1);
            }

            time_t now = time(NULL);
            struct tm *local_time = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", local_time);

            fprintf(log_file, "%s: Relay %s\n", timestamp, touch_status ? "ON" : "OFF");
            fflush(log_file);
        }

        sleep(50);
    }

    cleanup_and_exit(0);
}

