#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_17 17
#define GPIO_LINE_18 18

struct gpiod_line *line_17, *line_18;
struct gpiod_chip *chip;
FILE *log_file;

void log_event(int valve_number, int duration) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
    fprintf(log_file, "%s: Valve %d opened for %d ms\n", timestamp, valve_number, duration);
}

void sig_handler(int signo) {
    if (gpiod_line_release(line_17) || gpiod_line_release(line_18)) {
        fprintf(stderr, "Error releasing GPIO lines\n");
    }
    if (fclose(log_file)) {
        fprintf(stderr, "Error closing log file\n");
    }
    exit(signo);
}

int main() {
    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }

    line_17 = gpiod_chip_get_line(chip, GPIO_LINE_17);
    if (!line_17) {
        fprintf(stderr, "Error getting GPIO line 17\n");
        return 1;
    }

    line_18 = gpiod_chip_get_line(chip, GPIO_LINE_18);
    if (!line_18) {
        fprintf(stderr, "Error getting GPIO line 18\n");
        return 1;
    }

    if (gpiod_line_request_output(line_17, "Valve 1", 0) || gpiod_line_request_output(line_18, "Valve 2", 0)) {
        fprintf(stderr, "Error requesting GPIO line as output\n");
        return 1;
    }

    log_file = fopen("valve_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        gpiod_line_set_value(line_17, 1);
        log_event(1, 500);
        usleep(500 * 1000);
        gpiod_line_set_value(line_17, 0);
        sleep(5);

        gpiod_line_set_value(line_18, 1);
        log_event(2, 1000);
        usleep(1000 * 1000);
        gpiod_line_set_value(line_18, 0);
        sleep(10);
    }

    return 0;
}

