#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define RELAY_PIN 17

static int i2c_handle = -1;
static int pi_handle = -1;

void cleanup(int signum) {
    if (i2c_handle >= 0) {
        piI2C_close(i2c_handle);
    }
    if (pi_handle >= 0) {
        gpioTerminate();
    }
    printf("Shutdown gracefully.\n");
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    pi_handle = gpioInitialise();
    if (pi_handle < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %d\n", pi_handle);
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0);

    i2c_handle = piI2C_open(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return EXIT_FAILURE;
    }

    if (piI2C_writeByteData(i2c_handle, 0x20, 0x00) < 0) {
        fprintf(stderr, "Failed to initialize MPR121: %d\n", piI2C_writeByteData(i2c_handle, 0x20, 0x00));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 12; i++) {
        if (piI2C_writeByteData(i2c_handle, 0x41 + i, 0x10) < 0) {
            fprintf(stderr, "Failed to set touch threshold: %d\n", piI2C_writeByteData(i2c_handle, 0x41 + i, 0x10));
            return EXIT_FAILURE;
        }
        if (piI2C_writeByteData(i2c_handle, 0x51 + i, 0x0A) < 0) {
            fprintf(stderr, "Failed to set release threshold: %d\n", piI2C_writeByteData(i2c_handle, 0x51 + i, 0x0A));
            return EXIT_FAILURE;
        }
    }

    if (piI2C_writeByteData(i2c_handle, 0x21, 0x20) < 0) {
        fprintf(stderr, "Failed to set filter/charge time: %d\n", piI2C_writeByteData(i2c_handle, 0x21, 0x20));
        return EXIT_FAILURE;
    }

    if (piI2C_writeByteData(i2c_handle, 0x22, 0x01) < 0) {
        fprintf(stderr, "Failed to set electrode current: %d\n", piI2C_writeByteData(i2c_handle, 0x22, 0x01));
        return EXIT_FAILURE;
    }

    if (piI2C_writeByteData(i2c_handle, 0x20, 0x20) < 0) {
        fprintf(stderr, "Failed to enter run mode: %d\n", piI2C_writeByteData(i2c_handle, 0x20, 0x20));
        return EXIT_FAILURE;
    }

    usleep(100000);

    while (1) {
        int touch_status = piI2C_readWordData(i2c_handle, 0x00);
        if (touch_status < 0) {
            fprintf(stderr, "Failed to read touch status: %d\n", touch_status);
            return EXIT_FAILURE;
        }

        if (touch_status > 0) {
            int relay_status = gpioRead(RELAY_PIN);
            gpioWrite(RELAY_PIN, !relay_status);
            printf("Touch detected, relay toggled.\n");
        }

        usleep(100000);
    }

    return EXIT_SUCCESS;
}

