#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_MOTION_SENSOR 17
#define GPIO_RELAY 18
#define LOG_FILE "door_events.log"

FILE *log_file;
int pi;
int rate_limit_remaining = 0;

void log_event(const char *event) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(log_file, "%ld.%09ld: %s\n", ts.tv_sec, ts.tv_nsec, event);
    fflush(log_file);
}

void handle_motion_detected() {
    if (rate_limit_remaining > 0) {
        log_event("Rate-limited event: motion detected while in cooldown");
        return;
    }

    log_event("Motion detected, unlocking door");
    gpioWrite(GPIO_RELAY, 1);
    rate_limit_remaining = 20; // 2 seconds at 50ms intervals
}

void handle_exit(int signum) {
    gpioWrite(GPIO_RELAY, 0);
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main() {
    pi = gpioInitialise();
    if (pi < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error(pi));
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    gpioSetMode(GPIO_MOTION_SENSOR, PI_INPUT);
    gpioSetPullUpDown(GPIO_MOTION_SENSOR, PI_PUD_DOWN);
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioWrite(GPIO_RELAY, 0);

    signal(SIGINT, handle_exit);

    while (1) {
        if (gpioRead(GPIO_MOTION_SENSOR) == 1) {
            handle_motion_detected();
        }

        if (rate_limit_remaining > 0) {
            rate_limit_remaining--;
