#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define DATA_PIN 4
#define CLOCK_PIN 17
#define LOCK_PIN 27
#define TIMEOUT 500000
#define THRESHOLD 10.0

static int pi;
static FILE *log_file;
static double scale_factor = 1.0;
static double offset = 0.0;

void cleanup(int signum) {
    if (log_file) fclose(log_file);
    if (pi >= 0) gpioTerminate();
    exit(0);
}

void read_calibration() {
    FILE *file = fopen("calibration.txt", "r");
    if (!file) return;
    if (fscanf(file, "%lf %lf", &scale_factor, &offset) != 2) {
        scale_factor = 1.0;
        offset = 0.0;
    }
    fclose(file);
}

void write_calibration() {
    FILE *file = fopen("calibration.txt", "w");
    if (!file) return;
    fprintf(file, "%.6lf %.6lf\n", scale_factor, offset);
    fclose(file);
}

void log_weight(double weight) {
    time_t now = time(NULL);
    struct tm *time = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d %.2lf\n",
            time->tm_year + 1900, time->tm_mon + 1, time->tm_mday,
            time->tm_hour, time->tm_min, time->tm_sec, weight);
}

int main() {
    signal(SIGINT, cleanup);

    pi = gpioInitialise();
    if (pi < 0) {
        printf("Error initializing pigpio: %d\n", pi);
        return 1;
    }

    read_calibration();

    if (gpioSetMode(DATA_PIN, PI_INPUT) < 0 ||
        gpioSetMode(CLOCK_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(LOCK_PIN, PI_OUTPUT) < 0) {
        printf("Error setting GPIO modes\n");
        cleanup(0);
        return 1;
    }

    log_file = fopen("weight_log.txt", "w");
    if (!log_file) {
        printf("Error opening log file\n");
        cleanup(0);
        return 1;
    }

    long long readings[100];
    for (int i = 0; i < 100; i++) {
        long long reading = hx711Read(DATA_PIN, CLOCK_PIN, TIMEOUT);
        if (reading < 0) {
            printf("HX711 read error: %lld\n", reading);
            cleanup(0);
            return 1;
        }
        readings[i] = reading;
    }

    for (int i = 0; i < 100; i++) offset += readings[i];
    offset /= 100.0;

    write_calibration();

    while (1) {
        long long reading = hx711Read(DATA_PIN, CLOCK_PIN, TIMEOUT);
        if (reading < 0) {
            printf("HX711 read error: %lld\n", reading);
            continue;
        }

        double weight = (reading - offset) * scale_factor;
        log_weight(weight);

        if (weight > THRESHOLD) gpioWrite(LOCK_PIN, 1);
        else gpioWrite(LOCK_PIN, 0);
    }

    return 0;
}

