#define GPIO_IN2 18
#define GPIO_PWM 27
#define PWM_FREQ 1000
#define PWM_DUTY_CYCLE 150
#define PWM_DUTY_CYCLE_OFF 0
#define CHECK_INTERVAL 60
#define RAIN_DETECTED_THRESHOLD 3
#define DEBOUNCE_INTERVAL 50
#define DEBOUNCE_COUNT 5
#define WINDOW_CLOSE_DURATION 5

volatile sig_atomic_t stop = 0;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        stop = 1;
    }
}

void log_event(const char *event) {
    time_t now = time(NULL);
    char buffer[26];
    strftime(buffer, 26, "%Y-%m-%d %H:%M:%S", localtime(&now));
    syslog(LOG_INFO, "%s: %s", buffer, event);
}

void close_window() {
    if (gpioSetMode(GPIO_IN1, PI_OUTPUT) != 0 ||
        gpioSetMode(GPIO_IN2, PI_OUTPUT) != 0 ||
        gpioSetMode(GPIO_PWM, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO mode for window control");
        exit(EXIT_FAILURE);
    }

    gpioWrite(GPIO_IN1, 1);
    gpioWrite(GPIO_IN2, 0);
    gpioPWM(GPIO_PWM, PWM_FREQ, PWM_DUTY_CYCLE);

    log_event("Window closing started");

    sleep(WINDOW_CLOSE_DURATION);

    gpioWrite(GPIO_IN1, 0);
    gpioWrite(GPIO_IN2, 0);
    gpioPWM(GPIO_PWM, PWM_FREQ, PWM_DUTY_CYCLE_OFF);

    log_event("Window closing finished");
}

int main() {
    openlog("window_control", LOG_PID, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (!stop) {
        int rain_detected_count = 0;

        for (int i = 0; i < DEBOUNCE_COUNT; i++) {
            int rain_sensor_value = gpioRead(GPIO_RAIN_SENSOR);

            if (rain_sensor_value < 0) {
                syslog(LOG_ERR, "Failed to read rain sensor");
                exit(EXIT_FAILURE);
            }

            if (rain_sensor_value == 0) {
                rain_detected_count++;
            }

            usleep(DEBOUNCE_INTERVAL * 1000);
        }

        if (rain_detected_count >= RAIN_DETECTED_THRESHOLD) {
            log_event("Rain detected");
            close_window();
        }

        sleep(CHECK_INTERVAL);
    }

    closelog();

    gpioTerminate();

    return 0;
}

