        if (data < 0) {
            printf("Error reading from HX711: %d\n", data);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        double weight = hx711_convert(data);
        if (weight < 0) {
            printf("Error converting HX711 data: %.2f\n", weight);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (weight <= WEIGHT_THRESHOLD) {
            gpioWrite(LOCK_PIN, PI_HIGH);
            log_event(weight);
            sleep(LOCK_DURATION);
            gpioWrite(LOCK_PIN, PI_LOW);
        }

        sleep(1000);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}
