#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define LOCK_PIN 27

double calibration_factor = 1.0;
FILE *log_file = NULL;

void hx711_read(void);
void calibrate(void);
void unlock_and_exit(int signum);

int main(void)
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, unlock_and_exit);

    calibrate();

    log_file = fopen("security.log", "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Failed to open security.log for writing.\n");
        unlock_and_exit(0);
    }

    hx711_read();

    return EXIT_SUCCESS;
}

void hx711_read(void)
{
    while (1)
    {
        int data = 0;
        int clock_delay = 1000;
        int data_delay = 1000;

        gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
        gpioSetMode(HX711_DATA_PIN, PI_INPUT);

        gpioWrite(HX711_CLOCK_PIN, 1);
        delay(clock_delay);

        for (int i = 0; i < 24; i++)
        {
            gpioWrite(HX711_CLOCK_PIN, 0);
            delay(clock_delay);

            data = (data << 1) | gpioRead(HX711_DATA_PIN);

            gpioWrite(HX711_CLOCK_PIN, 1);
            delay(clock_delay);
        }

        double weight = data / calibration_factor;

        if (weight > 5.0)
        {
            time_t now = time(NULL);
            struct tm *local_time = localtime(&now);

            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", local_time);

            fprintf(log_file, "%s: Weight exceeded 5.0 kg: %f\n", timestamp, weight);

            gpioWrite(LOCK_PIN, 1);
            delay(5000);
            gpioWrite(LOCK_PIN, 0);
        }
    }
}

void calibrate(void)
{
    FILE *calibration_file = fopen("calibration.txt", "r");
    if (calibration_file == NULL || fscanf(calibration_file, "%lf", &calibration_factor) != 1)
    {
        printf("Place a known weight on the scale and press enter.\n");
        getchar();

        hx711_read();

        printf("Enter the weight in kg: ");
        double known_weight;
        scanf("%lf", &known_weight);

        calibration_factor = known_weight;

        calibration_file = fopen("calibration.txt", "w");
        if (calibration_file == NULL || fprintf(calibration_file, "%f", calibration_factor) < 0)
        {
            fprintf(stderr, "Failed to write calibration factor to file.\n");
            unlock_and_exit(0);
        }
    }

    if (calibration_file != NULL)
        fclose(calibration_file);
}

void unlock_and_exit(int signum)
{
    gpioWrite(LOCK_PIN, 0);

    if (log_file != NULL)
        fclose(log_file);

    gpioTerminate();

    exit(signum);
}

