#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define CHIP_NAME "gpiochip0"
#define SENSOR_LINE 16
#define RELAY_LINE 20
#define LOG_FILE "relay_events.log"

struct gpiod_line *sensor_gpio;
struct gpiod_line *relay_gpio;
FILE *log_file;

void sig_handler(int signo) {
    if (sensor_gpio)
        gpiod_line_release(sensor_gpio);
    if (relay_gpio)
        gpiod_line_release(relay_gpio);
    if (log_file)
        fclose(log_file);
    exit(0);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[2];
    int ret, sensor_val, relay_val;
    struct timespec ts;
    char timestamp[30];

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    sensor_gpio = gpiod_chip_get_line(chip, SENSOR_LINE);
    if (!sensor_gpio) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    relay_gpio = gpiod_chip_get_line(chip, RELAY_LINE);
    if (!relay_gpio) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    ret = gpiod_line_request_bulk_inputs(lines, 1, sensor_gpio);
    if (ret) {
        perror("gpiod_line_request_bulk_inputs");
        return 1;
    }

    ret = gpiod_line_request_bulk_outputs(lines, 1, relay_gpio);
    if (ret) {
        perror("gpiod_line_request_bulk_outputs");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    while (1) {
        sensor_val = gpiod_line_get_value(sensor_gpio);
        if (sensor_val < 0) {
            perror("gpiod_line_get_value");
            return 1;
        }

        if (sensor_val == 0) {
            relay_val = gpiod_line_get_value(relay_gpio);
            if (relay_val < 0) {
                perror("gpiod_line_get_value");
                return 1;
            }

            relay_val = !relay_val;
            ret = gpiod_line_set_value(relay_gpio, relay_val);
            if (ret) {
                perror("gpiod_line_set_value");
                return 1;
            }

            clock_gettime(CLOCK_REALTIME, &ts);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&ts.tv_sec));
            fprintf(log_file, "%s: Relay state changed to %s\n", timestamp, relay_val ? "ON" : "OFF");
            fflush(log_file);
        }
    }

    return 0;
}

