#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_LINE 18
#define CONFIG_FILE "watering.conf"

struct gpiod_line *line;
struct gpiod_chip *chip;
int duration;
volatile sig_atomic_t stop;

void sig_handler(int signum) {
    stop = 1;
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(struct sigaction));
    action.sa_handler = sig_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line, "valve", 0)) {
        fprintf(stderr, "Failed to request GPIO line as output: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    FILE *file = fopen(CONFIG_FILE, "r");
    if (!file) {
        fprintf(stderr, "Failed to open config file: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    char line_buf[256];
    if (!fgets(line_buf, sizeof(line_buf), file)) {
        fprintf(stderr, "Failed to read config file\n");
        fclose(file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    fclose(file);

    if (sscanf(line_buf, "duration=%d", &duration) != 1 || duration < 1 || duration > 3600) {
        fprintf(stderr, "Invalid duration in config file\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("Valve off, duration %ds\n", duration);

    while (!stop) {
        gpiod_line_set_value(line, 1);
        printf("Valve on\n");

        for (int i = 0; i < duration && !stop; i++) {
            sleep(1);
        }

        gpiod_line_set_value(line, 0);
        printf("Valve off\n");

        for (int i = 0; i < duration && !stop; i++) {
            sleep(1);
        }
    }

    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

