        fprintf(stderr, "Failed to read config file\n");
        fclose(file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    fclose(file);

    if (sscanf(line_buf, "duration=%d", &duration) != 1 || duration < 1 || duration > 3600) {
        fprintf(stderr, "Invalid duration in config file\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("Valve off, duration %ds\n", duration);

    while (!stop) {
        gpiod_line_set_value(line, 1);
        printf("Valve on\n");

        for (int i = 0; i < duration && !stop; i++) {
            sleep(1);
        }

        gpiod_line_set_value(line, 0);
        printf("Valve off\n");

        for (int i = 0; i < duration && !stop; i++) {
            sleep(1);
        }
    }

    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}
