    if (gpioSetMode(GPIO_LEFT, PI_OUTPUT) < 0 ||
        gpioSetMode(GPIO_RIGHT, PI_OUTPUT) < 0) {
        printf("Could not set GPIO mode\n");
        return 1;
    }

    signal(SIGINT, stop_motors);

    while (1) {
        int sensor1 = gpioRead(GPIO_SENSOR1);
        int sensor2 = gpioRead(GPIO_SENSOR2);
        int sensor3 = gpioRead(GPIO_SENSOR3);

        if (sensor1 < 0 || sensor2 < 0 || sensor3 < 0) {
            printf("Could not read sensor\n");
            return 1;
        }

        int left_speed = BASE_SPEED;
        int right_speed = BASE_SPEED;

        if (sensor2 == 0) {
            if (sensor1 == 0) right_speed /= 2;
            if (sensor3 == 0) left_speed /= 2;
        } else {
            left_speed = 0;
            right_speed = 0;
        }

        piHiLo(GPIO_LEFT, left_speed);
        piHiLo(GPIO_RIGHT, right_speed);

        time_t now = time(0);
        struct tm *local = localtime(&now);
        char timestamp[20];
        strftime(timestamp, 20, "%Y-%m-%dT%H:%M:%S", local);

        fprintf(log_file, "%s %d %d %d %d %d\n", timestamp, sensor1, sensor2, sensor3, left_speed, right_speed);
    }

    return 0;
}

