#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <pigpiod_if.h>

#define BH1750_I2C_BUS 1
#define BH1750_I2C_ADDR 0x23
#define BH1750_CMD 0x10
#define LUX_THRESHOLD 150
#define GPIO_RELAY 23

int i2c_handle = -1;
int relay_state = 0;
FILE *log_file = NULL;

void log_message(const char *msg) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(log_file, "%ld.%09ld: %s\n", ts.tv_sec, ts.tv_nsec, msg);
    fflush(log_file);
}

void handle_sigint(int signum) {
    if (i2c_handle >= 0) {
        piI2CSend(i2c_handle, NULL, 0);  // dummy write to flush
        piI2CClose(i2c_handle);
    }
    gpioWrite(GPIO_RELAY, 0);
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

int main() {
    signal(SIGINT, handle_sigint);

    log_file = fopen("grow_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    int pi = gpioInitialise();
    if (pi < 0) {
        log_message("Failed to initialise pigpio");
        return 1;
    }

    gpioSetMode(GPIO_RELAY, PI_OUTPUT);

    i2c_handle = piI2COpen(BH1750_I2C_BUS, BH1750_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        log_message("Failed to open I2C device");
        return 1;
    }

    while (1) {
        int result = piI2CSend(i2c_handle, &BH1750_CMD, 1);
        if (result < 0) {
            log_message("Failed to send I2C command");
            continue;
        }

        usleep(180000);  // 180 ms

        unsigned char buf[2];
        result = piI2CRead(i2c_handle, buf, 2);
        if (result < 0) {
            log_message("Failed to read I2C data");
            continue;
        }

        int lux = (buf[0] << 8) | buf[1];
        char msg[128];
        sprintf(msg, "Lux: %d", lux);
        log_message(msg);

        if (lux < LUX_THRESHOLD && relay_state == 0) {
            gpioWrite(GPIO_RELAY, 1);
            relay_state = 1;
            log_message("Relay ON");
        } else if (lux >= LUX_THRESHOLD && relay_state == 1) {
            gpioWrite(GPIO_RELAY, 0);
            relay_state = 0;
            log_message("Relay OFF");
        }
    }

    return 0;
}

