#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_LOCK 21
#define GPIO_UNLOCK 22
#define GPIO_SERVO 18
#define SERVO_LOCK 1000
#define SERVO_UNLOCK 2000
#define MIN_PULSE 500
#define MAX_PULSE 2500
#define DEBOUNCE_TIME 100

volatile int button_state[2] = {-1, -1};

void cleanup(int signum) {
    printf("Cleaning up and exiting...\n");
    piGpioInitialise();
    exit(0);
}

void servo_control(int pulse) {
    if (pulse < MIN_PULSE) pulse = MIN_PULSE;
    if (pulse > MAX_PULSE) pulse = MAX_PULSE;
    if (gpioPWM(GPIO_SERVO, pulse) < 0) {
        printf("Failed to set servo pulse width\n");
        cleanup(0);
    }
}

void button_handler(int gpio, int level, uint32_t tick) {
    if (level == 0) {
        if (gpio == GPIO_LOCK) {
            button_state[0] = 1;
        } else if (gpio == GPIO_UNLOCK) {
            button_state[1] = 1;
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        printf("Failed to initialize gpio\n");
        return -1;
    }

    if (gpioSetPullUpDown(GPIO_LOCK, PI_PUD_UP) < 0 || gpioSetPullUpDown(GPIO_UNLOCK, PI_PUD_UP) < 0) {
        printf("Failed to set button pull-up resistors\n");
        cleanup(0);
    }

    if (gpioSetAlertFunc(GPIO_LOCK, button_handler) < 0 || gpioSetAlertFunc(GPIO_UNLOCK, button_handler) < 0) {
        printf("Failed to set button alert functions\n");
        cleanup(0);
    }

    if (gpioSetPWMrange(GPIO_SERVO, 255) < 0 || gpioSetPWMdutycycle(GPIO_SERVO, 0) < 0) {
        printf("Failed to set PWM for servo\n");
        cleanup(0);
    }

    signal(SIGINT, cleanup);

    while (1) {
        if (button_state[0] == 1) {
            servo_control(SERVO_LOCK);
            button_state[0] = 0;
        } else if (button_state[1] == 1) {
            servo_control(SERVO_UNLOCK);
            button_state[1] = 0;
        }
        sleep(DEBOUNCE_TIME / 1000);
    }

    cleanup(0);
    return 0;
}

