#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

struct gpiod_line *line1, *line2;
struct gpiod_chip *chip;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        printf("Stopping motors and releasing GPIO lines...\n");
        gpiod_line_set_value(line1, 0);
        gpiod_line_set_value(line2, 0);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        exit(0);
    }
}

int main() {
    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line1 = gpiod_chip_get_line(chip, 17);
    if (!line1) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    line2 = gpiod_chip_get_line(chip, 27);
    if (!line2) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    if (gpiod_line_request_output(line1, "motor1", 0)) {
        perror("gpiod_line_request_output");
        return 1;
    }

    if (gpiod_line_request_output(line2, "motor2", 0)) {
        perror("gpiod_line_request_output");
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        gpiod_line_set_value(line1, 1);
        usleep(200 * 1000);
        gpiod_line_set_value(line1, 0);

        gpiod_line_set_value(line2, 1);
        usleep(300 * 1000);
        gpiod_line_set_value(line2, 0);
    }

    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return 0;
}

