#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <zmq.h>
#include <gpiod.h>

#define GPIO17 17
#define GPIO27 27

struct gpiod_line *sound_sensor_line;
struct gpiod_line *alarm_led_line;
void *zmq_context;
void *zmq_socket;

void sig_handler(int signum) {
    printf("Signal caught. Cleaning up and exiting...\n");
    gpiod_line_release(sound_sensor_line);
    gpiod_line_release(alarm_led_line);
    zmq_close(zmq_socket);
    zmq_term(zmq_context);
    exit(signum);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        printf("Usage: %s <mode>\n", argv[0]);
        printf("mode: sound_sensor | alarm_node\n");
        return -1;
    }

    const char *mode = argv[1];
    const char *chip_name = "/dev/gpiochip0";
    struct gpiod_chip *chip = gpiod_chip_open(chip_name);
    if (!chip) {
        printf("Failed to open GPIO chip %s\n", chip_name);
        return -1;
    }

    sound_sensor_line = gpiod_chip_get_line(chip, GPIO17);
    if (!sound_sensor_line) {
        printf("Failed to get line %d from chip %s\n", GPIO17, chip_name);
        return -1;
    }

    alarm_led_line = gpiod_chip_get_line(chip, GPIO27);
    if (!alarm_led_line) {
        printf("Failed to get line %d from chip %s\n", GPIO27, chip_name);
        return -1;
    }

    if (gpiod_line_request_input(sound_sensor_line, "sound_sensor")) {
        printf("Failed to request input for line %d\n", GPIO17);
        return -1;
    }

    if (gpiod_line_request_output(alarm_led_line, "alarm_led", 0)) {
        printf("Failed to request output for line %d\n", GPIO27);
        return -1;
    }

    zmq_context = zmq_ctx_new();
    if (!zmq_context) {
        printf("Failed to create ZeroMQ context\n");
        return -1;
    }

    if (strcmp(mode, "sound_sensor") == 0) {
        zmq_socket = zmq_socket(zmq_context, ZMQ_PUB);
        if (zmq_socket == NULL) {
            printf("Failed to create ZeroMQ socket\n");
            return -1;
        }

        if (zmq_bind(zmq_socket, "tcp://*:5555") != 0) {
            printf("Failed to bind ZeroMQ socket\n");
            return -1;
        }

        signal(SIGINT, sig_handler);
        signal(SIGTERM, sig_handler);

        while (1) {
            int value = gpiod_line_get_value(sound_sensor_line);
            if (value < 0) {
                printf("Failed to get line value\n");
                return -1;
            }

            if (value == 1) {
                char message[] = "Sound Alert";
                if (zmq_send(zmq_socket, message, sizeof(message), 0) != sizeof(message)) {
                    printf("Failed to send message\n");
                    return -1;
                }
            }

            usleep(10000);
        }
    } else if (strcmp(mode, "alarm_node") == 0) {
        zmq_socket = zmq_socket(zmq_context, ZMQ_SUB);
        if (zmq_socket == NULL) {
            printf("Failed to create ZeroMQ socket\n");
            return -1;
        }

        if (zmq_connect(zmq_socket, "tcp://localhost:5555") != 0) {
            printf("Failed to connect ZeroMQ socket\n");
