#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <syslog.h>
#include <pigpio.h>
#include <paho-mqtt/MQTTClient.h>

#define GPIO_IR_INPUT 17
#define PULSE_BUFFER_SIZE 32
#define NEC_FRAME_SIZE 32
#define NEC_HEADER_MARK 9000
#define NEC_HEADER_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_SPACE_1 1690
#define NEC_SPACE_0 560

volatile sig_atomic_t stop = 0;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        stop = 1;
    }
}

void log_error(const char *msg) {
    syslog(LOG_ERR, "%s", msg);
    exit(EXIT_FAILURE);
}

void decode_frame(unsigned long long pulse_timings[], int pulse_count) {
    if (pulse_count < 2 * NEC_FRAME_SIZE + 1) {
        syslog(LOG_ERR, "Invalid frame size: %d", pulse_count);
        return;
    }

    unsigned long long address = 0, command = 0;
    int i;
    for (i = 0; i < NEC_FRAME_SIZE; i++) {
        if (pulse_timings[2 * i] != NEC_BIT_MARK || pulse_timings[2 * i + 1] != NEC_SPACE_0) {
            syslog(LOG_ERR, "Invalid frame bit: %llu, %llu", pulse_timings[2 * i], pulse_timings[2 * i + 1]);
            return;
        }
        address <<= 1;
        command <<= 1;
        if (pulse_timings[2 * i + 2] == NEC_SPACE_1) {
            address |= 1;
            command |= 1;
        }
    }

    if (address != ~command) {
        syslog(LOG_ERR, "Invalid frame checksum: %llx, %llx", address, command);
        return;
    }

    syslog(LOG_INFO, "Decoded address: %llx, command: %llx", address, command);

    // Publish to MQTT
    MQTTClient client;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    MQTTClient_create(&client, "tcp://localhost:1883", "IR_Decoder", NULL, 0, 0);
    MQTTClient_connect(client, &conn_opts);
    char topic[] = "ir/decoded";
    char payload[64];
    sprintf(payload, "{\"address\":%llx,\"command\":%llx}", address, command);
    MQTTClient_publish(client, topic, strlen(payload), payload);
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
}

int main() {
    openlog("IR_Decoder", LOG_PERROR, LOG_USER);
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    if (gpioInitialise() < 0) {
        log_error("Failed to initialize GPIO");
    }

    int pi = gpioCfg(GPIO_IR_INPUT, PI_INPUT);
    if (pi < 0) {
        log_error("Failed to configure GPIO");
    }

    unsigned long long pulse_timings[PULSE_BUFFER_SIZE];
    int pulse_count = 0;

    while (!stop) {
        int pulse = gpioRead(GPIO_IR_INPUT);
        if (pulse < 0) {
            log_error("Failed to read GPIO");
        }

        if (pulse == 0 && pulse_count > 0) {
            decode_frame(pulse_timings, pulse_count);
            pulse_count = 0;
        }

        if (pulse_count >= PULSE_BUFFER_SIZE) {
            syslog(LOG_ERR, "Pulse buffer overflow");
            pulse_count = 0;
        } else {
            pulse_timings[pulse_count++] = gpioTick();
        }
    }

    gpioTerminate();
    closelog();

    return 0;
}

