#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <time.h>
#include <math.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDRS {0x23, 0x24, 0x25, 0x26}
#define UDP_ADDR "239.255.255.250"
#define UDP_PORT 5005

int exit_flag = 0;
int i2c_fds[4] = {-1, -1, -1, -1};
int udp_fd = -1;

void exit_handler(int signum) {
    exit_flag = 1;
}

void close_and_exit() {
    for (int i = 0; i < 4; i++) {
        if (i2c_fds[i] != -1) close(i2c_fds[i]);
    }
    if (udp_fd != -1) close(udp_fd);
    exit(0);
}

int main() {
    struct sockaddr_in udp_addr;
    char buf[100];
    int n, i;
    float lux;
    unsigned short data;
    struct timespec ts;
    struct sigaction act;

    act.sa_handler = exit_handler;
    sigemptyset(&act.sa_mask);
    act.sa_flags = 0;
    sigaction(SIGINT, &act, NULL);
    sigaction(SIGTERM, &act, NULL);

    udp_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_fd == -1) {
        perror("socket");
        close_and_exit();
    }

    udp_addr.sin_family = AF_INET;
    udp_addr.sin_port = htons(UDP_PORT);
    udp_addr.sin_addr.s_addr = inet_addr(UDP_ADDR);
    if (connect(udp_fd, (struct sockaddr*)&udp_addr, sizeof(udp_addr)) == -1) {
        perror("connect");
        close_and_exit();
    }

    for (i = 0; i < 4; i++) {
        i2c_fds[i] = open(I2C_DEV, O_RDWR);
        if (i2c_fds[i] == -1) {
            perror("open");
            close_and_exit();
        }
        if (ioctl(i2c_fds[i], I2C_SLAVE, I2C_ADDRS[i]) == -1) {
            perror("ioctl");
            close_and_exit();
        }
    }

    while (!exit_flag) {
        for (i = 0; i < 4; i++) {
            if (write(i2c_fds[i], "\x20", 1) != 1) {
                printf("Write error for sensor %d\n", i+1);
                continue;
            }
            nanosleep((const struct timespec[]){{0, 180000000}}, NULL);
            if (read(i2c_fds[i], &data, 2) != 2) {
                printf("Read error for sensor %d\n", i+1);
                continue;
            }
            lux = ((data >> 8) | (data << 8)) / 1.2;
            sprintf(buf, "%d,%.1f;", i+1, lux);
            write(udp_fd, buf, strlen(buf));
        }
        sleep(1);
    }

    close_and_exit();
    return 0;
}

