#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define SENSOR_ADDRESS 0x28
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "airflow_log.txt"

static int fd;
static FILE *log_file;

void sigint_handler(int signum) {
    close(fd);
    fflush(log_file);
    exit(0);
}

int i2c_write_read(unsigned char *data, int write_len, int read_len) {
    struct i2c_rdwr_ioctl_data msg;
    struct i2c_msg msgs[2];
    int retries = 3;

    msgs[0].addr = SENSOR_ADDRESS;
    msgs[0].flags = 0;
    msgs[0].len = write_len;
    msgs[0].buf = data;

    msgs[1].addr = SENSOR_ADDRESS;
    msgs[1].flags = I2C_M_RD;
    msgs[1].len = read_len;
    msgs[1].buf = data;

    while (retries--) {
        msg.msgs = msgs;
        msg.nmsgs = 2;

        if (ioctl(fd, I2C_RDWR, &msg) != -1)
            return 0;

        if (errno != EAGAIN && errno != EBUSY && errno != ETIMEDOUT)
            return -1;

        usleep(100000);
    }

    return -1;
}

int main() {
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    unsigned char data[2];
    while (1) {
        if (i2c_write_read(data, 0, 2) == 0) {
            int raw = (data[0] << 8) | data[1];
            double flow = (raw - 3277) * 0.1;

            time_t t = time(NULL);
            struct tm *tmp = localtime(&t);
            char time_str[16];
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tmp);

            fprintf(log_file, "%s, %.2f\n", time_str, flow);
            fflush(log_file);
        } else {
            if (errno == ENXIO) {
                fprintf(stderr, "Sensor not present\n");
                return 1;
            } else if (errno == EIO) {
                fprintf(stderr, "I/O error\n");
                return 1;
            } else {
                perror("i2c_write_read");
            }
        }

        sleep(1);
    }

    return 0;
}

