#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SENSOR_ADDRESS 0x39
#define REG_WHO_AM_I 0x24
#define EXPECTED_ID 0x19
#define REG_ENABLE 0x80
#define PON_BIT 0x01
#define REG_CFG6 0xAF
#define SMUX_CONFIG 0x01
#define SP_EN_BIT 0x01
#define REG_F1 0x60
#define REG_F8 0x73
#define LUX_CONST 0.000045
#define LOG_FILE "spectral_log.csv"

static int i2c_file_descriptor;
static FILE *log_file;

static void cleanup_and_exit(int signal) {
    fclose(log_file);
    close(i2c_file_descriptor);
    exit(signal);
}

static int i2c_write_register(int reg, int val) {
    unsigned char buffer[2] = {reg, val};
    return write(i2c_file_descriptor, buffer, 2);
}

static int i2c_read_register(int reg, unsigned char *val) {
    if (write(i2c_file_descriptor, &reg, 1) != 1)
        return -1;
    return read(i2c_file_descriptor, val, 1);
}

int main() {
    i2c_file_descriptor = open(I2C_DEVICE, O_RDWR);
    if (i2c_file_descriptor < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_file_descriptor, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to set I2C slave");
        return 1;
    }

    unsigned char id;
    if (i2c_read_register(REG_WHO_AM_I, &id) != 1 || id != EXPECTED_ID) {
        fprintf(stderr, "Sensor not present or incorrect ID\n");
        return 1;
    }

    if (i2c_write_register(REG_ENABLE, PON_BIT) != 2) {
        perror("Failed to power on sensor");
        return 1;
    }

    if (i2c_write_register(REG_CFG6, SMUX_CONFIG) != 2) {
        perror("Failed to configure SMUX");
        return 1;
    }

    if (i2c_write_register(REG_ENABLE, SP_EN_BIT) != 2) {
        perror("Failed to enable spectral measurement");
        return 1;
    }

    signal(SIGINT, cleanup_and_exit);

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        unsigned char data[10];
        for (int i = 0; i < 10; i++) {
            if (i2c_read_register(REG_F1 + i*2, &data[i]) != 1) {
                perror("Failed to read spectral data");
                cleanup_and_exit(1);
            }
        }

        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d,", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec);

        for (int i = 0; i < 10; i++)
            fprintf(log_file, "%u,", data[i]);

        float lux = 0;
        for (int i = 0; i < 10; i++)
            lux += data[i] * LUX_CONST;
        fprintf(log_file, "%f\n", lux);

        fflush(log_file);
        sleep(5);
    }

    return 0;
}

