#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <time.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>

#define DEFAULT_I2C_ADDR 0x37
#define DEFAULT_INTERVAL 1
#define DEFAULT_FILENAME "seismic_data.csv"

#define ACCEL_REG 0x28
#define ACCEL_LEN 6

#define G_SCALE 0.000244

#define MAX_RETRIES 3
#define BACKOFF_MS 10

int i2c_fd = -1;
FILE *data_file = NULL, *error_file = NULL;
int i2c_addr = DEFAULT_I2C_ADDR, interval = DEFAULT_INTERVAL;
char *filename = DEFAULT_FILENAME;

void cleanup_and_exit(int signum) {
    if (i2c_fd != -1) close(i2c_fd);
    if (data_file != NULL) fclose(data_file);
    if (error_file != NULL) fclose(error_file);
    exit(signum);
}

int i2c_read(int reg, uint8_t *buf, int len) {
    int retries = 0;
    while (retries <= MAX_RETRIES) {
        if (ioctl(i2c_fd, I2C_SLAVE, i2c_addr) == 0) {
            if (write(i2c_fd, &reg, 1) == 1) {
                if (read(i2c_fd, buf, len) == len) {
                    return 0;
                }
            }
        }
        if (++retries > MAX_RETRIES) {
            fprintf(error_file, "%ld: Failed to read from sensor\n", time(NULL));
            return -1;
        }
        usleep(BACKOFF_MS * 1000);
    }
    return 0;
}

int main(int argc, char **argv) {
    int opt;
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a': i2c_addr = strtol(optarg, NULL, 0); break;
            case 'i': interval = atoi(optarg); break;
            case 'f': filename = optarg; break;
            default: return -1;
        }
    }

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Failed to open I2C device\n");
        return -1;
    }

    data_file = fopen(filename, "w");
    if (data_file == NULL) {
        fprintf(stderr, "Failed to open data file\n");
        cleanup_and_exit(-1);
    }

    error_file = fopen("seismic_error.log", "w");
    if (error_file == NULL) {
        fprintf(stderr, "Failed to open error file\n");
        cleanup_and_exit(-1);
    }

    uint8_t buf[ACCEL_LEN];
    while (1) {
        if (i2c_read(ACCEL_REG, buf, ACCEL_LEN) == 0) {
            fprintf(data_file, "%ld,%.3f,%.3f,%.3f\n",
                    time(NULL),
                    (buf[0] | (buf[1] << 8)) * G_SCALE,
                    (buf[2] | (buf[3] << 8)) * G_SCALE,
                    (buf[4] | (buf[5] << 8)) * G_SCALE);
        }
        sleep(interval);
    }

    return 0;
}

