#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define POWER_ON_CMD 0x01
#define CONTINUOUS_HR_MODE_CMD 0x10
#define SLEEP_SEC 1
#define UDP_PORT 5000
#define UDP_TTL 1
#define UDP_MULTICAST_ADDR "239.255.255.250"

static int i2c_fd = -1;
static int sock_fd = -1;

static void cleanup_and_exit(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (sock_fd != -1) {
        close(sock_fd);
    }
    exit(0);
}

int main() {
    struct sockaddr_in addr;
    struct ip_mreq mreq;
    int ret;
    unsigned char buf[2];
    unsigned short raw;
    float lux;
    char msg[32];

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd == -1) {
        perror("open");
        return 1;
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR);
    if (ret == -1) {
        perror("ioctl");
        return 1;
    }

    ret = write(i2c_fd, &POWER_ON_CMD, 1);
    if (ret != 1) {
        perror("write");
        return 1;
    }

    ret = write(i2c_fd, &CONTINUOUS_HR_MODE_CMD, 1);
    if (ret != 1) {
        perror("write");
        return 1;
    }

    sock_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock_fd == -1) {
        perror("socket");
        return 1;
    }

    ret = setsockopt(sock_fd, IPPROTO_IP, IP_MULTICAST_TTL, &UDP_TTL, sizeof(UDP_TTL));
    if (ret == -1) {
        perror("setsockopt");
        return 1;
    }

    addr.sin_family = AF_INET;
    addr.sin_port = htons(UDP_PORT);
    addr.sin_addr.s_addr = inet_addr(UDP_MULTICAST_ADDR);

    mreq.imr_multiaddr.s_addr = inet_addr(UDP_MULTICAST_ADDR);
    mreq.imr_interface.s_addr = htonl(INADDR_ANY);

    ret = setsockopt(sock_fd, IPPROTO_IP, IP_ADD_MEMBERSHIP, &mreq, sizeof(mreq));
    if (ret == -1) {
        perror("setsockopt");
        return 1;
    }

    while (1) {
        ret = read(i2c_fd, buf, 2);
        if (ret != 2) {
            perror("read");
            sleep(SLEEP_SEC);
            continue;
        }

        raw = (buf[0] << 8) | buf[1];
        lux = (float)raw / 1.2f;

        sprintf(msg, "%.2f", lux);

        ret = sendto(sock_fd, msg, strlen(msg), 0, (struct sockaddr *)&addr, sizeof(addr));
        if (ret == -1) {
            perror("sendto");
            sleep(SLEEP_SEC);
            continue;
        }

        sleep(SLEEP_SEC);
    }

    return 0;
}

