#define DEVICE_PATH "/dev/serial0"
#define BAUD_RATE 115200
#define READ_BUFFER_SIZE 256
#define SELECT_TIMEOUT_SECONDS 2
#define INTER_BYTE_TIMEOUT_USECONDS 500000

static volatile int should_exit = 0;

void handle_signal(int signum) {
    should_exit = 1;
}

int main() {
    int fd = open(DEVICE_PATH, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        printf("Failed to open device: %s\n", strerror(errno));
        return 1;
    }

    struct termios options;
    if (tcgetattr(fd, &options) < 0) {
        printf("Failed to get device options: %s\n", strerror(errno));
        return 1;
    }

    options.c_cflag |= (CS8 | CREAD);
    options.c_cflag &= ~(PARENB | PARODD | CSTOPB | CSIZE);
    options.c_cflag |= (CS8);
    options.c_iflag |= (IGNBRK | IGNPAR);
    options.c_iflag &= ~(INLCR | IGNCR | ICRNL | IXON | IXOFF | IXANY);
    options.c_oflag = 0;
    options.c_lflag = 0;
    options.c_cc[VTIME] = INTER_BYTE_TIMEOUT_USECONDS / 1000000;
    options.c_cc[VMIN] = 0;

    if (tcsetattr(fd, TCSANOW, &options) < 0) {
        printf("Failed to set device options: %s\n", strerror(errno));
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    char read_buffer[READ_BUFFER_SIZE];
    char line_buffer[READ_BUFFER_SIZE];
    int line_buffer_index = 0;

    while (!should_exit) {
        fd_set read_fds;
        FD_ZERO(&read_fds);
        FD_SET(fd, &read_fds);

        struct timeval timeout;
        timeout.tv_sec = SELECT_TIMEOUT_SECONDS;
        timeout.tv_usec = 0;

        int select_result = select(fd + 1, &read_fds, NULL, NULL, &timeout);
        if (select_result < 0) {
            printf("Select failed: %s\n", strerror(errno));
            break;
        } else if (select_result == 0) {
            continue;
        }

        int read_result = read(fd, read_buffer, READ_BUFFER_SIZE);
        if (read_result < 0) {
            printf("Read failed: %s\n", strerror(errno));
            break;
        }

        for (int i = 0; i < read_result; i++) {
            if (read_buffer[i] == '\n') {
                line_buffer[line_buffer_index] = '\0';
                line_buffer_index = 0;

                char *timestamp_str = strtok(line_buffer, ",");
                char *range_str = strtok(NULL, ",");
                if (timestamp_str == NULL || range_str == NULL) {
                    printf("Invalid line format\n");
                    continue;
                }

                time_t timestamp = atol(timestamp_str);
                double range = atof(range_str);

                struct tm *timeinfo = localtime(&timestamp);
                char timestamp_formatted[20];
                strftime(timestamp_formatted, 20, "%Y-%m-%d %H:%M:%S", timeinfo);

                printf("Timestamp: %s, Range: %.2f meters\n", timestamp_formatted, range);
            } else {
                line_buffer[line_buffer_index++] = read_buffer[i];
            }
        }
    }

    close(fd);
    return 0;
}

