#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <fcntl.h>
#include <errno.h>

#define GPIO_LEFT 4
#define GPIO_MIDDLE 17
#define GPIO_RIGHT 27

#define BAUD 115200

static int ser;

void sig_handler(int signo) {
    if (pigpio_stop() < 0) {
        fprintf(stderr, "pigpio_stop() failed: %s\n", strerror(errno));
    }
    if (ser >= 0) {
        fprintf(stderr, "Closing serial port...\n");
        if (ioctl(ser, TIOCM_DTR, 0) < 0) {
            fprintf(stderr, "ioctl(TIOCM_DTR, 0) failed: %s\n", strerror(errno));
        }
        close(ser);
    }
    exit(0);
}

int main() {
    int left, middle, right;
    struct timespec ts;
    char buf[256];
    struct sigaction sigIntHandler;

    ser = open("/dev/ttyAMA0", O_WRONLY);
    if (ser < 0) {
        fprintf(stderr, "open(/dev/ttyAMA0, O_WRONLY) failed: %s\n", strerror(errno));
        return 1;
    }
    if (ioctl(ser, TIOCMSET, TIOCM_RTS | TIOCM_DTR) < 0) {
        fprintf(stderr, "ioctl(TIOCMSET, TIOCM_RTS | TIOCM_DTR) failed: %s\n", strerror(errno));
        return 1;
    }
    if (ioctl(ser, TIOCSSERIAL, BAUD) < 0) {
        fprintf(stderr, "ioctl(TIOCSSERIAL, BAUD) failed: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise() failed: %s\n", strerror(errno));
        return 1;
    }
    gpioSetPullUpDown(GPIO_LEFT, PI_PUD_UP);
    gpioSetPullUpDown(GPIO_MIDDLE, PI_PUD_UP);
    gpioSetPullUpDown(GPIO_RIGHT, PI_PUD_UP);

    sigIntHandler.sa_handler = sig_handler;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_flags = 0;
    sigaction(SIGINT, &sigIntHandler, NULL);
    sigaction(SIGTERM, &sigIntHandler, NULL);

    while (1) {
        left = gpioRead(GPIO_LEFT);
        middle = gpioRead(GPIO_MIDDLE);
        right = gpioRead(GPIO_RIGHT);
        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "gpioRead() failed: %s\n", strerror(errno));
            continue;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        printf("%ld.%09ld: %d %d %d\n", ts.tv_sec, ts.tv_nsec, left, middle, right);

        if (left == 0 && middle == 0 && right == 0) {
            sprintf(buf, "EMERGENCY STOP!\n");
            if (write(ser, buf, strlen(buf)) < 0) {
                fprintf(stderr, "write() failed: %s\n", strerror(errno));
            }
        }

        usleep(100000);
    }

    return 0;
}

